import java.math.BigDecimal;
import java.math.BigInteger;
import java.math.RoundingMode;
import java.util.*;
import java.io.*;
import java.nio.file.*;

public class Main {

    static Map<String, Integer> currencies = new HashMap<>();
    static TreeMap<String, Account> accounts = new TreeMap<>();

    static class Account {
        String name;
        String currency;
        BigDecimal balance;
        BigDecimal limit;

        Account(String name, String currency, BigDecimal limit) {
            this.name = name;
            this.currency = currency;
            this.balance = BigDecimal.ZERO;
            this.limit = limit;
        }
    }

    static BigDecimal round(BigDecimal value, int minorUnits) {
        return value.setScale(minorUnits, RoundingMode.HALF_EVEN);
    }

    static String formatMoney(BigDecimal value, int minorUnits) {
        BigDecimal rounded = value.setScale(minorUnits, RoundingMode.HALF_EVEN);
        if (rounded.compareTo(BigDecimal.ZERO) == 0) {
            rounded = BigDecimal.ZERO.setScale(minorUnits);
        }

        String sign = "";
        if (rounded.compareTo(BigDecimal.ZERO) < 0) {
            sign = "-";
            rounded = rounded.negate();
        }

        String plain = rounded.setScale(minorUnits).toPlainString();
        int dotIndex = plain.indexOf('.');
        String intPart;
        String decPart;
        if (dotIndex >= 0) {
            intPart = plain.substring(0, dotIndex);
            decPart = plain.substring(dotIndex + 1);
        } else {
            intPart = plain;
            decPart = "";
        }

        StringBuilder sb = new StringBuilder();
        int len = intPart.length();
        for (int i = 0; i < len; i++) {
            if (i > 0 && (len - i) % 3 == 0) {
                sb.append(',');
            }
            sb.append(intPart.charAt(i));
        }

        if (minorUnits > 0) {
            sb.append('.');
            sb.append(decPart);
        }

        return sign + sb.toString();
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        String content = new String(Files.readAllBytes(Paths.get(dir, "ledger.txt")));
        String[] lines = content.split("\n", -1);

        List<String> rejections = new ArrayList<>();

        for (int lineNum = 1; lineNum <= lines.length; lineNum++) {
            String line = lines[lineNum - 1];
            String trimmed = line.trim();

            if (trimmed.isEmpty() || trimmed.startsWith("#")) {
                continue;
            }

            String[] fields = trimmed.split("\\s+");
            String cmd = fields[0];
            String rejection = null;

            switch (cmd) {
                case "currency": {
                    String code = fields[1];
                    int minorUnits = Integer.parseInt(fields[2]);
                    currencies.put(code, minorUnits);
                    break;
                }

                case "open": {
                    String accName = fields[1];
                    String code = fields[2];
                    BigDecimal limit = BigDecimal.ZERO;
                    if (fields.length > 3) {
                        int mu = currencies.get(code);
                        limit = round(new BigDecimal(fields[3]), mu);
                    }

                    if (accounts.containsKey(accName)) {
                        rejection = "account exists " + accName;
                    } else {
                        accounts.put(accName, new Account(accName, code, limit));
                    }
                    break;
                }

                case "deposit": {
                    String accName = fields[1];
                    if (!accounts.containsKey(accName)) {
                        rejection = "unknown account " + accName;
                        break;
                    }
                    Account acc = accounts.get(accName);
                    int mu = currencies.get(acc.currency);
                    BigDecimal amount = round(new BigDecimal(fields[2]), mu);

                    if (amount.compareTo(BigDecimal.ZERO) <= 0) {
                        rejection = "non-positive amount";
                        break;
                    }

                    acc.balance = acc.balance.add(amount);
                    break;
                }

                case "withdraw": {
                    String accName = fields[1];
                    if (!accounts.containsKey(accName)) {
                        rejection = "unknown account " + accName;
                        break;
                    }
                    Account acc = accounts.get(accName);
                    int mu = currencies.get(acc.currency);
                    BigDecimal amount = round(new BigDecimal(fields[2]), mu);

                    if (amount.compareTo(BigDecimal.ZERO) <= 0) {
                        rejection = "non-positive amount";
                        break;
                    }

                    BigDecimal newBalance = acc.balance.subtract(amount);
                    if (newBalance.compareTo(acc.limit.negate()) < 0) {
                        rejection = "insufficient funds " + accName;
                        break;
                    }

                    acc.balance = newBalance;
                    break;
                }

                case "transfer": {
                    String fromName = fields[1];
                    String toName = fields[2];

                    if (!accounts.containsKey(fromName)) {
                        rejection = "unknown account " + fromName;
                        break;
                    }
                    if (!accounts.containsKey(toName)) {
                        rejection = "unknown account " + toName;
                        break;
                    }

                    Account from = accounts.get(fromName);
                    Account to = accounts.get(toName);

                    if (!from.currency.equals(to.currency)) {
                        rejection = "currency mismatch";
                        break;
                    }

                    int mu = currencies.get(from.currency);
                    BigDecimal amount = round(new BigDecimal(fields[3]), mu);

                    if (amount.compareTo(BigDecimal.ZERO) <= 0) {
                        rejection = "non-positive amount";
                        break;
                    }

                    BigDecimal newBalance = from.balance.subtract(amount);
                    if (newBalance.compareTo(from.limit.negate()) < 0) {
                        rejection = "insufficient funds " + fromName;
                        break;
                    }

                    from.balance = newBalance;
                    to.balance = to.balance.add(amount);
                    break;
                }

                case "convert": {
                    String fromName = fields[1];
                    String toName = fields[2];

                    if (!accounts.containsKey(fromName)) {
                        rejection = "unknown account " + fromName;
                        break;
                    }
                    if (!accounts.containsKey(toName)) {
                        rejection = "unknown account " + toName;
                        break;
                    }

                    Account from = accounts.get(fromName);
                    Account to = accounts.get(toName);

                    int fromMu = currencies.get(from.currency);
                    int toMu = currencies.get(to.currency);

                    BigDecimal amount = round(new BigDecimal(fields[3]), fromMu);

                    if (amount.compareTo(BigDecimal.ZERO) <= 0) {
                        rejection = "non-positive amount";
                        break;
                    }

                    BigDecimal newBalance = from.balance.subtract(amount);
                    if (newBalance.compareTo(from.limit.negate()) < 0) {
                        rejection = "insufficient funds " + fromName;
                        break;
                    }

                    BigDecimal rate = new BigDecimal(fields[4]);
                    BigDecimal received = round(amount.multiply(rate), toMu);

                    from.balance = newBalance;
                    to.balance = to.balance.add(received);
                    break;
                }

                case "interest": {
                    String accName = fields[1];
                    if (!accounts.containsKey(accName)) {
                        rejection = "unknown account " + accName;
                        break;
                    }
                    Account acc = accounts.get(accName);
                    int mu = currencies.get(acc.currency);
                    BigDecimal rate = new BigDecimal(fields[2]);
                    BigDecimal interest = round(acc.balance.multiply(rate), mu);
                    acc.balance = acc.balance.add(interest);
                    break;
                }

                case "split": {
                    String fromName = fields[1];
                    if (!accounts.containsKey(fromName)) {
                        rejection = "unknown account " + fromName;
                        break;
                    }

                    List<String> targetNames = new ArrayList<>();
                    List<BigInteger> weights = new ArrayList<>();
                    for (int i = 3; i < fields.length; i++) {
                        String[] parts = fields[i].split(":");
                        targetNames.add(parts[0]);
                        weights.add(new BigInteger(parts[1]));
                    }

                    boolean unknownFound = false;
                    for (String tn : targetNames) {
                        if (!accounts.containsKey(tn)) {
                            rejection = "unknown account " + tn;
                            unknownFound = true;
                            break;
                        }
                    }
                    if (unknownFound) break;

                    Account from = accounts.get(fromName);

                    boolean mismatch = false;
                    for (String tn : targetNames) {
                        if (!accounts.get(tn).currency.equals(from.currency)) {
                            rejection = "currency mismatch";
                            mismatch = true;
                            break;
                        }
                    }
                    if (mismatch) break;

                    int mu = currencies.get(from.currency);
                    BigDecimal amount = round(new BigDecimal(fields[2]), mu);

                    if (amount.compareTo(BigDecimal.ZERO) <= 0) {
                        rejection = "non-positive amount";
                        break;
                    }

                    BigDecimal newBalance = from.balance.subtract(amount);
                    if (newBalance.compareTo(from.limit.negate()) < 0) {
                        rejection = "insufficient funds " + fromName;
                        break;
                    }

                    BigInteger A = amount.movePointRight(mu).toBigIntegerExact();
                    BigInteger W = BigInteger.ZERO;
                    for (BigInteger w : weights) {
                        W = W.add(w);
                    }

                    int n = targetNames.size();
                    BigInteger[] base = new BigInteger[n];
                    BigInteger[] remainder = new BigInteger[n];
                    BigInteger totalBase = BigInteger.ZERO;

                    for (int i = 0; i < n; i++) {
                        BigInteger product = A.multiply(weights.get(i));
                        BigInteger[] divRem = product.divideAndRemainder(W);
                        base[i] = divRem[0];
                        remainder[i] = divRem[1];
                        totalBase = totalBase.add(base[i]);
                    }

                    BigInteger leftover = A.subtract(totalBase);

                    Integer[] indices = new Integer[n];
                    for (int i = 0; i < n; i++) indices[i] = i;

                    final BigInteger[] rem = remainder;
                    Arrays.sort(indices, (a, b) -> {
                        int cmp = rem[b].compareTo(rem[a]);
                        if (cmp != 0) return cmp;
                        return Integer.compare(a, b);
                    });

                    BigInteger[] finalAmounts = new BigInteger[n];
                    for (int i = 0; i < n; i++) {
                        finalAmounts[i] = base[i];
                    }
                    for (int i = 0; i < leftover.intValue(); i++) {
                        finalAmounts[indices[i]] = finalAmounts[indices[i]].add(BigInteger.ONE);
                    }

                    from.balance = newBalance;
                    for (int i = 0; i < n; i++) {
                        BigDecimal received = new BigDecimal(finalAmounts[i]).movePointLeft(mu);
                        accounts.get(targetNames.get(i)).balance = accounts.get(targetNames.get(i)).balance.add(received);
                    }
                    break;
                }
            }

            if (rejection != null) {
                rejections.add("line " + lineNum + ": REJECT " + rejection);
            }
        }

        StringBuilder out = new StringBuilder();
        for (String r : rejections) {
            out.append(r).append("\n");
        }
        out.append("\n");

        for (Map.Entry<String, Account> entry : accounts.entrySet()) {
            Account acc = entry.getValue();
            int mu = currencies.get(acc.currency);
            out.append(acc.name).append(" ").append(acc.currency).append(" ")
               .append(formatMoney(acc.balance, mu)).append("\n");
        }
        out.append("\n");

        TreeMap<String, BigDecimal> totals = new TreeMap<>();
        TreeMap<String, Integer> counts = new TreeMap<>();
        for (Account acc : accounts.values()) {
            totals.merge(acc.currency, acc.balance, BigDecimal::add);
            counts.merge(acc.currency, 1, Integer::sum);
        }

        for (String code : totals.keySet()) {
            int mu = currencies.get(code);
            out.append("total ").append(code).append(" ")
               .append(formatMoney(totals.get(code), mu))
               .append(" (").append(counts.get(code)).append(" accounts)\n");
        }

        System.out.print(out.toString());
    }
}

import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

public class Main {
    public static void main(String[] args) throws Exception {
        String dir = args[0];
        int port = Integer.parseInt(args[1]);

        List<String> lines = Files.readAllLines(Path.of(dir, "queries.txt"));

        for (String line : lines) {
            if (line.trim().isEmpty()) continue;
            String[] parts = line.trim().split(" ", 2);
            String name = parts[0];
            String type = parts[1];

            int id = ThreadLocalRandom.current().nextInt(0, 65536);
            byte[] query = buildQuery(id, name, type);

            byte[] response = sendUdp(port, query, id);

            if ((response[2] & 0x02) != 0) {
                response = sendTcp(port, query, id);
            }

            printResponse(name, type, response);
        }
    }

    static int typeCode(String type) {
        switch (type.toUpperCase()) {
            case "A": return 1;
            case "AAAA": return 28;
            case "CNAME": return 5;
            case "MX": return 15;
            case "TXT": return 16;
            default: return 0;
        }
    }

    static byte[] buildQuery(int id, String name, String type) {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        // Header: ID
        baos.write((id >> 8) & 0xFF);
        baos.write(id & 0xFF);
        // Flags: RD=1, everything else 0 => 0x0100
        baos.write(0x01);
        baos.write(0x00);
        // QDCOUNT=1
        baos.write(0x00); baos.write(0x01);
        // ANCOUNT=0
        baos.write(0x00); baos.write(0x00);
        // NSCOUNT=0
        baos.write(0x00); baos.write(0x00);
        // ARCOUNT=0
        baos.write(0x00); baos.write(0x00);

        // QNAME
        String qname = name.endsWith(".") ? name.substring(0, name.length() - 1) : name;
        if (!qname.isEmpty()) {
            String[] labels = qname.split("\\.");
            for (String label : labels) {
                baos.write(label.length());
                for (int i = 0; i < label.length(); i++) {
                    baos.write(label.charAt(i));
                }
            }
        }
        baos.write(0);

        // QTYPE
        int tc = typeCode(type);
        baos.write((tc >> 8) & 0xFF);
        baos.write(tc & 0xFF);
        // QCLASS=1 (IN)
        baos.write(0x00); baos.write(0x01);

        return baos.toByteArray();
    }

    static byte[] sendUdp(int port, byte[] query, int id) throws Exception {
        DatagramSocket socket = new DatagramSocket();
        socket.setSoTimeout(10000);
        InetAddress addr = InetAddress.getByName("127.0.0.1");
        DatagramPacket sendPacket = new DatagramPacket(query, query.length, addr, port);
        socket.send(sendPacket);

        byte[] buf = new byte[65535];
        while (true) {
            DatagramPacket recvPacket = new DatagramPacket(buf, buf.length);
            socket.receive(recvPacket);
            byte[] data = Arrays.copyOf(buf, recvPacket.getLength());
            if (data.length >= 12) {
                int respId = ((data[0] & 0xFF) << 8) | (data[1] & 0xFF);
                int qr = (data[2] & 0x80) != 0 ? 1 : 0;
                if (respId == id && qr == 1) {
                    socket.close();
                    return data;
                }
            }
        }
    }

    static byte[] sendTcp(int port, byte[] query, int id) throws Exception {
        Socket socket = new Socket();
        socket.connect(new InetSocketAddress("127.0.0.1", port), 10000);
        socket.setSoTimeout(10000);

        OutputStream os = socket.getOutputStream();
        os.write((query.length >> 8) & 0xFF);
        os.write(query.length & 0xFF);
        os.write(query);
        os.flush();

        InputStream is = socket.getInputStream();
        byte[] lenBuf = new byte[2];
        readFully(is, lenBuf);
        int len = ((lenBuf[0] & 0xFF) << 8) | (lenBuf[1] & 0xFF);

        byte[] data = new byte[len];
        readFully(is, data);

        socket.close();
        return data;
    }

    static void readFully(InputStream is, byte[] buf) throws Exception {
        int offset = 0;
        while (offset < buf.length) {
            int n = is.read(buf, offset, buf.length - offset);
            if (n < 0) throw new IOException("Unexpected EOF");
            offset += n;
        }
    }

    static void printResponse(String queryName, String queryType, byte[] msg) {
        int flags = ((msg[2] & 0xFF) << 8) | (msg[3] & 0xFF);
        int rcode = flags & 0x0F;
        int qdcount = ((msg[4] & 0xFF) << 8) | (msg[5] & 0xFF);
        int ancount = ((msg[6] & 0xFF) << 8) | (msg[7] & 0xFF);

        String outName = normalizeQueryName(queryName);
        System.out.println(outName + " " + queryType + " " + rcodeName(rcode));

        int pos = 12;
        // Skip question section
        for (int i = 0; i < qdcount; i++) {
            pos = skipName(msg, pos);
            pos += 4; // QTYPE(2) + QCLASS(2)
        }

        // Parse answer section
        for (int i = 0; i < ancount; i++) {
            String owner = parseName(msg, pos);
            pos = skipName(msg, pos);

            int rtype = ((msg[pos] & 0xFF) << 8) | (msg[pos + 1] & 0xFF);
            // rclass not needed for output
            int ttl = ((msg[pos + 4] & 0xFF) << 24) | ((msg[pos + 5] & 0xFF) << 16)
                    | ((msg[pos + 6] & 0xFF) << 8) | (msg[pos + 7] & 0xFF);
            int rdlength = ((msg[pos + 8] & 0xFF) << 8) | (msg[pos + 9] & 0xFF);
            pos += 10;

            int rdataStart = pos;
            String dataStr = formatRData(msg, rdataStart, rdlength, rtype);
            String typeName = typeName(rtype);

            System.out.println("  " + owner + " " + Integer.toUnsignedString(ttl) + " " + typeName + " " + dataStr);

            pos += rdlength;
        }
    }

    static String normalizeQueryName(String name) {
        String n = name.endsWith(".") ? name.substring(0, name.length() - 1) : name;
        n = n.toLowerCase();
        if (n.isEmpty()) return ".";
        return n;
    }

    static String rcodeName(int rcode) {
        switch (rcode) {
            case 0: return "NOERROR";
            case 1: return "FORMERR";
            case 2: return "SERVFAIL";
            case 3: return "NXDOMAIN";
            case 4: return "NOTIMP";
            case 5: return "REFUSED";
            default: return "RCODE" + rcode;
        }
    }

    static String typeName(int rtype) {
        switch (rtype) {
            case 1: return "A";
            case 5: return "CNAME";
            case 15: return "MX";
            case 16: return "TXT";
            case 28: return "AAAA";
            default: return "TYPE" + rtype;
        }
    }

    static String formatRData(byte[] msg, int offset, int rdlength, int rtype) {
        switch (rtype) {
            case 1: return formatA(msg, offset);
            case 28: return formatAAAA(msg, offset);
            case 5: return parseName(msg, offset);
            case 15: return formatMX(msg, offset);
            case 16: return formatTXT(msg, offset, rdlength);
            default: return formatUnknown(msg, offset, rdlength);
        }
    }

    static String formatA(byte[] msg, int offset) {
        return (msg[offset] & 0xFF) + "." + (msg[offset + 1] & 0xFF) + "."
                + (msg[offset + 2] & 0xFF) + "." + (msg[offset + 3] & 0xFF);
    }

    static String formatAAAA(byte[] msg, int offset) {
        int[] groups = new int[8];
        for (int i = 0; i < 8; i++) {
            groups[i] = ((msg[offset + i * 2] & 0xFF) << 8) | (msg[offset + i * 2 + 1] & 0xFF);
        }

        // Find longest run of consecutive zero groups (length >= 2), first one wins ties
        int bestStart = -1, bestLen = 0;
        int curStart = -1, curLen = 0;
        for (int i = 0; i < 8; i++) {
            if (groups[i] == 0) {
                if (curStart == -1) { curStart = i; curLen = 1; }
                else curLen++;
            } else {
                if (curLen >= 2 && curLen > bestLen) {
                    bestStart = curStart;
                    bestLen = curLen;
                }
                curStart = -1; curLen = 0;
            }
        }
        if (curLen >= 2 && curLen > bestLen) {
            bestStart = curStart;
            bestLen = curLen;
        }

        if (bestStart == -1) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 8; i++) {
                if (i > 0) sb.append(":");
                sb.append(Integer.toHexString(groups[i]));
            }
            return sb.toString();
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < bestStart; i++) {
            if (sb.length() > 0) sb.append(":");
            sb.append(Integer.toHexString(groups[i]));
        }
        sb.append("::");
        for (int i = bestStart + bestLen; i < 8; i++) {
            if (i > bestStart + bestLen) sb.append(":");
            sb.append(Integer.toHexString(groups[i]));
        }
        return sb.toString();
    }

    static String formatMX(byte[] msg, int offset) {
        int pref = ((msg[offset] & 0xFF) << 8) | (msg[offset + 1] & 0xFF);
        String exchange = parseName(msg, offset + 2);
        return pref + " " + exchange;
    }

    static String formatTXT(byte[] msg, int offset, int rdlength) {
        StringBuilder sb = new StringBuilder();
        int end = offset + rdlength;
        int pos = offset;
        boolean first = true;
        while (pos < end) {
            int len = msg[pos] & 0xFF;
            pos++;
            if (!first) sb.append(" ");
            first = false;
            sb.append('"');
            for (int i = 0; i < len && pos < end; i++) {
                int b = msg[pos] & 0xFF;
                if (b == '"') sb.append("\\\"");
                else if (b == '\\') sb.append("\\\\");
                else if (b >= 0x20 && b <= 0x7E) sb.append((char) b);
                else sb.append(String.format("\\%03d", b));
                pos++;
            }
            sb.append('"');
        }
        return sb.toString();
    }

    static String formatUnknown(byte[] msg, int offset, int rdlength) {
        if (rdlength == 0) return "\\# 0";
        StringBuilder sb = new StringBuilder("\\# " + rdlength);
        sb.append(" ");
        for (int i = 0; i < rdlength; i++) {
            sb.append(String.format("%02x", msg[offset + i] & 0xFF));
        }
        return sb.toString();
    }

    static String parseName(byte[] msg, int pos) {
        List<String> labels = new ArrayList<>();
        int jumps = 0;
        while (true) {
            int len = msg[pos] & 0xFF;
            if (len == 0) break;
            if ((len & 0xC0) == 0xC0) {
                int ptr = ((len & 0x3F) << 8) | (msg[pos + 1] & 0xFF);
                pos = ptr;
                jumps++;
                if (jumps > 128) break;
                continue;
            }
            StringBuilder label = new StringBuilder();
            for (int i = 0; i < len; i++) {
                label.append((char) (msg[pos + 1 + i] & 0xFF));
            }
            labels.add(label.toString());
            pos += 1 + len;
        }
        if (labels.isEmpty()) return ".";
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < labels.size(); i++) {
            if (i > 0) sb.append(".");
            sb.append(labels.get(i).toLowerCase());
        }
        return sb.toString();
    }

    static int skipName(byte[] msg, int pos) {
        while (true) {
            int len = msg[pos] & 0xFF;
            if (len == 0) return pos + 1;
            if ((len & 0xC0) == 0xC0) return pos + 2;
            pos += 1 + len;
        }
    }
}

import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String dir = args[0];
        File[] files = new File(dir).listFiles();
        if (files == null) return;

        List<File> bmpFiles = new ArrayList<>();
        for (File f : files) {
            if (f.isFile() && f.getName().endsWith(".bmp")) {
                bmpFiles.add(f);
            }
        }

        bmpFiles.sort((a, b) -> {
            byte[] ba = a.getName().getBytes("UTF-8");
            byte[] bb = b.getName().getBytes("UTF-8");
            int len = Math.min(ba.length, bb.length);
            for (int i = 0; i < len; i++) {
                int diff = (ba[i] & 0xFF) - (bb[i] & 0xFF);
                if (diff != 0) return diff;
            }
            return ba.length - bb.length;
        });

        for (File f : bmpFiles) {
            processFile(f);
        }
    }

    static void processFile(File f) throws Exception {
        byte[] data = Files.readAllBytes(f.toPath());

        // File header: 14 bytes
        int bfOffBits = readU32(data, 10);

        // DIB header starts at offset 14
        int dibSize = readU32(data, 14);
        int width = readI32(data, 18);
        int height = readI32(data, 22);
        int bpp = readU16(data, 28);
        int compression = readU32(data, 30);
        int coloursUsed = readU32(data, 46);

        boolean bottomUp = height > 0;
        int absHeight = Math.abs(height);

        System.out.println("== " + f.getName());

        if (compression != 0 && compression != 3) {
            System.out.println("error: unsupported compression " + compression);
            return;
        }

        // Read masks for BI_BITFIELDS
        int redMask = 0, greenMask = 0, blueMask = 0;
        if (compression == 3) {
            redMask = readU32(data, 14 + 40);
            greenMask = readU32(data, 14 + 44);
            blueMask = readU32(data, 14 + 48);
        }

        // Palette location and size
        int paletteOffset = 14 + dibSize;
        int paletteSize;
        if (bpp <= 8) {
            paletteSize = coloursUsed > 0 ? coloursUsed : (1 << bpp);
        } else {
            paletteSize = 0;
        }

        // Row size in bytes (padded to multiple of 4)
        int rowBytes = ((bpp * width + 31) / 32) * 4;

        // Build ink array
        boolean[] ink = new boolean[width * absHeight];
        int inkCount = 0;

        for (int storedRow = 0; storedRow < absHeight; storedRow++) {
            int y = bottomUp ? (absHeight - 1 - storedRow) : storedRow;
            int rowOffset = bfOffBits + storedRow * rowBytes;

            for (int x = 0; x < width; x++) {
                int r, g, b;

                if (bpp == 1 || bpp == 4 || bpp == 8) {
                    int idx;
                    if (bpp == 1) {
                        int byteVal = data[rowOffset + x / 8] & 0xFF;
                        idx = (byteVal >> (7 - (x % 8))) & 1;
                    } else if (bpp == 4) {
                        int byteVal = data[rowOffset + x / 2] & 0xFF;
                        idx = (x % 2 == 0) ? ((byteVal >> 4) & 0x0F) : (byteVal & 0x0F);
                    } else {
                        idx = data[rowOffset + x] & 0xFF;
                    }
                    if (idx < paletteSize) {
                        b = data[paletteOffset + idx * 4] & 0xFF;
                        g = data[paletteOffset + idx * 4 + 1] & 0xFF;
                        r = data[paletteOffset + idx * 4 + 2] & 0xFF;
                    } else {
                        r = g = b = 0;
                    }
                } else if (bpp == 24) {
                    int pxOff = rowOffset + x * 3;
                    b = data[pxOff] & 0xFF;
                    g = data[pxOff + 1] & 0xFF;
                    r = data[pxOff + 2] & 0xFF;
                } else if (bpp == 32) {
                    int pxOff = rowOffset + x * 4;
                    if (compression == 3) {
                        int pixel = readU32(data, pxOff);
                        r = extractChannel(pixel, redMask);
                        g = extractChannel(pixel, greenMask);
                        b = extractChannel(pixel, blueMask);
                    } else {
                        b = data[pxOff] & 0xFF;
                        g = data[pxOff + 1] & 0xFF;
                        r = data[pxOff + 2] & 0xFF;
                    }
                } else {
                    r = g = b = 0;
                }

                int luminance = (299 * r + 587 * g + 114 * b) / 1000;
                if (luminance < 128) {
                    ink[y * width + x] = true;
                    inkCount++;
                }
            }
        }

        System.out.println("size " + width + "x" + absHeight + " bpp " + bpp
                + " header " + dibSize + " " + (bottomUp ? "bottom-up" : "top-down")
                + " ink " + inkCount);

        // Find connected components using BFS (8-connectivity)
        int[] labels = new int[width * absHeight];
        Arrays.fill(labels, -1);

        // Each component: firstX, firstY, minX, minY, maxX, maxY, count
        List<int[]> components = new ArrayList<>();

        int[] dx = {-1, 0, 1, -1, 1, -1, 0, 1};
        int[] dy = {-1, -1, -1, 0, 0, 1, 1, 1};

        for (int y = 0; y < absHeight; y++) {
            for (int x = 0; x < width; x++) {
                if (ink[y * width + x] && labels[y * width + x] == -1) {
                    int compIdx = components.size();
                    int minX = x, maxX = x, minY = y, maxY = y;
                    int count = 0;

                    Queue<int[]> queue = new LinkedList<>();
                    queue.add(new int[]{x, y});
                    labels[y * width + x] = compIdx;

                    while (!queue.isEmpty()) {
                        int[] cur = queue.poll();
                        int cx = cur[0], cy = cur[1];
                        count++;
                        if (cx < minX) minX = cx;
                        if (cx > maxX) maxX = cx;
                        if (cy < minY) minY = cy;
                        if (cy > maxY) maxY = cy;

                        for (int d = 0; d < 8; d++) {
                            int nx = cx + dx[d];
                            int ny = cy + dy[d];
                            if (nx >= 0 && nx < width && ny >= 0 && ny < absHeight) {
                                if (ink[ny * width + nx] && labels[ny * width + nx] == -1) {
                                    labels[ny * width + nx] = compIdx;
                                    queue.add(new int[]{nx, ny});
                                }
                            }
                        }
                    }

                    components.add(new int[]{x, y, minX, minY, maxX, maxY, count});
                }
            }
        }

        System.out.println("components " + components.size());
        for (int[] c : components) {
            System.out.println(c[0] + "," + c[1] + " bbox " + c[2] + "," + c[3]
                    + "-" + c[4] + "," + c[5] + " pixels " + c[6]);
        }
    }

    static int extractChannel(int pixel, int mask) {
        int s = Integer.numberOfTrailingZeros(mask);
        int v = (pixel & mask) >>> s;
        int n = Integer.bitCount(mask);
        int m = (1 << n) - 1;
        return (v * 255 + m / 2) / m;
    }

    static int readU32(byte[] data, int offset) {
        return (data[offset] & 0xFF)
                | ((data[offset + 1] & 0xFF) << 8)
                | ((data[offset + 2] & 0xFF) << 16)
                | ((data[offset + 3] & 0xFF) << 24);
    }

    static int readI32(byte[] data, int offset) {
        return readU32(data, offset);
    }

    static int readU16(byte[] data, int offset) {
        return (data[offset] & 0xFF) | ((data[offset + 1] & 0xFF) << 8);
    }
}

import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
