import json
import sys


def json_type(v):
    if v is None:
        return 'null'
    if isinstance(v, bool):
        return 'boolean'
    if isinstance(v, (int, float)):
        return 'number'
    if isinstance(v, str):
        return 'string'
    if isinstance(v, list):
        return 'array'
    if isinstance(v, dict):
        return 'object'


def is_number(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def is_integer(v):
    if isinstance(v, bool):
        return False
    if isinstance(v, int):
        return True
    if isinstance(v, float):
        return v == int(v)
    return False


def deep_equal(a, b):
    ta, tb = json_type(a), json_type(b)
    if ta != tb:
        return False
    if ta == 'null':
        return True
    if ta == 'boolean':
        return a == b
    if ta == 'number':
        return float(a) == float(b)
    if ta == 'string':
        return a == b
    if ta == 'array':
        return len(a) == len(b) and all(deep_equal(x, y) for x, y in zip(a, b))
    if ta == 'object':
        return set(a.keys()) == set(b.keys()) and all(deep_equal(a[k], b[k]) for k in a)
    return False


def escape_token(token):
    return str(token).replace('~', '~0').replace('/', '~1')


def make_ptr(prefix, *tokens):
    result = prefix
    for t in tokens:
        result += '/' + escape_token(t)
    return result


def check_type(instance, type_val):
    if isinstance(type_val, str):
        type_list = [type_val]
    else:
        type_list = type_val
    it = json_type(instance)
    for t in type_list:
        if t == it:
            return True
        if t == 'integer' and it == 'number' and is_integer(instance):
            return True
    return False


def resolve_ref(ref, root_schema):
    if ref == '#':
        return root_schema, '#'
    prefix = '#/$defs/'
    escaped_name = ref[len(prefix):]
    name = escaped_name.replace('~1', '/').replace('~0', '~')
    return root_schema['$defs'][name], ref


def validate(instance, schema, instance_ptr, schema_ptr, root_schema):
    errors = set()

    if schema is True:
        return errors
    if schema is False:
        errors.add((instance_ptr, schema_ptr))
        return errors

    # $ref
    if '$ref' in schema:
        ref_schema, ref_loc = resolve_ref(schema['$ref'], root_schema)
        errors |= validate(instance, ref_schema, instance_ptr, ref_loc, root_schema)

    # type
    if 'type' in schema:
        if not check_type(instance, schema['type']):
            errors.add((instance_ptr, make_ptr(schema_ptr, 'type')))

    # enum
    if 'enum' in schema:
        if not any(deep_equal(instance, v) for v in schema['enum']):
            errors.add((instance_ptr, make_ptr(schema_ptr, 'enum')))

    # const
    if 'const' in schema:
        if not deep_equal(instance, schema['const']):
            errors.add((instance_ptr, make_ptr(schema_ptr, 'const')))

    # Number keywords
    if is_number(instance):
        if 'minimum' in schema and float(instance) < float(schema['minimum']):
            errors.add((instance_ptr, make_ptr(schema_ptr, 'minimum')))
        if 'maximum' in schema and float(instance) > float(schema['maximum']):
            errors.add((instance_ptr, make_ptr(schema_ptr, 'maximum')))
        if 'exclusiveMinimum' in schema and float(instance) <= float(schema['exclusiveMinimum']):
            errors.add((instance_ptr, make_ptr(schema_ptr, 'exclusiveMinimum')))
        if 'exclusiveMaximum' in schema and float(instance) >= float(schema['exclusiveMaximum']):
            errors.add((instance_ptr, make_ptr(schema_ptr, 'exclusiveMaximum')))

    # String keywords
    if isinstance(instance, str):
        if 'minLength' in schema and len(instance) < schema['minLength']:
            errors.add((instance_ptr, make_ptr(schema_ptr, 'minLength')))
        if 'maxLength' in schema and len(instance) > schema['maxLength']:
            errors.add((instance_ptr, make_ptr(schema_ptr, 'maxLength')))

    # Array keywords
    if isinstance(instance, list):
        if 'minItems' in schema and len(instance) < schema['minItems']:
            errors.add((instance_ptr, make_ptr(schema_ptr, 'minItems')))
        if 'maxItems' in schema and len(instance) > schema['maxItems']:
            errors.add((instance_ptr, make_ptr(schema_ptr, 'maxItems')))
        if 'uniqueItems' in schema and schema['uniqueItems'] is True:
            has_dup = False
            for i in range(len(instance)):
                if has_dup:
                    break
                for j in range(i + 1, len(instance)):
                    if deep_equal(instance[i], instance[j]):
                        has_dup = True
                        break
            if has_dup:
                errors.add((instance_ptr, make_ptr(schema_ptr, 'uniqueItems')))
        if 'prefixItems' in schema:
            pi = schema['prefixItems']
            for i in range(min(len(instance), len(pi))):
                errors |= validate(instance[i], pi[i], make_ptr(instance_ptr, i),
                                  make_ptr(schema_ptr, 'prefixItems', i), root_schema)
        if 'items' in schema:
            start = len(schema.get('prefixItems', []))
            for i in range(start, len(instance)):
                errors |= validate(instance[i], schema['items'], make_ptr(instance_ptr, i),
                                  make_ptr(schema_ptr, 'items'), root_schema)

    # Object keywords
    if isinstance(instance, dict):
        if 'minProperties' in schema and len(instance) < schema['minProperties']:
            errors.add((instance_ptr, make_ptr(schema_ptr, 'minProperties')))
        if 'maxProperties' in schema and len(instance) > schema['maxProperties']:
            errors.add((instance_ptr, make_ptr(schema_ptr, 'maxProperties')))

        if 'properties' in schema:
            for name, subschema in schema['properties'].items():
                if name in instance:
                    errors |= validate(instance[name], subschema, make_ptr(instance_ptr, name),
                                      make_ptr(schema_ptr, 'properties', name), root_schema)

        if 'required' in schema:
            for j, req_name in enumerate(schema['required']):
                if req_name not in instance:
                    errors.add((instance_ptr, make_ptr(schema_ptr, 'required', j)))

        if 'additionalProperties' in schema:
            prop_names = set(schema.get('properties', {}).keys())
            for name in instance:
                if name not in prop_names:
                    errors |= validate(instance[name], schema['additionalProperties'],
                                      make_ptr(instance_ptr, name),
                                      make_ptr(schema_ptr, 'additionalProperties'), root_schema)

    # Applicators
    if 'allOf' in schema:
        for i, subschema in enumerate(schema['allOf']):
            errors |= validate(instance, subschema, instance_ptr,
                              make_ptr(schema_ptr, 'allOf', i), root_schema)

    if 'anyOf' in schema:
        accepted = False
        for subschema in schema['anyOf']:
            sub_errors = validate(instance, subschema, instance_ptr,
                                 make_ptr(schema_ptr, 'anyOf'), root_schema)
            if not sub_errors:
                accepted = True
                break
        if not accepted:
            errors.add((instance_ptr, make_ptr(schema_ptr, 'anyOf')))

    if 'oneOf' in schema:
        count = 0
        for subschema in schema['oneOf']:
            sub_errors = validate(instance, subschema, instance_ptr,
                                 make_ptr(schema_ptr, 'oneOf'), root_schema)
            if not sub_errors:
                count += 1
                if count > 1:
                    break
        if count != 1:
            errors.add((instance_ptr, make_ptr(schema_ptr, 'oneOf')))

    if 'not' in schema:
        sub_errors = validate(instance, schema['not'], instance_ptr,
                              make_ptr(schema_ptr, 'not'), root_schema)
        if not sub_errors:
            errors.add((instance_ptr, make_ptr(schema_ptr, 'not')))

    if 'if' in schema:
        if_errors = validate(instance, schema['if'], instance_ptr,
                             make_ptr(schema_ptr, 'if'), root_schema)
        if not if_errors:
            if 'then' in schema:
                errors |= validate(instance, schema['then'], instance_ptr,
                                  make_ptr(schema_ptr, 'then'), root_schema)
        else:
            if 'else' in schema:
                errors |= validate(instance, schema['else'], instance_ptr,
                                  make_ptr(schema_ptr, 'else'), root_schema)

    return errors


def main():
    directory = sys.argv[1]

    with open(directory + '/schema.json', 'r', encoding='utf-8') as f:
        root_schema = json.load(f)

    with open(directory + '/instances.json', 'r', encoding='utf-8') as f:
        instances = json.load(f)

    valid_count = 0
    invalid_count = 0

    for n, instance in enumerate(instances):
        errors = validate(instance, root_schema, '#', '#', root_schema)
        if not errors:
            print(f'{n}: valid')
            valid_count += 1
        else:
            print(f'{n}: invalid ({len(errors)})')
            sorted_errors = sorted(errors, key=lambda e: (e[0], e[1]))
            for inst_loc, schema_loc in sorted_errors:
                print(f'  {inst_loc} {schema_loc}')
            invalid_count += 1

    print(f'valid={valid_count} invalid={invalid_count}')


if __name__ == '__main__':
    main()

import * as fs from 'fs';
import * as path from 'path';

function roundHalfEven(num: bigint, den: bigint): bigint {
    // den > 0, round num/den to nearest integer, ties to even
    let q: bigint, r: bigint;
    if (num >= 0n) {
        q = num / den;
        r = num % den;
    } else {
        q = num / den;
        r = num % den;
        if (r < 0n) { q -= 1n; r += den; }
    }
    // now 0 <= r < den
    const twice_r = 2n * r;
    if (twice_r < den) return q;
    if (twice_r > den) return q + 1n;
    // exactly half: round to even
    if (q % 2n === 0n) return q;
    return q + 1n;
}

function parseNumber(s: string): { value: bigint; decimals: number } {
    let negative = false;
    let i = 0;
    if (s[i] === '-') { negative = true; i++; }
    let intPart = '';
    while (i < s.length && s[i] >= '0' && s[i] <= '9') { intPart += s[i]; i++; }
    let fracPart = '';
    if (i < s.length && s[i] === '.') {
        i++;
        while (i < s.length && s[i] >= '0' && s[i] <= '9') { fracPart += s[i]; i++; }
    }
    let digits = intPart + fracPart;
    if (digits === '') digits = '0';
    let value = BigInt(digits);
    if (negative) value = -value;
    return { value, decimals: fracPart.length };
}

function roundToMinor(parsed: { value: bigint; decimals: number }, minor: number): bigint {
    const { value, decimals } = parsed;
    if (decimals <= minor) {
        return value * (10n ** BigInt(minor - decimals));
    } else {
        return roundHalfEven(value, 10n ** BigInt(decimals - minor));
    }
}

function formatMoney(minorUnits: bigint, minor: number): string {
    let negative = minorUnits < 0n;
    if (minorUnits === 0n) negative = false;
    const abs = negative ? -minorUnits : minorUnits;

    let intPart: string;
    let fracPart: string;
    if (minor === 0) {
        intPart = abs.toString();
        fracPart = '';
    } else {
        const divisor = 10n ** BigInt(minor);
        intPart = (abs / divisor).toString();
        fracPart = (abs % divisor).toString().padStart(minor, '0');
    }

    // Add commas every 3 digits from right
    let withCommas = '';
    let count = 0;
    for (let i = intPart.length - 1; i >= 0; i--) {
        if (count > 0 && count % 3 === 0) withCommas = ',' + withCommas;
        withCommas = intPart[i] + withCommas;
        count++;
    }

    let result = (negative ? '-' : '') + withCommas;
    if (minor > 0) result += '.' + fracPart;
    return result;
}

// Main
const dir = process.argv[2];
const content = fs.readFileSync(path.join(dir, 'ledger.txt'), 'utf-8');
const lines = content.split('\n');

interface CurrencyInfo { minor: number; }
interface AccountInfo { code: string; balance: bigint; limit: bigint; }

const currencies = new Map<string, CurrencyInfo>();
const accounts = new Map<string, AccountInfo>();
const rejections: string[] = [];

for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    const line = lines[lineNum];
    const trimmed = line.trim();
    if (trimmed === '' || trimmed[0] === '#') continue;

    const fields = trimmed.split(/\s+/);
    const cmd = fields[0];
    const n = lineNum + 1;

    let rejected = false;
    let rejectReason = '';

    if (cmd === 'currency') {
        currencies.set(fields[1], { minor: parseInt(fields[2]) });
    } else if (cmd === 'open') {
        const name = fields[1];
        const code = fields[2];
        if (accounts.has(name)) {
            rejected = true;
            rejectReason = `account exists ${name}`;
        } else {
            const minor = currencies.get(code)!.minor;
            let limit = 0n;
            if (fields.length > 3) {
                limit = roundToMinor(parseNumber(fields[3]), minor);
            }
            accounts.set(name, { code, balance: 0n, limit });
        }
    } else if (cmd === 'deposit') {
        const name = fields[1];
        const acct = accounts.get(name);
        if (!acct) {
            rejected = true;
            rejectReason = `unknown account ${name}`;
        } else {
            const minor = currencies.get(acct.code)!.minor;
            const rounded = roundToMinor(parseNumber(fields[2]), minor);
            if (rounded <= 0n) {
                rejected = true;
                rejectReason = `non-positive amount`;
            } else {
                acct.balance += rounded;
            }
        }
    } else if (cmd === 'withdraw') {
        const name = fields[1];
        const acct = accounts.get(name);
        if (!acct) {
            rejected = true;
            rejectReason = `unknown account ${name}`;
        } else {
            const minor = currencies.get(acct.code)!.minor;
            const rounded = roundToMinor(parseNumber(fields[2]), minor);
            if (rounded <= 0n) {
                rejected = true;
                rejectReason = `non-positive amount`;
            } else if (acct.balance - rounded < -acct.limit) {
                rejected = true;
                rejectReason = `insufficient funds ${name}`;
            } else {
                acct.balance -= rounded;
            }
        }
    } else if (cmd === 'transfer') {
        const from = fields[1];
        const to = fields[2];
        const fromAcct = accounts.get(from);
        const toAcct = accounts.get(to);
        if (!fromAcct) {
            rejected = true;
            rejectReason = `unknown account ${from}`;
        } else if (!toAcct) {
            rejected = true;
            rejectReason = `unknown account ${to}`;
        } else if (fromAcct.code !== toAcct.code) {
            rejected = true;
            rejectReason = `currency mismatch`;
        } else {
            const minor = currencies.get(fromAcct.code)!.minor;
            const rounded = roundToMinor(parseNumber(fields[3]), minor);
            if (rounded <= 0n) {
                rejected = true;
                rejectReason = `non-positive amount`;
            } else if (fromAcct.balance - rounded < -fromAcct.limit) {
                rejected = true;
                rejectReason = `insufficient funds ${from}`;
            } else {
                fromAcct.balance -= rounded;
                toAcct.balance += rounded;
            }
        }
    } else if (cmd === 'convert') {
        const from = fields[1];
        const to = fields[2];
        const fromAcct = accounts.get(from);
        const toAcct = accounts.get(to);
        if (!fromAcct) {
            rejected = true;
            rejectReason = `unknown account ${from}`;
        } else if (!toAcct) {
            rejected = true;
            rejectReason = `unknown account ${to}`;
        } else {
            const fromMinor = currencies.get(fromAcct.code)!.minor;
            const toMinor = currencies.get(toAcct.code)!.minor;
            const rounded = roundToMinor(parseNumber(fields[3]), fromMinor);
            if (rounded <= 0n) {
                rejected = true;
                rejectReason = `non-positive amount`;
            } else if (fromAcct.balance - rounded < -fromAcct.limit) {
                rejected = true;
                rejectReason = `insufficient funds ${from}`;
            } else {
                const parsedRate = parseNumber(fields[4]);
                // to receives: rounded * rate rounded to toMinor decimal places
                // actual value = rounded / 10^fromMinor, multiply by rate_num/rate_den
                // in to's minor units: rounded * rate_num * 10^toMinor / (rate_den * 10^fromMinor)
                const numerator = rounded * parsedRate.value * (10n ** BigInt(toMinor));
                const denominator = (10n ** BigInt(parsedRate.decimals)) * (10n ** BigInt(fromMinor));
                const toReceive = roundHalfEven(numerator, denominator);
                fromAcct.balance -= rounded;
                toAcct.balance += toReceive;
            }
        }
    } else if (cmd === 'interest') {
        const name = fields[1];
        const acct = accounts.get(name);
        if (!acct) {
            rejected = true;
            rejectReason = `unknown account ${name}`;
        } else {
            const parsedRate = parseNumber(fields[2]);
            // interest in minor units = round_half_even(balance * rate_num, rate_den)
            const numerator = acct.balance * parsedRate.value;
            const denominator = 10n ** BigInt(parsedRate.decimals);
            const interest = roundHalfEven(numerator, denominator);
            acct.balance += interest;
        }
    } else if (cmd === 'split') {
        const from = fields[1];
        const fromAcct = accounts.get(from);
        if (!fromAcct) {
            rejected = true;
            rejectReason = `unknown account ${from}`;
        } else {
            // Parse targets in order, check for unknown accounts
            const targetNames: string[] = [];
            const targetWeights: bigint[] = [];
            const targetAccts: AccountInfo[] = [];
            for (let i = 3; i < fields.length; i++) {
                const colonPos = fields[i].indexOf(':');
                const tName = fields[i].substring(0, colonPos);
                const tWeight = BigInt(fields[i].substring(colonPos + 1));
                const tAcct = accounts.get(tName);
                if (!tAcct) {
                    if (!rejected) {
                        rejected = true;
                        rejectReason = `unknown account ${tName}`;
                    }
                    // still parse remaining to maintain order, but we already rejected
                    targetNames.push(tName);
                    targetWeights.push(tWeight);
                    targetAccts.push(null as any);
                } else {
                    targetNames.push(tName);
                    targetWeights.push(tWeight);
                    targetAccts.push(tAcct);
                }
            }

            if (!rejected) {
                const minor = currencies.get(fromAcct.code)!.minor;
                // Check currency mismatch
                for (const tAcct of targetAccts) {
                    if (tAcct.code !== fromAcct.code) {
                        rejected = true;
                        rejectReason = `currency mismatch`;
                        break;
                    }
                }
            }

            if (!rejected) {
                const minor = currencies.get(fromAcct.code)!.minor;
                const rounded = roundToMinor(parseNumber(fields[2]), minor);
                if (rounded <= 0n) {
                    rejected = true;
                    rejectReason = `non-positive amount`;
                } else if (fromAcct.balance - rounded < -fromAcct.limit) {
                    rejected = true;
                    rejectReason = `insufficient funds ${from}`;
                } else {
                    // Perform split
                    const A = rounded;
                    const W = targetWeights.reduce((s, w) => s + w, 0n);

                    const allocations: { index: number; base: bigint; remainder: bigint }[] = [];
                    let totalBase = 0n;

                    for (let i = 0; i < targetWeights.length; i++) {
                        const wi = targetWeights[i];
                        const base = (A * wi) / W;
                        const rem = (A * wi) % W;
                        allocations.push({ index: i, base, remainder: rem });
                        totalBase += base;
                    }

                    const leftover = A - totalBase;

                    // Sort by remainder descending, ties by original index ascending
                    allocations.sort((a, b) => {
                        if (a.remainder > b.remainder) return -1;
                        if (a.remainder < b.remainder) return 1;
                        return a.index - b.index;
                    });

                    for (let i = 0; i < leftover; i++) {
                        allocations[i].base += 1n;
                    }

                    fromAcct.balance -= rounded;
                    for (const alloc of allocations) {
                        targetAccts[alloc.index].balance += alloc.base;
                    }
                }
            }
        }
    }

    if (rejected) {
        rejections.push(`line ${n}: REJECT ${rejectReason}`);
    }
}

// Output rejections
for (const r of rejections) {
    console.log(r);
}
console.log('');

// Accounts sorted by name (byte-wise ascending)
const sortedAccounts = [...accounts.entries()].sort((a, b) => {
    if (a[0] < b[0]) return -1;
    if (a[0] > b[0]) return 1;
    return 0;
});

for (const [name, acct] of sortedAccounts) {
    const minor = currencies.get(acct.code)!.minor;
    console.log(`${name} ${acct.code} ${formatMoney(acct.balance, minor)}`);
}

console.log('');

// Currency totals
const currencyTotals = new Map<string, { total: bigint; count: number }>();
for (const [, acct] of sortedAccounts) {
    const code = acct.code;
    const entry = currencyTotals.get(code) || { total: 0n, count: 0 };
    entry.total += acct.balance;
    entry.count++;
    currencyTotals.set(code, entry);
}

const sortedCurrencies = [...currencyTotals.entries()].sort((a, b) => {
    if (a[0] < b[0]) return -1;
    if (a[0] > b[0]) return 1;
    return 0;
});

for (const [code, { total, count }] of sortedCurrencies) {
    const minor = currencies.get(code)!.minor;
    console.log(`total ${code} ${formatMoney(total, minor)} (${count} accounts)`);
}

import Foundation
import Darwin

func typeCode(_ type: String) -> UInt16 {
    switch type {
    case "A": return 1
    case "CNAME": return 5
    case "MX": return 15
    case "TXT": return 16
    case "AAAA": return 28
    default: return 0
    }
}

func typeNameFor(_ type: Int) -> String {
    switch type {
    case 1: return "A"
    case 5: return "CNAME"
    case 15: return "MX"
    case 16: return "TXT"
    case 28: return "AAAA"
    default: return "TYPE\(type)"
    }
}

func rcodeString(_ code: Int) -> String {
    switch code {
    case 0: return "NOERROR"
    case 1: return "FORMERR"
    case 2: return "SERVFAIL"
    case 3: return "NXDOMAIN"
    case 4: return "NOTIMP"
    case 5: return "REFUSED"
    default: return "RCODE\(code)"
    }
}

func encodeName(_ name: String) -> [UInt8] {
    var result: [UInt8] = []
    var n = name
    if n.hasSuffix(".") { n = String(n.dropLast()) }
    if n.isEmpty {
        result.append(0)
        return result
    }
    let labels = n.components(separatedBy: ".")
    for label in labels {
        let bytes = Array(label.utf8)
        result.append(UInt8(bytes.count))
        result.append(contentsOf: bytes)
    }
    result.append(0)
    return result
}

func buildQuery(id: UInt16, name: String, type: String) -> [UInt8] {
    var msg: [UInt8] = []
    msg.append(UInt8(id >> 8))
    msg.append(UInt8(id & 0xFF))
    msg.append(0x01)
    msg.append(0x00)
    msg.append(0x00); msg.append(0x01)
    msg.append(0x00); msg.append(0x00)
    msg.append(0x00); msg.append(0x00)
    msg.append(0x00); msg.append(0x00)
    msg.append(contentsOf: encodeName(name))
    let qt = typeCode(type)
    msg.append(UInt8(qt >> 8))
    msg.append(UInt8(qt & 0xFF))
    msg.append(0x00); msg.append(0x01)
    return msg
}

func withSockaddr(_ port: UInt16, _ body: (UnsafePointer<sockaddr>, socklen_t) -> Int) -> Int {
    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = port.bigEndian
    addr.sin_addr.s_addr = inet_addr("127.0.0.1")
    return withUnsafePointer(to: &addr) {
        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
            body($0, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
}

func sendUDP(query: [UInt8], port: UInt16, expectedID: UInt16) -> [UInt8] {
    let sock = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP)
    defer { close(sock) }
    query.withUnsafeBytes { ptr in
        _ = withSockaddr(port) { addrPtr, addrLen in
            sendto(sock, ptr.baseAddress, query.count, 0, addrPtr, addrLen)
        }
    }
    var buf = [UInt8](repeating: 0, count: 4096)
    while true {
        let n = recvfrom(sock, &buf, buf.count, 0, nil, nil)
        if n < 12 { continue }
        let respID = (Int(buf[0]) << 8) | Int(buf[1])
        let flags = (Int(buf[2]) << 8) | Int(buf[3])
        let qr = (flags & 0x8000) != 0
        if qr && respID == Int(expectedID) {
            return Array(buf[0..<n])
        }
    }
}

func recvAll(_ sock: Int32, _ buf: inout [UInt8], _ count: Int) {
    var offset = 0
    while offset < count {
        let n = recv(sock, &buf[offset], count - offset, 0)
        if n <= 0 { break }
        offset += n
    }
}

func sendTCP(query: [UInt8], port: UInt16, expectedID: UInt16) -> [UInt8] {
    let sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP)
    defer { close(sock) }
    _ = withSockaddr(port) { addrPtr, addrLen in
        connect(sock, addrPtr, addrLen)
    }
    var toSend = [UInt8(query.count >> 8), UInt8(query.count & 0xFF)]
    toSend.append(contentsOf: query)
    toSend.withUnsafeBytes { ptr in
        _ = send(sock, ptr.baseAddress, toSend.count, 0)
    }
    var lenBuf = [UInt8](repeating: 0, count: 2)
    recvAll(sock, &lenBuf, 2)
    let msgLen = (Int(lenBuf[0]) << 8) | Int(lenBuf[1])
    var buf = [UInt8](repeating: 0, count: msgLen)
    recvAll(sock, &buf, msgLen)
    return buf
}

struct NameResult {
    let name: String
    let nextOffset: Int
}

func readName(_ msg: [UInt8], at startOffset: Int) -> NameResult {
    var labels: [String] = []
    var offset = startOffset
    var jumped = false
    var nextOffset = 0
    var visited = Set<Int>()
    visited.insert(startOffset)

    while offset < msg.count {
        let len = Int(msg[offset])
        if len & 0xC0 == 0xC0 {
            if offset + 1 >= msg.count { break }
            if !jumped {
                nextOffset = offset + 2
                jumped = true
            }
            let ptr = ((len & 0x3F) << 8) | Int(msg[offset + 1])
            if visited.contains(ptr) { break }
            visited.insert(ptr)
            offset = ptr
        } else if len == 0 {
            if !jumped {
                nextOffset = offset + 1
            }
            break
        } else {
            offset += 1
            if offset + len > msg.count { break }
            let labelBytes = Array(msg[offset..<(offset + len)])
            let label = String(decoding: labelBytes, as: UTF8.self)
            labels.append(label.lowercased())
            offset += len
        }
    }

    if labels.isEmpty {
        return NameResult(name: ".", nextOffset: nextOffset)
    }
    return NameResult(name: labels.joined(separator: "."), nextOffset: nextOffset)
}

func skipName(_ msg: [UInt8], at startOffset: Int) -> Int {
    var offset = startOffset
    while offset < msg.count {
        let len = Int(msg[offset])
        if len & 0xC0 == 0xC0 {
            return offset + 2
        } else if len == 0 {
            return offset + 1
        } else {
            offset += 1 + len
        }
    }
    return offset
}

func formatIPv6(_ data: [UInt8]) -> String {
    var groups: [Int] = []
    for i in 0..<8 {
        groups.append((Int(data[i * 2]) << 8) | Int(data[i * 2 + 1]))
    }
    var bestStart = -1
    var bestLen = 0
    var i = 0
    while i < 8 {
        if groups[i] == 0 {
            var j = i
            while j < 8 && groups[j] == 0 { j += 1 }
            let runLen = j - i
            if runLen >= 2 && runLen > bestLen {
                bestLen = runLen
                bestStart = i
            }
            i = j
        } else {
            i += 1
        }
    }
    if bestStart < 0 {
        return groups.map { String(format: "%x", $0) }.joined(separator: ":")
    }
    var parts: [String] = []
    for k in 0..<bestStart {
        parts.append(String(format: "%x", groups[k]))
    }
    var afterParts: [String] = []
    for k in (bestStart + bestLen)..<8 {
        afterParts.append(String(format: "%x", groups[k]))
    }
    if bestStart == 0 && bestStart + bestLen == 8 {
        return "::"
    } else if bestStart == 0 {
        return "::" + afterParts.joined(separator: ":")
    } else if bestStart + bestLen == 8 {
        return parts.joined(separator: ":") + "::"
    } else {
        return parts.joined(separator: ":") + "::" + afterParts.joined(separator: ":")
    }
}

func formatTXT(_ data: [UInt8]) -> String {
    var result: [String] = []
    var offset = 0
    while offset < data.count {
        let strLen = Int(data[offset])
        offset += 1
        if offset + strLen > data.count { break }
        var s = "\""
        for i in 0..<strLen {
            let b = data[offset + i]
            if b == 0x22 {
                s += "\\\""
            } else if b == 0x5C {
                s += "\\\\"
            } else if b >= 0x20 && b <= 0x7E {
                s.append(Character(UnicodeScalar(b)))
            } else {
                s += "\\\(String(format: "%03d", b))"
            }
        }
        s += "\""
        result.append(s)
        offset += strLen
    }
    return result.joined(separator: " ")
}

func formatRData(type: Int, data: [UInt8], msg: [UInt8], rdOffset: Int, rdLength: Int) -> String {
    switch type {
    case 1:
        guard data.count >= 4 else { return "" }
        return "\(data[0]).\(data[1]).\(data[2]).\(data[3])"
    case 28:
        guard data.count >= 16 else { return "" }
        return formatIPv6(data)
    case 5:
        let r = readName(msg, at: rdOffset)
        return r.name
    case 15:
        guard data.count >= 2 else { return "" }
        let pref = (Int(data[0]) << 8) | Int(data[1])
        let r = readName(msg, at: rdOffset + 2)
        return "\(pref) \(r.name)"
    case 16:
        return formatTXT(data)
    default:
        if rdLength == 0 {
            return "\\# 0"
        }
        let hex = data.map { String(format: "%02x", $0) }.joined()
        return "\\# \(rdLength) \(hex)"
    }
}

func formatQueryName(_ name: String) -> String {
    var n = name
    if n.hasSuffix(".") { n = String(n.dropLast()) }
    if n.isEmpty { return "." }
    return n.lowercased()
}

func parseAndPrint(response: [UInt8], queryName: String, queryType: String) {
    let flags = (Int(response[2]) << 8) | Int(response[3])
    let rcode = flags & 0x0F
    let qdcount = (Int(response[4]) << 8) | Int(response[5])
    let ancount = (Int(response[6]) << 8) | Int(response[7])

    let nameStr = formatQueryName(queryName)
    let rcodeStr = rcodeString(rcode)
    print("\(nameStr) \(queryType) \(rcodeStr)")

    var offset = 12
    for _ in 0..<qdcount {
        offset = skipName(response, at: offset)
        offset += 4
    }

    for _ in 0..<ancount {
        let owner = readName(response, at: offset)
        offset = owner.nextOffset

        let rtype = (Int(response[offset]) << 8) | Int(response[offset + 1])
        offset += 2
        offset += 2 // skip CLASS
        let ttl = (UInt32(response[offset]) << 24) | (UInt32(response[offset + 1]) << 16) | (UInt32(response[offset + 2]) << 8) | UInt32(response[offset + 3])
        offset += 4
        let rdlength = (Int(response[offset]) << 8) | Int(response[offset + 1])
        offset += 2

        let rdataEnd = offset + rdlength
        let rdata = Array(response[offset..<rdataEnd])

        let tname = typeNameFor(rtype)
        let dataStr = formatRData(type: rtype, data: rdata, msg: response, rdOffset: offset, rdLength: rdlength)

        print("  \(owner.name) \(ttl) \(tname) \(dataStr)")

        offset = rdataEnd
    }
}

