for line in lines {
    let trimmed = line.trimmingCharacters(in: .whitespaces)
    if trimmed.isEmpty { continue }
    let parts = trimmed.components(separatedBy: " ")
    let name = parts[0]
    let type = parts[1]

    let id = UInt16.random(in: 0...65535)
    let query = buildQuery(id: id, name: name, type: type)

    var response = sendUDP(query: query, port: port, expectedID: id)

    let flags = (Int(response[2]) << 8) | Int(response[3])
    let tc = (flags & 0x0200) != 0

    if tc {
        response = sendTCP(query: query, port: port, expectedID: id)
    }

    parseAndPrint(response: response, queryName: name, queryType: type)
}

import Foundation
import Darwin

func typeCode(_ type: String) -> UInt16 {
    switch type {
    case "A": return 1
    case "CNAME": return 5
    case "MX": return 15
    case "TXT": return 16
    case "AAAA": return 28
    default: return 0
    }
}

func typeNameFor(_ type: Int) -> String {
    switch type {
    case 1: return "A"
    case 5: return "CNAME"
    case 15: return "MX"
    case 16: return "TXT"
    case 28: return "AAAA"
    default: return "TYPE\(type)"
    }
}

func rcodeString(_ code: Int) -> String {
    switch code {
    case 0: return "NOERROR"
    case 1: return "FORMERR"
    case 2: return "SERVFAIL"
    case 3: return "NXDOMAIN"
    case 4: return "NOTIMP"
    case 5: return "REFUSED"
    default: return "RCODE\(code)"
    }
}

func encodeName(_ name: String) -> [UInt8] {
    var result: [UInt8] = []
    var n = name
    if n.hasSuffix(".") { n = String(n.dropLast()) }
    if n.isEmpty {
        result.append(0)
        return result
    }
    let labels = n.components(separatedBy: ".")
    for label in labels {
        let bytes = Array(label.utf8)
        result.append(UInt8(bytes.count))
        result.append(contentsOf: bytes)
    }
    result.append(0)
    return result
}

func buildQuery(id: UInt16, name: String, type: String) -> [UInt8] {
    var msg: [UInt8] = []
    msg.append(UInt8(id >> 8))
    msg.append(UInt8(id & 0xFF))
    msg.append(0x01)
    msg.append(0x00)
    msg.append(0x00); msg.append(0x01)
    msg.append(0x00); msg.append(0x00)
    msg.append(0x00); msg.append(0x00)
    msg.append(0x00); msg.append(0x00)
    msg.append(contentsOf: encodeName(name))
    let qt = typeCode(type)
    msg.append(UInt8(qt >> 8))
    msg.append(UInt8(qt & 0xFF))
    msg.append(0x00); msg.append(0x01)
    return msg
}

func withSockaddr(_ port: UInt16, _ body: (UnsafePointer<sockaddr>, socklen_t) -> Int) -> Int {
    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = port.bigEndian
    addr.sin_addr.s_addr = inet_addr("127.0.0.1")
    return withUnsafePointer(to: &addr) {
        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
            body($0, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
}

func sendUDP(query: [UInt8], port: UInt16, expectedID: UInt16) -> [UInt8] {
    let sock = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP)
    defer { close(sock) }
    query.withUnsafeBytes { ptr in
        _ = withSockaddr(port) { addrPtr, addrLen in
            sendto(sock, ptr.baseAddress, query.count, 0, addrPtr, addrLen)
        }
    }
    var buf = [UInt8](repeating: 0, count: 4096)
    while true {
        let n = recvfrom(sock, &buf, buf.count, 0, nil, nil)
        if n < 12 { continue }
        let respID = (Int(buf[0]) << 8) | Int(buf[1])
        let flags = (Int(buf[2]) << 8) | Int(buf[3])
        let qr = (flags & 0x8000) != 0
        if qr && respID == Int(expectedID) {
            return Array(buf[0..<n])
        }
    }
}

func recvAll(_ sock: Int32, _ buf: inout [UInt8], _ count: Int) {
    var offset = 0
    while offset < count {
        let n = recv(sock, &buf[offset], count - offset, 0)
        if n <= 0 { break }
        offset += n
    }
}

func sendTCP(query: [UInt8], port: UInt16, expectedID: UInt16) -> [UInt8] {
    let sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP)
    defer { close(sock) }
    _ = withSockaddr(port) { addrPtr, addrLen in
        Int(connect(sock, addrPtr, addrLen))
    }
    var toSend = [UInt8(query.count >> 8), UInt8(query.count & 0xFF)]
    toSend.append(contentsOf: query)
    toSend.withUnsafeBytes { ptr in
        _ = send(sock, ptr.baseAddress, toSend.count, 0)
    }
    var lenBuf = [UInt8](repeating: 0, count: 2)
    recvAll(sock, &lenBuf, 2)
    let msgLen = (Int(lenBuf[0]) << 8) | Int(lenBuf[1])
    var buf = [UInt8](repeating: 0, count: msgLen)
    recvAll(sock, &buf, msgLen)
    return buf
}

struct NameResult {
    let name: String
    let nextOffset: Int
}

func readName(_ msg: [UInt8], at startOffset: Int) -> NameResult {
    var labels: [String] = []
    var offset = startOffset
    var jumped = false
    var nextOffset = 0
    var visited = Set<Int>()
    visited.insert(startOffset)

    while offset < msg.count {
        let len = Int(msg[offset])
        if len & 0xC0 == 0xC0 {
            if offset + 1 >= msg.count { break }
            if !jumped {
                nextOffset = offset + 2
                jumped = true
            }
            let ptr = ((len & 0x3F) << 8) | Int(msg[offset + 1])
            if visited.contains(ptr) { break }
            visited.insert(ptr)
            offset = ptr
        } else if len == 0 {
            if !jumped {
                nextOffset = offset + 1
            }
            break
        } else {
            offset += 1
            if offset + len > msg.count { break }
            let labelBytes = Array(msg[offset..<(offset + len)])
            let label = String(decoding: labelBytes, as: UTF8.self)
            labels.append(label.lowercased())
            offset += len
        }
    }

    if labels.isEmpty {
        return NameResult(name: ".", nextOffset: nextOffset)
    }
    return NameResult(name: labels.joined(separator: "."), nextOffset: nextOffset)
}

func skipName(_ msg: [UInt8], at startOffset: Int) -> Int {
    var offset = startOffset
    while offset < msg.count {
        let len = Int(msg[offset])
        if len & 0xC0 == 0xC0 {
            return offset + 2
        } else if len == 0 {
            return offset + 1
        } else {
            offset += 1 + len
        }
    }
    return offset
}

