use std::env;
use std::fs;
use std::io::{Read, Write};
use std::net::{TcpStream, UdpSocket};
use std::time::{SystemTime, UNIX_EPOCH};

fn generate_id(counter: u16) -> u16 {
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .subsec_nanos();
    ((nanos as u16) ^ ((nanos >> 16) as u16)) ^ counter
}

fn type_code(t: &str) -> u16 {
    match t {
        "A" => 1,
        "AAAA" => 28,
        "MX" => 15,
        "TXT" => 16,
        "CNAME" => 5,
        _ => 0,
    }
}

fn type_name(n: u16) -> String {
    match n {
        1 => "A".to_string(),
        5 => "CNAME".to_string(),
        15 => "MX".to_string(),
        16 => "TXT".to_string(),
        28 => "AAAA".to_string(),
        _ => format!("TYPE{}", n),
    }
}

fn rcode_str(code: u8) -> String {
    match code {
        0 => "NOERROR".to_string(),
        1 => "FORMERR".to_string(),
        2 => "SERVFAIL".to_string(),
        3 => "NXDOMAIN".to_string(),
        4 => "NOTIMP".to_string(),
        5 => "REFUSED".to_string(),
        _ => format!("RCODE{}", code),
    }
}

fn build_query(id: u16, name: &str, qtype: u16) -> Vec<u8> {
    let mut msg = Vec::new();
    msg.extend_from_slice(&id.to_be_bytes());
    msg.extend_from_slice(&0x0100u16.to_be_bytes());
    msg.extend_from_slice(&1u16.to_be_bytes());
    msg.extend_from_slice(&0u16.to_be_bytes());
    msg.extend_from_slice(&0u16.to_be_bytes());
    msg.extend_from_slice(&0u16.to_be_bytes());

    let name_no_dot = name.trim_end_matches('.');
    if !name_no_dot.is_empty() {
        for label in name_no_dot.split('.') {
            msg.push(label.len() as u8);
            msg.extend_from_slice(label.as_bytes());
        }
    }
    msg.push(0);

    msg.extend_from_slice(&qtype.to_be_bytes());
    msg.extend_from_slice(&1u16.to_be_bytes());

    msg
}

fn parse_name(msg: &[u8], offset: usize) -> (String, usize) {
    let mut labels: Vec<String> = Vec::new();
    let mut pos = offset;
    let mut next_pos: Option<usize> = None;
    let mut jumped = false;
    let mut iter = 0;

    loop {
        iter += 1;
        if iter > 128 {
            break;
        }
        if pos >= msg.len() {
            break;
        }
        let len = msg[pos] as usize;
        if len == 0 {
            if !jumped {
                next_pos = Some(pos + 1);
            }
            break;
        }
        if len & 0xC0 == 0xC0 {
            if pos + 1 >= msg.len() {
                break;
            }
            if !jumped {
                next_pos = Some(pos + 2);
                jumped = true;
            }
            let ptr = ((len & 0x3F) << 8) | (msg[pos + 1] as usize);
            pos = ptr;
        } else {
            if pos + 1 + len > msg.len() {
                break;
            }
            let label = String::from_utf8_lossy(&msg[pos + 1..pos + 1 + len]).to_lowercase();
            labels.push(label);
            pos += 1 + len;
        }
    }

    let name = if labels.is_empty() {
        ".".to_string()
    } else {
        labels.join(".")
    };

    (name, next_pos.unwrap_or(pos + 1))
}

fn format_ipv6(bytes: &[u8]) -> String {
    let mut groups = [0u16; 8];
    for i in 0..8 {
        groups[i] = u16::from_be_bytes([bytes[i * 2], bytes[i * 2 + 1]]);
    }

    let mut best_start: usize = 8;
    let mut best_len: usize = 0;
    let mut i = 0;
    while i < 8 {
        if groups[i] == 0 {
            let start = i;
            while i < 8 && groups[i] == 0 {
                i += 1;
            }
            let run_len = i - start;
            if run_len >= 2 && run_len > best_len {
                best_start = start;
                best_len = run_len;
            }
        } else {
            i += 1;
        }
    }

    let hex_groups: Vec<String> = groups.iter().map(|g| format!("{:x}", g)).collect();

    if best_len >= 2 {
        let before: Vec<&str> = hex_groups[..best_start].iter().map(|s| s.as_str()).collect();
        let after: Vec<&str> = hex_groups[best_start + best_len..]
            .iter()
            .map(|s| s.as_str())
            .collect();
        let mut result = String::new();
        result.push_str(&before.join(":"));
        result.push_str("::");
        result.push_str(&after.join(":"));
        result
    } else {
        hex_groups.join(":")
    }
}

fn escape_txt(s: &[u8]) -> String {
    let mut result = String::new();
    result.push('"');
    for &b in s {
        match b {
            b'"' => result.push_str("\\\""),
            b'\\' => result.push_str("\\\\"),
            0x20..=0x7E => result.push(b as char),
            _ => result.push_str(&format!("\\{:03}", b)),
        }
    }
    result.push('"');
    result
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let port: u16 = args[2].parse().unwrap();

    let content = fs::read_to_string(format!("{}/queries.txt", dir)).unwrap();
    let addr = format!("127.0.0.1:{}", port);
    let mut counter: u16 = 0;

    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let parts: Vec<&str> = trimmed.split(' ').collect();
        if parts.len() < 2 {
            continue;
        }
        let name = parts[0];
        let qtype_str = parts[1];
        let qtype = type_code(qtype_str);

        let id = generate_id(counter);
        counter = counter.wrapping_add(1);
        let query = build_query(id, name, qtype);

        // Send over UDP
        let udp = UdpSocket::bind("0.0.0.0:0").unwrap();
        udp.connect(&addr).unwrap();
        udp.send(&query).unwrap();

        let mut buf = vec![0u8; 4096];
        let mut resp: Vec<u8> = Vec::new();
        loop {
            let n = udp.recv(&mut buf).unwrap();
            if n >= 12 {
                let resp_id = u16::from_be_bytes([buf[0], buf[1]]);
                let flags = u16::from_be_bytes([buf[2], buf[3]]);
                let qr = (flags >> 15) & 1;
                if resp_id == id && qr == 1 {
                    resp = buf[..n].to_vec();
                    break;
                }
            }
        }

        // Check TC flag
        let flags = u16::from_be_bytes([resp[2], resp[3]]);
        let tc = (flags >> 9) & 1;

        if tc == 1 {
            let mut stream = TcpStream::connect(&addr).unwrap();
            let len = query.len() as u16;
            stream.write_all(&len.to_be_bytes()).unwrap();
            stream.write_all(&query).unwrap();

            let mut len_buf = [0u8; 2];
            stream.read_exact(&mut len_buf).unwrap();
            let resp_len = u16::from_be_bytes(len_buf) as usize;
            let mut tcp_resp = vec![0u8; resp_len];
            stream.read_exact(&mut tcp_resp).unwrap();
            resp = tcp_resp;
        }

        if resp.len() < 12 {
            continue;
        }

        let flags = u16::from_be_bytes([resp[2], resp[3]]);
        let rcode = (flags & 0x0F) as u8;
        let qdcount = u16::from_be_bytes([resp[4], resp[5]]) as usize;
        let ancount = u16::from_be_bytes([resp[6], resp[7]]) as usize;

        // Print query line
        let out_name = {
            let n = name.trim_end_matches('.');
            if n.is_empty() {
                ".".to_string()
            } else {
                n.to_lowercase()
            }
        };
        println!("{} {} {}", out_name, qtype_str, rcode_str(rcode));

        // Skip question section
        let mut pos = 12;
        for _ in 0..qdcount {
            let (_, new_pos) = parse_name(&resp, pos);
            pos = new_pos + 4; // skip QTYPE + QCLASS
        }

        // Parse answer section
        for _ in 0..ancount {
            if pos + 10 > resp.len() {
                break;
            }
            let (owner, new_pos) = parse_name(&resp, pos);
            pos = new_pos;

            if pos + 10 > resp.len() {
                break;
            }
            let rtype = u16::from_be_bytes([resp[pos], resp[pos + 1]]);
            pos += 2;
            pos += 2; // skip CLASS
            let ttl = u32::from_be_bytes([resp[pos], resp[pos + 1], resp[pos + 2], resp[pos + 3]]);
            pos += 4;
            let rdlength = u16::from_be_bytes([resp[pos], resp[pos + 1]]) as usize;
            pos += 2;

            let rdata_offset = pos;
            let rdata = &resp[pos..pos + rdlength];
            pos += rdlength;

            let data_str = match rtype {
                1 => {
                    if rdlength >= 4 {
                        format!("{}.{}.{}.{}", rdata[0], rdata[1], rdata[2], rdata[3])
                    } else {
                        String::new()
                    }
                }
                28 => {
                    if rdlength >= 16 {
                        format_ipv6(rdata)
                    } else {
                        String::new()
                    }
                }
                5 => {
                    let (target, _) = parse_name(&resp, rdata_offset);
                    target
                }
                15 => {
                    if rdlength >= 2 {
                        let pref = u16::from_be_bytes([rdata[0], rdata[1]]);
                        let (exchange, _) = parse_name(&resp, rdata_offset + 2);
                        format!("{} {}", pref, exchange)
                    } else {
                        String::new()
                    }
                }
                16 => {
                    let mut txt_parts: Vec<String> = Vec::new();
                    let mut tp = rdata_offset;
                    while tp < rdata_offset + rdlength {
                        let slen = resp[tp] as usize;
                        tp += 1;
                        if tp + slen > resp.len() {
                            break;
                        }
                        let sdata = &resp[tp..tp + slen];
                        txt_parts.push(escape_txt(sdata));
                        tp += slen;
                    }
                    txt_parts.join(" ")
                }
                _ => {
                    if rdlength == 0 {
                        "\\# 0".to_string()
                    } else {
                        let hex: String = rdata.iter().map(|b| format!("{:02x}", b)).collect();
                        format!("\\# {} {}", rdlength, hex)
                    }
                }
            };

            println!("  {} {} {} {}", owner, ttl, type_name(rtype), data_str);
        }
    }
}

import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';

const dir = process.argv[2];
const config = JSON.parse(fs.readFileSync(path.join(dir, 'config.json'), 'utf-8'));
const tokensRaw = fs.readFileSync(path.join(dir, 'tokens.txt'), 'utf-8');

const now: number = config.now;
const leeway: number = config.leeway;
const issuer: string = config.issuer;
const audience: string = config.audience;

const keyMap = new Map<string, { kty: string; alg: string; k: string }>();
for (const key of config.keys) {
    keyMap.set(key.kid, key);
}

function isValidBase64url(s: string): boolean {
    if (s.length === 0) return false;
    if (s.length % 4 === 1) return false;
    return /^[A-Za-z0-9\-_]+$/.test(s);
}

function base64urlDecode(s: string): Buffer {
    let base64 = s.replace(/-/g, '+').replace(/_/g, '/');
    const pad = base64.length % 4;
    if (pad === 2) base64 += '==';
    else if (pad === 3) base64 += '=';
    return Buffer.from(base64, 'base64');
}

const lines = tokensRaw.split('\n');
let tokenNum = 0;
let valid = 0;
let invalid = 0;
const outputLines: string[] = [];

for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed === '') continue;
    tokenNum++;

    let result = '';

    // Rule 1: MALFORMED
    const segments = trimmed.split('.');
    if (segments.length !== 3) {
        result = 'MALFORMED';
    } else {
        const [headerSeg, payloadSeg, sigSeg] = segments;
        if (!isValidBase64url(headerSeg) || !isValidBase64url(payloadSeg) || !isValidBase64url(sigSeg)) {
            result = 'MALFORMED';
        } else {
            let header: any;
            let payload: any;
            try {
                header = JSON.parse(base64urlDecode(headerSeg).toString('utf-8'));
            } catch {
                result = 'MALFORMED';
            }
            if (!result) {
                try {
                    payload = JSON.parse(base64urlDecode(payloadSeg).toString('utf-8'));
                } catch {
                    result = 'MALFORMED';
                }
            }
            if (!result) {
                if (typeof header !== 'object' || header === null || Array.isArray(header)) {
                    result = 'MALFORMED';
                } else if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
                    result = 'MALFORMED';
                } else {
                    // Rule 2: UNSUPPORTED_ALG
                    if (typeof header.alg !== 'string' || !['HS256', 'HS384', 'HS512'].includes(header.alg)) {
                        result = 'UNSUPPORTED_ALG';
                    } else {
                        // Rule 3: UNKNOWN_KEY
                        const kid = header.kid;
                        if (typeof kid !== 'string' || !keyMap.has(kid)) {
                            result = 'UNKNOWN_KEY';
                        } else {
                            const key = keyMap.get(kid)!;
                            // Rule 4: ALG_MISMATCH
                            if (key.alg !== header.alg) {
                                result = 'ALG_MISMATCH';
                            } else {
                                // Rule 5: BAD_SIGNATURE
                                const signingInput = headerSeg + '.' + payloadSeg;
                                const secret = base64urlDecode(key.k);
                                const hashAlg = header.alg === 'HS256' ? 'sha256'
                                    : header.alg === 'HS384' ? 'sha384' : 'sha512';
                                const expectedSig = crypto.createHmac(hashAlg, secret).update(signingInput).digest();
                                const actualSig = base64urlDecode(sigSeg);

                                if (actualSig.length !== expectedSig.length ||
                                    !crypto.timingSafeEqual(expectedSig, actualSig)) {
                                    result = 'BAD_SIGNATURE';
                                } else {
                                    // Rule 6: EXPIRED
                                    if (payload.exp !== undefined && now >= payload.exp + leeway) {
                                        result = 'EXPIRED';
                                    } else if (payload.nbf !== undefined && now + leeway < payload.nbf) {
                                        // Rule 7: NOT_YET_VALID
                                        result = 'NOT_YET_VALID';
                                    } else if (payload.iss === undefined || payload.iss !== issuer) {
                                        // Rule 8: BAD_ISSUER
                                        result = 'BAD_ISSUER';
                                    } else if (payload.aud === undefined) {
                                        // Rule 9: BAD_AUDIENCE
                                        result = 'BAD_AUDIENCE';
                                    } else if (typeof payload.aud === 'string') {
                                        if (payload.aud !== audience) {
                                            result = 'BAD_AUDIENCE';
                                        }
                                    } else if (Array.isArray(payload.aud)) {
                                        if (!payload.aud.includes(audience)) {
                                            result = 'BAD_AUDIENCE';
                                        }
                                    } else {
                                        result = 'BAD_AUDIENCE';
                                    }

                                    if (!result) {
                                        const sub = payload.sub as string;
                                        let scopes: string[] = [];
                                        if (typeof payload.scope === 'string' && payload.scope !== '') {
                                            const parts = payload.scope.split(' ').filter(s => s !== '');
                                            scopes = [...new Set(parts)];
                                            scopes.sort((a, b) => {
                                                const aCps = [...a];
                                                const bCps = [...b];
                                                const minLen = Math.min(aCps.length, bCps.length);
                                                for (let i = 0; i < minLen; i++) {
                                                    const diff = aCps[i].codePointAt(0)! - bCps[i].codePointAt(0)!;
                                                    if (diff !== 0) return diff;
                                                }
                                                return aCps.length - bCps.length;
                                            });
                                        }
                                        result = `VALID sub=${sub} scope=${scopes.join(',')}`;
                                        valid++;
                                        outputLines.push(`${tokenNum}: ${result}`);
                                        continue;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    if (result) {
        invalid++;
        outputLines.push(`${tokenNum}: ${result}`);
    }
}

if (outputLines.length > 0) {
    console.log(outputLines.join('\n'));
}
console.log('');
console.log(`valid=${valid} invalid=${invalid}`);

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>

static int read_exact(int fd, uint8_t *buf, int n) {
    int total = 0;
    while (total < n) {
        int r = read(fd, buf + total, n - total);
        if (r <= 0) return -1;
        total += r;
    }
    return total;
}

static int parse_name(uint8_t *msg, int msglen, int offset, char *out, int outsz) {
    int pos = offset;
    int consumed = -1;
    int outpos = 0;
    int jumps = 0;

    while (pos < msglen) {
        uint8_t len = msg[pos];
        if ((len & 0xC0) == 0xC0) {
            if (consumed < 0) consumed = pos + 2 - offset;
            int ptr = ((len & 0x3F) << 8) | msg[pos + 1];
            pos = ptr;
            jumps++;
            if (jumps > 128) break;
        } else if (len == 0) {
            if (consumed < 0) consumed = pos + 1 - offset;
            break;
        } else {
            pos++;
            if (outpos > 0 && outpos < outsz - 1) out[outpos++] = '.';
            for (int i = 0; i < len && pos < msglen && outpos < outsz - 1; i++) {
                char c = msg[pos++];
                if (c >= 'A' && c <= 'Z') c += 32;
                out[outpos++] = c;
            }
        }
    }
    if (outpos == 0) {
        out[0] = '.';
        outpos = 1;
    }
    out[outpos] = '\0';
    if (consumed < 0) consumed = pos - offset;
    return consumed;
}

static void get_type_name(int type, char *buf, int bufsz) {
    switch (type) {
        case 1:  snprintf(buf, bufsz, "A"); break;
        case 5:  snprintf(buf, bufsz, "CNAME"); break;
        case 15: snprintf(buf, bufsz, "MX"); break;
        case 16: snprintf(buf, bufsz, "TXT"); break;
        case 28: snprintf(buf, bufsz, "AAAA"); break;
        default: snprintf(buf, bufsz, "TYPE%d", type); break;
    }
}

static void get_rcode_name(int rcode, char *buf, int bufsz) {
    switch (rcode) {
        case 0: snprintf(buf, bufsz, "NOERROR"); break;
        case 1: snprintf(buf, bufsz, "FORMERR"); break;
        case 2: snprintf(buf, bufsz, "SERVFAIL"); break;
        case 3: snprintf(buf, bufsz, "NXDOMAIN"); break;
        case 4: snprintf(buf, bufsz, "NOTIMP"); break;
        case 5: snprintf(buf, bufsz, "REFUSED"); break;
        default: snprintf(buf, bufsz, "RCODE%d", rcode); break;
    }
}

static void format_ipv6(uint8_t *data, char *out, int outsz) {
    uint16_t groups[8];
    for (int i = 0; i < 8; i++)
        groups[i] = (data[i * 2] << 8) | data[i * 2 + 1];

    int best_start = -1, best_len = 0;
    int cur_start = -1, cur_len = 0;
    for (int i = 0; i < 8; i++) {
        if (groups[i] == 0) {
            if (cur_start < 0) { cur_start = i; cur_len = 1; }
            else cur_len++;
        } else {
            if (cur_len > best_len && cur_len >= 2) {
                best_start = cur_start;
                best_len = cur_len;
            }
            cur_start = -1;
            cur_len = 0;
        }
    }
    if (cur_len > best_len && cur_len >= 2) {
        best_start = cur_start;
        best_len = cur_len;
    }

    int pos = 0;
    for (int i = 0; i < 8; i++) {
        if (i == best_start) {
            if (pos < outsz - 2) { out[pos++] = ':'; out[pos++] = ':'; }
            i += best_len - 1;
            continue;
        }
        if (pos > 0 && !(pos >= 2 && out[pos - 1] == ':' && out[pos - 2] == ':')) {
            if (pos < outsz - 1) out[pos++] = ':';
        }
        pos += snprintf(out + pos, outsz - pos, "%x", groups[i]);
    }
    out[pos] = '\0';
}

static void format_txt(uint8_t *data, int datalen, char *out, int outsz) {
    int pos = 0;
    int i = 0;
    int first = 1;
    while (i < datalen) {
        int slen = data[i];
        i++;
        if (!first && pos < outsz - 1) out[pos++] = ' ';
        first = 0;
        if (pos < outsz - 1) out[pos++] = '"';
        for (int j = 0; j < slen && i < datalen; j++, i++) {
            uint8_t c = data[i];
            if (c == '"') {
                if (pos < outsz - 2) { out[pos++] = '\\'; out[pos++] = '"'; }
            } else if (c == '\\') {
                if (pos < outsz - 2) { out[pos++] = '\\'; out[pos++] = '\\'; }
            } else if (c >= 0x20 && c <= 0x7E) {
                if (pos < outsz - 1) out[pos++] = c;
            } else {
                if (pos < outsz - 4) pos += snprintf(out + pos, outsz - pos, "\\%03d", c);
            }
        }
        if (pos < outsz - 1) out[pos++] = '"';
    }
    out[pos] = '\0';
}

static void format_rdata(int type, uint8_t *msg, int msglen, int rdoffset, int rdlen, char *out, int outsz) {
    switch (type) {
        case 1:
            snprintf(out, outsz, "%d.%d.%d.%d", msg[rdoffset], msg[rdoffset + 1], msg[rdoffset + 2], msg[rdoffset + 3]);
            break;
        case 28:
            format_ipv6(msg + rdoffset, out, outsz);
            break;
        case 5: {
            char name[512];
            parse_name(msg, msglen, rdoffset, name, sizeof(name));
            snprintf(out, outsz, "%s", name);
            break;
        }
        case 15: {
            int pref = (msg[rdoffset] << 8) | msg[rdoffset + 1];
            char name[512];
            parse_name(msg, msglen, rdoffset + 2, name, sizeof(name));
            snprintf(out, outsz, "%d %s", pref, name);
            break;
        }
        case 16:
            format_txt(msg + rdoffset, rdlen, out, outsz);
            break;
        default: {
            int n = snprintf(out, outsz, "\\# %d", rdlen);
            if (rdlen > 0) {
                out[n++] = ' ';
                for (int i = 0; i < rdlen; i++)
                    n += snprintf(out + n, outsz - n, "%02x", msg[rdoffset + i]);
            }
            out[n] = '\0';
            break;
        }
    }
}

static void parse_response(uint8_t *msg, int msglen, char *query_name, int query_type) {
    if (msglen < 12) return;

    uint16_t flags = (msg[2] << 8) | msg[3];
    int rcode = flags & 0x0F;
    uint16_t qdcount = (msg[4] << 8) | msg[5];
    uint16_t ancount = (msg[6] << 8) | msg[7];

    char rcode_str[32];
    get_rcode_name(rcode, rcode_str, sizeof(rcode_str));
    printf("%s %d %s\n", query_name, query_type, rcode_str);

    int pos = 12;
    for (int i = 0; i < qdcount; i++) {
        while (pos < msglen) {
            uint8_t b = msg[pos];
            if ((b & 0xC0) == 0xC0) { pos += 2; break; }
            else if (b == 0) { pos++; break; }
            else pos += 1 + b;
        }
        pos += 4;
    }

    for (int i = 0; i < ancount && pos < msglen; i++) {
        char owner[512];
        int consumed = parse_name(msg, msglen, pos, owner, sizeof(owner));
        pos += consumed;

        if (pos + 10 > msglen) break;
        uint16_t rtype = (msg[pos] << 8) | msg[pos + 1];
        uint32_t ttl = ((uint32_t)msg[pos + 4] << 24) | ((uint32_t)msg[pos + 5] << 16) |
                       ((uint32_t)msg[pos + 6] << 8) | msg[pos + 7];
        uint16_t rdlen = (msg[pos + 8] << 8) | msg[pos + 9];
        pos += 10;

        int rdoffset = pos;
        pos += rdlen;

        char type_name[32];
        get_type_name(rtype, type_name, sizeof(type_name));

        char data[8192];
        format_rdata(rtype, msg, msglen, rdoffset, rdlen, data, sizeof(data));

        printf("  %s %u %s %s\n", owner, ttl, type_name, data);
    }
}

static int build_query(uint16_t id, const char *name, int qtype, uint8_t *buf, int bufsz) {
    int pos = 0;
    buf[pos++] = (id >> 8) & 0xFF;
    buf[pos++] = id & 0xFF;
    buf[pos++] = 0x01;
    buf[pos++] = 0x00;
    buf[pos++] = 0x00; buf[pos++] = 0x01;
    buf[pos++] = 0x00; buf[pos++] = 0x00;
    buf[pos++] = 0x00; buf[pos++] = 0x00;
    buf[pos++] = 0x00; buf[pos++] = 0x00;

    const char *p = name;
    while (*p) {
        const char *dot = strchr(p, '.');
        int label_len;
        if (dot) {
            label_len = dot - p;
            if (label_len > 0) {
                buf[pos++] = label_len;
                memcpy(buf + pos, p, label_len);
                pos += label_len;
            }
            p = dot + 1;
        } else {
            label_len = strlen(p);
            if (label_len > 0) {
                buf[pos++] = label_len;
                memcpy(buf + pos, p, label_len);
                pos += label_len;
            }
            p += label_len;
        }
    }
    buf[pos++] = 0;

    buf[pos++] = (qtype >> 8) & 0xFF;
    buf[pos++] = qtype & 0xFF;
    buf[pos++] = 0x00;
    buf[pos++] = 0x01;

    return pos;
}

static int get_type_num(const char *type) {
    if (strcmp(type, "A") == 0) return 1;
    if (strcmp(type, "AAAA") == 0) return 28;
    if (strcmp(type, "MX") == 0) return 15;
    if (strcmp(type, "TXT") == 0) return 16;
    if (strcmp(type, "CNAME") == 0) return 5;
    return 0;
}

static void normalize_name(const char *name, char *out, int outsz) {
    int len = strlen(name);
    int pos = 0;
    for (int i = 0; i < len; i++) {
        char c = name[i];
        if (c >= 'A' && c <= 'Z') c += 32;
        if (pos < outsz - 1) out[pos++] = c;
    }
    if (pos > 0 && out[pos - 1] == '.') pos--;
    if (pos == 0) { out[0] = '.'; pos = 1; }
    out[pos] = '\0';
}

int main(int argc, char *argv[]) {
    if (argc < 3) return 1;

    srandom(time(NULL) ^ getpid());

    char filepath[2048];
    snprintf(filepath, sizeof(filepath), "%s/queries.txt", argv[1]);
    int port = atoi(argv[2]);

    FILE *f = fopen(filepath, "r");
    if (!f) return 1;

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    addr.sin_addr.s_addr = inet_addr("127.0.0.1");

    char line[4096];
    while (fgets(line, sizeof(line), f)) {
        int len = strlen(line);
        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r')) line[--len] = '\0';
        if (len == 0) continue;

        char *space = strchr(line, ' ');
        if (!space) continue;
        *space = '\0';
        char *name_str = line;
        char *type_str = space + 1;

        int qtype = get_type_num(type_str);
        char norm_name[512];
        normalize_name(name_str, norm_name, sizeof(norm_name));

        uint16_t id = (uint16_t)(random() & 0xFFFF);

        uint8_t query[512];
        int qlen = build_query(id, name_str, qtype, query, sizeof(query));

        int udp_fd = socket(AF_INET, SOCK_DGRAM, 0);
        sendto(udp_fd, query, qlen, 0, (struct sockaddr *)&addr, sizeof(addr));

        uint8_t resp[65536];
        int resp_len;
        int done = 0;

        while (!done) {
            resp_len = recvfrom(udp_fd, resp, sizeof(resp), 0, NULL, NULL);
            if (resp_len < 12) continue;

            uint16_t resp_id = (resp[0] << 8) | resp[1];
            if (resp_id != id) continue;

            uint16_t resp_flags = (resp[2] << 8) | resp[3];
            if (!(resp_flags & 0x8000)) continue;

            if (resp_flags & 0x0200) {
                close(udp_fd);

                int tcp_fd = socket(AF_INET, SOCK_STREAM, 0);
                connect(tcp_fd, (struct sockaddr *)&addr, sizeof(addr));

                uint8_t tcp_buf[512];
                tcp_buf[0] = (qlen >> 8) & 0xFF;
                tcp_buf[1] = qlen & 0xFF;
                memcpy(tcp_buf + 2, query, qlen);
                write(tcp_fd, tcp_buf, qlen + 2);

                uint8_t lenbuf[2];
                read_exact(tcp_fd, lenbuf, 2);
                int tcp_resp_len = (lenbuf[0] << 8) | lenbuf[1];

                uint8_t tcp_resp[65536];
                read_exact(tcp_fd, tcp_resp, tcp_resp_len);
                close(tcp_fd);

                parse_response(tcp_resp, tcp_resp_len, norm_name, qtype);
                done = 1;
            } else {
                parse_response(resp, resp_len, norm_name, qtype);
                done = 1;
            }
        }

        close(udp_fd);
    }

    fclose(f);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>

static int read_exact(int fd, uint8_t *buf, int n) {
    int total = 0;
    while (total < n) {
        int r = read(fd, buf + total, n - total);
        if (r <= 0) return -1;
        total += r;
    }
    return total;
}

static int parse_name(uint8_t *msg, int msglen, int offset, char *out, int outsz) {
    int pos = offset;
    int consumed = -1;
    int outpos = 0;
    int jumps = 0;

    while (pos < msglen) {
        uint8_t len = msg[pos];
        if ((len & 0xC0) == 0xC0) {
            if (consumed < 0) consumed = pos + 2 - offset;
            int ptr = ((len & 0x3F) << 8) | msg[pos + 1];
            pos = ptr;
            jumps++;
            if (jumps > 128) break;
        } else if (len == 0) {
            if (consumed < 0) consumed = pos + 1 - offset;
            break;
        } else {
            pos++;
            if (outpos > 0 && outpos < outsz - 1) out[outpos++] = '.';
            for (int i = 0; i < len && pos < msglen && outpos < outsz - 1; i++) {
                char c = msg[pos++];
                if (c >= 'A' && c <= 'Z') c += 32;
                out[outpos++] = c;
            }
        }
    }
    if (outpos == 0) {
        out[0] = '.';
        outpos = 1;
    }
    out[outpos] = '\0';
    if (consumed < 0) consumed = pos - offset;
    return consumed;
}

static void get_type_name(int type, char *buf, int bufsz) {
    switch (type) {
        case 1:  snprintf(buf, bufsz, "A"); break;
        case 5:  snprintf(buf, bufsz, "CNAME"); break;
        case 15: snprintf(buf, bufsz, "MX"); break;
        case 16: snprintf(buf, bufsz, "TXT"); break;
        case 28: snprintf(buf, bufsz, "AAAA"); break;
        default: snprintf(buf, bufsz, "TYPE%d", type); break;
    }
}

static void get_rcode_name(int rcode, char *buf, int bufsz) {
    switch (rcode) {
        case 0: snprintf(buf, bufsz, "NOERROR"); break;
        case 1: snprintf(buf, bufsz, "FORMERR"); break;
        case 2: snprintf(buf, bufsz, "SERVFAIL"); break;
        case 3: snprintf(buf, bufsz, "NXDOMAIN"); break;
        case 4: snprintf(buf, bufsz, "NOTIMP"); break;
        case 5: snprintf(buf, bufsz, "REFUSED"); break;
        default: snprintf(buf, bufsz, "RCODE%d", rcode); break;
    }
}

static void format_ipv6(uint8_t *data, char *out, int outsz) {
    uint16_t groups[8];
    for (int i = 0; i < 8; i++)
        groups[i] = (data[i * 2] << 8) | data[i * 2 + 1];

    int best_start = -1, best_len = 0;
    int cur_start = -1, cur_len = 0;
    for (int i = 0; i < 8; i++) {
        if (groups[i] == 0) {
            if (cur_start < 0) { cur_start = i; cur_len = 1; }
            else cur_len++;
        } else {
            if (cur_len > best_len && cur_len >= 2) {
                best_start = cur_start;
                best_len = cur_len;
            }
            cur_start = -1;
            cur_len = 0;
        }
    }
    if (cur_len > best_len && cur_len >= 2) {
        best_start = cur_start;
        best_len = cur_len;
    }

    int pos = 0;
    for (int i = 0; i < 8; i++) {
        if (i == best_start) {
            if (pos < outsz - 2) { out[pos++] = ':'; out[pos++] = ':'; }
            i += best_len - 1;
            continue;
        }
        if (pos > 0 && !(pos >= 2 && out[pos - 1] == ':' && out[pos - 2] == ':')) {
            if (pos < outsz - 1) out[pos++] = ':';
        }
        pos += snprintf(out + pos, outsz - pos, "%x", groups[i]);
    }
    out[pos] = '\0';
}

static void format_txt(uint8_t *data, int datalen, char *out, int outsz) {
    int pos = 0;
    int i = 0;
    int first = 1;
    while (i < datalen) {
        int slen = data[i];
        i++;
        if (!first && pos < outsz - 1) out[pos++] = ' ';
        first = 0;
        if (pos < outsz - 1) out[pos++] = '"';
        for (int j = 0; j < slen && i < datalen; j++, i++) {
            uint8_t c = data[i];
            if (c == '"') {
                if (pos < outsz - 2) { out[pos++] = '\\'; out[pos++] = '"'; }
            } else if (c == '\\') {
                if (pos < outsz - 2) { out[pos++] = '\\'; out[pos++] = '\\'; }
            } else if (c >= 0x20 && c <= 0x7E) {
                if (pos < outsz - 1) out[pos++] = c;
            } else {
                if (pos < outsz - 4) pos += snprintf(out + pos, outsz - pos, "\\%03d", c);
            }
        }
        if (pos < outsz - 1) out[pos++] = '"';
    }
    out[pos] = '\0';
}

static void format_rdata(int type, uint8_t *msg, int msglen, int rdoffset, int rdlen, char *out, int outsz) {
    switch (type) {
        case 1:
            snprintf(out, outsz, "%d.%d.%d.%d", msg[rdoffset], msg[rdoffset + 1], msg[rdoffset + 2], msg[rdoffset + 3]);
            break;
        case 28:
            format_ipv6(msg + rdoffset, out, outsz);
            break;
        case 5: {
            char name[512];
            parse_name(msg, msglen, rdoffset, name, sizeof(name));
            snprintf(out, outsz, "%s", name);
            break;
        }
        case 15: {
            int pref = (msg[rdoffset] << 8) | msg[rdoffset + 1];
            char name[512];
            parse_name(msg, msglen, rdoffset + 2, name, sizeof(name));
            snprintf(out, outsz, "%d %s", pref, name);
            break;
        }
        case 16:
            format_txt(msg + rdoffset, rdlen, out, outsz);
            break;
        default: {
            int n = snprintf(out, outsz, "\\# %d", rdlen);
            if (rdlen > 0) {
                n += snprintf(out + n, outsz - n, " ");
                for (int i = 0; i < rdlen; i++)
                    n += snprintf(out + n, outsz - n, "%02x", msg[rdoffset + i]);
            }
            break;
        }
    }
}

static void parse_response(uint8_t *msg, int msglen, char *query_name, int query_type) {
    if (msglen < 12) return;

    uint16_t flags = (msg[2] << 8) | msg[3];
    int rcode = flags & 0x0F;
    uint16_t qdcount = (msg[4] << 8) | msg[5];
    uint16_t ancount = (msg[6] << 8) | msg[7];

    char rcode_str[32];
    get_rcode_name(rcode, rcode_str, sizeof(rcode_str));

    char type_str[32];
    get_type_name(query_type, type_str, sizeof(type_str));

    printf("%s %s %s\n", query_name, type_str, rcode_str);

    int pos = 12;
    for (int i = 0; i < qdcount; i++) {
        while (pos < msglen) {
            uint8_t b = msg[pos];
            if ((b & 0xC0) == 0xC0) { pos += 2; break; }
            else if (b == 0) { pos++; break; }
            else pos += 1 + b;
        }
        pos += 4;
    }

    for (int i = 0; i < ancount && pos < msglen; i++) {
        char owner[512];
        int consumed = parse_name(msg, msglen, pos, owner, sizeof(owner));
        pos += consumed;

        if (pos + 10 > msglen) break;
        uint16_t rtype = (msg[pos] << 8) | msg[pos + 1];
        uint32_t ttl = ((uint32_t)msg[pos + 4] << 24) | ((uint32_t)msg[pos + 5] << 16) |
                       ((uint32_t)msg[pos + 6] << 8) | msg[pos + 7];
        uint16_t rdlen = (msg[pos + 8] << 8) | msg[pos + 9];
        pos += 10;

        int rdoffset = pos;
        pos += rdlen;

        char type_name[32];
        get_type_name(rtype, type_name, sizeof(type_name));

        char data[8192];
        format_rdata(rtype, msg, msglen, rdoffset, rdlen, data, sizeof(data));

        printf("  %s %u %s %s\n", owner, ttl, type_name, data);
    }
}

static int build_query(uint16_t id, const char *name, int qtype, uint8_t *buf, int bufsz) {
    int pos = 0;
    buf[pos++] = (id >> 8) & 0xFF;
    buf[pos++] = id & 0xFF;
    buf[pos++] = 0x01;
    buf[pos++] = 0x00;
    buf[pos++] = 0x00; buf[pos++] = 0x01;
    buf[pos++] = 0x00; buf[pos++] = 0x00;
    buf[pos++] = 0x00; buf[pos++] = 0x00;
    buf[pos++] = 0x00; buf[pos++] = 0x00;

    const char *p = name;
    while (*p) {
        const char *dot = strchr(p, '.');
        int label_len;
        if (dot) {
            label_len = dot - p;
            if (label_len > 0) {
                buf[pos++] = label_len;
                memcpy(buf + pos, p, label_len);
                pos += label_len;
            }
            p = dot + 1;
        } else {
            label_len = strlen(p);
            if (label_len > 0) {
                buf[pos++] = label_len;
                memcpy(buf + pos, p, label_len);
                pos += label_len;
            }
            p += label_len;
        }
    }
    buf[pos++] = 0;

    buf[pos++] = (qtype >> 8) & 0xFF;
    buf[pos++] = qtype & 0xFF;
    buf[pos++] = 0x00;
    buf[pos++] = 0x01;

    return pos;
}

static int get_type_num(const char *type) {
    if (strcmp(type, "A") == 0) return 1;
    if (strcmp(type, "AAAA") == 0) return 28;
    if (strcmp(type, "MX") == 0) return 15;
    if (strcmp(type, "TXT") == 0) return 16;
    if (strcmp(type, "CNAME") == 0) return 5;
    return 0;
}

static void normalize_name(const char *name, char *out, int outsz) {
    int len = strlen(name);
    int pos = 0;
    for (int i = 0; i < len; i++) {
        char c = name[i];
        if (c >= 'A' && c <= 'Z') c += 32;
        if (pos < outsz - 1) out[pos++] = c;
    }
    if (pos > 0 && out[pos - 1] == '.') pos--;
    if (pos == 0) { out[0] = '.'; pos = 1; }
    out[pos] = '\0';
}

int main(int argc, char *argv[]) {
    if (argc < 3) return 1;

    srandom(time(NULL) ^ getpid());

    char filepath[2048];
    snprintf(filepath, sizeof(filepath), "%s/queries.txt", argv[1]);
    int port = atoi(argv[2]);

    FILE *f = fopen(filepath, "r");
    if (!f) return 1;

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    addr.sin_addr.s_addr = inet_addr("127.0.0.1");

    char line[4096];
    while (fgets(line, sizeof(line), f)) {
        int len = strlen(line);
        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r')) line[--len] = '\0';
        if (len == 0) continue;

        char *space = strchr(line, ' ');
        if (!space) continue;
        *space = '\0';
        char *name_str = line;
        char *type_str = space + 1;

        int qtype = get_type_num(type_str);
        char norm_name[512];
        normalize_name(name_str, norm_name, sizeof(norm_name));

        uint16_t id = (uint16_t)(random() & 0xFFFF);

        uint8_t query[512];
        int qlen = build_query(id, name_str, qtype, query, sizeof(query));

        int udp_fd = socket(AF_INET, SOCK_DGRAM, 0);
        sendto(udp_fd, query, qlen, 0, (struct sockaddr *)&addr, sizeof(addr));

        uint8_t resp[65536];
        int resp_len;
        int done = 0;

        while (!done) {
            resp_len = recvfrom(udp_fd, resp, sizeof(resp), 0, NULL, NULL);
            if (resp_len < 12) continue;

            uint16_t resp_id = (resp[0] << 8) | resp[1];
            if (resp_id != id) continue;

            uint16_t resp_flags = (resp[2] << 8) | resp[3];
            if (!(resp_flags & 0x8000)) continue;

            if (resp_flags & 0x0200) {
                close(udp_fd);

                int tcp_fd = socket(AF_INET, SOCK_STREAM, 0);
                connect(tcp_fd, (struct sockaddr *)&addr, sizeof(addr));

                uint8_t tcp_buf[512];
                tcp_buf[0] = (qlen >> 8) & 0xFF;
                tcp_buf[1] = qlen & 0xFF;
                memcpy(tcp_buf + 2, query, qlen);
                write(tcp_fd, tcp_buf, qlen + 2);

                uint8_t lenbuf[2];
                read_exact(tcp_fd, lenbuf, 2);
                int tcp_resp_len = (lenbuf[0] << 8) | lenbuf[1];

                uint8_t tcp_resp[65536];
                read_exact(tcp_fd, tcp_resp, tcp_resp_len);
                close(tcp_fd);

                parse_response(tcp_resp, tcp_resp_len, norm_name, qtype);
                done = 1;
            } else {
                parse_response(resp, resp_len, norm_name, qtype);
                done = 1;
            }
        }

        close(udp_fd);
    }

    fclose(f);
    return 0;
}

import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.security.*;

public class Main {

    // --- Simple JSON Parser ---
    static class JsonParser {
        private final String input;
        private int pos;

        JsonParser(String input) {
            this.input = input;
            this.pos = 0;
        }

        Object parse() {
            skipWs();
            Object v = parseValue();
            skipWs();
            return v;
        }

        private void skipWs() {
            while (pos < input.length()) {
                char c = input.charAt(pos);
                if (c == ' ' || c == '\t' || c == '\n' || c == '\r') pos++;
                else break;
            }
        }

        private Object parseValue() {
            if (pos >= input.length()) throw new RuntimeException("EOF");
            char c = input.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (c == 't') { expect("true"); return Boolean.TRUE; }
            if (c == 'f') { expect("false"); return Boolean.FALSE; }
            if (c == 'n') { expect("null"); return null; }
            if (c == '-' || (c >= '0' && c <= '9')) return parseNumber();
            throw new RuntimeException("Unexpected char: " + c);
        }

        private Map<String, Object> parseObject() {
            Map<String, Object> map = new LinkedHashMap<>();
            pos++; // {
            skipWs();
            if (pos < input.length() && input.charAt(pos) == '}') { pos++; return map; }
            while (true) {
                skipWs();
                String key = parseString();
                skipWs();
                expect(':');
                skipWs();
                map.put(key, parseValue());
                skipWs();
                if (pos < input.length() && input.charAt(pos) == ',') { pos++; }
                else break;
            }
            expect('}');
            return map;
        }

        private List<Object> parseArray() {
            List<Object> list = new ArrayList<>();
            pos++; // [
            skipWs();
            if (pos < input.length() && input.charAt(pos) == ']') { pos++; return list; }
            while (true) {
                skipWs();
                list.add(parseValue());
                skipWs();
                if (pos < input.length() && input.charAt(pos) == ',') { pos++; }
                else break;
            }
            expect(']');
            return list;
        }

        private String parseString() {
            expect('"');
            StringBuilder sb = new StringBuilder();
            while (pos < input.length()) {
                char c = input.charAt(pos);
                if (c == '"') { pos++; return sb.toString(); }
                if (c == '\\') {
                    pos++;
                    char e = input.charAt(pos);
                    switch (e) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u':
                            pos++;
                            int cp = Integer.parseInt(input.substring(pos, pos + 4), 16);
                            sb.append((char) cp);
                            pos += 3;
                            break;
                        default: throw new RuntimeException("Bad escape");
                    }
                } else {
                    sb.append(c);
                }
                pos++;
            }
            throw new RuntimeException("Unterminated string");
        }

        private Double parseNumber() {
            int start = pos;
            if (pos < input.length() && input.charAt(pos) == '-') pos++;
            while (pos < input.length() && input.charAt(pos) >= '0' && input.charAt(pos) <= '9') pos++;
            if (pos < input.length() && input.charAt(pos) == '.') {
                pos++;
                while (pos < input.length() && input.charAt(pos) >= '0' && input.charAt(pos) <= '9') pos++;
            }
            if (pos < input.length() && (input.charAt(pos) == 'e' || input.charAt(pos) == 'E')) {
                pos++;
                if (pos < input.length() && (input.charAt(pos) == '+' || input.charAt(pos) == '-')) pos++;
                while (pos < input.length() && input.charAt(pos) >= '0' && input.charAt(pos) <= '9') pos++;
            }
            return Double.parseDouble(input.substring(start, pos));
        }

        private void expect(char c) {
            if (pos >= input.length() || input.charAt(pos) != c)
                throw new RuntimeException("Expected '" + c + "' at " + pos);
            pos++;
        }

        private void expect(String s) {
            if (!input.startsWith(s, pos))
                throw new RuntimeException("Expected '" + s + "' at " + pos);
            pos += s.length();
        }
    }

    // --- Base64url ---
    static boolean isValidBase64url(String s) {
        if (s.isEmpty()) return false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
                  (c >= '0' && c <= '9') || c == '-' || c == '_')) {
                return false;
            }
        }
        return s.length() % 4 != 1;
    }

    static byte[] decodeBase64url(String s) {
        String std = s.replace('-', '+').replace('_', '/');
        int pad = (4 - std.length() % 4) % 4;
        if (pad > 0) std += "=".repeat(pad);
        return java.util.Base64.getDecoder().decode(std);
    }

    // --- HMAC ---
    static byte[] computeHmac(String alg, byte[] key, byte[] data) throws Exception {
        String macAlg;
        switch (alg) {
            case "HS256": macAlg = "HmacSHA256"; break;
            case "HS384": macAlg = "HmacSHA384"; break;
            case "HS512": macAlg = "HmacSHA512"; break;
            default: throw new RuntimeException("Unsupported");
        }
        Mac mac = Mac.getInstance(macAlg);
        mac.init(new SecretKeySpec(key, macAlg));
        return mac.doFinal(data);
    }

    // --- Main ---
    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        String dir = args[0];

        String configStr = new String(Files.readAllBytes(Paths.get(dir, "config.json")), StandardCharsets.UTF_8);
        Map<String, Object> config = (Map<String, Object>) new JsonParser(configStr).parse();

        double now = ((Number) config.get("now")).doubleValue();
        double leeway = ((Number) config.get("leeway")).doubleValue();
        String issuer = (String) config.get("issuer");
        String audience = (String) config.get("audience");

        List<Map<String, Object>> keysList = (List<Map<String, Object>>) config.get("keys");
        Map<String, Map<String, Object>> keyMap = new HashMap<>();
        for (Map<String, Object> k : keysList) {
            keyMap.put((String) k.get("kid"), k);
        }

        List<String> lines = Files.readAllLines(Paths.get(dir, "tokens.txt"), StandardCharsets.UTF_8);

        int validCount = 0, invalidCount = 0, lineNum = 0;

        for (String line : lines) {
            String trimmed = line.trim();
            if (trimmed.isEmpty()) continue;
            lineNum++;

            String result = validate(trimmed, now, leeway, issuer, audience, keyMap);
            if (result.startsWith("VALID")) validCount++;
            else invalidCount++;
            System.out.println(lineNum + ": " + result);
        }

        System.out.println();
        System.out.println("valid=" + validCount + " invalid=" + invalidCount);
    }

    @SuppressWarnings("unchecked")
    static String validate(String token, double now, double leeway, String issuer,
                           String audience, Map<String, Map<String, Object>> keyMap) {
        // Rule 1: MALFORMED
        String[] parts = token.split("\\.", -1);
        if (parts.length != 3) return "MALFORMED";

        String headerSeg = parts[0];
        String payloadSeg = parts[1];
        String sigSeg = parts[2];

        if (!isValidBase64url(headerSeg) || !isValidBase64url(payloadSeg) || !isValidBase64url(sigSeg))
            return "MALFORMED";

        byte[] headerBytes, payloadBytes;
        try {
            headerBytes = decodeBase64url(headerSeg);
            payloadBytes = decodeBase64url(payloadSeg);
        } catch (Exception e) {
            return "MALFORMED";
        }

        Map<String, Object> header, payload;
        try {
            Object ho = new JsonParser(new String(headerBytes, StandardCharsets.UTF_8)).parse();
            if (!(ho instanceof Map)) return "MALFORMED";
            header = (Map<String, Object>) ho;

            Object po = new JsonParser(new String(payloadBytes, StandardCharsets.UTF_8)).parse();
            if (!(po instanceof Map)) return "MALFORMED";
            payload = (Map<String, Object>) po;
        } catch (Exception e) {
            return "MALFORMED";
        }

        // Rule 2: UNSUPPORTED_ALG
        Object algObj = header.get("alg");
        if (!(algObj instanceof String)) return "UNSUPPORTED_ALG";
        String alg = (String) algObj;
        if (!alg.equals("HS256") && !alg.equals("HS384") && !alg.equals("HS512"))
            return "UNSUPPORTED_ALG";

        // Rule 3: UNKNOWN_KEY
        Object kidObj = header.get("kid");
        if (!(kidObj instanceof String)) return "UNKNOWN_KEY";
        String kid = (String) kidObj;
        if (!keyMap.containsKey(kid)) return "UNKNOWN_KEY";
        Map<String, Object> keyEntry = keyMap.get(kid);

        // Rule 4: ALG_MISMATCH
        String keyAlg = (String) keyEntry.get("alg");
        if (!alg.equals(keyAlg)) return "ALG_MISMATCH";

        // Rule 5: BAD_SIGNATURE
        byte[] secret;
        try {
            secret = decodeBase64url((String) keyEntry.get("k"));
        } catch (Exception e) {
            return "BAD_SIGNATURE";
        }

        byte[] signingInput = (headerSeg + "." + payloadSeg).getBytes(StandardCharsets.US_ASCII);
        byte[] expectedSig;
        try {
            expectedSig = computeHmac(alg, secret, signingInput);
        } catch (Exception e) {
            return "BAD_SIGNATURE";
        }

        byte[] actualSig;
        try {
            actualSig = decodeBase64url(sigSeg);
        } catch (Exception e) {
            return "BAD_SIGNATURE";
        }

        if (!Arrays.equals(expectedSig, actualSig)) return "BAD_SIGNATURE";

        // Rule 6: EXPIRED
        if (payload.containsKey("exp")) {
            double exp = ((Number) payload.get("exp")).doubleValue();
            if (now >= exp + leeway) return "EXPIRED";
        }

        // Rule 7: NOT_YET_VALID
        if (payload.containsKey("nbf")) {
            double nbf = ((Number) payload.get("nbf")).doubleValue();
            if (now + leeway < nbf) return "NOT_YET_VALID";
        }

        // Rule 8: BAD_ISSUER
        Object issObj = payload.get("iss");
        if (!(issObj instanceof String) || !issObj.equals(issuer)) return "BAD_ISSUER";

        // Rule 9: BAD_AUDIENCE
        Object audObj = payload.get("aud");
        if (audObj == null) return "BAD_AUDIENCE";
        if (audObj instanceof String) {
            if (!audObj.equals(audience)) return "BAD_AUDIENCE";
        } else if (audObj instanceof List) {
            boolean found = false;
            for (Object elem : (List<Object>) audObj) {
                if (audience.equals(elem)) { found = true; break; }
            }
            if (!found) return "BAD_AUDIENCE";
        } else {
            return "BAD_AUDIENCE";
        }

        // VALID
        String sub = (String) payload.get("sub");
        String scopeStr = (String) payload.get("scope");
        String scopes = "";
        if (scopeStr != null && !scopeStr.isEmpty()) {
            String[] sp = scopeStr.split(" ");
            LinkedHashSet<String> set = new LinkedHashSet<>();
            for (String p : sp) {
                if (!p.isEmpty()) set.add(p);
            }
            List<String> sorted = new ArrayList<>(set);
            sorted.sort(Comparator.naturalOrder());
            scopes = String.join(",", sorted);
        }

        return "VALID sub=" + sub + " scope=" + scopes;
    }
}

import java.io.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {

    // === JSON Value Model ===
    static abstract class JVal { }

    static class JNull extends JVal { }

    static class JBool extends JVal {
        final boolean value;
        JBool(boolean v) { value = v; }
    }

    static class JNum extends JVal {
        final double value;
        JNum(double v) { value = v; }
        boolean isInteger() { return value == Math.floor(value) && !Double.isInfinite(value); }
    }

    static class JStr extends JVal {
        final String value;
        JStr(String v) { value = v; }
        int cpLength() { return value.codePointCount(0, value.length()); }
    }

    static class JArr extends JVal {
        final List<JVal> elements;
        JArr(List<JVal> e) { elements = e; }
    }

    static class JObj extends JVal {
        final LinkedHashMap<String, JVal> members;
        JObj(LinkedHashMap<String, JVal> m) { members = m; }
    }

    // === Deep Equality ===
    static boolean deepEquals(JVal a, JVal b) {
        if (a instanceof JNull && b instanceof JNull) return true;
        if (a instanceof JBool && b instanceof JBool) return ((JBool)a).value == ((JBool)b).value;
        if (a instanceof JNum && b instanceof JNum) return ((JNum)a).value == ((JNum)b).value;
        if (a instanceof JStr && b instanceof JStr) return ((JStr)a).value.equals(((JStr)b).value);
        if (a instanceof JArr && b instanceof JArr) {
            List<JVal> ea = ((JArr)a).elements, eb = ((JArr)b).elements;
            if (ea.size() != eb.size()) return false;
            for (int i = 0; i < ea.size(); i++) if (!deepEquals(ea.get(i), eb.get(i))) return false;
            return true;
        }
        if (a instanceof JObj && b instanceof JObj) {
            LinkedHashMap<String, JVal> ma = ((JObj)a).members, mb = ((JObj)b).members;
            if (ma.size() != mb.size()) return false;
            for (Map.Entry<String, JVal> e : ma.entrySet()) {
                if (!mb.containsKey(e.getKey())) return false;
                if (!deepEquals(e.getValue(), mb.get(e.getKey()))) return false;
            }
            return true;
        }
        return false;
    }

    // === JSON Parser ===
    static class Parser {
        final String input;
        int pos;
        Parser(String s) { input = s; pos = 0; }

        JVal parse() { skipWS(); JVal v = parseValue(); skipWS(); return v; }

        void skipWS() { while (pos < input.length() && (input.charAt(pos)==' '||input.charAt(pos)=='\t'||input.charAt(pos)=='\n'||input.charAt(pos)=='\r')) pos++; }

        JVal parseValue() {
            skipWS();
            char c = input.charAt(pos);
            if (c=='n') { pos+=4; return new JNull(); }
            if (c=='t') { pos+=4; return new JBool(true); }
            if (c=='f') { pos+=5; return new JBool(false); }
            if (c=='"') return parseString();
            if (c=='[') return parseArray();
            if (c=='{') return parseObject();
            return parseNumber();
        }

        JStr parseString() {
            pos++; // skip "
            StringBuilder sb = new StringBuilder();
            while (input.charAt(pos) != '"') {
                char c = input.charAt(pos);
                if (c == '\\') {
                    pos++;
                    char e = input.charAt(pos);
                    switch (e) {
                        case '"': sb.append('"'); pos++; break;
                        case '\\': sb.append('\\'); pos++; break;
                        case '/': sb.append('/'); pos++; break;
                        case 'b': sb.append('\b'); pos++; break;
                        case 'f': sb.append('\f'); pos++; break;
                        case 'n': sb.append('\n'); pos++; break;
                        case 'r': sb.append('\r'); pos++; break;
                        case 't': sb.append('\t'); pos++; break;
                        case 'u': {
                            pos++;
                            int hi = parseHex4();
                            if (hi >= 0xD800 && hi <= 0xDBFF && pos + 1 < input.length() && input.charAt(pos)=='\\' && input.charAt(pos+1)=='u') {
                                pos += 2;
                                int lo = parseHex4();
                                if (lo >= 0xDC00 && lo <= 0xDFFF) {
                                    sb.append(Character.toChars(0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00)));
                                } else {
                                    sb.append((char)hi);
                                    sb.append((char)lo);
                                }
                            } else {
                                sb.append((char)hi);
                            }
                            break;
                        }
                        default: throw new RuntimeException("bad escape");
                    }
                } else {
                    sb.append(c); pos++;
                }
            }
            pos++; // skip closing "
            return new JStr(sb.toString());
        }

        int parseHex4() {
            int v = 0;
            for (int i = 0; i < 4; i++) {
                char c = input.charAt(pos++);
                if (c>='0'&&c<='9') v=v*16+(c-'0');
                else if (c>='a'&&c<='f') v=v*16+(c-'a'+10);
                else v=v*16+(c-'A'+10);
            }
            return v;
        }

        JNum parseNumber() {
            int start = pos;
            if (input.charAt(pos)=='-') pos++;
            if (input.charAt(pos)=='0') pos++;
            else while (pos<input.length()&&input.charAt(pos)>='0'&&input.charAt(pos)<='9') pos++;
            if (pos<input.length()&&input.charAt(pos)=='.') { pos++; while(pos<input.length()&&input.charAt(pos)>='0'&&input.charAt(pos)<='9') pos++; }
            if (pos<input.length()&&(input.charAt(pos)=='e'||input.charAt(pos)=='E')) { pos++; if(pos<input.length()&&(input.charAt(pos)=='+'||input.charAt(pos)=='-')) pos++; while(pos<input.length()&&input.charAt(pos)>='0'&&input.charAt(pos)<='9') pos++; }
            return new JNum(Double.parseDouble(input.substring(start, pos)));
        }

        JArr parseArray() {
            pos++;
            List<JVal> list = new ArrayList<>();
            skipWS();
            if (input.charAt(pos)==']') { pos++; return new JArr(list); }
            while (true) {
                list.add(parseValue());
                skipWS();
                if (input.charAt(pos)==',') { pos++; continue; }
                pos++; break;
            }
            return new JArr(list);
        }

        JObj parseObject() {
            pos++;
            LinkedHashMap<String, JVal> map = new LinkedHashMap<>();
            skipWS();
            if (input.charAt(pos)=='}') { pos++; return new JObj(map); }
            while (true) {
                skipWS();
                JStr key = parseString();
                skipWS();
                pos++; // skip :
                map.put(key.value, parseValue());
                skipWS();
                if (input.charAt(pos)==',') { pos++; continue; }
                pos++; break;
            }
            return new JObj(map);
        }
    }

    // === JSON Pointer Helpers ===
    static String escTok(String tok) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < tok.length(); i++) {
            char c = tok.charAt(i);
            if (c=='~') sb.append("~0");
            else if (c=='/') sb.append("~1");
            else sb.append(c);
        }
        return sb.toString();
    }

    static String ptr(String base, String token) { return base + "/" + escTok(token); }

    static String decodeTok(String tok) { return tok.replace("~1","/").replace("~0","~"); }

    // === Error ===
    static class Err implements Comparable<Err> {
        final String il, sl;
        Err(String i, String s) { il=i; sl=s; }
        public int compareTo(Err o) {
            int c = cmpCP(this.il, o.il);
            return c != 0 ? c : cmpCP(this.sl, o.sl);
        }
    }

    static int cmpCP(String a, String b) {
        int i=0, j=0;
        while (i<a.length() && j<b.length()) {
            int ca=a.codePointAt(i), cb=b.codePointAt(j);
            if (ca!=cb) return Integer.compare(ca,cb);
            i+=Character.charCount(ca); j+=Character.charCount(cb);
        }
        if (i<a.length()) return 1;
        if (j<b.length()) return -1;
        return 0;
    }

    // === Validator ===
    static JVal rootSchema;

    static void validate(JVal inst, JVal schema, String il, String sl, Set<Err> errs) {
        if (schema instanceof JBool) {
            if (!((JBool)schema).value) errs.add(new Err(il, sl));
            return;
        }
        JObj obj = (JObj) schema;

        // type
        if (obj.members.containsKey("type")) {
            if (!checkType(inst, obj.members.get("type")))
                errs.add(new Err(il, sl + "/type"));
        }

        // enum
        if (obj.members.containsKey("enum")) {
            JArr ea = (JArr) obj.members.get("enum");
            boolean found = false;
            for (JVal e : ea.elements) if (deepEquals(inst, e)) { found=true; break; }
            if (!found) errs.add(new Err(il, sl + "/enum"));
        }

        // const
        if (obj.members.containsKey("const")) {
            if (!deepEquals(inst, obj.members.get("const")))
                errs.add(new Err(il, sl + "/const"));
        }

        // number keywords
        if (inst instanceof JNum) {
            double v = ((JNum)inst).value;
            if (obj.members.containsKey("minimum")) { if (!(v >= ((JNum)obj.members.get("minimum")).value)) errs.add(new Err(il, sl+"/minimum")); }
            if (obj.members.containsKey("maximum")) { if (!(v <= ((JNum)obj.members.get("maximum")).value)) errs.add(new Err(il, sl+"/maximum")); }
            if (obj.members.containsKey("exclusiveMinimum")) { if (!(v > ((JNum)obj.members.get("exclusiveMinimum")).value)) errs.add(new Err(il, sl+"/exclusiveMinimum")); }
            if (obj.members.containsKey("exclusiveMaximum")) { if (!(v < ((JNum)obj.members.get("exclusiveMaximum")).value)) errs.add(new Err(il, sl+"/exclusiveMaximum")); }
        }

        // string keywords
        if (inst instanceof JStr) {
            int len = ((JStr)inst).cpLength();
            if (obj.members.containsKey("minLength")) { if (!(len >= (int)((JNum)obj.members.get("minLength")).value)) errs.add(new Err(il, sl+"/minLength")); }
            if (obj.members.containsKey("maxLength")) { if (!(len <= (int)((JNum)obj.members.get("maxLength")).value)) errs.add(new Err(il, sl+"/maxLength")); }
        }

        // array keywords
        if (inst instanceof JArr) {
            List<JVal> elems = ((JArr)inst).elements;
            int cnt = elems.size();
            if (obj.members.containsKey("minItems")) { if (!(cnt >= (int)((JNum)obj.members.get("minItems")).value)) errs.add(new Err(il, sl+"/minItems")); }
            if (obj.members.containsKey("maxItems")) { if (!(cnt <= (int)((JNum)obj.members.get("maxItems")).value)) errs.add(new Err(il, sl+"/maxItems")); }
            if (obj.members.containsKey("uniqueItems") && ((JBool)obj.members.get("uniqueItems")).value) {
                boolean uniq = true;
                outer: for (int i=0;i<cnt;i++) for (int j=i+1;j<cnt;j++) if (deepEquals(elems.get(i),elems.get(j))) { uniq=false; break outer; }
                if (!uniq) errs.add(new Err(il, sl+"/uniqueItems"));
            }
            int prefixLen = 0;
            if (obj.members.containsKey("prefixItems")) {
                JArr pi = (JArr) obj.members.get("prefixItems");
                prefixLen = pi.elements.size();
                for (int i=0;i<prefixLen&&i<cnt;i++)
                    validate(elems.get(i), pi.elements.get(i), il+"/"+i, sl+"/prefixItems/"+i, errs);
            }
            if (obj.members.containsKey("items")) {
                JVal is = obj.members.get("items");
                for (int i=prefixLen;i<cnt;i++)
                    validate(elems.get(i), is, il+"/"+i, sl+"/items", errs);
            }
        }

        // object keywords
        if (inst instanceof JObj) {
            LinkedHashMap<String,JVal> im = ((JObj)inst).members;
            JVal propsVal = obj.members.get("properties");
            if (propsVal != null) {
                LinkedHashMap<String,JVal> ps = ((JObj)propsVal).members;
                for (Map.Entry<String,JVal> e : ps.entrySet()) {
                    if (im.containsKey(e.getKey()))
                        validate(im.get(e.getKey()), e.getValue(), ptr(il, e.getKey()), ptr(ptr(sl,"properties"), e.getKey()), errs);
                }
            }
            if (obj.members.containsKey("required")) {
                JArr req = (JArr) obj.members.get("required");
                for (int j=0;j<req.elements.size();j++) {
                    String nm = ((JStr)req.elements.get(j)).value;
                    if (!im.containsKey(nm)) errs.add(new Err(il, sl+"/required/"+j));
                }
            }
            if (obj.members.containsKey("additionalProperties")) {
                JVal addS = obj.members.get("additionalProperties");
                Set<String> pk = new HashSet<>();
                if (propsVal != null) pk = ((JObj)propsVal).members.keySet();
                for (Map.Entry<String,JVal> e : im.entrySet()) {
                    if (!pk.contains(e.getKey()))
                        validate(e.getValue(), addS, ptr(il, e.getKey()), sl+"/additionalProperties", errs);
                }
            }
            if (obj.members.containsKey("minProperties")) { if (!(im.size() >= (int)((JNum)obj.members.get("minProperties")).value)) errs.add(new Err(il, sl+"/minProperties")); }
            if (obj.members.containsKey("maxProperties")) { if (!(im.size() <= (int)((JNum)obj.members.get("maxProperties")).value)) errs.add(new Err(il, sl+"/maxProperties")); }
        }

        // applicators
        if (obj.members.containsKey("allOf")) {
            JArr ao = (JArr) obj.members.get("allOf");
            for (int i=0;i<ao.elements.size();i++)
                validate(inst, ao.elements.get(i), il, sl+"/allOf/"+i, errs);
        }
        if (obj.members.containsKey("anyOf")) {
            JArr ao = (JArr) obj.members.get("anyOf");
            boolean any = false;
            for (JVal s : ao.elements) if (accepts(inst, s)) { any=true; break; }
            if (!any) errs.add(new Err(il, sl+"/anyOf"));
        }
        if (obj.members.containsKey("oneOf")) {
            JArr oo = (JArr) obj.members.get("oneOf");
            int c = 0;
            for (JVal s : oo.elements) if (accepts(inst, s)) c++;
            if (c != 1) errs.add(new Err(il, sl+"/oneOf"));
        }
        if (obj.members.containsKey("not")) {
            if (accepts(inst, obj.members.get("not"))) errs.add(new Err(il, sl+"/not"));
        }
        if (obj.members.containsKey("if")) {
            boolean ifOk = accepts(inst, obj.members.get("if"));
            if (ifOk && obj.members.containsKey("then"))
                validate(inst, obj.members.get("then"), il, sl+"/then", errs);
            if (!ifOk && obj.members.containsKey("else"))
                validate(inst, obj.members.get("else"), il, sl+"/else", errs);
        }
        if (obj.members.containsKey("$ref")) {
            String ref = ((JStr)obj.members.get("$ref")).value;
            JVal refSchema;
            String refLoc;
            if (ref.equals("#")) {
                refSchema = rootSchema;
                refLoc = "#";
            } else {
                String enc = ref.substring(8); // after "#/$defs/"
                String name = decodeTok(enc);
                refSchema = ((JObj)((JObj)rootSchema).members.get("$defs")).members.get(name);
                refLoc = "#/$defs/" + escTok(name);
            }
            validate(inst, refSchema, il, refLoc, errs);
        }
    }

    static boolean accepts(JVal inst, JVal schema) {
        Set<Err> tmp = new HashSet<>();
        validate(inst, schema, "#", "#", tmp);
        return tmp.isEmpty();
    }

    static boolean checkType(JVal inst, JVal tv) {
        if (tv instanceof JStr) return typeMatch(inst, ((JStr)tv).value);
        if (tv instanceof JArr) { for (JVal t : ((JArr)tv).elements) if (typeMatch(inst, ((JStr)t).value)) return true; return false; }
        return true;
    }

    static boolean typeMatch(JVal inst, String tn) {
        switch (tn) {
            case "null": return inst instanceof JNull;
            case "boolean": return inst instanceof JBool;
            case "object": return inst instanceof JObj;
            case "array": return inst instanceof JArr;
            case "number": return inst instanceof JNum;
            case "string": return inst instanceof JStr;
            case "integer": return inst instanceof JNum && ((JNum)inst).isInteger();
            default: return true;
        }
    }

    // === Main ===
    public static void main(String[] args) throws Exception {
        String dir = args[0];
        byte[] sb = Files.readAllBytes(Paths.get(dir, "schema.json"));
        byte[] ib = Files.readAllBytes(Paths.get(dir, "instances.json"));
        rootSchema = new Parser(new String(sb, StandardCharsets.UTF_8)).parse();
        JArr instances = (JArr) new Parser(new String(ib, StandardCharsets.UTF_8)).parse();

        int vc=0, ic=0;
        StringBuilder out = new StringBuilder();
        for (int n=0; n<instances.elements.size(); n++) {
            TreeSet<Err> errs = new TreeSet<>();
            validate(instances.elements.get(n), rootSchema, "#", "#", errs);
            if (errs.isEmpty()) {
                out.append(n).append(": valid\n");
                vc++;
            } else {
                out.append(n).append(": invalid (").append(errs.size()).append(")\n");
                for (Err e : errs) out.append("  ").append(e.il).append(" ").append(e.sl).append("\n");
                ic++;
            }
        }
        out.append("valid=").append(vc).append(" invalid=").append(ic).append("\n");
        System.out.print(out.toString());
    }
}

import Foundation
import CommonCrypto

func isValidBase64url(_ s: String) -> Bool {
    if s.isEmpty { return false }
    for ch in s.unicodeScalars {
        let v = ch.value
        if !((v >= 65 && v <= 90) || (v >= 97 && v <= 122) || (v >= 48 && v <= 57) || v == 45 || v == 95) {
            return false
        }
    }
    if s.count % 4 == 1 { return false }
    return true
}

func decodeBase64url(_ s: String) -> Data? {
    var base64 = s.replacingOccurrences(of: "-", with: "+")
    base64 = base64.replacingOccurrences(of: "_", with: "/")
    let remainder = base64.count % 4
    if remainder == 2 { base64 += "==" }
    else if remainder == 3 { base64 += "=" }
    return Data(base64Encoded: base64)
}

func computeHMAC(algorithm: String, key: Data, data: Data) -> Data {
    let alg: CCHmacAlgorithm
    let hashLen: Int
    switch algorithm {
    case "HS256":
        alg = CCHmacAlgorithm(kCCHmacAlgSHA256)
        hashLen = Int(CC_SHA256_DIGEST_LENGTH)
    case "HS384":
        alg = CCHmacAlgorithm(kCCHmacAlgSHA384)
        hashLen = Int(CC_SHA384_DIGEST_LENGTH)
    case "HS512":
        alg = CCHmacAlgorithm(kCCHmacAlgSHA512)
        hashLen = Int(CC_SHA512_DIGEST_LENGTH)
    default:
        return Data()
    }
    var hash = [UInt8](repeating: 0, count: hashLen)
    CCHmac(alg, key, key.count, data, data.count, &hash)
    return Data(hash)
}

func checkToken(_ token: String, now: Double, leeway: Double, issuer: String, audience: String, keySet: [String: (alg: String, k: Data)]) -> String {
    // Rule 1: MALFORMED
    let segments = token.components(separatedBy: ".")
    guard segments.count == 3 else { return "MALFORMED" }
    guard !segments[0].isEmpty && !segments[1].isEmpty && !segments[2].isEmpty else { return "MALFORMED" }
    guard isValidBase64url(segments[0]) && isValidBase64url(segments[1]) && isValidBase64url(segments[2]) else { return "MALFORMED" }

    guard let headerData = decodeBase64url(segments[0]) else { return "MALFORMED" }
    guard let payloadData = decodeBase64url(segments[1]) else { return "MALFORMED" }

    guard let header = try? JSONSerialization.jsonObject(with: headerData) as? [String: Any] else { return "MALFORMED" }
    guard let payload = try? JSONSerialization.jsonObject(with: payloadData) as? [String: Any] else { return "MALFORMED" }

    // Rule 2: UNSUPPORTED_ALG
    guard let alg = header["alg"] as? String else { return "UNSUPPORTED_ALG" }
    guard alg == "HS256" || alg == "HS384" || alg == "HS512" else { return "UNSUPPORTED_ALG" }

    // Rule 3: UNKNOWN_KEY
    guard let kid = header["kid"] as? String else { return "UNKNOWN_KEY" }
    guard let keyInfo = keySet[kid] else { return "UNKNOWN_KEY" }

    // Rule 4: ALG_MISMATCH
    guard keyInfo.alg == alg else { return "ALG_MISMATCH" }

    // Rule 5: BAD_SIGNATURE
    let signingInput = "\(segments[0]).\(segments[1])"
    guard let signingInputData = signingInput.data(using: .ascii) else { return "BAD_SIGNATURE" }
    let expectedSig = computeHMAC(algorithm: alg, key: keyInfo.k, data: signingInputData)
    guard let actualSig = decodeBase64url(segments[2]) else { return "BAD_SIGNATURE" }
    guard actualSig == expectedSig else { return "BAD_SIGNATURE" }

    // Rule 6: EXPIRED
    if let exp = payload["exp"] as? Double {
        if now >= exp + leeway { return "EXPIRED" }
    }

    // Rule 7: NOT_YET_VALID
    if let nbf = payload["nbf"] as? Double {
        if now + leeway < nbf { return "NOT_YET_VALID" }
    }

    // Rule 8: BAD_ISSUER
    guard let iss = payload["iss"] as? String, iss == issuer else { return "BAD_ISSUER" }

    // Rule 9: BAD_AUDIENCE
    var audValid = false
    if let aud = payload["aud"] {
        if let audStr = aud as? String {
            audValid = (audStr == audience)
        } else if let audArr = aud as? [Any] {
            audValid = audArr.contains(where: { ($0 as? String) == audience })
        }
    }
    guard audValid else { return "BAD_AUDIENCE" }

    // VALID
    let sub = payload["sub"] as? String ?? ""
    let scopeStr = payload["scope"] as? String ?? ""
    let pieces = scopeStr.components(separatedBy: " ").filter { !$0.isEmpty }
    var seen = Set<String>()
    var uniqueScopes: [String] = []
    for s in pieces {
        if !seen.contains(s) {
            seen.insert(s)
            uniqueScopes.append(s)
        }
    }
    uniqueScopes.sort { $0.unicodeScalars.lexicographicallyPrecedes($1.unicodeScalars) }
    let scopesStr = uniqueScopes.joined(separator: ",")

    return "VALID sub=\(sub) scope=\(scopesStr)"
}

// Main
let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]

let configPath = dir + "/config.json"
guard let configData = FileManager.default.contents(atPath: configPath) else { exit(1) }
guard let config = try? JSONSerialization.jsonObject(with: configData) as? [String: Any] else { exit(1) }

let now = (config["now"] as? NSNumber)?.doubleValue ?? 0
let leeway = (config["leeway"] as? NSNumber)?.doubleValue ?? 0
let issuer = config["issuer"] as? String ?? ""
let audience = config["audience"] as? String ?? ""

var keySet: [String: (alg: String, k: Data)] = [:]
if let keys = config["keys"] as? [[String: Any]] {
    for key in keys {
        let kid = key["kid"] as? String ?? ""
        let alg = key["alg"] as? String ?? ""
        let kStr = key["k"] as? String ?? ""
        let kData = decodeBase64url(kStr) ?? Data()
        keySet[kid] = (alg: alg, k: kData)
    }
}

let tokensPath = dir + "/tokens.txt"
guard let tokensData = FileManager.default.contents(atPath: tokensPath) else { exit(1) }
let tokensContent = String(data: tokensData, encoding: .utf8) ?? ""
let lines = tokensContent.components(separatedBy: "\n")

var validCount = 0
var invalidCount = 0
var lineNumber = 0

for line in lines {
    let trimmed = line.trimmingCharacters(in: .whitespaces)
    if trimmed.isEmpty { continue }
    lineNumber += 1
    let n = lineNumber

    let result = checkToken(trimmed, now: now, leeway: leeway, issuer: issuer, audience: audience, keySet: keySet)
    print("\(n): \(result)")
    if result.hasPrefix("VALID") {
        validCount += 1
    } else {
        invalidCount += 1
    }
}

