import Foundation
import CommonCrypto

func isValidBase64url(_ s: String) -> Bool {
    if s.isEmpty { return false }
    for ch in s.unicodeScalars {
        let v = ch.value
        if !((v >= 65 && v <= 90) || (v >= 97 && v <= 122) || (v >= 48 && v <= 57) || v == 45 || v == 95) {
            return false
        }
    }
    if s.count % 4 == 1 { return false }
    return true
}

func decodeBase64url(_ s: String) -> Data? {
    var base64 = s.replacingOccurrences(of: "-", with: "+")
    base64 = base64.replacingOccurrences(of: "_", with: "/")
    let remainder = base64.count % 4
    if remainder == 2 { base64 += "==" }
    else if remainder == 3 { base64 += "=" }
    return Data(base64Encoded: base64)
}

func computeHMAC(algorithm: String, key: Data, data: Data) -> Data {
    let alg: CCHmacAlgorithm
    let hashLen: Int
    switch algorithm {
    case "HS256":
        alg = CCHmacAlgorithm(kCCHmacAlgSHA256)
        hashLen = Int(CC_SHA256_DIGEST_LENGTH)
    case "HS384":
        alg = CCHmacAlgorithm(kCCHmacAlgSHA384)
        hashLen = Int(CC_SHA384_DIGEST_LENGTH)
    case "HS512":
        alg = CCHmacAlgorithm(kCCHmacAlgSHA512)
        hashLen = Int(CC_SHA512_DIGEST_LENGTH)
    default:
        return Data()
    }
    var hash = [UInt8](repeating: 0, count: hashLen)
    let keyBytes = [UInt8](key)
    let dataBytes = [UInt8](data)
    CCHmac(alg, keyBytes, keyBytes.count, dataBytes, dataBytes.count, &hash)
    return Data(hash)
}

func checkToken(_ token: String, now: Double, leeway: Double, issuer: String, audience: String, keySet: [String: (alg: String, k: Data)]) -> String {
    // Rule 1: MALFORMED
    let segments = token.components(separatedBy: ".")
    guard segments.count == 3 else { return "MALFORMED" }
    guard !segments[0].isEmpty && !segments[1].isEmpty && !segments[2].isEmpty else { return "MALFORMED" }
    guard isValidBase64url(segments[0]) && isValidBase64url(segments[1]) && isValidBase64url(segments[2]) else { return "MALFORMED" }

    guard let headerData = decodeBase64url(segments[0]) else { return "MALFORMED" }
    guard let payloadData = decodeBase64url(segments[1]) else { return "MALFORMED" }

    guard let header = try? JSONSerialization.jsonObject(with: headerData) as? [String: Any] else { return "MALFORMED" }
    guard let payload = try? JSONSerialization.jsonObject(with: payloadData) as? [String: Any] else { return "MALFORMED" }

    // Rule 2: UNSUPPORTED_ALG
    guard let alg = header["alg"] as? String else { return "UNSUPPORTED_ALG" }
    guard alg == "HS256" || alg == "HS384" || alg == "HS512" else { return "UNSUPPORTED_ALG" }

    // Rule 3: UNKNOWN_KEY
    guard let kid = header["kid"] as? String else { return "UNKNOWN_KEY" }
    guard let keyInfo = keySet[kid] else { return "UNKNOWN_KEY" }

    // Rule 4: ALG_MISMATCH
    guard keyInfo.alg == alg else { return "ALG_MISMATCH" }

    // Rule 5: BAD_SIGNATURE
    let signingInput = "\(segments[0]).\(segments[1])"
    guard let signingInputData = signingInput.data(using: .ascii) else { return "BAD_SIGNATURE" }
    let expectedSig = computeHMAC(algorithm: alg, key: keyInfo.k, data: signingInputData)
    guard let actualSig = decodeBase64url(segments[2]) else { return "BAD_SIGNATURE" }
    guard actualSig == expectedSig else { return "BAD_SIGNATURE" }

    // Rule 6: EXPIRED
    if let exp = payload["exp"] as? Double {
        if now >= exp + leeway { return "EXPIRED" }
    }

    // Rule 7: NOT_YET_VALID
    if let nbf = payload["nbf"] as? Double {
        if now + leeway < nbf { return "NOT_YET_VALID" }
    }

    // Rule 8: BAD_ISSUER
    guard let iss = payload["iss"] as? String, iss == issuer else { return "BAD_ISSUER" }

    // Rule 9: BAD_AUDIENCE
    var audValid = false
    if let aud = payload["aud"] {
        if let audStr = aud as? String {
            audValid = (audStr == audience)
        } else if let audArr = aud as? [Any] {
            audValid = audArr.contains(where: { ($0 as? String) == audience })
        }
    }
    guard audValid else { return "BAD_AUDIENCE" }

    // VALID
    let sub = payload["sub"] as? String ?? ""
    let scopeStr = payload["scope"] as? String ?? ""
    let pieces = scopeStr.components(separatedBy: " ").filter { !$0.isEmpty }
    var seen = Set<String>()
    var uniqueScopes: [String] = []
    for s in pieces {
        if !seen.contains(s) {
            seen.insert(s)
            uniqueScopes.append(s)
        }
    }
    uniqueScopes.sort { $0.unicodeScalars.lexicographicallyPrecedes($1.unicodeScalars) }
    let scopesStr = uniqueScopes.joined(separator: ",")

    return "VALID sub=\(sub) scope=\(scopesStr)"
}

// Main
let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]

let configPath = dir + "/config.json"
guard let configData = FileManager.default.contents(atPath: configPath) else { exit(1) }
guard let config = try? JSONSerialization.jsonObject(with: configData) as? [String: Any] else { exit(1) }

let now = (config["now"] as? NSNumber)?.doubleValue ?? 0
let leeway = (config["leeway"] as? NSNumber)?.doubleValue ?? 0
let issuer = config["issuer"] as? String ?? ""
let audience = config["audience"] as? String ?? ""

var keySet: [String: (alg: String, k: Data)] = [:]
if let keys = config["keys"] as? [[String: Any]] {
    for key in keys {
        let kid = key["kid"] as? String ?? ""
        let alg = key["alg"] as? String ?? ""
        let kStr = key["k"] as? String ?? ""
        let kData = decodeBase64url(kStr) ?? Data()
        keySet[kid] = (alg: alg, k: kData)
    }
}

let tokensPath = dir + "/tokens.txt"
guard let tokensData = FileManager.default.contents(atPath: tokensPath) else { exit(1) }
let tokensContent = String(data: tokensData, encoding: .utf8) ?? ""
let lines = tokensContent.components(separatedBy: "\n")

var validCount = 0
var invalidCount = 0
var lineNumber = 0

for line in lines {
    let trimmed = line.trimmingCharacters(in: .whitespaces)
    if trimmed.isEmpty { continue }
    lineNumber += 1
    let n = lineNumber

    let result = checkToken(trimmed, now: now, leeway: leeway, issuer: issuer, audience: audience, keySet: keySet)
    print("\(n): \(result)")
    if result.hasPrefix("VALID") {
        validCount += 1
    } else {
        invalidCount += 1
    }
}

print("")
print("valid=\(validCount) invalid=\(invalidCount)")

import Foundation

// MARK: - JSON Value

enum JSONValue {
    case null
    case bool(Bool)
    case number(Double)
    case string(String)
    case array([JSONValue])
    case object([(String, JSONValue)])
}

// MARK: - JSON Parser

struct JSONParser {
    let chars: [Character]
    var pos: Int

    init(_ input: String) {
        chars = Array(input)
        pos = 0
    }

    mutating func parse() -> JSONValue {
        skipWS()
        let v = parseValue()
        return v
    }

    mutating func skipWS() {
        while pos < chars.count {
            let c = chars[pos]
            if c == " " || c == "\t" || c == "\n" || c == "\r" { pos += 1 }
            else { break }
        }
    }

    mutating func parseValue() -> JSONValue {
        skipWS()
        guard pos < chars.count else { return .null }
        let c = chars[pos]
        switch c {
        case "{": return parseObject()
        case "[": return parseArray()
        case "\"": return .string(parseString())
        case "t": pos += 4; return .bool(true)
        case "f": pos += 5; return .bool(false)
        case "n": pos += 4; return .null
        default: return parseNumber()
        }
    }

    mutating func parseObject() -> JSONValue {
        pos += 1
        skipWS()
        var members: [(String, JSONValue)] = []
        if pos < chars.count && chars[pos] != "}" {
            while true {
                skipWS()
                let key = parseString()
                skipWS()
                pos += 1 // colon
                let val = parseValue()
                members.append((key, val))
                skipWS()
                if pos < chars.count && chars[pos] == "," {
                    pos += 1
                } else {
                    break
                }
            }
        }
        if pos < chars.count && chars[pos] == "}" { pos += 1 }
        return .object(members)
    }

    mutating func parseArray() -> JSONValue {
        pos += 1
        skipWS()
        var elements: [JSONValue] = []
        if pos < chars.count && chars[pos] != "]" {
            while true {
                let val = parseValue()
                elements.append(val)
                skipWS()
                if pos < chars.count && chars[pos] == "," {
                    pos += 1
                } else {
                    break
                }
            }
        }
        if pos < chars.count && chars[pos] == "]" { pos += 1 }
        return .array(elements)
    }

    mutating func parseString() -> String {
        pos += 1 // opening quote
        var result = ""
        while pos < chars.count && chars[pos] != "\"" {
            if chars[pos] == "\\" {
                pos += 1
                guard pos < chars.count else { break }
                let c = chars[pos]
                switch c {
                case "\"": result.append("\"")
                case "\\": result.append("\\")
                case "/": result.append("/")
                case "b": result.append("\u{08}")
                case "f": result.append("\u{0C}")
                case "n": result.append("\n")
                case "r": result.append("\r")
                case "t": result.append("\t")
                case "u":
                    pos += 1
                    let cp = parseHex4()
                    if cp >= 0xD800 && cp <= 0xDBFF && pos + 1 < chars.count && chars[pos] == "\\" && chars[pos+1] == "u" {
                        pos += 2
                        let low = parseHex4()
                        let full = 0x10000 + (cp - 0xD800) * 0x400 + (low - 0xDC00)
                        if let scalar = UnicodeScalar(full) {
                            result.append(Character(scalar))
                        }
                    } else {
                        if let scalar = UnicodeScalar(cp) {
                            result.append(Character(scalar))
                        }
                    }
                default:
                    result.append(c)
                }
            } else {
                result.append(chars[pos])
            }
            pos += 1
        }
        if pos < chars.count && chars[pos] == "\"" { pos += 1 }
        return result
    }

    mutating func parseHex4() -> Int {
        var value = 0
        for _ in 0..<4 {
            guard pos < chars.count else { break }
            value *= 16
            let c = chars[pos]
            if c >= "0" && c <= "9" { value += Int(c.asciiValue! - 48) }
            else if c >= "a" && c <= "f" { value += Int(c.asciiValue! - 97 + 10) }
            else if c >= "A" && c <= "F" { value += Int(c.asciiValue! - 65 + 10) }
            pos += 1
        }
        return value
    }

    mutating func parseNumber() -> JSONValue {
        let start = pos
        if pos < chars.count && chars[pos] == "-" { pos += 1 }
        while pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" { pos += 1 }
        if pos < chars.count && chars[pos] == "." {
            pos += 1
            while pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" { pos += 1 }
        }
        if pos < chars.count && (chars[pos] == "e" || chars[pos] == "E") {
            pos += 1
            if pos < chars.count && (chars[pos] == "+" || chars[pos] == "-") { pos += 1 }
            while pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" { pos += 1 }
        }
        let str = String(chars[start..<pos])
        return .number(Double(str) ?? 0)
    }
}

// MARK: - JSON Pointer

func escapeToken(_ token: String) -> String {
    var result = ""
    for c in token {
        if c == "~" { result += "~0" }
        else if c == "/" { result += "~1" }
        else { result.append(c) }
    }
    return result
}

func unescapeToken(_ token: String) -> String {
    var result = ""
    var i = token.startIndex
    while i < token.endIndex {
        if token[i] == "~" {
            let next = token.index(after: i)
            if next < token.endIndex {
                if token[next] == "0" {
                    result.append("~")
                    i = token.index(after: next)
                    continue
                } else if token[next] == "1" {
                    result.append("/")
                    i = token.index(after: next)
                    continue
                }
            }
        }
        result.append(token[i])
        i = token.index(after: i)
    }
    return result
}

func pointerStr(_ tokens: [String]) -> String {
    if tokens.isEmpty { return "#" }
    var s = "#"
    for t in tokens {
        s += "/" + escapeToken(t)
    }
    return s
}

// MARK: - Deep Equality

func deepEqual(_ a: JSONValue, _ b: JSONValue) -> Bool {
    switch (a, b) {
    case (.null, .null): return true
    case (.bool(let x), .bool(let y)): return x == y
    case (.number(let x), .number(let y)): return x == y
    case (.string(let x), .string(let y)): return x == y
    case (.array(let x), .array(let y)):
        if x.count != y.count { return false }
        for i in 0..<x.count {
            if !deepEqual(x[i], y[i]) { return false }
        }
        return true
    case (.object(let x), .object(let y)):
        if x.count != y.count { return false }
        for (kx, vx) in x {
            var found = false
            for (ky, vy) in y {
                if kx == ky {
                    if !deepEqual(vx, vy) { return false }
                    found = true
                    break
                }
            }
            if !found { return false }
        }
        return true
    default: return false
    }
}

// MARK: - Helpers

func getMember(_ obj: [(String, JSONValue)], _ key: String) -> JSONValue? {
    for (k, v) in obj {
        if k == key { return v }
    }
    return nil
}

func isInteger(_ n: Double) -> Bool {
    return n == n.rounded()
}

// MARK: - Type Check

func checkType(instance: JSONValue, typeVal: JSONValue) -> Bool {
    var typeNames: [String] = []
    if case .string(let t) = typeVal {
        typeNames = [t]
    } else if case .array(let arr) = typeVal {
        for item in arr {
            if case .string(let t) = item { typeNames.append(t) }
        }
    } else {
        return true
    }
    for name in typeNames {
        switch name {
        case "null": if case .null = instance { return true }
        case "boolean": if case .bool = instance { return true }
        case "number": if case .number = instance { return true }
        case "integer": if case .number(let n) = instance { if isInteger(n) { return true } }
        case "string": if case .string = instance { return true }
        case "array": if case .array = instance { return true }
        case "object": if case .object = instance { return true }
        default: break
        }
    }
    return false
}

// MARK: - Ref Resolution

func resolveRef(ref: String, rootSchema: JSONValue) -> JSONValue? {
    if ref == "#" { return rootSchema }
    guard ref.hasPrefix("#/$defs/") else { return nil }
    let remaining = String(ref.dropFirst("#/$defs/".count))
    let token = unescapeToken(remaining)
    guard case .object(let rootMembers) = rootSchema else { return nil }
    guard let defs = getMember(rootMembers, "$defs") else { return nil }
    guard case .object(let defsMembers) = defs else { return nil }
    return getMember(defsMembers, token)
}

func refSchemaLoc(ref: String) -> [String] {
    if ref == "#" { return [] }
    guard ref.hasPrefix("#/$defs/") else { return [] }
    let remaining = String(ref.dropFirst("#/$defs/".count))
    let token = unescapeToken(remaining)
    return ["$defs", token]
}

// MARK: - Validation

func validate(instance: JSONValue, schema: JSONValue, instanceLoc: [String], schemaLoc: [String], rootSchema: JSONValue) -> Set<(String, String)> {
    var errors = Set<(String, String)>()

    // Boolean schema
    if case .bool(let b) = schema {
        if !b {
            errors.insert((pointerStr(instanceLoc), pointerStr(schemaLoc)))
        }
        return errors
    }

    guard case .object(let members) = schema else { return errors }

    func kw(_ name: String) -> JSONValue? {
        return getMember(members, name)
    }

    // --- Any type keywords ---

    // type
    if let typeVal = kw("type") {
        if !checkType(instance: instance, typeVal: typeVal) {
            errors.insert((pointerStr(instanceLoc), pointerStr(schemaLoc + ["type"])))
        }
    }

    // enum
    if let enumVal = kw("enum"), case .array(let items) = enumVal {
        var found = false
        for item in items {
            if deepEqual(instance, item) { found = true; break }
        }
        if !found {
            errors.insert((pointerStr(instanceLoc), pointerStr(schemaLoc + ["enum"])))
        }
    }

    // const
    if let constVal = kw("const") {
        if !deepEqual(instance, constVal) {
            errors.insert((pointerStr(instanceLoc), pointerStr(schemaLoc + ["const"])))
        }
    }

    // --- Number keywords ---
    if case .number(let num) = instance {
        if let v = kw("minimum"), case .number(let val) = v {
            if num < val {
                errors.insert((pointerStr(instanceLoc), pointerStr(schemaLoc + ["minimum"])))
            }
        }
        if let v = kw("maximum"), case .number(let val) = v {
            if num > val {
                errors.insert((pointerStr(instanceLoc), pointerStr(schemaLoc + ["maximum"])))
            }
        }
        if let v = kw("exclusiveMinimum"), case .number(let val) = v {
            if num <= val {
                errors.insert((pointerStr(instanceLoc), pointerStr(schemaLoc + ["exclusiveMinimum"])))
            }
        }
        if let v = kw("exclusiveMaximum"), case .number(let val) = v {
            if num >= val {
                errors.insert((pointerStr(instanceLoc), pointerStr(schemaLoc + ["exclusiveMaximum"])))
            }
        }
    }

    // --- String keywords ---
    if case .string(let str) = instance {
        let len = str.unicodeScalars.count
        if let v = kw("minLength"), case .number(let val) = v {
            if Double(len) < val {
                errors.insert((pointerStr(instanceLoc), pointerStr(schemaLoc + ["minLength"])))
            }
        }
        if let v = kw("maxLength"), case .number(let val) = v {
            if Double(len) > val {
                errors.insert((pointerStr(instanceLoc), pointerStr(schemaLoc + ["maxLength"])))
            }
        }
    }

    // --- Array keywords ---
    if case .array(let arr) = instance {
        if let v = kw("minItems"), case .number(let val) = v {
            if Double(arr.count) < val {
                errors.insert((pointerStr(instanceLoc), pointerStr(schemaLoc + ["minItems"])))
            }
        }
        if let v = kw("maxItems"), case .number(let val) = v {
            if Double(arr.count) > val {
                errors.insert((pointerStr(instanceLoc), pointerStr(schemaLoc + ["maxItems"])))
            }
        }
        if let v = kw("uniqueItems"), case .bool(let u) = v, u {
            var hasDup = false
            outer: for i in 0..<arr.count {
                for j in (i+1)..<arr.count {
                    if deepEqual(arr[i], arr[j]) { hasDup = true; break outer }
                }
            }
            if hasDup {
                errors.insert((pointerStr(instanceLoc), pointerStr(schemaLoc + ["uniqueItems"])))
            }
        }

        // prefixItems
        var prefixLen = 0
        if let pv = kw("prefixItems"), case .array(let schemas) = pv {
            prefixLen = schemas.count
            for i in 0..<min(arr.count, schemas.count) {
                let sub = validate(instance: arr[i], schema: schemas[i],
                    instanceLoc: instanceLoc + [String(i)],
                    schemaLoc: schemaLoc + ["prefixItems", String(i)],
                    rootSchema: rootSchema)
                errors.formUnion(sub)
            }
        }

        // items
        if let itemsSchema = kw("items") {
            let startIdx = prefixLen
            for i in startIdx..<arr.count {
                let sub = validate(instance: arr[i], schema: itemsSchema,
                    instanceLoc: instanceLoc + [String(i)],
                    schemaLoc: schemaLoc + ["items"],
                    rootSchema: rootSchema)
                errors.formUnion(sub)
            }
        }
    }

    // --- Object keywords ---
    if case .object(let objMembers) = instance {
        if let v = kw("minProperties"), case .number(let val) = v {
            if Double(objMembers.count) < val {
                errors.insert((pointerStr(instanceLoc), pointerStr(schemaLoc + ["minProperties"])))
            }
        }
        if let v = kw("maxProperties"), case .number(let val) = v {
            if Double(objMembers.count) > val {
                errors.insert((pointerStr(instanceLoc), pointerStr(schemaLoc + ["maxProperties"])))
            }
        }

        // required
        if let rv = kw("required"), case .array(let reqItems) = rv {
            for (j, reqItem) in reqItems.enumerated() {
                if case .string(let name) = reqItem {
                    if getMember(objMembers, name) == nil {
                        errors.insert((pointerStr(instanceLoc), pointerStr(schemaLoc + ["required", String(j)])))
                    }
                }
            }
        }

        // properties
        var propKeys = Set<String>()
        if let pv = kw("properties"), case .object(let props) = pv {
            for (k, v) in props {
                propKeys.insert(k)
                if let instVal = getMember(objMembers, k) {
                    let sub = validate(instance: instVal, schema: v,
                        instanceLoc: instanceLoc + [k],
                        schemaLoc: schemaLoc + ["properties", k],
                        rootSchema: rootSchema)
                    errors.formUnion(sub)
                }
            }
        }

        // additionalProperties
        if let addProps = kw("additionalProperties") {
            for (k, v) in objMembers {
                if !propKeys.contains(k) {
                    let sub = validate(instance: v, schema: addProps,
                        instanceLoc: instanceLoc + [k],
                        schemaLoc: schemaLoc + ["additionalProperties"],
                        rootSchema: rootSchema)
                    errors.formUnion(sub)
                }
            }
        }
    }

    // --- Applicators ---

    // $ref
    if let rv = kw("$ref"), case .string(let ref) = rv {
        if let resolved = resolveRef(ref: ref, rootSchema: rootSchema) {
            let sub = validate(instance: instance, schema: resolved,
                instanceLoc: instanceLoc,
                schemaLoc: refSchemaLoc(ref: ref),
                rootSchema: rootSchema)
            errors.formUnion(sub)
        }
    }

    // allOf
    if let av = kw("allOf"), case .array(let schemas) = av {
        for (i, subSchema) in schemas.enumerated() {
            let sub = validate(instance: instance, schema: subSchema,
                instanceLoc: instanceLoc,
                schemaLoc: schemaLoc + ["allOf", String(i)],
                rootSchema: rootSchema)
            errors.formUnion(sub)
        }
    }

    // anyOf
    if let av = kw("anyOf"), case .array(let schemas) = av {
        var anyValid = false
        for subSchema in schemas {
            let sub = validate(instance: instance, schema: subSchema,
                instanceLoc: instanceLoc,
                schemaLoc: schemaLoc + ["anyOf", "0"],
                rootSchema: rootSchema)
            if sub.isEmpty { anyValid = true; break }
        }
        if !anyValid {
            errors.insert((pointerStr(instanceLoc), pointerStr(schemaLoc + ["anyOf"])))
        }
    }

    // oneOf
    if let ov = kw("oneOf"), case .array(let schemas) = ov {
        var validCount = 0
        for subSchema in schemas {
            let sub = validate(instance: instance, schema: subSchema,
                instanceLoc: instanceLoc,
                schemaLoc: schemaLoc + ["oneOf", "0"],
                rootSchema: rootSchema)
            if sub.isEmpty { validCount += 1 }
        }
        if validCount != 1 {
            errors.insert((pointerStr(instanceLoc), pointerStr(schemaLoc + ["oneOf"])))
        }
    }

    // not
    if let nv = kw("not") {
        let sub = validate(instance: instance, schema: nv,
            instanceLoc: instanceLoc,
            schemaLoc: schemaLoc + ["not"],
            rootSchema: rootSchema)
        if sub.isEmpty {
            errors.insert((pointerStr(instanceLoc), pointerStr(schemaLoc + ["not"])))
        }
    }

    // if/then/else
    if let ifVal = kw("if") {
        let ifErrs = validate(instance: instance, schema: ifVal,
            instanceLoc: instanceLoc,
            schemaLoc: schemaLoc + ["if"],
            rootSchema: rootSchema)
        if ifErrs.isEmpty {
            if let thenVal = kw("then") {
                let sub = validate(instance: instance, schema: thenVal,
                    instanceLoc: instanceLoc,
                    schemaLoc: schemaLoc + ["then"],
                    rootSchema: rootSchema)
                errors.formUnion(sub)
            }
        } else {
            if let elseVal = kw("else") {
                let sub = validate(instance: instance, schema: elseVal,
                    instanceLoc: instanceLoc,
                    schemaLoc: schemaLoc + ["else"],
                    rootSchema: rootSchema)
                errors.formUnion(sub)
            }
        }
    }

    return errors
}

