function compareByCodePoint(a: string, b: string): number {
  const aChars = Array.from(a);
  const bChars = Array.from(b);
  const len = Math.min(aChars.length, bChars.length);
  for (let i = 0; i < len; i++) {
    const ca = aChars[i].codePointAt(0)!;
    const cb = bChars[i].codePointAt(0)!;
    if (ca !== cb) return ca - cb;
  }
  return aChars.length - bChars.length;
}

function isValidId(id: any): boolean {
  if (typeof id === 'string') return true;
  if (typeof id === 'number' && Number.isInteger(id)) return true;
  return false;
}

function processLine(line: string): string | null {
  if (line.trim() === '') return null;

  let msg: any;
  try {
    msg = JSON.parse(line);
  } catch {
    return JSON.stringify({ jsonrpc: "2.0", id: null, error: { code: -32700, message: "Parse error" } });
  }

  if (typeof msg !== 'object' || msg === null || Array.isArray(msg)) {
    return JSON.stringify({ jsonrpc: "2.0", id: null, error: { code: -32600, message: "Invalid Request" } });
  }

  // Response from client: no method but has result or error → ignore
  if (!('method' in msg) && ('result' in msg || 'error' in msg)) {
    return null;
  }

  // Check invalid request conditions
  const jsonrpcOk = 'jsonrpc' in msg && msg.jsonrpc === "2.0";
  const methodOk = 'method' in msg && typeof msg.method === 'string';

  let idValid = true;
  let idValue: any = null;
  if ('id' in msg) {
    if (isValidId(msg.id)) {
      idValue = msg.id;
    } else {
      idValid = false;
    }
  }

  if (!jsonrpcOk || !methodOk || !idValid) {
    return JSON.stringify({ jsonrpc: "2.0", id: idValid ? idValue : null, error: { code: -32600, message: "Invalid Request" } });
  }

  // Notification: valid object without id → ignore
  if (!('id' in msg)) {
    return null;
  }

  // It's a request
  const id = idValue;
  const method = msg.method as string;

  // 6a: method not found
  const validMethods = ['initialize', 'ping', 'tools/list', 'tools/call'];
  if (!validMethods.includes(method)) {
    return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32601, message: "Method not found" } });
  }

  // 6b: params present but not an object
  if ('params' in msg) {
    const p = msg.params;
    if (typeof p !== 'object' || p === null || Array.isArray(p)) {
      return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32602, message: "Invalid params" } });
    }
  }

  const params = 'params' in msg ? msg.params : undefined;

  // 6c: not initialized and method is not initialize or ping
  if (!initialized && method !== 'initialize' && method !== 'ping') {
    return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32002, message: "Server not initialized" } });
  }

  // 6d: dispatch
  switch (method) {
    case 'initialize': return handleInitialize(id, params);
    case 'ping': return handlePing(id);
    case 'tools/list': return handleToolsList(id);
    case 'tools/call': return handleToolsCall(id, params);
  }

  return null;
}

function handleInitialize(id: any, params: any): string {
  if (initialized) {
    return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32600, message: "Already initialized" } });
  }

  if (params === undefined || typeof params !== 'object' || params === null || Array.isArray(params)) {
    return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32602, message: "Invalid params" } });
  }

  if (!('protocolVersion' in params) || typeof params.protocolVersion !== 'string') {
    return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32602, message: "Invalid params" } });
  }

  const supportedVersions = ["2025-06-18", "2025-03-26", "2024-11-05"];
  const version = supportedVersions.includes(params.protocolVersion) ? params.protocolVersion : "2025-06-18";

  initialized = true;

  return JSON.stringify({
    jsonrpc: "2.0",
    id,
    result: {
      protocolVersion: version,
      capabilities: { tools: { listChanged: false } },
      serverInfo: { name: "cb2-kv", title: "CB2 key-value server", version: "1.4.2" }
    }
  });
}

function handlePing(id: any): string {
  return JSON.stringify({ jsonrpc: "2.0", id, result: {} });
}

function handleToolsList(id: any): string {
  return JSON.stringify({ jsonrpc: "2.0", id, result: { tools: toolDefs } });
}

function handleToolsCall(id: any, params: any): string {
  if (params === undefined || params === null || typeof params !== 'object' || Array.isArray(params)) {
    return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32602, message: "Invalid params" } });
  }

  if (!('name' in params) || typeof params.name !== 'string') {
    return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32602, message: "Invalid params" } });
  }

  const toolName = params.name;
  const toolDef = toolDefs.find(t => t.name === toolName);

  if (!toolDef) {
    return JSON.stringify({ jsonrpc: "2.0", id, error: { code: -32602, message: `Unknown tool: ${toolName}` } });
  }

  let args: Record<string, any> = {};
  if ('arguments' in params) {
    const a = params.arguments;
    if (a === null || typeof a !== 'object' || Array.isArray(a)) {
      return JSON.stringify({ jsonrpc: "2.0", id, result: { content: [{ type: "text", text: "arguments must be an object" }], isError: true } });
    }
    args = a;
  }

  const failure = validateArgs(args, toolDef.inputSchema);
  if (failure) {
    return JSON.stringify({ jsonrpc: "2.0", id, result: { content: [{ type: "text", text: failure }], isError: true } });
  }

  return executeTool(id, toolDef.name, args);
}

function validateArgs(args: Record<string, any>, schema: any): string | null {
  const properties: Record<string, any> = schema.properties || {};
  const required: string[] = schema.required || [];
  const propNames = Object.keys(properties);

  // Check unknown arguments
  const unknownKeys = Object.keys(args).filter(k => !propNames.includes(k));
  if (unknownKeys.length > 0) {
    unknownKeys.sort(compareByCodePoint);
    return `unknown argument: ${unknownKeys[0]}`;
  }

  // Check each property in schema order
  for (const propName of propNames) {
    const propSchema = properties[propName];
    const isRequired = required.includes(propName);
    const isPresent = propName in args;

    if (!isPresent) {
      if (isRequired) {
        return `missing required argument: ${propName}`;
      }
      continue;
    }

    const value = args[propName];

    if (propSchema.type === 'string') {
      if (typeof value !== 'string') {
        return `argument ${propName} must be a string`;
      }
      if (propSchema.minLength === 1 && value.length === 0) {
        return `argument ${propName} must not be empty`;
      }
    } else if (propSchema.type === 'array') {
      if (!Array.isArray(value)) {
        return `argument ${propName} must be an array of integers`;
      }
      const itemSchema = propSchema.items;
      if (itemSchema && itemSchema.type === 'integer') {
        for (const elem of value) {
          if (typeof elem !== 'number' || !Number.isInteger(elem)) {
            return `argument ${propName} must be an array of integers`;
          }
        }
      }
      if (propSchema.minItems === 1 && value.length === 0) {
        return `argument ${propName} must not be empty`;
      }
    }
  }

  return null;
}

function executeTool(id: any, toolName: string, args: Record<string, any>): string {
  switch (toolName) {
    case 'kv_set': {
      const key = args.key as string;
      const value = args.value as string;
      const existed = store.has(key);
      store.set(key, value);
      const text = existed ? `updated ${key}` : `created ${key}`;
      return JSON.stringify({ jsonrpc: "2.0", id, result: { content: [{ type: "text", text }], isError: false } });
    }
    case 'kv_get': {
      const key = args.key as string;
      if (!store.has(key)) {
        return JSON.stringify({ jsonrpc: "2.0", id, result: { content: [{ type: "text", text: `key not found: ${key}` }], isError: true } });
      }
      const value = store.get(key)!;
      return JSON.stringify({ jsonrpc: "2.0", id, result: { content: [{ type: "text", text: value }], isError: false } });
    }
    case 'kv_list': {
      const prefix = (args.prefix as string) || "";
      let keys = Array.from(store.keys());
      if (prefix) {
        keys = keys.filter(k => k.startsWith(prefix));
      }
      keys.sort(compareByCodePoint);
      const structuredContent = { keys, count: keys.length };
      return JSON.stringify({
        jsonrpc: "2.0", id,
        result: {
          content: [{ type: "text", text: JSON.stringify(structuredContent) }],
          structuredContent,
          isError: false
        }
      });
    }
    case 'sum': {
      const numbers = args.numbers as number[];
      const total = numbers.reduce((acc, n) => acc + n, 0);
      const structuredContent = { sum: total, count: numbers.length };
      return JSON.stringify({
        jsonrpc: "2.0", id,
        result: {
          content: [{ type: "text", text: JSON.stringify(structuredContent) }],
          structuredContent,
          isError: false
        }
      });
    }
    case 'text_stats': {
      const text = args.text as string;
      let words = 0;
      let inWord = false;
      for (const ch of text) {
        if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r') {
          inWord = false;
        } else {
          if (!inWord) words++;
          inWord = true;
        }
      }
      const codepoints = Array.from(text).length;
      const utf8Bytes = Buffer.byteLength(text, 'utf8');
      const structuredContent = { words, codepoints, utf8_bytes: utf8Bytes };
      return JSON.stringify({
        jsonrpc: "2.0", id,
        result: {
          content: [{ type: "text", text: JSON.stringify(structuredContent) }],
          structuredContent,
          isError: false
        }
      });
    }
  }
  return null;
}

const outputs: string[] = [];

rl.on('line', (line: string) => {
  const result = processLine(line);
  if (result !== null) {
    outputs.push(result);
  }
});

rl.on('close', () => {
  for (const line of outputs) {
    process.stdout.write(line + '\n');
  }
  process.exit(0);
});

import Foundation

// ===== Big Integer Operations (unsigned, decimal digits, most significant first) =====

func norm(_ d: [Int]) -> [Int] {
    var i = 0
    while i < d.count - 1 && d[i] == 0 { i += 1 }
    return Array(d[i...])
}

func cmpM(_ a: [Int], _ b: [Int]) -> Int {
    if a.count != b.count { return a.count < b.count ? -1 : 1 }
    for i in 0..<a.count { if a[i] != b[i] { return a[i] < b[i] ? -1 : 1 } }
    return 0
}

func addM(_ a: [Int], _ b: [Int]) -> [Int] {
    let n = max(a.count, b.count)
    var r = [Int](repeating: 0, count: n + 1)
    var c = 0
    for i in 0..<n {
        let x = (i < a.count) ? a[a.count-1-i] : 0
        let y = (i < b.count) ? b[b.count-1-i] : 0
        let s = x + y + c
        r[n-i] = s % 10
        c = s / 10
    }
    r[0] = c
    return norm(r)
}

func subM(_ a: [Int], _ b: [Int]) -> [Int] {
    // requires |a| >= |b|
    let n = a.count
    var r = [Int](repeating: 0, count: n)
    var b0 = 0
    for i in 0..<n {
        let x = a[n-1-i]
        let y = (i < b.count) ? b[b.count-1-i] : 0
        var d = x - y - b0
        if d < 0 { d += 10; b0 = 1 } else { b0 = 0 }
        r[n-1-i] = d
    }
    return norm(r)
}

func mulM(_ a: [Int], _ b: [Int]) -> [Int] {
    if (a.count == 1 && a[0] == 0) || (b.count == 1 && b[0] == 0) { return [0] }
    let ar = Array(a.reversed())
    let br = Array(b.reversed())
    var r = [Int](repeating: 0, count: a.count + b.count)
    for i in 0..<ar.count {
        var c = 0
        for j in 0..<br.count {
            let s = r[i+j] + ar[i]*br[j] + c
            r[i+j] = s % 10
            c = s / 10
        }
        var p = i + br.count
        while c > 0 {
            let s = r[p] + c
            r[p] = s % 10
            c = s / 10
            p += 1
        }
    }
    r.reverse()
    return norm(r)
}

func divModM(_ a: [Int], _ b: [Int]) -> (q: [Int], r: [Int]) {
    if cmpM(a, b) < 0 { return ([0], a) }
    var q = [Int](repeating: 0, count: a.count)
    var rem: [Int] = [0]
    for i in 0..<a.count {
        rem = norm(rem + [a[i]])
        var qi = 0
        while cmpM(rem, b) >= 0 {
            rem = subM(rem, b)
            qi += 1
        }
        q[i] = qi
    }
    return (norm(q), norm(rem))
}

func addOne(_ d: [Int]) -> [Int] {
    var r = d
    var c = 1
    for i in stride(from: r.count-1, through: 0, by: -1) {
        let s = r[i] + c
        r[i] = s % 10
        c = s / 10
        if c == 0 { break }
    }
    if c > 0 { r.insert(c, at: 0) }
    return r
}

func intToDigits(_ n: Int) -> [Int] {
    if n == 0 { return [0] }
    var d = [Int]()
    var v = n
    while v > 0 { d.append(v % 10); v /= 10 }
    return d.reversed()
}

// ===== Big Decimal =====

struct BD {
    var neg: Bool
    var mag: [Int]  // magnitude, most significant first, normalized (no leading zeros unless zero)
    var scale: Int  // number of decimal places

    var isZero: Bool { mag.count == 1 && mag[0] == 0 }
}

func zero(scale: Int) -> BD { BD(neg: false, mag: [0], scale: scale) }

func parseBD(_ s: String) -> BD {
    var str = s
    var neg = false
    if str.hasPrefix("-") { neg = true; str = String(str.dropFirst()) }
    var ip = "", fp = ""
    if let di = str.firstIndex(of: ".") {
        ip = String(str[str.startIndex..<di])
        fp = String(str[str.index(after: di)...])
    } else {
        ip = str
    }
    // Strip leading zeros from integer part
    while ip.count > 1 && ip.first == "0" { ip = String(ip.dropFirst()) }
    if ip.isEmpty { ip = "0" }
    var d = [Int]()
    for ch in ip { d.append(Int(ch.asciiValue! - 48)) }
    for ch in fp { d.append(Int(ch.asciiValue! - 48)) }
    let sc = fp.count
    let m = norm(d)
    // Handle negative zero
    if m.count == 1 && m[0] == 0 { neg = false }
    return BD(neg: neg, mag: m, scale: sc)
}

func roundBD(_ d: BD, to target: Int) -> BD {
    if d.scale <= target {
        let extra = target - d.scale
        var m = d.mag + [Int](repeating: 0, count: extra)
        return BD(neg: d.neg, mag: m, scale: target)
    }
    let drop = d.scale - target
    let n = d.mag.count
    let fi = n - drop  // first dropped index

    let fd = d.mag[fi]
    var nzAfter = false
    if fd == 5 {
        for j in (fi+1)..<n { if d.mag[j] != 0 { nzAfter = true; break } }
    }

    var keep = Array(d.mag[0..<fi])
    var up = false

    if fd > 5 { up = true }
    else if fd == 5 {
        if nzAfter { up = true }
        else {
            let last = keep.isEmpty ? 0 : keep[keep.count - 1]
            if last % 2 == 1 { up = true }
        }
    }

    if up { keep = addOne(keep) }
    if keep.isEmpty { keep = [0] }
    keep = norm(keep)

    var neg = d.neg
    if keep.count == 1 && keep[0] == 0 { neg = false }
    return BD(neg: neg, mag: keep, scale: target)
}

func addBD(_ a: BD, _ b: BD) -> BD {
    let ts = max(a.scale, b.scale)
    let am = a.mag + [Int](repeating: 0, count: ts - a.scale)
    let bm = b.mag + [Int](repeating: 0, count: ts - b.scale)

    if a.neg == b.neg {
        var m = addM(am, bm)
        var neg = a.neg
        if m.count == 1 && m[0] == 0 { neg = false }
        return BD(neg: neg, mag: m, scale: ts)
    } else {
        let c = cmpM(am, bm)
        if c == 0 { return zero(scale: ts) }
        if c > 0 {
            var m = subM(am, bm)
            var neg = a.neg
            if m.count == 1 && m[0] == 0 { neg = false }
            return BD(neg: neg, mag: m, scale: ts)
        } else {
            var m = subM(bm, am)
            var neg = b.neg
            if m.count == 1 && m[0] == 0 { neg = false }
            return BD(neg: neg, mag: m, scale: ts)
        }
    }
}

func negBD(_ a: BD) -> BD {
    if a.isZero { return BD(neg: false, mag: a.mag, scale: a.scale) }
    return BD(neg: !a.neg, mag: a.mag, scale: a.scale)
}

func mulBD(_ a: BD, _ b: BD) -> BD {
    var neg = (a.neg != b.neg)
    let m = mulM(a.mag, b.mag)
    if m.count == 1 && m[0] == 0 { neg = false }
    return BD(neg: neg, mag: m, scale: a.scale + b.scale)
}

func cmpBD(_ a: BD, _ b: BD) -> Int {
    let ts = max(a.scale, b.scale)
    let am = a.mag + [Int](repeating: 0, count: ts - a.scale)
    let bm = b.mag + [Int](repeating: 0, count: ts - b.scale)

    if a.neg != b.neg {
        if a.neg { return -1 } else { return 1 }
    }
    let c = cmpM(am, bm)
    if a.neg { return -c }
    return c
}

func fmtBD(_ d: BD, minor: Int) -> String {
    // Ensure we have the right scale
    var m = d.mag
    let sc = d.scale
    // If sc < minor, pad with zeros
    if sc < minor {
        m = m + [Int](repeating: 0, count: minor - sc)
    }
    // If sc > minor, truncate (shouldn't happen with proper rounding)
    if sc > minor {
        let keep = m.count - (sc - minor)
        if keep > 0 {
            m = Array(m[0..<keep])
        } else {
            m = [0]
        }
    }

    // Check zero
    if m.count == 1 && m[0] == 0 {
        if minor == 0 { return "0" }
        return "0." + String(repeating: "0", count: minor)
    }

    var res = ""
    if d.neg { res += "-" }

    // Integer part: first (m.count - minor) digits
    let ipc = m.count - minor
    var intDigits: [Int]
    var fracDigits: [Int]
    if ipc > 0 {
        intDigits = Array(m[0..<ipc])
        fracDigits = Array(m[ipc...])
    } else {
        intDigits = [0]
        fracDigits = [Int](repeating: 0, count: -ipc) + m
    }

    // Format integer part with commas
    let iStr = intDigits.map { String($0) }.joined()
    var parts: [String] = []
    var rem = iStr
    while rem.count > 3 {
        parts.insert(String(rem.suffix(3)), at: 0)
        rem = String(rem.dropLast(3))
    }
    parts.insert(rem, at: 0)
    res += parts.joined(separator: ",")

    if minor > 0 {
        res += "."
        let fStr = fracDigits.map { String($0) }.joined()
        if fStr.count >= minor {
            res += String(fStr.prefix(minor))
        } else {
            res += fStr + String(repeating: "0", count: minor - fStr.count)
        }
    }

    return res
}

// Convert BD to integer in minor units (magnitude as digits)
// Assumes BD is at scale = minorUnits and is non-negative
func toMinor(_ d: BD) -> [Int] {
    return d.mag
}

// ===== Main =====

let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]
let path = dir + "/ledger.txt"
guard let content = try? String(contentsOfFile: path, encoding: .utf8) else { exit(1) }

let lines = content.components(separatedBy: "\n")

var currencies: [String: Int] = [:]
var accounts: [String: (cur: String, bal: BD, lim: BD)] = [:]
var rejects: [(Int, String)] = []

for (idx, rawLine) in lines.enumerated() {
    let ln = idx + 1
    let trimmed = rawLine.trimmingCharacters(in: .whitespaces)
    if trimmed.isEmpty || trimmed.hasPrefix("#") { continue }

    let flds = trimmed.components(separatedBy: .whitespaces).filter { !$0.isEmpty }
    guard !flds.isEmpty else { continue }
    let cmd = flds[0]

    switch cmd {
    case "currency":
        currencies[flds[1]] = Int(flds[2])!

    case "open":
        let name = flds[1]
        let code = flds[2]
        let minor = currencies[code]!
        if accounts[name] != nil {
            rejects.append((ln, "account exists \(name)"))
            continue
        }
        var lim = zero(scale: minor)
        if flds.count >= 4 {
            lim = roundBD(parseBD(flds[3]), to: minor)
        }
        accounts[name] = (cur: code, bal: zero(scale: minor), lim: lim)

    case "deposit":
        let name = flds[1]
        guard let acct = accounts[name] else {
            rejects.append((ln, "unknown account \(name)")); continue
        }
        let minor = currencies[acct.cur]!
        let amt = roundBD(parseBD(flds[2]), to: minor)
        if amt.isZero || amt.neg {
            rejects.append((ln, "non-positive amount")); continue
        }
        accounts[name]!.bal = addBD(acct.bal, amt)

    case "withdraw":
        let name = flds[1]
        guard let acct = accounts[name] else {
            rejects.append((ln, "unknown account \(name)")); continue
        }
        let minor = currencies[acct.cur]!
        let amt = roundBD(parseBD(flds[2]), to: minor)
        if amt.isZero || amt.neg {
            rejects.append((ln, "non-positive amount")); continue
        }
        let newBal = addBD(acct.bal, negBD(amt))
        let minAllowed = negBD(acct.lim)
        if cmpBD(newBal, minAllowed) < 0 {
            rejects.append((ln, "insufficient funds \(name)")); continue
        }
        accounts[name]!.bal = newBal

    case "transfer":
        let from = flds[1], to = flds[2]
        guard let fa = accounts[from] else {
            rejects.append((ln, "unknown account \(from)")); continue
        }
        guard let ta = accounts[to] else {
            rejects.append((ln, "unknown account \(to)")); continue
        }
        if fa.cur != ta.cur {
            rejects.append((ln, "currency mismatch")); continue
        }
        let minor = currencies[fa.cur]!
        let amt = roundBD(parseBD(flds[3]), to: minor)
        if amt.isZero || amt.neg {
            rejects.append((ln, "non-positive amount")); continue
        }
        let newFrom = addBD(fa.bal, negBD(amt))
        let minAllowed = negBD(fa.lim)
        if cmpBD(newFrom, minAllowed) < 0 {
            rejects.append((ln, "insufficient funds \(from)")); continue
        }
        accounts[from]!.bal = newFrom
        accounts[to]!.bal = addBD(ta.bal, amt)

    case "convert":
        let from = flds[1], to = flds[2]
        guard let fa = accounts[from] else {
            rejects.append((ln, "unknown account \(from)")); continue
        }
        guard let ta = accounts[to] else {
            rejects.append((ln, "unknown account \(to)")); continue
        }
        let fromMinor = currencies[fa.cur]!
        let toMinor = currencies[ta.cur]!
        let amt = roundBD(parseBD(flds[3]), to: fromMinor)
        if amt.isZero || amt.neg {
            rejects.append((ln, "non-positive amount")); continue
        }
        let newFrom = addBD(fa.bal, negBD(amt))
        let minAllowed = negBD(fa.lim)
        if cmpBD(newFrom, minAllowed) < 0 {
            rejects.append((ln, "insufficient funds \(from)")); continue
        }
        let rate = parseBD(flds[4])
        let recvExact = mulBD(amt, rate)
        let recv = roundBD(recvExact, to: toMinor)
        accounts[from]!.bal = newFrom
        accounts[to]!.bal = addBD(ta.bal, recv)

    case "interest":
        let name = flds[1]
        guard let acct = accounts[name] else {
            rejects.append((ln, "unknown account \(name)")); continue
        }
        let minor = currencies[acct.cur]!
        let rate = parseBD(flds[2])
        let intExact = mulBD(acct.bal, rate)
        let intAmt = roundBD(intExact, to: minor)
        accounts[name]!.bal = addBD(acct.bal, intAmt)

    case "split":
        let from = flds[1]
        guard let fa = accounts[from] else {
            rejects.append((ln, "unknown account \(from)")); continue
        }
        // Parse targets: flds[3], flds[4], ...
        var tNames: [String] = []
        var tWeights: [Int] = []
        var unknownFound = false
        for i in 3..<flds.count {
            let parts = flds[i].components(separatedBy: ":")
            let tn = parts[0]
            let tw = Int(parts[1])!
            if accounts[tn] == nil {
                rejects.append((ln, "unknown account \(tn)"))
                unknownFound = true
                break
            }
            tNames.append(tn)
            tWeights.append(tw)
        }
        if unknownFound { continue }

        // Check currency mismatch
        let fromCur = fa.cur
        var mismatch = false
        for tn in tNames {
            if accounts[tn]!.cur != fromCur {
                mismatch = true; break
            }
        }
        if mismatch {
            rejects.append((ln, "currency mismatch")); continue
        }

        let minor = currencies[fromCur]!
        let amt = roundBD(parseBD(flds[2]), to: minor)
        if amt.isZero || amt.neg {
            rejects.append((ln, "non-positive amount")); continue
        }

        // Check insufficient funds
        let newFrom = addBD(fa.bal, negBD(amt))
        let minAllowed = negBD(fa.lim)
        if cmpBD(newFrom, minAllowed) < 0 {
            rejects.append((ln, "insufficient funds \(from)")); continue
        }

        // Perform split
        let A = amt.mag  // magnitude in minor units (positive integer)
        var W = 0
        for w in tWeights { W += w }
        let Wd = intToDigits(W)

        var bases: [[Int]] = []
        var rems: [[Int]] = []
        var baseSum = [0]

        for i in 0..<tNames.count {
            let wi = intToDigits(tWeights[i])
            let prod = mulM(A, wi)
            let (q, r) = divModM(prod, Wd)
            bases.append(q)
            rems.append(r)
            baseSum = addM(baseSum, q)
        }

        let leftover = subM(A, baseSum)  // A - sum(bases)
        let leftoverInt = digitsToInt(leftover)  // should be small (0 to n-1)

        // Sort targets by remainder descending, ties by original order
        var indices = Array(0..<tNames.count)
        indices.sort { i, j in
            let c = cmpM(rems[i], rems[j])
            if c != 0 { return c > 0 }  // larger remainder first
            return i < j  // earlier in list wins ties
        }

        // Give +1 to first `leftoverInt` targets
        accounts[from]!.bal = newFrom
        for idx in indices {
            let extra: [Int]
            if idx < leftoverInt {
                extra = addOne(bases[idx])
            } else {
                extra = bases[idx]
            }
            // Wait, no. The extra is +1 minor unit, not +1 to the base.
            // Actually, the target gets base_i + (1 if selected, else 0) minor units.
            // So I need to add 1 to the base if selected.
            // Hmm wait, let me re-read: "the minor units still left over are then given one each to the targets with the largest remainders"
            // So the target gets base_i + 1 if it's in the top `leftover` targets by remainder.
            // Yes, so extra = base_i + 1 if selected, base_i otherwise.
        }

        // Let me redo this:
        accounts[from]!.bal = newFrom
        for idx in indices {
            var share = bases[idx]
            // Check if this target gets an extra unit
            // ...
        }

        // Hmm, I need to track which targets get the extra. Let me redo:
        var shares: [[Int]] = bases  // copy
        for k in 0..<leftoverInt {
            let idx = indices[k]
            shares[idx] = addOne(shares[idx])
        }

        accounts[from]!.bal = newFrom
        for i in 0..<tNames.count {
            let add = BD(neg: false, mag: shares[i], scale: minor)
            accounts[tNames[i]]!.bal = addBD(accounts[tNames[i]]!.bal, add)
        }

    default:
        break
    }
}

import Foundation

// ===== Big Integer Operations (unsigned, decimal digits, most significant first) =====

func norm(_ d: [Int]) -> [Int] {
    var i = 0
    while i < d.count - 1 && d[i] == 0 { i += 1 }
    return Array(d[i...])
}

func cmpM(_ a: [Int], _ b: [Int]) -> Int {
    if a.count != b.count { return a.count < b.count ? -1 : 1 }
    for i in 0..<a.count { if a[i] != b[i] { return a[i] < b[i] ? -1 : 1 } }
    return 0
}

func addM(_ a: [Int], _ b: [Int]) -> [Int] {
    let n = max(a.count, b.count)
    var r = [Int](repeating: 0, count: n + 1)
    var c = 0
    for i in 0..<n {
        let x = (i < a.count) ? a[a.count-1-i] : 0
        let y = (i < b.count) ? b[b.count-1-i] : 0
        let s = x + y + c
        r[n-i] = s % 10
        c = s / 10
    }
    r[0] = c
    return norm(r)
}

func subM(_ a: [Int], _ b: [Int]) -> [Int] {
    let n = a.count
    var r = [Int](repeating: 0, count: n)
    var borrow = 0
    for i in 0..<n {
        let x = a[n-1-i]
        let y = (i < b.count) ? b[b.count-1-i] : 0
        var d = x - y - borrow
        if d < 0 { d += 10; borrow = 1 } else { borrow = 0 }
        r[n-1-i] = d
    }
    return norm(r)
}

func mulM(_ a: [Int], _ b: [Int]) -> [Int] {
    if (a.count == 1 && a[0] == 0) || (b.count == 1 && b[0] == 0) { return [0] }
    let ar = Array(a.reversed())
    let br = Array(b.reversed())
    var r = [Int](repeating: 0, count: a.count + b.count)
    for i in 0..<ar.count {
        var c = 0
        for j in 0..<br.count {
            let s = r[i+j] + ar[i]*br[j] + c
            r[i+j] = s % 10
            c = s / 10
        }
        var p = i + br.count
        while c > 0 {
            let s = r[p] + c
            r[p] = s % 10
            c = s / 10
            p += 1
        }
    }
    r.reverse()
    return norm(r)
}

func divModM(_ a: [Int], _ b: [Int]) -> (q: [Int], r: [Int]) {
    if cmpM(a, b) < 0 { return ([0], a) }
    var q = [Int](repeating: 0, count: a.count)
    var rem: [Int] = [0]
    for i in 0..<a.count {
        rem = norm(rem + [a[i]])
        var qi = 0
        while cmpM(rem, b) >= 0 {
            rem = subM(rem, b)
            qi += 1
        }
        q[i] = qi
    }
    return (norm(q), norm(rem))
}

func addOne(_ d: [Int]) -> [Int] {
    var r = d
    var c = 1
    for i in stride(from: r.count-1, through: 0, by: -1) {
        let s = r[i] + c
        r[i] = s % 10
        c = s / 10
        if c == 0 { break }
    }
    if c > 0 { r.insert(c, at: 0) }
    return r
}

func intToDigits(_ n: Int) -> [Int] {
    if n == 0 { return [0] }
    var d = [Int]()
    var v = n
    while v > 0 { d.append(v % 10); v /= 10 }
    return d.reversed()
}

func digitsToInt(_ d: [Int]) -> Int {
    var v = 0
    for digit in d { v = v * 10 + digit }
    return v
}

// ===== Big Decimal =====

struct BD {
    var neg: Bool
    var mag: [Int]  // magnitude, most significant first, normalized
    var scale: Int  // number of decimal places

    var isZero: Bool { mag.count == 1 && mag[0] == 0 }
}

func zeroBD(scale: Int) -> BD { BD(neg: false, mag: [0], scale: scale) }

func parseBD(_ s: String) -> BD {
    var str = s
    var neg = false
    if str.hasPrefix("-") { neg = true; str = String(str.dropFirst()) }
    var ip = "", fp = ""
    if let di = str.firstIndex(of: ".") {
        ip = String(str[str.startIndex..<di])
        fp = String(str[str.index(after: di)...])
    } else {
        ip = str
    }
    while ip.count > 1 && ip.first == "0" { ip = String(ip.dropFirst()) }
    if ip.isEmpty { ip = "0" }
    var d = [Int]()
    for ch in ip { d.append(Int(ch.asciiValue! - 48)) }
    for ch in fp { d.append(Int(ch.asciiValue! - 48)) }
    let sc = fp.count
    let m = norm(d)
    if m.count == 1 && m[0] == 0 { neg = false }
    return BD(neg: neg, mag: m, scale: sc)
}

func roundBD(_ d: BD, to target: Int) -> BD {
    if d.scale <= target {
        let extra = target - d.scale
        let m = d.mag + [Int](repeating: 0, count: extra)
        return BD(neg: d.neg, mag: m, scale: target)
    }
    let drop = d.scale - target
    let n = d.mag.count
    let fi = n - drop

    let fd = d.mag[fi]
    var nzAfter = false
    if fd == 5 {
        for j in (fi+1)..<n { if d.mag[j] != 0 { nzAfter = true; break } }
    }

    var keep = Array(d.mag[0..<fi])
    var up = false

    if fd > 5 { up = true }
    else if fd == 5 {
        if nzAfter { up = true }
        else {
            let last = keep.isEmpty ? 0 : keep[keep.count - 1]
            if last % 2 == 1 { up = true }
        }
    }

    if up { keep = addOne(keep) }
    if keep.isEmpty { keep = [0] }
    keep = norm(keep)

    var neg = d.neg
    if keep.count == 1 && keep[0] == 0 { neg = false }
    return BD(neg: neg, mag: keep, scale: target)
}

func addBD(_ a: BD, _ b: BD) -> BD {
    let ts = max(a.scale, b.scale)
    let am = a.mag + [Int](repeating: 0, count: ts - a.scale)
    let bm = b.mag + [Int](repeating: 0, count: ts - b.scale)

    if a.neg == b.neg {
        let m = addM(am, bm)
        var neg = a.neg
        if m.count == 1 && m[0] == 0 { neg = false }
        return BD(neg: neg, mag: m, scale: ts)
    } else {
        let c = cmpM(am, bm)
        if c == 0 { return zeroBD(scale: ts) }
        if c > 0 {
            let m = subM(am, bm)
            var neg = a.neg
            if m.count == 1 && m[0] == 0 { neg = false }
            return BD(neg: neg, mag: m, scale: ts)
        } else {
            let m = subM(bm, am)
            var neg = b.neg
            if m.count == 1 && m[0] == 0 { neg = false }
            return BD(neg: neg, mag: m, scale: ts)
        }
    }
}

func negBD(_ a: BD) -> BD {
    if a.isZero { return BD(neg: false, mag: a.mag, scale: a.scale) }
    return BD(neg: !a.neg, mag: a.mag, scale: a.scale)
}

func mulBD(_ a: BD, _ b: BD) -> BD {
    var neg = (a.neg != b.neg)
    let m = mulM(a.mag, b.mag)
    if m.count == 1 && m[0] == 0 { neg = false }
    return BD(neg: neg, mag: m, scale: a.scale + b.scale)
}

func cmpBD(_ a: BD, _ b: BD) -> Int {
    let ts = max(a.scale, b.scale)
    let am = a.mag + [Int](repeating: 0, count: ts - a.scale)
    let bm = b.mag + [Int](repeating: 0, count: ts - b.scale)

    if a.neg != b.neg {
        if a.neg { return -1 } else { return 1 }
    }
    let c = cmpM(am, bm)
    if a.neg { return -c }
    return c
}

func fmtBD(_ d: BD, minor: Int) -> String {
    var m = d.mag
    let sc = d.scale
    if sc < minor {
        m = m + [Int](repeating: 0, count: minor - sc)
    }
    if sc > minor {
        let keep = m.count - (sc - minor)
        if keep > 0 { m = Array(m[0..<keep]) } else { m = [0] }
    }

    if m.count == 1 && m[0] == 0 {
        if minor == 0 { return "0" }
        return "0." + String(repeating: "0", count: minor)
    }

    var res = ""
    if d.neg { res += "-" }

    let ipc = m.count - minor
    var intDigits: [Int]
    var fracDigits: [Int]
    if ipc > 0 {
        intDigits = Array(m[0..<ipc])
        fracDigits = Array(m[ipc...])
    } else {
        intDigits = [0]
        fracDigits = [Int](repeating: 0, count: -ipc) + m
    }

    let iStr = intDigits.map { String($0) }.joined()
    var parts: [String] = []
    var rem = iStr
    while rem.count > 3 {
        parts.insert(String(rem.suffix(3)), at: 0)
        rem = String(rem.dropLast(3))
    }
    parts.insert(rem, at: 0)
    res += parts.joined(separator: ",")

    if minor > 0 {
        res += "."
        let fStr = fracDigits.map { String($0) }.joined()
        if fStr.count >= minor {
            res += String(fStr.prefix(minor))
        } else {
            res += fStr + String(repeating: "0", count: minor - fStr.count)
        }
    }

    return res
}

// ===== Main =====

let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]
let path = dir + "/ledger.txt"
guard let content = try? String(contentsOfFile: path, encoding: .utf8) else { exit(1) }

let lines = content.components(separatedBy: "\n")

var currencies: [String: Int] = [:]
var accounts: [String: (cur: String, bal: BD, lim: BD)] = [:]
var rejects: [(Int, String)] = []

for (idx, rawLine) in lines.enumerated() {
    let ln = idx + 1
    let trimmed = rawLine.trimmingCharacters(in: .whitespaces)
    if trimmed.isEmpty || trimmed.hasPrefix("#") { continue }

    let flds = trimmed.components(separatedBy: .whitespaces).filter { !$0.isEmpty }
    guard !flds.isEmpty else { continue }
    let cmd = flds[0]

    switch cmd {
    case "currency":
        currencies[flds[1]] = Int(flds[2])!

    case "open":
        let name = flds[1]
        let code = flds[2]
        let minor = currencies[code]!
        if accounts[name] != nil {
            rejects.append((ln, "account exists \(name)"))
            continue
        }
        var lim = zeroBD(scale: minor)
        if flds.count >= 4 {
            lim = roundBD(parseBD(flds[3]), to: minor)
        }
        accounts[name] = (cur: code, bal: zeroBD(scale: minor), lim: lim)

    case "deposit":
        let name = flds[1]
        guard let acct = accounts[name] else {
            rejects.append((ln, "unknown account \(name)")); continue
        }
        let minor = currencies[acct.cur]!
        let amt = roundBD(parseBD(flds[2]), to: minor)
        if amt.isZero || amt.neg {
            rejects.append((ln, "non-positive amount")); continue
        }
        accounts[name]!.bal = addBD(acct.bal, amt)

    case "withdraw":
        let name = flds[1]
        guard let acct = accounts[name] else {
            rejects.append((ln, "unknown account \(name)")); continue
        }
        let minor = currencies[acct.cur]!
        let amt = roundBD(parseBD(flds[2]), to: minor)
        if amt.isZero || amt.neg {
            rejects.append((ln, "non-positive amount")); continue
        }
        let newBal = addBD(acct.bal, negBD(amt))
        let minAllowed = negBD(acct.lim)
        if cmpBD(newBal, minAllowed) < 0 {
            rejects.append((ln, "insufficient funds \(name)")); continue
        }
        accounts[name]!.bal = newBal

    case "transfer":
        let from = flds[1], to = flds[2]
        guard let fa = accounts[from] else {
            rejects.append((ln, "unknown account \(from)")); continue
        }
        guard let ta = accounts[to] else {
            rejects.append((ln, "unknown account \(to)")); continue
        }
        if fa.cur != ta.cur {
            rejects.append((ln, "currency mismatch")); continue
        }
        let minor = currencies[fa.cur]!
        let amt = roundBD(parseBD(flds[3]), to: minor)
        if amt.isZero || amt.neg {
            rejects.append((ln, "non-positive amount")); continue
        }
        let newFrom = addBD(fa.bal, negBD(amt))
        let minAllowed = negBD(fa.lim)
        if cmpBD(newFrom, minAllowed) < 0 {
            rejects.append((ln, "insufficient funds \(from)")); continue
        }
        accounts[from]!.bal = newFrom
        accounts[to]!.bal = addBD(ta.bal, amt)

    case "convert":
        let from = flds[1], to = flds[2]
        guard let fa = accounts[from] else {
            rejects.append((ln, "unknown account \(from)")); continue
        }
        guard let ta = accounts[to] else {
            rejects.append((ln, "unknown account \(to)")); continue
        }
        let fromMinor = currencies[fa.cur]!
        let toMinor = currencies[ta.cur]!
        let amt = roundBD(parseBD(flds[3]), to: fromMinor)
        if amt.isZero || amt.neg {
            rejects.append((ln, "non-positive amount")); continue
        }
        let newFrom = addBD(fa.bal, negBD(amt))
        let minAllowed = negBD(fa.lim)
        if cmpBD(newFrom, minAllowed) < 0 {
            rejects.append((ln, "insufficient funds \(from)")); continue
        }
        let rate = parseBD(flds[4])
        let recvExact = mulBD(amt, rate)
        let recv = roundBD(recvExact, to: toMinor)
        accounts[from]!.bal = newFrom
        accounts[to]!.bal = addBD(ta.bal, recv)

    case "interest":
        let name = flds[1]
        guard let acct = accounts[name] else {
            rejects.append((ln, "unknown account \(name)")); continue
        }
        let minor = currencies[acct.cur]!
        let rate = parseBD(flds[2])
        let intExact = mulBD(acct.bal, rate)
        let intAmt = roundBD(intExact, to: minor)
        accounts[name]!.bal = addBD(acct.bal, intAmt)

    case "split":
        let from = flds[1]
        guard let fa = accounts[from] else {
            rejects.append((ln, "unknown account \(from)")); continue
        }
        var tNames: [String] = []
        var tWeights: [Int] = []
        var unknownFound = false
        for i in 3..<flds.count {
            let parts = flds[i].components(separatedBy: ":")
            let tn = parts[0]
            let tw = Int(parts[1])!
            if accounts[tn] == nil {
                rejects.append((ln, "unknown account \(tn)"))
                unknownFound = true
                break
            }
            tNames.append(tn)
            tWeights.append(tw)
        }
        if unknownFound { continue }

        let fromCur = fa.cur
        var mismatch = false
        for tn in tNames {
            if accounts[tn]!.cur != fromCur {
                mismatch = true; break
            }
        }
        if mismatch {
            rejects.append((ln, "currency mismatch")); continue
        }

        let minor = currencies[fromCur]!
        let amt = roundBD(parseBD(flds[2]), to: minor)
        if amt.isZero || amt.neg {
            rejects.append((ln, "non-positive amount")); continue
        }

        let newFrom = addBD(fa.bal, negBD(amt))
        let minAllowed = negBD(fa.lim)
        if cmpBD(newFrom, minAllowed) < 0 {
            rejects.append((ln, "insufficient funds \(from)")); continue
        }

        // Perform split in minor units
        let A = amt.mag  // positive integer magnitude
        var W = 0
        for w in tWeights { W += w }
        let Wd = intToDigits(W)

        var bases: [[Int]] = []
        var rems: [[Int]] = []
        var baseSum = [0]

        for i in 0..<tNames.count {
            let wi = intToDigits(tWeights[i])
            let prod = mulM(A, wi)
            let (q, r) = divModM(prod, Wd)
            bases.append(q)
            rems.append(r)
            baseSum = addM(baseSum, q)
        }

        let leftover = subM(A, baseSum)
        let leftoverInt = digitsToInt(leftover)

        // Sort targets by remainder descending, ties by original order
        var indices = Array(0..<tNames.count)
        indices.sort { i, j in
            let c = cmpM(rems[i], rems[j])
            if c != 0 { return c > 0 }
            return i < j
        }

        var shares: [[Int]] = bases
        for k in 0..<leftoverInt {
            let idx = indices[k]
            shares[idx] = addOne(shares[idx])
        }

        accounts[from]!.bal = newFrom
        for i in 0..<tNames.count {
            let add = BD(neg: false, mag: shares[i], scale: minor)
            accounts[tNames[i]]!.bal = addBD(accounts[tNames[i]]!.bal, add)
        }

    default:
        break
    }
}

// ===== Output =====

var output = ""

for (ln, reason) in rejects {
    output += "line \(ln): REJECT \(reason)\n"
}

output += "\n"

let sortedAccounts = accounts.keys.sorted(by: { $0 < $1 })
for name in sortedAccounts {
    let acct = accounts[name]!
    let minor = currencies[acct.cur]!
    output += "\(name) \(acct.cur) \(fmtBD(acct.bal, minor: minor))\n"
}

output += "\n"

// Collect currencies with at least one account
var curTotals: [String: (sum: BD, count: Int)] = [:]
for name in sortedAccounts {
    let acct = accounts[name]!
    let cur = acct.cur
    if curTotals[cur] == nil {
        let minor = currencies[cur]!
        curTotals[cur] = (sum: zeroBD(scale: minor), count: 0)
    }
    curTotals[cur]!.sum = addBD(curTotals[cur]!.sum, acct.bal)
    curTotals[cur]!.count += 1
}

let sortedCurrencies = curTotals.keys.sorted(by: { $0 < $1 })
for cur in sortedCurrencies {
    let info = curTotals[cur]!
    let minor = currencies[cur]!
    output += "total \(cur) \(fmtBD(info.sum, minor: minor)) (\(info.count) accounts)\n"
}

print(output, terminator: "")
exit(0)

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {

    static class ParseException extends Exception {}

    static class JsonNum {
        boolean isInt;
        long longVal;
        double dblVal;
        JsonNum(boolean isInt, long longVal, double dblVal) {
            this.isInt = isInt; this.longVal = longVal; this.dblVal = dblVal;
        }
    }

    static class Parser {
        String s; int pos;
        Parser(String s) { this.s = s; this.pos = 0; }

        Object parse() throws ParseException {
            skipWs();
            Object v = parseValue();
            skipWs();
            if (pos != s.length()) throw new ParseException();
            return v;
        }

        void skipWs() {
            while (pos < s.length()) {
                char c = s.charAt(pos);
                if (c == ' ' || c == '\t' || c == '\r' || c == '\n') pos++;
                else break;
            }
        }

        Object parseValue() throws ParseException {
            if (pos >= s.length()) throw new ParseException();
            char c = s.charAt(pos);
            if (c == '{') return parseObj();
            if (c == '[') return parseArr();
            if (c == '"') return parseStr();
            if (c == 't') { expect("true"); return Boolean.TRUE; }
            if (c == 'f') { expect("false"); return Boolean.FALSE; }
            if (c == 'n') { expect("null"); return null; }
            if (c == '-' || (c >= '0' && c <= '9')) return parseNum();
            throw new ParseException();
        }

        void expect(String lit) throws ParseException {
            if (!s.startsWith(lit, pos)) throw new ParseException();
            pos += lit.length();
        }

        @SuppressWarnings("unchecked")
        Map<String, Object> parseObj() throws ParseException {
            Map<String, Object> map = new LinkedHashMap<>();
            pos++;
            skipWs();
            if (pos < s.length() && s.charAt(pos) == '}') { pos++; return map; }
            while (true) {
                skipWs();
                if (pos >= s.length() || s.charAt(pos) != '"') throw new ParseException();
                String key = parseStr();
                skipWs();
                if (pos >= s.length() || s.charAt(pos) != ':') throw new ParseException();
                pos++;
                skipWs();
                Object val = parseValue();
                map.put(key, val);
                skipWs();
                if (pos >= s.length()) throw new ParseException();
                char c = s.charAt(pos);
                if (c == '}') { pos++; return map; }
                if (c == ',') { pos++; continue; }
                throw new ParseException();
            }
        }

        List<Object> parseArr() throws ParseException {
            List<Object> list = new ArrayList<>();
            pos++;
            skipWs();
            if (pos < s.length() && s.charAt(pos) == ']') { pos++; return list; }
            while (true) {
                skipWs();
                Object val = parseValue();
                list.add(val);
                skipWs();
                if (pos >= s.length()) throw new ParseException();
                char c = s.charAt(pos);
                if (c == ']') { pos++; return list; }
                if (c == ',') { pos++; continue; }
                throw new ParseException();
            }
        }

        String parseStr() throws ParseException {
            pos++;
            StringBuilder sb = new StringBuilder();
            while (pos < s.length()) {
                char c = s.charAt(pos);
                if (c == '"') { pos++; return sb.toString(); }
                if (c == '\\') {
                    pos++;
                    if (pos >= s.length()) throw new ParseException();
                    char e = s.charAt(pos); pos++;
                    switch (e) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u':
                            if (pos + 4 > s.length()) throw new ParseException();
                            String hex = s.substring(pos, pos + 4);
                            try { sb.append((char) Integer.parseInt(hex, 16)); }
                            catch (NumberFormatException ex) { throw new ParseException(); }
                            pos += 4;
                            break;
                        default: throw new ParseException();
                    }
                } else if (c < 0x20) {
                    throw new ParseException();
                } else {
                    sb.append(c); pos++;
                }
            }
            throw new ParseException();
        }

        JsonNum parseNum() throws ParseException {
            int start = pos;
            if (pos < s.length() && s.charAt(pos) == '-') pos++;
            if (pos >= s.length()) throw new ParseException();
            char c = s.charAt(pos);
            if (c == '0') { pos++; }
            else if (c >= '1' && c <= '9') { while (pos < s.length() && s.charAt(pos) >= '0' && s.charAt(pos) <= '9') pos++; }
            else throw new ParseException();
            boolean hasFrac = false, hasExp = false;
            if (pos < s.length() && s.charAt(pos) == '.') {
                hasFrac = true; pos++;
                if (pos >= s.length() || s.charAt(pos) < '0' || s.charAt(pos) > '9') throw new ParseException();
                while (pos < s.length() && s.charAt(pos) >= '0' && s.charAt(pos) <= '9') pos++;
            }
            if (pos < s.length() && (s.charAt(pos) == 'e' || s.charAt(pos) == 'E')) {
                hasExp = true; pos++;
                if (pos < s.length() && (s.charAt(pos) == '+' || s.charAt(pos) == '-')) pos++;
                if (pos >= s.length() || s.charAt(pos) < '0' || s.charAt(pos) > '9') throw new ParseException();
                while (pos < s.length() && s.charAt(pos) >= '0' && s.charAt(pos) <= '9') pos++;
            }
            String numStr = s.substring(start, pos);
            boolean isInt = !hasFrac && !hasExp;
            long lv = 0; double dv = 0;
            if (isInt) { lv = Long.parseLong(numStr); dv = (double) lv; }
            else { dv = Double.parseDouble(numStr); lv = (long) dv; }
            return new JsonNum(isInt, lv, dv);
        }
    }

    @SuppressWarnings("unchecked")
    static String toJson(Object val) {
        if (val == null) return "null";
        if (val instanceof Boolean) return val.toString();
        if (val instanceof JsonNum) {
            JsonNum n = (JsonNum) val;
            if (n.isInt) return Long.toString(n.longVal);
            double d = n.dblVal;
            if (d == Math.floor(d) && !Double.isInfinite(d) && Math.abs(d) < 9e15)
                return Long.toString((long) d);
            return Double.toString(d);
        }
        if (val instanceof String) return escStr((String) val);
        if (val instanceof Map) {
            Map<String, Object> m = (Map<String, Object>) val;
            StringBuilder sb = new StringBuilder("{");
            boolean first = true;
            for (Map.Entry<String, Object> e : m.entrySet()) {
                if (!first) sb.append(",");
                sb.append(escStr(e.getKey())).append(":").append(toJson(e.getValue()));
                first = false;
            }
            return sb.append("}").toString();
        }
        if (val instanceof List) {
            List<Object> l = (List<Object>) val;
            StringBuilder sb = new StringBuilder("[");
            boolean first = true;
            for (Object item : l) { if (!first) sb.append(","); sb.append(toJson(item)); first = false; }
            return sb.append("]").toString();
        }
        return "null";
    }

    static String escStr(String s) {
        StringBuilder sb = new StringBuilder("\"");
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                case '\b': sb.append("\\b"); break;
                case '\f': sb.append("\\f"); break;
                default:
                    if (c < 0x20) sb.append(String.format("\\u%04x", (int) c));
                    else sb.append(c);
            }
        }
        return sb.append("\"").toString();
    }

    // Tool definitions
    static class PropDef {
        String name, type; int minLength, minItems;
        PropDef(String n, String t, int ml, int mi) { name=n; type=t; minLength=ml; minItems=mi; }
    }
    static class ToolDef {
        String name, title, desc; List<PropDef> props; Set<String> required; boolean hasOutputSchema;
        ToolDef(String n, String t, String d, List<PropDef> p, Set<String> r, boolean os) {
            name=n; title=t; desc=d; props=p; required=r; hasOutputSchema=os;
        }
    }

