    static String makeResponse(Object id, Map<String,Object> result) {
        Map<String,Object> r = new LinkedHashMap<>();
        r.put("jsonrpc","2.0"); r.put("id",id); r.put("result",result);
        return toJson(r);
    }

    static String makeError(Object id, int code, String msg) {
        Map<String,Object> r = new LinkedHashMap<>();
        r.put("jsonrpc","2.0"); r.put("id",id);
        Map<String,Object> e = new LinkedHashMap<>();
        e.put("code", new JsonNum(true, code, code)); e.put("message", msg);
        r.put("error", e);
        return toJson(r);
    }

    static boolean isValidId(Object val) {
        if (val instanceof String) return true;
        if (val instanceof JsonNum) return ((JsonNum)val).isInt;
        return false;
    }

    static Object getIdForResp(Map<String,Object> msg) {
        if (!msg.containsKey("id")) return null;
        Object id = msg.get("id");
        return isValidId(id) ? id : null;
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        initTools();
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in, StandardCharsets.UTF_8));
        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out, StandardCharsets.UTF_8), false);

        String line;
        while ((line = in.readLine()) != null) {
            if (line.trim().isEmpty()) continue;

            Object parsed;
            try { parsed = new Parser(line).parse(); }
            catch (ParseException ex) { out.println(makeError(null,-32700,"Parse error")); continue; }

            if (!(parsed instanceof Map)) { out.println(makeError(null,-32600,"Invalid Request")); continue; }
            Map<String,Object> msg = (Map<String,Object>) parsed;

            if (!msg.containsKey("method") && (msg.containsKey("result") || msg.containsKey("error"))) continue;

            boolean invalid = false;
            if (!"2.0".equals(msg.get("jsonrpc"))) invalid = true;
            if (!msg.containsKey("method") || !(msg.get("method") instanceof String)) invalid = true;
            if (msg.containsKey("id") && !isValidId(msg.get("id"))) invalid = true;
            if (invalid) { out.println(makeError(getIdForResp(msg),-32600,"Invalid Request")); continue; }

            if (!msg.containsKey("id")) continue;
            Object id = msg.get("id");
            String method = (String) msg.get("method");

            if (!method.equals("initialize") && !method.equals("ping") && !method.equals("tools/list") && !method.equals("tools/call")) {
                out.println(makeError(id,-32601,"Method not found")); continue;
            }
            if (msg.containsKey("params") && !(msg.get("params") instanceof Map)) {
                out.println(makeError(id,-32602,"Invalid params")); continue;
            }
            Map<String,Object> params = msg.containsKey("params") ? (Map<String,Object>) msg.get("params") : null;

            if (!initialized && !method.equals("initialize") && !method.equals("ping")) {
                out.println(makeError(id,-32002,"Server not initialized")); continue;
            }

            String resp;
            switch (method) {
                case "initialize": resp = handleInit(id, params); break;
                case "ping": resp = makeResponse(id, new LinkedHashMap<>()); break;
                case "tools/list": resp = handleToolsList(id); break;
                case "tools/call": resp = handleToolsCall(id, params); break;
                default: resp = makeError(id,-32601,"Method not found");
            }
            out.println(resp);
        }
        out.flush();
    }

    static String handleInit(Object id, Map<String,Object> params) {
        if (initialized) return makeError(id,-32600,"Already initialized");
        if (params == null || !params.containsKey("protocolVersion") || !(params.get("protocolVersion") instanceof String))
            return makeError(id,-32602,"Invalid params");
        String cv = (String) params.get("protocolVersion");
        String sv = (cv.equals("2025-06-18")||cv.equals("2025-03-26")||cv.equals("2024-11-05")) ? cv : "2025-06-18";
        initialized = true;
        Map<String,Object> res = new LinkedHashMap<>();
        res.put("protocolVersion", sv);
        Map<String,Object> caps = new LinkedHashMap<>();
        Map<String,Object> tc = new LinkedHashMap<>(); tc.put("listChanged", false);
        caps.put("tools", tc);
        res.put("capabilities", caps);
        Map<String,Object> si = new LinkedHashMap<>();
        si.put("name","cb2-kv"); si.put("title","CB2 key-value server"); si.put("version","1.4.2");
        res.put("serverInfo", si);
        return makeResponse(id, res);
    }

