    @SuppressWarnings("unchecked")
    static String handleToolsCall(Object id, Map<String,Object> params) {
        if (params == null || !params.containsKey("name") || !(params.get("name") instanceof String))
            return makeError(id,-32602,"Invalid params");
        String toolName = (String) params.get("name");
        ToolDef tool = null;
        for (ToolDef t : tools) if (t.name.equals(toolName)) { tool = t; break; }
        if (tool == null) return makeError(id,-32602,"Unknown tool: "+toolName);

        Map<String,Object> arguments;
        if (!params.containsKey("arguments")) {
            arguments = new LinkedHashMap<>();
        } else {
            Object ao = params.get("arguments");
            if (ao == null || !(ao instanceof Map)) return toolFail(id,"arguments must be an object");
            arguments = (Map<String,Object>) ao;
        }

        Set<String> known = new HashSet<>();
        for (PropDef p : tool.props) known.add(p.name);
        String unknownArg = null;
        for (String k : arguments.keySet()) {
            if (!known.contains(k)) {
                if (unknownArg == null || cmpCP(k, unknownArg) < 0) unknownArg = k;
            }
        }
        if (unknownArg != null) return toolFail(id,"unknown argument: "+unknownArg);

        for (PropDef p : tool.props) {
            boolean present = arguments.containsKey(p.name);
            Object val = present ? arguments.get(p.name) : null;
            if (!present) {
                if (tool.required.contains(p.name)) return toolFail(id,"missing required argument: "+p.name);
                continue;
            }
            if (p.type.equals("string")) {
                if (!(val instanceof String)) return toolFail(id,"argument "+p.name+" must be a string");
                if (p.minLength > 0 && ((String)val).codePointCount(0,((String)val).length()) < p.minLength)
                    return toolFail(id,"argument "+p.name+" must not be empty");
            } else if (p.type.equals("array")) {
                if (!(val instanceof List)) return toolFail(id,"argument "+p.name+" must be an array of integers");
                List<Object> arr = (List<Object>) val;
                if (p.minItems > 0 && arr.size() < p.minItems)
                    return toolFail(id,"argument "+p.name+" must not be empty");
                for (Object el : arr) {
                    if (!(el instanceof JsonNum) || !((JsonNum)el).isInt)
                        return toolFail(id,"argument "+p.name+" must be an array of integers");
                }
            }
        }

        return execTool(id, tool, arguments);
    }

    @SuppressWarnings("unchecked")
    static String execTool(Object id, ToolDef tool, Map<String,Object> args) {
        switch (tool.name) {
            case "kv_set": {
                String k = (String) args.get("key"), v = (String) args.get("value");
                boolean ex = kvStore.containsKey(k); kvStore.put(k,v);
                return toolOk(id,(ex?"updated ":"created ")+k);
            }
            case "kv_get": {
                String k = (String) args.get("key");
                if (!kvStore.containsKey(k)) return toolFail(id,"key not found: "+k);
                return toolOk(id,kvStore.get(k));
            }
            case "kv_list": {
                String prefix = args.containsKey("prefix") ? (String)args.get("prefix") : "";
                List<String> keys = new ArrayList<>();
                for (String k : kvStore.keySet()) if (k.startsWith(prefix)) keys.add(k);
                keys.sort(Main::cmpCP);
                Map<String,Object> sc = new LinkedHashMap<>();
                sc.put("keys", new ArrayList<Object>(keys));
                sc.put("count", new JsonNum(true, keys.size(), keys.size()));
                return toolOkStruct(id, sc);
            }
            case "sum": {
                List<Object> nums = (List<Object>) args.get("numbers");
                long s = 0; for (Object n : nums) s += ((JsonNum)n).longVal;
                Map<String,Object> sc = new LinkedHashMap<>();
                sc.put("sum", new JsonNum(true,s,s));
                sc.put("count", new JsonNum(true,nums.size(),nums.size()));
                return toolOkStruct(id, sc);
            }
            case "text_stats": {
                String text = (String) args.get("text");
                int w = countWords(text);
                int cp = text.codePointCount(0, text.length());
                int ub = text.getBytes(StandardCharsets.UTF_8).length;
                Map<String,Object> sc = new LinkedHashMap<>();
                sc.put("words", new JsonNum(true,w,w));
                sc.put("codepoints", new JsonNum(true,cp,cp));
                sc.put("utf8_bytes", new JsonNum(true,ub,ub));
                return toolOkStruct(id, sc);
            }
        }
        return toolFail(id,"internal error");
    }

    static int countWords(String text) {
        int w = 0; boolean inW = false;
        int i = 0;
        while (i < text.length()) {
            int cp = text.codePointAt(i);
            if (cp==0x20||cp==0x09||cp==0x0A||cp==0x0D) inW=false;
            else { if(!inW) w++; inW=true; }
            i += Character.charCount(cp);
        }
        return w;
    }

    static String toolOk(Object id, String text) {
        Map<String,Object> r = new LinkedHashMap<>();
        List<Object> c = new ArrayList<>();
        Map<String,Object> b = new LinkedHashMap<>(); b.put("type","text"); b.put("text",text); c.add(b);
        r.put("content",c); r.put("isError",false);
        return makeResponse(id,r);
    }

    static String toolOkStruct(Object id, Map<String,Object> sc) {
        String jsonText = toJson(sc);
        Map<String,Object> r = new LinkedHashMap<>();
        List<Object> c = new ArrayList<>();
        Map<String,Object> b = new LinkedHashMap<>(); b.put("type","text"); b.put("text",jsonText); c.add(b);
        r.put("content",c); r.put("structuredContent",sc); r.put("isError",false);
        return makeResponse(id,r);
    }

    static String toolFail(Object id, String msg) {
        Map<String,Object> r = new LinkedHashMap<>();
        List<Object> c = new ArrayList<>();
        Map<String,Object> b = new LinkedHashMap<>(); b.put("type","text"); b.put("text",msg); c.add(b);
        r.put("content",c); r.put("isError",true);
        return makeResponse(id,r);
    }

    static int cmpCP(String a, String b) {
        int i=0, j=0;
        while (i<a.length() && j<b.length()) {
            int ca=a.codePointAt(i), cb=b.codePointAt(j);
            if (ca!=cb) return Integer.compare(ca,cb);
            i+=Character.charCount(ca); j+=Character.charCount(cb);
        }
        return Integer.compare(a.length()-i, b.length()-j);
    }
}

use std::collections::HashMap;
use std::env;
use std::fs;
use std::cmp::Ordering;

const BASE: u64 = 1_000_000_000;

#[derive(Clone, Debug)]
struct BigInt {
    sign: i32, // -1, 0, 1
    mag: Vec<u32>, // least significant first, base 10^9
}

impl BigInt {
    fn zero() -> Self { BigInt { sign: 0, mag: vec![] } }
    fn is_zero(&self) -> bool { self.mag.is_empty() }

    fn normalize(&mut self) {
        while self.mag.last() == Some(&0) { self.mag.pop(); }
        if self.mag.is_empty() { self.sign = 0; }
    }

    fn from_u64(v: u64) -> Self {
        if v == 0 { return Self::zero(); }
        let mut mag = Vec::new();
        let mut val = v;
        while val > 0 {
            mag.push((val % BASE) as u32);
            val /= BASE;
        }
        BigInt { sign: 1, mag }
    }

    fn cmp_mag(&self, other: &Self) -> Ordering {
        if self.mag.len() != other.mag.len() {
            return self.mag.len().cmp(&other.mag.len());
        }
        for i in (0..self.mag.len()).rev() {
            if self.mag[i] != other.mag[i] {
                return self.mag[i].cmp(&other.mag[i]);
            }
        }
        Ordering::Equal
    }

    fn add_mag(&self, other: &Self) -> Self {
        // self and other are non-negative (sign >= 0), returns sum
        let mut result = Vec::new();
        let mut carry: u64 = 0;
        let max_len = self.mag.len().max(other.mag.len());
        for i in 0..max_len {
            let da = if i < self.mag.len() { self.mag[i] as u64 } else { 0 };
            let db = if i < other.mag.len() { other.mag[i] as u64 } else { 0 };
            let sum = da + db + carry;
            result.push((sum % BASE) as u32);
            carry = sum / BASE;
        }
        if carry > 0 { result.push(carry as u32); }
        let mut r = BigInt { sign: 1, mag: result };
        r.normalize();
        r
    }

    fn sub_mag(&self, other: &Self) -> Self {
        // self >= other >= 0, returns self - other
        let mut result = Vec::new();
        let mut borrow: i64 = 0;
        for i in 0..self.mag.len() {
            let da = self.mag[i] as i64;
            let db = if i < other.mag.len() { other.mag[i] as i64 } else { 0 };
            let mut diff = da - db - borrow;
            if diff < 0 {
                diff += BASE as i64;
                borrow = 1;
            } else {
                borrow = 0;
            }
            result.push(diff as u32);
        }
        let mut r = BigInt { sign: 1, mag: result };
        r.normalize();
        r
    }

    fn add(&self, other: &Self) -> Self {
        if self.is_zero() { return other.clone(); }
        if other.is_zero() { return self.clone(); }
        if self.sign == other.sign {
            let mut r = self.add_mag(other);
            r.sign = self.sign;
            r.normalize();
            r
        } else {
            match self.cmp_mag(other) {
                Ordering::Equal => BigInt::zero(),
                Ordering::Greater => {
                    let mut r = self.sub_mag(other);
                    r.sign = self.sign;
                    r.normalize();
                    r
                }
                Ordering::Less => {
                    let mut r = other.sub_mag(self);
                    r.sign = other.sign;
                    r.normalize();
                    r
                }
            }
        }
    }

    fn sub(&self, other: &Self) -> Self {
        let mut nb = other.clone();
        if nb.sign != 0 { nb.sign = -nb.sign; }
        self.add(&nb)
    }

    fn mul(&self, other: &Self) -> Self {
        if self.is_zero() || other.is_zero() { return BigInt::zero(); }
        let mut result = vec![0u64; self.mag.len() + other.mag.len()];
        for i in 0..self.mag.len() {
            let mut carry: u64 = 0;
            for j in 0..other.mag.len() {
                let prod = (self.mag[i] as u64) * (other.mag[j] as u64) + result[i + j] + carry;
                result[i + j] = prod % BASE;
                carry = prod / BASE;
            }
            if carry > 0 { result[i + other.mag.len()] += carry; }
        }
        let mut mag = Vec::new();
        let mut carry: u64 = 0;
        for &v in &result {
            let val = v + carry;
            mag.push((val % BASE) as u32);
            carry = val / BASE;
        }
        while carry > 0 {
            mag.push((carry % BASE) as u32);
            carry /= BASE;
        }
        let mut r = BigInt { sign: self.sign * other.sign, mag };
        r.normalize();
        r
    }

    fn mul_small(&self, n: u32) -> Self {
        if self.is_zero() || n == 0 { return BigInt::zero(); }
        let mut mag = Vec::new();
        let mut carry: u64 = 0;
        for &d in &self.mag {
            let prod = (d as u64) * (n as u64) + carry;
            mag.push((prod % BASE) as u32);
            carry = prod / BASE;
        }
        while carry > 0 {
            mag.push((carry % BASE) as u32);
            carry /= BASE;
        }
        let mut r = BigInt { sign: self.sign, mag };
        r.normalize();
        r
    }

    fn cmp(&self, other: &Self) -> Ordering {
        if self.sign != other.sign {
            return self.sign.cmp(&other.sign);
        }
        if self.sign == 0 { return Ordering::Equal; }
        let c = self.cmp_mag(other);
        if self.sign < 0 { c.reverse() } else { c }
    }

    fn is_odd(&self) -> bool {
        !self.mag.is_empty() && (self.mag[0] % 2 == 1)
    }

    fn to_string(&self) -> String {
        if self.is_zero() { return "0".to_string(); }
        let mut s = String::new();
        if self.sign < 0 { s.push('-'); }
        let last = self.mag.last().unwrap();
        s.push_str(&last.to_string());
        for i in (0..self.mag.len() - 1).rev() {
            s.push_str(&format!("{:09}", self.mag[i]));
        }
        s
    }
}

fn pow10(n: u32) -> BigInt {
    let mut result = BigInt::from_u64(1);
    for _ in 0..n {
        result = result.mul(&BigInt::from_u64(10));
    }
    result
}

fn div_mod_pos(a: &BigInt, b: &BigInt) -> (BigInt, BigInt) {
    // a >= 0, b > 0, returns (a/b, a%b)
    if a.cmp_mag(b) == Ordering::Less {
        return (BigInt::zero(), a.clone());
    }
    let mut quotient = vec![0u32; a.mag.len()];
    let mut remainder = BigInt::zero();

    for i in (0..a.mag.len()).rev() {
        // remainder = remainder * BASE + a.mag[i]
        remainder = remainder.mul_small(BASE as u32);
        remainder = remainder.add(&BigInt::from_u64(a.mag[i] as u64));

        // Binary search for q_digit
        let mut lo: u32 = 0;
        let mut hi: u32 = BASE as u32 - 1;
        while lo < hi {
            let mid = lo + (hi - lo + 1) / 2;
            let product = b.mul_small(mid);
            if product.cmp_mag(&remainder) == Ordering::Greater {
                hi = mid - 1;
            } else {
                lo = mid;
            }
        }
        quotient[i] = lo;
        let product = b.mul_small(lo);
        remainder = remainder.sub_mag(&product);
    }

    while quotient.last() == Some(&0) { quotient.pop(); }
    let q = if quotient.is_empty() { BigInt::zero() } else { BigInt { sign: 1, mag: quotient } };
    (q, remainder)
}

fn round_div(numerator: &BigInt, denominator: &BigInt) -> BigInt {
    // denominator > 0, returns round(numerator/denominator) with round-half-even
    if numerator.is_zero() { return BigInt::zero(); }

    let sign = numerator.sign;
    let abs_num = BigInt { sign: 1, mag: numerator.mag.clone() };

    let (q, r) = div_mod_pos(&abs_num, denominator);

    let two_r = r.mul_small(2);
    let cmp = two_r.cmp_mag(denominator);

    let mut result = q;
    match cmp {
        Ordering::Greater => { result = result.add(&BigInt::from_u64(1)); }
        Ordering::Equal => {
            if result.is_odd() {
                result = result.add(&BigInt::from_u64(1));
            }
        }
        Ordering::Less => {}
    }

    if sign < 0 {
        result.sign = -result.sign;
        result.normalize();
    }
    result
}

#[derive(Clone)]
struct Decimal {
    num: BigInt,
    scale: u32,
}

fn parse_decimal(s: &str) -> Decimal {
    let (neg, rest) = if s.starts_with('-') {
        (true, &s[1..])
    } else if s.starts_with('+') {
        (false, &s[1..])
    } else {
        (false, s)
    };

    let (int_part, frac_part) = if let Some(dot_pos) = rest.find('.') {
        (&rest[..dot_pos], &rest[dot_pos+1..])
    } else {
        (rest, "")
    };

    let all_digits = format!("{}{}", int_part, frac_part);
    let scale = frac_part.len() as u32;

    // Parse all_digits as BigInt (remove leading zeros)
    let trimmed = all_digits.trim_start_matches('0');
    let mut num = if trimmed.is_empty() {
        BigInt::zero()
    } else {
        parse_bigint_str(trimmed)
    };

    if neg && !num.is_zero() {
        num.sign = -1;
    }

    Decimal { num, scale }
}

fn parse_bigint_str(s: &str) -> BigInt {
    // s is a string of digits (no leading zeros, no sign)
    let mut mag = Vec::new();
    let bytes = s.as_bytes();
    let len = bytes.len();
    // Process from right in groups of 9
    let mut i = len;
    while i > 0 {
        let start = if i >= 9 { i - 9 } else { 0 };
        let group = &s[start..i];
        let val: u32 = group.parse().unwrap();
        mag.push(val);
        i = start;
    }
    let mut r = BigInt { sign: 1, mag };
    r.normalize();
    r
}

fn round_to_minor(dec: &Decimal, minor_units: u32) -> BigInt {
    if dec.scale <= minor_units {
        let factor = pow10(minor_units - dec.scale);
        dec.num.mul(&factor)
    } else {
        let divisor = pow10(dec.scale - minor_units);
        round_div(&dec.num, &divisor)
    }
}

fn format_comma(s: &str) -> String {
    let mut result = String::new();
    let len = s.len();
    for (i, ch) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(ch);
    }
    result
}

fn format_money(value: &BigInt, minor_units: u32) -> String {
    if value.is_zero() {
        if minor_units == 0 {
            return "0".to_string();
        } else {
            return format!("0.{}", "0".repeat(minor_units as usize));
        }
    }

    let neg = value.sign < 0;
    let abs_val = BigInt { sign: 1, mag: value.mag.clone() };

    let (int_part, frac_part) = if minor_units == 0 {
        (abs_val, BigInt::zero())
    } else {
        div_mod_pos(&abs_val, &pow10(minor_units))
    };

    let int_str = format_comma(&int_part.to_string());

    let mut s = String::new();
    if neg { s.push('-'); }

    if minor_units == 0 {
        s.push_str(&int_str);
    } else {
        s.push_str(&int_str);
        s.push('.');
        let frac_str = frac_part.to_string();
        let pad = minor_units as usize - frac_str.len();
        for _ in 0..pad { s.push('0'); }
        s.push_str(&frac_str);
    }

    s
}

struct Currency {
    minor_units: u32,
}

struct Account {
    code: String,
    balance: BigInt, // in minor units
    limit: BigInt,   // in minor units, non-negative
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let content = fs::read_to_string(format!("{}/ledger.txt", dir)).unwrap();

    let mut currencies: HashMap<String, Currency> = HashMap::new();
    let mut accounts: HashMap<String, Account> = HashMap::new();
    let mut rejections: Vec<String> = Vec::new();

    for (line_num, line) in content.lines().enumerate() {
        let n = line_num + 1;
        let trimmed = line.trim();

        // Skip blank lines and comments
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        // Parse fields
        let fields: Vec<&str> = trimmed.split_whitespace().collect();
        let cmd = fields[0];

        match cmd {
            "currency" => {
                let code = fields[1].to_string();
                let minor: u32 = fields[2].parse().unwrap();
                currencies.insert(code, Currency { minor_units: minor });
            }
            "open" => {
                let name = fields[1];
                let code = fields[2];

                // Check if account exists
                if accounts.contains_key(name) {
                    rejections.push(format!("line {}: REJECT account exists {}", n, name));
                    continue;
                }

                let currency = currencies.get(code).unwrap();
                let minor = currency.minor_units;
                let limit = if fields.len() > 3 {
                    let dec = parse_decimal(fields[3]);
                    let l = round_to_minor(&dec, minor);
                    // limit should be non-negative? The spec says "overdraft limit" so probably non-negative.
                    // But what if someone gives a negative limit? Let's just use it as-is.
                    // Actually, let's take absolute value? No, let's just use it.
                    // The spec says "the balance may go down to -limit but not below".
                    // If limit is negative, then -limit is positive, meaning balance can't go below a positive number?
                    // That seems weird. Let's just store it as given.
                    l
                } else {
                    BigInt::zero()
                };

                accounts.insert(name.to_string(), Account {
                    code: code.to_string(),
                    balance: BigInt::zero(),
                    limit,
                });
            }
            "deposit" => {
                let name = fields[1];
                let amount_str = fields[2];

                // Check unknown account
                if !accounts.contains_key(name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", n, name));
                    continue;
                }

                let acc = accounts.get(name).unwrap();
                let minor = currencies[&acc.code].minor_units;
                let dec = parse_decimal(amount_str);
                let amount = round_to_minor(&dec, minor);

                // Check non-positive
                if amount.cmp(&BigInt::zero()) != Ordering::Greater {
                    rejections.push(format!("line {}: REJECT non-positive amount", n));
                    continue;
                }

                let new_balance = acc.balance.add(&amount);
                accounts.get_mut(name).unwrap().balance = new_balance;
            }
            "withdraw" => {
                let name = fields[1];
                let amount_str = fields[2];

                if !accounts.contains_key(name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", n, name));
                    continue;
                }

                let acc = accounts.get(name).unwrap();
                let minor = currencies[&acc.code].minor_units;
                let dec = parse_decimal(amount_str);
                let amount = round_to_minor(&dec, minor);

                if amount.cmp(&BigInt::zero()) != Ordering::Greater {
                    rejections.push(format!("line {}: REJECT non-positive amount", n));
                    continue;
                }

                // Check insufficient funds
                let new_balance = acc.balance.sub(&amount);
                let min_allowed = acc.limit.mul_small(0); // wait, this is wrong
                // min_allowed = -limit
                let min_allowed = BigInt { sign: if acc.limit.is_zero() { 0 } else { -1 }, mag: acc.limit.mag.clone() };

                if new_balance.cmp(&min_allowed) == Ordering::Less {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", n, name));
                    continue;
                }

                accounts.get_mut(name).unwrap().balance = new_balance;
            }
            "transfer" => {
                let from = fields[1];
                let to = fields[2];
                let amount_str = fields[3];

                // Check unknown accounts
                if !accounts.contains_key(from) {
                    rejections.push(format!("line {}: REJECT unknown account {}", n, from));
                    continue;
                }
                if !accounts.contains_key(to) {
                    rejections.push(format!("line {}: REJECT unknown account {}", n, to));
                    continue;
                }

                // Currency mismatch
                let from_code = accounts[from].code.clone();
                let to_code = accounts[to].code.clone();
                if from_code != to_code {
                    rejections.push(format!("line {}: REJECT currency mismatch", n));
                    continue;
                }

                let minor = currencies[&from_code].minor_units;
                let dec = parse_decimal(amount_str);
                let amount = round_to_minor(&dec, minor);

                if amount.cmp(&BigInt::zero()) != Ordering::Greater {
                    rejections.push(format!("line {}: REJECT non-positive amount", n));
                    continue;
                }

                // Insufficient funds
                let new_from_balance = accounts[from].balance.sub(&amount);
                let min_allowed = negate(&accounts[from].limit);
                if new_from_balance.cmp(&min_allowed) == Ordering::Less {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", n, from));
                    continue;
                }

                accounts.get_mut(from).unwrap().balance = new_from_balance;
                let new_to_balance = accounts[to].balance.add(&amount);
                accounts.get_mut(to).unwrap().balance = new_to_balance;
            }
            "convert" => {
                let from = fields[1];
                let to = fields[2];
                let amount_str = fields[3];
                let rate_str = fields[4];

                if !accounts.contains_key(from) {
                    rejections.push(format!("line {}: REJECT unknown account {}", n, from));
                    continue;
                }
                if !accounts.contains_key(to) {
                    rejections.push(format!("line {}: REJECT unknown account {}", n, to));
                    continue;
                }

                let from_code = accounts[from].code.clone();
                let to_code = accounts[to].code.clone();
                let from_minor = currencies[&from_code].minor_units;
                let to_minor = currencies[&to_code].minor_units;

                let dec = parse_decimal(amount_str);
                let amount = round_to_minor(&dec, from_minor);

                if amount.cmp(&BigInt::zero()) != Ordering::Greater {
                    rejections.push(format!("line {}: REJECT non-positive amount", n));
                    continue;
                }

                // Insufficient funds
                let new_from_balance = accounts[from].balance.sub(&amount);
                let min_allowed = negate(&accounts[from].limit);
                if new_from_balance.cmp(&min_allowed) == Ordering::Less {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", n, from));
                    continue;
                }

                // Compute converted amount
                let rate_dec = parse_decimal(rate_str);
                // amount (in from minor units) * rate, rounded to to_minor decimal places
                // = amount * rate_num / 10^rate_scale, rounded to to_minor decimal places
                // = round(amount * rate_num * 10^to_minor / 10^rate_scale)
                let numerator = amount.mul(&rate_dec.num).mul(&pow10(to_minor));
                let denominator = pow10(rate_dec.scale);
                let received = round_div(&numerator, &denominator);

                accounts.get_mut(from).unwrap().balance = new_from_balance;
                let new_to_balance = accounts[to].balance.add(&received);
                accounts.get_mut(to).unwrap().balance = new_to_balance;
            }
            "interest" => {
                let name = fields[1];
                let rate_str = fields[2];

                if !accounts.contains_key(name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", n, name));
                    continue;
                }

                let acc = accounts.get(name).unwrap();
                let minor = currencies[&acc.code].minor_units;
                let rate_dec = parse_decimal(rate_str);

                // interest = balance * rate, rounded to minor units
                // balance is in minor units (integer)
                // rate = rate_num / 10^rate_scale
                // interest_minor = round(balance * rate_num / 10^rate_scale)
                // = round(balance * rate_num * 10^minor / 10^(rate_scale + minor))
                // Hmm wait. balance is already in minor units. So:
                // interest (in minor units) = round(balance * rate_num / 10^rate_scale)
                let numerator = acc.balance.mul(&rate_dec.num);
                let denominator = pow10(rate_dec.scale);
                let interest = round_div(&numerator, &denominator);

                let new_balance = acc.balance.add(&interest);
                accounts.get_mut(name).unwrap().balance = new_balance;
            }
            "split" => {
                let from = fields[1];
                let amount_str = fields[2];

                // Parse targets
                let mut targets: Vec<(String, u64)> = Vec::new(); // (name, weight)
                // Wait, weights could be larger than u64? Let me use BigInt for weights too.
                // Actually, let's parse them as BigInt.
                let mut target_names: Vec<String> = Vec::new();
                let mut target_weights: Vec<BigInt> = Vec::new();

                for i in 3..fields.len() {
                    let parts: Vec<&str> = fields[i].splitn(2, ':').collect();
                    let tname = parts[0].to_string();
                    let tweight = parse_bigint_str(parts[1].trim_start_matches('0'));
                    // Hmm, what if weight is "0"? The spec says weights are positive integers.
                    // But we should handle it. Actually the spec says weights are positive, so they're >= 1.
                    // But let's handle "0" gracefully just in case. Actually if weight is 0, parse_bigint_str("") would fail.
                    // Let me just parse normally.
                    target_names.push(tname);
                    target_weights.push(tweight);
                }

                // Check unknown accounts: from first, then targets
                if !accounts.contains_key(from) {
                    rejections.push(format!("line {}: REJECT unknown account {}", n, from));
                    continue;
                }
                for tname in &target_names {
                    if !accounts.contains_key(tname) {
                        rejections.push(format!("line {}: REJECT unknown account {}", n, tname));
                        break; // Only report first unknown
                    }
                }
                // Hmm wait, I need to check all targets and report the first unknown. Let me redo this.

                // Actually let me redo the unknown account check properly
                let mut unknown_found = false;
                if !accounts.contains_key(from) {
                    rejections.push(format!("line {}: REJECT unknown account {}", n, from));
                    unknown_found = true;
                }
                if !unknown_found {
                    for tname in &target_names {
                        if !accounts.contains_key(tname) {
                            rejections.push(format!("line {}: REJECT unknown account {}", n, tname));
                            unknown_found = true;
                            break;
                        }
                    }
                }
                if unknown_found { continue; }

                // Currency mismatch
                let from_code = accounts[from].code.clone();
                let mut mismatch = false;
                for tname in &target_names {
                    if accounts[tname].code != from_code {
                        mismatch = true;
                        break;
                    }
                }
                if mismatch {
                    rejections.push(format!("line {}: REJECT currency mismatch", n));
                    continue;
                }

                let minor = currencies[&from_code].minor_units;
                let dec = parse_decimal(amount_str);
                let amount = round_to_minor(&dec, minor);

                if amount.cmp(&BigInt::zero()) != Ordering::Greater {
                    rejections.push(format!("line {}: REJECT non-positive amount", n));
                    continue;
                }

                // Insufficient funds
                let new_from_balance = accounts[from].balance.sub(&amount);
                let min_allowed = negate(&accounts[from].limit);
                if new_from_balance.cmp(&min_allowed) == Ordering::Less {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", n, from));
                    continue;
                }

                // Compute split
                let w_sum = {
                    let mut s = BigInt::zero();
                    for w in &target_weights {
                        s = s.add(w);
                    }
                    s
                };

                let n_targets = target_names.len();
                let mut base_amounts: Vec<BigInt> = Vec::new();
                let mut remainders: Vec<BigInt> = Vec::new();

                for w in &target_weights {
                    let product = amount.mul(w);
                    let (base, rem) = div_mod_pos(&product, &w_sum);
                    base_amounts.push(base);
                    remainders.push(rem);
                }

                let total_base = {
                    let mut s = BigInt::zero();
                    for b in &base_amounts {
                        s = s.add(b);
                    }
                    s
                };

                let leftover = amount.sub(&total_base);
                // leftover is a non-negative integer < n_targets
                // Convert to u32 for indexing
                let leftover_n = if leftover.is_zero() { 0 } else { leftover.mag[0] as usize };

                // Sort by remainder descending, stable
                let mut indices: Vec<usize> = (0..n_targets).collect();
                indices.sort_by(|&a, &b| {
                    remainders[b].cmp(&remainders[a]) // descending
                });
                // Rust's sort_by is stable, so equal remainders keep original order. ✓

                // Distribute leftover
                for i in 0..leftover_n {
                    base_amounts[indices[i]] = base_amounts[indices[i]].add(&BigInt::from_u64(1));
                }

                // Apply
                accounts.get_mut(from).unwrap().balance = new_from_balance;
                for i in 0..n_targets {
                    let tname = &target_names[i];
                    let new_bal = accounts[tname].balance.add(&base_amounts[i]);
                    accounts.get_mut(tname.as_str()).unwrap().balance = new_bal;
                }
            }
            _ => {}
        }
    }

    // Output
    for r in &rejections {
        println!("{}", r);
    }
    println!();

    // Accounts sorted by name
    let mut account_names: Vec<&String> = accounts.keys().collect();
    account_names.sort();
    for name in &account_names {
        let acc = &accounts[*name];
        let minor = currencies[&acc.code].minor_units;
        println!("{} {} {}", name, acc.code, format_money(&acc.balance, minor));
    }
    println!();

    // Currency totals
    let mut currency_accounts: HashMap<String, (BigInt, u32)> = HashMap::new();
    for acc in accounts.values() {
        let entry = currency_accounts.entry(acc.code.clone()).or_insert((BigInt::zero(), 0));
        entry.0 = entry.0.add(&acc.balance);
        entry.1 += 1;
    }

    let mut codes: Vec<String> = currency_accounts.keys().cloned().collect();
    codes.sort();
    for code in &codes {
        let (total, count) = &currency_accounts[code];
        let minor = currencies[code].minor_units;
        println!("total {} {} ({} accounts)", code, format_money(total, minor), count);
    }
}

fn negate(b: &BigInt) -> BigInt {
    if b.is_zero() { return BigInt::zero(); }
    BigInt { sign: -b.sign, mag: b.mag.clone() }
}

use std::collections::HashMap;
use std::env;
use std::fs;
use std::cmp::Ordering;

const BASE: u64 = 1_000_000_000;

#[derive(Clone, Debug)]
struct BigInt {
    sign: i32,
    mag: Vec<u32>,
}

impl BigInt {
    fn zero() -> Self { BigInt { sign: 0, mag: vec![] } }
    fn is_zero(&self) -> bool { self.mag.is_empty() }

    fn normalize(&mut self) {
        while self.mag.last() == Some(&0) { self.mag.pop(); }
        if self.mag.is_empty() { self.sign = 0; }
    }

    fn from_u64(v: u64) -> Self {
        if v == 0 { return Self::zero(); }
        let mut mag = Vec::new();
        let mut val = v;
        while val > 0 {
            mag.push((val % BASE) as u32);
            val /= BASE;
        }
        BigInt { sign: 1, mag }
    }

    fn cmp_mag(&self, other: &Self) -> Ordering {
        if self.mag.len() != other.mag.len() {
            return self.mag.len().cmp(&other.mag.len());
        }
        for i in (0..self.mag.len()).rev() {
            if self.mag[i] != other.mag[i] {
                return self.mag[i].cmp(&other.mag[i]);
            }
        }
        Ordering::Equal
    }

    fn add_mag(&self, other: &Self) -> Self {
        let mut result = Vec::new();
        let mut carry: u64 = 0;
        let max_len = self.mag.len().max(other.mag.len());
        for i in 0..max_len {
            let da = if i < self.mag.len() { self.mag[i] as u64 } else { 0 };
            let db = if i < other.mag.len() { other.mag[i] as u64 } else { 0 };
            let sum = da + db + carry;
            result.push((sum % BASE) as u32);
            carry = sum / BASE;
        }
        if carry > 0 { result.push(carry as u32); }
        let mut r = BigInt { sign: 1, mag: result };
        r.normalize();
        r
    }

    fn sub_mag(&self, other: &Self) -> Self {
        let mut result = Vec::new();
        let mut borrow: i64 = 0;
        for i in 0..self.mag.len() {
            let da = self.mag[i] as i64;
            let db = if i < other.mag.len() { other.mag[i] as i64 } else { 0 };
            let mut diff = da - db - borrow;
            if diff < 0 {
                diff += BASE as i64;
                borrow = 1;
            } else {
                borrow = 0;
            }
            result.push(diff as u32);
        }
        let mut r = BigInt { sign: 1, mag: result };
        r.normalize();
        r
    }

    fn add(&self, other: &Self) -> Self {
        if self.is_zero() { return other.clone(); }
        if other.is_zero() { return self.clone(); }
        if self.sign == other.sign {
            let mut r = self.add_mag(other);
            r.sign = self.sign;
            r.normalize();
            r
        } else {
            match self.cmp_mag(other) {
                Ordering::Equal => BigInt::zero(),
                Ordering::Greater => {
                    let mut r = self.sub_mag(other);
                    r.sign = self.sign;
                    r.normalize();
                    r
                }
                Ordering::Less => {
                    let mut r = other.sub_mag(self);
                    r.sign = other.sign;
                    r.normalize();
                    r
                }
            }
        }
    }

    fn sub(&self, other: &Self) -> Self {
        let mut nb = other.clone();
        if nb.sign != 0 { nb.sign = -nb.sign; }
        self.add(&nb)
    }

    fn mul(&self, other: &Self) -> Self {
        if self.is_zero() || other.is_zero() { return BigInt::zero(); }
        let mut result = vec![0u64; self.mag.len() + other.mag.len()];
        for i in 0..self.mag.len() {
            let mut carry: u64 = 0;
            for j in 0..other.mag.len() {
                let prod = (self.mag[i] as u64) * (other.mag[j] as u64) + result[i + j] + carry;
                result[i + j] = prod % BASE;
                carry = prod / BASE;
            }
            let mut k = i + other.mag.len();
            while carry > 0 {
                let sum = result[k] + carry;
                result[k] = sum % BASE;
                carry = sum / BASE;
                k += 1;
            }
        }
        let mut mag = Vec::new();
        let mut carry: u64 = 0;
        for &v in &result {
            let val = v + carry;
            mag.push((val % BASE) as u32);
            carry = val / BASE;
        }
        while carry > 0 {
            mag.push((carry % BASE) as u32);
            carry /= BASE;
        }
        let mut r = BigInt { sign: self.sign * other.sign, mag };
        r.normalize();
        r
    }

    fn mul_small(&self, n: u32) -> Self {
        if self.is_zero() || n == 0 { return BigInt::zero(); }
        let mut mag = Vec::new();
        let mut carry: u64 = 0;
        for &d in &self.mag {
            let prod = (d as u64) * (n as u64) + carry;
            mag.push((prod % BASE) as u32);
            carry = prod / BASE;
        }
        while carry > 0 {
            mag.push((carry % BASE) as u32);
            carry /= BASE;
        }
        let mut r = BigInt { sign: self.sign, mag };
        r.normalize();
        r
    }

    fn cmp(&self, other: &Self) -> Ordering {
        if self.sign != other.sign {
            return self.sign.cmp(&other.sign);
        }
        if self.sign == 0 { return Ordering::Equal; }
        let c = self.cmp_mag(other);
        if self.sign < 0 { c.reverse() } else { c }
    }

    fn is_odd(&self) -> bool {
        !self.mag.is_empty() && (self.mag[0] % 2 == 1)
    }

    fn to_string(&self) -> String {
        if self.is_zero() { return "0".to_string(); }
        let mut s = String::new();
        if self.sign < 0 { s.push('-'); }
        let last = self.mag.last().unwrap();
        s.push_str(&last.to_string());
        for i in (0..self.mag.len() - 1).rev() {
            s.push_str(&format!("{:09}", self.mag[i]));
        }
        s
    }
}

fn pow10(n: u32) -> BigInt {
    let mut result = BigInt::from_u64(1);
    for _ in 0..n {
        result = result.mul(&BigInt::from_u64(10));
    }
    result
}

fn div_mod_pos(a: &BigInt, b: &BigInt) -> (BigInt, BigInt) {
    if a.cmp_mag(b) == Ordering::Less {
        return (BigInt::zero(), a.clone());
    }
    let mut quotient = vec![0u32; a.mag.len()];
    let mut remainder = BigInt::zero();

    for i in (0..a.mag.len()).rev() {
        remainder = remainder.mul_small(BASE as u32);
        remainder = remainder.add(&BigInt::from_u64(a.mag[i] as u64));

        let mut lo: u32 = 0;
        let mut hi: u32 = BASE as u32 - 1;
        while lo < hi {
            let mid = lo + (hi - lo + 1) / 2;
            let product = b.mul_small(mid);
            if product.cmp_mag(&remainder) == Ordering::Greater {
                hi = mid - 1;
            } else {
                lo = mid;
            }
        }
        quotient[i] = lo;
        let product = b.mul_small(lo);
        remainder = remainder.sub_mag(&product);
    }

    while quotient.last() == Some(&0) { quotient.pop(); }
    let q = if quotient.is_empty() { BigInt::zero() } else { BigInt { sign: 1, mag: quotient } };
    (q, remainder)
}

fn round_div(numerator: &BigInt, denominator: &BigInt) -> BigInt {
    if numerator.is_zero() { return BigInt::zero(); }

    let sign = numerator.sign;
    let abs_num = BigInt { sign: 1, mag: numerator.mag.clone() };

    let (q, r) = div_mod_pos(&abs_num, denominator);

    let two_r = r.mul_small(2);
    let cmp = two_r.cmp_mag(denominator);

    let mut result = q;
    match cmp {
        Ordering::Greater => { result = result.add(&BigInt::from_u64(1)); }
        Ordering::Equal => {
            if result.is_odd() {
                result = result.add(&BigInt::from_u64(1));
            }
        }
        Ordering::Less => {}
    }

    if sign < 0 {
        result.sign = -result.sign;
        result.normalize();
    }
    result
}

#[derive(Clone)]
struct Decimal {
    num: BigInt,
    scale: u32,
}

fn parse_decimal(s: &str) -> Decimal {
    let (neg, rest) = if s.starts_with('-') {
        (true, &s[1..])
    } else if s.starts_with('+') {
        (false, &s[1..])
    } else {
        (false, s)
    };

    let (int_part, frac_part) = if let Some(dot_pos) = rest.find('.') {
        (&rest[..dot_pos], &rest[dot_pos+1..])
    } else {
        (rest, "")
    };

    let all_digits = format!("{}{}", int_part, frac_part);
    let scale = frac_part.len() as u32;

    let trimmed = all_digits.trim_start_matches('0');
    let mut num = if trimmed.is_empty() {
        BigInt::zero()
    } else {
        parse_bigint_str(trimmed)
    };

    if neg && !num.is_zero() {
        num.sign = -1;
    }

    Decimal { num, scale }
}

fn parse_bigint_str(s: &str) -> BigInt {
    let mut mag = Vec::new();
    let bytes = s.as_bytes();
    let len = bytes.len();
    let mut i = len;
    while i > 0 {
        let start = if i >= 9 { i - 9 } else { 0 };
        let group = &s[start..i];
        let val: u32 = group.parse().unwrap();
        mag.push(val);
        i = start;
    }
    let mut r = BigInt { sign: 1, mag };
    r.normalize();
    r
}

fn round_to_minor(dec: &Decimal, minor_units: u32) -> BigInt {
    if dec.scale <= minor_units {
        let factor = pow10(minor_units - dec.scale);
        dec.num.mul(&factor)
    } else {
        let divisor = pow10(dec.scale - minor_units);
        round_div(&dec.num, &divisor)
    }
}

fn format_comma(s: &str) -> String {
    let mut result = String::new();
    let len = s.len();
    for (i, ch) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(ch);
    }
    result
}

fn format_money(value: &BigInt, minor_units: u32) -> String {
    if value.is_zero() {
        if minor_units == 0 {
            return "0".to_string();
        } else {
            return format!("0.{}", "0".repeat(minor_units as usize));
        }
    }

    let neg = value.sign < 0;
    let abs_val = BigInt { sign: 1, mag: value.mag.clone() };

    let (int_part, frac_part) = if minor_units == 0 {
        (abs_val, BigInt::zero())
    } else {
        div_mod_pos(&abs_val, &pow10(minor_units))
    };

    let int_str = format_comma(&int_part.to_string());

    let mut s = String::new();
    if neg { s.push('-'); }

    if minor_units == 0 {
        s.push_str(&int_str);
    } else {
        s.push_str(&int_str);
        s.push('.');
        let frac_str = frac_part.to_string();
        let pad = minor_units as usize - frac_str.len();
        for _ in 0..pad { s.push('0'); }
        s.push_str(&frac_str);
    }

    s
}

fn negate(b: &BigInt) -> BigInt {
    if b.is_zero() { return BigInt::zero(); }
    BigInt { sign: -b.sign, mag: b.mag.clone() }
}

struct Currency {
    minor_units: u32,
}

struct Account {
    code: String,
    balance: BigInt,
    limit: BigInt,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let content = fs::read_to_string(format!("{}/ledger.txt", dir)).unwrap();

    let mut currencies: HashMap<String, Currency> = HashMap::new();
    let mut accounts: HashMap<String, Account> = HashMap::new();
    let mut rejections: Vec<String> = Vec::new();

    for (line_num, line) in content.lines().enumerate() {
        let n = line_num + 1;
        let trimmed = line.trim();

        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }

        let fields: Vec<&str> = trimmed.split_whitespace().collect();
        let cmd = fields[0];

        match cmd {
            "currency" => {
                let code = fields[1].to_string();
                let minor: u32 = fields[2].parse().unwrap();
                currencies.insert(code, Currency { minor_units: minor });
            }
            "open" => {
                let name = fields[1];
                let code = fields[2];

                if accounts.contains_key(name) {
                    rejections.push(format!("line {}: REJECT account exists {}", n, name));
                    continue;
                }

                let currency = currencies.get(code).unwrap();
                let minor = currency.minor_units;
                let limit = if fields.len() > 3 {
                    let dec = parse_decimal(fields[3]);
                    round_to_minor(&dec, minor)
                } else {
                    BigInt::zero()
                };

                accounts.insert(name.to_string(), Account {
                    code: code.to_string(),
                    balance: BigInt::zero(),
                    limit,
                });
            }
            "deposit" => {
                let name = fields[1];
                let amount_str = fields[2];

                if !accounts.contains_key(name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", n, name));
                    continue;
                }

                let acc = accounts.get(name).unwrap();
                let minor = currencies[&acc.code].minor_units;
                let dec = parse_decimal(amount_str);
                let amount = round_to_minor(&dec, minor);

                if amount.cmp(&BigInt::zero()) != Ordering::Greater {
                    rejections.push(format!("line {}: REJECT non-positive amount", n));
                    continue;
                }

                let new_balance = acc.balance.add(&amount);
                accounts.get_mut(name).unwrap().balance = new_balance;
            }
            "withdraw" => {
                let name = fields[1];
                let amount_str = fields[2];

                if !accounts.contains_key(name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", n, name));
                    continue;
                }

                let acc = accounts.get(name).unwrap();
                let minor = currencies[&acc.code].minor_units;
                let dec = parse_decimal(amount_str);
                let amount = round_to_minor(&dec, minor);

                if amount.cmp(&BigInt::zero()) != Ordering::Greater {
                    rejections.push(format!("line {}: REJECT non-positive amount", n));
                    continue;
                }

                let new_balance = acc.balance.sub(&amount);
                let min_allowed = negate(&acc.limit);

                if new_balance.cmp(&min_allowed) == Ordering::Less {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", n, name));
                    continue;
                }

                accounts.get_mut(name).unwrap().balance = new_balance;
            }
            "transfer" => {
                let from = fields[1];
                let to = fields[2];
                let amount_str = fields[3];

                if !accounts.contains_key(from) {
                    rejections.push(format!("line {}: REJECT unknown account {}", n, from));
                    continue;
                }
                if !accounts.contains_key(to) {
                    rejections.push(format!("line {}: REJECT unknown account {}", n, to));
                    continue;
                }

                let from_code = accounts[from].code.clone();
                let to_code = accounts[to].code.clone();
                if from_code != to_code {
                    rejections.push(format!("line {}: REJECT currency mismatch", n));
                    continue;
                }

                let minor = currencies[&from_code].minor_units;
                let dec = parse_decimal(amount_str);
                let amount = round_to_minor(&dec, minor);

                if amount.cmp(&BigInt::zero()) != Ordering::Greater {
                    rejections.push(format!("line {}: REJECT non-positive amount", n));
                    continue;
                }

                let new_from_balance = accounts[from].balance.sub(&amount);
                let min_allowed = negate(&accounts[from].limit);
                if new_from_balance.cmp(&min_allowed) == Ordering::Less {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", n, from));
                    continue;
                }

                accounts.get_mut(from).unwrap().balance = new_from_balance;
                let new_to_balance = accounts[to].balance.add(&amount);
                accounts.get_mut(to).unwrap().balance = new_to_balance;
            }
            "convert" => {
                let from = fields[1];
                let to = fields[2];
                let amount_str = fields[3];
                let rate_str = fields[4];

                if !accounts.contains_key(from) {
                    rejections.push(format!("line {}: REJECT unknown account {}", n, from));
                    continue;
                }
                if !accounts.contains_key(to) {
                    rejections.push(format!("line {}: REJECT unknown account {}", n, to));
                    continue;
                }

                let from_code = accounts[from].code.clone();
                let to_code = accounts[to].code.clone();
                let from_minor = currencies[&from_code].minor_units;
                let to_minor = currencies[&to_code].minor_units;

                let dec = parse_decimal(amount_str);
                let amount = round_to_minor(&dec, from_minor);

                if amount.cmp(&BigInt::zero()) != Ordering::Greater {
                    rejections.push(format!("line {}: REJECT non-positive amount", n));
                    continue;
                }

                let new_from_balance = accounts[from].balance.sub(&amount);
                let min_allowed = negate(&accounts[from].limit);
                if new_from_balance.cmp(&min_allowed) == Ordering::Less {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", n, from));
                    continue;
                }

                // amount is in from_minor units, rate = rate_num / 10^rate_scale
                // converted value in to currency = amount / 10^from_minor * rate
                // in to_minor units: round(amount * rate_num * 10^to_minor / 10^(from_minor + rate_scale))
                let rate_dec = parse_decimal(rate_str);
                let numerator = amount.mul(&rate_dec.num).mul(&pow10(to_minor));
                let denominator = pow10(from_minor + rate_dec.scale);
                let received = round_div(&numerator, &denominator);

                accounts.get_mut(from).unwrap().balance = new_from_balance;
                let new_to_balance = accounts[to].balance.add(&received);
                accounts.get_mut(to).unwrap().balance = new_to_balance;
            }
            "interest" => {
                let name = fields[1];
                let rate_str = fields[2];

                if !accounts.contains_key(name) {
                    rejections.push(format!("line {}: REJECT unknown account {}", n, name));
                    continue;
                }

                let acc = accounts.get(name).unwrap();
                let rate_dec = parse_decimal(rate_str);

                // balance is in minor units, rate is dimensionless
                // interest_minor = round(balance_minor * rate_num / 10^rate_scale)
                let numerator = acc.balance.mul(&rate_dec.num);
                let denominator = pow10(rate_dec.scale);
                let interest = round_div(&numerator, &denominator);

                let new_balance = acc.balance.add(&interest);
                accounts.get_mut(name).unwrap().balance = new_balance;
            }
            "split" => {
                let from = fields[1];
                let amount_str = fields[2];

                let mut target_names: Vec<String> = Vec::new();
                let mut target_weights: Vec<BigInt> = Vec::new();

                for i in 3..fields.len() {
                    let parts: Vec<&str> = fields[i].splitn(2, ':').collect();
                    let tname = parts[0].to_string();
                    let wstr = parts[1].trim_start_matches('0');
                    let tweight = if wstr.is_empty() { BigInt::zero() } else { parse_bigint_str(wstr) };
                    target_names.push(tname);
                    target_weights.push(tweight);
                }

                let mut unknown_found = false;
                if !accounts.contains_key(from) {
                    rejections.push(format!("line {}: REJECT unknown account {}", n, from));
                    unknown_found = true;
                }
                if !unknown_found {
                    for tname in &target_names {
                        if !accounts.contains_key(tname) {
                            rejections.push(format!("line {}: REJECT unknown account {}", n, tname));
                            unknown_found = true;
                            break;
                        }
                    }
                }
                if unknown_found { continue; }

                let from_code = accounts[from].code.clone();
                let mut mismatch = false;
                for tname in &target_names {
                    if accounts[tname].code != from_code {
                        mismatch = true;
                        break;
                    }
                }
                if mismatch {
                    rejections.push(format!("line {}: REJECT currency mismatch", n));
                    continue;
                }

                let minor = currencies[&from_code].minor_units;
                let dec = parse_decimal(amount_str);
                let amount = round_to_minor(&dec, minor);

                if amount.cmp(&BigInt::zero()) != Ordering::Greater {
                    rejections.push(format!("line {}: REJECT non-positive amount", n));
                    continue;
                }

                let new_from_balance = accounts[from].balance.sub(&amount);
                let min_allowed = negate(&accounts[from].limit);
                if new_from_balance.cmp(&min_allowed) == Ordering::Less {
                    rejections.push(format!("line {}: REJECT insufficient funds {}", n, from));
                    continue;
                }

                let w_sum = {
                    let mut s = BigInt::zero();
                    for w in &target_weights {
                        s = s.add(w);
                    }
                    s
                };

                let n_targets = target_names.len();
                let mut base_amounts: Vec<BigInt> = Vec::new();
                let mut remainders: Vec<BigInt> = Vec::new();

                for w in &target_weights {
                    let product = amount.mul(w);
                    let (base, rem) = div_mod_pos(&product, &w_sum);
                    base_amounts.push(base);
                    remainders.push(rem);
                }

                let total_base = {
                    let mut s = BigInt::zero();
                    for b in &base_amounts {
                        s = s.add(b);
                    }
                    s
                };

                let leftover = amount.sub(&total_base);
                let leftover_n = if leftover.is_zero() { 0usize } else { leftover.mag[0] as usize };

                let mut indices: Vec<usize> = (0..n_targets).collect();
                indices.sort_by(|&a, &b| {
                    remainders[b].cmp(&remainders[a])
                });

                for i in 0..leftover_n {
                    base_amounts[indices[i]] = base_amounts[indices[i]].add(&BigInt::from_u64(1));
                }

                accounts.get_mut(from).unwrap().balance = new_from_balance;
                for i in 0..n_targets {
                    let tname = &target_names[i];
                    let new_bal = accounts[tname].balance.add(&base_amounts[i]);
                    accounts.get_mut(tname.as_str()).unwrap().balance = new_bal;
                }
            }
            _ => {}
        }
    }

    for r in &rejections {
        println!("{}", r);
    }
    println!();

    let mut account_names: Vec<&String> = accounts.keys().collect();
    account_names.sort();
    for name in &account_names {
        let acc = &accounts[*name];
        let minor = currencies[&acc.code].minor_units;
        println!("{} {} {}", name, acc.code, format_money(&acc.balance, minor));
    }
    println!();

    let mut currency_accounts: HashMap<String, (BigInt, u32)> = HashMap::new();
    for acc in accounts.values() {
        let entry = currency_accounts.entry(acc.code.clone()).or_insert((BigInt::zero(), 0));
        entry.0 = entry.0.add(&acc.balance);
        entry.1 += 1;
    }

    let mut codes: Vec<String> = currency_accounts.keys().cloned().collect();
    codes.sort();
    for code in &codes {
        let (total, count) = &currency_accounts[code];
        let minor = currencies[code].minor_units;
        println!("total {} {} ({} accounts)", code, format_money(total, minor), count);
    }
}

use std::collections::HashSet;
use std::env;
use std::fs;

// ============ SHA-256 ============
const K256: [u32; 64] = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

fn sha256(data: &[u8]) -> [u8; 32] {
    let mut h: [u32; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
        0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
    ];
    let msg_len = data.len();
    let zeros = (64usize.wrapping_sub((msg_len + 9) % 64)) % 64;
    let mut padded = Vec::with_capacity(msg_len + 1 + zeros + 8);
    padded.extend_from_slice(data);
    padded.push(0x80);
    padded.extend_from_slice(&vec![0u8; zeros]);
    padded.extend_from_slice(&((msg_len as u64) * 8).to_be_bytes());

    for block in padded.chunks(64) {
        let mut w = [0u32; 64];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([block[i*4], block[i*4+1], block[i*4+2], block[i*4+3]]);
        }
        for i in 16..64 {
            let s0 = w[i-15].rotate_right(7) ^ w[i-15].rotate_right(18) ^ (w[i-15] >> 3);
            let s1 = w[i-2].rotate_right(17) ^ w[i-2].rotate_right(19) ^ (w[i-2] >> 10);
            w[i] = w[i-16].wrapping_add(s0).wrapping_add(w[i-7]).wrapping_add(s1);
        }
        let mut a = h[0]; let mut b = h[1]; let mut c = h[2]; let mut d = h[3];
        let mut e = h[4]; let mut f = h[5]; let mut g = h[6]; let mut hh = h[7];
        for i in 0..64 {
            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
            let ch = (e & f) ^ (!e & g);
            let temp1 = hh.wrapping_add(s1).wrapping_add(ch).wrapping_add(K256[i]).wrapping_add(w[i]);
            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let temp2 = s0.wrapping_add(maj);
            hh = g; g = f; f = e; e = d.wrapping_add(temp1);
            d = c; c = b; b = a; a = temp1.wrapping_add(temp2);
        }
        h[0] = h[0].wrapping_add(a); h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c); h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e); h[5] = h[5].wrapping_add(f);
        h[6] = h[6].wrapping_add(g); h[7] = h[7].wrapping_add(hh);
    }
    let mut out = [0u8; 32];
    for i in 0..8 { out[i*4..i*4+4].copy_from_slice(&h[i].to_be_bytes()); }
    out
}

