// ============ HMAC ============
fn hmac(key: &[u8], message: &[u8], block_size: usize, hash_fn: fn(&[u8]) -> Vec<u8>) -> Vec<u8> {
    let mut k = key.to_vec();
    if k.len() > block_size {
        k = hash_fn(&k);
    }
    k.resize(block_size, 0);
    let ipad: Vec<u8> = k.iter().map(|b| b ^ 0x36).collect();
    let opad: Vec<u8> = k.iter().map(|b| b ^ 0x5c).collect();
    let mut inner = ipad;
    inner.extend_from_slice(message);
    let inner_hash = hash_fn(&inner);
    let mut outer = opad;
    outer.extend_from_slice(&inner_hash);
    hash_fn(&outer)
}

fn hmac_sha256(key: &[u8], message: &[u8]) -> Vec<u8> {
    hmac(key, message, 64, |d| sha256(d).to_vec())
}
fn hmac_sha384(key: &[u8], message: &[u8]) -> Vec<u8> {
    hmac(key, message, 128, |d| sha384(d).to_vec())
}
fn hmac_sha512(key: &[u8], message: &[u8]) -> Vec<u8> {
    hmac(key, message, 128, |d| sha512(d).to_vec())
}

// ============ Base64url ============
fn base64url_valid(s: &str) -> bool {
    if s.is_empty() { return false; }
    if s.len() % 4 == 1 { return false; }
    for c in s.chars() {
        if !c.is_ascii_alphanumeric() && c != '-' && c != '_' {
            return false;
        }
    }
    true
}

fn base64url_decode(s: &str) -> Vec<u8> {
    let mut result = Vec::new();
    let mut bit_buf: u32 = 0;
    let mut bit_count: u32 = 0;
    for c in s.chars() {
        let v: u32 = match c {
            'A'..='Z' => (c as u32) - ('A' as u32),
            'a'..='z' => (c as u32) - ('a' as u32) + 26,
            '0'..='9' => (c as u32) - ('0' as u32) + 52,
            '-' => 62,
            '_' => 63,
            _ => unreachable!(),
        };
        bit_buf = (bit_buf << 6) | v;
        bit_count += 6;
        if bit_count >= 8 {
            bit_count -= 8;
            result.push((bit_buf >> bit_count) as u8);
        }
    }
    result
}

// ============ JSON ============
#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        if let Json::Obj(fields) = self {
            for (k, v) in fields {
                if k == key { return Some(v); }
            }
        }
        None
    }
}

struct JParser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> JParser<'a> {
    fn new(s: &'a str) -> Self {
        JParser { input: s.as_bytes(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn peek(&self) -> Option<u8> {
        if self.pos < self.input.len() { Some(self.input[self.pos]) } else { None }
    }

    fn parse_value(&mut self) -> Result<Json, &'static str> {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => self.parse_string().map(Json::Str),
            Some(b't') => self.expect_lit(b"true").map(|_| Json::Bool(true)),
            Some(b'f') => self.expect_lit(b"false").map(|_| Json::Bool(false)),
            Some(b'n') => self.expect_lit(b"null").map(|_| Json::Null),
            Some(c) if c == b'-' || c.is_ascii_digit() => self.parse_number(),
            _ => Err("invalid value"),
        }
    }

    fn expect_lit(&mut self, lit: &[u8]) -> Result<(), &'static str> {
        if self.pos + lit.len() <= self.input.len() && &self.input[self.pos..self.pos+lit.len()] == lit {
            self.pos += lit.len();
            Ok(())
        } else {
            Err("invalid literal")
        }
    }

    fn parse_object(&mut self) -> Result<Json, &'static str> {
        self.pos += 1; // {
        let mut fields = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') { self.pos += 1; return Ok(Json::Obj(fields)); }
        loop {
            self.skip_ws();
            if self.peek() != Some(b'"') { return Err("expected key"); }
            let key = self.parse_string()?;
            self.skip_ws();
            if self.peek() != Some(b':') { return Err("expected colon"); }
            self.pos += 1;
            let val = self.parse_value()?;
            fields.push((key, val));
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b'}') => { self.pos += 1; break; }
                _ => return Err("expected , or }"),
            }
        }
        Ok(Json::Obj(fields))
    }

    fn parse_array(&mut self) -> Result<Json, &'static str> {
        self.pos += 1; // [
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') { self.pos += 1; return Ok(Json::Arr(items)); }
        loop {
            let val = self.parse_value()?;
            items.push(val);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b']') => { self.pos += 1; break; }
                _ => return Err("expected , or ]"),
            }
        }
        Ok(Json::Arr(items))
    }

    fn parse_string(&mut self) -> Result<String, &'static str> {
        self.pos += 1; // opening "
        let mut s = String::new();
        loop {
            if self.pos >= self.input.len() { return Err("unterminated string"); }
            let c = self.input[self.pos];
            match c {
                b'"' => { self.pos += 1; return Ok(s); }
                b'\\' => {
                    self.pos += 1;
                    if self.pos >= self.input.len() { return Err("unterminated escape"); }
                    let e = self.input[self.pos];
                    self.pos += 1;
                    match e {
                        b'"' => s.push('"'),
                        b'\\' => s.push('\\'),
                        b'/' => s.push('/'),
                        b'b' => s.push('\u{0008}'),
                        b'f' => s.push('\u{000C}'),
                        b'n' => s.push('\n'),
                        b'r' => s.push('\r'),
                        b't' => s.push('\t'),
                        b'u' => {
                            let cp = self.parse_hex4()?;
                            if cp >= 0xD800 && cp <= 0xDBFF {
                                // high surrogate, expect low surrogate
                                if self.pos + 1 < self.input.len() && self.input[self.pos] == b'\\' && self.input[self.pos+1] == b'u' {
                                    self.pos += 2;
                                    let lo = self.parse_hex4()?;
                                    if lo >= 0xDC00 && lo <= 0xDFFF {
                                        let full = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                        s.push(char::from_u32(full).unwrap_or('\u{FFFD}'));
                                    } else {
                                        s.push('\u{FFFD}');
                                        if let Some(ch) = char::from_u32(lo) { s.push(ch); }
                                    }
                                } else {
                                    s.push('\u{FFFD}');
                                }
                            } else {
                                s.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                            }
                        }
                        _ => return Err("invalid escape"),
                    }
                }
                _ => {
                    // raw byte, collect UTF-8 sequence
                    let start = self.pos;
                    self.pos += 1;
                    // handle multi-byte UTF-8
                    if c >= 0x80 {
                        let extra = if c < 0xC0 { 0 } else if c < 0xE0 { 1 } else if c < 0xF0 { 2 } else { 3 };
                        for _ in 0..extra {
                            if self.pos < self.input.len() { self.pos += 1; }
                        }
                    }
                    s.push_str(std::str::from_utf8(&self.input[start..self.pos]).unwrap_or("\u{FFFD}"));
                }
            }
        }
    }

    fn parse_hex4(&mut self) -> Result<u32, &'static str> {
        if self.pos + 4 > self.input.len() { return Err("hex too short"); }
        let mut val: u32 = 0;
        for i in 0..4 {
            let c = self.input[self.pos + i];
            let d = match c {
                b'0'..=b'9' => (c - b'0') as u32,
                b'a'..=b'f' => (c - b'a') as u32 + 10,
                b'A'..=b'F' => (c - b'A') as u32 + 10,
                _ => return Err("invalid hex"),
            };
            val = val * 16 + d;
        }
        self.pos += 4;
        Ok(val)
    }

    fn parse_number(&mut self) -> Result<Json, &'static str> {
        let start = self.pos;
        if self.peek() == Some(b'-') { self.pos += 1; }
        while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        if self.pos < self.input.len() && self.input[self.pos] == b'.' {
            self.pos += 1;
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        if self.pos < self.input.len() && (self.input[self.pos] == b'e' || self.input[self.pos] == b'E') {
            self.pos += 1;
            if self.pos < self.input.len() && (self.input[self.pos] == b'+' || self.input[self.pos] == b'-') { self.pos += 1; }
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        let s = std::str::from_utf8(&self.input[start..self.pos]).map_err(|_| "invalid number")?;
        s.parse::<f64>().map(Json::Num).map_err(|_| "invalid number")
    }
}

fn parse_json(s: &str) -> Result<Json, &'static str> {
    let mut p = JParser::new(s);
    let v = p.parse_value()?;
    p.skip_ws();
    if p.pos != p.input.len() { return Err("trailing content"); }
    Ok(v)
}

// ============ Main ============
fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let config_str = fs::read_to_string(format!("{}/config.json", dir)).unwrap();
    let config = parse_json(&config_str).unwrap();

    let now = match config.get("now") { Some(Json::Num(n)) => *n, _ => 0.0 };
    let leeway = match config.get("leeway") { Some(Json::Num(n)) => *n, _ => 0.0 };
    let issuer = match config.get("issuer") { Some(Json::Str(s)) => s.clone(), _ => String::new() };
    let audience = match config.get("audience") { Some(Json::Str(s)) => s.clone(), _ => String::new() };

    // Parse keys
    let mut keys: Vec<(String, String, String, Vec<u8>)> = Vec::new(); // kid, kty, alg, secret_bytes
    if let Some(Json::Arr(key_arr)) = config.get("keys") {
        for k in key_arr {
            let kid = match k.get("kid") { Some(Json::Str(s)) => s.clone(), _ => continue };
            let kty = match k.get("kty") { Some(Json::Str(s)) => s.clone(), _ => continue };
            let alg = match k.get("alg") { Some(Json::Str(s)) => s.clone(), _ => continue };
            let k_val = match k.get("k") { Some(Json::Str(s)) => s.clone(), _ => continue };
            let secret = base64url_decode(&k_val);
            keys.push((kid, kty, alg, secret));
        }
    }

    // Read tokens
    let tokens_str = fs::read_to_string(format!("{}/tokens.txt", dir)).unwrap();
    let lines: Vec<&str> = tokens_str.split('\n').collect();

    let mut valid_count = 0;
    let mut invalid_count = 0;
    let mut output = String::new();
    let mut token_num = 0;

    for line in lines {
        let trimmed = line.trim_matches(|c| c == ' ' || c == '\t' || c == '\r');
        if trimmed.is_empty() { continue; }
        token_num += 1;
        let token = trimmed;

        let result = validate_token(token, now, leeway, &issuer, &audience, &keys);
        if result.starts_with("VALID") {
            valid_count += 1;
        } else {
            invalid_count += 1;
        }
        output.push_str(&format!("{}: {}\n", token_num, result));
    }

    output.push('\n');
    output.push_str(&format!("valid={} invalid={}", valid_count, invalid_count));
    print!("{}", output);
}

fn validate_token(
    token: &str,
    now: f64,
    leeway: f64,
    issuer: &str,
    audience: &str,
    keys: &[(String, String, String, Vec<u8>)],
) -> String {
    // Rule 1: MALFORMED
    let parts: Vec<&str> = token.split('.').collect();
    if parts.len() != 3 { return "MALFORMED".to_string(); }

    for &p in &parts {
        if !base64url_valid(p) { return "MALFORMED".to_string(); }
    }

    let header_bytes = base64url_decode(parts[0]);
    let payload_bytes = base64url_decode(parts[1]);

    let header_str = match std::str::from_utf8(&header_bytes) {
        Ok(s) => s,
        Err(_) => return "MALFORMED".to_string(),
    };
    let payload_str = match std::str::from_utf8(&payload_bytes) {
        Ok(s) => s,
        Err(_) => return "MALFORMED".to_string(),
    };

    let header = match parse_json(header_str) {
        Ok(Json::Obj(_)) => parse_json(header_str).unwrap(),
        _ => return "MALFORMED".to_string(),
    };
    let payload = match parse_json(payload_str) {
        Ok(Json::Obj(_)) => parse_json(payload_str).unwrap(),
        _ => return "MALFORMED".to_string(),
    };

    // Rule 2: UNSUPPORTED_ALG
    let alg = match header.get("alg") {
        Some(Json::Str(s)) => s.clone(),
        _ => return "UNSUPPORTED_ALG".to_string(),
    };
    if alg != "HS256" && alg != "HS384" && alg != "HS512" {
        return "UNSUPPORTED_ALG".to_string();
    }

    // Rule 3: UNKNOWN_KEY
    let kid = match header.get("kid") {
        Some(Json::Str(s)) => s.clone(),
        _ => return "UNKNOWN_KEY".to_string(),
    };
    let key_idx = keys.iter().position(|(k, _, _, _)| k == &kid);
    let key_idx = match key_idx {
        Some(i) => i,
        None => return "UNKNOWN_KEY".to_string(),
    };

    // Rule 4: ALG_MISMATCH
    if keys[key_idx].2 != alg {
        return "ALG_MISMATCH".to_string();
    }

    // Rule 5: BAD_SIGNATURE
    let signing_input = format!("{}.{}", parts[0], parts[1]).into_bytes();
    let secret = &keys[key_idx].3;
    let expected_sig = match alg.as_str() {
        "HS256" => hmac_sha256(secret, &signing_input),
        "HS384" => hmac_sha384(secret, &signing_input),
        "HS512" => hmac_sha512(secret, &signing_input),
        _ => unreachable!(),
    };
    let actual_sig = base64url_decode(parts[2]);
    if actual_sig != expected_sig {
        return "BAD_SIGNATURE".to_string();
    }

    // Rule 6: EXPIRED
    if let Some(Json::Num(exp)) = payload.get("exp") {
        if now >= *exp + leeway { return "EXPIRED".to_string(); }
    }

    // Rule 7: NOT_YET_VALID
    if let Some(Json::Num(nbf)) = payload.get("nbf") {
        if now + leeway < *nbf { return "NOT_YET_VALID".to_string(); }
    }

    // Rule 8: BAD_ISSUER
    match payload.get("iss") {
        Some(Json::Str(s)) if s == issuer => {}
        _ => return "BAD_ISSUER".to_string(),
    }

    // Rule 9: BAD_AUDIENCE
    match payload.get("aud") {
        Some(Json::Str(s)) if s == audience => {}
        Some(Json::Arr(items)) => {
            let found = items.iter().any(|item| matches!(item, Json::Str(s) if s == audience));
            if !found { return "BAD_AUDIENCE".to_string(); }
        }
        _ => return "BAD_AUDIENCE".to_string(),
    }

    // VALID
    let sub = match payload.get("sub") {
        Some(Json::Str(s)) => s.clone(),
        _ => String::new(),
    };
    let scope_str = match payload.get("scope") {
        Some(Json::Str(s)) => s.clone(),
        _ => String::new(),
    };
    let mut scope_set: HashSet<String> = HashSet::new();
    for piece in scope_str.split(' ') {
        if !piece.is_empty() {
            scope_set.insert(piece.to_string());
        }
    }
    let mut scopes: Vec<String> = scope_set.into_iter().collect();
    scopes.sort();
    let scopes_joined = scopes.join(",");

    format!("VALID sub={} scope={}", sub, scopes_joined)
}

import Foundation

// MARK: - JSON Value (preserves int vs float distinction)
enum JV {
    case null
    case bool(Bool)
    case int(Int64)
    case double(Double)
    case string(String)
    case array([JV])
    case object([(String, JV)])
}

// MARK: - JSON Parser
struct JSONParser {
    let chars: [Character]
    var pos: Int
    init(_ s: String) { chars = Array(s); pos = 0 }

    mutating func skipWS() {
        while pos < chars.count {
            let c = chars[pos]
            if c == " " || c == "\t" || c == "\n" || c == "\r" { pos += 1 } else { break }
        }
    }

    mutating func parse() -> JV? {
        skipWS()
        guard let v = parseValue() else { return nil }
        skipWS()
        guard pos == chars.count else { return nil }
        return v
    }

    mutating func parseValue() -> JV? {
        skipWS()
        guard pos < chars.count else { return nil }
        let c = chars[pos]
        switch c {
        case "n": return parseKeyword("null", .null)
        case "t": return parseKeyword("true", .bool(true))
        case "f": return parseKeyword("false", .bool(false))
        case "\"": return parseStringVal()
        case "[": return parseArrayVal()
        case "{": return parseObjectVal()
        default:
            if c == "-" || (c >= "0" && c <= "9") { return parseNumberVal() }
            return nil
        }
    }

    mutating func parseKeyword(_ kw: String, _ val: JV) -> JV? {
        let n = kw.count
        guard pos + n <= chars.count else { return nil }
        let sub = String(chars[pos..<pos+n])
        guard sub == kw else { return nil }
        pos += n
        return val
    }

    mutating func parseStringVal() -> JV? {
        guard pos < chars.count && chars[pos] == "\"" else { return nil }
        pos += 1
        var s = ""
        while pos < chars.count {
            let c = chars[pos]
            if c == "\"" { pos += 1; return .string(s) }
            if c == "\\" {
                pos += 1
                guard pos < chars.count else { return nil }
                let e = chars[pos]
                switch e {
                case "\"": s.append("\""); pos += 1
                case "\\": s.append("\\"); pos += 1
                case "/": s.append("/"); pos += 1
                case "b": s.append("\u{08}"); pos += 1
                case "f": s.append("\u{0C}"); pos += 1
                case "n": s.append("\n"); pos += 1
                case "r": s.append("\r"); pos += 1
                case "t": s.append("\t"); pos += 1
                case "u":
                    pos += 1
                    guard pos + 4 <= chars.count else { return nil }
                    let hex = String(chars[pos..<pos+4])
                    guard let code = UInt32(hex, radix: 16) else { return nil }
                    pos += 4
                    if code >= 0xD800 && code <= 0xDBFF {
                        guard pos + 6 <= chars.count && chars[pos] == "\\" && chars[pos+1] == "u" else { return nil }
                        pos += 2
                        let hex2 = String(chars[pos..<pos+4])
                        guard let code2 = UInt32(hex2, radix: 16) else { return nil }
                        pos += 4
                        guard code2 >= 0xDC00 && code2 <= 0xDFFF else { return nil }
                        let combined = 0x10000 + ((code - 0xD800) << 10) + (code2 - 0xDC00)
                        guard let scalar = Unicode.Scalar(combined) else { return nil }
                        s.append(Character(scalar))
                    } else if code >= 0xD800 && code <= 0xDFFF {
                        return nil
                    } else {
                        guard let scalar = Unicode.Scalar(code) else { return nil }
                        s.append(Character(scalar))
                    }
                default: return nil
                }
            } else {
                s.append(c); pos += 1
            }
        }
        return nil
    }

    mutating func parseNumberVal() -> JV? {
        let start = pos
        var isInt = true
        if pos < chars.count && chars[pos] == "-" { pos += 1 }
        guard pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" else { return nil }
        if chars[pos] == "0" { pos += 1 }
        else { while pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" { pos += 1 } }
        if pos < chars.count && chars[pos] == "." {
            isInt = false; pos += 1
            guard pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" else { return nil }
            while pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" { pos += 1 }
        }
        if pos < chars.count && (chars[pos] == "e" || chars[pos] == "E") {
            isInt = false; pos += 1
            if pos < chars.count && (chars[pos] == "+" || chars[pos] == "-") { pos += 1 }
            guard pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" else { return nil }
            while pos < chars.count && chars[pos] >= "0" && chars[pos] <= "9" { pos += 1 }
        }
        let numStr = String(chars[start..<pos])
        if isInt {
            if let i = Int64(numStr) { return .int(i) }
            return .double(Double(numStr) ?? 0)
        } else {
            guard let d = Double(numStr) else { return nil }
            return .double(d)
        }
    }

    mutating func parseArrayVal() -> JV? {
        guard pos < chars.count && chars[pos] == "[" else { return nil }
        pos += 1
        var arr: [JV] = []
        skipWS()
        if pos < chars.count && chars[pos] == "]" { pos += 1; return .array(arr) }
        while true {
            guard let v = parseValue() else { return nil }
            arr.append(v)
            skipWS()
            guard pos < chars.count else { return nil }
            if chars[pos] == "]" { pos += 1; return .array(arr) }
            guard chars[pos] == "," else { return nil }
            pos += 1
        }
    }

    mutating func parseObjectVal() -> JV? {
        guard pos < chars.count && chars[pos] == "{" else { return nil }
        pos += 1
        var obj: [(String, JV)] = []
        skipWS()
        if pos < chars.count && chars[pos] == "}" { pos += 1; return .object(obj) }
        while true {
            skipWS()
            guard case .some(.string(let key)) = parseStringVal() else { return nil }
            skipWS()
            guard pos < chars.count && chars[pos] == ":" else { return nil }
            pos += 1
            guard let val = parseValue() else { return nil }
            obj.append((key, val))
            skipWS()
            guard pos < chars.count else { return nil }
            if chars[pos] == "}" { pos += 1; return .object(obj) }
            guard chars[pos] == "," else { return nil }
            pos += 1
        }
    }
}

// MARK: - JSON Serializer
func escStr(_ s: String) -> String {
    var r = "\""
    for c in s.unicodeScalars {
        switch c {
        case "\"": r += "\\\""
        case "\\": r += "\\\\"
        case "\n": r += "\\n"
        case "\r": r += "\\r"
        case "\t": r += "\\t"
        default:
            if c.value < 0x20 { r += String(format: "\\u%04x", c.value) }
            else { r.unicodeScalars.append(c) }
        }
    }
    r += "\""
    return r
}

func ser(_ v: JV) -> String {
    switch v {
    case .null: return "null"
    case .bool(true): return "true"
    case .bool(false): return "false"
    case .int(let i): return "\(i)"
    case .double(let d):
        if d == d.rounded() && abs(d) < 1e15 { return String(format: "%.0f", d) }
        return "\(d)"
    case .string(let s): return escStr(s)
    case .array(let arr): return "[" + arr.map(ser).joined(separator: ",") + "]"
    case .object(let pairs): return "{" + pairs.map { "\(escStr($0.0)):\(ser($0.1))" }.joined(separator: ",") + "}"
    }
}

// MARK: - Helpers
func objGet(_ obj: [(String, JV)], _ key: String) -> JV? {
    for (k, v) in obj { if k == key { return v } }
    return nil
}

func cpLess(_ a: String, _ b: String) -> Bool {
    let aS = Array(a.unicodeScalars)
    let bS = Array(b.unicodeScalars)
    let n = min(aS.count, bS.count)
    for i in 0..<n {
        if aS[i].value != bS[i].value { return aS[i].value < bS[i].value }
    }
    return aS.count < bS.count
}

func countWords(_ text: String) -> Int {
    var cnt = 0
    var inWord = false
    for c in text {
        if c == " " || c == "\t" || c == "\n" || c == "\r" {
            inWord = false
        } else {
            if !inWord { cnt += 1; inWord = true }
        }
    }
    return cnt
}

// MARK: - Tool Schema Definitions
struct PropDef {
    let name: String
    let type: String
    let minLength: Int?
    let minItems: Int?
}

let toolProps: [String: [PropDef]] = [
    "kv_set": [PropDef(name:"key",type:"string",minLength:1,minItems:nil),
               PropDef(name:"value",type:"string",minLength:nil,minItems:nil)],
    "kv_get": [PropDef(name:"key",type:"string",minLength:1,minItems:nil)],
    "kv_list": [PropDef(name:"prefix",type:"string",minLength:nil,minItems:nil)],
    "sum": [PropDef(name:"numbers",type:"array",minLength:nil,minItems:1)],
    "text_stats": [PropDef(name:"text",type:"string",minLength:nil,minItems:nil)]
]

let toolRequired: [String: [String]] = [
    "kv_set": ["key","value"],
    "kv_get": ["key"],
    "kv_list": [],
    "sum": ["numbers"],
    "text_stats": ["text"]
]

let validToolNames = ["kv_set","kv_get","kv_list","sum","text_stats"]

// MARK: - Main
var initialized = false
var store: [String: String] = [:]

let data = FileHandle.standardInput.readDataToEndOfFile()
let text = String(data: data, encoding: .utf8) ?? ""
let lines = text.components(separatedBy: "\n")

var outputLines: [String] = []

for rawLine in lines {
    var line = rawLine
    if line.hasSuffix("\r") { line = String(line.dropLast()) }

    // skip blank lines
    var blank = true
    for c in line { if c != " " && c != "\t" && c != "\r" { blank = false; break } }
    if blank { continue }

    // 1. Parse JSON
    var parser = JSONParser(line)
    guard let json = parser.parse() else {
        outputLines.append(ser(.object([
            ("jsonrpc", .string("2.0")),
            ("id", .null),
            ("error", .object([("code", .int(-32700)), ("message", .string("Parse error"))]))
        ])))
        continue
    }

    // 2. Must be an object
    guard case .object(let obj) = json else {
        outputLines.append(ser(.object([
            ("jsonrpc", .string("2.0")),
            ("id", .null),
            ("error", .object([("code", .int(-32600)), ("message", .string("Invalid Request"))]))
        ])))
        continue
    }

    // 3. Client response?
    let hasMethod = objGet(obj, "method") != nil
    let hasResult = objGet(obj, "result") != nil
    let hasError = objGet(obj, "error") != nil
    if !hasMethod && (hasResult || hasError) { continue }

    // 4. Validity check
    var isValid = true
    let jsonrpcVal = objGet(obj, "jsonrpc")
    if case .string(let s) = jsonrpcVal { if s != "2.0" { isValid = false } } else { isValid = false }
    let methodVal = objGet(obj, "method")
    if case .string = methodVal { } else { isValid = false }

    let idVal = objGet(obj, "id")
    let hasId = idVal != nil
    var validId: JV? = nil
    if hasId {
        switch idVal! {
        case .string(let s): validId = .string(s)
        case .int(let i): validId = .int(i)
        default: break
        }
    }

    if !isValid || (hasId && validId == nil) {
        let rid: JV = validId ?? .null
        outputLines.append(ser(.object([
            ("jsonrpc", .string("2.0")),
            ("id", rid),
            ("error", .object([("code", .int(-32600)), ("message", .string("Invalid Request"))]))
        ])))
        continue
    }

    // 5. Notification
    if !hasId { continue }

    // 6. Request
    guard case .string(let method) = methodVal else { continue }
    let rid = validId!

    // 6a. Method not found
    let validMethods = ["initialize","ping","tools/list","tools/call"]
    if !validMethods.contains(method) {
        outputLines.append(ser(.object([
            ("jsonrpc", .string("2.0")),
            ("id", rid),
            ("error", .object([("code", .int(-32601)), ("message", .string("Method not found"))]))
        ])))
        continue
    }

    // 6b. params present but not object
    let paramsVal = objGet(obj, "params")
    if let pv = paramsVal {
        if case .object = pv { } else {
            outputLines.append(ser(.object([
                ("jsonrpc", .string("2.0")),
                ("id", rid),
                ("error", .object([("code", .int(-32602)), ("message", .string("Invalid params"))]))
            ])))
            continue
        }
    }

    // 6c. Not initialized
    if !initialized && method != "initialize" && method != "ping" {
        outputLines.append(ser(.object([
            ("jsonrpc", .string("2.0")),
            ("id", rid),
            ("error", .object([("code", .int(-32002)), ("message", .string("Server not initialized"))]))
        ])))
        continue
    }

    // 6d. Dispatch
    switch method {
    case "initialize":
        if initialized {
            outputLines.append(ser(.object([
                ("jsonrpc", .string("2.0")),
                ("id", rid),
                ("error", .object([("code", .int(-32600)), ("message", .string("Already initialized"))]))
            ])))
            continue
        }
        guard let params = paramsVal, case .object(let p) = params else {
            outputLines.append(ser(.object([
                ("jsonrpc", .string("2.0")),
                ("id", rid),
                ("error", .object([("code", .int(-32602)), ("message", .string("Invalid params"))]))
            ])))
            continue
        }
        let pv = objGet(p, "protocolVersion")
        guard case .string(let version) = pv else {
            outputLines.append(ser(.object([
                ("jsonrpc", .string("2.0")),
                ("id", rid),
                ("error", .object([("code", .int(-32602)), ("message", .string("Invalid params"))]))
            ])))
            continue
        }
        let supported = ["2025-06-18","2025-03-26","2024-11-05"]
        let rv = supported.contains(version) ? version : "2025-06-18"
        initialized = true
        let result: JV = .object([
            ("protocolVersion", .string(rv)),
            ("capabilities", .object([("tools", .object([("listChanged", .bool(false))]))])),
            ("serverInfo", .object([("name", .string("cb2-kv")),("title", .string("CB2 key-value server")),("version", .string("1.4.2"))]))
        ])
        outputLines.append(ser(.object([("jsonrpc", .string("2.0")),("id", rid),("result", result)])))

    case "ping":
        outputLines.append(ser(.object([("jsonrpc", .string("2.0")),("id", rid),("result", .object([]))])))

    case "tools/list":
        let tools: JV = .array([
            .object([
                ("name", .string("kv_set")),
                ("title", .string("Set a value")),
                ("description", .string("Store a string value under a key, replacing any previous value.")),
                ("inputSchema", .object([
                    ("type", .string("object")),
                    ("properties", .object([
                        ("key", .object([("type", .string("string")),("minLength", .int(1))])),
                        ("value", .object([("type", .string("string"))]))
                    ])),
                    ("required", .array([.string("key"), .string("value")])),
                    ("additionalProperties", .bool(false))
                ]))
            ]),
            .object([
                ("name", .string("kv_get")),
                ("title", .string("Get a value")),
                ("description", .string("Return the value stored under a key.")),
                ("inputSchema", .object([
                    ("type", .string("object")),
                    ("properties", .object([
                        ("key", .object([("type", .string("string")),("minLength", .int(1))]))
                    ])),
                    ("required", .array([.string("key")])),
                    ("additionalProperties", .bool(false))
                ]))
            ]),
            .object([
                ("name", .string("kv_list")),
                ("title", .string("List keys")),
                ("description", .string("List the stored keys that start with a prefix, sorted by Unicode code point.")),
                ("inputSchema", .object([
                    ("type", .string("object")),
                    ("properties", .object([
                        ("prefix", .object([("type", .string("string"))]))
                    ])),
                    ("additionalProperties", .bool(false))
                ])),
                ("outputSchema", .object([
                    ("type", .string("object")),
                    ("properties", .object([
                        ("keys", .object([("type", .string("array")),("items", .object([("type", .string("string"))]))])),
                        ("count", .object([("type", .string("integer"))]))
                    ])),
                    ("required", .array([.string("keys"), .string("count")]))
                ]))
            ]),
            .object([
                ("name", .string("sum")),
                ("title", .string("Sum integers")),
                ("description", .string("Add up a non-empty list of integers.")),
                ("inputSchema", .object([
                    ("type", .string("object")),
                    ("properties", .object([
                        ("numbers", .object([("type", .string("array")),("items", .object([("type", .string("integer"))])),("minItems", .int(1))]))
                    ])),
                    ("required", .array([.string("numbers")])),
                    ("additionalProperties", .bool(false))
                ])),
                ("outputSchema", .object([
                    ("type", .string("object")),
                    ("properties", .object([
                        ("sum", .object([("type", .string("integer"))])),
                        ("count", .object([("type", .string("integer"))]))
                    ])),
                    ("required", .array([.string("sum"), .string("count")]))
                ])),
                ("annotations", .object([("readOnlyHint", .bool(true)),("idempotentHint", .bool(true))]))
            ]),
            .object([
                ("name", .string("text_stats")),
                ("title", .string("Text statistics")),
                ("description", .string("Count the words, Unicode code points and UTF-8 bytes of a text.")),
                ("inputSchema", .object([
                    ("type", .string("object")),
                    ("properties", .object([
                        ("text", .object([("type", .string("string"))]))
                    ])),
                    ("required", .array([.string("text")])),
                    ("additionalProperties", .bool(false))
                ])),
                ("outputSchema", .object([
                    ("type", .string("object")),
                    ("properties", .object([
                        ("words", .object([("type", .string("integer"))])),
                        ("codepoints", .object([("type", .string("integer"))])),
                        ("utf8_bytes", .object([("type", .string("integer"))]))
                    ])),
                    ("required", .array([.string("words"), .string("codepoints"), .string("utf8_bytes")]))
                ])),
                ("annotations", .object([("readOnlyHint", .bool(true))]))
            ])
        ])
        outputLines.append(ser(.object([("jsonrpc", .string("2.0")),("id", rid),("result", .object([("tools", tools)]))])))

    case "tools/call":
        guard let params = paramsVal, case .object(let p) = params else {
            outputLines.append(ser(.object([
                ("jsonrpc", .string("2.0")),
                ("id", rid),
                ("error", .object([("code", .int(-32602)), ("message", .string("Invalid params"))]))
            ])))
            continue
        }
        let nameVal = objGet(p, "name")
        guard case .string(let toolName) = nameVal else {
            outputLines.append(ser(.object([
                ("jsonrpc", .string("2.0")),
                ("id", rid),
                ("error", .object([("code", .int(-32602)), ("message", .string("Invalid params"))]))
            ])))
            continue
        }
        if !validToolNames.contains(toolName) {
            outputLines.append(ser(.object([
                ("jsonrpc", .string("2.0")),
                ("id", rid),
                ("error", .object([("code", .int(-32602)), ("message", .string("Unknown tool: \(toolName)"))]))
            ])))
            continue
        }

        // Arguments
        let argsVal = objGet(p, "arguments")
        var args: [(String, JV)] = []
        if let av = argsVal {
            guard case .object(let a) = av else {
                let fr: JV = .object([
                    ("content", .array([.object([("type", .string("text")),("text", .string("arguments must be an object"))])])),
                    ("isError", .bool(true))
                ])
                outputLines.append(ser(.object([("jsonrpc", .string("2.0")),("id", rid),("result", fr)])))
                continue
            }
            args = a
        }

        let props = toolProps[toolName]!
        let required = toolRequired[toolName]!
        let propNames = Set(props.map { $0.name })

        // Unknown arguments
        let unknowns = args.filter { !propNames.contains($0.0) }
        if !unknowns.isEmpty {
            let smallest = unknowns.map { $0.0 }.min(by: cpLess)!
            let fr: JV = .object([
                ("content", .array([.object([("type", .string("text")),("text", .string("unknown argument: \(smallest)"))])])),
                ("isError", .bool(true))
            ])
            outputLines.append(ser(.object([("jsonrpc", .string("2.0")),("id", rid),("result", fr)])))
            continue
        }

        // Validate each property
        var vErr: String? = nil
        for prop in props {
            let av = objGet(args, prop.name)
            let isReq = required.contains(prop.name)
            if av == nil {
                if isReq { vErr = "missing required argument: \(prop.name)"; break }
                continue
            }
            switch prop.type {
            case "string":
                guard case .string(let s) = av! else { vErr = "argument \(prop.name) must be a string"; break }
                if let ml = prop.minLength, s.count < ml { vErr = "argument \(prop.name) must not be empty"; break }
            case "array":
                guard case .array(let arr) = av! else { vErr = "argument \(prop.name) must be an array of integers"; break }
                var allInt = true
                for e in arr { if case .int = e { } else { allInt = false; break } }
                if !allInt { vErr = "argument \(prop.name) must be an array of integers"; break }
                if let mi = prop.minItems, arr.count < mi { vErr = "argument \(prop.name) must not be empty"; break }
            default: break
            }
            if vErr != nil { break }
        }
        if let e = vErr {
            let fr: JV = .object([
                ("content", .array([.object([("type", .string("text")),("text", .string(e))])])),
                ("isError", .bool(true))
            ])
            outputLines.append(ser(.object([("jsonrpc", .string("2.0")),("id", rid),("result", fr)])))
            continue
        }

        // Execute tool
        switch toolName {
        case "kv_set":
            guard case .string(let key) = objGet(args, "key")!,
                  case .string(let val) = objGet(args, "value")! else { break }
            let existed = store[key] != nil
            store[key] = val
            let txt = existed ? "updated \(key)" : "created \(key)"
            let r: JV = .object([
                ("content", .array([.object([("type", .string("text")),("text", .string(txt))])])),
                ("isError", .bool(false))
            ])
            outputLines.append(ser(.object([("jsonrpc", .string("2.0")),("id", rid),("result", r)])))

        case "kv_get":
            guard case .string(let key) = objGet(args, "key")! else { break }
            if let val = store[key] {
                let r: JV = .object([
                    ("content", .array([.object([("type", .string("text")),("text", .string(val))])])),
                    ("isError", .bool(false))
                ])
                outputLines.append(ser(.object([("jsonrpc", .string("2.0")),("id", rid),("result", r)])))
            } else {
                let fr: JV = .object([
                    ("content", .array([.object([("type", .string("text")),("text", .string("key not found: \(key)"))])])),
                    ("isError", .bool(true))
                ])
                outputLines.append(ser(.object([("jsonrpc", .string("2.0")),("id", rid),("result", fr)])))
            }

        case "kv_list":
            var prefix = ""
            if let pv = objGet(args, "prefix"), case .string(let s) = pv { prefix = s }
            let keys = store.keys.filter { $0.hasPrefix(prefix) }.sorted(by: cpLess)
            let S: JV = .object([
                ("keys", .array(keys.map { .string($0) })),
                ("count", .int(Int64(keys.count)))
            ])
            let SText = ser(S)
            let r: JV = .object([
                ("content", .array([.object([("type", .string("text")),("text", .string(SText))])])),
                ("structuredContent", S),
                ("isError", .bool(false))
            ])
            outputLines.append(ser(.object([("jsonrpc", .string("2.0")),("id", rid),("result", r)])))

        case "sum":
            guard case .array(let arr) = objGet(args, "numbers")! else { break }
            var total: Int64 = 0
            for e in arr { if case .int(let i) = e { total += i } }
            let S: JV = .object([("sum", .int(total)),("count", .int(Int64(arr.count)))])
            let SText = ser(S)
            let r: JV = .object([
                ("content", .array([.object([("type", .string("text")),("text", .string(SText))])])),
                ("structuredContent", S),
                ("isError", .bool(false))
            ])
            outputLines.append(ser(.object([("jsonrpc", .string("2.0")),("id", rid),("result", r)])))

        case "text_stats":
            guard case .string(let txt) = objGet(args, "text")! else { break }
            let w = countWords(txt)
            let c = txt.unicodeScalars.count
            let b = txt.utf8.count
            let S: JV = .object([
                ("words", .int(Int64(w))),
                ("codepoints", .int(Int64(c))),
                ("utf8_bytes", .int(Int64(b)))
            ])
            let SText = ser(S)
            let r: JV = .object([
                ("content", .array([.object([("type", .string("text")),("text", .string(SText))])])),
                ("structuredContent", S),
                ("isError", .bool(false))
            ])
            outputLines.append(ser(.object([("jsonrpc", .string("2.0")),("id", rid),("result", r)])))

        default: break
        }

    default: break
    }
}

for ol in outputLines { print(ol) }
fflush(stdout)
exit(0)

