        f.mag = big_mul(&f.mag, &ten);
        Big d = big_from_int(s[i] - '0');
        f.mag = big_add(&f.mag, &d);
        i++;
    }

    // Parse decimal part
    if (i < (int)strlen(s) && s[i] == '.') {
        i++;
        while (i < (int)strlen(s) && isdigit(s[i])) {
            Big ten = big_from_int(10);
            f.mag = big_mul(&f.mag, &ten);
            Big d = big_from_int(s[i] - '0');
            f.mag = big_add(&f.mag, &d);
            f.dec++;
            i++;
        }
    }

    if (f.mag.len == 0) f.sign = 0;
    return f;
}

// Print a Fix with `places` decimal places
static void fix_print(Fix f, int places) {
    // Round to places first
    f = fix_round(f, places);

    if (f.sign == 0) {
        // Print zero
        if (places > 0) {
            printf("0.");
            for (int i = 0; i < places; i++) putchar('0');
        } else {
            putchar('0');
        }
        return;
    }

    if (f.sign < 0) putchar('-');

    // Get integer part and decimal part
    // f.mag has f.dec decimal places
    // Integer part = f.mag / 10^f.dec
    // Decimal part = f.mag % 10^f.dec

    Big int_part, dec_part;
    if (f.dec > 0) {
        Big p = big_pow10(f.dec);
        big_divmod(&f.mag, &p, &int_part, &dec_part);
    } else {
        int_part = f.mag;
        dec_part = big_zero();
    }

    // Print integer part with comma grouping
    // Convert int_part to string
    char buf[512];
    int pos = 0;
    if (int_part.len == 0) {
        buf[pos++] = '0';
    } else {
        // Convert chunks to string
        // Most significant chunk first
        char chunk_str[10];
        // First chunk (most significant) - no leading zeros
        snprintf(chunk_str, sizeof(chunk_str), "%d", int_part.d[int_part.len - 1]);
        for (int k = 0; chunk_str[k]; k++) buf[pos++] = chunk_str[k];
        // Remaining chunks - pad with leading zeros to 9 digits
        for (int i = int_part.len - 2; i >= 0; i--) {
            snprintf(chunk_str, sizeof(chunk_str), "%09d", int_part.d[i]);
            for (int k = 0; k < 9; k++) buf[pos++] = chunk_str[k];
        }
    }
    buf[pos] = '\0';

    // Add comma grouping
    int int_len = pos;
    int commas = (int_len - 1) / 3;
    int first_group = int_len - commas * 3;

    for (int i = 0; i < int_len; i++) {
        putchar(buf[i]);
        if (i < int_len - 1 && (int_len - 1 - i) % 3 == 0) putchar(',');
    }

    // Print decimal part
    if (places > 0) {
        putchar('.');
        // dec_part has f.dec digits (after rounding, f.dec == places)
        // Convert dec_part to string, pad to `places` digits
        char dbuf[16];
        int dpos = 0;
        if (dec_part.len == 0) {
            // All zeros
            for (int i = 0; i < places; i++) dbuf[dpos++] = '0';
        } else {
            // Convert chunks
            char chunk_str[10];
            snprintf(chunk_str, sizeof(chunk_str), "%d", dec_part.d[dec_part.len - 1]);
            int start_pad = 0;
            // The most significant chunk of dec_part might have fewer than 9 digits
            // We need to pad the total to `places` digits
            int total_digits = (dec_part.len - 1) * 9 + (int)strlen(chunk_str);
            int pad = places - total_digits;
            for (int p = 0; p < pad; p++) dbuf[dpos++] = '0';
            for (int k = 0; chunk_str[k]; k++) dbuf[dpos++] = chunk_str[k];
            for (int i = dec_part.len - 2; i >= 0; i--) {
                snprintf(chunk_str, sizeof(chunk_str), "%09d", dec_part.d[i]);
                for (int k = 0; k < 9; k++) dbuf[dpos++] = chunk_str[k];
            }
        }
        dbuf[dpos] = '\0';
        for (int i = 0; i < places; i++) putchar(dbuf[i]);
    }
}

// Convert Fix to integer (multiply by 10^minor_units), assuming dec <= minor_units
static Big fix_to_minor(Fix f, int minor_units) {
    // f should already be rounded to minor_units decimal places
    // Multiply magnitude by 10^(minor_units - f.dec)
    Big result = f.mag;
    int pad = minor_units - f.dec;
    if (pad > 0) {
        Big p = big_pow10(pad);
        result = big_mul(&result, &p);
    }
    return result;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

/* ==================== Big Integer (unsigned, base 10^9) ==================== */

#define MAX_CHUNKS 40
#define BASE 1000000000LL

typedef struct { int len; long long d[MAX_CHUNKS]; } Big;

static Big big_zero(void) {
    Big r; r.len = 0; memset(r.d, 0, sizeof(r.d)); return r;
}

static void big_trim(Big *a) {
    while (a->len > 0 && a->d[a->len - 1] == 0) a->len--;
}

static int big_cmp(const Big *a, const Big *b) {
    if (a->len != b->len) return a->len < b->len ? -1 : 1;
    for (int i = a->len - 1; i >= 0; i--)
        if (a->d[i] != b->d[i]) return a->d[i] < b->d[i] ? -1 : 1;
    return 0;
}

static Big big_add(const Big *a, const Big *b) {
    Big r; memset(r.d, 0, sizeof(r.d));
    int ml = a->len > b->len ? a->len : b->len;
    long long carry = 0;
    for (int i = 0; i < ml || carry; i++) {
        long long s = carry;
        if (i < a->len) s += a->d[i];
        if (i < b->len) s += b->d[i];
        r.d[i] = s % BASE; carry = s / BASE;
    }
    r.len = 0;
    for (int i = MAX_CHUNKS - 1; i >= 0; i--) { if (r.d[i]) { r.len = i+1; break; } }
    return r;
}

static Big big_sub(const Big *a, const Big *b) { /* a >= b */
    Big r; memset(r.d, 0, sizeof(r.d));
    long long borrow = 0;
    for (int i = 0; i < a->len; i++) {
        long long diff = a->d[i] - borrow - (i < b->len ? b->d[i] : 0);
        if (diff < 0) { r.d[i] = diff + BASE; borrow = 1; }
        else { r.d[i] = diff; borrow = 0; }
    }
    big_trim(&r); return r;
}

static Big big_mul(const Big *a, const Big *b) {
    Big r; memset(r.d, 0, sizeof(r.d));
    for (int i = 0; i < a->len; i++) {
        long long carry = 0;
        for (int j = 0; j < b->len; j++) {
            long long prod = a->d[i] * b->d[j] + r.d[i+j] + carry;
            r.d[i+j] = prod % BASE; carry = prod / BASE;
        }
        r.d[i + b->len] += carry;
    }
    r.len = 0;
    for (int i = MAX_CHUNKS - 1; i >= 0; i--) { if (r.d[i]) { r.len = i+1; break; } }
    return r;
}

static Big big_from_int(long long n) {
    Big r; memset(r.d, 0, sizeof(r.d));
    if (n <= 0) { r.len = 0; return r; }
    r.len = 0;
    while (n > 0) { r.d[r.len++] = n % BASE; n /= BASE; }
    return r;
}

static Big big_pow10(int k) {
    Big r = big_from_int(1);
    Big ten = big_from_int(10);
    for (int i = 0; i < k; i++) r = big_mul(&r, &ten);
    return r;
}

/* Knuth division: a / b, a >= 0, b > 0 */
static void big_divmod(const Big *a, const Big *b, Big *q, Big *r) {
    if (big_cmp(a, b) < 0) { *q = big_zero(); *r = *a; return; }
    int n = b->len;
    if (n == 1) {
        /* single-chunk divisor */
        long long dv = b->d[0];
        Big qq; memset(qq.d, 0, sizeof(qq.d)); qq.len = a->len;
        long long rem = 0;
        for (int i = a->len - 1; i >= 0; i--) {
            long long cur = rem * BASE + a->d[i];
            qq.d[i] = cur / dv;
            rem = cur % dv;
        }
        big_trim(&qq); *q = qq; *r = big_from_int(rem);
        return;
    }
    /* normalize */
    int s = 0;
    long long top = b->d[n-1];
    while (top < BASE / 2) { top *= 2; s++; }

    Big un, vn; memset(&un, 0, sizeof(un)); memset(&vn, 0, sizeof(vn));
    long long carry = 0;
    for (int i = 0; i < n; i++) {
        long long v = b->d[i] * (1LL << s) + carry;
        vn.d[i] = v % BASE; carry = v / BASE;
    }
    vn.len = n;
    if (carry) { vn.d[n] = carry; vn.len = n + 1; n = vn.len; }

    carry = 0;
    for (int i = 0; i < a->len; i++) {
        long long v = a->d[i] * (1LL << s) + carry;
        un.d[i] = v % BASE; carry = v / BASE;
    }
    un.len = a->len;
    if (carry) { un.d[un.len] = carry; un.len++; }
    un.d[un.len] = 0; un.len++;

    int m = un.len - n - 1;
    Big qq; memset(&qq, 0, sizeof(qq)); qq.len = m + 1;

    for (int j = m; j >= 0; j--) {
        long long qhat, rhat;
        if (un.d[j+n] == vn.d[n-1]) {
            qhat = BASE - 1;
        } else {
            qhat = (un.d[j+n] * BASE + un.d[j+n-1]) / vn.d[n-1];
        }
        rhat = (un.d[j+n] * BASE + un.d[j+n-1]) - qhat * vn.d[n-1];

        while (qhat >= BASE || (n >= 2 && qhat * vn.d[n-2] > rhat * BASE + un.d[j+n-2])) {
            qhat--;
            rhat += vn.d[n-1];
            if (rhat >= BASE) break;
        }

        long long borrow = 0;
        for (int i = 0; i < n; i++) {
            long long prod = qhat * vn.d[i] + borrow;
            long long tmp = un.d[j+i] - (prod % BASE);
            un.d[j+i] = tmp < 0 ? tmp + BASE : tmp;
            borrow = prod / BASE + (tmp < 0 ? 1 : 0);
        }
        un.d[j+n] -= borrow;
        if (un.d[j+n] < 0) {
            un.d[j+n] += BASE;
            qhat--;
            carry = 0;
            for (int i = 0; i < n; i++) {
                long long sm = un.d[j+i] + vn.d[i] + carry;
                un.d[j+i] = sm % BASE; carry = sm / BASE;
            }
            un.d[j+n] += carry;
        }
        qq.d[j] = qhat;
    }
    *q = qq; big_trim(q);

    Big rem; memset(&rem, 0, sizeof(rem));
    rem.len = n;
    for (int i = 0; i < n; i++) rem.d[i] = un.d[i];
    big_trim(&rem);
    if (s > 0) {
        carry = 0;
        for (int i = rem.len - 1; i >= 0; i--) {
            long long v = rem.d[i] + carry * BASE;
            rem.d[i] = v >> s; carry = v & ((1LL << s) - 1);
        }
        big_trim(&rem);
    }
    *r = rem;
}

/* ==================== Fixed-Point ==================== */

typedef struct { int sign; Big mag; int dec; } Fix;

static Fix fix_zero(void) { Fix f; f.sign = 0; f.mag = big_zero(); f.dec = 0; return f; }

static Fix fix_neg(Fix f) { if (f.sign) f.sign = -f.sign; return f; }

static Fix fix_round(Fix f, int places) {
    if (f.sign == 0) { f.dec = places; return f; }
    if (f.dec <= places) {
        int pad = places - f.dec;
        if (pad > 0) { Big p = big_pow10(pad); f.mag = big_mul(&f.mag, &p); }
        f.dec = places; return f;
    }
    int k = f.dec - places;
    Big divisor = big_pow10(k);
    Big q, r;
    big_divmod(&f.mag, &divisor, &q, &r);
    /* half = divisor / 2 */
    Big two = big_from_int(2), half;
    big_divmod(&divisor, &two, &half, &r); /* r unused, divisor is even */
    /* recompute r */
    big_divmod(&f.mag, &divisor, &q, &r);

    int cmp = big_cmp(&r, &half);
    if (cmp > 0 || (cmp == 0 && q.len > 0 && q.d[0] % 2 != 0)) {
        Big one = big_from_int(1);
        q = big_add(&q, &one);
    }
    f.mag = q; f.dec = places;
    if (q.len == 0) f.sign = 0;
    return f;
}

static Fix fix_add(Fix a, Fix b) {
    if (a.sign == 0) return b;
    if (b.sign == 0) return a;
    int md = a.dec > b.dec ? a.dec : b.dec;
    if (a.dec < md) { Big p = big_pow10(md - a.dec); a.mag = big_mul(&a.mag, &p); a.dec = md; }
    if (b.dec < md) { Big p = big_pow10(md - b.dec); b.mag = big_mul(&b.mag, &p); b.dec = md; }
    Fix r; r.dec = md;
    if (a.sign == b.sign) {
        r.sign = a.sign; r.mag = big_add(&a.mag, &b.mag);
    } else {
        int c = big_cmp(&a.mag, &b.mag);
        if (c == 0) { r.sign = 0; r.mag = big_zero(); }
        else if (c > 0) { r.sign = a.sign; r.mag = big_sub(&a.mag, &b.mag); }
        else { r.sign = b.sign; r.mag = big_sub(&b.mag, &a.mag); }
    }
    if (r.mag.len == 0) r.sign = 0;
    return r;
}

static Fix fix_sub(Fix a, Fix b) { return fix_add(a, fix_neg(b)); }

static Fix fix_mul(Fix a, Fix b) {
    Fix r; r.dec = a.dec + b.dec;
    if (a.sign == 0 || b.sign == 0) { r.sign = 0; r.mag = big_zero(); return r; }
    r.sign = a.sign * b.sign;
    r.mag = big_mul(&a.mag, &b.mag);
    if (r.mag.len == 0) r.sign = 0;
    return r;
}

static int fix_cmp(Fix a, Fix b) {
    if (a.sign == 0 && b.sign == 0) return 0;
    if (a.sign == 0) return -1;
    if (b.sign == 0) return 1;
    if (a.sign != b.sign) return a.sign < b.sign ? -1 : 1;
    int md = a.dec > b.dec ? a.dec : b.dec;
    if (a.dec < md) { Big p = big_pow10(md - a.dec); a.mag = big_mul(&a.mag, &p); }
    if (b.dec < md) { Big p = big_pow10(md - b.dec); b.mag = big_mul(&b.mag, &p); }
    int c = big_cmp(&a.mag, &b.mag);
    return a.sign > 0 ? c : -c;
}

static Fix fix_parse(const char *s) {
    Fix f; f.sign = 1; f.mag = big_zero(); f.dec = 0;
    int i = 0;
    if (s[i] == '-') { f.sign = -1; i++; }
    else if (s[i] == '+') { i++; }
    while (s[i] && isdigit((unsigned char)s[i])) {
        Big ten = big_from_int(10);
        f.mag = big_mul(&f.mag, &ten);
        Big d = big_from_int(s[i] - '0');
        f.mag = big_add(&f.mag, &d);
        i++;
    }
    if (s[i] == '.') {
        i++;
        while (s[i] && isdigit((unsigned char)s[i])) {
            Big ten = big_from_int(10);
            f.mag = big_mul(&f.mag, &ten);
            Big d = big_from_int(s[i] - '0');
            f.mag = big_add(&f.mag, &d);
            f.dec++; i++;
        }
    }
    if (f.mag.len == 0) f.sign = 0;
    return f;
}

static void big_to_str(const Big *a, char *buf) {
    if (a->len == 0) { buf[0] = '0'; buf[1] = '\0'; return; }
    int pos = 0;
    pos += sprintf(buf + pos, "%lld", a->d[a->len - 1]);
    for (int i = a->len - 2; i >= 0; i--)
        pos += sprintf(buf + pos, "%09lld", a->d[i]);
    buf[pos] = '\0';
}

static void print_int_comma(const char *s) {
    int len = (int)strlen(s);
    for (int i = 0; i < len; i++) {
        if (i > 0 && (len - i) % 3 == 0) putchar(',');
        putchar(s[i]);
    }
}

static void fix_print(Fix f, int places) {
    f = fix_round(f, places);
    if (f.sign == 0) {
        if (places > 0) { printf("0."); for (int i = 0; i < places; i++) putchar('0'); }
        else printf("0");
        return;
    }
    if (f.sign < 0) putchar('-');
    /* integer part = f.mag / 10^places, fractional = f.mag % 10^places */
    Big ipart, fpart;
    if (places > 0) {
        Big p = big_pow10(places);
        big_divmod(&f.mag, &p, &ipart, &fpart);
    } else {
        ipart = f.mag; fpart = big_zero();
    }
    char buf[512];
    big_to_str(&ipart, buf);
    print_int_comma(buf);
    if (places > 0) {
        putchar('.');
        char dbuf[64];
        big_to_str(&fpart, dbuf);
        int dlen = (int)strlen(dbuf);
        for (int i = dlen; i < places; i++) putchar('0');
        printf("%s", dbuf);
    }
}

/* ==================== Ledger ==================== */

#define MAX_CURRENCY 256
#define MAX_ACCOUNTS 4096
#define MAX_LINE 4096

typedef struct { char code[32]; int minor; } Currency;
typedef struct { char name[256]; int cur_idx; Fix balance; Fix limit; } Account;

static Currency currencies[MAX_CURRENCY];
static int num_cur = 0;
static Account accounts[MAX_ACCOUNTS];
static int num_acc = 0;

static int find_currency(const char *code) {
    for (int i = 0; i < num_cur; i++)
        if (strcmp(currencies[i].code, code) == 0) return i;
    return -1;
}

static int find_account(const char *name) {
    for (int i = 0; i < num_acc; i++)
        if (strcmp(accounts[i].name, name) == 0) return i;
    return -1;
}

/* Rejection list */
typedef struct { int line; char reason[256]; } Reject;
static Reject rejects[MAX_ACCOUNTS * 2];
static int num_rej = 0;

static void add_reject(int line, const char *reason) {
    rejects[num_rej].line = line;
    strcpy(rejects[num_rej].reason, reason);
    num_rej++;
}

/* Tokenize a line by spaces */
static int tokenize(char *line, char **toks, int max) {
    int n = 0;
    char *p = line;
    while (*p && n < max) {
        while (*p == ' ' || *p == '\t') p++;
        if (!*p || *p == '\n' || *p == '\r') break;
        toks[n++] = p;
        while (*p && *p != ' ' && *p != '\t' && *p != '\n' && *p != '\r') p++;
        if (*p) *p++ = '\0';
    }
    return n;
}

int main(int argc, char *argv[]) {
    if (argc < 2) return 1;
    char path[512];
    snprintf(path, sizeof(path), "%s/ledger.txt", argv[1]);
    FILE *fp = fopen(path, "r");
    if (!fp) return 1;

    char line[MAX_LINE];
    int lineno = 0;

    while (fgets(line, sizeof(line), fp)) {
        lineno++;
        /* check blank or comment */
        char *p = line;
        while (*p == ' ' || *p == '\t') p++;
        if (*p == '\0' || *p == '\n' || *p == '\r' || *p == '#') continue;

        char *toks[64];
        int nt = tokenize(line, toks, 64);
        if (nt == 0) continue;

        const char *cmd = toks[0];

        if (strcmp(cmd, "currency") == 0) {
            /* currency CODE minor */
            if (nt >= 3) {
                strcpy(currencies[num_cur].code, toks[1]);
                currencies[num_cur].minor = atoi(toks[2]);
                num_cur++;
            }
        }
        else if (strcmp(cmd, "open") == 0) {
            /* open account CODE [limit] */
            if (nt >= 3) {
                const char *aname = toks[1];
                const char *code = toks[2];
                if (find_account(aname) >= 0) {
                    char rbuf[256]; snprintf(rbuf, sizeof(rbuf), "account exists %s", aname);
                    add_reject(lineno, rbuf); continue;
                }
                int ci = find_currency(code);
                if (ci < 0) continue; /* shouldn't happen per spec */
                Fix limit = fix_zero();
                if (nt >= 4) limit = fix_parse(toks[3]);
                limit = fix_round(limit, currencies[ci].minor);
                if (limit.sign < 0) limit = fix_zero(); /* limit should be non-negative */
                strcpy(accounts[num_acc].name, aname);
                accounts[num_acc].cur_idx = ci;
                accounts[num_acc].balance = fix_zero();
                accounts[num_acc].balance.dec = currencies[ci].minor;
                accounts[num_acc].limit = limit;
                num_acc++;
            }
        }
        else if (strcmp(cmd, "deposit") == 0) {
            /* deposit account amount */
            if (nt >= 3) {
                const char *aname = toks[1];
                int ai = find_account(aname);
                if (ai < 0) {
                    char rbuf[256]; snprintf(rbuf, sizeof(rbuf), "unknown account %s", aname);
                    add_reject(lineno, rbuf); continue;
                }
                Fix amt = fix_parse(toks[2]);
                int mu = currencies[accounts[ai].cur_idx].minor;
                amt = fix_round(amt, mu);
                if (amt.sign <= 0) { add_reject(lineno, "non-positive amount"); continue; }
                accounts[ai].balance = fix_add(accounts[ai].balance, amt);
                accounts[ai].balance.dec = mu;
            }
        }
        else if (strcmp(cmd, "withdraw") == 0) {
            /* withdraw account amount */
            if (nt >= 3) {
                const char *aname = toks[1];
                int ai = find_account(aname);
                if (ai < 0) {
                    char rbuf[256]; snprintf(rbuf, sizeof(rbuf), "unknown account %s", aname);
                    add_reject(lineno, rbuf); continue;
                }
                Fix amt = fix_parse(toks[2]);
                int mu = currencies[accounts[ai].cur_idx].minor;
                amt = fix_round(amt, mu);
                if (amt.sign <= 0) { add_reject(lineno, "non-positive amount"); continue; }
                Fix newbal = fix_sub(accounts[ai].balance, amt);
                Fix neg_limit = fix_neg(accounts[ai].limit);
                if (fix_cmp(newbal, neg_limit) < 0) {
                    char rbuf[256]; snprintf(rbuf, sizeof(rbuf), "insufficient funds %s", aname);
                    add_reject(lineno, rbuf); continue;
                }
                accounts[ai].balance = newbal;
                accounts[ai].balance.dec = mu;
            }
        }
        else if (strcmp(cmd, "transfer") == 0) {
            /* transfer from to amount */
            if (nt >= 4) {
                const char *from = toks[1], *to = toks[2];
                int fi = find_account(from), ti = find_account(to);
                if (fi < 0) { char rbuf[256]; snprintf(rbuf, sizeof(rbuf), "unknown account %s", from); add_reject(lineno, rbuf); continue; }
                if (ti < 0) { char rbuf[256]; snprintf(rbuf, sizeof(rbuf), "unknown account %s", to); add_reject(lineno, rbuf); continue; }
                if (accounts[fi].cur_idx != accounts[ti].cur_idx) { add_reject(lineno, "currency mismatch"); continue; }
                Fix amt = fix_parse(toks[3]);
                int mu = currencies[accounts[fi].cur_idx].minor;
                amt = fix_round(amt, mu);
                if (amt.sign <= 0) { add_reject(lineno, "non-positive amount"); continue; }
                Fix newbal = fix_sub(accounts[fi].balance, amt);
                Fix neg_limit = fix_neg(accounts[fi].limit);
                if (fix_cmp(newbal, neg_limit) < 0) {
                    char rbuf[256]; snprintf(rbuf, sizeof(rbuf), "insufficient funds %s", from);
                    add_reject(lineno, rbuf); continue;
                }
                accounts[fi].balance = newbal; accounts[fi].balance.dec = mu;
                accounts[ti].balance = fix_add(accounts[ti].balance, amt); accounts[ti].balance.dec = mu;
            }
        }
        else if (strcmp(cmd, "convert") == 0) {
            /* convert from to amount rate */
            if (nt >= 5) {
                const char *from = toks[1], *to = toks[2];
                int fi = find_account(from), ti = find_account(to);
                if (fi < 0) { char rbuf[256]; snprintf(rbuf, sizeof(rbuf), "unknown account %s", from); add_reject(lineno, rbuf); continue; }
                if (ti < 0) { char rbuf[256]; snprintf(rbuf, sizeof(rbuf), "unknown account %s", to); add_reject(lineno, rbuf); continue; }
                Fix amt = fix_parse(toks[3]);
                int mu_from = currencies[accounts[fi].cur_idx].minor;
                amt = fix_round(amt, mu_from);
                if (amt.sign <= 0) { add_reject(lineno, "non-positive amount"); continue; }
                Fix newbal = fix_sub(accounts[fi].balance, amt);
                Fix neg_limit = fix_neg(accounts[fi].limit);
                if (fix_cmp(newbal, neg_limit) < 0) {
                    char rbuf[256]; snprintf(rbuf, sizeof(rbuf), "insufficient funds %s", from);
                    add_reject(lineno, rbuf); continue;
                }
                Fix rate = fix_parse(toks[4]);
                Fix received = fix_mul(amt, rate);
                int mu_to = currencies[accounts[ti].cur_idx].minor;
                received = fix_round(received, mu_to);
                accounts[fi].balance = newbal; accounts[fi].balance.dec = mu_from;
                accounts[ti].balance = fix_add(accounts[ti].balance, received); accounts[ti].balance.dec = mu_to;
            }
        }
        else if (strcmp(cmd, "interest") == 0) {
            /* interest account rate */
            if (nt >= 3) {
                const char *aname = toks[1];
                int ai = find_account(aname);
                if (ai < 0) { char rbuf[256]; snprintf(rbuf, sizeof(rbuf), "unknown account %s", aname); add_reject(lineno, rbuf); continue; }
                Fix rate = fix_parse(toks[2]);
                Fix gain = fix_mul(accounts[ai].balance, rate);
                int mu = currencies[accounts[ai].cur_idx].minor;
                gain = fix_round(gain, mu);
                accounts[ai].balance = fix_add(accounts[ai].balance, gain);
                accounts[ai].balance.dec = mu;
            }
        }
        else if (strcmp(cmd, "split") == 0) {
            /* split from amount to1:w1 to2:w2 ... */
            if (nt >= 4) {
                const char *from = toks[1];
                int fi = find_account(from);
                if (fi < 0) { char rbuf[256]; snprintf(rbuf, sizeof(rbuf), "unknown account %s", from); add_reject(lineno, rbuf); continue; }
                /* collect targets */
                int ntargets = nt - 3;
                int tgt_idx[64];
                long long tgt_w[64];
                int unknown_found = 0;
                for (int i = 0; i < ntargets; i++) {
                    char *spec = toks[3 + i];
                    char *colon = strchr(spec, ':');
                    if (!colon) { unknown_found = 1; break; }
                    *colon = '\0';
                    int ti = find_account(spec);
                    if (ti < 0) { char rbuf[256]; snprintf(rbuf, sizeof(rbuf), "unknown account %s", spec); add_reject(lineno, rbuf); unknown_found = 1; break; }
                    tgt_idx[i] = ti;
                    tgt_w[i] = atoll(colon + 1);
                }
                if (unknown_found) continue;
                /* currency mismatch */
                int cur_mismatch = 0;
                for (int i = 0; i < ntargets; i++) {
                    if (accounts[tgt_idx[i]].cur_idx != accounts[fi].cur_idx) { cur_mismatch = 1; break; }
                }
                if (cur_mismatch) { add_reject(lineno, "currency mismatch"); continue; }
                /* amount */
                Fix amt = fix_parse(toks[2]);
                int mu = currencies[accounts[fi].cur_idx].minor;
                amt = fix_round(amt, mu);
                if (amt.sign <= 0) { add_reject(lineno, "non-positive amount"); continue; }
                /* insufficient funds */
                Fix newbal = fix_sub(accounts[fi].balance, amt);
                Fix neg_limit = fix_neg(accounts[fi].limit);
                if (fix_cmp(newbal, neg_limit) < 0) {
                    char rbuf[256]; snprintf(rbuf, sizeof(rbuf), "insufficient funds %s", from);
                    add_reject(lineno, rbuf); continue;
                }
                accounts[fi].balance = newbal; accounts[fi].balance.dec = mu;

                /* Perform split in minor units */
                Big A = amt.mag; /* amt is positive, already rounded to mu places */
                /* A is the amount in minor units (since amt.dec == mu, mag = value * 10^mu... 
                   wait no. amt.mag represents the number with mu decimal places.
                   The minor unit value = amt.mag (integer). */
                long long W = 0;
                for (int i = 0; i < ntargets; i++) W += tgt_w[i];
                Big Wbig = big_from_int(W);

                Big base_share[64];
                Big rem_share[64];
                for (int i = 0; i < ntargets; i++) {
                    Big wi = big_from_int(tgt_w[i]);
                    Big prod = big_mul(&A, &wi);
                    big_divmod(&prod, &Wbig, &base_share[i], &rem_share[i]);
                }

                /* leftover = A - sum(base_share) */
                Big sum_base = big_zero();
                for (int i = 0; i < ntargets; i++) sum_base = big_add(&sum_base, &base_share[i]);
                Big leftover = big_sub(&A, &sum_base);
                /* leftover is a small number (0 to ntargets-1) */
                long long lo = 0;
                if (leftover.len > 0) lo = leftover.d[0];

                /* distribute: give 1 to targets with largest remainders, ties by order */
                for (long long k = 0; k < lo; k++) {
                    int best = -1;
                    for (int i = 0; i < ntargets; i++) {
                        if (best == -1) { best = i; continue; }
                        /* compare rem_share[i] vs rem_share[best], prefer larger; tie prefer smaller index */
                        int c = big_cmp(&rem_share[i], &rem_share[best]);
                        if (c > 0) best = i;
                    }
                    Big one = big_from_int(1);
                    base_share[best] = big_add(&base_share[best], &one);
                    rem_share[best] = big_zero(); /* used up */
                }

                /* add to targets */
                for (int i = 0; i < ntargets; i++) {
                    Fix share;
                    share.sign = 1; share.mag = base_share[i]; share.dec = mu;
                    if (share.mag.len == 0) share.sign = 0;
                    accounts[tgt_idx[i]].balance = fix_add(accounts[tgt_idx[i]].balance, share);
                    accounts[tgt_idx[i]].balance.dec = mu;
                }
            }
        }
    }
    fclose(fp);

    /* Output rejections */
    for (int i = 0; i < num_rej; i++)
        printf("line %d: REJECT %s\n", rejects[i].line, rejects[i].reason);

    printf("\n");

    /* Sort accounts by name */
    for (int i = 0; i < num_acc - 1; i++)
        for (int j = i + 1; j < num_acc; j++)
            if (strcmp(accounts[i].name, accounts[j].name) > 0) {
                Account tmp = accounts[i]; accounts[i] = accounts[j]; accounts[j] = tmp;
            }

    for (int i = 0; i < num_acc; i++) {
        printf("%s %s ", accounts[i].name, currencies[accounts[i].cur_idx].code);
        fix_print(accounts[i].balance, currencies[accounts[i].cur_idx].minor);
        printf("\n");
    }

    printf("\n");

    /* Currency totals: currencies with at least one account, sorted by code */
    /* collect used currencies */
    int used_cur[MAX_CURRENCY]; int num_used = 0;
    for (int i = 0; i < num_acc; i++) {
        int ci = accounts[i].cur_idx;
        int found = 0;
        for (int j = 0; j < num_used; j++) if (used_cur[j] == ci) { found = 1; break; }
        if (!found) used_cur[num_used++] = ci;
    }
    /* sort by code */
    for (int i = 0; i < num_used - 1; i++)
        for (int j = i + 1; j < num_used; j++)
            if (strcmp(currencies[used_cur[i]].code, currencies[used_cur[j]].code) > 0) {
                int tmp = used_cur[i]; used_cur[i] = used_cur[j]; used_cur[j] = tmp;
            }

    for (int k = 0; k < num_used; k++) {
        int ci = used_cur[k];
        Fix total = fix_zero(); total.dec = currencies[ci].minor;
        int count = 0;
        for (int i = 0; i < num_acc; i++) {
            if (accounts[i].cur_idx == ci) {
                total = fix_add(total, accounts[i].balance);
                count++;
            }
        }
        printf("total %s ", currencies[ci].code);
        fix_print(total, currencies[ci].minor);
        printf(" (%d accounts)\n", count);
    }

    return 0;
}

use std::io::{self, BufRead, Write};

#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

struct Parser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Parser { input: input.as_bytes(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn peek(&self) -> Option<u8> {
        if self.pos < self.input.len() { Some(self.input[self.pos]) } else { None }
    }

    fn parse_value(&mut self) -> Result<JsonValue, ()> {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => self.parse_string().map(JsonValue::Str),
            Some(b't') => self.parse_true(),
            Some(b'f') => self.parse_false(),
            Some(b'n') => self.parse_null(),
            Some(c) if c == b'-' || c.is_ascii_digit() => self.parse_number(),
            _ => Err(()),
        }
    }

    fn parse_true(&mut self) -> Result<JsonValue, ()> {
        if self.pos + 4 <= self.input.len() && &self.input[self.pos..self.pos+4] == b"true" {
            self.pos += 4;
            Ok(JsonValue::Bool(true))
        } else { Err(()) }
    }

    fn parse_false(&mut self) -> Result<JsonValue, ()> {
        if self.pos + 5 <= self.input.len() && &self.input[self.pos..self.pos+5] == b"false" {
            self.pos += 5;
            Ok(JsonValue::Bool(false))
        } else { Err(()) }
    }

    fn parse_null(&mut self) -> Result<JsonValue, ()> {
        if self.pos + 4 <= self.input.len() && &self.input[self.pos..self.pos+4] == b"null" {
            self.pos += 4;
            Ok(JsonValue::Null)
        } else { Err(()) }
    }

    fn parse_number(&mut self) -> Result<JsonValue, ()> {
        let start = self.pos;
        let mut is_float = false;
        if self.peek() == Some(b'-') { self.pos += 1; }
        if self.peek() == Some(b'0') {
            self.pos += 1;
        } else if self.peek().map_or(false, |c| c.is_ascii_digit()) {
            while self.peek().map_or(false, |c| c.is_ascii_digit()) { self.pos += 1; }
        } else { return Err(()); }
        if self.peek() == Some(b'.') {
            is_float = true;
            self.pos += 1;
            if !self.peek().map_or(false, |c| c.is_ascii_digit()) { return Err(()); }
            while self.peek().map_or(false, |c| c.is_ascii_digit()) { self.pos += 1; }
        }
        if self.peek() == Some(b'e') || self.peek() == Some(b'E') {
            is_float = true;
            self.pos += 1;
            if self.peek() == Some(b'+') || self.peek() == Some(b'-') { self.pos += 1; }
            if !self.peek().map_or(false, |c| c.is_ascii_digit()) { return Err(()); }
            while self.peek().map_or(false, |c| c.is_ascii_digit()) { self.pos += 1; }
        }
        let s = std::str::from_utf8(&self.input[start..self.pos]).map_err(|_| ())?;
        if is_float {
            s.parse::<f64>().map(JsonValue::Float).map_err(|_| ())
        } else {
            s.parse::<i64>().map(JsonValue::Int).map_err(|_| ())
        }
    }

    fn parse_hex4(&mut self) -> Result<u32, ()> {
        if self.pos + 4 > self.input.len() { return Err(()); }
        let mut val: u32 = 0;
        for i in 0..4 {
            let c = self.input[self.pos + i];
            let d = match c {
                b'0'..=b'9' => (c - b'0') as u32,
                b'a'..=b'f' => (c - b'a' + 10) as u32,
                b'A'..=b'F' => (c - b'A' + 10) as u32,
                _ => return Err(()),
            };
            val = val * 16 + d;
        }
        self.pos += 4;
        Ok(val)
    }

    fn parse_string(&mut self) -> Result<String, ()> {
        self.pos += 1; // skip opening "
        let mut result: Vec<u8> = Vec::new();
        loop {
            if self.pos >= self.input.len() { return Err(()); }
            let c = self.input[self.pos];
            match c {
                b'"' => { self.pos += 1; return String::from_utf8(result).map_err(|_| ()); }
                b'\\' => {
                    self.pos += 1;
                    if self.pos >= self.input.len() { return Err(()); }
                    match self.input[self.pos] {
                        b'"' => { result.push(b'"'); self.pos += 1; }
                        b'\\' => { result.push(b'\\'); self.pos += 1; }
                        b'/' => { result.push(b'/'); self.pos += 1; }
                        b'b' => { result.push(0x08); self.pos += 1; }
                        b'f' => { result.push(0x0C); self.pos += 1; }
                        b'n' => { result.push(b'\n'); self.pos += 1; }
                        b'r' => { result.push(b'\r'); self.pos += 1; }
                        b't' => { result.push(b'\t'); self.pos += 1; }
                        b'u' => {
                            self.pos += 1;
                            let cp = self.parse_hex4()?;
                            if cp >= 0xD800 && cp <= 0xDBFF {
                                if self.pos + 1 < self.input.len() && self.input[self.pos] == b'\\' && self.input[self.pos+1] == b'u' {
                                    self.pos += 2;
                                    let lo = self.parse_hex4()?;
                                    if lo >= 0xDC00 && lo <= 0xDFFF {
                                        let combined = 0x10000u32 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                                        let ch = char::from_u32(combined).ok_or(())?;
                                        let mut buf = [0u8; 4];
                                        let s = ch.encode_utf8(&mut buf);
                                        result.extend_from_slice(s.as_bytes());
                                    } else { return Err(()); }
                                } else { return Err(()); }
                            } else if cp >= 0xDC00 && cp <= 0xDFFF {
                                return Err(());
                            } else {
                                let ch = char::from_u32(cp).ok_or(())?;
                                let mut buf = [0u8; 4];
                                let s = ch.encode_utf8(&mut buf);
                                result.extend_from_slice(s.as_bytes());
                            }
                        }
                        _ => return Err(()),
                    }
                }
                _ => { result.push(c); self.pos += 1; }
            }
        }
    }

    fn parse_object(&mut self) -> Result<JsonValue, ()> {
        self.pos += 1; // skip {
        let mut members = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') { self.pos += 1; return Ok(JsonValue::Object(members)); }
        loop {
            self.skip_ws();
            if self.peek() != Some(b'"') { return Err(()); }
            let key = self.parse_string()?;
            self.skip_ws();
            if self.peek() != Some(b':') { return Err(()); }
            self.pos += 1;
            let value = self.parse_value()?;
            members.push((key, value));
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b'}') => { self.pos += 1; return Ok(JsonValue::Object(members)); }
                _ => return Err(()),
            }
        }
    }

    fn parse_array(&mut self) -> Result<JsonValue, ()> {
        self.pos += 1; // skip [
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') { self.pos += 1; return Ok(JsonValue::Array(items)); }
        loop {
            let value = self.parse_value()?;
            items.push(value);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.pos += 1; }
                Some(b']') => { self.pos += 1; return Ok(JsonValue::Array(items)); }
                _ => return Err(()),
            }
        }
    }
}

fn parse_json(s: &str) -> Option<JsonValue> {
    let mut p = Parser::new(s);
    let v = p.parse_value().ok()?;
    p.skip_ws();
    if p.pos != p.input.len() { return None; }
    Some(v)
}

fn escape_str(s: &str) -> String {
    let mut r = String::with_capacity(s.len() + 2);
    r.push('"');
    for ch in s.chars() {
        match ch {
            '"' => r.push_str("\\\""),
            '\\' => r.push_str("\\\\"),
            '\u{08}' => r.push_str("\\b"),
            '\u{0C}' => r.push_str("\\f"),
            '\n' => r.push_str("\\n"),
            '\r' => r.push_str("\\r"),
            '\t' => r.push_str("\\t"),
            c if (c as u32) < 0x20 => { r.push_str(&format!("\\u{:04x}", c as u32)); }
            c => r.push(c),
        }
    }
    r.push('"');
    r
}

fn to_json(v: &JsonValue) -> String {
    match v {
        JsonValue::Null => "null".to_string(),
        JsonValue::Bool(true) => "true".to_string(),
        JsonValue::Bool(false) => "false".to_string(),
        JsonValue::Int(n) => format!("{}", n),
        JsonValue::Float(_) => "0".to_string(), // shouldn't appear in output
        JsonValue::Str(s) => escape_str(s),
        JsonValue::Array(items) => {
            let parts: Vec<String> = items.iter().map(to_json).collect();
            format!("[{}]", parts.join(","))
        }
        JsonValue::Object(members) => {
            let parts: Vec<String> = members.iter().map(|(k, v)| format!("{}:{}", escape_str(k), to_json(v))).collect();
            format!("{{{}}}", parts.join(","))
        }
    }
}

fn obj_get<'a>(v: &'a JsonValue, key: &str) -> Option<&'a JsonValue> {
    if let JsonValue::Object(members) = v {
        members.iter().find(|(k, _)| k == key).map(|(_, v)| v)
    } else { None }
}

fn obj_has(v: &JsonValue, key: &str) -> bool {
    if let JsonValue::Object(members) = v {
        members.iter().any(|(k, _)| k == key)
    } else { false }
}

fn is_valid_id(v: &JsonValue) -> bool {
    matches!(v, JsonValue::Str(_) | JsonValue::Int(_))
}

fn is_json_int(v: &JsonValue) -> bool {
    matches!(v, JsonValue::Int(_))
}

fn make_id(v: &JsonValue) -> String {
    match v {
        JsonValue::Str(s) => escape_str(s),
        JsonValue::Int(n) => format!("{}", n),
        _ => "null".to_string(),
    }
}

fn make_result(id_json: &str, result_json: &str) -> String {
    format!("{{\"jsonrpc\":\"2.0\",\"id\":{},\"result\":{}}}", id_json, result_json)
}

fn make_error(id_json: &str, code: i64, msg: &str) -> String {
    format!("{{\"jsonrpc\":\"2.0\",\"id\":{},\"error\":{{\"code\":{},\"message\":{}}}}}", id_json, code, escape_str(msg))
}

