// Content-Type / Content-Disposition parameter parsing
struct Param {
    var name: String // lowercased
    var value: String // raw value (token or unquoted string)
    var isQuoted: Bool
}

func parseContentType(_ value: String) -> (type: String, subtype: String, params: [Param]) {
    let chars = Array(value)
    var i = 0

    // Skip leading spaces/tabs
    while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }

    // Read type
    var type = ""
    while i < chars.count && chars[i] != "/" && chars[i] != ";" && chars[i] != " " && chars[i] != "\t" {
        type.append(chars[i])
        i += 1
    }

    // Skip spaces/tabs
    while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }

    // Expect /
    if i < chars.count && chars[i] == "/" { i += 1 }

    // Skip spaces/tabs
    while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }

    // Read subtype
    var subtype = ""
    while i < chars.count && chars[i] != ";" && chars[i] != " " && chars[i] != "\t" {
        subtype.append(chars[i])
        i += 1
    }

    // Parse parameters
    var params: [Param] = []
    while i < chars.count {
        // Skip spaces/tabs
        while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }

        // Expect ;
        if i < chars.count && chars[i] == ";" { i += 1 } else { break }

        // Skip spaces/tabs
        while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }

        // Read attribute name
        var attrName = ""
        while i < chars.count && chars[i] != "=" && chars[i] != ";" && chars[i] != " " && chars[i] != "\t" {
            attrName.append(chars[i])
            i += 1
        }

        // Skip spaces/tabs
        while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }

        // Expect =
        if i < chars.count && chars[i] == "=" { i += 1 } else { break }

        // Skip spaces/tabs
        while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }

        // Read value
        var paramValue = ""
        var isQuoted = false
        if i < chars.count && chars[i] == "\"" {
            isQuoted = true
            i += 1
            while i < chars.count && chars[i] != "\"" {
                if chars[i] == "\\" && i + 1 < chars.count {
                    paramValue.append(chars[i+1])
                    i += 2
                } else {
                    paramValue.append(chars[i])
                    i += 1
                }
            }
            if i < chars.count && chars[i] == "\"" { i += 1 }
        } else {
            while i < chars.count && chars[i] != ";" && chars[i] != " " && chars[i] != "\t" {
                paramValue.append(chars[i])
                i += 1
            }
        }

        params.append(Param(name: attrName.lowercased(), value: paramValue, isQuoted: isQuoted))
    }

    return (type.lowercased(), subtype.lowercased(), params)
}

func parseDisposition(_ value: String) -> (disposition: String, params: [Param]) {
    let chars = Array(value)
    var i = 0

    // Skip leading spaces/tabs
    while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }

    // Read disposition type
    var disp = ""
    while i < chars.count && chars[i] != ";" && chars[i] != " " && chars[i] != "\t" {
        disp.append(chars[i])
        i += 1
    }

    // Parse parameters (same as content-type)
    var params: [Param] = []
    while i < chars.count {
        while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }
        if i < chars.count && chars[i] == ";" { i += 1 } else { break }
        while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }

        var attrName = ""
        while i < chars.count && chars[i] != "=" && chars[i] != ";" && chars[i] != " " && chars[i] != "\t" {
            attrName.append(chars[i])
            i += 1
        }
        while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }
        if i < chars.count && chars[i] == "=" { i += 1 } else { break }
        while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }

        var paramValue = ""
        var isQuoted = false
        if i < chars.count && chars[i] == "\"" {
            isQuoted = true
            i += 1
            while i < chars.count && chars[i] != "\"" {
                if chars[i] == "\\" && i + 1 < chars.count {
                    paramValue.append(chars[i+1])
                    i += 2
                } else {
                    paramValue.append(chars[i])
                    i += 1
                }
            }
            if i < chars.count && chars[i] == "\"" { i += 1 }
        } else {
            while i < chars.count && chars[i] != ";" && chars[i] != " " && chars[i] != "\t" {
                paramValue.append(chars[i])
                i += 1
            }
        }

        params.append(Param(name: attrName.lowercased(), value: paramValue, isQuoted: isQuoted))
    }

    return (disp.lowercased(), params)
}

// RFC 2231 file name extraction
func extractRFC2231Param(params: [Param], attrName: String) -> String? {
    let target = attrName.lowercased()

    // Check for RFC 2231 form: attr* or attr*N or attr*N*
    var segments: [(index: Int, value: String, isEncoded: Bool)] = []
    var charset: String? = nil

    for p in params {
        let name = p.name
        if name == target + "*" {
            // Single encoded parameter: attr*=charset'language'value
            // Parse charset'language'value
            let v = p.value
            if let firstQuote = v.firstIndex(of: "'") {
                let cs = String(v[v.startIndex..<firstQuote])
                let rest = v[v.index(after: firstQuote)...]
                if let secondQuote = rest.firstIndex(of: "'") {
                    // charset'language'percent-encoded-value
                    charset = cs
                    let encodedValue = String(rest[rest.index(after: secondQuote)...])
                    segments.append((index: 0, value: encodedValue, isEncoded: true))
                } else {
                    // charset'value (no language)
                    charset = cs
                    segments.append((index: 0, value: String(rest), isEncoded: true))
                }
            }
        } else if name.hasPrefix(target + "*") {
            let suffix = String(name.dropFirst(target.count + 1))
            var isEncoded = false
            var idxStr = suffix
            if idxStr.hasSuffix("*") {
                isEncoded = true
                idxStr = String(idxStr.dropLast())
            }
            if let idx = Int(idxStr) {
                segments.append((index: idx, value: p.value, isEncoded: isEncoded))
                if isEncoded && idx == 0 {
                    // First encoded segment has charset'language'value
                    let v = p.value
                    if let firstQuote = v.firstIndex(of: "'") {
                        let cs = String(v[v.startIndex..<firstQuote])
                        let rest = v[v.index(after: firstQuote)...]
                        if let secondQuote = rest.firstIndex(of: "'") {
                            charset = cs
                            let encodedValue = String(rest[rest.index(after: secondQuote)...])
                            // Update the segment
                            segments.removeAll { $0.index == 0 && $0.isEncoded }
                            segments.append((index: 0, value: encodedValue, isEncoded: true))
                        } else {
                            charset = cs
                            segments.removeAll { $0.index == 0 && $0.isEncoded }
                            segments.append((index: 0, value: String(rest), isEncoded: true))
                        }
                    }
                }
            }
        }
    }

    if segments.isEmpty { return nil }

    // Sort by index
    segments.sort { $0.index < $1.index }

    // Percent-decode encoded segments
    var allBytes: [UInt8] = []
    for seg in segments {
        if seg.isEncoded {
            allBytes.append(contentsOf: percentDecode(seg.value))
        } else {
            allBytes.append(contentsOf: Array(seg.value.utf8))
        }
    }

    let cs = charset ?? "us-ascii"
    return decodeCharset(allBytes, cs)
}

func percentDecode(_ s: String) -> [UInt8] {
    var bytes: [UInt8] = []
    let chars = Array(s.utf8)
    var i = 0
    while i < chars.count {
        if chars[i] == 0x25 && i + 2 < chars.count {
            let h1 = hexVal(chars[i+1])
            let h2 = hexVal(chars[i+2])
            if h1 >= 0 && h2 >= 0 {
                bytes.append(UInt8(h1 * 16 + h2))
                i += 3
            } else {
                bytes.append(chars[i])
                i += 1
            }
        } else {
            bytes.append(chars[i])
            i += 1
        }
    }
    return bytes
}

// Quoted string output
func quotedString(_ s: String) -> String {
    var result = "\""
    for c in s.unicodeScalars {
        switch c {
        case "\\":
            result += "\\\\"
        case "\"":
            result += "\\\""
        case "\n":
            result += "\\n"
        case "\t":
            result += "\\t"
        default:
            if c.value < 0x20 || (c.value >= 0x7F && c.value <= 0x9F) {
                result += String(format: "\\u%04x", c.value)
            } else {
                result += String(c)
            }
        }
    }
    result += "\""
    return result
}

// Main entity structure
struct Entity {
    var headers: [(name: String, value: String)] // unfolded, name lowercased
    var bodyBytes: [UInt8]
    var lineBreak: [UInt8]
    var parts: [Entity]? // nil if not multipart
}

func getHeader(_ entity: Entity, _ name: String) -> String? {
    let target = name.lowercased()
    for (n, v) in entity.headers {
        if n == target { return v }
    }
    return nil
}

func parseEntity(_ data: [UInt8], lineBreak: [UInt8]) -> Entity {
    // Find empty line (header/body separator)
    var headerEnd = 0
    var i = 0
    while i < data.count {
        // Check for empty line: line break immediately followed by another line break
        if i + lineBreak.count * 2 <= data.count {
            if Array(data[i..<i+lineBreak.count]) == lineBreak && Array(data[i+lineBreak.count..<i+lineBreak.count*2]) == lineBreak {
                headerEnd = i + lineBreak.count // body starts after the empty line's line break
                i += lineBreak.count * 2
                break
            }
        }
        // Check if we're at start and first thing is empty line (no headers)
        if i == 0 && lineBreak.count <= data.count && Array(data[0..<lineBreak.count]) == lineBreak {
            headerEnd = lineBreak.count
            i = lineBreak.count
            break
        }
        // Skip to next line break
        if i + lineBreak.count <= data.count && Array(data[i..<i+lineBreak.count]) == lineBreak {
            i += lineBreak.count
        } else {
            i += 1
        }
    }

    // If no empty line found, all is headers (or all is body if no headers)
    // Actually if we never found the separator, the whole thing is headers with empty body
    // Hmm, but the spec says "header lines, an empty line, then the body"
    // If there's no empty line, maybe the whole file is headers? Or maybe the body is empty?
    // Let me handle the case where headerEnd is still 0 and we didn't find a separator
    if headerEnd == 0 && i >= data.count {
        // No separator found - treat all as headers, body is empty
        // Actually, let me reconsider. If the file starts with a line break, that's the separator.
        // If there's no line break at all, there are no headers and the body is the whole file?
        // The spec says "A part may have no header lines at all (it then starts with the empty line)."
        // So the empty line is always present. Let me assume it's always there.
        // If we can't find it, let's say body is empty.
        headerEnd = data.count
    }

    // Parse headers
    let headerData = Array(data[0..<headerEnd]) // includes trailing line break(s)
    // Actually, headerEnd points to the start of the body (after the empty line)
    // The header section is data[0..<headerEnd-lineBreak.count] (without the empty line's line break)
    // Wait, let me reconsider.

    // Actually let me redo this. Let me find the position of the empty line separator.
    // The empty line is a line break immediately following another line break (or at the start of the file).
    // After the empty line, the body starts.

    // Let me re-find:
    var sepPos = -1 // position of the start of the empty line (the first line break of the two)
    var bodyStart = -1 // position where body starts

    i = 0
    if i + lineBreak.count <= data.count && Array(data[i..<i+lineBreak.count]) == lineBreak {
        // File starts with empty line (no headers)
        sepPos = 0
        bodyStart = lineBreak.count
    } else {
        // Find \r\n\r\n or \n\n
        while i < data.count {
            if i + lineBreak.count * 2 <= data.count {
                if Array(data[i..<i+lineBreak.count]) == lineBreak && Array(data[i+lineBreak.count..<i+lineBreak.count*2]) == lineBreak {
                    sepPos = i
                    bodyStart = i + lineBreak.count * 2
                    break
                }
            }
            // Move to next line break
            if i + lineBreak.count <= data.count && Array(data[i..<i+lineBreak.count]) == lineBreak {
                i += lineBreak.count
            } else {
                i += 1
            }
        }
    }

    if sepPos < 0 {
        // No separator found - treat entire content as headers with empty body
        // Actually this shouldn't happen per spec, but handle gracefully
        sepPos = data.count
        bodyStart = data.count
    }

    let headerSection = Array(data[0..<sepPos])
    let bodySection = Array(data[bodyStart...])

    // Unfold headers
    var unfoldedHeaders: [(name: String, value: String)] = []
    let headerLines = splitLines(headerSection, lineBreak: lineBreak)

    var currentLine = ""
    for line in headerLines {
        if line.isEmpty { break } // shouldn't happen since we already found the separator
        if line.first == " " || line.first == "\t" {
            // Continuation line
            currentLine += line
        } else {
            if !currentLine.isEmpty {
                unfoldedHeaders.append(parseHeaderLine(currentLine))
            }
            currentLine = line
        }
    }
    if !currentLine.isEmpty {
        unfoldedHeaders.append(parseHeaderLine(currentLine))
    }

    let entity = Entity(headers: unfoldedHeaders, bodyBytes: bodySection, lineBreak: lineBreak, parts: nil)

    // Check if multipart
    let ct = getHeader(entity, "content-type")
    let (type, subtype, ctParams) = parseContentType(ct ?? "text/plain")

    if type == "multipart" && !subtype.isEmpty {
        // Find boundary
        var boundary: String? = nil
        for p in ctParams {
            if p.name == "boundary" {
                boundary = p.value
                break
            }
        }

        if let b = boundary {
            let parts = splitMultipart(bodySection, boundary: b, lineBreak: lineBreak)
            let partsEntities = parts.map { parseEntity($0, lineBreak: lineBreak) }
            return Entity(headers: unfoldedHeaders, bodyBytes: bodySection, lineBreak: lineBreak, parts: partsEntities)
        }
    }

    return entity
}

func splitLines(_ data: [UInt8], lineBreak: [UInt8]) -> [String] {
    var lines: [String] = []
    var current: [UInt8] = []
    var i = 0
    while i < data.count {
        if i + lineBreak.count <= data.count && Array(data[i..<i+lineBreak.count]) == lineBreak {
            lines.append(String(bytes: current, encoding: .ascii) ?? "")
            current = []
            i += lineBreak.count
        } else {
            current.append(data[i])
            i += 1
        }
    }
    if !current.isEmpty {
        lines.append(String(bytes: current, encoding: .ascii) ?? "")
    }
    return lines
}

func parseHeaderLine(_ line: String) -> (name: String, value: String) {
    let colonIdx = line.firstIndex(of: ":")!
    let name = String(line[line.startIndex..<colonIdx]).lowercased()
    var value = String(line[line.index(after: colonIdx)...])
    // Trim leading and trailing spaces/tabs
    while value.hasPrefix(" ") || value.hasPrefix("\t") { value.removeFirst() }
    while value.hasSuffix(" ") || value.hasSuffix("\t") { value.removeLast() }
    return (name, value)
}

func splitMultipart(_ body: [UInt8], boundary: String, lineBreak: [UInt8]) -> [[UInt8]] {
    let delimiter = Array(("--" + boundary).utf8)
    let closeDelimiter = Array(("--" + boundary + "--").utf8)

    // Find all delimiter and close-delimiter positions
    // A delimiter line: starts at beginning of a line, content is exactly delimiter + optional spaces/tabs
    // A close delimiter: starts at beginning of a line, content is exactly closeDelimiter + optional spaces/tabs

    struct DelimPos {
        var lineStart: Int // position of start of delimiter text (after line break)
        var lineEnd: Int // position after the line break following the delimiter
        var isClose: Bool
    }

    var delims: [DelimPos] = []
    var pos = 0

    // Check if body starts with delimiter (no preamble)
    // We need to check each line
    // First, let's find all line starts
    var lineStarts: [Int] = [0]
    var li = 0
    while li < body.count {
        if li + lineBreak.count <= body.count && Array(body[li..<li+lineBreak.count]) == lineBreak {
            lineStarts.append(li + lineBreak.count)
            li += lineBreak.count
        } else {
            li += 1
        }
    }

    for ls in lineStarts {
        let remaining = body.count - ls
        // Check if this line is a delimiter or close delimiter
        if remaining >= closeDelimiter.count && Array(body[ls..<ls+closeDelimiter.count]) == closeDelimiter {
            // Check what follows closeDelimiter
            var after = ls + closeDelimiter.count
            // Skip spaces/tabs
            while after < body.count && (body[after] == 0x20 || body[after] == 0x09) {
                after += 1
            }
            // Must be end of line or end of data
            if after >= body.count || (after + lineBreak.count <= body.count && Array(body[after..<after+lineBreak.count]) == lineBreak) {
                var lineEnd = after
                if after + lineBreak.count <= body.count && Array(body[after..<after+lineBreak.count]) == lineBreak {
                    lineEnd = after + lineBreak.count
                }
                delims.append(DelimPos(lineStart: ls, lineEnd: lineEnd, isClose: true))
                continue
            }
        }

        if remaining >= delimiter.count && Array(body[ls..<ls+delimiter.count]) == delimiter {
            // Check what follows delimiter
            var after = ls + delimiter.count
            // Skip spaces/tabs
            while after < body.count && (body[after] == 0x20 || body[after] == 0x09) {
                after += 1
            }
            // Must be end of line or end of data
            if after >= body.count || (after + lineBreak.count <= body.count && Array(body[after..<after+lineBreak.count]) == lineBreak) {
                var lineEnd = after
                if after + lineBreak.count <= body.count && Array(body[after..<after+lineBreak.count]) == lineBreak {
                    lineEnd = after + lineBreak.count
                }
                delims.append(DelimPos(lineStart: ls, lineEnd: lineEnd, isClose: false))
            }
        }
    }

    // Find first delimiter and close delimiter
    guard let firstDelimIdx = delims.firstIndex(where: { !$0.isClose }) else { return [] }
    let closeIdx = delims.firstIndex(where: { $0.isClose })

    var parts: [[UInt8]] = []

    // Parts are between consecutive delimiters (from first delimiter to close delimiter)
    // The content of each part starts right after the delimiter's line break
    // and ends just before the line break that precedes the next delimiter

    let relevantDelims: [DelimPos]
    if let ci = closeIdx {
        relevantDelims = Array(delims[firstDelimIdx...ci])
    } else {
        // No close delimiter? Use all delimiters from first onwards
        relevantDelims = Array(delims[firstDelimIdx...])
    }

    if relevantDelims.count < 2 { return [] }

    for k in 0..<(relevantDelims.count - 1) {
        let d1 = relevantDelims[k]
        let d2 = relevantDelims[k + 1]

        // Content starts at d1.lineEnd (after the line break following the delimiter line)
        let contentStart = d1.lineEnd

        // Content ends at d2.lineStart - lineBreak.count (the line break before the next delimiter belongs to the delimiter)
        let contentEnd = d2.lineStart - lineBreak.count

        if contentStart <= contentEnd {
            parts.append(Array(body[contentStart..<contentEnd]))
        } else {
            parts.append([])
        }
    }

    return parts
}

// Main
let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }

let dir = args[1]
let fm = FileManager.default
guard let files = try? fm.contentsOfDirectory(atPath: dir) else { exit(1) }

let emlFiles = files.filter { $0.hasSuffix(".eml") }.sorted()

var firstFile = true

for fileName in emlFiles {
    let filePath = dir + "/" + fileName

    guard let data = fm.contents(atPath: filePath) else { continue }
    let bytes = [UInt8](data)

    // Detect line break
    let lineBreak: [UInt8]
    if bytes.contains(0x0D) && bytes.contains(0x0A) {
        // Check if CRLF exists
        var hasCRLF = false
        for i in 0..<bytes.count-1 {
            if bytes[i] == 0x0D && bytes[i+1] == 0x0A {
                hasCRLF = true
                break
            }
        }
        lineBreak = hasCRLF ? [0x0D, 0x0A] : [0x0A]
    } else {
        lineBreak = [0x0A]
    }

    let entity = parseEntity(bytes, lineBreak: lineBreak)

    // Print output
    if !firstFile {
        print("")
    }
    firstFile = false

    print("== \(fileName)")

    // From header
    if let from = getHeader(entity, "from") {
        print("From: \(quotedString(decodeRFC2047(from)))")
    } else {
        print("From: -")
    }

    // Subject header
    if let subject = getHeader(entity, "subject") {
        print("Subject: \(quotedString(decodeRFC2047(subject)))")
    } else {
        print("Subject: -")
    }

    // Print tree
    printTree(entity, indent: 0, lineBreak: lineBreak)
}

func printTree(_ entity: Entity, indent: Int, lineBreak: [UInt8]) {
    let prefix = String(repeating: "  ", count: indent)

    let ct = getHeader(entity, "content-type")
    let (type, subtype, ctParams) = parseContentType(ct ?? "text/plain")

    let cte = (getHeader(entity, "content-transfer-encoding") ?? "7bit").lowercased()

    if type == "multipart" && entity.parts != nil {
        print("\(prefix)multipart/\(subtype) parts=\(entity.parts!.count)")
        for part in entity.parts! {
            printTree(part, indent: indent + 1, lineBreak: lineBreak)
        }
    } else {
        // Check disposition
        let cd = getHeader(entity, "content-disposition")
        var dispType = "-"
        var cdParams: [Param] = []
        if let cdv = cd {
            let (dt, dp) = parseDisposition(cdv)
            dispType = dt
            cdParams = dp
        }

        // Check if text part (not attachment)
        let isText = type == "text" && dispType != "attachment"

        // Get charset
        var charset = "us-ascii"
        for p in ctParams {
            if p.name == "charset" {
                charset = p.value.lowercased()
                break
            }
        }

        // Decode body
        let decodedBytes = decodeCTE(entity.bodyBytes, cte, lineBreak: lineBreak)

        if isText {
            // Decode text
            var text = decodeCharset(decodedBytes, charset)
            // Replace CRLF and lone CR with LF
            text = text.replacingOccurrences(of: "\r\n", with: "\n")
            text = text.replacingOccurrences(of: "\r", with: "\n")

            let charCount = text.count
            print("\(prefix)text/\(subtype) charset=\(charset) cte=\(cte) chars=\(charCount)")
            print("\(prefix)  \(quotedString(text))")
        } else {
            // Non-text part
            let size = decodedBytes.count
            let crc = crc32(decodedBytes)

            // Get file name
            var name: String? = nil

            // RFC 2231 filename from Content-Disposition
            if !cdParams.isEmpty {
                name = extractRFC2231Param(params: cdParams, attrName: "filename")
            }
            // Regular filename from Content-Disposition
            if name == nil {
                for p in cdParams {
                    if p.name == "filename" {
                        name = decodeRFC2047(p.value)
                        break
                    }
                }
            }
            // RFC 2231 name from Content-Type
            if name == nil {
                name = extractRFC2231Param(params: ctParams, attrName: "name")
            }
            // Regular name from Content-Type
            if name == nil {
                for p in ctParams {
                    if p.name == "name" {
                        name = decodeRFC2047(p.value)
                        break
                    }
                }
            }

            let nameStr = name != nil ? quotedString(name!) : "-"

            print("\(prefix)\(type)/\(subtype) cte=\(cte) disposition=\(dispType) name=\(nameStr) size=\(size) crc32=\(String(format: "%08x", crc))")
        }
    }
}

import Foundation

// CRC-32 (zlib/PNG)
func crc32(_ data: [UInt8]) -> UInt32 {
    var crc: UInt32 = 0xFFFFFFFF
    for byte in data {
        crc ^= UInt32(byte)
        for _ in 0..<8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320
            } else {
                crc >>= 1
            }
        }
    }
    return crc ^ 0xFFFFFFFF
}

// Base64 lookup table
let base64Lookup: [UInt8: UInt8] = {
    var table = [UInt8: UInt8]()
    let alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    for (i, c) in alphabet.utf8.enumerated() {
        table[c] = UInt8(i)
    }
    return table
}()

// Base64 decode
func base64Decode(_ data: [UInt8]) -> [UInt8] {
    var filtered: [UInt8] = []
    for b in data {
        if b == 0x3D { break }
        if let val = base64Lookup[b] {
            filtered.append(val)
        }
    }

    var result: [UInt8] = []
    var i = 0
    while i < filtered.count {
        let remaining = filtered.count - i
        if remaining >= 4 {
            let b0 = filtered[i], b1 = filtered[i+1], b2 = filtered[i+2], b3 = filtered[i+3]
            result.append((b0 << 2) | (b1 >> 4))
            result.append(((b1 & 0x0F) << 4) | (b2 >> 2))
            result.append(((b2 & 0x03) << 6) | b3)
            i += 4
        } else if remaining == 3 {
            let b0 = filtered[i], b1 = filtered[i+1], b2 = filtered[i+2]
            result.append((b0 << 2) | (b1 >> 4))
            result.append(((b1 & 0x0F) << 4) | (b2 >> 2))
            i += 3
        } else if remaining == 2 {
            let b0 = filtered[i], b1 = filtered[i+1]
            result.append((b0 << 2) | (b1 >> 4))
            i += 2
        } else {
            break
        }
    }
    return result
}

func hexVal(_ b: UInt8) -> Int {
    if b >= 0x30 && b <= 0x39 { return Int(b - 0x30) }
    if b >= 0x41 && b <= 0x46 { return Int(b - 0x41 + 10) }
    if b >= 0x61 && b <= 0x66 { return Int(b - 0x61 + 10) }
    return -1
}

// Quoted-printable decode
func quotedPrintableDecode(_ data: [UInt8], lineBreak: [UInt8]) -> [UInt8] {
    // Split into lines
    var lines: [[UInt8]] = []
    var current: [UInt8] = []
    var i = 0
    while i < data.count {
        if i + lineBreak.count <= data.count && Array(data[i..<i+lineBreak.count]) == lineBreak {
            lines.append(current)
            current = []
            i += lineBreak.count
        } else {
            current.append(data[i])
            i += 1
        }
    }
    lines.append(current)

    // Remove trailing spaces/tabs from each line
    for j in 0..<lines.count {
        while let last = lines[j].last, last == 0x20 || last == 0x09 {
            lines[j].removeLast()
        }
    }

    // Join soft line breaks
    var joined: [UInt8] = []
    var j = 0
    while j < lines.count {
        if lines[j].last == 0x3D && j < lines.count - 1 {
            joined.append(contentsOf: lines[j].dropLast())
            j += 1
        } else {
            joined.append(contentsOf: lines[j])
            if j < lines.count - 1 {
                joined.append(contentsOf: lineBreak)
            }
            j += 1
        }
    }

    // Decode =XY sequences
    var result: [UInt8] = []
    var k = 0
    while k < joined.count {
        if joined[k] == 0x3D && k + 2 < joined.count {
            let h1 = hexVal(joined[k+1])
            let h2 = hexVal(joined[k+2])
            if h1 >= 0 && h2 >= 0 {
                result.append(UInt8(h1 * 16 + h2))
                k += 3
            } else {
                result.append(0x3D)
                k += 1
            }
        } else {
            result.append(joined[k])
            k += 1
        }
    }
    return result
}

// Transfer encoding decode
func decodeCTE(_ data: [UInt8], _ encoding: String, lineBreak: [UInt8]) -> [UInt8] {
    let enc = encoding.lowercased()
    switch enc {
    case "base64":
        return base64Decode(data)
    case "quoted-printable":
        return quotedPrintableDecode(data, lineBreak: lineBreak)
    default:
        return data
    }
}

// Charset decoding
func decodeCharset(_ bytes: [UInt8], _ charset: String) -> String {
    let cs = charset.lowercased()
    switch cs {
    case "us-ascii", "ascii":
        return String(bytes.map { Character(UnicodeScalar($0)) })
    case "utf-8":
        return String(bytes: bytes, encoding: .utf8) ?? ""
    case "iso-8859-1", "latin1", "latin-1":
        return String(bytes.map { Character(UnicodeScalar($0)) })
    case "windows-1252":
        let cp1252: [UInt32] = [
            0x20AC, 0x0081, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021,
            0x02C6, 0x2030, 0x0160, 0x2039, 0x0152, 0x008D, 0x017D, 0x008F,
            0x0090, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014,
            0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0x009D, 0x017E, 0x0178
        ]
        var result = ""
        for b in bytes {
            if b >= 0x80 && b <= 0x9F {
                let cp = cp1252[Int(b - 0x80)]
                result += String(UnicodeScalar(cp)!)
            } else {
                result += String(UnicodeScalar(b))
            }
        }
        return result
    default:
        return String(bytes.map { Character(UnicodeScalar($0)) })
    }
}

// RFC 2047 encoded-word matching
struct EncodedWordMatch {
    var bytes: [UInt8]
    var charset: String
    var end: Int
}

func matchEncodedWord(_ chars: [Character], from start: Int) -> EncodedWordMatch? {
    var i = start
    guard i + 1 < chars.count && chars[i] == "=" && chars[i+1] == "?" else { return nil }
    i += 2

    // charset: one or more chars other than ?, space, tab
    var charset = ""
    while i < chars.count && chars[i] != "?" && chars[i] != " " && chars[i] != "\t" {
        charset.append(chars[i])
        i += 1
    }
    if charset.isEmpty || i >= chars.count || chars[i] != "?" { return nil }
    i += 1

    // encoding: B, b, Q, q
    guard i < chars.count && (chars[i] == "B" || chars[i] == "b" || chars[i] == "Q" || chars[i] == "q") else { return nil }
    let encoding = chars[i]
    i += 1

    guard i < chars.count && chars[i] == "?" else { return nil }
    i += 1

    // encoded-text: zero or more chars other than ?, space, tab
    var encodedText = ""
    while i < chars.count && chars[i] != "?" && chars[i] != " " && chars[i] != "\t" {
        encodedText.append(chars[i])
        i += 1
    }
    guard i < chars.count && chars[i] == "?" else { return nil }
    i += 1
    guard i < chars.count && chars[i] == "=" else { return nil }
    i += 1

    // Decode
    var bytes: [UInt8] = []
    if encoding == "B" || encoding == "b" {
        bytes = base64Decode(Array(encodedText.utf8))
    } else {
        var j = 0
        let et = Array(encodedText.utf8)
        while j < et.count {
            if et[j] == 0x5F {
                bytes.append(0x20)
                j += 1
            } else if et[j] == 0x3D && j + 2 < et.count {
                let h1 = hexVal(et[j+1])
                let h2 = hexVal(et[j+2])
                if h1 >= 0 && h2 >= 0 {
                    bytes.append(UInt8(h1 * 16 + h2))
                    j += 3
                } else {
                    bytes.append(0x3D)
                    j += 1
                }
            } else {
                bytes.append(et[j])
                j += 1
            }
        }
    }

    return EncodedWordMatch(bytes: bytes, charset: charset, end: i)
}

func normalizeCharset(_ cs: String) -> String {
    // Remove *language suffix
    if let starPos = cs.firstIndex(of: "*") {
        return String(cs[cs.startIndex..<starPos]).lowercased()
    }
    return cs.lowercased()
}

// RFC 2047 decode
func decodeRFC2047(_ text: String) -> String {
    let chars = Array(text)
    var result = ""
    var i = 0
    var prevWasEncodedWordEnd = false

    while i < chars.count {
        if chars[i] == "=" && i + 1 < chars.count && chars[i+1] == "?" {
            if let match = matchEncodedWord(chars, from: i) {
                let cs = normalizeCharset(match.charset)
                var bytes = match.bytes
                var pos = match.end

                // Extend run with same-charset adjacent words
                while pos < chars.count {
                    var j = pos
                    while j < chars.count && (chars[j] == " " || chars[j] == "\t") { j += 1 }
                    if j < chars.count && chars[j] == "=" && j + 1 < chars.count && chars[j+1] == "?" {
                        if let nextMatch = matchEncodedWord(chars, from: j) {
                            if normalizeCharset(nextMatch.charset) == cs {
                                bytes.append(contentsOf: nextMatch.bytes)
                                pos = nextMatch.end
                                continue
                            }
                        }
                    }
                    break
                }

                let decoded = decodeCharset(bytes, match.charset.replacingOccurrences(of: "*", with: "").split(separator: "*").first.map(String.init) ?? match.charset)
                // Actually use the full charset name (before *) for decoding
                let fullCharset = match.charset.contains("*") ? String(match.charset[match.charset.startIndex..<match.charset.firstIndex(of: "*")!]) : match.charset
                let decodedText = decodeCharset(bytes, fullCharset)
                result += decodedText
                i = pos
                prevWasEncodedWordEnd = true
                continue
            }
        }

        if chars[i] == " " || chars[i] == "\t" {
            // Check if between adjacent encoded-words
            var j = i
            while j < chars.count && (chars[j] == " " || chars[j] == "\t") { j += 1 }
            if prevWasEncodedWordEnd && j < chars.count && chars[j] == "=" && j + 1 < chars.count && chars[j+1] == "?" {
                if matchEncodedWord(chars, from: j) != nil {
                    i = j
                    continue
                }
            }
            result.append(chars[i])
            i += 1
            prevWasEncodedWordEnd = false
        } else {
            result.append(chars[i])
            i += 1
            prevWasEncodedWordEnd = false
        }
    }
    return result
}

// Parameter structure
struct Param {
    var name: String // lowercased
    var value: String
    var isQuoted: Bool
}

// Parse Content-Type value
func parseContentType(_ value: String) -> (type: String, subtype: String, params: [Param]) {
    let chars = Array(value)
    var i = 0

    while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }

    var type = ""
    while i < chars.count && chars[i] != "/" && chars[i] != ";" && chars[i] != " " && chars[i] != "\t" {
        type.append(chars[i]); i += 1
    }

    while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }
    if i < chars.count && chars[i] == "/" { i += 1 }
    while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }

    var subtype = ""
    while i < chars.count && chars[i] != ";" && chars[i] != " " && chars[i] != "\t" {
        subtype.append(chars[i]); i += 1
    }

    var params: [Param] = []
    while i < chars.count {
        while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }
        if i >= chars.count { break }
        if chars[i] != ";" { break }
        i += 1
        while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }

        var attrName = ""
        while i < chars.count && chars[i] != "=" && chars[i] != ";" && chars[i] != " " && chars[i] != "\t" {
            attrName.append(chars[i]); i += 1
        }
        while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }
        if i >= chars.count || chars[i] != "=" { break }
        i += 1
        while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }

        var paramValue = ""
        var isQuoted = false
        if i < chars.count && chars[i] == "\"" {
            isQuoted = true
            i += 1
            while i < chars.count && chars[i] != "\"" {
                if chars[i] == "\\" && i + 1 < chars.count {
                    paramValue.append(chars[i+1]); i += 2
                } else {
                    paramValue.append(chars[i]); i += 1
                }
            }
            if i < chars.count && chars[i] == "\"" { i += 1 }
        } else {
            while i < chars.count && chars[i] != ";" && chars[i] != " " && chars[i] != "\t" {
                paramValue.append(chars[i]); i += 1
            }
        }
        params.append(Param(name: attrName.lowercased(), value: paramValue, isQuoted: isQuoted))
    }

    return (type.lowercased(), subtype.lowercased(), params)
}

// Parse Content-Disposition value
func parseDisposition(_ value: String) -> (disposition: String, params: [Param]) {
    let chars = Array(value)
    var i = 0

    while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }

    var disp = ""
    while i < chars.count && chars[i] != ";" && chars[i] != " " && chars[i] != "\t" {
        disp.append(chars[i]); i += 1
    }

    var params: [Param] = []
    while i < chars.count {
        while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }
        if i >= chars.count { break }
        if chars[i] != ";" { break }
        i += 1
        while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }

        var attrName = ""
        while i < chars.count && chars[i] != "=" && chars[i] != ";" && chars[i] != " " && chars[i] != "\t" {
            attrName.append(chars[i]); i += 1
        }
        while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }
        if i >= chars.count || chars[i] != "=" { break }
        i += 1
        while i < chars.count && (chars[i] == " " || chars[i] == "\t") { i += 1 }

        var paramValue = ""
        var isQuoted = false
        if i < chars.count && chars[i] == "\"" {
            isQuoted = true
            i += 1
            while i < chars.count && chars[i] != "\"" {
                if chars[i] == "\\" && i + 1 < chars.count {
                    paramValue.append(chars[i+1]); i += 2
                } else {
                    paramValue.append(chars[i]); i += 1
                }
            }
            if i < chars.count && chars[i] == "\"" { i += 1 }
        } else {
            while i < chars.count && chars[i] != ";" && chars[i] != " " && chars[i] != "\t" {
                paramValue.append(chars[i]); i += 1
            }
        }
        params.append(Param(name: attrName.lowercased(), value: paramValue, isQuoted: isQuoted))
    }

    return (disp.lowercased(), params)
}

// Percent decode
func percentDecode(_ s: String) -> [UInt8] {
    var bytes: [UInt8] = []
    let chars = Array(s.utf8)
    var i = 0
    while i < chars.count {
        if chars[i] == 0x25 && i + 2 < chars.count {
            let h1 = hexVal(chars[i+1])
            let h2 = hexVal(chars[i+2])
            if h1 >= 0 && h2 >= 0 {
                bytes.append(UInt8(h1 * 16 + h2))
                i += 3
            } else {
                bytes.append(chars[i]); i += 1
            }
        } else {
            bytes.append(chars[i]); i += 1
        }
    }
    return bytes
}

// RFC 2231 parameter extraction
func extractRFC2231Param(params: [Param], attrName: String) -> String? {
    let target = attrName.lowercased()

    // Check if any RFC 2231 form parameters exist for this attribute
    var hasRFC2231 = false
    for p in params {
        if p.name == target + "*" { hasRFC2231 = true; break }
        if p.name.hasPrefix(target + "*") {
            let suffix = String(p.name.dropFirst(target.count + 1))
            var numPart = suffix
            if numPart.hasSuffix("*") { numPart = String(numPart.dropLast()) }
            if Int(numPart) != nil { hasRFC2231 = true; break }
        }
    }
    if !hasRFC2231 { return nil }

    // Collect segments
    struct Seg { var index: Int; var value: String; var isEncoded: Bool }
    var segments: [Seg] = []
    var charset: String? = nil

    for p in params {
        let name = p.name
        if name == target + "*" {
            // Single encoded parameter: attr*=charset'language'value
            let v = p.value
            if let firstQ = v.firstIndex(of: "'") {
                let cs = String(v[v.startIndex..<firstQ])
                let rest = v[v.index(after: firstQ)...]
                if let secondQ = rest.firstIndex(of: "'") {
                    charset = cs
                    let encodedValue = String(rest[rest.index(after: secondQ)...])
                    segments.append(Seg(index: 0, value: encodedValue, isEncoded: true))
                } else {
                    charset = cs
                    segments.append(Seg(index: 0, value: String(rest), isEncoded: true))
                }
            }
        } else if name.hasPrefix(target + "*") {
            let suffix = String(name.dropFirst(target.count + 1))
            var isEncoded = false
            var idxStr = suffix
            if idxStr.hasSuffix("*") {
                isEncoded = true
                idxStr = String(idxStr.dropLast())
            }
            if let idx = Int(idxStr) {
                segments.append(Seg(index: idx, value: p.value, isEncoded: isEncoded))
                if isEncoded && idx == 0 {
                    let v = p.value
                    if let firstQ = v.firstIndex(of: "'") {
                        let cs = String(v[v.startIndex..<firstQ])
                        let rest = v[v.index(after: firstQ)...]
                        if let secondQ = rest.firstIndex(of: "'") {
                            charset = cs
                            let encodedValue = String(rest[rest.index(after: secondQ)...])
                            // Replace segment 0
                            segments.removeAll { $0.index == 0 && $0.isEncoded }
                            segments.append(Seg(index: 0, value: encodedValue, isEncoded: true))
                        } else {
                            charset = cs
                            segments.removeAll { $0.index == 0 && $0.isEncoded }
                            segments.append(Seg(index: 0, value: String(rest), isEncoded: true))
                        }
                    }
                }
            }
        }
    }

    if segments.isEmpty { return nil }

    segments.sort { $0.index < $1.index }

    var allBytes: [UInt8] = []
    for seg in segments {
        if seg.isEncoded {
            allBytes.append(contentsOf: percentDecode(seg.value))
        } else {
            allBytes.append(contentsOf: Array(seg.value.utf8))
        }
    }

    let cs = charset ?? "us-ascii"
    return decodeCharset(allBytes, cs)
}

// Quoted string output
func quotedString(_ s: String) -> String {
    var result = "\""
    for c in s.unicodeScalars {
        switch c {
        case "\\":
            result += "\\\\"
        case "\"":
            result += "\\\""
        case "\n":
            result += "\\n"
        case "\t":
            result += "\\t"
        default:
            if c.value < 0x20 || (c.value >= 0x7F && c.value <= 0x9F) {
                result += String(format: "\\u%04x", c.value)
            } else {
                result += String(c)
            }
        }
    }
    result += "\""
    return result
}

// Entity structure
struct Entity {
    var headers: [(name: String, value: String)]
    var bodyBytes: [UInt8]
    var parts: [Entity]?
}

func getHeader(_ entity: Entity, _ name: String) -> String? {
    let target = name.lowercased()
    for (n, v) in entity.headers {
        if n == target { return v }
    }
    return nil
}

// Split bytes into lines (returns content of each line, not including line break)
func splitIntoLines(_ data: [UInt8], lineBreak: [UInt8]) -> [(content: [UInt8], endPos: Int)] {
    var lines: [(content: [UInt8], endPos: Int)] = []
    var current: [UInt8] = []
    var i = 0
    while i < data.count {
        if i + lineBreak.count <= data.count && Array(data[i..<i+lineBreak.count]) == lineBreak {
            lines.append((content: current, endPos: i + lineBreak.count))
            current = []
            i += lineBreak.count
        } else {
            current.append(data[i])
            i += 1
        }
    }
    if !current.isEmpty {
        lines.append((content: current, endPos: i))
    }
    return lines
}

func parseEntity(_ data: [UInt8], lineBreak: [UInt8]) -> Entity {
    // Find header/body separator (empty line)
    var bodyStart = 0

    if data.count >= lineBreak.count && Array(data[0..<lineBreak.count]) == lineBreak {
        // File starts with empty line (no headers)
        bodyStart = lineBreak.count
    } else {
        // Find the first empty line
        var i = 0
        var found = false
        while i < data.count {
            if i + lineBreak.count <= data.count && Array(data[i..<i+lineBreak.count]) == lineBreak {
                // Check if next line is also empty (or this is the end)
                let nextStart = i + lineBreak.count
                if nextStart >= data.count {
                    // Empty line at end: headers only, empty body
                    bodyStart = nextStart
                    found = true
                    break
                }
                if nextStart + lineBreak.count <= data.count && Array(data[nextStart..<nextStart+lineBreak.count]) == lineBreak {
                    // Two consecutive line breaks = empty line
                    bodyStart = nextStart + lineBreak.count
                    found = true
                    break
                }
                // Not an empty line, skip to next
                i = nextStart
            } else {
                i += 1
            }
        }
        if !found {
            // No separator found, treat all as headers, empty body
            bodyStart = data.count
        }
    }

    // Parse headers from data[0..<bodyStart-lineBreak.count] (everything before the empty line)
    let headerEnd = bodyStart > lineBreak.count ? bodyStart - lineBreak.count : 0
    let headerData = Array(data[0..<headerEnd])

    // Unfold headers
    var unfoldedHeaders: [(name: String, value: String)] = []
    let headerLines = splitIntoLines(headerData, lineBreak: lineBreak)

    var currentLine = ""
    for lineInfo in headerLines {
        let line = String(bytes: lineInfo.content, encoding: .ascii) ?? ""
        if line.isEmpty { continue }
        if line.first == " " || line.first == "\t" {
            currentLine += line
        } else {
            if !currentLine.isEmpty {
                unfoldedHeaders.append(parseHeaderLine(currentLine))
            }
            currentLine = line
        }
    }
    if !currentLine.isEmpty {
        unfoldedHeaders.append(parseHeaderLine(currentLine))
    }

    let bodySection = Array(data[bodyStart...])

    let entity = Entity(headers: unfoldedHeaders, bodyBytes: bodySection, parts: nil)

    // Check if multipart
    let ctRaw = getHeader(entity, "content-type")
    let (type, subtype, _) = parseContentType(ctRaw ?? "text/plain")

    if type == "multipart" {
        let (_, _, ctParams) = parseContentType(ctRaw ?? "")
        var boundary: String? = nil
        for p in ctParams {
            if p.name == "boundary" { boundary = p.value; break }
        }

        if let b = boundary {
            let partsData = splitMultipart(bodySection, boundary: b, lineBreak: lineBreak)
            let partsEntities = partsData.map { parseEntity($0, lineBreak: lineBreak) }
            return Entity(headers: unfoldedHeaders, bodyBytes: bodySection, parts: partsEntities)
        }
    }

    return entity
}

func parseHeaderLine(_ line: String) -> (name: String, value: String) {
    guard let colonIdx = line.firstIndex(of: ":") else { return (line.lowercased(), "") }
    let name = String(line[line.startIndex..<colonIdx]).lowercased()
    var value = String(line[line.index(after: colonIdx)...])
    while value.hasPrefix(" ") || value.hasPrefix("\t") { value.removeFirst() }
    while value.hasSuffix(" ") || value.hasSuffix("\t") { value.removeLast() }
    return (name, value)
}

func splitMultipart(_ body: [UInt8], boundary: String, lineBreak: [UInt8]) -> [[UInt8]] {
    let delimiterPrefix = Array(("--" + boundary).utf8)
    let closeSuffix: [UInt8] = [0x2D, 0x2D] // "--"

    struct DelimPos {
        var lineStart: Int
        var lineEnd: Int // position after the line break following delimiter
        var isClose: Bool
    }

    var delims: [DelimPos] = []

    // Find all line starts
    var lineStarts: [Int] = [0]
    var li = 0
    while li < body.count {
        if li + lineBreak.count <= body.count && Array(body[li..<li+lineBreak.count]) == lineBreak {
            lineStarts.append(li + lineBreak.count)
            li += lineBreak.count
        } else {
            li += 1
        }
    }

    for ls in lineStarts {
        let remaining = body.count - ls
        guard remaining >= delimiterPrefix.count else { continue }

        // Check if line starts with delimiterPrefix
        if Array(body[ls..<ls+delimiterPrefix.count]) != delimiterPrefix { continue }

        // Check what follows the delimiter prefix
        var after = ls + delimiterPrefix.count

        // Check for close delimiter: must have "--" after prefix
        if after + 2 <= body.count && body[after] == 0x2D && body[after+1] == 0x2D {
            after += 2
            // Skip spaces/tabs
            while after < body.count && (body[after] == 0x20 || body[after] == 0x09) { after += 1 }
            // Must be end of line or end of data
            if after >= body.count {
                delims.append(DelimPos(lineStart: ls, lineEnd: after, isClose: true))
                continue
            }
            if after + lineBreak.count <= body.count && Array(body[after..<after+lineBreak.count]) == lineBreak {
                delims.append(DelimPos(lineStart: ls, lineEnd: after + lineBreak.count, isClose: true))
                continue
            }
            // Not valid close delimiter, fall through to check as regular delimiter
        }

        // Check for regular delimiter
        after = ls + delimiterPrefix.count
        while after < body.count && (body[after] == 0x20 || body[after] == 0x09) { after += 1 }
        if after >= body.count {
            delims.append(DelimPos(lineStart: ls, lineEnd: after, isClose: false))
            continue
        }
        if after + lineBreak.count <= body.count && Array(body[after..<after+lineBreak.count]) == lineBreak {
            delims.append(DelimPos(lineStart: ls, lineEnd: after + lineBreak.count, isClose: false))
            continue
        }
        // Not a valid delimiter line (e.g., --Bxyz)
    }

    // Find first delimiter (not close)
    guard let firstIdx = delims.firstIndex(where: { !$0.isClose }) else { return [] }

    // Find close delimiter after first
    let closeIdx = delims.firstIndex(where: { $0.isClose && $0.lineStart > delims[firstIdx].lineStart })

    var relevantDelims: [DelimPos]
    if let ci = closeIdx {
        relevantDelims = Array(delims[firstIdx...ci])
    } else {
        relevantDelims = Array(delims[firstIdx...])
    }

    if relevantDelims.count < 2 { return [] }

    var parts: [[UInt8]] = []
    for k in 0..<(relevantDelims.count - 1) {
        let d1 = relevantDelims[k]
        let d2 = relevantDelims[k + 1]

        let contentStart = d1.lineEnd
        // The line break before d2 belongs to d2, not to the part
        var contentEnd = d2.lineStart
        if contentEnd >= lineBreak.count {
            contentEnd -= lineBreak.count
        }

        if contentStart <= contentEnd {
            parts.append(Array(body[contentStart..<contentEnd]))
        } else {
            parts.append([])
        }
    }

    return parts
}

// Print tree
func printTree(_ entity: Entity, indent: Int, lineBreak: [UInt8]) {
    let prefix = String(repeating: "  ", count: indent)

    let ctRaw = getHeader(entity, "content-type")
    let (type, subtype, ctParams) = parseContentType(ctRaw ?? "text/plain")

    let cte = (getHeader(entity, "content-transfer-encoding") ?? "7bit").lowercased()

    if type == "multipart" && entity.parts != nil {
        print("\(prefix)multipart/\(subtype) parts=\(entity.parts!.count)")
        for part in entity.parts! {
            printTree(part, indent: indent + 1, lineBreak: lineBreak)
        }
    } else {
        // Check disposition
        let cdRaw = getHeader(entity, "content-disposition")
        var dispType = "-"
        var cdParams: [Param] = []
        if let cdv = cdRaw {
            let (dt, dp) = parseDisposition(cdv)
            dispType = dt
            cdParams = dp
        }

        // Check if text part (not attachment)
        let isText = type == "text" && dispType != "attachment"

        // Get charset
        var charset = "us-ascii"
        for p in ctParams {
            if p.name == "charset" { charset = p.value.lowercased(); break }
        }

        // Decode body
        let decodedBytes = decodeCTE(entity.bodyBytes, cte, lineBreak: lineBreak)

        if isText {
            var text = decodeCharset(decodedBytes, charset)
            text = text.replacingOccurrences(of: "\r\n", with: "\n")
            text = text.replacingOccurrences(of: "\r", with: "\n")

            let charCount = text.count
            print("\(prefix)text/\(subtype) charset=\(charset) cte=\(cte) chars=\(charCount)")
            print("\(prefix)  \(quotedString(text))")
        } else {
            let size = decodedBytes.count
            let crc = crc32(decodedBytes)

            // Get file name
            var name: String? = nil

            // RFC 2231 filename from Content-Disposition
            if !cdParams.isEmpty {
                name = extractRFC2231Param(params: cdParams, attrName: "filename")
            }
            // Regular filename from Content-Disposition
            if name == nil {
                for p in cdParams {
                    if p.name == "filename" {
                        name = decodeRFC2047(p.value)
                        break
                    }
                }
            }
            // RFC 2231 name from Content-Type
            if name == nil {
                name = extractRFC2231Param(params: ctParams, attrName: "name")
            }
            // Regular name from Content-Type
            if name == nil {
                for p in ctParams {
                    if p.name == "name" {
                        name = decodeRFC2047(p.value)
                        break
                    }
                }
            }

            let nameStr = name != nil ? quotedString(name!) : "-"

            print("\(prefix)\(type)/\(subtype) cte=\(cte) disposition=\(dispType) name=\(nameStr) size=\(size) crc32=\(String(format: "%08x", crc))")
        }
    }
}

// Main
let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }

let dir = args[1]
let fm = FileManager.default
guard let files = try? fm.contentsOfDirectory(atPath: dir) else { exit(1) }

let emlFiles = files.filter { $0.hasSuffix(".eml") }.sorted()

var firstFile = true

for fileName in emlFiles {
    let filePath = dir + "/" + fileName

    guard let data = fm.contents(atPath: filePath) else { continue }
    let bytes = [UInt8](data)

    // Detect line break
    let lineBreak: [UInt8]
    var hasCRLF = false
    for i in 0..<(bytes.count > 1 ? bytes.count - 1 : 0) {
        if bytes[i] == 0x0D && bytes[i+1] == 0x0A {
            hasCRLF = true
            break
        }
    }
    lineBreak = hasCRLF ? [0x0D, 0x0A] : [0x0A]

    let entity = parseEntity(bytes, lineBreak: lineBreak)

    if !firstFile {
        print("")
    }
    firstFile = false

    print("== \(fileName)")

    if let from = getHeader(entity, "from") {
        print("From: \(quotedString(decodeRFC2047(from)))")
    } else {
        print("From: -")
    }

    if let subject = getHeader(entity, "subject") {
        print("Subject: \(quotedString(decodeRFC2047(subject)))")
    } else {
        print("Subject: -")
    }

    printTree(entity, indent: 0, lineBreak: lineBreak)
}

import Foundation

// ============ TOKENS ============

enum TK: UInt8 {
    case intLit, strLit, ident
    case kwLet, kwFn, kwIf, kwElse, kwWhile, kwFor, kwIn, kwReturn, kwBreak, kwContinue
    case kwAnd, kwOr, kwNot, kwTrue, kwFalse, kwNil
    case plus, minus, star, slash, percent
    case eq, neq, lt, le, gt, ge
    case assign
    case lparen, rparen, lbracket, rbracket, lbrace, rbrace
    case comma, semicolon
    case eof
}

struct Token {
    var kind: TK
    var intVal: Int = 0
    var strVal: String = ""
    var line: Int = 1
}

func tokenize(_ src: [UInt8]) -> [Token] {
    var tokens: [Token] = []
    tokens.reserveCapacity(src.count / 3)
    var pos = 0
    var line = 1
    let n = src.count

    func isDigit(_ c: UInt8) -> Bool { c >= 48 && c <= 57 }
    func isAlpha(_ c: UInt8) -> Bool { (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95 }
    func isAlnum(_ c: UInt8) -> Bool { isAlpha(c) || isDigit(c) }

    while true {
        // skip whitespace and comments
        while pos < n {
            let c = src[pos]
            if c == 10 { line += 1; pos += 1 }
            else if c == 32 || c == 9 || c == 13 { pos += 1 }
            else if c == 35 { while pos < n && src[pos] != 10 { pos += 1 } }
            else { break }
        }
        if pos >= n { tokens.append(Token(kind: .eof, line: line)); break }

        let c = src[pos]
        let ln = line

        if isDigit(c) {
            var val: Int = 0
            while pos < n && isDigit(src[pos]) {
                val = val &* 10 &+ Int(src[pos] - 48)
                pos += 1
            }
            tokens.append(Token(kind: .intLit, intVal: val, line: ln))
        } else if c == 34 {
            pos += 1
            var buf: [UInt8] = []
            while pos < n && src[pos] != 34 {
                if src[pos] == 92 {
                    pos += 1
                    let e = src[pos]
                    switch e {
                    case 110: buf.append(10)
                    case 116: buf.append(9)
                    case 34:  buf.append(34)
                    case 92:  buf.append(92)
                    default:  buf.append(e)
                    }
                    pos += 1
                } else {
                    buf.append(src[pos])
                    pos += 1
                }
            }
            pos += 1
            tokens.append(Token(kind: .strLit, strVal: String(decoding: buf, as: UTF8.self), line: ln))
        } else if isAlpha(c) {
            var buf: [UInt8] = []
            while pos < n && isAlnum(src[pos]) {
                buf.append(src[pos])
                pos += 1
            }
            let str = String(decoding: buf, as: UTF8.self)
            let kind: TK
            switch str {
            case "let": kind = .kwLet
            case "fn": kind = .kwFn
            case "if": kind = .kwIf
            case "else": kind = .kwElse
            case "while": kind = .kwWhile
            case "for": kind = .kwFor
            case "in": kind = .kwIn
            case "return": kind = .kwReturn
            case "break": kind = .kwBreak
            case "continue": kind = .kwContinue
            case "and": kind = .kwAnd
            case "or": kind = .kwOr
            case "not": kind = .kwNot
            case "true": kind = .kwTrue
            case "false": kind = .kwFalse
            case "nil": kind = .kwNil
            default: kind = .ident
            }
            tokens.append(Token(kind: kind, strVal: str, line: ln))
        } else {
            let next: UInt8? = pos + 1 < n ? src[pos + 1] : nil
            if c == 61 && next == 61 { tokens.append(Token(kind: .eq, line: ln)); pos += 2; continue }
            if c == 33 && next == 61 { tokens.append(Token(kind: .neq, line: ln)); pos += 2; continue }
            if c == 60 && next == 61 { tokens.append(Token(kind: .le, line: ln)); pos += 2; continue }
            if c == 62 && next == 61 { tokens.append(Token(kind: .ge, line: ln)); pos += 2; continue }

            switch c {
            case 43: tokens.append(Token(kind: .plus, line: ln))
            case 45: tokens.append(Token(kind: .minus, line: ln))
            case 42: tokens.append(Token(kind: .star, line: ln))
            case 47: tokens.append(Token(kind: .slash, line: ln))
            case 37: tokens.append(Token(kind: .percent, line: ln))
            case 61: tokens.append(Token(kind: .assign, line: ln))
            case 60: tokens.append(Token(kind: .lt, line: ln))
            case 62: tokens.append(Token(kind: .gt, line: ln))
            case 40: tokens.append(Token(kind: .lparen, line: ln))
            case 41: tokens.append(Token(kind: .rparen, line: ln))
            case 91: tokens.append(Token(kind: .lbracket, line: ln))
            case 93: tokens.append(Token(kind: .rbracket, line: ln))
            case 123: tokens.append(Token(kind: .lbrace, line: ln))
            case 125: tokens.append(Token(kind: .rbrace, line: ln))
            case 44: tokens.append(Token(kind: .comma, line: ln))
            case 59: tokens.append(Token(kind: .semicolon, line: ln))
            default: pos += 1; continue
            }
            pos += 1
        }
    }
    return tokens
}

// ============ AST ============

indirect enum Expr {
    case intLit(Int, Int)
    case strLit(String, Int)
    case boolLit(Bool, Int)
    case nilLit(Int)
    case ident(String, Int)
    case binop(op: String, lhs: Expr, rhs: Expr, line: Int)
    case unop(op: String, operand: Expr, line: Int)
    case call(callee: Expr, args: [Expr], line: Int)
    case index(obj: Expr, idx: Expr, line: Int)
    case listLit([Expr], Int)
    case fnExpr(params: [String], body: [ASTStmt], line: Int)
}

enum ElsePart {
    case none
    case elseIf(ASTStmt)
    case elseBlock([ASTStmt])
}

indirect enum ASTStmt {
    case letDecl(name: String, value: Expr, line: Int)
    case fnDecl(name: String, params: [String], body: [ASTStmt], line: Int)
    case ifStmt(cond: Expr, then: [ASTStmt], elsePart: ElsePart, line: Int)
    case whileStmt(cond: Expr, body: [ASTStmt], line: Int)
    case forStmt(varName: String, iterable: Expr, body: [ASTStmt], line: Int)
    case returnStmt(value: Expr?, line: Int)
    case breakStmt(Int)
    case continueStmt(Int)
    case assign(name: String, value: Expr, line: Int)
    case indexAssign(obj: Expr, idx: Expr, value: Expr, line: Int)
    case exprStmt(expr: Expr, line: Int)
}

// ============ VALUES ============

enum Val {
    case int(Int)
    case bool(Bool)
    case string(String)
    case list(ListRef)
    case func(FuncRef)
    case nil_
}

final class ListRef {
    var elements: [Val]
    init(_ e: [Val] = []) { elements = e }
}

final class FuncRef {
    let params: [String]
    let body: [ASTStmt]
    let capturedScope: Scope?
    let builtinName: String
    let builtinArity: Int
    let builtinImpl: (([Val], Int) throws -> Val)?

    init(params: [String], body: [ASTStmt], scope: Scope) {
        self.params = params
        self.body = body
        self.capturedScope = scope
        self.builtinName = ""
        self.builtinArity = 0
        self.builtinImpl = nil
    }
    init(builtin name: String, arity: Int, impl: @escaping ([Val], Int) throws -> Val) {
        self.params = []
        self.body = []
        self.capturedScope = nil
        self.builtinName = name
        self.builtinArity = arity
        self.builtinImpl = impl
    }
}

// ============ SCOPE ============

final class Scope {
    var vars: [String: Val]
    let parent: Scope?
    init(parent: Scope?) { vars = [:]; self.parent = parent }

    func lookup(_ name: String) -> Val? {
        var s: Scope? = self
        while let sc = s {
            if let v = sc.vars[name] { return v }
            s = sc.parent
        }
        return nil
    }
    func assign(_ name: String, _ value: Val) -> Bool {
        var s: Scope? = self
        while let sc = s {
            if sc.vars[name] != nil { sc.vars[name] = value; return true }
            s = sc.parent
        }
        return false
    }
    func declare(_ name: String, _ value: Val) { vars[name] = value }
}

// ============ ERRORS & CONTROL FLOW ============

struct TernError: Error {
    let line: Int
    let message: String
}

enum Ctrl {
    case normal
    case breakLoop
    case continueLoop
    case returnVal(Val)
}

// ============ PARSER ============

final class Parser {
    let tokens: [Token]
    var pos = 0
    init(_ t: [Token]) { tokens = t }

    func peek() -> Token { tokens[pos] }
    func advance() -> Token { let t = tokens[pos]; pos += 1; return t }
    func expect(_ k: TK) { pos += 1 }

    func parseProgram() -> [ASTStmt] {
        var s: [ASTStmt] = []
        while peek().kind != .eof { s.append(parseStmt()) }
        return s
    }

    func parseStmt() -> ASTStmt {
        let t = peek()
        switch t.kind {
        case .kwLet:
            pos += 1
            let name = advance().strVal
            expect(.assign)
            let v = parseExpr()
            expect(.semicolon)
            return .letDecl(name: name, value: v, line: t.line)
        case .kwFn:
            pos += 1
            let name = advance().strVal
            expect(.lparen)
            let params = parseParams()
            expect(.rparen)
            let body = parseBlock()
            return .fnDecl(name: name, params: params, body: body, line: t.line)
        case .kwIf:
            return parseIfStmt()
        case .kwWhile:
            pos += 1
            let cond = parseExpr()
            let body = parseBlock()
            return .whileStmt(cond: cond, body: body, line: t.line)
        case .kwFor:
            pos += 1
            let vn = advance().strVal
            expect(.kwIn)
            let iter = parseExpr()
            let body = parseBlock()
            return .forStmt(varName: vn, iterable: iter, body: body, line: t.line)
        case .kwReturn:
            pos += 1
            if peek().kind == .semicolon { pos += 1; return .returnStmt(value: nil, line: t.line) }
            let v = parseExpr()
            expect(.semicolon)
            return .returnStmt(value: v, line: t.line)
        case .kwBreak:
            pos += 1; expect(.semicolon); return .breakStmt(t.line)
        case .kwContinue:
            pos += 1; expect(.semicolon); return .continueStmt(t.line)
        default:
            // assignment, index-assign, or expr stmt
            if t.kind == .ident && tokens[pos + 1].kind == .assign {
                let name = advance().strVal
                pos += 1 // skip =
                let v = parseExpr()
                expect(.semicolon)
                return .assign(name: name, value: v, line: t.line)
            }
            let expr = parseExpr()
            if peek().kind == .assign {
                pos += 1
                let v = parseExpr()
                expect(.semicolon)
                if case let .index(obj, idx, _) = expr {
                    return .indexAssign(obj: obj, idx: idx, value: v, line: t.line)
                }
                return .exprStmt(expr: expr, line: t.line)
            }
            expect(.semicolon)
            return .exprStmt(expr: expr, line: t.line)
        }
    }

    func parseIfStmt() -> ASTStmt {
        let t = advance()
        let cond = parseExpr()
        let then = parseBlock()
        var ep: ElsePart = .none
        if peek().kind == .kwElse {
            pos += 1
            if peek().kind == .kwIf { ep = .elseIf(parseIfStmt()) }
            else { ep = .elseBlock(parseBlock()) }
        }
        return .ifStmt(cond: cond, then: then, elsePart: ep, line: t.line)
    }

    func parseBlock() -> [ASTStmt] {
        expect(.lbrace)
        var s: [ASTStmt] = []
        while peek().kind != .rbrace { s.append(parseStmt()) }
        expect(.rbrace)
        return s
    }

    func parseParams() -> [String] {
        var p: [String] = []
        if peek().kind != .rparen {
            p.append(advance().strVal)
            while peek().kind == .comma { pos += 1; p.append(advance().strVal) }
        }
        return p
    }

    func parseExpr() -> Expr { parseOr() }

    func parseOr() -> Expr {
        var l = parseAnd()
        while peek().kind == .kwOr {
            let t = advance(); let r = parseAnd()
            l = .binop(op: "or", lhs: l, rhs: r, line: t.line)
        }
        return l
    }

    func parseAnd() -> Expr {
        var l = parseNot()
        while peek().kind == .kwAnd {
            let t = advance(); let r = parseNot()
            l = .binop(op: "and", lhs: l, rhs: r, line: t.line)
        }
        return l
    }

    func parseNot() -> Expr {
        if peek().kind == .kwNot {
            let t = advance(); let o = parseNot()
            return .unop(op: "not", operand: o, line: t.line)
        }
        return parseCmp()
    }

    func parseCmp() -> Expr {
        var l = parseAdd()
        while true {
            let t = peek()
            let op: String
            switch t.kind {
            case .eq: op = "=="
            case .neq: op = "!="
            case .lt: op = "<"
            case .le: op = "<="
            case .gt: op = ">"
            case .ge: op = ">="
            default: return l
            }
            pos += 1; let r = parseAdd()
            l = .binop(op: op, lhs: l, rhs: r, line: t.line)
        }
    }

    func parseAdd() -> Expr {
        var l = parseMul()
        while true {
            let t = peek()
            let op: String
            switch t.kind {
            case .plus: op = "+"
            case .minus: op = "-"
            default: return l
            }
            pos += 1; let r = parseMul()
            l = .binop(op: op, lhs: l, rhs: r, line: t.line)
        }
    }

    func parseMul() -> Expr {
        var l = parseUnary()
        while true {
            let t = peek()
            let op: String
            switch t.kind {
            case .star: op = "*"
            case .slash: op = "/"
            case .percent: op = "%"
            default: return l
            }
            pos += 1; let r = parseUnary()
            l = .binop(op: op, lhs: l, rhs: r, line: t.line)
        }
    }

    func parseUnary() -> Expr {
        if peek().kind == .minus {
            let t = advance(); let o = parseUnary()
            return .unop(op: "neg", operand: o, line: t.line)
        }
        return parsePostfix()
    }

    func parsePostfix() -> Expr {
        var e = parsePrimary()
        while true {
            let t = peek()
            if t.kind == .lparen {
                pos += 1
                var args: [Expr] = []
                if peek().kind != .rparen {
                    args.append(parseExpr())
                    while peek().kind == .comma { pos += 1; args.append(parseExpr()) }
                }
                expect(.rparen)
                e = .call(callee: e, args: args, line: t.line)
            } else if t.kind == .lbracket {
                pos += 1
                let idx = parseExpr()
                expect(.rbracket)
                e = .index(obj: e, idx: idx, line: t.line)
            } else { break }
        }
        return e
    }

    func parsePrimary() -> Expr {
        let t = peek()
        switch t.kind {
        case .intLit: pos += 1; return .intLit(t.intVal, t.line)
        case .strLit: pos += 1; return .strLit(t.strVal, t.line)
        case .kwTrue: pos += 1; return .boolLit(true, t.line)
        case .kwFalse: pos += 1; return .boolLit(false, t.line)
        case .kwNil: pos += 1; return .nilLit(t.line)
        case .ident: pos += 1; return .ident(t.strVal, t.line)
        case .lparen:
            pos += 1; let e = parseExpr(); expect(.rparen); return e
        case .lbracket:
            pos += 1
            var elems: [Expr] = []
            if peek().kind != .rbracket {
                elems.append(parseExpr())
                while peek().kind == .comma { pos += 1; elems.append(parseExpr()) }
            }
            expect(.rbracket)
            return .listLit(elems, t.line)
        case .kwFn:
            pos += 1; expect(.lparen)
            let params = parseParams()
            expect(.rparen)
            let body = parseBlock()
            return .fnExpr(params: params, body: body, line: t.line)
        default:
            pos += 1; return .nilLit(t.line)
        }
    }
}

// ============ TYPE NAME ============

func typeName(_ v: Val) -> String {
    switch v {
    case .int: return "int"
    case .bool: return "bool"
    case .string: return "string"
    case .list: return "list"
    case .func: return "function"
    case .nil_: return "nil"
    }
}

// ============ TRUTHINESS ============

func truthy(_ v: Val) -> Bool {
    switch v {
    case .int(let i): return i != 0
    case .bool(let b): return b
    case .string(let s): return !s.isEmpty
    case .list(let l): return !l.elements.isEmpty
    case .func: return true
    case .nil_: return false
    }
}

// ============ DISPLAY ============

func displayVal(_ v: Val, inList: Bool, seen: inout Set<ObjectIdentifier>) -> String {
    switch v {
    case .int(let i): return String(i)
    case .bool(let b): return b ? "true" : "false"
    case .nil_: return "nil"
    case .func: return "<fn>"
    case .string(let s):
        if inList { return quoteString(s) }
        return s
    case .list(let l):
        let oid = ObjectIdentifier(l)
        if seen.contains(oid) { return "[...]" }
        seen.insert(oid)
        var parts: [String] = []
        parts.reserveCapacity(l.elements.count)
        for e in l.elements {
            parts.append(displayVal(e, inList: true, seen: &seen))
        }
        seen.remove(oid)
        return "[" + parts.joined(separator: ", ") + "]"
    }
}

func quoteString(_ s: String) -> String {
    var r = "\""
    for ch in s.unicodeScalars {
        switch ch {
        case "\\": r += "\\\\"
        case "\"": r += "\\\""
        case "\n": r += "\\n"
        case "\t": r += "\\t"
        default: r.unicodeScalars.append(ch)
        }
    }
    r += "\""
    return r
}

// ============ VALUE EQUALITY ============

func valEqual(_ a: Val, _ b: Val) -> Bool {
    switch (a, b) {
    case (.int(let x), .int(let y)): return x == y
    case (.bool(let x), .bool(let y)): return x == y
    case (.string(let x), .string(let y)): return x == y
    case (.nil_, .nil_): return true
    case (.func(let x), .func(let y)): return x === y
    case (.list(let x), .list(let y)):
        if x === y { return true }
        if x.elements.count != y.elements.count { return false }
        for i in 0..<x.elements.count {
            if !valEqual(x.elements[i], y.elements[i]) { return false }
        }
        return true
    default: return false
    }
}

// ============ BUILTINS ============

func makeBuiltins() -> Scope {
    let s = Scope(parent: nil)

    s.declare("print", .func(FuncRef(builtin: "print", arity: -1) { args, ln in
        var parts: [String] = []
        parts.reserveCapacity(args.count)
        for a in args {
            var seen = Set<ObjectIdentifier>()
            parts.append(displayVal(a, inList: false, seen: &seen))
        }
        print(parts.joined(separator: " "))
        return .nil_
    }))

    s.declare("str", .func(FuncRef(builtin: "str", arity: 1) { args, ln in
        var seen = Set<ObjectIdentifier>()
        return .string(displayVal(args[0], inList: false, seen: &seen))
    }))

    s.declare("type", .func(FuncRef(builtin: "type", arity: 1) { args, _ in
        .string(typeName(args[0]))
    }))

    s.declare("len", .func(FuncRef(builtin: "len", arity: 1) { args, ln in
        switch args[0] {
        case .string(let s): return .int(s.count)
        case .list(let l): return .int(l.elements.count)
        default: throw TernError(line: ln, message: "bad argument to len")
        }
    }))

    s.declare("push", .func(FuncRef(builtin: "push", arity: 2) { args, ln in
        switch args[0] {
        case .list(let l): l.elements.append(args[1]); return .nil_
        default: throw TernError(line: ln, message: "bad argument to push")
        }
    }))

    s.declare("pop", .func(FuncRef(builtin: "pop", arity: 1) { args, ln in
        switch args[0] {
        case .list(let l):
            if l.elements.isEmpty { throw TernError(line: ln, message: "bad argument to pop") }
            return l.elements.removeLast()
        default: throw TernError(line: ln, message: "bad argument to pop")
        }
    }))

    s.declare("range", .func(FuncRef(builtin: "range", arity: 2) { args, ln in
        guard case .int(let a) = args[0], case .int(let b) = args[1] else {
            throw TernError(line: ln, message: "bad argument to range")
        }
        if b <= a { return .list(ListRef()) }
        var elems: [Val] = []
        elems.reserveCapacity(b - a)
        var i = a
        while i < b { elems.append(.int(i)); i += 1 }
        return .list(ListRef(elems))
    }))

    s.declare("slice", .func(FuncRef(builtin: "slice", arity: 3) { args, ln in
        guard case .int(let a) = args[1], case .int(let b) = args[2] else {
            throw TernError(line: ln, message: "bad argument to slice")
        }
        switch args[0] {
        case .string(let s):
            let chars = Array(s)
            if a < 0 || b > chars.count || a > b { throw TernError(line: ln, message: "bad argument to slice") }
            return .string(String(chars[a..<b]))
        case .list(let l):
            if a < 0 || b > l.elements.count || a > b { throw TernError(line: ln, message: "bad argument to slice") }
            return .list(ListRef(Array(l.elements[a..<b])))
        default:
            throw TernError(line: ln, message: "bad argument to slice")
        }
    }))

    return s
}

// ============ INTERPRETER ============

func evalExpr(_ e: Expr, _ scope: Scope) throws -> Val {
    switch e {
    case .intLit(let v, _): return .int(v)
    case .strLit(let s, _): return .string(s)
    case .boolLit(let b, _): return .bool(b)
    case .nilLit: return .nil_
    case .ident(let name, let ln):
        if let v = scope.lookup(name) { return v }
        throw TernError(line: ln, message: "undefined variable \(name)")

    case .binop(let op, let lhs, let rhs, let ln):
        if op == "and" {
            let lv = try evalExpr(lhs, scope)
            if !truthy(lv) { return lv }
            return try evalExpr(rhs, scope)
        }
        if op == "or" {
            let lv = try evalExpr(lhs, scope)
            if truthy(lv) { return lv }
            return try evalExpr(rhs, scope)
        }
        if op == "==" {
            let lv = try evalExpr(lhs, scope)
            let rv = try evalExpr(rhs, scope)
            return .bool(valEqual(lv, rv))
        }
        if op == "!=" {
            let lv = try evalExpr(lhs, scope)
            let rv = try evalExpr(rhs, scope)
            return .bool(!valEqual(lv, rv))
        }
        // arithmetic and comparison operators
        let lv = try evalExpr(lhs, scope)
        let rv = try evalExpr(rhs, scope)
        return try applyBinop(op, lv, rv, ln)

    case .unop(let op, let operand, let ln):
        if op == "not" {
            let v = try evalExpr(operand, scope)
            return .bool(!truthy(v))
        }
        // neg
        let v = try evalExpr(operand, scope)
        guard case .int(let i) = v else {
            throw TernError(line: ln, message: "cannot apply - to \(typeName(v))")
        }
        if i == Int.min { throw TernError(line: ln, message: "integer overflow") }
        return .int(-i)

    case .call(let callee, let argExprs, let ln):
        let fnVal = try evalExpr(callee, scope)
        var args: [Val] = []
        args.reserveCapacity(argExprs.count)
        for ae in argExprs { args.append(try evalExpr(ae, scope)) }
        guard case .func(let f) = fnVal else {
            throw TernError(line: ln, message: "cannot call \(typeName(fnVal))")
        }
        if f.builtinImpl != nil {
            // builtin
            if f.builtinArity >= 0 && args.count != f.builtinArity {
                throw TernError(line: ln, message: "expected \(f.builtinArity) arguments, got \(args.count)")
            }
            return try f.builtinImpl!(args, ln)
        } else {
            // user function
            if args.count != f.params.count {
                throw TernError(line: ln, message: "expected \(f.params.count) arguments, got \(args.count)")
            }
            let callScope = Scope(parent: f.capturedScope!)
            for i in 0..<f.params.count {
                callScope.declare(f.params[i], args[i])
            }
            let result = try execBlock(f.body, callScope)
            if case .returnVal(let v) = result { return v }
            return .nil_
        }

    case .index(let obj, let idx, let ln):
        let ov = try evalExpr(obj, scope)
        let iv = try evalExpr(idx, scope)
        return try indexRead(ov, iv, ln)

    case .listLit(let elems, _):
        var vals: [Val] = []
        vals.reserveCapacity(elems.count)
        for el in elems { vals.append(try evalExpr(el, scope)) }
        return .list(ListRef(vals))

    case .fnExpr(let params, let body, _):
        return .func(FuncRef(params: params, body: body, scope: scope))
    }
}

func indexRead(_ obj: Val, _ idx: Val, _ ln: Int) throws -> Val {
    switch obj {
    case .list(let l):
        guard case .int(let i) = idx else {
            throw TernError(line: ln, message: "cannot index list with \(typeName(idx))")
        }
        if i < 0 || i >= l.elements.count {
            throw TernError(line: ln, message: "index \(i) out of range for length \(l.elements.count)")
        }
        return l.elements[i]
    case .string(let s):
        guard case .int(let i) = idx else {
            throw TernError(line: ln, message: "cannot index string with \(typeName(idx))")
        }
        let chars = Array(s)
        if i < 0 || i >= chars.count {
            throw TernError(line: ln, message: "index \(i) out of range for length \(chars.count)")
        }
        return .string(String(chars[i]))
    default:
        throw TernError(line: ln, message: "cannot index \(typeName(obj)) with \(typeName(idx))")
    }
}

func applyBinop(_ op: String, _ lv: Val, _ rv: Val, _ ln: Int) throws -> Val {
    switch op {
    case "+":
        if case .int(let a) = lv, case .int(let b) = rv {
            let (r, ov) = a.addingReportingOverflow(b)
            if ov { throw TernError(line: ln, message: "integer overflow") }
            return .int(r)
        }
        if case .string(let a) = lv, case .string(let b) = rv { return .string(a + b) }
        if case .list(let a) = lv, case .list(let b) = rv {
            var elems = a.elements
            elems.append(contentsOf: b.elements)
            return .list(ListRef(elems))
        }
        throw TernError(line: ln, message: "cannot apply + to \(typeName(lv)) and \(typeName(rv))")
    case "-":
        guard case .int(let a) = lv, case .int(let b) = rv else {
            throw TernError(line: ln, message: "cannot apply - to \(typeName(lv)) and \(typeName(rv))")
        }
        let (r, ov) = a.subtractingReportingOverflow(b)
        if ov { throw TernError(line: ln, message: "integer overflow") }
        return .int(r)
    case "*":
        guard case .int(let a) = lv, case .int(let b) = rv else {
            throw TernError(line: ln, message: "cannot apply * to \(typeName(lv)) and \(typeName(rv))")
        }
        let (r, ov) = a.multipliedReportingOverflow(by: b)
        if ov { throw TernError(line: ln, message: "integer overflow") }
        return .int(r)
    case "/":
        guard case .int(let a) = lv, case .int(let b) = rv else {
            throw TernError(line: ln, message: "cannot apply / to \(typeName(lv)) and \(typeName(rv))")
        }
        if b == 0 { throw TernError(line: ln, message: "division by zero") }
        if a == Int.min && b == -1 { throw TernError(line: ln, message: "integer overflow") }
        return .int(a / b) // Swift truncates toward zero
    case "%":
        guard case .int(let a) = lv, case .int(let b) = rv else {
            throw TernError(line: ln, message: "cannot apply % to \(typeName(lv)) and \(typeName(rv))")
        }
        if b == 0 { throw TernError(line: ln, message: "division by zero") }
        if b == -1 { return .int(0) }
        return .int(a % b) // Swift % gives sign of dividend
    case "<":
        if case .int(let a) = lv, case .int(let b) = rv { return .bool(a < b) }
        if case .string(let a) = lv, case .string(let b) = rv { return .bool(a < b) }
        throw TernError(line: ln, message: "cannot apply < to \(typeName(lv)) and \(typeName(rv))")
    case "<=":
        if case .int(let a) = lv, case .int(let b) = rv { return .bool(a <= b) }
        if case .string(let a) = lv, case .string(let b) = rv { return .bool(a <= b) }
        throw TernError(line: ln, message: "cannot apply <= to \(typeName(lv)) and \(typeName(rv))")
    case ">":
        if case .int(let a) = lv, case .int(let b) = rv { return .bool(a > b) }
        if case .string(let a) = lv, case .string(let b) = rv { return .bool(a > b) }
        throw TernError(line: ln, message: "cannot apply > to \(typeName(lv)) and \(typeName(rv))")
    case ">=":
        if case .int(let a) = lv, case .int(let b) = rv { return .bool(a >= b) }
        if case .string(let a) = lv, case .string(let b) = rv { return .bool(a >= b) }
        throw TernError(line: ln, message: "cannot apply >= to \(typeName(lv)) and \(typeName(rv))")
    default:
        throw TernError(line: ln, message: "unknown operator \(op)")
    }
}

func execBlock(_ stmts: [ASTStmt], _ scope: Scope) throws -> Ctrl {
    for s in stmts {
        let c = try execStmt(s, scope)
        switch c {
        case .normal: continue
        default: return c
        }
    }
    return .normal
}

func execStmt(_ s: ASTStmt, _ scope: Scope) throws -> Ctrl {
    switch s {
    case .letDecl(let name, let value, _):
        let v = try evalExpr(value, scope)
        scope.declare(name, v)
        return .normal

    case .fnDecl(let name, let params, let body, _):
        let f = FuncRef(params: params, body: body, scope: scope)
        scope.declare(name, .func(f))
        return .normal

    case .ifStmt(let cond, let then, let elsePart, _):
        let cv = try evalExpr(cond, scope)
        if truthy(cv) {
            let inner = Scope(parent: scope)
            return try execBlock(then, inner)
        } else {
            switch elsePart {
            case .none: return .normal
            case .elseIf(let stmt): return try execStmt(stmt, scope)
            case .elseBlock(let stmts):
                let inner = Scope(parent: scope)
                return try execBlock(stmts, inner)
            }
        }

    case .whileStmt(let cond, let body, _):
        while true {
            let cv = try evalExpr(cond, scope)
            if !truthy(cv) { break }
            let inner = Scope(parent: scope)
            let c = try execBlock(body, inner)
            switch c {
            case .breakLoop: break
            case .continueLoop: continue
            case .returnVal(let v): return .returnVal(v)
            case .normal: continue
            }
        }
        return .normal

    case .forStmt(let varName, let iterable, let body, let ln):
        let iterVal = try evalExpr(iterable, scope)
        guard case .list(let lst) = iterVal else {
            throw TernError(line: ln, message: "cannot iterate \(typeName(iterVal))")
        }
        var i = 0
        while i < lst.elements.count {
            let inner = Scope(parent: scope)
            inner.declare(varName, lst.elements[i])
            let c = try execBlock(body, inner)
            switch c {
            case .breakLoop: break
            case .continueLoop: i += 1; continue
            case .returnVal(let v): return .returnVal(v)
            case .normal: i += 1; continue
            }
            break // breakLoop exits while
        }
        return .normal

    case .returnStmt(let value, _):
        if let v = value { return .returnVal(try evalExpr(v, scope)) }
        return .returnVal(.nil_)

    case .breakStmt: return .breakLoop
    case .continueStmt: return .continueLoop

    case .assign(let name, let value, let ln):
        let v = try evalExpr(value, scope)
        if !scope.assign(name, v) {
            throw TernError(line: ln, message: "undefined variable \(name)")
        }
        return .normal

    case .indexAssign(let obj, let idx, let value, let ln):
        let ov = try evalExpr(obj, scope)
        let iv = try evalExpr(idx, scope)
        let vv = try evalExpr(value, scope)
        guard case .list(let l) = ov else {
            throw TernError(line: ln, message: "cannot assign into \(typeName(ov))")
        }
        guard case .int(let i) = iv else {
            throw TernError(line: ln, message: "cannot index list with \(typeName(iv))")
        }
        if i < 0 || i >= l.elements.count {
            throw TernError(line: ln, message: "index \(i) out of range for length \(l.elements.count)")
        }
        l.elements[i] = vv
        return .normal

    case .exprStmt(let expr, _):
        _ = try evalExpr(expr, scope)
        return .normal
    }
}

// ============ MAIN ============

func main() {
    let args = CommandLine.arguments
    guard args.count >= 2 else { exit(0) }
    let dir = args[1]
    let path = dir + "/program.tern"
    guard let data = FileManager.default.contents(atPath: path) else { exit(0) }
    let src = [UInt8](data)

    let tokens = tokenize(src)
    let parser = Parser(tokens)
    let program = parser.parseProgram()

    let builtins = makeBuiltins()
    let globalScope = Scope(parent: builtins)

    do {
        _ = try execBlock(program, globalScope)
    } catch let e as TernError {
        print("error at line \(e.line): \(e.message)")
    } catch {
        // shouldn't happen
    }
    fflush(stdout)
    exit(0)
}

main()

import Foundation

// ============ TOKENS ============

enum TK: UInt8 {
    case intLit, strLit, ident
    case kwLet, kwFn, kwIf, kwElse, kwWhile, kwFor, kwIn, kwReturn, kwBreak, kwContinue
    case kwAnd, kwOr, kwNot, kwTrue, kwFalse, kwNil
    case plus, minus, star, slash, percent
    case eq, neq, lt, le, gt, ge
    case assign
    case lparen, rparen, lbracket, rbracket, lbrace, rbrace
    case comma, semicolon
    case eof
}

struct Token {
    var kind: TK
    var intVal: Int = 0
    var strVal: String = ""
    var line: Int = 1
}

func tokenize(_ src: [UInt8]) -> [Token] {
    var tokens: [Token] = []
    tokens.reserveCapacity(src.count / 3)
    var pos = 0
    var line = 1
    let n = src.count

    func isDigit(_ c: UInt8) -> Bool { c >= 48 && c <= 57 }
    func isAlpha(_ c: UInt8) -> Bool { (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95 }
    func isAlnum(_ c: UInt8) -> Bool { isAlpha(c) || isDigit(c) }

    while true {
        // skip whitespace and comments
        while pos < n {
            let c = src[pos]
            if c == 10 { line += 1; pos += 1 }
            else if c == 32 || c == 9 || c == 13 { pos += 1 }
            else if c == 35 { while pos < n && src[pos] != 10 { pos += 1 } }
            else { break }
        }
        if pos >= n { tokens.append(Token(kind: .eof, line: line)); break }

        let c = src[pos]
        let ln = line

        if isDigit(c) {
            var val: Int = 0
            while pos < n && isDigit(src[pos]) {
                val = val &* 10 &+ Int(src[pos] - 48)
                pos += 1
            }
            tokens.append(Token(kind: .intLit, intVal: val, line: ln))
        } else if c == 34 {
            pos += 1
            var buf: [UInt8] = []
            while pos < n && src[pos] != 34 {
                if src[pos] == 92 {
                    pos += 1
                    let e = src[pos]
                    switch e {
                    case 110: buf.append(10)
                    case 116: buf.append(9)
                    case 34:  buf.append(34)
                    case 92:  buf.append(92)
                    default:  buf.append(e)
                    }
                    pos += 1
                } else {
                    buf.append(src[pos])
                    pos += 1
                }
            }
            pos += 1
            tokens.append(Token(kind: .strLit, strVal: String(decoding: buf, as: UTF8.self), line: ln))
        } else if isAlpha(c) {
            var buf: [UInt8] = []
            while pos < n && isAlnum(src[pos]) {
                buf.append(src[pos])
                pos += 1
            }
            let str = String(decoding: buf, as: UTF8.self)
            let kind: TK
            switch str {
            case "let": kind = .kwLet
            case "fn": kind = .kwFn
            case "if": kind = .kwIf
            case "else": kind = .kwElse
            case "while": kind = .kwWhile
            case "for": kind = .kwFor
            case "in": kind = .kwIn
            case "return": kind = .kwReturn
            case "break": kind = .kwBreak
            case "continue": kind = .kwContinue
            case "and": kind = .kwAnd
            case "or": kind = .kwOr
            case "not": kind = .kwNot
            case "true": kind = .kwTrue
            case "false": kind = .kwFalse
            case "nil": kind = .kwNil
            default: kind = .ident
            }
            tokens.append(Token(kind: kind, strVal: str, line: ln))
        } else {
            let next: UInt8? = pos + 1 < n ? src[pos + 1] : nil
            if c == 61 && next == 61 { tokens.append(Token(kind: .eq, line: ln)); pos += 2; continue }
            if c == 33 && next == 61 { tokens.append(Token(kind: .neq, line: ln)); pos += 2; continue }
            if c == 60 && next == 61 { tokens.append(Token(kind: .le, line: ln)); pos += 2; continue }
            if c == 62 && next == 61 { tokens.append(Token(kind: .ge, line: ln)); pos += 2; continue }

            switch c {
            case 43: tokens.append(Token(kind: .plus, line: ln))
            case 45: tokens.append(Token(kind: .minus, line: ln))
            case 42: tokens.append(Token(kind: .star, line: ln))
            case 47: tokens.append(Token(kind: .slash, line: ln))
            case 37: tokens.append(Token(kind: .percent, line: ln))
            case 61: tokens.append(Token(kind: .assign, line: ln))
            case 60: tokens.append(Token(kind: .lt, line: ln))
            case 62: tokens.append(Token(kind: .gt, line: ln))
            case 40: tokens.append(Token(kind: .lparen, line: ln))
            case 41: tokens.append(Token(kind: .rparen, line: ln))
            case 91: tokens.append(Token(kind: .lbracket, line: ln))
            case 93: tokens.append(Token(kind: .rbracket, line: ln))
            case 123: tokens.append(Token(kind: .lbrace, line: ln))
            case 125: tokens.append(Token(kind: .rbrace, line: ln))
            case 44: tokens.append(Token(kind: .comma, line: ln))
            case 59: tokens.append(Token(kind: .semicolon, line: ln))
            default: pos += 1; continue
            }
            pos += 1
        }
    }
    return tokens
}

// ============ AST ============

indirect enum Expr {
    case intLit(Int, Int)
    case strLit(String, Int)
    case boolLit(Bool, Int)
    case nilLit(Int)
    case ident(String, Int)
    case binop(op: String, lhs: Expr, rhs: Expr, line: Int)
    case unop(op: String, operand: Expr, line: Int)
    case call(callee: Expr, args: [Expr], line: Int)
    case index(obj: Expr, idx: Expr, line: Int)
    case listLit([Expr], Int)
    case fnExpr(params: [String], body: [ASTStmt], line: Int)
}

enum ElsePart {
    case none
    case elseIf(ASTStmt)
    case elseBlock([ASTStmt])
}

indirect enum ASTStmt {
    case letDecl(name: String, value: Expr, line: Int)
    case fnDecl(name: String, params: [String], body: [ASTStmt], line: Int)
    case ifStmt(cond: Expr, then: [ASTStmt], elsePart: ElsePart, line: Int)
    case whileStmt(cond: Expr, body: [ASTStmt], line: Int)
    case forStmt(varName: String, iterable: Expr, body: [ASTStmt], line: Int)
    case returnStmt(value: Expr?, line: Int)
    case breakStmt(Int)
    case continueStmt(Int)
    case assign(name: String, value: Expr, line: Int)
    case indexAssign(obj: Expr, idx: Expr, value: Expr, line: Int)
    case exprStmt(expr: Expr, line: Int)
}

// ============ VALUES ============

enum Val {
    case int(Int)
    case bool(Bool)
    case string(String)
    case list(ListRef)
    case fn(FuncRef)
    case nil_
}

final class ListRef {
    var elements: [Val]
    init(_ e: [Val] = []) { elements = e }
}

final class FuncRef {
    let params: [String]
    let body: [ASTStmt]
    let capturedScope: Scope?
    let builtinName: String
    let builtinArity: Int
    let builtinImpl: (([Val], Int) throws -> Val)?

    init(params: [String], body: [ASTStmt], scope: Scope) {
        self.params = params
        self.body = body
        self.capturedScope = scope
        self.builtinName = ""
        self.builtinArity = 0
        self.builtinImpl = nil
    }
    init(builtin name: String, arity: Int, impl: @escaping ([Val], Int) throws -> Val) {
        self.params = []
        self.body = []
        self.capturedScope = nil
        self.builtinName = name
        self.builtinArity = arity
        self.builtinImpl = impl
    }
}

// ============ SCOPE ============

final class Scope {
    var vars: [String: Val]
    let parent: Scope?
    init(parent: Scope?) { vars = [:]; self.parent = parent }

    func lookup(_ name: String) -> Val? {
        var s: Scope? = self
        while let sc = s {
            if let v = sc.vars[name] { return v }
            s = sc.parent
        }
        return nil
    }
    func assign(_ name: String, _ value: Val) -> Bool {
        var s: Scope? = self
        while let sc = s {
            if sc.vars[name] != nil { sc.vars[name] = value; return true }
            s = sc.parent
        }
        return false
    }
    func declare(_ name: String, _ value: Val) { vars[name] = value }
}

// ============ ERRORS & CONTROL FLOW ============

struct TernError: Error {
    let line: Int
    let message: String
}

enum Ctrl {
    case normal
    case breakLoop
    case continueLoop
    case returnVal(Val)
}

// ============ PARSER ============

final class Parser {
    let tokens: [Token]
    var pos = 0
    init(_ t: [Token]) { tokens = t }

    func peek() -> Token { tokens[pos] }
    func advance() -> Token { let t = tokens[pos]; pos += 1; return t }
    func expect(_ k: TK) { pos += 1 }

    func parseProgram() -> [ASTStmt] {
        var s: [ASTStmt] = []
        while peek().kind != .eof { s.append(parseStmt()) }
        return s
    }

    func parseStmt() -> ASTStmt {
        let t = peek()
        switch t.kind {
        case .kwLet:
            pos += 1
            let name = advance().strVal
            expect(.assign)
            let v = parseExpr()
            expect(.semicolon)
            return .letDecl(name: name, value: v, line: t.line)
        case .kwFn:
            pos += 1
            let name = advance().strVal
            expect(.lparen)
            let params = parseParams()
            expect(.rparen)
            let body = parseBlock()
            return .fnDecl(name: name, params: params, body: body, line: t.line)
        case .kwIf:
            return parseIfStmt()
        case .kwWhile:
            pos += 1
            let cond = parseExpr()
            let body = parseBlock()
            return .whileStmt(cond: cond, body: body, line: t.line)
        case .kwFor:
            pos += 1
            let vn = advance().strVal
            expect(.kwIn)
            let iter = parseExpr()
            let body = parseBlock()
            return .forStmt(varName: vn, iterable: iter, body: body, line: t.line)
        case .kwReturn:
            pos += 1
            if peek().kind == .semicolon { pos += 1; return .returnStmt(value: nil, line: t.line) }
            let v = parseExpr()
            expect(.semicolon)
            return .returnStmt(value: v, line: t.line)
        case .kwBreak:
            pos += 1; expect(.semicolon); return .breakStmt(t.line)
        case .kwContinue:
            pos += 1; expect(.semicolon); return .continueStmt(t.line)
        default:
            // assignment, index-assign, or expr stmt
            if t.kind == .ident && tokens[pos + 1].kind == .assign {
                let name = advance().strVal
                pos += 1 // skip =
                let v = parseExpr()
                expect(.semicolon)
                return .assign(name: name, value: v, line: t.line)
            }
            let expr = parseExpr()
            if peek().kind == .assign {
                pos += 1
                let v = parseExpr()
                expect(.semicolon)
                if case let .index(obj, idx, _) = expr {
                    return .indexAssign(obj: obj, idx: idx, value: v, line: t.line)
                }
                return .exprStmt(expr: expr, line: t.line)
            }
            expect(.semicolon)
            return .exprStmt(expr: expr, line: t.line)
        }
    }

    func parseIfStmt() -> ASTStmt {
        let t = advance()
        let cond = parseExpr()
        let then = parseBlock()
        var ep: ElsePart = .none
        if peek().kind == .kwElse {
            pos += 1
            if peek().kind == .kwIf { ep = .elseIf(parseIfStmt()) }
            else { ep = .elseBlock(parseBlock()) }
        }
        return .ifStmt(cond: cond, then: then, elsePart: ep, line: t.line)
    }

    func parseBlock() -> [ASTStmt] {
        expect(.lbrace)
        var s: [ASTStmt] = []
        while peek().kind != .rbrace { s.append(parseStmt()) }
        expect(.rbrace)
        return s
    }

    func parseParams() -> [String] {
        var p: [String] = []
        if peek().kind != .rparen {
            p.append(advance().strVal)
            while peek().kind == .comma { pos += 1; p.append(advance().strVal) }
        }
        return p
    }

    func parseExpr() -> Expr { parseOr() }

    func parseOr() -> Expr {
        var l = parseAnd()
        while peek().kind == .kwOr {
            let t = advance(); let r = parseAnd()
            l = .binop(op: "or", lhs: l, rhs: r, line: t.line)
        }
        return l
    }

    func parseAnd() -> Expr {
        var l = parseNot()
        while peek().kind == .kwAnd {
            let t = advance(); let r = parseNot()
            l = .binop(op: "and", lhs: l, rhs: r, line: t.line)
        }
        return l
    }

    func parseNot() -> Expr {
        if peek().kind == .kwNot {
            let t = advance(); let o = parseNot()
            return .unop(op: "not", operand: o, line: t.line)
        }
        return parseCmp()
    }

    func parseCmp() -> Expr {
        var l = parseAdd()
        while true {
            let t = peek()
            let op: String
            switch t.kind {
            case .eq: op = "=="
            case .neq: op = "!="
            case .lt: op = "<"
            case .le: op = "<="
            case .gt: op = ">"
            case .ge: op = ">="
            default: return l
            }
            pos += 1; let r = parseAdd()
            l = .binop(op: op, lhs: l, rhs: r, line: t.line)
        }
    }

    func parseAdd() -> Expr {
        var l = parseMul()
        while true {
            let t = peek()
            let op: String
            switch t.kind {
            case .plus: op = "+"
            case .minus: op = "-"
            default: return l
            }
            pos += 1; let r = parseMul()
            l = .binop(op: op, lhs: l, rhs: r, line: t.line)
        }
    }

    func parseMul() -> Expr {
        var l = parseUnary()
        while true {
            let t = peek()
            let op: String
            switch t.kind {
            case .star: op = "*"
            case .slash: op = "/"
            case .percent: op = "%"
            default: return l
            }
            pos += 1; let r = parseUnary()
            l = .binop(op: op, lhs: l, rhs: r, line: t.line)
        }
    }

    func parseUnary() -> Expr {
        if peek().kind == .minus {
            let t = advance(); let o = parseUnary()
            return .unop(op: "neg", operand: o, line: t.line)
        }
        return parsePostfix()
    }

    func parsePostfix() -> Expr {
        var e = parsePrimary()
        while true {
            let t = peek()
            if t.kind == .lparen {
                pos += 1
                var args: [Expr] = []
                if peek().kind != .rparen {
                    args.append(parseExpr())
                    while peek().kind == .comma { pos += 1; args.append(parseExpr()) }
                }
                expect(.rparen)
                e = .call(callee: e, args: args, line: t.line)
            } else if t.kind == .lbracket {
                pos += 1
                let idx = parseExpr()
                expect(.rbracket)
                e = .index(obj: e, idx: idx, line: t.line)
            } else { break }
        }
        return e
    }

    func parsePrimary() -> Expr {
        let t = peek()
        switch t.kind {
        case .intLit: pos += 1; return .intLit(t.intVal, t.line)
        case .strLit: pos += 1; return .strLit(t.strVal, t.line)
        case .kwTrue: pos += 1; return .boolLit(true, t.line)
        case .kwFalse: pos += 1; return .boolLit(false, t.line)
        case .kwNil: pos += 1; return .nilLit(t.line)
        case .ident: pos += 1; return .ident(t.strVal, t.line)
        case .lparen:
            pos += 1; let e = parseExpr(); expect(.rparen); return e
        case .lbracket:
            pos += 1
            var elems: [Expr] = []
            if peek().kind != .rbracket {
                elems.append(parseExpr())
                while peek().kind == .comma { pos += 1; elems.append(parseExpr()) }
            }
            expect(.rbracket)
            return .listLit(elems, t.line)
        case .kwFn:
            pos += 1; expect(.lparen)
            let params = parseParams()
            expect(.rparen)
            let body = parseBlock()
            return .fnExpr(params: params, body: body, line: t.line)
        default:
            pos += 1; return .nilLit(t.line)
        }
    }
}

// ============ TYPE NAME ============

func typeName(_ v: Val) -> String {
    switch v {
    case .int: return "int"
    case .bool: return "bool"
    case .string: return "string"
    case .list: return "list"
    case .fn: return "function"
    case .nil_: return "nil"
    }
}

// ============ TRUTHINESS ============

func truthy(_ v: Val) -> Bool {
    switch v {
    case .int(let i): return i != 0
    case .bool(let b): return b
    case .string(let s): return !s.isEmpty
    case .list(let l): return !l.elements.isEmpty
    case .fn: return true
    case .nil_: return false
    }
}

// ============ DISPLAY ============

func displayVal(_ v: Val, inList: Bool, seen: inout Set<ObjectIdentifier>) -> String {
    switch v {
    case .int(let i): return String(i)
    case .bool(let b): return b ? "true" : "false"
    case .nil_: return "nil"
    case .fn: return "<fn>"
    case .string(let s):
        if inList { return quoteString(s) }
        return s
    case .list(let l):
        let oid = ObjectIdentifier(l)
        if seen.contains(oid) { return "[...]" }
        seen.insert(oid)
        var parts: [String] = []
        parts.reserveCapacity(l.elements.count)
        for e in l.elements {
            parts.append(displayVal(e, inList: true, seen: &seen))
        }
        seen.remove(oid)
        return "[" + parts.joined(separator: ", ") + "]"
    }
}

func quoteString(_ s: String) -> String {
    var r = "\""
    for ch in s.unicodeScalars {
        switch ch {
        case "\\": r += "\\\\"
        case "\"": r += "\\\""
        case "\n": r += "\\n"
        case "\t": r += "\\t"
        default: r.unicodeScalars.append(ch)
        }
    }
    r += "\""
    return r
}

// ============ VALUE EQUALITY ============

func valEqual(_ a: Val, _ b: Val) -> Bool {
    switch (a, b) {
    case (.int(let x), .int(let y)): return x == y
    case (.bool(let x), .bool(let y)): return x == y
    case (.string(let x), .string(let y)): return x == y
    case (.nil_, .nil_): return true
    case (.fn(let x), .fn(let y)): return x === y
    case (.list(let x), .list(let y)):
        if x === y { return true }
        if x.elements.count != y.elements.count { return false }
        for i in 0..<x.elements.count {
            if !valEqual(x.elements[i], y.elements[i]) { return false }
        }
        return true
    default: return false
    }
}

// ============ BUILTINS ============

func makeBuiltins() -> Scope {
    let s = Scope(parent: nil)

    s.declare("print", .fn(FuncRef(builtin: "print", arity: -1) { args, ln in
        var parts: [String] = []
        parts.reserveCapacity(args.count)
        for a in args {
            var seen = Set<ObjectIdentifier>()
            parts.append(displayVal(a, inList: false, seen: &seen))
        }
        print(parts.joined(separator: " "))
        return .nil_
    }))

    s.declare("str", .fn(FuncRef(builtin: "str", arity: 1) { args, ln in
        var seen = Set<ObjectIdentifier>()
        return .string(displayVal(args[0], inList: false, seen: &seen))
    }))

    s.declare("type", .fn(FuncRef(builtin: "type", arity: 1) { args, _ in
        .string(typeName(args[0]))
    }))

    s.declare("len", .fn(FuncRef(builtin: "len", arity: 1) { args, ln in
        switch args[0] {
        case .string(let s): return .int(s.utf8.count)
        case .list(let l): return .int(l.elements.count)
        default: throw TernError(line: ln, message: "bad argument to len")
        }
    }))

    s.declare("push", .fn(FuncRef(builtin: "push", arity: 2) { args, ln in
        switch args[0] {
        case .list(let l): l.elements.append(args[1]); return .nil_
        default: throw TernError(line: ln, message: "bad argument to push")
        }
    }))

    s.declare("pop", .fn(FuncRef(builtin: "pop", arity: 1) { args, ln in
        switch args[0] {
        case .list(let l):
            if l.elements.isEmpty { throw TernError(line: ln, message: "bad argument to pop") }
            return l.elements.removeLast()
        default: throw TernError(line: ln, message: "bad argument to pop")
        }
    }))

    s.declare("range", .fn(FuncRef(builtin: "range", arity: 2) { args, ln in
        guard case .int(let a) = args[0], case .int(let b) = args[1] else {
            throw TernError(line: ln, message: "bad argument to range")
        }
        if b <= a { return .list(ListRef()) }
        var elems: [Val] = []
        elems.reserveCapacity(b - a)
        var i = a
        while i < b { elems.append(.int(i)); i += 1 }
        return .list(ListRef(elems))
    }))

    s.declare("slice", .fn(FuncRef(builtin: "slice", arity: 3) { args, ln in
        guard case .int(let a) = args[1], case .int(let b) = args[2] else {
            throw TernError(line: ln, message: "bad argument to slice")
        }
        switch args[0] {
        case .string(let s):
            let chars = Array(s.unicodeScalars)
            if a < 0 || b > chars.count || a > b { throw TernError(line: ln, message: "bad argument to slice") }
            return .string(String(String.UnicodeScalarView(chars[a..<b])))
        case .list(let l):
            if a < 0 || b > l.elements.count || a > b { throw TernError(line: ln, message: "bad argument to slice") }
            return .list(ListRef(Array(l.elements[a..<b])))
        default:
            throw TernError(line: ln, message: "bad argument to slice")
        }
    }))

    return s
}

// ============ INTERPRETER ============

func evalExpr(_ e: Expr, _ scope: Scope) throws -> Val {
    switch e {
    case .intLit(let v, _): return .int(v)
    case .strLit(let s, _): return .string(s)
    case .boolLit(let b, _): return .bool(b)
    case .nilLit: return .nil_
    case .ident(let name, let ln):
        if let v = scope.lookup(name) { return v }
        throw TernError(line: ln, message: "undefined variable \(name)")

    case .binop(let op, let lhs, let rhs, let ln):
        if op == "and" {
            let lv = try evalExpr(lhs, scope)
            if !truthy(lv) { return lv }
            return try evalExpr(rhs, scope)
        }
        if op == "or" {
            let lv = try evalExpr(lhs, scope)
            if truthy(lv) { return lv }
            return try evalExpr(rhs, scope)
        }
        if op == "==" {
            let lv = try evalExpr(lhs, scope)
            let rv = try evalExpr(rhs, scope)
            return .bool(valEqual(lv, rv))
        }
        if op == "!=" {
            let lv = try evalExpr(lhs, scope)
            let rv = try evalExpr(rhs, scope)
            return .bool(!valEqual(lv, rv))
        }
        // arithmetic and comparison operators
        let lv = try evalExpr(lhs, scope)
        let rv = try evalExpr(rhs, scope)
        return try applyBinop(op, lv, rv, ln)

    case .unop(let op, let operand, let ln):
        if op == "not" {
            let v = try evalExpr(operand, scope)
            return .bool(!truthy(v))
        }
        // neg
        let v = try evalExpr(operand, scope)
        guard case .int(let i) = v else {
            throw TernError(line: ln, message: "cannot apply - to \(typeName(v))")
        }
        if i == Int.min { throw TernError(line: ln, message: "integer overflow") }
        return .int(-i)

    case .call(let callee, let argExprs, let ln):
        let fnVal = try evalExpr(callee, scope)
        var args: [Val] = []
        args.reserveCapacity(argExprs.count)
        for ae in argExprs { args.append(try evalExpr(ae, scope)) }
        guard case .fn(let f) = fnVal else {
            throw TernError(line: ln, message: "cannot call \(typeName(fnVal))")
        }
        if f.builtinImpl != nil {
            // builtin
            if f.builtinArity >= 0 && args.count != f.builtinArity {
                throw TernError(line: ln, message: "expected \(f.builtinArity) arguments, got \(args.count)")
            }
            return try f.builtinImpl!(args, ln)
        } else {
            // user function
            if args.count != f.params.count {
                throw TernError(line: ln, message: "expected \(f.params.count) arguments, got \(args.count)")
            }
            let callScope = Scope(parent: f.capturedScope!)
            for i in 0..<f.params.count {
                callScope.declare(f.params[i], args[i])
            }
            let result = try execBlock(f.body, callScope)
            if case .returnVal(let v) = result { return v }
            return .nil_
        }

    case .index(let obj, let idx, let ln):
        let ov = try evalExpr(obj, scope)
        let iv = try evalExpr(idx, scope)
        return try indexRead(ov, iv, ln)

    case .listLit(let elems, _):
        var vals: [Val] = []
        vals.reserveCapacity(elems.count)
        for el in elems { vals.append(try evalExpr(el, scope)) }
        return .list(ListRef(vals))

    case .fnExpr(let params, let body, _):
        return .fn(FuncRef(params: params, body: body, scope: scope))
    }
}

func indexRead(_ obj: Val, _ idx: Val, _ ln: Int) throws -> Val {
    switch obj {
    case .list(let l):
        guard case .int(let i) = idx else {
            throw TernError(line: ln, message: "cannot index list with \(typeName(idx))")
        }
        if i < 0 || i >= l.elements.count {
            throw TernError(line: ln, message: "index \(i) out of range for length \(l.elements.count)")
        }
        return l.elements[i]
    case .string(let s):
        guard case .int(let i) = idx else {
            throw TernError(line: ln, message: "cannot index string with \(typeName(idx))")
        }
        let chars = Array(s.unicodeScalars)
        if i < 0 || i >= chars.count {
            throw TernError(line: ln, message: "index \(i) out of range for length \(chars.count)")
        }
        return .string(String(String.UnicodeScalarView([chars[i]])))
    default:
        throw TernError(line: ln, message: "cannot index \(typeName(obj)) with \(typeName(idx))")
    }
}

func applyBinop(_ op: String, _ lv: Val, _ rv: Val, _ ln: Int) throws -> Val {
    switch op {
    case "+":
        if case .int(let a) = lv, case .int(let b) = rv {
            let (r, ov) = a.addingReportingOverflow(b)
            if ov { throw TernError(line: ln, message: "integer overflow") }
            return .int(r)
        }
        if case .string(let a) = lv, case .string(let b) = rv { return .string(a + b) }
        if case .list(let a) = lv, case .list(let b) = rv {
            var elems = a.elements
            elems.append(contentsOf: b.elements)
            return .list(ListRef(elems))
        }
        throw TernError(line: ln, message: "cannot apply + to \(typeName(lv)) and \(typeName(rv))")
    case "-":
        guard case .int(let a) = lv, case .int(let b) = rv else {
            throw TernError(line: ln, message: "cannot apply - to \(typeName(lv)) and \(typeName(rv))")
        }
        let (r, ov) = a.subtractingReportingOverflow(b)
        if ov { throw TernError(line: ln, message: "integer overflow") }
        return .int(r)
    case "*":
        guard case .int(let a) = lv, case .int(let b) = rv else {
            throw TernError(line: ln, message: "cannot apply * to \(typeName(lv)) and \(typeName(rv))")
        }
        let (r, ov) = a.multipliedReportingOverflow(by: b)
        if ov { throw TernError(line: ln, message: "integer overflow") }
        return .int(r)
    case "/":
        guard case .int(let a) = lv, case .int(let b) = rv else {
            throw TernError(line: ln, message: "cannot apply / to \(typeName(lv)) and \(typeName(rv))")
        }
        if b == 0 { throw TernError(line: ln, message: "division by zero") }
        if a == Int.min && b == -1 { throw TernError(line: ln, message: "integer overflow") }
        return .int(a / b)
    case "%":
        guard case .int(let a) = lv, case .int(let b) = rv else {
            throw TernError(line: ln, message: "cannot apply % to \(typeName(lv)) and \(typeName(rv))")
        }
        if b == 0 { throw TernError(line: ln, message: "division by zero") }
        if b == -1 { return .int(0) }
        return .int(a % b)
    case "<":
        if case .int(let a) = lv, case .int(let b) = rv { return .bool(a < b) }
        if case .string(let a) = lv, case .string(let b) = rv { return .bool(a < b) }
        throw TernError(line: ln, message: "cannot apply < to \(typeName(lv)) and \(typeName(rv))")
    case "<=":
        if case .int(let a) = lv, case .int(let b) = rv { return .bool(a <= b) }
        if case .string(let a) = lv, case .string(let b) = rv { return .bool(a <= b) }
        throw TernError(line: ln, message: "cannot apply <= to \(typeName(lv)) and \(typeName(rv))")
    case ">":
        if case .int(let a) = lv, case .int(let b) = rv { return .bool(a > b) }
        if case .string(let a) = lv, case .string(let b) = rv { return .bool(a > b) }
        throw TernError(line: ln, message: "cannot apply > to \(typeName(lv)) and \(typeName(rv))")
    case ">=":
        if case .int(let a) = lv, case .int(let b) = rv { return .bool(a >= b) }
        if case .string(let a) = lv, case .string(let b) = rv { return .bool(a >= b) }
        throw TernError(line: ln, message: "cannot apply >= to \(typeName(lv)) and \(typeName(rv))")
    default:
        throw TernError(line: ln, message: "unknown operator \(op)")
    }
}

func execBlock(_ stmts: [ASTStmt], _ scope: Scope) throws -> Ctrl {
    for s in stmts {
        let c = try execStmt(s, scope)
        switch c {
        case .normal: continue
        default: return c
        }
    }
    return .normal
}

func execStmt(_ s: ASTStmt, _ scope: Scope) throws -> Ctrl {
    switch s {
    case .letDecl(let name, let value, _):
        let v = try evalExpr(value, scope)
        scope.declare(name, v)
        return .normal

    case .fnDecl(let name, let params, let body, _):
        let f = FuncRef(params: params, body: body, scope: scope)
        scope.declare(name, .fn(f))
        return .normal

    case .ifStmt(let cond, let then, let elsePart, _):
        let cv = try evalExpr(cond, scope)
        if truthy(cv) {
            let inner = Scope(parent: scope)
            return try execBlock(then, inner)
        } else {
            switch elsePart {
            case .none: return .normal
            case .elseIf(let stmt): return try execStmt(stmt, scope)
            case .elseBlock(let stmts):
                let inner = Scope(parent: scope)
                return try execBlock(stmts, inner)
            }
        }

    case .whileStmt(let cond, let body, _):
        while true {
            let cv = try evalExpr(cond, scope)
            if !truthy(cv) { break }
            let inner = Scope(parent: scope)
            let c = try execBlock(body, inner)
            switch c {
            case .breakLoop: break
            case .continueLoop: continue
            case .returnVal(let v): return .returnVal(v)
            case .normal: continue
            }
        }
        return .normal

    case .forStmt(let varName, let iterable, let body, let ln):
        let iterVal = try evalExpr(iterable, scope)
        guard case .list(let lst) = iterVal else {
            throw TernError(line: ln, message: "cannot iterate \(typeName(iterVal))")
        }
        var i = 0
        while i < lst.elements.count {
            let inner = Scope(parent: scope)
            inner.declare(varName, lst.elements[i])
            let c = try execBlock(body, inner)
            switch c {
            case .breakLoop: break
            case .continueLoop: i += 1; continue
            case .returnVal(let v): return .returnVal(v)
            case .normal: i += 1; continue
            }
            break // breakLoop exits while
        }
        return .normal

    case .returnStmt(let value, _):
        if let v = value { return .returnVal(try evalExpr(v, scope)) }
        return .returnVal(.nil_)

    case .breakStmt: return .breakLoop
    case .continueStmt: return .continueLoop

    case .assign(let name, let value, let ln):
        let v = try evalExpr(value, scope)
        if !scope.assign(name, v) {
            throw TernError(line: ln, message: "undefined variable \(name)")
        }
        return .normal

    case .indexAssign(let obj, let idx, let value, let ln):
        let ov = try evalExpr(obj, scope)
        let iv = try evalExpr(idx, scope)
        let vv = try evalExpr(value, scope)
        guard case .list(let l) = ov else {
            throw TernError(line: ln, message: "cannot assign into \(typeName(ov))")
        }
        guard case .int(let i) = iv else {
            throw TernError(line: ln, message: "cannot index list with \(typeName(iv))")
        }
        if i < 0 || i >= l.elements.count {
            throw TernError(line: ln, message: "index \(i) out of range for length \(l.elements.count)")
        }
        l.elements[i] = vv
        return .normal

    case .exprStmt(let expr, _):
        _ = try evalExpr(expr, scope)
        return .normal
    }
}

