                    oldLines[oldLines.count - 1] = Array(oldLines.last![0..<oldLines.last!.count - 1])
                }
            case 0x2B: // added - affects new side
                if !newLines.isEmpty, newLines.last!.last == 0x0A {
                    newLines[newLines.count - 1] = Array(newLines.last![0..<newLines.last!.count - 1])
                }
            default:
                break
            }
            i += 1
            continue
        }

        let content = Array(line[1...])

        switch marker {
        case 0x20: // space - context
            oldLines.append(content)
            newLines.append(content)
        case 0x2D: // minus - removed
            oldLines.append(content)
        case 0x2B: // plus - added
            newLines.append(content)
        default:
            break
        }

        lastMarker = marker
        i += 1
    }

    let malformed = (oldLines.count != b) || (newLines.count != d)
    return (Hunk(a: a, b: b, c: c, d: d, oldLines: oldLines, newLines: newLines, malformed: malformed), i)
}

func parseDiff(_ diffData: [UInt8]) -> [Section] {
    let lines = splitIntoLines(diffData)
    var sections: [Section] = []
    var i = 0

    while i < lines.count {
        if !startsWithString(lines[i], "diff --git a/") {
            i += 1
            continue
        }

        let s = lineToString(lines[i])
        let afterPrefix = String(s.dropFirst("diff --git a/".count))
        guard let bPos = afterPrefix.range(of: " b/") else {
            i += 1
            continue
        }
        let path = String(afterPrefix[afterPrefix.startIndex..<bPos.lowerBound])

        i += 1
        var kind: SectionKind = .modify
        var hunks: [Hunk] = []
        var afterHeader = false

        while i < lines.count {
            let hline = lines[i]

            if startsWithString(hline, "diff --git ") {
                break
            }

            if !afterHeader {
                if startsWithString(hline, "new file mode ") {
                    kind = .create
                    i += 1
                } else if startsWithString(hline, "deleted file mode ") {
                    kind = .delete
                    i += 1
                } else if startsWithString(hline, "index ") {
                    i += 1
                } else if startsWithString(hline, "--- ") {
                    i += 1
                    if i < lines.count && startsWithString(lines[i], "+++ ") {
                        i += 1
                    }
                    afterHeader = true
                } else if startsWithString(hline, "@@ ") {
                    afterHeader = true
                } else {
                    i += 1
                }
            }

            if afterHeader {
                if i >= lines.count { break }
                let hl = lines[i]
                if startsWithString(hl, "diff --git ") { break }
                if startsWithString(hl, "@@ ") {
                    let (hunk, newI) = parseHunk(lines, i)
                    hunks.append(hunk)
                    i = newI
                } else {
                    i += 1
                }
            }
        }

        sections.append(Section(path: path, kind: kind, hunks: hunks))
    }

    return sections
}

func applyHunks(_ content: [[UInt8]], hunks: [Hunk]) -> ([[UInt8]], [String], Bool) {
    var current = content
    var delta = 0
    var reports: [String] = []
    var allApplied = true

    for (idx, hunk) in hunks.enumerated() {
        let hunkNum = idx + 1

        if hunk.malformed {
            reports.append("  hunk \(hunkNum): malformed")
            allApplied = false
            continue
        }

        let P = hunk.a + delta

        if hunk.b == 0 {
            if P < 0 || P > current.count {
                reports.append("  hunk \(hunkNum): rejected")
                allApplied = false
                continue
            }
            var newContent: [[UInt8]] = []
            if P > 0 {
                newContent.append(contentsOf: current[0..<P])
            }
            newContent.append(contentsOf: hunk.newLines)
            if P < current.count {
                newContent.append(contentsOf: current[P..<current.count])
            }
            current = newContent
            delta += hunk.d
            reports.append("  hunk \(hunkNum): applied at \(P) (offset 0)")
        } else {
            let b = hunk.b
            let n = current.count

            if n < b {
                reports.append("  hunk \(hunkNum): rejected")
                allApplied = false
                continue
            }

            let minP = 1
            let maxP = n - b + 1

            var found = false
            var foundP = 0

            let maxDist = max(P - minP, maxP - P)

            for k in 0...max(maxDist, 0) {
                if k == 0 {
                    if P >= minP && P <= maxP {
                        var matches = true
                        for j in 0..<b {
                            if current[P - 1 + j] != hunk.oldLines[j] {
                                matches = false
                                break
                            }
                        }
                        if matches {
                            found = true
                            foundP = P
                            break
                        }
                    }
                } else {
                    let p1 = P - k
                    if p1 >= minP && p1 <= maxP {
                        var matches = true
                        for j in 0..<b {
                            if current[p1 - 1 + j] != hunk.oldLines[j] {
                                matches = false
                                break
                            }
                        }
                        if matches {
                            found = true
                            foundP = p1
                            break
                        }
                    }
                    let p2 = P + k
                    if p2 >= minP && p2 <= maxP {
                        var matches = true
                        for j in 0..<b {
                            if current[p2 - 1 + j] != hunk.oldLines[j] {
                                matches = false
                                break
                            }
                        }
                        if matches {
                            found = true
                            foundP = p2
                            break
                        }
                    }
                }
            }

            if found {
                var newContent: [[UInt8]] = []
                if foundP - 1 > 0 {
                    newContent.append(contentsOf: current[0..<(foundP - 1)])
                }
                newContent.append(contentsOf: hunk.newLines)
                let tailStart = foundP + b - 1
                if tailStart < current.count {
                    newContent.append(contentsOf: current[tailStart..<current.count])
                }
                current = newContent
                let offset = foundP - P
                delta += hunk.d - hunk.b
                let offsetStr = offset > 0 ? "+\(offset)" : "\(offset)"
                reports.append("  hunk \(hunkNum): applied at \(foundP) (offset \(offsetStr))")
            } else {
                reports.append("  hunk \(hunkNum): rejected")
                allApplied = false
            }
        }
    }

    return (current, reports, allApplied)
}

func kindString(_ kind: SectionKind) -> String {
    switch kind {
    case .create: return "create"
    case .delete: return "delete"
    case .modify: return "modify"
    }
}

