import * as fs from 'fs';
import * as path from 'path';

function crc32(data: Buffer): number {
    const table: number[] = new Array(256);
    for (let i = 0; i < 256; i++) {
        let c = i;
        for (let j = 0; j < 8; j++) {
            if (c & 1) c = 0xEDB88320 ^ (c >>> 1);
            else c = c >>> 1;
        }
        table[i] = c;
    }
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < data.length; i++) {
        crc = table[(crc ^ data[i]) & 0xFF] ^ (crc >>> 8);
    }
    return (crc ^ 0xFFFFFFFF) >>> 0;
}

function splitLines(content: string): string[] {
    if (content === '') return [];
    const parts = content.split('\n');
    const lines: string[] = [];
    for (let i = 0; i < parts.length; i++) {
        if (i < parts.length - 1) {
            lines.push(parts[i] + '\n');
        } else {
            if (parts[i] !== '') {
                lines.push(parts[i]);
            }
        }
    }
    return lines;
}

interface Hunk {
    a: number;
    b: number;
    c: number;
    d: number;
    oldLines: string[];
    newLines: string[];
    malformed: boolean;
}

interface Section {
    filePath: string;
    kind: 'create' | 'delete' | 'modify';
    hunks: Hunk[];
}

function parseDiff(diffContent: string): Section[] {
    const lines = diffContent.split('\n');
    if (lines.length > 0 && lines[lines.length - 1] === '') {
        lines.pop();
    }

    const sections: Section[] = [];
    let i = 0;

    while (i < lines.length) {
        const line = lines[i];
        const diffMatch = line.match(/^diff --git a\/(.+) b\/(.+)$/);
        if (!diffMatch) {
            i++;
            continue;
        }

        const filePath = diffMatch[1];
        i++;

        let kind: 'create' | 'delete' | 'modify' = 'modify';

        while (i < lines.length) {
            const l = lines[i];
            if (l.startsWith('new file mode')) {
                kind = 'create';
                i++;
            } else if (l.startsWith('deleted file mode')) {
                kind = 'delete';
                i++;
            } else if (l.startsWith('index ')) {
                i++;
            } else if (
                l.startsWith('--- ') ||
                l.startsWith('+++ ') ||
                l.startsWith('@@ ') ||
                l.startsWith('diff --git ')
            ) {
                break;
            } else {
                i++;
            }
        }

        if (i < lines.length && lines[i].startsWith('--- ')) i++;
        if (i < lines.length && lines[i].startsWith('+++ ')) i++;

        const hunks: Hunk[] = [];

        while (i < lines.length) {
            const l = lines[i];
            if (l.startsWith('diff --git ')) break;
            if (!l.startsWith('@@ ')) {
                i++;
                continue;
            }

            const hunkMatch = l.match(/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/);
            if (!hunkMatch) {
                i++;
                continue;
            }

            const a = parseInt(hunkMatch[1]);
            const b = hunkMatch[2] !== undefined ? parseInt(hunkMatch[2]) : 1;
            const c = parseInt(hunkMatch[3]);
            const d = hunkMatch[4] !== undefined ? parseInt(hunkMatch[4]) : 1;

            i++;

            const oldLines: string[] = [];
            const newLines: string[] = [];
            let lastMarker = '';

            while (i < lines.length) {
                const bl = lines[i];
                if (bl.startsWith('diff --git ') || bl.startsWith('@@ ')) break;

                if (bl.startsWith('\\')) {
                    if (lastMarker === '-' || lastMarker === ' ') {
                        if (oldLines.length > 0) {
                            oldLines[oldLines.length - 1] = oldLines[oldLines.length - 1].replace(/\n$/, '');
                        }
                    }
                    if (lastMarker === '+' || lastMarker === ' ') {
                        if (newLines.length > 0) {
                            newLines[newLines.length - 1] = newLines[newLines.length - 1].replace(/\n$/, '');
                        }
                    }
                    i++;
                    continue;
                }

                if (bl.length === 0) {
                    i++;
                    continue;
                }

                const marker = bl[0];
                const content = bl.slice(1);

                if (marker === ' ') {
                    oldLines.push(content + '\n');
                    newLines.push(content + '\n');
                    lastMarker = ' ';
                } else if (marker === '-') {
                    oldLines.push(content + '\n');
                    lastMarker = '-';
                } else if (marker === '+') {
                    newLines.push(content + '\n');
                    lastMarker = '+';
                }

                i++;
            }

            const malformed = oldLines.length !== b || newLines.length !== d;
            hunks.push({ a, b, c, d, oldLines, newLines, malformed });
        }

        sections.push({ filePath, kind, hunks });
    }

    return sections;
}

function main(): void {
    const dir = process.argv[2];
    const diffPath = path.join(dir, 'changes.diff');
    const treePath = path.join(dir, 'tree');

    const diffContent = fs.readFileSync(diffPath, 'latin1');
    const sections = parseDiff(diffContent);

    sections.sort((a, b) =>
        Buffer.from(a.filePath, 'latin1').compare(Buffer.from(b.filePath, 'latin1'))
    );

    const output: string[] = [];

    for (const section of sections) {
        const fullPath = path.join(treePath, section.filePath);

        if (section.kind === 'create') {
            if (fs.existsSync(fullPath)) {
                output.push(`${section.filePath}: ${section.kind}`);
                output.push(`  error: already exists`);
                continue;
            }
        } else {
            if (!fs.existsSync(fullPath)) {
                output.push(`${section.filePath}: ${section.kind}`);
                output.push(`  error: not found`);
                continue;
            }
        }

        let lines: string[];
        if (section.kind === 'create') {
            lines = [];
        } else {
            const content = fs.readFileSync(fullPath, 'latin1');
            lines = splitLines(content);
        }

        let delta = 0;
        const results: { status: string; position?: number; offset?: number }[] = [];

        for (const hunk of section.hunks) {
            if (hunk.malformed) {
                results.push({ status: 'malformed' });
                continue;
            }

            const P = hunk.a + delta;

            if (hunk.b === 0) {
                if (P >= 0 && P <= lines.length) {
                    lines.splice(P, 0, ...hunk.newLines);
                    results.push({ status: 'applied', position: P, offset: 0 });
                    delta += hunk.d - hunk.b;
                } else {
                    results.push({ status: 'rejected' });
                }
                continue;
            }

            let found = false;
            for (let offset = 0; ; offset++) {
                const low = P - offset;
                const high = P + offset;

                if (low < 1 && high + hunk.b - 1 > lines.length) break;

                if (low >= 1 && low + hunk.b - 1 <= lines.length) {
                    let match = true;
                    for (let j = 0; j < hunk.b; j++) {
                        if (lines[low - 1 + j] !== hunk.oldLines[j]) {
                            match = false;
                            break;
                        }
                    }
                    if (match) {
                        lines.splice(low - 1, hunk.b, ...hunk.newLines);
                        results.push({ status: 'applied', position: low, offset: low - P });
                        delta += hunk.d - hunk.b;
                        found = true;
                        break;
                    }
                }

                if (offset > 0 && high >= 1 && high + hunk.b - 1 <= lines.length) {
                    let match = true;
                    for (let j = 0; j < hunk.b; j++) {
                        if (lines[high - 1 + j] !== hunk.oldLines[j]) {
                            match = false;
                            break;
                        }
                    }
                    if (match) {
                        lines.splice(high - 1, hunk.b, ...hunk.newLines);
                        results.push({ status: 'applied', position: high, offset: high - P });
                        delta += hunk.d - hunk.b;
                        found = true;
                        break;
                    }
                }
            }

            if (!found) {
                results.push({ status: 'rejected' });
            }
        }

        output.push(`${section.filePath}: ${section.kind}`);

        for (let idx = 0; idx < results.length; idx++) {
            const r = results[idx];
            const n = idx + 1;
            if (r.status === 'applied') {
                const k = r.offset!;
                const kStr = k > 0 ? `+${k}` : `${k}`;
                output.push(`  hunk ${n}: applied at ${r.position} (offset ${kStr})`);
            } else if (r.status === 'rejected') {
                output.push(`  hunk ${n}: rejected`);
            } else {
                output.push(`  hunk ${n}: malformed`);
            }
        }

        if (section.kind === 'delete') {
            const allApplied = results.every(r => r.status === 'applied');
            if (allApplied && lines.length === 0) {
                output.push(`  result: deleted`);
            } else {
                const content = Buffer.from(lines.join(''), 'latin1');
                const crc = crc32(content);
                output.push(`  result: ${lines.length} lines, crc32 ${crc.toString(16).padStart(8, '0')}`);
            }
        } else {
            const content = Buffer.from(lines.join(''), 'latin1');
            const crc = crc32(content);
            output.push(`  result: ${lines.length} lines, crc32 ${crc.toString(16).padStart(8, '0')}`);
        }
    }

    if (output.length > 0) {
        process.stdout.write(output.join('\n') + '\n');
    }
}

main();

import sys
import os
import re
import base64
import zlib

def main():
    directory = sys.argv[1]
    files = sorted(os.listdir(directory))

    first = True
    for fname in files:
        if not fname.endswith('.eml'):
            continue
        if not first:
            print()
        first = False

        filepath = os.path.join(directory, fname)
        with open(filepath, 'rb') as f:
            data = f.read()

        print(f'== {fname}')

        entity = parse_entity(data)

        # From and Subject
        from_raw = entity['headers'].get('from')
        subject_raw = entity['headers'].get('subject')

        if from_raw is not None:
            print(f'From: {quote_string(decode_encoded_words(from_raw))}')
        else:
            print('From: -')

        if subject_raw is not None:
            print(f'Subject: {quote_string(decode_encoded_words(subject_raw))}')
        else:
            print('Subject: -')

        print_tree(entity, 0)

def parse_entity(data):
    if b'\r\n' in data:
        lb = b'\r\n'
    else:
        lb = b'\n'

    sep = lb + lb
    idx = data.find(sep)
    if idx == -1:
        if data.startswith(lb):
            headers_raw = b''
            body = data[len(lb):]
        else:
            headers_raw = data
            body = b''
    else:
        headers_raw = data[:idx]
        body = data[idx + len(sep):]

    headers = parse_headers(headers_raw, lb)

    ct_raw = headers.get('content-type')
    if ct_raw is not None:
        ct_type, ct_subtype, ct_params = parse_content_type(ct_raw)
    else:
        ct_type, ct_subtype, ct_params = 'text', 'plain', {}

    cte_raw = headers.get('content-transfer-encoding', '7bit').lower().strip()
    if ct_type == 'multipart':
        cte = '7bit'  # ignored, but we still need a value for output
        # Actually, for multipart, cte is ignored. What do we print?
        # Looking at the output format: multipart prints don't include cte.
        # So it doesn't matter what we store.
    else:
        cte = cte_raw

    cd_raw = headers.get('content-disposition')
    if cd_raw is not None:
        disp_type, disp_params = parse_content_disposition(cd_raw)
    else:
        disp_type, disp_params = None, {}

    filename = get_filename(ct_params, disp_params)

    if ct_type == 'text':
        charset = ct_params.get('charset', 'us-ascii').lower()
    else:
        charset = None

    return {
        'headers': headers,
        'body': body,
        'lb': lb,
        'type': ct_type,
        'subtype': ct_subtype,
        'cte': cte,
        'disp_type': disp_type,
        'disp_params': disp_params,
        'ct_params': ct_params,
        'filename': filename,
        'charset': charset,
    }

def parse_headers(raw, lb):
    if not raw:
        return {}

    lines = raw.split(lb)

    # Unfold
    unfolded = []
    for line in lines:
        if line and (line[0:1] == b' ' or line[0:1] == b'\t'):
            if unfolded:
                unfolded[-1] += lb + line
            else:
                unfolded.append(line)
        else:
            unfolded.append(line)

    headers = {}
    for line in unfolded:
        if not line:
            continue
        colon = line.find(b':')
        if colon == -1:
            continue
        name = line[:colon].strip().decode('ascii').lower()
        value = line[colon+1:].strip(b' \t').decode('ascii')
        headers[name] = value

    return headers

def parse_content_type(value):
    i = 0
    while i < len(value) and value[i] in ' \t':
        i += 1

    # Read type
    type_start = i
    while i < len(value) and value[i] not in '; \t/':
        i += 1
    type_str = value[type_start:i]

    # Skip spaces/tabs
    while i < len(value) and value[i] in ' \t':
        i += 1

    # Expect /
    if i < len(value) and value[i] == '/':
        i += 1
    else:
        return 'text', 'plain', {}

    # Skip spaces/tabs
    while i < len(value) and value[i] in ' \t':
        i += 1

    # Read subtype
    sub_start = i
    while i < len(value) and value[i] not in '; \t':
        i += 1
    subtype_str = value[sub_start:i]

    params = parse_params(value, i)
    return type_str.lower(), subtype_str.lower(), params

def parse_content_disposition(value):
    i = 0
    while i < len(value) and value[i] in ' \t':
        i += 1

    start = i
    while i < len(value) and value[i] not in '; \t':
        i += 1
    disp_type = value[start:i].lower()

    params = parse_params(value, i)
    return disp_type, params

def parse_params(value, start):
    params = {}
    i = start
    while i < len(value):
        while i < len(value) and value[i] in ' \t':
            i += 1
        if i >= len(value) or value[i] != ';':
            break
        i += 1
        while i < len(value) and value[i] in ' \t':
            i += 1

        attr_start = i
        while i < len(value) and value[i] not in ' \t=':
            i += 1
        attr_name = value[attr_start:i].lower()

        while i < len(value) and value[i] in ' \t':
            i += 1

        if i < len(value) and value[i] == '=':
            i += 1
        else:
            if attr_name:
                params[attr_name] = ''
            continue

        while i < len(value) and value[i] in ' \t':
            i += 1

        if i < len(value) and value[i] == '"':
            i += 1
            val_chars = []
            while i < len(value) and value[i] != '"':
                if value[i] == '\\' and i + 1 < len(value):
                    i += 1
                    val_chars.append(value[i])
                else:
                    val_chars.append(value[i])
                i += 1
            if i < len(value):
                i += 1
            params[attr_name] = ''.join(val_chars)
        else:
            val_start = i
            while i < len(value) and value[i] not in '; \t':
                i += 1
            params[attr_name] = value[val_start:i]

    return params

def get_filename(ct_params, disp_params):
    if has_rfc2231(disp_params, 'filename'):
        result = get_rfc2231_value(disp_params, 'filename')
        if result is not None:
            charset, data = result
            return decode_charset_bytes(data, charset)

    if 'filename' in disp_params:
        return decode_encoded_words(disp_params['filename'])

    if has_rfc2231(ct_params, 'name'):
        result = get_rfc2231_value(ct_params, 'name')
        if result is not None:
            charset, data = result
            return decode_charset_bytes(data, charset)

    if 'name' in ct_params:
        return decode_encoded_words(ct_params['name'])

    return None

def has_rfc2231(params, attr):
    if attr + '*' in params:
        return True
    for key in params:
        if key.startswith(attr + '*'):
            suffix = key[len(attr) + 1:]
            base = suffix.rstrip('*')
            if base.isdigit():
                return True
    return False

def get_rfc2231_value(params, attr):
    if attr + '*' in params:
        return parse_pct_param(params[attr + '*'])

    segments = {}
    for key in params:
        if key.startswith(attr + '*'):
            suffix = key[len(attr) + 1:]
            if suffix.endswith('*'):
                encoded = True
                num_str = suffix[:-1]
            else:
                encoded = False
                num_str = suffix
            if num_str.isdigit():
                segments[int(num_str)] = (params[key], encoded)

    if not segments:
        return None

    charset = None
    byte_parts = []

    for num in sorted(segments.keys()):
        val, encoded = segments[num]
        if encoded:
            if num == 0:
                first_q = val.find("'")
                second_q = val.find("'", first_q + 1) if first_q != -1 else -1
                if first_q != -1 and second_q != -1:
                    charset = val[:first_q]
                    rest = val[second_q + 1:]
                    byte_parts.append(percent_decode(rest))
                else:
                    byte_parts.append(percent_decode(val))
            else:
                byte_parts.append(percent_decode(val))
        else:
            byte_parts.append(val.encode('ascii'))

    if charset is None:
        charset = 'us-ascii'

    return charset, b''.join(byte_parts)

def parse_pct_param(val):
    first_q = val.find("'")
    second_q = val.find("'", first_q + 1) if first_q != -1 else -1
    if first_q != -1 and second_q != -1:
        charset = val[:first_q]
        rest = val[second_q + 1:]
        return charset, percent_decode(rest)
    else:
        return 'us-ascii', percent_decode(val)

def percent_decode(s):
    result = bytearray()
    i = 0
    while i < len(s):
        if s[i] == '%' and i + 2 < len(s):
            hex_str = s[i+1:i+3]
            if all(c in '0123456789abcdefABCDEF' for c in hex_str):
                result.append(int(hex_str, 16))
                i += 3
            else:
                result.append(ord('%'))
                i += 1
        else:
            result.append(ord(s[i]))
            i += 1
    return bytes(result)

def decode_encoded_words(text):
    pattern = r'=\?([^? \t]+)\?([BbQq])\?([^? \t]*)\?='
    matches = list(re.finditer(pattern, text))
    if not matches:
        return text

    # Group into runs
    runs = []
    current_run = [matches[0]]
    current_charset = base_charset(matches[0].group(1))

    for k in range(1, len(matches)):
        prev = matches[k-1]
        curr = matches[k]
        between = text[prev.end():curr.start()]
        curr_cs = base_charset(curr.group(1))

        if all(c in ' \t' for c in between) and curr_cs.lower() == current_charset.lower():
            current_run.append(curr)
        else:
            runs.append((current_run, current_charset))
            current_run = [curr]
            current_charset = curr_cs

    runs.append((current_run, current_charset))

    # Build result
    result = []
    last_end = 0
    for run, cs in runs:
        result.append(text[last_end:run[0].start()])
        byte_data = b''
        for wm in run:
            enc = wm.group(2).upper()
            encoded = wm.group(3)
            if enc == 'B':
                byte_data += base64_decode_str(encoded)
            elif enc == 'Q':
                byte_data += q_decode_str(encoded)
        decoded = decode_charset_bytes(byte_data, cs)
        result.append(decoded)
        last_end = run[-1].end()

    result.append(text[last_end:])
    return ''.join(result)

def base_charset(charset):
    if '*' in charset:
        return charset[:charset.index('*')]
    return charset

def base64_decode_str(s):
    alphabet = set('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/')
    chars = []
    for c in s:
        if c in alphabet:
            chars.append(c)
        elif c == '=':
            break
    filtered = ''.join(chars)
    padding = (4 - len(filtered) % 4) % 4
    filtered += '=' * padding
    return base64.b64decode(filtered)

def q_decode_str(s):
    result = bytearray()
    i = 0
    while i < len(s):
        if s[i] == '_':
            result.append(0x20)
            i += 1
        elif s[i] == '=' and i + 2 < len(s) and s[i+1] in '0123456789abcdefABCDEF' and s[i+2] in '0123456789abcdefABCDEF':
            result.append(int(s[i+1:i+3], 16))
            i += 3
        else:
            result.append(ord(s[i]))
            i += 1
    return bytes(result)

def decode_charset_bytes(data, charset):
    cs = charset.lower()
    if cs == 'us-ascii':
        return data.decode('ascii')
    elif cs == 'utf-8':
        return data.decode('utf-8')
    elif cs == 'iso-8859-1':
        return data.decode('latin-1')
    elif cs == 'windows-1252':
        return data.decode('cp1252')
    else:
        return data.decode('latin-1')  # fallback

def decode_cte(data, cte, lb):
    if cte in ('7bit', '8bit', 'binary'):
        return data
    elif cte == 'base64':
        return decode_base64_body(data)
    elif cte == 'quoted-printable':
        return decode_qp_body(data, lb)
    else:
        return data

def decode_base64_body(data):
    alphabet = set(b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/')
    chars = bytearray()
    for b in data:
        if b in alphabet:
            chars.append(b)
        elif b == ord('='):
            break
    s = bytes(chars)
    padding = (4 - len(s) % 4) % 4
    s += b'=' * padding
    return base64.b64decode(s)

def decode_qp_body(data, lb):
    lines = data.split(lb)

    # Remove trailing spaces/tabs from each line
    stripped = [line.rstrip(b' \t') for line in lines]

    # Handle soft line breaks
    result = bytearray()
    i = 0
    while i < len(stripped):
        line = stripped[i]
        if line.endswith(b'=') and i + 1 < len(stripped):
            result.extend(line[:-1])
            i += 1
        else:
            result.extend(line)
            if i + 1 < len(stripped):
                result.extend(lb)
            i += 1

    # Handle =XY
    final = bytearray()
    i = 0
    while i < len(result):
        if result[i:i+1] == b'=' and i + 2 < len(result):
            hex_str = result[i+1:i+3]
            if all(b in b'0123456789abcdefABCDEF' for b in hex_str):
                final.append(int(hex_str, 16))
                i += 3
            else:
                final.append(ord('='))
                i += 1
        else:
            final.append(result[i])
            i += 1

    return bytes(final)

def print_tree(entity, indent):
    prefix = '  ' * indent

    if entity['type'] == 'multipart':
        boundary = entity['ct_params'].get('boundary', '')
        parts = parse_multipart(entity['body'], boundary, entity['lb'])
        print(f'{prefix}multipart/{entity["subtype"]} parts={len(parts)}')
        for part in parts:
            print_tree(part, indent + 1)
    elif entity['type'] == 'text' and entity['disp_type'] != 'attachment':
        raw_body = entity['body']
        decoded_bytes = decode_cte(raw_body, entity['cte'], entity['lb'])
        text = decode_charset_bytes(decoded_bytes, entity['charset'])
        text = text.replace('\r\n', '\n').replace('\r', '\n')
        chars = len(text)
        print(f'{prefix}text/{entity["subtype"]} charset={entity["charset"]} cte={entity["cte"]} chars={chars}')
        print(f'{prefix}  {quote_string(text)}')
    else:
        raw_body = entity['body']
        decoded_bytes = decode_cte(raw_body, entity['cte'], entity['lb'])
        size = len(decoded_bytes)
        crc = zlib.crc32(decoded_bytes) & 0xFFFFFFFF
        disp_str = entity['disp_type'] if entity['disp_type'] else '-'
        name_str = quote_string(entity['filename']) if entity['filename'] is not None else '-'
        print(f'{prefix}{entity["type"]}/{entity["subtype"]} cte={entity["cte"]} disposition={disp_str} name={name_str} size={size} crc32={crc:08x}')

def parse_multipart(body, boundary, lb):
    if not boundary:
        return []

    delim = b'--' + boundary.encode('ascii')
    close_delim = delim + b'--'

    # Find all delimiter positions
    delimiters = []
    pos = 0
    while pos < len(body):
        line_end = body.find(lb, pos)
        if line_end == -1:
            line_content = body[pos:]
            line_end_full = len(body)
        else:
            line_content = body[pos:line_end]
            line_end_full = line_end + len(lb)

        stripped = line_content.rstrip(b' \t')
        if stripped == close_delim:
            delimiters.append((pos, line_end_full, True))
        elif stripped == delim:
            delimiters.append((pos, line_end_full, False))

        pos = line_end_full

    # Find first regular delimiter and first close delimiter after it
    first_reg = None
    close_idx = None
    for i, (start, end, is_close) in enumerate(delimiters):
        if not is_close and first_reg is None:
            first_reg = i
        if is_close and first_reg is not None:
            close_idx = i
            break

    if first_reg is None:
        return []

    if close_idx is None:
        # No close delimiter; treat end of body as close
        close_idx = len(delimiters)

    # Parts are between consecutive delimiters from first_reg to close_idx
    parts = []
    relevant = delimiters[first_reg:close_idx]

    for i in range(len(relevant)):
        if i == 0:
            content_start = relevant[0][1]
        else:
            content_start = relevant[i - 1][1]

        # Wait, that's wrong. Let me redo.
        pass

    # Actually, parts are between consecutive delimiters.
    # Part i is between delimiters[first_reg + i] and delimiters[first_reg + i + 1]
    # But the last part is between delimiters[close_idx - 1] and delimiters[close_idx]

    # Hmm, let me think again.
    # delimiters[first_reg] is the first regular delimiter.
    # delimiters[first_reg + 1] is the next delimiter (regular or close).
    # Part 1 is between delimiters[first_reg] and delimiters[first_reg + 1].
    # Part 2 is between delimiters[first_reg + 1] and delimiters[first_reg + 2].
    # ...
    # Part N is between delimiters[close_idx - 1] and delimiters[close_idx].

    # So the number of parts is close_idx - first_reg.

    for i in range(first_reg, close_idx):
        content_start = delimiters[i][1]
        content_end = delimiters[i + 1][0]

        # Remove trailing line break before next delimiter
        if content_end > content_start:
            if body[content_end - len(lb):content_end] == lb:
                content_end -= len(lb)

        part_data = body[content_start:content_end]
        part = parse_entity(part_data)
        parts.append(part)

    return parts

def quote_string(s):
    result = ['"']
    for c in s:
        cp = ord(c)
        if c == '\\':
            result.append('\\\\')
        elif c == '"':
            result.append('\\"')
        elif c == '\n':
            result.append('\\n')
        elif c == '\t':
            result.append('\\t')
        elif cp < 0x20 or (0x7F <= cp <= 0x9F):
            result.append('\\u{:04x}'.format(cp))
        else:
            result.append(c)
    result.append('"')
    return ''.join(result)

