        return decode_base64_body(data)
    elif cte == 'quoted-printable':
        return decode_qp_body(data, lb)
    else:
        return data


def decode_base64_body(data):
    alphabet = set(b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/')
    chars = bytearray()
    for b in data:
        if b in alphabet:
            chars.append(b)
        elif b == ord('='):
            break
    s = bytes(chars)
    padding = (4 - len(s) % 4) % 4
    s += b'=' * padding
    return base64.b64decode(s)


def decode_qp_body(data, lb):
    lines = data.split(lb)

    # Remove trailing spaces/tabs from each line
    stripped = [line.rstrip(b' \t') for line in lines]

    # Handle soft line breaks
    result = bytearray()
    i = 0
    while i < len(stripped):
        line = stripped[i]
        if line.endswith(b'=') and i + 1 < len(stripped):
            result.extend(line[:-1])
            i += 1
        else:
            result.extend(line)
            if i + 1 < len(stripped):
                result.extend(lb)
            i += 1

    # Handle =XY
    final = bytearray()
    i = 0
    while i < len(result):
        if result[i:i+1] == b'=' and i + 2 < len(result):
            hex_str = result[i+1:i+3]
            if all(b in b'0123456789abcdefABCDEF' for b in hex_str):
                final.append(int(hex_str, 16))
                i += 3
            else:
                final.append(ord('='))
                i += 1
        else:
            final.append(result[i])
            i += 1

    return bytes(final)


def print_tree(entity, indent):
    prefix = '  ' * indent

    if entity['type'] == 'multipart':
        boundary = entity['ct_params'].get('boundary', '')
        parts = parse_multipart(entity['body'], boundary, entity['lb'])
        print(f'{prefix}multipart/{entity["subtype"]} parts={len(parts)}')
        for part in parts:
            print_tree(part, indent + 1)
    elif entity['type'] == 'text' and entity['disp_type'] != 'attachment':
        raw_body = entity['body']
        decoded_bytes = decode_cte(raw_body, entity['cte'], entity['lb'])
        text = decode_charset_bytes(decoded_bytes, entity['charset'])
        text = text.replace('\r\n', '\n').replace('\r', '\n')
        chars = len(text)
        print(f'{prefix}text/{entity["subtype"]} charset={entity["charset"]} cte={entity["cte"]} chars={chars}')
        print(f'{prefix}  {quote_string(text)}')
    else:
        raw_body = entity['body']
        decoded_bytes = decode_cte(raw_body, entity['cte'], entity['lb'])
        size = len(decoded_bytes)
        crc = zlib.crc32(decoded_bytes) & 0xFFFFFFFF
        disp_str = entity['disp_type'] if entity['disp_type'] else '-'
        name_str = quote_string(entity['filename']) if entity['filename'] is not None else '-'
        print(f'{prefix}{entity["type"]}/{entity["subtype"]} cte={entity["cte"]} disposition={disp_str} name={name_str} size={size} crc32={crc:08x}')


def parse_multipart(body, boundary, lb):
    if not boundary:
        return []

    delim = b'--' + boundary.encode('ascii')
    close_delim = delim + b'--'

    # Find all delimiter positions
    delimiters = []
    pos = 0
    while pos < len(body):
        line_end = body.find(lb, pos)
        if line_end == -1:
            line_content = body[pos:]
            line_end_full = len(body)
        else:
            line_content = body[pos:line_end]
            line_end_full = line_end + len(lb)

        stripped = line_content.rstrip(b' \t')
        if stripped == close_delim:
            delimiters.append((pos, line_end_full, True))
        elif stripped == delim:
            delimiters.append((pos, line_end_full, False))

        pos = line_end_full

    # Find first regular delimiter and first close delimiter after it
    first_reg = None
    close_idx = None
    for i, (start, end, is_close) in enumerate(delimiters):
        if not is_close and first_reg is None:
            first_reg = i
        if is_close and first_reg is not None:
            close_idx = i
            break

    if first_reg is None:
        return []

    if close_idx is None:
        # No close delimiter; treat end of body as close
        close_idx = len(delimiters)

    # Parts are between consecutive delimiters from first_reg to close_idx
    parts = []
    for i in range(first_reg, close_idx):
        content_start = delimiters[i][1]
        content_end = delimiters[i + 1][0]

        # Remove trailing line break before next delimiter
        if content_end > content_start:
            if body[content_end - len(lb):content_end] == lb:
                content_end -= len(lb)

        part_data = body[content_start:content_end]
        part = parse_entity(part_data)
        parts.append(part)

    return parts


def quote_string(s):
    result = ['"']
    for c in s:
        cp = ord(c)
        if c == '\\':
            result.append('\\\\')
        elif c == '"':
            result.append('\\"')
        elif c == '\n':
            result.append('\\n')
        elif c == '\t':
            result.append('\\t')
        elif cp < 0x20 or (0x7F <= cp <= 0x9F):
            result.append('\\u{:04x}'.format(cp))
        else:
            result.append(c)
    result.append('"')
    return ''.join(result)


if __name__ == '__main__':
    main()

static List<Entity> parseMultipart(byte[] body, String boundary) {
    List<Entity> parts = new ArrayList<>();
    String delimiter = "--" + boundary;
    String closeDelimiter = delimiter + "--";

    // Split body into lines
    // Find delimiter lines and close delimiter lines
    // Parts are between consecutive delimiters

    List<int[]> linePositions = new ArrayList<>(); // [start, end) of each line (excluding line break)
    int pos = 0;
    while (pos < body.length) {
        int lineEnd = findLineBreak(body, pos);
        if (lineEnd == -1) {
            linePositions.add(new int[]{pos, body.length});
            break;
        }
        linePositions.add(new int[]{pos, lineEnd});
        pos = lineEnd + lbLen;
    }

    // Find delimiter and close delimiter lines
    List<Integer> delimIndices = new ArrayList<>();
    int closeIdx = -1;
    for (int i = 0; i < linePositions.size(); i++) {
        String line = new String(body, linePositions[i][0], linePositions[i][1] - linePositions[i][0], StandardCharsets.US_ASCII);
        if (isCloseDelimiter(line, closeDelimiter)) {
            closeIdx = i;
            break;
        } else if (isDelimiter(line, delimiter)) {
            delimIndices.add(i);
        }
    }

    // Parts are between consecutive delimiters
    for (int i = 0; i < delimIndices.size() - 1; i++) {
        int partStartLine = delimIndices.get(i) + 1;
        int partEndLine = delimIndices.get(i + 1);

        // The part content is from the start of partStartLine to the end of partEndLine's preceding line
        // "the line break that ends the last content line before a delimiter belongs to the delimiter, not to the part"

        int partStart, partEnd;
        if (partStartLine >= partEndLine) {
            // Empty part
            partStart = 0;
            partEnd = 0;
            // Actually, need to compute byte positions
            // partStart = start of line partStartLine (if exists)
            // partEnd = end of line partEndLine-1 + lineBreak (but we don't include this lineBreak)
            // Hmm, this is tricky
        }

        // Actually, let me think differently.
        // The part bytes are from the byte position after the delimiter line's line break
        // to the byte position at the start of the next delimiter line.
        // But "the line break that ends the last content line before a delimiter belongs to the delimiter, not to the part"
        // So the part ends at the end of the last content line (not including its line break).

        // Wait, let me re-read: "Each part is the content between two consecutive delimiters, where the line break that ends the last content line before a delimiter belongs to the delimiter, not to the part."

        // So if we have:
        // --boundary\r\n
        // part content line 1\r\n
        // part content line 2\r\n
        // --boundary\r\n
        // 
        // The part content is "part content line 1\r\npart content line 2"
        // (The \r\n after "line 2" belongs to the delimiter, not the part)

        // So the part bytes go from after the opening delimiter's line break to the position just before the closing delimiter's line break.

        // Hmm wait, "the line break that ends the last content line before a delimiter belongs to the delimiter". So the last line of the part doesn't include its trailing line break.

        // Let me compute byte positions:
        // After delimiter at index i: byte position = linePositions[i][1] + lbLen (start of next line)
        // Before delimiter at index i+1: byte position = linePositions[i+1][0] - lbLen (end of previous line, excluding its line break)
        // Wait, that's the end of the line before the delimiter. But what if the part is empty (delimiter immediately followed by another delimiter)?

        // If partStartLine >= partEndLine, the part is empty.

        // Let me compute:
        int partByteStart = linePositions[delimIndices.get(i)][1] + lbLen; // after delimiter line break
        int partByteEnd;
        if (partStartLine >= partEndLine) {
            // No content lines between delimiters
            // The part is empty
            partByteEnd = partByteStart; // empty
            // Actually wait, if delimiter at i is followed immediately by delimiter at i+1,
            // then partByteStart = end of line i + lbLen = start of line i+1 = linePositions[delimIndices.get(i+1)][0]
            // And partByteEnd should also be that (empty part)
            partByteEnd = linePositions[delimIndices.get(i+1)][0];
            // Hmm, but that would include the line break of the first delimiter... 
            // No: partByteStart = linePositions[delimIndices.get(i)][1] + lbLen
            // linePositions[delimIndices.get(i)][1] is the end of the delimiter line (before its line break)
            // + lbLen gives the position after the delimiter's line break = start of next line
            // If next line is the next delimiter, then partByteStart = linePositions[delimIndices.get(i+1)][0]
            // And partByteEnd should be the same (empty part)
            partByteEnd = partByteStart;
        } else {
            // Part has content lines from partStartLine to partEndLine-1
            // End of content = end of line (partEndLine-1) (excluding its line break)
            partByteEnd = linePositions[partEndLine - 1][1]; // end of last content line (before its line break)
            // But wait, we need to include the line breaks between content lines
            // The part content is everything from partByteStart to partByteEnd
            // This includes line breaks between content lines but not the final line break before the delimiter
        }

        byte[] partBytes = Arrays.copyOfRange(body, partByteStart, partByteEnd);
        Entity part = parseEntity(partBytes, 0, partBytes.length);
        parts.add(part);
    }

    return parts;
}

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.regex.*;
import java.util.zip.CRC32;

public class Main {
    static int lbLen;

    static class Entity {
        List<String[]> headers;
        byte[] body;
        List<Entity> parts; // null if not multipart
        String type, subtype;
        Map<String, String> ctParams;
        String dispType; // null if no Content-Disposition
        Map<String, String> dispParams;
        String cte;
    }

    public static void main(String[] args) throws Exception {
        File dir = new File(args[0]);
        File[] files = dir.listFiles((d, name) -> name.endsWith(".eml"));
        if (files == null) files = new File[0];
        Arrays.sort(files, Comparator.comparing(File::getName));

        boolean first = true;
        for (File f : files) {
            if (!first) System.out.println();
            first = false;
            processFile(f);
        }
    }

    static void processFile(File f) throws Exception {
        byte[] data = Files.readAllBytes(f.toPath());
        lbLen = detectLineBreak(data);
        Entity msg = parseEntity(data, 0, data.length);

        System.out.println("== " + f.getName());

        String from = getHeader(msg.headers, "from");
        System.out.println("From: " + (from != null ? toQuotedString(decodeEncodedWords(from)) : "-"));

        String subject = getHeader(msg.headers, "subject");
        System.out.println("Subject: " + (subject != null ? toQuotedString(decodeEncodedWords(subject)) : "-"));

        printEntity(msg, 0);
    }

    static int detectLineBreak(byte[] data) {
        for (int i = 0; i < data.length - 1; i++) {
            if (data[i] == '\r' && data[i + 1] == '\n') return 2;
        }
        return 1;
    }

    static int findLineBreak(byte[] data, int pos, int end) {
        if (lbLen == 2) {
            for (int i = pos; i < end - 1; i++) {
                if (data[i] == '\r' && data[i + 1] == '\n') return i;
            }
        } else {
            for (int i = pos; i < end; i++) {
                if (data[i] == '\n') return i;
            }
        }
        return -1;
    }

    static Entity parseEntity(byte[] data, int start, int end) {
        Entity e = new Entity();
        e.headers = new ArrayList<>();
        e.parts = null;

        // Parse headers
        int pos = start;
        List<String> rawLines = new ArrayList<>();
        boolean foundBlank = false;

        while (pos < end) {
            int lbPos = findLineBreak(data, pos, end);
            int contentEnd, nextPos;
            if (lbPos == -1) {
                contentEnd = end;
                nextPos = end;
            } else {
                contentEnd = lbPos;
                nextPos = lbPos + lbLen;
            }

            if (contentEnd == pos) {
                // Blank line
                pos = nextPos;
                foundBlank = true;
                break;
            }

            rawLines.add(new String(data, pos, contentEnd - pos, java.nio.charset.StandardCharsets.US_ASCII));
            pos = nextPos;
        }

        // Unfold
        List<String> unfolded = new ArrayList<>();
        for (String line : rawLines) {
            if (!line.isEmpty() && (line.charAt(0) == ' ' || line.charAt(0) == '\t')) {
                if (!unfolded.isEmpty()) {
                    unfolded.set(unfolded.size() - 1, unfolded.get(unfolded.size() - 1) + line);
                }
            } else {
                unfolded.add(line);
            }
        }

        // Parse header lines
        for (String line : unfolded) {
            int colon = line.indexOf(':');
            if (colon >= 0) {
                String name = line.substring(0, colon).trim().toLowerCase();
                String value = trimSpacesTabs(line.substring(colon + 1));
                e.headers.add(new String[]{name, value});
            }
        }

        // Body
        e.body = Arrays.copyOfRange(data, pos, end);

        // Content-Type
        String ctVal = getHeader(e.headers, "content-type");
        if (ctVal != null) {
            ParamResult pr = parseParams(ctVal);
            String main = pr.mainValue.toLowerCase();
            int slash = main.indexOf('/');
            if (slash >= 0) {
                e.type = main.substring(0, slash).trim();
                e.subtype = main.substring(slash + 1).trim();
            } else {
                e.type = main.trim();
                e.subtype = "";
            }
            e.ctParams = pr.params;
        } else {
            e.type = "text";
            e.subtype = "plain";
            e.ctParams = new LinkedHashMap<>();
        }

        // Content-Disposition
        String cdVal = getHeader(e.headers, "content-disposition");
        if (cdVal != null) {
            ParamResult pr = parseParams(cdVal);
            e.dispType = pr.mainValue.toLowerCase().trim();
            e.dispParams = pr.params;
        } else {
            e.dispType = null;
            e.dispParams = new LinkedHashMap<>();
        }

        // Content-Transfer-Encoding
        String cteVal = getHeader(e.headers, "content-transfer-encoding");
        e.cte = cteVal != null ? trimSpacesTabs(cteVal).toLowerCase() : "7bit";

        // Multipart
        if (e.type.equals("multipart")) {
            String boundary = e.ctParams.get("boundary");
            if (boundary != null) {
                e.parts = parseMultipart(e.body, boundary);
            } else {
                e.parts = new ArrayList<>();
            }
        }

        return e;
    }

    static List<Entity> parseMultipart(byte[] body, String boundary) {
        List<Entity> parts = new ArrayList<>();
        String delim = "--" + boundary;
        String closeDelim = delim + "--";

        // Split body into lines
        List<int[]> lines = new ArrayList<>(); // [contentStart, contentEnd, nextStart]
        int pos = 0;
        while (pos < body.length) {
            int lbPos = findLineBreak(body, pos, body.length);
            int contentEnd, nextPos;
            if (lbPos == -1) {
                contentEnd = body.length;
                nextPos = body.length;
            } else {
                contentEnd = lbPos;
                nextPos = lbPos + lbLen;
            }
            lines.add(new int[]{pos, contentEnd, nextPos});
            pos = nextPos;
        }

        // Find boundary lines
        List<Integer> boundaryIndices = new ArrayList<>();
        int closeIdx = -1;
        for (int i = 0; i < lines.size(); i++) {
            String lineContent = new String(body, lines.get(i)[0], lines.get(i)[1] - lines.get(i)[0],
                    java.nio.charset.StandardCharsets.US_ASCII);
            if (isCloseDelimiter(lineContent, closeDelim)) {
                boundaryIndices.add(i);
                closeIdx = i;
                break;
            } else if (isDelimiter(lineContent, delim)) {
                boundaryIndices.add(i);
            }
        }

        if (boundaryIndices.size() < 2) return parts; // Need at least 2 boundaries to have a part

        // Extract parts between consecutive boundaries
        for (int i = 0; i < boundaryIndices.size() - 1; i++) {
            int dIdx = boundaryIndices.get(i);
            int nIdx = boundaryIndices.get(i + 1);

            int partStart = lines.get(dIdx)[2]; // after delimiter line break

            int partEnd;
            if (nIdx > dIdx + 1) {
                partEnd = lines.get(nIdx - 1)[1]; // end of last content line before next boundary
            } else {
                // Empty part
                partEnd = partStart;
            }

            byte[] partBytes = Arrays.copyOfRange(body, partStart, partEnd);
            Entity part = parseEntity(partBytes, 0, partBytes.length);
            parts.add(part);
        }

        return parts;
    }

    static boolean isDelimiter(String line, String delim) {
        if (!line.startsWith(delim)) return false;
        String rest = line.substring(delim.length());
        for (int i = 0; i < rest.length(); i++) {
            if (rest.charAt(i) != ' ' && rest.charAt(i) != '\t') return false;
        }
        return true;
    }

    static boolean isCloseDelimiter(String line, String closeDelim) {
        if (!line.startsWith(closeDelim)) return false;
        String rest = line.substring(closeDelim.length());
        for (int i = 0; i < rest.length(); i++) {
            if (rest.charAt(i) != ' ' && rest.charAt(i) != '\t') return false;
        }
        return true;
    }

    static String getHeader(List<String[]> headers, String name) {
        for (String[] h : headers) {
            if (h[0].equals(name)) return h[1];
        }
        return null;
    }

    static String trimSpacesTabs(String s) {
        int start = 0, end = s.length();
        while (start < end && (s.charAt(start) == ' ' || s.charAt(start) == '\t')) start++;
        while (end > start && (s.charAt(end - 1) == ' ' || s.charAt(end - 1) == '\t')) end--;
        return s.substring(start, end);
    }

    // Parameter parsing
    static class ParamResult {
        String mainValue;
        Map<String, String> params;
    }

    static ParamResult parseParams(String value) {
        ParamResult result = new ParamResult();
        result.params = new LinkedHashMap<>();

        int i = 0;
        // Skip leading whitespace
        while (i < value.length() && (value.charAt(i) == ' ' || value.charAt(i) == '\t')) i++;

        // Read main value (token up to ; or whitespace)
        int start = i;
        while (i < value.length() && value.charAt(i) != ';' && value.charAt(i) != ' ' && value.charAt(i) != '\t') i++;
        result.mainValue = value.substring(start, i);

        // Parse parameters
        while (i < value.length()) {
            while (i < value.length() && (value.charAt(i) == ';' || value.charAt(i) == ' ' || value.charAt(i) == '\t')) i++;
            if (i >= value.length()) break;

            // Attribute name
            start = i;
            while (i < value.length() && value.charAt(i) != '=' && value.charAt(i) != ';' && value.charAt(i) != ' ' && value.charAt(i) != '\t') i++;
            String attrName = value.substring(start, i).toLowerCase();

            // Skip whitespace
            while (i < value.length() && (value.charAt(i) == ' ' || value.charAt(i) == '\t')) i++;
            if (i < value.length() && value.charAt(i) == '=') i++;
            while (i < value.length() && (value.charAt(i) == ' ' || value.charAt(i) == '\t')) i++;

            // Value
            String attrValue;
            if (i < value.length() && value.charAt(i) == '"') {
                i++; // skip "
                StringBuilder sb = new StringBuilder();
                while (i < value.length() && value.charAt(i) != '"') {
                    if (value.charAt(i) == '\\' && i + 1 < value.length()) {
                        sb.append(value.charAt(i + 1));
                        i += 2;
                    } else {
                        sb.append(value.charAt(i));
                        i++;
                    }
                }
                if (i < value.length()) i++; // skip closing "
                attrValue = sb.toString();
            } else {
                start = i;
                while (i < value.length() && value.charAt(i) != ';' && value.charAt(i) != ' ' && value.charAt(i) != '\t') i++;
                attrValue = value.substring(start, i);
            }

            result.params.put(attrName, attrValue);
        }

        return result;
    }

    // Transfer encoding
    static byte[] decodeTransfer(byte[] data, String cte) {
        switch (cte) {
            case "base64": return decodeBase64Bytes(data);
            case "quoted-printable": return decodeQP(data);
            default: return data; // 7bit, 8bit, binary
        }
    }

    static byte[] decodeBase64Bytes(byte[] data) {
        byte[] filtered = new byte[data.length];
        int len = 0;
        for (byte b : data) {
            if (b == '=') break;
            if ((b >= 'A' && b <= 'Z') || (b >= 'a' && b <= 'z') ||
                (b >= '0' && b <= '9') || b == '+' || b == '/') {
                filtered[len++] = b;
            }
        }
        int outLen = (len / 4) * 3;
        if (len % 4 == 2) outLen += 1;
        else if (len % 4 == 3) outLen += 2;
        byte[] out = new byte[outLen];
        int oi = 0;
        for (int i = 0; i + 1 < len; i += 4) {
            int remaining = Math.min(4, len - i);
            int v0 = b64val(filtered[i]);
            int v1 = b64val(filtered[i + 1]);
            out[oi++] = (byte) ((v0 << 2) | (v1 >> 4));
            if (remaining >= 3) {
                int v2 = b64val(filtered[i + 2]);
                out[oi++] = (byte) ((v1 << 4) | (v2 >> 2));
                if (remaining >= 4) {
                    int v3 = b64val(filtered[i + 3]);
                    out[oi++] = (byte) ((v2 << 6) | v3);
                }
            }
        }
        return Arrays.copyOf(out, oi);
    }

    static int b64val(byte b) {
        if (b >= 'A' && b <= 'Z') return b - 'A';
        if (b >= 'a' && b <= 'z') return b - 'a' + 26;
        if (b >= '0' && b <= '9') return b - '0' + 52;
        if (b == '+') return 62;
        if (b == '/') return 63;
        return 0;
    }

    static byte[] decodeQP(byte[] data) {
        // Split into lines
        List<byte[]> rawLines = new ArrayList<>();
        List<Boolean> hasBreak = new ArrayList<>();
        int pos = 0;
        while (pos < data.length) {
            int lbPos = findLineBreak(data, pos, data.length);
            byte[] lineContent;
            if (lbPos == -1) {
                lineContent = Arrays.copyOfRange(data, pos, data.length);
                rawLines.add(lineContent);
                hasBreak.add(false);
                break;
            } else {
                lineContent = Arrays.copyOfRange(data, pos, lbPos);
                rawLines.add(lineContent);
                hasBreak.add(true);
                pos = lbPos + lbLen;
            }
        }

        // Remove trailing spaces/tabs
        for (int i = 0; i < rawLines.size(); i++) {
            byte[] line = rawLines.get(i);
            int end = line.length;
            while (end > 0 && (line[end - 1] == ' ' || line[end - 1] == '\t')) end--;
            rawLines.set(i, Arrays.copyOf(line, end));
        }

        // Join soft-broken lines
        List<byte[]> logicalLines = new ArrayList<>();
        List<Boolean> hardBreaks = new ArrayList<>();
        int i = 0;
        while (i < rawLines.size()) {
            byte[] current = rawLines.get(i);
            boolean hb = hasBreak.get(i);

            while (current.length > 0 && current[current.length - 1] == '=' && hb && i + 1 < rawLines.size()) {
                current = Arrays.copyOf(current, current.length - 1);
                byte[] next = rawLines.get(i + 1);
                byte[] joined = new byte[current.length + next.length];
                System.arraycopy(current, 0, joined, 0, current.length);
                System.arraycopy(next, 0, joined, current.length, next.length);
                current = joined;
                i++;
                hb = hasBreak.get(i);
            }

            logicalLines.add(current);
            hardBreaks.add(hb);
            i++;
        }

        // Process =XY
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        for (int li = 0; li < logicalLines.size(); li++) {
            byte[] line = logicalLines.get(li);
            int j = 0;
            while (j < line.length) {
                if (line[j] == '=' && j + 2 < line.length && isHex(line[j + 1]) && isHex(line[j + 2])) {
                    out.write(hexVal(line[j + 1]) * 16 + hexVal(line[j + 2]));
                    j += 3;
                } else {
                    out.write(line[j]);
                    j++;
                }
            }
            if (hardBreaks.get(li)) {
                if (lbLen == 2) {
                    out.write('\r');
                    out.write('\n');
                } else {
                    out.write('\n');
                }
            }
        }
        return out.toByteArray();
    }

    static boolean isHex(byte b) {
        return (b >= '0' && b <= '9') || (b >= 'a' && b <= 'f') || (b >= 'A' && b <= 'F');
    }

    static int hexVal(byte b) {
        if (b >= '0' && b <= '9') return b - '0';
        if (b >= 'a' && b <= 'f') return b - 'a' + 10;
        if (b >= 'A' && b <= 'F') return b - 'A' + 10;
        return 0;
    }

    // Charset decoding
    static String decodeCharset(byte[] data, String charset) {
        charset = charset.toLowerCase();
        switch (charset) {
            case "us-ascii":
            case "utf-8":
                return new String(data, java.nio.charset.StandardCharsets.UTF_8);
            case "iso-8859-1":
                return new String(data, java.nio.charset.StandardCharsets.ISO_8859_1);
            case "windows-1252":
                return decodeWindows1252(data);
            default:
                return new String(data, java.nio.charset.StandardCharsets.ISO_8859_1);
        }
    }

    static final int[] CP1252_MAP = new int[32]; // 0x80-0x9F
    static {
        int[] map = {
            0x20AC, 0x0081, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021,
            0x02C6, 0x2030, 0x0160, 0x2039, 0x0152, 0x008D, 0x017D, 0x008F,
            0x0090, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014,
            0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0x009D, 0x017E, 0x0178
        };
        System.arraycopy(map, 0, CP1252_MAP, 0, 32);
    }

    static String decodeWindows1252(byte[] data) {
        StringBuilder sb = new StringBuilder(data.length);
        for (byte b : data) {
            int unsigned = b & 0xFF;
            if (unsigned >= 0x80 && unsigned <= 0x9F) {
                sb.append((char) CP1252_MAP[unsigned - 0x80]);
            } else {
                sb.append((char) unsigned);
            }
        }
        return sb.toString();
    }

    // RFC 2047 encoded-word decoding
    static String decodeEncodedWords(String input) {
        Pattern p = Pattern.compile("=\\?([^? \\t]+)\\?([BbQq])\\?([^? \\t]*)\\?=");
        Matcher m = p.matcher(input);

        List<int[]> matchPos = new ArrayList<>();
        List<String> matchCharsets = new ArrayList<>();
        List<byte[]> matchBytes = new ArrayList<>();

        while (m.find()) {
            matchPos.add(new int[]{m.start(), m.end()});
            String cs = m.group(1);
            int starIdx = cs.indexOf('*');
            if (starIdx >= 0) cs = cs.substring(0, starIdx);
            matchCharsets.add(cs.toLowerCase());
            String enc = m.group(2).toUpperCase();
            String text = m.group(3);
            if (enc.equals("B")) {
                matchBytes.add(decodeBase64Bytes(text.getBytes(java.nio.charset.StandardCharsets.US_ASCII)));
            } else {
                matchBytes.add(decodeQPEW(text));
            }
        }

        if (matchPos.isEmpty()) return input;

        // Group into runs of adjacent same-charset encoded-words
        List<List<Integer>> runs = new ArrayList<>();
        List<Integer> currentRun = new ArrayList<>();
        currentRun.add(0);

        for (int i = 1; i < matchPos.size(); i++) {
            String between = input.substring(matchPos.get(i - 1)[1], matchPos.get(i)[0]);
            boolean adjacent = between.matches("[ \\t]*");
            if (adjacent && matchCharsets.get(i).equals(matchCharsets.get(i - 1))) {
                currentRun.add(i);
            } else {
                runs.add(currentRun);
                currentRun = new ArrayList<>();
                currentRun.add(i);
            }
        }
        runs.add(currentRun);

        // Build output
        StringBuilder out = new StringBuilder();
        int pos = 0;

        for (int r = 0; r < runs.size(); r++) {
            List<Integer> run = runs.get(r);
            int runStart = matchPos.get(run.get(0))[0];
            int runEnd = matchPos.get(run.get(run.size() - 1))[1];

            String gap = input.substring(pos, runStart);

            if (r > 0) {
                // Check if gap is only whitespace (adjacent runs)
                if (gap.matches("[ \\t]*")) {
                    // Remove whitespace between adjacent encoded-words
                } else {
                    out.append(gap);
                }
            } else {
                out.append(gap);
            }

            // Decode run
            ByteArrayOutputStream runBytes = new ByteArrayOutputStream();
            for (int idx : run) {
                byte[] b = matchBytes.get(idx);
                runBytes.write(b, 0, b.length);
            }
            out.append(decodeCharset(runBytes.toByteArray(), matchCharsets.get(run.get(0))));

            pos = runEnd;
        }

        out.append(input, pos, input.length());
        return out.toString();
    }

    static byte[] decodeQPEW(String text) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        int i = 0;
        while (i < text.length()) {
            char c = text.charAt(i);
            if (c == '_') {
                out.write(0x20);
                i++;
            } else if (c == '=' && i + 2 < text.length() && isHex((byte) text.charAt(i + 1)) && isHex((byte) text.charAt(i + 2))) {
                out.write(hexVal((byte) text.charAt(i + 1)) * 16 + hexVal((byte) text.charAt(i + 2)));
                i += 3;
            } else {
                out.write(c);
                i++;
            }
        }
        return out.toByteArray();
    }

    // RFC 2231 file name decoding
    static String getFileName(Entity e) {
        // Check Content-Disposition filename
        String name = tryRFC2231(e.dispParams, "filename");
        if (name != null) return name;

        name = tryPlainParam(e.dispParams, "filename");
        if (name != null) return decodeEncodedWords(name);

        // Check Content-Type name
        name = tryRFC2231(e.ctParams, "name");
        if (name != null) return name;

        name = tryPlainParam(e.ctParams, "name");
        if (name != null) return decodeEncodedWords(name);

        return null;
    }

    static String tryPlainParam(Map<String, String> params, String attr) {
        // Check if RFC 2231 form exists (attr* or attr*N or attr*N*)
        if (params.containsKey(attr + "*")) return null;
        for (String key : params.keySet()) {
            if (key.startsWith(attr + "*") && key.length() > attr.length() + 1) {
                String suffix = key.substring(attr.length() + 1);
                // Check if suffix is a number or number*
                String numPart = suffix.endsWith("*") ? suffix.substring(0, suffix.length() - 1) : suffix;
                try {
                    Integer.parseInt(numPart);
                    return null; // RFC 2231 form exists
                } catch (NumberFormatException ex) {
                    // Not a segment number, ignore
                }
            }
        }
        return params.get(attr);
    }

    static String tryRFC2231(Map<String, String> params, String attr) {
        // Check for attr* (single segment)
        boolean hasSingle = params.containsKey(attr + "*");

        // Find continuation segments
        Map<Integer, String> literalSegs = new TreeMap<>();
        Map<Integer, String> encodedSegs = new TreeMap<>();

        for (String key : params.keySet()) {
            if (key.startsWith(attr + "*")) {
                String suffix = key.substring(attr.length() + 1);
                if (suffix.equals("*")) continue; // single segment, handled separately
                boolean isEncoded = suffix.endsWith("*");
                String numStr = isEncoded ? suffix.substring(0, suffix.length() - 1) : suffix;
                try {
                    int num = Integer.parseInt(numStr);
                    if (isEncoded) {
                        encodedSegs.put(num, params.get(key));
                    } else {
                        literalSegs.put(num, params.get(key));
                    }
                } catch (NumberFormatException ex) {
                    // ignore
                }
            }
        }

        if (!hasSingle && literalSegs.isEmpty() && encodedSegs.isEmpty()) return null;

        String charset = "us-ascii";
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();

        if (hasSingle && literalSegs.isEmpty() && encodedSegs.isEmpty()) {
            // Single segment: charset'language'value (percent-encoded)
            byte[] decoded = percentDecode(params.get(attr + "*"));
            // Extract charset prefix
            String decodedStr = new String(decoded, java.nio.charset.StandardCharsets.ISO_8859_1);
            int q1 = decodedStr.indexOf('\'');
            int q2 = decodedStr.indexOf('\'', q1 + 1);
            if (q1 >= 0 && q2 >= 0) {
                charset = decodedStr.substring(0, q1);
                bytes.write(decoded, q2 + 1, decoded.length - q2 - 1);
            } else {
                bytes.write(decoded);
            }
        } else {
            // Continuation segments
            int maxNum = -1;
            if (!literalSegs.isEmpty()) maxNum = Math.max(maxNum, Collections.max(literalSegs.keySet()));
            if (!encodedSegs.isEmpty()) maxNum = Math.max(maxNum, Collections.max(encodedSegs.keySet()));

            // Get charset from first encoded segment
            if (encodedSegs.containsKey(0)) {
                byte[] decoded0 = percentDecode(encodedSegs.get(0));
                String decodedStr = new String(decoded0, java.nio.charset.StandardCharsets.ISO_8859_1);
                int q1 = decodedStr.indexOf('\'');
                int q2 = decodedStr.indexOf('\'', q1 + 1);
                if (q1 >= 0 && q2 >= 0) {
                    charset = decodedStr.substring(0, q1);
                    bytes.write(decoded0, q2 + 1, decoded0.length - q2 - 1);
                } else {
                    bytes.write(decoded0);
                }
            }

            for (int i = 0; i <= maxNum; i++) {
                if (i == 0 && encodedSegs.containsKey(0)) continue; // already handled
                if (encodedSegs.containsKey(i)) {
                    bytes.write(percentDecode(encodedSegs.get(i)));
                } else if (literalSegs.containsKey(i)) {
                    bytes.write(literalSegs.get(i).getBytes(java.nio.charset.StandardCharsets.ISO_8859_1));
                }
            }
        }

        return decodeCharset(bytes.toByteArray(), charset);
    }

    static byte[] percentDecode(String s) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        int i = 0;
        while (i < s.length()) {
            if (s.charAt(i) == '%' && i + 2 < s.length() && isHex((byte) s.charAt(i + 1)) && isHex((byte) s.charAt(i + 2))) {
                out.write(hexVal((byte) s.charAt(i + 1)) * 16 + hexVal((byte) s.charAt(i + 2)));
                i += 3;
            } else {
                out.write(s.charAt(i));
                i++;
            }
        }
        return out.toByteArray();
    }

    // Output
    static void printEntity(Entity e, int indent) {
        String prefix = "  ".repeat(indent);

        if (e.type.equals("multipart")) {
            System.out.println(prefix + "multipart/" + e.subtype + " parts=" + e.parts.size());
            for (Entity part : e.parts) {
                printEntity(part, indent + 1);
            }
        } else if (e.type.equals("text") && !"attachment".equals(e.dispType)) {
            // Text part
            byte[] decoded = decodeTransfer(e.body, e.cte);
            String charset = e.ctParams.getOrDefault("charset", "us-ascii").toLowerCase();
            String text = decodeCharset(decoded, charset);
            // Replace CRLF and lone CR with LF
            text = text.replace("\r\n", "\n").replace("\r", "\n");

            System.out.println(prefix + "text/" + e.subtype + " charset=" + charset + " cte=" + e.cte + " chars=" + text.codePointCount(0, text.length()));
            System.out.println(prefix + "  " + toQuotedString(text));
        } else {
            // Other part
            byte[] decoded = decodeTransfer(e.body, e.cte);
            CRC32 crc = new CRC32();
            crc.update(decoded);

            String disp = e.dispType != null ? e.dispType : "-";
            String name = getFileName(e);
            String nameStr = name != null ? toQuotedString(name) : "-";

            System.out.println(prefix + e.type + "/" + e.subtype + " cte=" + e.cte + " disposition=" + disp + " name=" + nameStr + " size=" + decoded.length + " crc32=" + String.format("%08x", crc.getValue()));
        }
    }

    static String toQuotedString(String s) {
        StringBuilder sb = new StringBuilder("\"");
        for (int i = 0; i < s.length(); ) {
            int cp = s.codePointAt(i);
            if (cp == '\\') sb.append("\\\\");
            else if (cp == '"') sb.append("\\\"");
            else if (cp == '\n') sb.append("\\n");
            else if (cp == '\t') sb.append("\\t");
            else if (cp < 0x20 || (cp >= 0x7F && cp <= 0x9F)) {
                sb.append(String.format("\\u%04x", cp));
            } else {
                sb.appendCodePoint(cp);
            }
            i += Character.charCount(cp);
        }
        sb.append("\"");
        return sb.toString();
    }
}

import * as fs from 'fs';
import * as path from 'path';

// ============ CRC-32 ============
function crc32(data: Buffer): number {
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < data.length; i++) {
    crc ^= data[i];
    for (let j = 0; j < 8; j++) {
      if (crc & 1) crc = (crc >>> 1) ^ 0xEDB88320;
      else crc = crc >>> 1;
    }
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

// ============ Charset Decoding ============
const CP1252_HIGH: number[] = [
  0x20AC, 0x0081, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021,
  0x02C6, 0x2030, 0x0160, 0x2039, 0x0152, 0x008D, 0x017D, 0x008F,
  0x0090, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014,
  0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0x009D, 0x017E, 0x0178
];

function decodeCharsetBytes(bytes: Buffer, charset: string): string {
  charset = charset.toLowerCase().trim();
  if (charset === 'us-ascii' || charset === 'ascii') {
    let s = '';
    for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
    return s;
  }
  if (charset === 'utf-8' || charset === 'utf8') {
    return new TextDecoder('utf-8').decode(bytes);
  }
  if (charset === 'iso-8859-1' || charset === 'latin1' || charset === 'iso8859-1') {
    let s = '';
    for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
    return s;
  }
  if (charset === 'windows-1252' || charset === 'cp1252' || charset === 'x-unknown-8859-1') {
    let s = '';
    for (let i = 0; i < bytes.length; i++) {
      const b = bytes[i];
      if (b >= 0x80 && b <= 0x9F) s += String.fromCharCode(CP1252_HIGH[b - 0x80]);
      else s += String.fromCharCode(b);
    }
    return s;
  }
  // Fallback: try utf-8
  return new TextDecoder('utf-8').decode(bytes);
}

// ============ Base64 ============
const B64_CHARS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const B64_LOOKUP: number[] = new Array(128).fill(-1);
for (let i = 0; i < B64_CHARS.length; i++) B64_LOOKUP[B64_CHARS.charCodeAt(i)] = i;

function base64Decode(input: Buffer): Buffer {
  const vals: number[] = [];
  for (let i = 0; i < input.length; i++) {
    const b = input[i];
    if (b === 0x3D) break; // '=' padding, stop
    if (b < 128) {
      const v = B64_LOOKUP[b];
      if (v >= 0) vals.push(v);
    }
  }
  const result: number[] = [];
  for (let i = 0; i < vals.length; i += 4) {
    const n = Math.min(4, vals.length - i);
    if (n >= 2) result.push((vals[i] << 2) | (vals[i + 1] >> 4));
    if (n >= 3) result.push(((vals[i + 1] & 0x0F) << 4) | (vals[i + 2] >> 2));
    if (n >= 4) result.push(((vals[i + 2] & 0x03) << 6) | vals[i + 3]);
  }
  return Buffer.from(result);
}

// ============ Quoted-Printable ============
function isHexDigit(b: number): boolean {
  return (b >= 0x30 && b <= 0x39) || (b >= 0x41 && b <= 0x46) || (b >= 0x61 && b <= 0x66);
}
function hexVal(b: number): number {
  if (b >= 0x30 && b <= 0x39) return b - 0x30;
  if (b >= 0x41 && b <= 0x46) return b - 0x37;
  return b - 0x57; // 0x61-0x66
}

function decodeQP(input: Buffer, lineBreak: string): Buffer {
  const lbLen = lineBreak.length;
  // Split into lines
  const lines: Buffer[] = [];
  let start = 0;
  let i = 0;
  while (i < input.length) {
    if (i + lbLen <= input.length && input.slice(i, i + lbLen).equals(Buffer.from(lineBreak, 'ascii'))) {
      lines.push(input.slice(start, i));
      start = i + lbLen;
      i += lbLen;
    } else {
      i++;
    }
  }
  lines.push(input.slice(start));

  // Remove trailing spaces/tabs
  for (let k = 0; k < lines.length; k++) {
    let end = lines[k].length;
    while (end > 0 && (lines[k][end - 1] === 0x20 || lines[k][end - 1] === 0x09)) end--;
    lines[k] = lines[k].slice(0, end);
  }

  // Process soft line breaks
  const hardLines: Buffer[] = [];
  i = 0;
  while (i < lines.length) {
    let current = lines[i];
    while (current.length > 0 && current[current.length - 1] === 0x3D && i + 1 < lines.length) {
      current = Buffer.concat([current.slice(0, -1), lines[i + 1]]);
      i++;
    }
    hardLines.push(current);
    i++;
  }

  // Decode =XY and join with \n
  const result: number[] = [];
  for (let k = 0; k < hardLines.length; k++) {
    const line = hardLines[k];
    let j = 0;
    while (j < line.length) {
      if (line[j] === 0x3D && j + 2 < line.length && isHexDigit(line[j + 1]) && isHexDigit(line[j + 2])) {
        result.push(hexVal(line[j + 1]) * 16 + hexVal(line[j + 2]));
        j += 3;
      } else {
        result.push(line[j]);
        j++;
      }
    }
    if (k < hardLines.length - 1) result.push(0x0A);
  }

  return Buffer.from(result);
}

// ============ Transfer Encoding Decode ============
function decodeTransfer(input: Buffer, encoding: string, lineBreak: string): Buffer {
  encoding = encoding.toLowerCase();
  if (encoding === 'base64') return base64Decode(input);
  if (encoding === 'quoted-printable') return decodeQP(input, lineBreak);
  return input; // 7bit, 8bit, binary
}

// ============ RFC 2047 Encoded Words ============
function normalizeCharsetForComparison(cs: string): string {
  // Remove *language suffix, lowercase
  const starIdx = cs.indexOf('*');
  if (starIdx >= 0) return cs.slice(0, starIdx).toLowerCase();
  return cs.toLowerCase();
}

function decodeEncodedWordBytes(charset: string, encoding: string, text: string): Buffer {
  if (encoding === 'B' || encoding === 'b') {
    return base64Decode(Buffer.from(text, 'ascii'));
  } else {
    // Q encoding
    const bytes: number[] = [];
    for (let i = 0; i < text.length; i++) {
      const c = text.charCodeAt(i);
      if (c === 0x5F) { // _
        bytes.push(0x20);
      } else if (c === 0x3D && i + 2 < text.length) { // =XY
        const h1 = text.charCodeAt(i + 1);
        const h2 = text.charCodeAt(i + 2);
        if (isHexDigit(h1) && isHexDigit(h2)) {
          bytes.push(hexVal(h1) * 16 + hexVal(h2));
          i += 2;
        } else {
          bytes.push(c);
        }
      } else {
        bytes.push(c);
      }
    }
    return Buffer.from(bytes);
  }
}

function decodeEncodedWords(s: string): string {
  // Find all encoded-word matches
  interface Match { start: number; end: number; charset: string; encoding: string; text: string; }
  const matches: Match[] = [];
  let i = 0;
  while (i < s.length) {
    if (s[i] === '=' && i + 1 < s.length && s[i + 1] === '?') {
      let j = i + 2;
      // charset: one or more chars other than ?, space, tab
      let cs = '';
      while (j < s.length && s[j] !== '?' && s[j] !== ' ' && s[j] !== '\t') { cs += s[j]; j++; }
      if (j < s.length && s[j] === '?' && cs.length > 0) {
        j++;
        // encoding: B, b, Q, q
        if (j < s.length && 'BbQq'.includes(s[j])) {
          const enc = s[j];
          j++;
          if (j < s.length && s[j] === '?') {
            j++;
            // encoded-text: zero or more chars other than ?, space, tab
            let txt = '';
            while (j < s.length && s[j] !== '?' && s[j] !== ' ' && s[j] !== '\t') { txt += s[j]; j++; }
            if (j < s.length && s[j] === '?' && j + 1 < s.length && s[j + 1] === '=') {
              j++; // skip ?
              j++; // skip =
              matches.push({ start: i, end: j, charset: cs, encoding: enc, text: txt });
              i = j;
              continue;
            }
          }
        }
      }
    }
    i++;
  }

  if (matches.length === 0) return s;

  // Group adjacent encoded words with same charset
  interface Group { matches: Match[]; }
  const groups: Group[] = [];
  let curGroup: Match[] = [matches[0]];
  for (let k = 1; k < matches.length; k++) {
    const prev = curGroup[curGroup.length - 1];
    const curr = matches[k];
    const between = s.slice(prev.end, curr.start);
    if (/^[ \t]*$/.test(between) && normalizeCharsetForComparison(prev.charset) === normalizeCharsetForComparison(curr.charset)) {
      curGroup.push(curr);
    } else {
      groups.push({ matches: curGroup });
      curGroup = [curr];
    }
  }
  groups.push({ matches: curGroup });

  // Build output
  let result = '';
  let pos = 0;
  for (const group of groups) {
    // Add text before this group
    result += s.slice(pos, group.matches[0].start);
    // Decode the group
    const charset = group.matches[0].charset;
    // Remove *language for charset
    let cs = charset;
    const starIdx = cs.indexOf('*');
    if (starIdx >= 0) cs = cs.slice(0, starIdx);

    const allBytes: number[] = [];
    for (const m of group.matches) {
      const bytes = decodeEncodedWordBytes(cs, m.encoding, m.text);
      for (let b = 0; b < bytes.length; b++) allBytes.push(bytes[b]);
    }
    result += decodeCharsetBytes(Buffer.from(allBytes), cs);
    pos = group.matches[group.matches.length - 1].end;
  }
  result += s.slice(pos);

  return result;
}

// ============ Parameter Parsing ============
interface Param { name: string; value: string; }

function parseParams(s: string): Param[] {
  // s is the part after type/subtype (or disposition type), starting with ;
  // Split by ; respecting quotes
  const params: Param[] = [];
  let i = 0;
  while (i < s.length) {
    // Skip spaces/tabs
    while (i < s.length && (s[i] === ' ' || s[i] === '\t')) i++;
    if (i >= s.length) break;
    // Read attribute name (up to = or ; or space or tab)
    let name = '';
    while (i < s.length && s[i] !== '=' && s[i] !== ';' && s[i] !== ' ' && s[i] !== '\t') {
      name += s[i]; i++;
    }
    if (i >= s.length || s[i] !== '=') {
      // Skip to next ;
      while (i < s.length && s[i] !== ';') i++;
      if (i < s.length) i++; // skip ;
      continue;
    }
    i++; // skip =
    // Skip spaces/tabs
    while (i < s.length && (s[i] === ' ' || s[i] === '\t')) i++;
    // Read value
    let value = '';
    if (i < s.length && s[i] === '"') {
      // Quoted string
      i++; // skip opening "
      while (i < s.length && s[i] !== '"') {
        if (s[i] === '\\' && i + 1 < s.length) {
          value += s[i + 1];
          i += 2;
        } else {
          value += s[i];
          i++;
        }
      }
      if (i < s.length) i++; // skip closing "
    } else {
      // Token: up to ;, space, tab
      while (i < s.length && s[i] !== ';' && s[i] !== ' ' && s[i] !== '\t') {
        value += s[i]; i++;
      }
    }
    params.push({ name: name.toLowerCase(), value });
    // Skip to next ;
    while (i < s.length && s[i] !== ';') i++;
    if (i < s.length) i++; // skip ;
  }
  return params;
}

// ============ RFC 2231 Decoding ============
function percentDecode(s: string): Buffer {
  const bytes: number[] = [];
  let i = 0;
  while (i < s.length) {
    if (s[i] === '%' && i + 2 < s.length && isHexDigit(s.charCodeAt(i + 1)) && isHexDigit(s.charCodeAt(i + 2))) {
      bytes.push(hexVal(s.charCodeAt(i + 1)) * 16 + hexVal(s.charCodeAt(i + 2)));
      i += 3;
    } else {
      bytes.push(s.charCodeAt(i));
      i++;
    }
  }
  return Buffer.from(bytes);
}

function decodeRFC2231(params: Param[], attr: string): string | null {
  // Check for single form: attr*=charset'lang'value
  const single = params.find(p => p.name === attr + '*');
  if (single) {
    const val = single.value;
    const firstQuote = val.indexOf("'");
    const secondQuote = val.indexOf("'", firstQuote + 1);
    if (firstQuote >= 0 && secondQuote >= 0) {
      const cs = val.slice(0, firstQuote);
      // lang = val.slice(firstQuote+1, secondQuote); // ignored
      const encoded = val.slice(secondQuote + 1);
      const bytes = percentDecode(encoded);
      return decodeCharsetBytes(bytes, cs || 'us-ascii');
    }
    return decodeCharsetBytes(percentDecode(val), 'us-ascii');
  }

  // Check for continuation segments
  const segments: { num: number; value: string; percentEncoded: boolean }[] = [];
  for (const p of params) {
    if (p.name.startsWith(attr + '*')) {
      const rest = p.name.slice(attr.length + 1);
      if (rest === '') continue; // handled above
      const lastChar = rest[rest.length - 1];
      if (lastChar === '*') {
        const numStr = rest.slice(0, -1);
        if (/^\d+$/.test(numStr)) {
          segments.push({ num: parseInt(numStr), value: p.value, percentEncoded: true });
        }
      } else if (/^\d+$/.test(rest)) {
        segments.push({ num: parseInt(rest), value: p.value, percentEncoded: false });
      }
    }
  }

  if (segments.length === 0) return null;

  segments.sort((a, b) => a.num - b.num);

  // Determine charset
  let cs = 'us-ascii';
  let allBytes: number[] = [];

  const hasPercent = segments.some(s => s.percentEncoded);

  if (hasPercent) {
    // Segment 0 is percent-encoded and starts with charset'lang'
    const seg0 = segments.find(s => s.num === 0);
    if (seg0 && seg0.percentEncoded) {
      const val = seg0.value;
      const fq = val.indexOf("'");
      const sq = val.indexOf("'", fq + 1);
      if (fq >= 0 && sq >= 0) {
        cs = val.slice(0, fq);
        const encodedRest = val.slice(sq + 1);
        const b = percentDecode(encodedRest);
        for (let i = 0; i < b.length; i++) allBytes.push(b[i]);
      } else {
        const b = percentDecode(val);
        for (let i = 0; i < b.length; i++) allBytes.push(b[i]);
      }
    }
    for (const seg of segments) {
      if (seg.num === 0) continue;
      const b = percentDecode(seg.value);
      for (let i = 0; i < b.length; i++) allBytes.push(b[i]);
    }
  } else {
    // All literal
    for (const seg of segments) {
      for (let i = 0; i < seg.value.length; i++) allBytes.push(seg.value.charCodeAt(i));
    }
  }

  return decodeCharsetBytes(Buffer.from(allBytes), cs);
}

function getFileName(cdParams: Param[] | null, ctParams: Param[] | null): string | null {
  // Priority: CD filename RFC2231, CD filename plain, CT name RFC2231, CT name plain

  if (cdParams) {
    const rfc2231 = decodeRFC2231(cdParams, 'filename');
    if (rfc2231 !== null) return rfc2231;
    const plain = cdParams.find(p => p.name === 'filename');
    if (plain) return decodeEncodedWords(plain.value);
  }

  if (ctParams) {
    const rfc2231 = decodeRFC2231(ctParams, 'name');
    if (rfc2231 !== null) return rfc2231;
    const plain = ctParams.find(p => p.name === 'name');
    if (plain) return decodeEncodedWords(plain.value);
  }

  return null;
}

