import * as fs from 'fs';
import * as path from 'path';

// CRC-32 (zlib/PNG)
function crc32(data: Buffer): number {
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < data.length; i++) {
    crc ^= data[i];
    for (let j = 0; j < 8; j++) {
      if (crc & 1) crc = (crc >>> 1) ^ 0xEDB88320;
      else crc >>>= 1;
    }
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

// CP1252 mapping for bytes 0x80-0x9F
const CP1252: number[] = [
  0x20AC, 0x0081, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021,
  0x02C6, 0x2030, 0x0160, 0x2039, 0x0152, 0x008D, 0x017D, 0x008F,
  0x0090, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014,
  0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0x009D, 0x017E, 0x0178
];

function decodeCharset(bytes: Buffer, charset: string): string {
  const cs = charset.toLowerCase().trim();
  if (cs === 'utf-8' || cs === 'utf8') {
    return new TextDecoder('utf-8').decode(bytes);
  }
  if (cs === 'iso-8859-1' || cs === 'latin1' || cs === 'iso8859-1') {
    let s = '';
    for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
    return s;
  }
  if (cs === 'windows-1252' || cs === 'cp1252') {
    let s = '';
    for (let i = 0; i < bytes.length; i++) {
      const b = bytes[i];
      if (b >= 0x80 && b <= 0x9F) s += String.fromCharCode(CP1252[b - 0x80]);
      else s += String.fromCharCode(b);
    }
    return s;
  }
  // us-ascii or unknown: map each byte to code point U+00XY
  let s = '';
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
  return s;
}

// Base64
const B64ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const B64LOOKUP = new Map<number, number>();
for (let i = 0; i < B64ALPHABET.length; i++) {
  B64LOOKUP.set(B64ALPHABET.charCodeAt(i), i);
}

function base64Decode(input: Buffer): Buffer {
  const vals: number[] = [];
  for (let i = 0; i < input.length; i++) {
    const b = input[i];
    if (b === 0x3D) break;
    const v = B64LOOKUP.get(b);
    if (v !== undefined) vals.push(v);
  }
  const out: number[] = [];
  for (let i = 0; i + 1 < vals.length; i += 4) {
    const n = Math.min(4, vals.length - i);
    if (n >= 2) out.push((vals[i] << 2) | (vals[i + 1] >> 4));
    if (n >= 3) out.push(((vals[i + 1] & 0x0F) << 4) | (vals[i + 2] >> 2));
    if (n >= 4) out.push(((vals[i + 2] & 0x03) << 6) | vals[i + 3]);
  }
  return Buffer.from(out);
}

// Hex helpers
function isHex(c: number): boolean {
  return (c >= 0x30 && c <= 0x39) || (c >= 0x41 && c <= 0x46) || (c >= 0x61 && c <= 0x66);
}
function hexVal(c: number): number {
  if (c <= 0x39) return c - 0x30;
  if (c <= 0x46) return c - 0x37;
  return c - 0x57;
}

// Quoted-Printable
function qpDecode(input: Buffer, lb: string): Buffer {
  const lbBuf = Buffer.from(lb);
  const lbLen = lbBuf.length;

  // Split into lines
  const lines: Buffer[] = [];
  let pos = 0;
  while (pos < input.length) {
    let end = pos;
    while (end < input.length) {
      if (end + lbLen <= input.length && input.slice(end, end + lbLen).equals(lbBuf)) break;
      end++;
    }
    lines.push(input.slice(pos, end));
    if (end + lbLen <= input.length) {
      pos = end + lbLen;
    } else {
      pos = end;
      break;
    }
  }

  // Step 1: Remove trailing spaces/tabs
  for (let i = 0; i < lines.length; i++) {
    let end = lines[i].length;
    while (end > 0 && (lines[i][end - 1] === 0x20 || lines[i][end - 1] === 0x09)) end--;
    lines[i] = lines[i].slice(0, end);
  }

  // Step 2: Join soft line breaks
  const hardLines: Buffer[] = [];
  let i = 0;
  while (i < lines.length) {
    let cur = lines[i];
    while (cur.length > 0 && cur[cur.length - 1] === 0x3D && i + 1 < lines.length) {
      cur = Buffer.concat([cur.slice(0, -1), lines[i + 1]]);
      i++;
    }
    hardLines.push(cur);
    i++;
  }

  // Step 3: Decode =XY and join with LF
  const out: number[] = [];
  for (let k = 0; k < hardLines.length; k++) {
    const line = hardLines[k];
    let j = 0;
    while (j < line.length) {
      if (line[j] === 0x3D && j + 2 < line.length && isHex(line[j + 1]) && isHex(line[j + 2])) {
        out.push(hexVal(line[j + 1]) * 16 + hexVal(line[j + 2]));
        j += 3;
      } else {
        out.push(line[j]);
        j++;
      }
    }
    if (k < hardLines.length - 1) out.push(0x0A);
  }

  return Buffer.from(out);
}

// Transfer encoding decode
function decodeTE(input: Buffer, encoding: string, lb: string): Buffer {
  const enc = encoding.toLowerCase();
  if (enc === 'base64') return base64Decode(input);
  if (enc === 'quoted-printable') return qpDecode(input, lb);
  return input;
}

// RFC 2047 encoded words
function decodeEncodedWords(s: string): string {
  interface EW { start: number; end: number; charset: string; encoding: string; text: string; }
  const matches: EW[] = [];
  let i = 0;
  while (i < s.length) {
    if (s[i] === '=' && i + 1 < s.length && s[i + 1] === '?') {
      let j = i + 2;
      let cs = '';
      while (j < s.length && s[j] !== '?' && s[j] !== ' ' && s[j] !== '\t') { cs += s[j]; j++; }
      if (cs.length > 0 && j < s.length && s[j] === '?') {
        j++;
        if (j < s.length && 'BbQq'.includes(s[j])) {
          const enc = s[j];
          j++;
          if (j < s.length && s[j] === '?') {
            j++;
            let txt = '';
            while (j < s.length && s[j] !== '?' && s[j] !== ' ' && s[j] !== '\t') { txt += s[j]; j++; }
            if (j < s.length && s[j] === '?' && j + 1 < s.length && s[j + 1] === '=') {
              j += 2;
              matches.push({ start: i, end: j, charset: cs, encoding: enc, text: txt });
              i = j;
              continue;
            }
          }
        }
      }
    }
    i++;
  }

  if (matches.length === 0) return s;

  function normCS(cs: string): string {
    const star = cs.indexOf('*');
    return (star >= 0 ? cs.slice(0, star) : cs).toLowerCase();
  }

  // Group adjacent encoded words with same charset
  const groups: EW[][] = [];
  let cur: EW[] = [matches[0]];
  for (let k = 1; k < matches.length; k++) {
    const prev = cur[cur.length - 1];
    const between = s.slice(prev.end, matches[k].start);
    if (/^[ \t]*$/.test(between) && normCS(prev.charset) === normCS(matches[k].charset)) {
      cur.push(matches[k]);
    } else {
      groups.push(cur);
      cur = [matches[k]];
    }
  }
  groups.push(cur);

  let result = '';
  let pos = 0;
  for (const g of groups) {
    result += s.slice(pos, g[0].start);
    const cs = normCS(g[0].charset);
    const allBytes: number[] = [];
    for (const m of g) {
      if (m.encoding === 'B' || m.encoding === 'b') {
        const b = base64Decode(Buffer.from(m.text, 'ascii'));
        for (let x = 0; x < b.length; x++) allBytes.push(b[x]);
      } else {
        for (let x = 0; x < m.text.length; x++) {
          const c = m.text.charCodeAt(x);
          if (c === 0x5F) { allBytes.push(0x20); }
          else if (c === 0x3D && x + 2 < m.text.length && isHex(m.text.charCodeAt(x + 1)) && isHex(m.text.charCodeAt(x + 2))) {
            allBytes.push(hexVal(m.text.charCodeAt(x + 1)) * 16 + hexVal(m.text.charCodeAt(x + 2)));
            x += 2;
          } else {
            allBytes.push(c);
          }
        }
      }
    }
    result += decodeCharset(Buffer.from(allBytes), cs);
    pos = g[g.length - 1].end;
  }
  result += s.slice(pos);
  return result;
}

// Parameter parsing
interface Param { name: string; value: string; }

function parseParams(s: string): Param[] {
  const params: Param[] = [];
  let i = 0;
  while (i < s.length) {
    while (i < s.length && (s[i] === ' ' || s[i] === '\t')) i++;
    if (i >= s.length) break;
    if (s[i] === ';') { i++; continue; }
    let name = '';
    while (i < s.length && s[i] !== '=' && s[i] !== ';' && s[i] !== ' ' && s[i] !== '\t') {
      name += s[i]; i++;
    }
    if (i >= s.length || s[i] !== '=') {
      while (i < s.length && s[i] !== ';') i++;
      if (i < s.length) i++;
      continue;
    }
    i++;
    while (i < s.length && (s[i] === ' ' || s[i] === '\t')) i++;
    let value = '';
    if (i < s.length && s[i] === '"') {
      i++;
      while (i < s.length && s[i] !== '"') {
        if (s[i] === '\\' && i + 1 < s.length) {
          value += s[i + 1]; i += 2;
        } else {
          value += s[i]; i++;
        }
      }
      if (i < s.length) i++;
    } else {
      while (i < s.length && s[i] !== ';' && s[i] !== ' ' && s[i] !== '\t') {
        value += s[i]; i++;
      }
    }
    params.push({ name: name.toLowerCase(), value });
    while (i < s.length && s[i] !== ';') i++;
    if (i < s.length) i++;
  }
  return params;
}

// RFC 2231
function percentDecode(s: string): Buffer {
  const bytes: number[] = [];
  let i = 0;
  while (i < s.length) {
    if (s[i] === '%' && i + 2 < s.length && isHex(s.charCodeAt(i + 1)) && isHex(s.charCodeAt(i + 2))) {
      bytes.push(hexVal(s.charCodeAt(i + 1)) * 16 + hexVal(s.charCodeAt(i + 2)));
      i += 3;
    } else {
      bytes.push(s.charCodeAt(i));
      i++;
    }
  }
  return Buffer.from(bytes);
}

function decodeRFC2231(params: Param[], attr: string): string | null {
  // Single form: attr*=charset'lang'value
  const single = params.find(p => p.name === attr + '*');
  if (single) {
    const val = single.value;
    const q1 = val.indexOf("'");
    const q2 = q1 >= 0 ? val.indexOf("'", q1 + 1) : -1;
    let cs = 'us-ascii';
    let encoded = val;
    if (q1 >= 0 && q2 >= 0) {
      cs = val.slice(0, q1) || 'us-ascii';
      encoded = val.slice(q2 + 1);
    }
    return decodeCharset(percentDecode(encoded), cs);
  }

  // Continuation segments
  const segs: { num: number; value: string; pct: boolean }[] = [];
  for (const p of params) {
    if (!p.name.startsWith(attr + '*')) continue;
    const rest = p.name.slice(attr.length + 1);
    if (rest === '') continue;
    if (rest.endsWith('*')) {
      const numStr = rest.slice(0, -1);
      if (/^\d+$/.test(numStr)) {
        segs.push({ num: parseInt(numStr), value: p.value, pct: true });
      }
    } else if (/^\d+$/.test(rest)) {
      segs.push({ num: parseInt(rest), value: p.value, pct: false });
    }
  }

  if (segs.length === 0) return null;
  segs.sort((a, b) => a.num - b.num);

  let cs = 'us-ascii';
  const allBytes: number[] = [];
  const hasPct = segs.some(s => s.pct);

  if (hasPct) {
    const seg0 = segs.find(s => s.num === 0);
    if (seg0 && seg0.pct) {
      const val = seg0.value;
      const q1 = val.indexOf("'");
      const q2 = q1 >= 0 ? val.indexOf("'", q1 + 1) : -1;
      if (q1 >= 0 && q2 >= 0) {
        cs = val.slice(0, q1) || 'us-ascii';
        const b = percentDecode(val.slice(q2 + 1));
        for (let x = 0; x < b.length; x++) allBytes.push(b[x]);
      } else {
        const b = percentDecode(val);
        for (let x = 0; x < b.length; x++) allBytes.push(b[x]);
      }
    }
    for (const seg of segs) {
      if (seg.num === 0) continue;
      const b = percentDecode(seg.value);
      for (let x = 0; x < b.length; x++) allBytes.push(b[x]);
    }
  } else {
    for (const seg of segs) {
      for (let x = 0; x < seg.value.length; x++) allBytes.push(seg.value.charCodeAt(x));
    }
  }

  return decodeCharset(Buffer.from(allBytes), cs);
}

function getFileName(cdParams: Param[] | null, ctParams: Param[] | null): string | null {
  if (cdParams) {
    const r = decodeRFC2231(cdParams, 'filename');
    if (r !== null) return r;
    const p = cdParams.find(pp => pp.name === 'filename');
    if (p) return decodeEncodedWords(p.value);
  }
  if (ctParams) {
    const r = decodeRFC2231(ctParams, 'name');
    if (r !== null) return r;
    const p = ctParams.find(pp => pp.name === 'name');
    if (p) return decodeEncodedWords(p.value);
  }
  return null;
}

// Entity structure
interface Entity {
  headers: Map<string, string>;
  body: Buffer;
  lb: string;
  type: string;
  subtype: string;
  ctParams: Param[];
  cdType: string | null;
  cdParams: Param[] | null;
  cte: string;
  parts?: Entity[];
}

// Detect line break
function detectLB(data: Buffer): string {
  for (let i = 0; i < data.length - 1; i++) {
    if (data[i] === 0x0D && data[i + 1] === 0x0A) return '\r\n';
  }
  return '\n';
}

// Parse headers from raw bytes
function parseHeaders(data: Buffer, lb: string): { headers: Map<string, string>; bodyStart: number } {
  const lbBuf = Buffer.from(lb);
  const lbLen = lbBuf.length;

  let pos = 0;
  while (pos <= data.length) {
    let lineEnd = pos;
    while (lineEnd < data.length) {
      if (lineEnd + lbLen <= data.length && data.slice(lineEnd, lineEnd + lbLen).equals(lbBuf)) break;
      lineEnd++;
    }
    if (lineEnd === pos) {
      // Empty line found
      const headerText = data.slice(0, pos).toString('ascii');
      const bodyStart = pos + lbLen;
      return { headers: parseHeaderText(headerText), bodyStart };
    }
    if (lineEnd + lbLen <= data.length) {
      pos = lineEnd + lbLen;
    } else {
      pos = lineEnd;
      break;
    }
  }

  // No empty line found
  const headerText = data.toString('ascii');
  return { headers: parseHeaderText(headerText), bodyStart: data.length };
}

function parseHeaderText(text: string): Map<string, string> {
  const lines = text.split(/\r\n|\n/);
  const unfolded: string[] = [];
  for (const line of lines) {
    if (line.length > 0 && (line[0] === ' ' || line[0] === '\t')) {
      if (unfolded.length > 0) unfolded[unfolded.length - 1] += line;
    } else {
      unfolded.push(line);
    }
  }

  const headers = new Map<string, string>();
  for (const line of unfolded) {
    const colon = line.indexOf(':');
    if (colon < 0) continue;
    const name = line.slice(0, colon).toLowerCase();
    let value = line.slice(colon + 1);
    value = value.replace(/^[ \t]+/, '').replace(/[ \t]+$/, '');
    headers.set(name, value);
  }
  return headers;
}

// Parse multipart body into parts
function parseMultipart(body: Buffer, B: string, lb: string): Entity[] {
  const lbBuf = Buffer.from(lb);
  const lbLen = lbBuf.length;

  interface BoundaryInfo { pos: number; isClose: boolean; lineEnd: number; }
  const boundaries: BoundaryInfo[] = [];

  let pos = 0;
  while (pos <= body.length) {
    let lineEnd = pos;
    while (lineEnd < body.length) {
      if (lineEnd + lbLen <= body.length && body.slice(lineEnd, lineEnd + lbLen).equals(lbBuf)) break;
      lineEnd++;
    }
    const lineContent = body.slice(pos, lineEnd).toString('ascii');
    const prefix = '--' + B;
    if (lineContent.startsWith(prefix)) {
      const after = lineContent.slice(prefix.length);
      if (/^[ \t]*$/.test(after)) {
        boundaries.push({ pos, isClose: false, lineEnd });
      } else if (after.startsWith('--') && /^[ \t]*$/.test(after.slice(2))) {
        boundaries.push({ pos, isClose: true, lineEnd });
      }
    }
    if (lineEnd + lbLen <= body.length) {
      pos = lineEnd + lbLen;
    } else {
      break;
    }
  }

  const parts: Entity[] = [];
  for (let i = 0; i < boundaries.length - 1; i++) {
    if (boundaries[i].isClose) break;
    const next = boundaries[i + 1];

    let contentStart = boundaries[i].lineEnd + lbLen;
    if (contentStart > body.length) contentStart = body.length;

    let contentEnd = next.pos;
    if (contentEnd >= lbLen && body.slice(contentEnd - lbLen, contentEnd).equals(lbBuf)) {
      contentEnd -= lbLen;
    }

    if (contentEnd < contentStart) contentEnd = contentStart;

    const partData = body.slice(contentStart, contentEnd);
    parts.push(parseEntity(partData, lb));

    if (next.isClose) break;
  }

  return parts;
}

// Parse entity
function parseEntity(data: Buffer, lb: string): Entity {
  const { headers, bodyStart } = parseHeaders(data, lb);
  const body = data.slice(bodyStart);

  // Content-Type
  const ctHeader = headers.get('content-type');
  let type = 'text', subtype = 'plain';
  let ctParams: Param[] = [];
  if (ctHeader) {
    const slash = ctHeader.indexOf('/');
    if (slash >= 0) {
      type = ctHeader.slice(0, slash).replace(/^[ \t]+/, '').replace(/[ \t]+$/, '').toLowerCase();
      let rest = ctHeader.slice(slash + 1);
      rest = rest.replace(/^[ \t]+/, '');
      let sub = '';
      let si = 0;
      while (si < rest.length && rest[si] !== ';' && rest[si] !== ' ' && rest[si] !== '\t') {
        sub += rest[si]; si++;
      }
      subtype = sub.toLowerCase();
      ctParams = parseParams(rest.slice(si));
    }
  }

  // Content-Disposition
  const cdHeader = headers.get('content-disposition');
  let cdType: string | null = null;
  let cdParams: Param[] | null = null;
  if (cdHeader) {
    let di = 0;
    while (di < cdHeader.length && cdHeader[di] !== ';' && cdHeader[di] !== ' ' && cdHeader[di] !== '\t') {
      di++;
    }
    cdType = cdHeader.slice(0, di).toLowerCase();
    cdParams = parseParams(cdHeader.slice(di));
  }

  // Content-Transfer-Encoding
  const cteHeader = headers.get('content-transfer-encoding');
  let cte = cteHeader ? cteHeader.toLowerCase().trim() : '7bit';

  const entity: Entity = { headers, body, lb, type, subtype, ctParams, cdType, cdParams, cte };

  // Multipart?
  if (type === 'multipart') {
    const boundaryParam = ctParams.find(p => p.name === 'boundary');
    if (boundaryParam) {
      entity.parts = parseMultipart(body, boundaryParam.value, lb);
    }
  }

  return entity;
}

// Quoted string output
function quoteStr(s: string): string {
  let result = '"';
  for (const ch of s) {
    const cp = ch.codePointAt(0)!;
    if (ch === '\\') result += '\\\\';
    else if (ch === '"') result += '\\"';
    else if (ch === '\n') result += '\\n';
    else if (ch === '\t') result += '\\t';
    else if (cp < 0x20 || (cp >= 0x7F && cp <= 0x9F)) {
      result += '\\u' + cp.toString(16).padStart(4, '0');
    } else {
      result += ch;
    }
  }
  result += '"';
  return result;
}

// Print entity tree
function printEntity(entity: Entity, indent: number): string[] {
  const lines: string[] = [];
  const ind = '  '.repeat(indent);

  if (entity.type === 'multipart') {
    const numParts = entity.parts ? entity.parts.length : 0;
    lines.push(`${ind}multipart/${entity.subtype} parts=${numParts}`);
    if (entity.parts) {
      for (const part of entity.parts) {
        lines.push(...printEntity(part, indent + 1));
      }
    }
  } else if (entity.type === 'text' && entity.cdType !== 'attachment') {
    const charsetParam = entity.ctParams.find(p => p.name === 'charset');
    const charset = charsetParam ? charsetParam.value.toLowerCase() : 'us-ascii';

    const decodedBytes = decodeTE(entity.body, entity.cte, entity.lb);
    let text = decodeCharset(decodedBytes, charset);
    text = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');

    const chars = [...text].length;
    lines.push(`${ind}text/${entity.subtype} charset=${charset} cte=${entity.cte} chars=${chars}`);
    lines.push(`${ind}  ${quoteStr(text)}`);
  } else {
    const decodedBytes = decodeTE(entity.body, entity.cte, entity.lb);
    const size = decodedBytes.length;
    const crc = crc32(decodedBytes).toString(16).padStart(8, '0');
    const name = getFileName(entity.cdParams, entity.ctParams);
    const disp = entity.cdType || '-';
    const nameStr = name !== null ? quoteStr(name) : '-';
    lines.push(`${ind}${entity.type}/${entity.subtype} cte=${entity.cte} disposition=${disp} name=${nameStr} size=${size} crc32=${crc}`);
  }

  return lines;
}

// Main
const dir = process.argv[2];
const files = fs.readdirSync(dir).filter(f => f.endsWith('.eml')).sort();

let first = true;
for (const file of files) {
  if (!first) console.log('');
  first = false;

  const data = fs.readFileSync(path.join(dir, file));
  const lb = detectLB(data);
  const entity = parseEntity(data, lb);

  console.log(`== ${file}`);

  const fromVal = entity.headers.get('from');
  const subjectVal = entity.headers.get('subject');

  console.log(`From: ${fromVal !== undefined ? quoteStr(decodeEncodedWords(fromVal)) : '-'}`);
  console.log(`Subject: ${subjectVal !== undefined ? quoteStr(decodeEncodedWords(subjectVal)) : '-'}`);

  const treeLines = printEntity(entity, 0);
  for (const line of treeLines) {
    console.log(line);
  }
}

