/* ============== Dynamic buffer for bytes ============== */
typedef struct {
    unsigned char *data;
    size_t len, cap;
} Buf;

static void buf_init(Buf *b) { b->data=NULL; b->len=0; b->cap=0; }
static void buf_free(Buf *b) { free(b->data); }
static void buf_reserve(Buf *b, size_t extra) {
    if (b->len + extra > b->cap) {
        size_t nc = b->cap ? b->cap*2 : 64;
        while (nc < b->len + extra) nc *= 2;
        b->data = realloc(b->data, nc);
        b->cap = nc;
    }
}
static void buf_push(Buf *b, unsigned char c) {
    buf_reserve(b, 1);
    b->data[b->len++] = c;
}
static void buf_append(Buf *b, const unsigned char *d, size_t n) {
    buf_reserve(b, n);
    memcpy(b->data + b->len, d, n);
    b->len += n;
}

/* ============== Dynamic buffer for code points ============== */
typedef struct {
    unsigned int *data;
    size_t len, cap;
} CPBuf;

static void cp_init(CPBuf *b) { b->data=NULL; b->len=0; b->cap=0; }
static void cp_free(CPBuf *b) { free(b->data); }
static void cp_reserve(CPBuf *b, size_t extra) {
    if (b->len + extra > b->cap) {
        size_t nc = b->cap ? b->cap*2 : 64;
        while (nc < b->len + extra) nc *= 2;
        b->data = realloc(b->data, nc * sizeof(unsigned int));
        b->cap = nc;
    }
}
static void cp_push(CPBuf *b, unsigned int c) {
    cp_reserve(b, 1);
    b->data[b->len++] = c;
}
static void cp_append(CPBuf *b, const CPBuf *src) {
    cp_reserve(b, src->len);
    memcpy(b->data + b->len, src->data, src->len * sizeof(unsigned int));
    b->len += src->len;
}

/* ============== CRC-32 ============== */
static uint32_t crc32_table[256];
static int crc32_table_ready = 0;

static void crc32_init(void) {
    for (uint32_t i = 0; i < 256; i++) {
        uint32_t c = i;
        for (int j = 0; j < 8; j++) {
            if (c & 1) c = (c >> 1) ^ 0xEDB88320;
            else c >>= 1;
        }
        crc32_table[i] = c;
    }
    crc32_table_ready = 1;
}

static uint32_t crc32_calc(const unsigned char *data, size_t len) {
    if (!crc32_table_ready) crc32_init();
    uint32_t crc = 0xFFFFFFFF;
    for (size_t i = 0; i < len; i++)
        crc = (crc >> 8) ^ crc32_table[(crc ^ data[i]) & 0xFF];
    return crc ^ 0xFFFFFFFF;
}

/* ============== Base64 decode ============== */
static int b64_val(int c) {
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
    if (c >= '0' && c <= '9') return c - '0' + 52;
    if (c == '+') return 62;
    if (c == '/') return 63;
    return -1;
}

static void base64_decode(const unsigned char *in, size_t inlen, Buf *out) {
    int acc = 0, bits = 0;
    for (size_t i = 0; i < inlen; i++) {
        if (in[i] == '=') break; // stop at padding
        int v = b64_val(in[i]);
        if (v < 0) continue; // ignore non-alphabet
        acc = (acc << 6) | v;
        bits += 6;
        if (bits >= 8) {
            bits -= 8;
            buf_push(out, (acc >> bits) & 0xFF);
        }
    }
}

/* ============== Quoted-printable decode ============== */
static int hex_val(int c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

static void qp_decode(const unsigned char *in, size_t inlen, Buf *out) {
    size_t i = 0;
    while (i < inlen) {
        if (in[i] == '=') {
            // Check for soft line break: = followed by line break
            // First, check if this = is followed by =XY
            if (i + 2 < inlen && hex_val(in[i+1]) >= 0 && hex_val(in[i+2]) >= 0) {
                // =XY
                buf_push(out, (hex_val(in[i+1]) << 4) | hex_val(in[i+2]));
                i += 3;
            } else {
                // Check for soft line break: = at end of line (possibly with trailing spaces/tabs)
                // "first remove all spaces and tabs at the end of each line"
                // Then "a line that then ends with = is joined to the next line"
                // So we need to look ahead: skip spaces/tabs, then check for line break
                size_t j = i + 1;
                while (j < inlen && (in[j] == ' ' || in[j] == '\t')) j++;
                if (j < inlen && in[j] == '\r' && j + 1 < inlen && in[j+1] == '\n') {
                    // soft line break (CRLF)
                    i = j + 2;
                } else if (j < inlen && in[j] == '\n') {
                    // soft line break (LF)
                    i = j + 1;
                } else {
                    // literal =
                    buf_push(out, '=');
                    i++;
                }
            }
        } else if (in[i] == '\r' && i + 1 < inlen && in[i+1] == '\n') {
            buf_push(out, '\r');
            buf_push(out, '\n');
            i += 2;
        } else if (in[i] == '\n') {
            buf_push(out, '\n');
            i++;
        } else if (in[i] == '\r') {
            buf_push(out, '\r');
            i++;
        } else {
            buf_push(out, in[i]);
            i++;
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <dirent.h>
#include <stdint.h>
#include <sys/stat.h>

/* ===== Dynamic byte buffer ===== */
typedef struct { unsigned char *d; size_t len, cap; } Buf;
static void bi(Buf*b){b->d=NULL;b->len=b->cap=0;}
static void bf(Buf*b){free(b->d);}
static void br(Buf*b,size_t x){if(b->len+x>b->cap){size_t n=b->cap?b->cap*2:64;while(n<b->len+x)n*=2;b->d=realloc(b->d,n);b->cap=n;}}
static void bp(Buf*b,unsigned char c){br(b,1);b->d[b->len++]=c;}
static void ba(Buf*b,const unsigned char*s,size_t n){br(b,n);memcpy(b->d+b->len,s,n);b->len+=n;}

/* ===== Dynamic code-point buffer ===== */
typedef struct { unsigned int *d; size_t len, cap; } CPB;
static void ci(CPB*b){b->d=NULL;b->len=b->cap=0;}
static void cf(CPB*b){free(b->d);}
static void cr(CPB*b,size_t x){if(b->len+x>b->cap){size_t n=b->cap?b->cap*2:64;while(n<b->len+x)n*=2;b->d=realloc(b->d,n*sizeof(unsigned));b->cap=n;}}
static void cp(CPB*b,unsigned int c){cr(b,1);b->d[b->len++]=c;}
static void cp_cat(CPB*b,const CPB*s){cr(b,s->len);memcpy(b->d+b->len,s->d,s->len*sizeof(unsigned));b->len+=s->len;}

/* ===== CRC-32 ===== */
static uint32_t crc_tab[256]; static int crc_rdy=0;
static void crc_init(void){for(uint32_t i=0;i<256;i++){uint32_t c=i;for(int j=0;j<8;j++)c=(c&1)?(c>>1)^0xEDB88320:c>>1;crc_tab[i]=c;}crc_rdy=1;}
static uint32_t crc32_calc(const unsigned char*d,size_t n){if(!crc_rdy)crc_init();uint32_t c=0xFFFFFFFF;for(size_t i=0;i<n;i++)c=(c>>8)^crc_tab[(c^d[i])&0xFF];return c^0xFFFFFFFF;}

/* ===== Base64 ===== */
static int b64v(int c){if(c>='A'&&c<='Z')return c-'A';if(c>='a'&&c<='z')return c-'a'+26;if(c>='0'&&c<='9')return c-'0'+52;if(c=='+')return 62;if(c=='/')return 63;return -1;}
static void b64dec(const unsigned char*in,size_t n,Buf*out){int acc=0,bits=0;for(size_t i=0;i<n;i++){if(in[i]=='=')break;int v=b64v(in[i]);if(v<0)continue;acc=(acc<<6)|v;bits+=6;if(bits>=8){bits-=8;bp(out,(unsigned char)((acc>>bits)&0xFF));}}}

/* ===== Hex ===== */
static int hv(int c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}

/* ===== Quoted-Printable ===== */
static void qpdec(const unsigned char*in,size_t n,Buf*out){
  size_t i=0;
  while(i<n){
    if(in[i]=='='){
      if(i+2<n&&hv(in[i+1])>=0&&hv(in[i+2])>=0){
        bp(out,(unsigned char)((hv(in[i+1])<<4)|hv(in[i+2])));i+=3;
      }else{
        size_t j=i+1;
        while(j<n&&(in[j]==' '||in[j]=='\t'))j++;
        if(j<n&&in[j]=='\r'&&j+1<n&&in[j+1]=='\n')i=j+2;
        else if(j<n&&in[j]=='\n')i=j+1;
        else{bp(out,'=');i++;}
      }
    }else{bp(out,in[i]);i++;}
  }
}

/* ===== Transfer encoding decode ===== */
static void cte_decode(const unsigned char*in,size_t n,const char*enc,Buf*out){
  if(!strcmp(enc,"base64"))b64dec(in,n,out);
  else if(!strcmp(enc,"quoted-printable"))qpdec(in,n,out);
  else ba(out,in,n);
}

/* ===== Charset decode ===== */
static void charset_decode(const unsigned char*in,size_t n,const char*cs,CPB*out){
  char lc[64];size_t cl=strlen(cs);if(cl>63)cl=63;memcpy(lc,cs,cl);lc[cl]=0;
  for(size_t i=0;i<cl;i++)lc[i]=(char)tolower(lc[i]);
  if(!strcmp(lc,"utf-8")){
    size_t i=0;
    while(i<n){
      unsigned int c;
      if(in[i]<0x80){c=in[i];i+=1;}
      else if((in[i]&0xE0)==0xC0){c=in[i]&0x1F;if(i+1<n)c=(c<<6)|(in[i+1]&0x3F);i+=2;}
      else if((in[i]&0xF0)==0xE0){c=in[i]&0x0F;if(i+1<n)c=(c<<6)|(in[i+1]&0x3F);if(i+2<n)c=(c<<6)|(in[i+2]&0x3F);i+=3;}
      else if((in[i]&0xF8)==0xF0){c=in[i]&0x07;if(i+1<n)c=(c<<6)|(in[i+1]&0x3F);if(i+2<n)c=(c<<6)|(in[i+2]&0x3F);if(i+3<n)c=(c<<6)|(in[i+3]&0x3F);i+=4;}
      else{c=in[i];i+=1;}
      cp(out,c);
    }
  }else if(!strcmp(lc,"iso-8859-1")){
    for(size_t i=0;i<n;i++)cp(out,in[i]);
  }else if(!strcmp(lc,"windows-1252")){
    static const unsigned int w1252[32]={
      0x20AC,0x0081,0x201A,0x0192,0x201E,0x2026,0x2020,0x2021,
      0x02C6,0x2030,0x0160,0x2039,0x0152,0x008D,0x017D,0x008F,
      0x0090,0x2018,0x2019,0x201C,0x201D,0x2022,0x2013,0x2014,
      0x02DC,0x2122,0x0161,0x203A,0x0153,0x009D,0x017E,0x0178};
    for(size_t i=0;i<n;i++){
      if(in[i]>=0x80&&in[i]<=0x9F)cp(out,w1252[in[i]-0x80]);
      else cp(out,in[i]);
    }
  }else{
    for(size_t i=0;i<n;i++)cp(out,in[i]);
  }
}

/* ===== UTF-8 encode ===== */
static void utf8_enc(Buf*b,unsigned int c){
  if(c<0x80)bp(b,(unsigned char)c);
  else if(c<0x800){bp(b,(unsigned char)(0xC0|(c>>6)));bp(b,(unsigned char)(0x80|(c&0x3F)));}
  else if(c<0x10000){bp(b,(unsigned char)(0xE0|(c>>12)));bp(b,(unsigned char)(0x80|((c>>6)&0x3F)));bp(b,(unsigned char)(0x80|(c&0x3F)));}
  else{bp(b,(unsigned char)(0xF0|(c>>18)));bp(b,(unsigned char)(0x80|((c>>12)&0x3F)));bp(b,(unsigned char)(0x80|((c>>6)&0x3F)));bp(b,(unsigned char)(0x80|(c&0x3F)));}
}

/* ===== Print quoted string ===== */
static void print_quoted(CPB*cpb){
  putchar('"');
  Buf tmp;bi(&tmp);
  for(size_t i=0;i<cpb->len;i++){
    unsigned int c=cpb->d[i];
    if(c=='\\')printf("\\\\");
    else if(c=='"')printf("\\\"");
    else if(c=='\n')printf("\\n");
    else if(c=='\t')printf("\\t");
    else if(c<0x20||(c>=0x7F&&c<=0x9F))printf("\\u%04x",c);
    else{tmp.len=0;utf8_enc(&tmp,c);fwrite(tmp.d,1,tmp.len,stdout);}
  }
  putchar('"');
  bf(&tmp);
}

/* ===== RFC 2047 encoded-word decode ===== */
static size_t try_ew(const unsigned char*data,size_t n,size_t pos,char*enc_out,size_t*et_out,size_t*et_len,char*cs_out){
  if(pos+1>=n||data[pos]!='='||data[pos+1]!='?')return 0;
  size_t p=pos+2;
  size_t cs_s=p;
  while(p<n&&data[p]!='?'&&data[p]!=' '&&data[p]!='\t')p++;
  if(p>=n||data[p]!='?')return 0;
  size_t cs_e=p;p++;
  size_t enc_s=p;
  while(p<n&&data[p]!='?')p++;
  if(p>=n||data[p]!='?')return 0;
  size_t enc_e=p;p++;
  if(enc_e-enc_s!=1)return 0;
  char ec=(char)data[enc_s];
  if(ec!='B'&&ec!='b'&&ec!='Q'&&ec!='q')return 0;
  size_t et_s=p;
  while(p<n&&data[p]!='?'&&data[p]!=' '&&data[p]!='\t')p++;
  if(p>=n||data[p]!='?')return 0;
  size_t et_e=p;p++;
  if(p>=n||data[p]!='=')return 0;
  p++;
  *enc_out=(ec=='b'||ec=='q')?(char)(ec-32):ec;
  *et_out=et_s;*et_len=et_e-et_s;
  size_t cslen=cs_e-cs_s;if(cslen>255)cslen=255;
  for(size_t k=0;k<cslen;k++)cs_out[k]=(char)tolower(data[cs_s+k]);
  cs_out[cslen]=0;
  char*st=strchr(cs_out,'*');if(st)*st=0;
  return p;
}

static void ew_decode(const unsigned char*in,size_t n,CPB*out){
  size_t i=0;
  while(i<n){
    char enc;size_t et_pos,et_len;char cs[256];
    size_t end=try_ew(in,n,i,&enc,&et_pos,&et_len,cs);
    if(!end){cp(out,in[i]);i++;continue;}
    /* collect bytes from first word */
    Buf wb;bi(&wb);
    if(enc=='B'){b64dec(in+et_pos,et_len,&wb);}
    else{for(size_t k=et_pos;k<et_pos+et_len;k++){
      if(in[k]=='_')bp(&wb,' ');
      else if(in[k]=='='&&k+2<et_pos+et_len&&hv(in[k+1])>=0&&hv(in[k+2])>=0){bp(&wb,(unsigned char)((hv(in[k+1])<<4)|hv(in[k+2])));k+=2;}
      else bp(&wb,in[k]);}}
    /* find adjacent words with same charset */
    size_t cur=end;
    while(cur<n){
      size_t ws=cur;while(ws<n&&(in[ws]==' '||in[ws]=='\t'))ws++;
      char enc2;size_t et2,el2;char cs2[256];
      size_t end2=try_ew(in,n,ws,&enc2,&et2,&el2,cs2);
      if(!end2)break;
      if(strcmp(cs,cs2)!=0)break;
      if(enc2=='B'){b64dec(in+et2,el2,&wb);}
      else{for(size_t k=et2;k<et2+el2;k++){
        if(in[k]=='_')bp(&wb,' ');
        else if(in[k]=='='&&k+2<et2+el2&&hv(in[k+1])>=0&&hv(in[k+2])>=0){bp(&wb,(unsigned char)((hv(in[k+1])<<4)|hv(in[k+2])));k+=2;}
        else bp(&wb,in[k]);}}
      cur=end2;
    }
    CPB tmp;ci(&tmp);
    charset_decode(wb.d,wb.len,cs,&tmp);
    cp_cat(out,&tmp);
    cf(&tmp);bf(&wb);
    i=cur;
  }
}

/* ===== Parameter storage ===== */
#define MAXP 64
typedef struct{char name[256];char value[4096];}Param;

/* ===== Parse header value into type + params ===== */
static void parse_ct(const char*val,char*type_out,Param*params,int*np){
  *np=0;
  size_t len=strlen(val),i=0;
  while(i<len&&(val[i]==' '||val[i]=='\t'))i++;
  size_t ts=i;
  while(i<len&&val[i]!=';'&&val[i]!=' '&&val[i]!='\t')i++;
  size_t te=i;
  size_t tl=te-ts;if(tl>255)tl=255;
  for(size_t k=0;k<tl;k++)type_out[k]=(char)tolower(val[ts+k]);
  type_out[tl]=0;
  while(i<len){
    while(i<len&&(val[i]==' '||val[i]=='\t'))i++;
    if(i>=len||val[i]!=';')break;
    i++;
    while(i<len&&(val[i]==' '||val[i]=='\t'))i++;
    if(i>=len)break;
    size_t ns=i;
    while(i<len&&val[i]!='='&&val[i]!=' '&&val[i]!='\t'&&val[i]!=';')i++;
    size_t ne=i;
    while(i<len&&(val[i]==' '||val[i]=='\t'))i++;
    if(i>=len||val[i]!='=')continue;
    i++;
    while(i<len&&(val[i]==' '||val[i]=='\t'))i++;
    if(i>=len)break;
    if(val[i]=='"'){
      i++;size_t vo=0;
      while(i<len&&val[i]!='"'){
        if(val[i]=='\\'&&i+1<len){params[*np].value[vo++]=val[i+1];i+=2;}
        else{params[*np].value[vo++]=val[i];i++;}
      }
      if(i<len)i++;
      params[*np].value[vo]=0;
    }else{
      size_t vs=i;
      while(i<len&&val[i]!=';'&&val[i]!=' '&&val[i]!='\t')i++;
      size_t vl=i-vs;if(vl>4095)vl=4095;
      memcpy(params[*np].value,val+vs,vl);
      params[*np].value[vl]=0;
    }
    size_t nl=ne-ns;if(nl>255)nl=255;
    for(size_t k=0;k<nl;k++)params[*np].name[k]=(char)tolower(val[ns+k]);
    params[*np].name[nl]=0;
    (*np)++;
    if(*np>=MAXP)break;
  }
}

/* ===== Find param value by name ===== */
static const char*find_param(Param*p,int np,const char*name){
  for(int i=0;i<np;i++)if(!strcmp(p[i].name,name))return p[i].value;
  return NULL;
}

/* ===== RFC 2231 matching ===== */
/* Returns segment index (>=0) if pname is RFC 2231 segment for attr, -1 otherwise.
   Sets *enc to 1 if percent-encoded. */
static int rfc2231_seg(const char*pname,const char*attr,int*enc){
  size_t al=strlen(attr);
  if(strncmp(pname,attr,al)!=0)return -1;
  if(pname[al]!='*')return -1;
  size_t i=al+1;
  if(pname[i]==0){*enc=1;return 0;}
  if(!isdigit((unsigned char)pname[i]))return -1;
  int idx=0;
  while(i<strlen(pname)&&isdigit((unsigned char)pname[i])){idx=idx*10+(pname[i]-'0');i++;}
  if(pname[i]=='*'){*enc=1;i++;}else *enc=0;
  if(pname[i]!=0)return -1;
  return idx;
}

/* ===== RFC 2231 assemble ===== */
/* Returns 1 if RFC 2231 form found, 0 otherwise.
   On success, fills *out with decoded code points. */
static int rfc2231_assemble(Param*params,int np,const char*attr,CPB*out){
  /* Collect segments */
  struct{int idx;int enc;const char*val;}segs[MAXP];
  int ns=0;
  for(int i=0;i<np;i++){
    int enc;int idx=rfc2231_seg(params[i].name,attr,&enc);
    if(idx>=0){segs[ns].idx=idx;segs[ns].enc=enc;segs[ns].val=params[i].value;ns++;}
  }
  if(ns==0)return 0;
  /* Sort by idx */
  for(int i=0;i<ns-1;i++)for(int j=i+1;j<ns;j++)if(segs[j].idx<segs[i].idx){
    struct{int idx;int enc;const char*val;}tmp=segs[i];segs[i]=segs[j];segs[j]=tmp;}
  /* Check: if any encoded, segment 0 must be encoded */
  int any_enc=0;for(int i=0;i<ns;i++)if(segs[i].enc){any_enc=1;break;}
  if(any_enc&&!(ns>0&&segs[0].enc&&segs[0].idx==0))return 0;
  /* Extract charset from first encoded segment */
  char charset[256]="us-ascii";
  Buf raw;bi(&raw);
  int cs_done=0;
  for(int i=0;i<ns;i++){
    const char*v=segs[i].val;
    if(segs[i].enc&&!cs_done){
      /* parse charset'language'prefix */
      const char*q1=strchr(v,'\'');
      if(q1){
        size_t cl=q1-v;if(cl>255)cl=255;
        memcpy(charset,v,cl);charset[cl]=0;
        const char*q2=strchr(q1+1,'\'');
        if(q2)v=q2+1;else v=q1+1;
      }
      cs_done=1;
    }
    /* decode percent-encoding if encoded */
    if(segs[i].enc){
      for(const char*p=v;*p;p++){
        if(*p=='%'&&p[1]&&p[2]&&hv(p[1])>=0&&hv(p[2])>=0){
          bp(&raw,(unsigned char)((hv(p[1])<<4)|hv(p[2])));p+=2;
        }else bp(&raw,(unsigned char)*p);
      }
    }else{
      ba(&raw,(const unsigned char*)v,strlen(v));
    }
  }
  charset_decode(raw.d,raw.len,charset,out);
  bf(&raw);
  return 1;
}

/* ===== Get filename from entity ===== */
static void get_filename(Param*cd_params,int cd_np,Param*ct_params,int ct_np,CPB*fn,CPB*ew_buf){
  /* Try RFC 2231 filename in Content-Disposition */
  if(rfc2231_assemble(cd_params,cd_np,"filename",fn))return;
  /* Try regular filename in Content-Disposition */
  const char*v=find_param(cd_params,cd_np,"filename");
  if(v){
    ew_decode((const unsigned char*)v,strlen(v),ew_buf);
    cp_cat(fn,ew_buf);ew_buf->len=0;
    return;
  }
  /* Try RFC 2231 name in Content-Type */
  if(rfc2231_assemble(ct_params,ct_np,"name",fn))return;
  /* Try regular name in Content-Type */
  v=find_param(ct_params,ct_np,"name");
  if(v){
    ew_decode((const unsigned char*)v,strlen(v),ew_buf);
    cp_cat(fn,ew_buf);ew_buf->len=0;
    return;
  }
}

/* ===== Entity structure ===== */
typedef struct Ent{
  char type[256],subtype[256],charset[256],cte[64],disp[64],boundary[256];
  unsigned char*body;size_t body_len;
  struct Ent*parts;int nparts;
  int is_multipart;
  CPB filename;int has_filename;
}Ent;

/* ===== Line break helpers ===== */
static int is_lb(const unsigned char*d,size_t pos,size_t n,const char*lb,int lb_len){
  if(pos+lb_len>n)return 0;
  for(int i=0;i<lb_len;i++)if(d[pos+i]!=(unsigned char)lb[i])return 0;
  return 1;
}

/* ===== Parse entity ===== */
static void parse_entity(const unsigned char*data,size_t dlen,const char*lb,int lb_len,Ent*e){
  memset(e,0,sizeof(*e));
  ci(&e->filename);
  /* Find header/body separator: first empty line */
  size_t hdr_end=0,body_start=0;
  if(dlen>=lb_len&&is_lb(data,0,dlen,lb,lb_len)){
    /* no headers */
    hdr_end=0;body_start=lb_len;
  }else{
    /* find first occurrence of lb+lb */
    hdr_end=dlen;body_start=dlen;
    for(size_t i=0;i+2*lb_len<=dlen;i++){
      if(is_lb(data,i,dlen,lb,lb_len)&&is_lb(data,i+lb_len,dlen,lb,lb_len)){
        hdr_end=i;body_start=i+lb_len;break;
      }
    }
  }
  /* Parse headers: unfold and extract */
  /* First, unfold: remove line breaks followed by space/tab */
  Buf unfolded;bi(&unfolded);
  {
    size_t i=0;
    while(i<hdr_end){
      if(is_lb(data,i,hdr_end,lb,lb_len)){
        size_t nl=i+lb_len;
        if(nl<hdr_end&&(data[nl]==' '||data[nl]=='\t')){
          /* continuation: skip the line break, keep the space/tab */
          i=nl;
        }else{
          /* end of header line */
          bp(&unfolded,'\n');
          i=nl;
        }
      }else{
        bp(&unfolded,data[i]);i++;
      }
    }
  }
  /* Now parse unfolded headers into key-value pairs */
  /* We need: Content-Type, Content-Disposition, Content-Transfer-Encoding, From, Subject */
  char from_val[4096]="",subj_val[4096]="";
  char ct_val[4096]="",cd_val[4096]="",cte_val[64]="7bit";
  int has_from=0,has_subj=0,has_ct=0,has_cd=0;
  {
    size_t i=0;
    while(i<unfolded.len){
      size_t ls=i;
      while(i<unfolded.len&&unfolded.d[i]!='\n')i++;
      size_t le=i;
      if(i<unfolded.len)i++; /* skip \n */
      if(le<=ls)continue;
      /* find colon */
      size_t colon=ls;
      while(colon<le&&unfolded.d[colon]!=':')colon++;
      if(colon>=le)continue;
      /* name */
      size_t ns=ls;
      /* trim leading spaces from name */
      while(ns<colon&&(unfolded.d[ns]==' '||unfolded.d[ns]=='\t'))ns++;
      /* trim trailing spaces from name */
      size_t ne=colon;
      while(ne>ns&&(unfolded.d[ne-1]==' '||unfolded.d[ne-1]=='\t'))ne--;
      /* lowercase name */
      char hname[256];size_t hnl=ne-ns;if(hnl>255)hnl=255;
      for(size_t k=0;k<hnl;k++)hname[k]=(char)tolower(unfolded.d[ns+k]);
      hname[hnl]=0;
      /* value: after colon, trim leading/trailing spaces/tabs */
      size_t vs=colon+1;
      while(vs<le&&(unfolded.d[vs]==' '||unfolded.d[vs]=='\t'))vs++;
      size_t ve=le;
      while(ve>vs&&(unfolded.d[ve-1]==' '||unfolded.d[ve-1]=='\t'))ve--;
      size_t vl=ve-vs;if(vl>4095)vl=4095;
      char hval[4096];memcpy(hval,unfolded.d+vs,vl);hval[vl]=0;

      if(!strcmp(hname,"content-type")){strcpy(ct_val,hval);has_ct=1;}
      else if(!strcmp(hname,"content-disposition")){strcpy(cd_val,hval);has_cd=1;}
      else if(!strcmp(hname,"content-transfer-encoding")){strcpy(cte_val,hval);if(strlen(cte_val)>63)cte_val[63]=0;}
      else if(!strcmp(hname,"from")){strcpy(from_val,hval);has_from=1;}
      else if(!strcmp(hname,"subject")){strcpy(subj_val,hval);has_subj=1;}
    }
  }
  bf(&unfolded);

  /* Lowercase cte */
  for(size_t i=0;cte_val[i];i++)cte_val[i]=(char)tolower(cte_val[i]);

  /* Parse Content-Type */
  Param ct_params[MAXP];int ct_np=0;
  char ct_type[256]="text/plain";char ct_sub[256]="";
  if(has_ct){
    char full_type[256];
    parse_ct(ct_val,full_type,ct_params,&ct_np);
    /* split type/subtype */
    char*sl=strchr(full_type,'/');
    if(sl){
      size_t tl=sl-full_type;if(tl>255)tl=255;
      memcpy(ct_type,full_type,tl);ct_type[tl]=0;
      strcpy(ct_sub,sl+1);
    }else{
      strcpy(ct_type,full_type);strcpy(ct_sub,"");
    }
  }

  /* Parse Content-Disposition */
  Param cd_params[MAXP];int cd_np=0;
  char cd_type[64]="";
  if(has_cd){
    char full_disp[64];
    parse_ct(cd_val,full_disp,cd_params,&cd_np);
    strcpy(cd_type,full_disp);
  }

  /* Fill entity */
  strcpy(e->type,ct_type);
  strcpy(e->subtype,ct_sub);
  e->is_multipart=!strcmp(e->type,"multipart");

  /* charset */
  if(!strcmp(e->type,"text")){
    const char*cs=find_param(ct_params,ct_np,"charset");
    if(cs){strcpy(e->charset,cs);for(size_t i=0;e->charset[i];i++)e->charset[i]=(char)tolower(e->charset[i]);}
    else strcpy(e->charset,"us-ascii");
  }else strcpy(e->charset,"");

  /* cte */
  if(e->is_multipart)strcpy(e->cte,"7bit");
  else strcpy(e->cte,cte_val);

  /* disposition */
  if(has_cd)strcpy(e->disp,cd_type);
  else e->disp[0]=0;

  /* boundary */
  if(e->is_multipart){
    const char*b=find_param(ct_params,ct_np,"boundary");
    if(b)strncpy(e->boundary,b,255);
  }

  /* filename */
  CPB ew_tmp;ci(&ew_tmp);
  get_filename(cd_params,cd_np,ct_params,ct_np,&e->filename,&ew_tmp);
  cf(&ew_tmp);
  e->has_filename=e->filename.len>0;

  /* body */
  e->body=(unsigned char*)data+body_start;
  e->body_len=dlen-body_start;

  /* multipart parsing */
  if(e->is_multipart&&e->boundary[0]){
    /* find delimiters in body */
    size_t blen=strlen(e->boundary);
    /* A delimiter line is: --boundary followed by only spaces/tabs
       A close delimiter: --boundary-- followed by only spaces/tabs */
    /* Find all delimiter positions */
    size_t delims[256];int nd=0;int is_close[256];
    size_t pos=0;
    while(pos<=e->body_len){
      /* Check if line starting at pos is a delimiter */
      /* A line starts at pos (either beginning of body or after a line break) */
      /* Check --boundary */
      if(pos+2+blen<=e->body_len&&e->body[pos]=='-'&&e->body[pos+1]=='-'&&
         memcmp(e->body+pos+2,e->boundary,blen)==0){
        size_t after=pos+2+blen;
        /* check for close: -- */
        int close=0;
        if(after+2<=e->body_len&&e->body[after]=='-'&&e->body[after+1]=='-'){close=1;after+=2;}
        /* check only spaces/tabs until end of line */
        int ok=1;
        while(after<e->body_len&&e->body[after]!='\r'&&e->body[after]!='\n'){
          if(e->body[after]!=' '&&e->body[after]!='\t'){ok=0;break;}
          after++;
        }
        if(ok){
          if(nd<256){delims[nd]=pos;is_close[nd]=close;nd++;}
          if(close)break;
        }
      }
      /* advance to next line */
      while(pos<e->body_len&&!is_lb(e->body,pos,e->body_len,lb,lb_len))pos++;
      if(pos<e->body_len)pos+=lb_len;
      else break;
    }

    /* Extract parts between consecutive delimiters */
    /* Part i is between delims[i] and delims[i+1] */
    /* Content starts after the line break following delims[i] */
    /* Content ends at the line break before delims[i+1] */
    int np=nd-1; /* number of parts = number of delimiters - 1 (but last might be close) */
    if(nd>=2)np=nd-1;
    else np=0;

    e->parts=(Ent*)malloc(np*sizeof(Ent));
    e->nparts=np;

    for(int pi=0;pi<np;pi++){
      size_t d_start=delims[pi];
      size_t d_end=delims[pi+1];
      /* content starts after line break following d_start */
      size_t cs=d_start;
      /* find end of delimiter line */
      while(cs<e->body_len&&e->body[cs]!='\r'&&e->body[cs]!='\n')cs++;
      /* cs is now at the line break (or end of body) */
      if(cs<e->body_len)cs+=lb_len; /* skip line break */
      /* content ends at the line break before d_end */
      size_t ce=d_end;
      if(ce>=lb_len)ce-=lb_len; /* the line break before the delimiter */
      else ce=0;
      if(ce<cs)ce=cs; /* empty part */
      parse_entity(e->body+cs,ce-cs,lb,lb_len,&e->parts[pi]);
    }
  }
}

/* ===== Output tree ===== */
static void print_tree(Ent*e,int indent){
  for(int i=0;i<indent;i++)printf("  ");
  if(e->is_multipart){
    printf("multipart/%s parts=%d\n",e->subtype,e->nparts);
    for(int i=0;i<e->nparts;i++)print_tree(&e->parts[i],indent+1);
  }else if(!strcmp(e->type,"text")&&strcmp(e->disp,"attachment")!=0){
    /* text part */
    Buf decoded;bi(&decoded);
    cte_decode(e->body,e->body_len,e->cte,&decoded);
    CPB cps;ci(&cps);
    charset_decode(decoded.d,decoded.len,e->charset,&cps);
    bf(&decoded);
    /* replace CRLF and lone CR with LF */
    CPB fixed;ci(&fixed);
    for(size_t i=0;i<cps.len;i++){
      if(cps.d[i]==0x0D){
        if(i+1<cps.len&&cps.d[i+1]==0x0A){cp(&fixed,0x0A);i++;}
        else cp(&fixed,0x0A);
      }else cp(&fixed,cps.d[i]);
    }
    cf(&cps);
    printf("text/%s charset=%s cte=%s chars=%zu\n",e->subtype,e->charset,e->cte,fixed.len);
    for(int i=0;i<indent+1;i++)printf("  ");
    print_quoted(&fixed);
    printf("\n");
    cf(&fixed);
  }else{
    /* other part */
    Buf decoded;bi(&decoded);
    cte_decode(e->body,e->body_len,e->cte,&decoded);
    uint32_t crc=crc32_calc(decoded.d,decoded.len);
    printf("%s/%s cte=%s disposition=%s name=",e->type,e->subtype,e->cte,
           e->disp[0]?e->disp:"-");
    if(e->has_filename)print_quoted(&e->filename);
    else putchar('-');
    printf(" size=%zu crc32=%08x\n",decoded.len,crc);
    bf(&decoded);
  }
}

/* ===== Free entity ===== */
static void free_ent(Ent*e){
  cf(&e->filename);
  if(e->parts){for(int i=0;i<e->nparts;i++)free_ent(&e->parts[i]);free(e->parts);}
}

/* ===== Main ===== */
int main(int argc,char**argv){
  if(argc<2){fprintf(stderr,"Usage: %s <dir>\n",argv[0]);return 1;}
  crc_init();
  DIR*dir=opendir(argv[1]);
  if(!dir){perror("opendir");return 1;}

  /* collect .eml filenames */
  char**names=NULL;int nfiles=0,cap=0;
  struct dirent*de;
  while((de=readdir(dir))){
    size_t l=strlen(de->d_name);
    if(l>4&&strcmp(de->d_name+l-4,".eml")==0){
      if(nfiles>=cap){cap=cap?cap*2:16;names=realloc(names,cap*sizeof(char*));}
      names[nfiles]=strdup(de->d_name);nfiles++;
    }
  }
  closedir(dir);

  /* sort byte-wise ascending */
  for(int i=0;i<nfiles-1;i++)for(int j=i+1;j<nfiles;j++)
    if(strcmp(names[j],names[i])<0){char*t=names[i];names[i]=names[j];names[j]=t;}

  for(int fi=0;fi<nfiles;fi++){
    if(fi>0)printf("\n");
    printf("== %s\n",names[fi]);

    /* read file */
    char path[4096];
    snprintf(path,sizeof(path),"%s/%s",argv[1],names[fi]);
    FILE*f=fopen(path,"rb");
    if(!f){fprintf(stderr,"Cannot open %s\n",path);continue;}
    fseek(f,0,SEEK_END);long fsz=ftell(f);fseek(f,0,SEEK_SET);
    unsigned char*fdata=(unsigned char*)malloc(fsz?fsz:1);
    fread(fdata,1,fsz,f);fclose(f);

    /* detect line ending */
    const char*lb="\r\n";int lb_len=2;
    int has_crlf=0;
    for(long i=0;i+1<fsz;i++){if(fdata[i]=='\r'&&fdata[i+1]=='\n'){has_crlf=1;break;}}
    if(!has_crlf){lb="\n";lb_len=1;}

    /* parse */
    Ent msg;
    parse_entity(fdata,(size_t)fsz,lb,lb_len,&msg);

    /* print From */
    /* We need to re-extract From/Subject from headers with RFC 2047 decoding */
    /* Actually let's redo: parse headers again for From/Subject with ew_decode */
    /* We need to find From and Subject in the raw data */
    /* Let me store them during parse_entity... Actually I already have them in the parse. */
    /* Let me restructure: I'll extract From/Subject in a separate pass */

    /* Find header/body separator again for From/Subject */
    size_t hdr_end=0;
    if(fsz>=lb_len&&is_lb(fdata,0,(size_t)fsz,lb,lb_len)){hdr_end=0;}
    else{
      hdr_end=(size_t)fsz;
      for(size_t i=0;i+2*lb_len<=(size_t)fsz;i++){
        if(is_lb(fdata,i,(size_t)fsz,lb,lb_len)&&is_lb(fdata,i+lb_len,(size_t)fsz,lb,lb_len)){hdr_end=i;break;}
      }
    }
    /* unfold headers */
    Buf uh;bi(&uh);
    {size_t i=0;while(i<hdr_end){
      if(is_lb(fdata,i,hdr_end,lb,lb_len)){
        size_t nl=i+lb_len;
        if(nl<hdr_end&&(fdata[nl]==' '||fdata[nl]=='\t')){i=nl;}
        else{bp(&uh,'\n');i=nl;}
      }else{bp(&uh,fdata[i]);i++;}
    }}
    /* extract From and Subject */
    int has_from=0,has_subj=0;
    char from_raw[4096]="",subj_raw[4096]="";
    {size_t i=0;while(i<uh.len){
      size_t ls=i;while(i<uh.len&&uh.d[i]!='\n')i++;size_t le=i;if(i<uh.len)i++;
      if(le<=ls)continue;
      size_t colon=ls;while(colon<le&&uh.d[colon]!=':')colon++;
      if(colon>=le)continue;
      size_t ns=ls;while(ns<colon&&(uh.d[ns]==' '||uh.d[ns]=='\t'))ns++;
      size_t ne=colon;while(ne>ns&&(uh.d[ne-1]==' '||uh.d[ne-1]=='\t'))ne--;
      char hn[256];size_t hnl=ne-ns;if(hnl>255)hnl=255;
      for(size_t k=0;k<hnl;k++)hn[k]=(char)tolower(uh.d[ns+k]);hn[hnl]=0;
      size_t vs=colon+1;while(vs<le&&(uh.d[vs]==' '||uh.d[vs]=='\t'))vs++;
      size_t ve=le;while(ve>vs&&(uh.d[ve-1]==' '||uh.d[ve-1]=='\t'))ve--;
      size_t vl=ve-vs;if(vl>4095)vl=4095;
      if(!strcmp(hn,"from")){memcpy(from_raw,uh.d+vs,vl);from_raw[vl]=0;has_from=1;}
      else if(!strcmp(hn,"subject")){memcpy(subj_raw,uh.d+vs,vl);subj_raw[vl]=0;has_subj=1;}
    }}
    bf(&uh);

    printf("From: ");
    if(has_from){CPB fc;ci(&fc);ew_decode((const unsigned char*)from_raw,strlen(from_raw),&fc);print_quoted(&fc);cf(&fc);}
    else putchar('-');
    printf("\nSubject: ");
    if(has_subj){CPB sc;ci(&sc);ew_decode((const unsigned char*)subj_raw,strlen(subj_raw),&sc);print_quoted(&sc);cf(&sc);}
    else putchar('-');
    printf("\n");

    /* print tree */
    print_tree(&msg,0);

    free_ent(&msg);
    free(fdata);
    free(names[fi]);
  }

  free(names);
  return 0;
}

import sys

INT_MIN = -(1 << 63)
INT_MAX = (1 << 63) - 1

T_INT = 0
T_STR = 1
T_IDENT = 2
T_KW = 3
T_OP = 4
T_EOF = 5

KEYWORDS = frozenset(['let', 'fn', 'if', 'else', 'while', 'for', 'in', 'return',
                       'break', 'continue', 'and', 'or', 'not', 'true', 'false', 'nil'])

_UNSET = object()


def tokenize(src):
    toks = []
    i = 0
    n = len(src)
    line = 1
    while i < n:
        c = src[i]
        if c == '\n':
            line += 1
            i += 1
            continue
        if c in ' \t\r':
            i += 1
            continue
        if c == '#':
            while i < n and src[i] != '\n':
                i += 1
            continue
        if c.isdigit():
            j = i + 1
            while j < n and src[j].isdigit():
                j += 1
            toks.append((T_INT, int(src[i:j]), line))
            i = j
            continue
        if c == '"':
            i += 1
            parts = []
            while i < n and src[i] != '"':
                if src[i] == '\\':
                    i += 1
                    nc = src[i]
                    if nc == 'n':
                        parts.append('\n')
                    elif nc == 't':
                        parts.append('\t')
                    elif nc == '"':
                        parts.append('"')
                    else:
                        parts.append('\\')
                    i += 1
                else:
                    parts.append(src[i])
                    i += 1
            i += 1
            toks.append((T_STR, ''.join(parts), line))
            continue
        if c.isalpha() or c == '_':
            j = i + 1
            while j < n and (src[j].isalnum() or src[j] == '_'):
                j += 1
            w = src[i:j]
            if w in KEYWORDS:
                toks.append((T_KW, w, line))
            else:
                toks.append((T_IDENT, w, line))
            i = j
            continue
        if i + 1 < n:
            two = src[i:i + 2]
            if two in ('==', '!=', '<=', '>='):
                toks.append((T_OP, two, line))
                i += 2
                continue
        toks.append((T_OP, c, line))
        i += 1
    toks.append((T_EOF, None, line))
    return toks


class Parser:
    __slots__ = ('toks', 'pos')

    def __init__(self, toks):
        self.toks = toks
        self.pos = 0

    def peek(self):
        return self.toks[self.pos]

    def advance(self):
        t = self.toks[self.pos]
        self.pos += 1
        return t

    def check(self, ttype, val=None):
        t = self.toks[self.pos]
        if t[0] != ttype:
            return False
        if val is not None and t[1] != val:
            return False
        return True

    def expect(self, ttype, val=None):
        self.advance()

    def parse_program(self):
        stmts = []
        while not self.check(T_EOF):
            stmts.append(self.parse_stmt())
        return stmts

    def parse_block(self):
        self.expect(T_OP, '{')
        stmts = []
        while not self.check(T_OP, '}'):
            stmts.append(self.parse_stmt())
        self.expect(T_OP, '}')
        return stmts

    def parse_params(self):
        params = []
        if self.check(T_IDENT):
            params.append(self.advance()[1])
            while self.check(T_OP, ','):
                self.advance()
                params.append(self.advance()[1])
        return params

    def parse_stmt(self):
        t = self.peek()
        if t[0] == T_KW:
            kw = t[1]
            if kw == 'let':
                return self.parse_let()
            if kw == 'fn':
                if self.toks[self.pos + 1][0] == T_IDENT:
                    return self.parse_fn_decl()
            elif kw == 'if':
                return self.parse_if()
            elif kw == 'while':
                return self.parse_while()
            elif kw == 'for':
                return self.parse_for()
            elif kw == 'return':
                return self.parse_return()
            elif kw == 'break':
                self.advance()
                self.expect(T_OP, ';')
                return ('break', t[2])
            elif kw == 'continue':
                self.advance()
                self.expect(T_OP, ';')
                return ('continue', t[2])

        expr = self.parse_expr()
        if self.check(T_OP, '='):
            self.advance()
            val = self.parse_expr()
            self.expect(T_OP, ';')
            if expr[0] == 'ident':
                return ('assign', expr[1], val, expr[2])
            elif expr[0] == 'index':
                return ('index_assign', expr[1], expr[2], val, expr[3])
        else:
            self.expect(T_OP, ';')
            return ('expr_stmt', expr)

    def parse_let(self):
        self.advance()
        name_tok = self.advance()
        self.expect(T_OP, '=')
        val = self.parse_expr()
        self.expect(T_OP, ';')
        return ('let', name_tok[1], val, name_tok[2])

    def parse_fn_decl(self):
        self.advance()
        name_tok = self.advance()
        self.expect(T_OP, '(')
        params = self.parse_params()
        self.expect(T_OP, ')')
        body = self.parse_block()
        return ('fn_decl', name_tok[1], params, body, name_tok[2])

    def parse_if(self):
        t = self.advance()
        cond = self.parse_expr()
        body = self.parse_block()
        else_body = None
        if self.check(T_KW, 'else'):
            self.advance()
            if self.check(T_KW, 'if'):
                else_body = self.parse_if()
            else:
                else_body = self.parse_block()
        return ('if', cond, body, else_body, t[2])

    def parse_while(self):
        t = self.advance()
        cond = self.parse_expr()
        body = self.parse_block()
        return ('while', cond, body, t[2])

    def parse_for(self):
        t = self.advance()
        var_tok = self.advance()
        self.expect(T_KW, 'in')
        iterable = self.parse_expr()
        body = self.parse_block()
        return ('for', var_tok[1], iterable, body, t[2])

    def parse_return(self):
        t = self.advance()
        if self.check(T_OP, ';'):
            self.advance()
            return ('return', None, t[2])
        expr = self.parse_expr()
        self.expect(T_OP, ';')
        return ('return', expr, t[2])

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self.check(T_KW, 'or'):
            t = self.advance()
            right = self.parse_and()
            left = ('binop', 'or', left, right, t[2])
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.check(T_KW, 'and'):
            t = self.advance()
            right = self.parse_not()
            left = ('binop', 'and', left, right, t[2])
        return left

    def parse_not(self):
        if self.check(T_KW, 'not'):
            t = self.advance()
            operand = self.parse_not()
            return ('unop', 'not', operand, t[2])
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_add()
        while True:
            t = self.peek()
            if t[0] == T_OP and t[1] in ('==', '!=', '<', '<=', '>', '>='):
                self.advance()
                right = self.parse_add()
                left = ('binop', t[1], left, right, t[2])
            else:
                break
        return left

    def parse_add(self):
        left = self.parse_mul()
        while True:
            t = self.peek()
            if t[0] == T_OP and t[1] in ('+', '-'):
                self.advance()
                right = self.parse_mul()
                left = ('binop', t[1], left, right, t[2])
            else:
                break
        return left

    def parse_mul(self):
        left = self.parse_unary()
        while True:
            t = self.peek()
            if t[0] == T_OP and t[1] in ('*', '/', '%'):
                self.advance()
                right = self.parse_unary()
                left = ('binop', t[1], left, right, t[2])
            else:
                break
        return left

    def parse_unary(self):
        if self.check(T_OP, '-'):
            t = self.advance()
            operand = self.parse_postfix()
            return ('unop', '-', operand, t[2])
        return self.parse_postfix()

    def parse_postfix(self):
        expr = self.parse_primary()
        while True:
            t = self.peek()
            if t[0] == T_OP and t[1] == '(':
                self.advance()
                args = []
                if not self.check(T_OP, ')'):
                    args.append(self.parse_expr())
                    while self.check(T_OP, ','):
                        self.advance()
                        args.append(self.parse_expr())
                self.expect(T_OP, ')')
                expr = ('call', expr, args, t[2])
            elif t[0] == T_OP and t[1] == '[':
                self.advance()
                idx = self.parse_expr()
                self.expect(T_OP, ']')
                expr = ('index', expr, idx, t[2])
            else:
                break
        return expr

    def parse_primary(self):
        t = self.advance()
        if t[0] == T_INT:
            return ('int', t[1], t[2])
        if t[0] == T_STR:
            return ('str', t[1], t[2])
        if t[0] == T_KW:
            kw = t[1]
            if kw == 'true':
                return ('bool', True, t[2])
            if kw == 'false':
                return ('bool', False, t[2])
            if kw == 'nil':
                return ('nil', t[2])
            if kw == 'fn':
                self.expect(T_OP, '(')
                params = self.parse_params()
                self.expect(T_OP, ')')
                body = self.parse_block()
                return ('fn', params, body, t[2])
        if t[0] == T_IDENT:
            return ('ident', t[1], t[2])
        if t[0] == T_OP:
            if t[1] == '(':
                expr = self.parse_expr()
                self.expect(T_OP, ')')
                return expr
            if t[1] == '[':
                elems = []
                if not self.check(T_OP, ']'):
                    elems.append(self.parse_expr())
                    while self.check(T_OP, ','):
                        self.advance()
                        elems.append(self.parse_expr())
                self.expect(T_OP, ']')
                return ('list', elems, t[2])
        raise Exception(f"Unexpected token: {t}")


class TernError(Exception):
    __slots__ = ('msg', 'line')

    def __init__(self, msg, line):
        self.msg = msg
        self.line = line


class BreakSignal(Exception):
    pass


class ContinueSignal(Exception):
    pass


class ReturnSignal(Exception):
    __slots__ = ('val',)

    def __init__(self, val):
        self.val = val


class TernFunction:
    __slots__ = ('params', 'body', 'scope', 'name')

    def __init__(self, params, body, scope, name=None):
        self.params = params
        self.body = body
        self.scope = scope
        self.name = name


class Scope:
    __slots__ = ('vars', 'parent')

    def __init__(self, parent=None):
        self.vars = {}
        self.parent = parent

    def get(self, name):
        s = self
        while s is not None:
            if name in s.vars:
                return s.vars[name]
            s = s.parent
        return _UNSET

    def set(self, name, val):
        s = self
        while s is not None:
            if name in s.vars:
                s.vars[name] = val
                return True
            s = s.parent
        return False

    def declare(self, name, val):
        self.vars[name] = val


def tern_type(v):
    if v is None:
        return 'nil'
    if isinstance(v, bool):
        return 'bool'
    if isinstance(v, int):
        return 'int'
    if isinstance(v, str):
        return 'string'
    if isinstance(v, list):
        return 'list'
    return 'function'


def truthy(v):
    if v is None:
        return False
    if isinstance(v, bool):
        return v
    if isinstance(v, int):
        return v != 0
    if isinstance(v, str):
        return len(v) > 0
    if isinstance(v, list):
        return len(v) > 0
    return True


def tern_eq(a, b):
    ta = tern_type(a)
    tb = tern_type(b)
    if ta != tb:
        return False
    if ta == 'nil':
        return True
    if ta == 'int' or ta == 'bool' or ta == 'string':
        return a == b
    if ta == 'list':
        if len(a) != len(b):
            return False
        for i in range(len(a)):
            if not tern_eq(a[i], b[i]):
                return False
        return True
    if ta == 'function':
        return a is b
    return False


def check_int(v, line):
    if v < INT_MIN or v > INT_MAX:
        raise TernError("integer overflow", line)
    return v


def tern_div(a, b, line):
    if b == 0:
        raise TernError("division by zero", line)
    q = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        q = -q
    return check_int(q, line)


def tern_mod(a, b, line):
    if b == 0:
        raise TernError("division by zero", line)
    q = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        q = -q
    r = a - q * b
    return check_int(r, line)


def display(v, in_list=False, seen=None):
    if v is None:
        return 'nil'
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, int):
        return str(v)
    if isinstance(v, str):
        if in_list:
            return '"' + v.replace('\\', '\\\\').replace('"', '\\"').replace('\n', '\\n').replace('\t', '\\t') + '"'
        return v
    if isinstance(v, list):
        if seen is None:
            seen = set()
        vid = id(v)
        if vid in seen:
            return '[...]'
        seen.add(vid)
        parts = [display(e, True, seen) for e in v]
        seen.discard(vid)
        return '[' + ', '.join(parts) + ']'
    return '<fn>'


class Interpreter:
    def __init__(self):
        self.globals = Scope()
        g = self.globals
        g.declare('print', ('builtin', 'print'))
        g.declare('str', ('builtin', 'str'))
        g.declare('type', ('builtin', 'type'))
        g.declare('len', ('builtin', 'len'))
        g.declare('push', ('builtin', 'push'))
        g.declare('pop', ('builtin', 'pop'))
        g.declare('range', ('builtin', 'range'))
        g.declare('slice', ('builtin', 'slice'))

    def run(self, stmts):
        try:
            self.exec_block(stmts, self.globals)
        except TernError as e:
            sys.stdout.write(f"error at line {e.line}: {e.msg}\n")

    def exec_block(self, stmts, scope):
        for stmt in stmts:
            self.exec_stmt(stmt, scope)

    def exec_stmt(self, stmt, scope):
        kind = stmt[0]
        if kind == 'let':
            _, name, val_node, line = stmt
            val = self.eval(val_node, scope)
            scope.declare(name, val)
        elif kind == 'fn_decl':
            _, name, params, body, line = stmt
            fn = TernFunction(params, body, scope, name)
            scope.declare(name, fn)
        elif kind == 'assign':
            _, name, val_node, line = stmt
            val = self.eval(val_node, scope)
            if not scope.set(name, val):
                raise TernError(f"undefined variable {name}", line)
        elif kind == 'index_assign':
            _, obj_node, idx_node, val_node, line = stmt
            obj = self.eval(obj_node, scope)
            idx = self.eval(idx_node, scope)
            val = self.eval(val_node, scope)
            if not isinstance(obj, list):
                raise TernError(f"cannot assign into {tern_type(obj)}", line)
            if tern_type(idx) != 'int':
                raise TernError(f"cannot index list with {tern_type(idx)}", line)
            if idx < 0 or idx >= len(obj):
                raise TernError(f"index {idx} out of range for length {len(obj)}", line)
            obj[idx] = val
        elif kind == 'if':
            _, cond, body, else_body, line = stmt
            if truthy(self.eval(cond, scope)):
                self.exec_block(body, Scope(scope))
            elif else_body is not None:
                if isinstance(else_body, list):
                    self.exec_block(else_body, Scope(scope))
                else:
                    self.exec_stmt(else_body, scope)
        elif kind == 'while':
            _, cond, body, line = stmt
            while truthy(self.eval(cond, scope)):
                try:
                    self.exec_block(body, Scope(scope))
                except BreakSignal:
                    break
                except ContinueSignal:
                    continue
        elif kind == 'for':
            _, var, iter_node, body, line = stmt
            lst = self.eval(iter_node, scope)
            if not isinstance(lst, list):
                raise TernError(f"cannot iterate {tern_type(lst)}", line)
            i = 0
            while i < len(lst):
                inner = Scope(scope)
                inner.declare(var, lst[i])
                try:
                    self.exec_block(body, inner)
                except BreakSignal:
                    break
                except ContinueSignal:
                    pass
                i += 1
        elif kind == 'return':
            _, expr_node, line = stmt
            val = self.eval(expr_node, scope) if expr_node is not None else None
            raise ReturnSignal(val)
        elif kind == 'break':
            raise BreakSignal()
        elif kind == 'continue':
            raise ContinueSignal()
        elif kind == 'expr_stmt':
            self.eval(stmt[1], scope)

    def eval(self, node, scope):
        kind = node[0]
        if kind == 'int':
            return node[1]
        if kind == 'str':
            return node[1]
        if kind == 'bool':
            return node[1]
        if kind == 'nil':
            return None
        if kind == 'ident':
            name = node[1]
            val = scope.get(name)
            if val is _UNSET:
                raise TernError(f"undefined variable {name}", node[2])
            return val
        if kind == 'list':
            return [self.eval(e, scope) for e in node[1]]
        if kind == 'fn':
            return TernFunction(node[1], node[2], scope)
        if kind == 'call':
            return self.eval_call(node, scope)
        if kind == 'index':
            return self.eval_index(node, scope)
        if kind == 'binop':
            return self.eval_binop(node, scope)
        if kind == 'unop':
            return self.eval_unop(node, scope)
        raise Exception(f"Unknown node type: {kind}")

    def eval_binop(self, node, scope):
        _, op, left_node, right_node, line = node
        if op == 'and':
            lv = self.eval(left_node, scope)
            if not truthy(lv):
                return lv
            return self.eval(right_node, scope)
        if op == 'or':
            lv = self.eval(left_node, scope)
            if truthy(lv):
                return lv
            return self.eval(right_node, scope)

        lv = self.eval(left_node, scope)
        rv = self.eval(right_node, scope)

        if op == '==':
            return tern_eq(lv, rv)
        if op == '!=':
            return not tern_eq(lv, rv)

        if op in ('<', '<=', '>', '>='):
            ta = tern_type(lv)
            tb = tern_type(rv)
            if ta == 'int' and tb == 'int':
                pass
            elif ta == 'string' and tb == 'string':
                pass
            else:
                raise TernError(f"cannot apply {op} to {ta} and {tb}", line)
            if op == '<':
                return lv < rv
            if op == '<=':
                return lv <= rv
            if op == '>':
                return lv > rv
            return lv >= rv

        if op == '+':
            ta = tern_type(lv)
            tb = tern_type(rv)
            if ta == 'int' and tb == 'int':
                return check_int(lv + rv, line)
            if ta == 'string' and tb == 'string':
                return lv + rv
            if ta == 'list' and tb == 'list':
                return lv + rv
            raise TernError(f"cannot apply + to {ta} and {tb}", line)

        if op in ('-', '*', '/', '%'):
            ta = tern_type(lv)
            tb = tern_type(rv)
            if ta != 'int' or tb != 'int':
                raise TernError(f"cannot apply {op} to {ta} and {tb}", line)
            if op == '-':
                return check_int(lv - rv, line)
            if op == '*':
                return check_int(lv * rv, line)
            if op == '/':
                return tern_div(lv, rv, line)
            return tern_mod(lv, rv, line)

        raise Exception(f"Unknown operator: {op}")

    def eval_unop(self, node, scope):
        _, op, operand_node, line = node
        if op == 'not':
            return not truthy(self.eval(operand_node, scope))
        if op == '-':
            v = self.eval(operand_node, scope)
            if tern_type(v) != 'int':
                raise TernError(f"cannot apply - to {tern_type(v)}", line)
            return check_int(-v, line)

    def eval_index(self, node, scope):
        _, obj_node, idx_node, line = node
        obj = self.eval(obj_node, scope)
        idx = self.eval(idx_node, scope)
        ta = tern_type(obj)
        ti = tern_type(idx)
        if ta not in ('list', 'string') or ti != 'int':
            raise TernError(f"cannot index {ta} with {ti}", line)
        if idx < 0 or idx >= len(obj):
            raise TernError(f"index {idx} out of range for length {len(obj)}", line)
        return obj[idx]

    def eval_call(self, node, scope):
        _, callee_node, arg_nodes, line = node
        callee = self.eval(callee_node, scope)
        args = [self.eval(a, scope) for a in arg_nodes]

        if isinstance(callee, tuple) and callee[0] == 'builtin':
            return self.call_builtin(callee[1], args, line)

        if not isinstance(callee, TernFunction):
            raise TernError(f"cannot call {tern_type(callee)}", line)

        if len(args) != len(callee.params):
            raise TernError(f"expected {len(callee.params)} arguments, got {len(args)}", line)

        call_scope = Scope(callee.scope)
        params = callee.params
        for i in range(len(params)):
            call_scope.declare(params[i], args[i])

        try:
            self.exec_block(callee.body, call_scope)
        except ReturnSignal as r:
            return r.val
        return None

    def call_builtin(self, name, args, line):
        if name == 'print':
            parts = [display(a) for a in args]
            sys.stdout.write(' '.join(parts) + '\n')
            return None
        if name == 'str':
            if len(args) != 1:
                raise TernError(f"expected 1 arguments, got {len(args)}", line)
            return display(args[0])
        if name == 'type':
            if len(args) != 1:
                raise TernError(f"expected 1 arguments, got {len(args)}", line)
            return tern_type(args[0])
        if name == 'len':
            if len(args) != 1:
                raise TernError(f"expected 1 arguments, got {len(args)}", line)
            v = args[0]
            if isinstance(v, str) or isinstance(v, list):
                return len(v)
            raise TernError("bad argument to len", line)
        if name == 'push':
            if len(args) != 2:
                raise TernError(f"expected 2 arguments, got {len(args)}", line)
            lst, v = args
            if not isinstance(lst, list):
                raise TernError("bad argument to push", line)
            lst.append(v)
            return None
        if name == 'pop':
            if len(args) != 1:
                raise TernError(f"expected 1 arguments, got {len(args)}", line)
            lst = args[0]
            if not isinstance(lst, list):
                raise TernError("bad argument to pop", line)
            if len(lst) == 0:
                raise TernError("bad argument to pop", line)
            return lst.pop()
        if name == 'range':
            if len(args) != 2:
                raise TernError(f"expected 2 arguments, got {len(args)}", line)
            a, b = args
            if tern_type(a) != 'int' or tern_type(b) != 'int':
                raise TernError("bad argument to range", line)
            return list(range(a, b))
        if name == 'slice':
            if len(args) != 3:
                raise TernError(f"expected 3 arguments, got {len(args)}", line)
            x, a, b = args
            if tern_type(a) != 'int' or tern_type(b) != 'int':
                raise TernError("bad argument to slice", line)
            tx = tern_type(x)
            if tx == 'string':
                if a < 0 or b > len(x) or a > b:
                    raise TernError("bad argument to slice", line)
                return x[a:b]
            if tx == 'list':
                if a < 0 or b > len(x) or a > b:
                    raise TernError("bad argument to slice", line)
                return x[a:b]
            raise TernError("bad argument to slice", line)


