fn parse_params(s: &str) -> Vec<(String, String)> {
    // s is the header value after the type/subtype or disposition type
    // Parse ; attribute=value pairs
    let mut params = vec![];
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        // Skip spaces/tabs
        while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\t') { i += 1; }
        if i >= bytes.len() { break; }
        if bytes[i] != b';' { i += 1; continue; } // skip non-semicolons? 
        // Actually, after the type, we should be at ; or end
        i += 1; // skip ;
        // Skip spaces/tabs
        while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\t') { i += 1; }
        // Read attribute name (token: up to =, space, tab, or ;)
        let attr_start = i;
        while i < bytes.len() && bytes[i] != b'=' && bytes[i] != b' ' && bytes[i] != b'\t' && bytes[i] != b';' { i += 1; }
        if i >= bytes.len() || bytes[i] != b'=' { break; } // no value
        let attr = s[attr_start..i].to_lowercase();
        i += 1; // skip =
        // Skip spaces/tabs
        while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\t') { i += 1; }
        // Read value
        let value;
        if i < bytes.len() && bytes[i] == b'"' {
            // Quoted string
            i += 1;
            let mut v = String::new();
            while i < bytes.len() && bytes[i] != b'"' {
                if bytes[i] == b'\\' && i + 1 < bytes.len() {
                    v.push(s.as_bytes()[i+1] as char);
                    i += 2;
                } else {
                    v.push(bytes[i] as char);
                    i += 1;
                }
            }
            if i < bytes.len() { i += 1; } // skip closing "
            value = v;
        } else {
            // Token
            let val_start = i;
            while i < bytes.len() && bytes[i] != b';' && bytes[i] != b' ' && bytes[i] != b'\t' { i += 1; }
            value = s[val_start..i].to_string();
        }
        params.push((attr, value));
    }
    params
}

use std::env;
use std::fs;

fn main() {
    let dir = env::args().nth(1).unwrap();
    let mut files: Vec<String> = fs::read_dir(&dir)
        .unwrap()
        .filter_map(|e| {
            let name = e.unwrap().file_name().into_string().unwrap();
            if name.ends_with(".eml") { Some(name) } else { None }
        })
        .collect();
    files.sort();

    let mut first = true;
    for fname in &files {
        if !first { println!(); }
        first = false;
        let content = fs::read(format!("{}/{}", dir, fname)).unwrap();
        process_file(fname, &content);
    }
}

fn process_file(fname: &str, content: &[u8]) {
    let lb = detect_lb(content);
    let entity = parse_entity(content, lb);

    println!("== {}", fname);

    // From header
    let from_val = get_header(&entity.headers, "from");
    match from_val {
        Some(v) => println!("From: {}", quote_string(&decode_rfc2047(v))),
        None => println!("From: -"),
    }

    // Subject header
    let subj_val = get_header(&entity.headers, "subject");
    match subj_val {
        Some(v) => println!("Subject: {}", quote_string(&decode_rfc2047(v))),
        None => println!("Subject: -"),
    }

    // Print tree
    print_entity(&entity, 0, lb);
}

fn print_entity(entity: &Entity, indent: usize, lb: &[u8]) {
    let ct = get_content_type(entity);
    let cte = get_cte(entity);
    let disp = get_content_disposition(entity);

    if ct.type_ == "multipart" {
        println!("{}multipart/{} parts={}", " ".repeat(indent), ct.subtype, entity.parts.len());
        for part in &entity.parts {
            print_entity(part, indent + 2, lb);
        }
    } else if ct.type_ == "text" && disp.as_ref().map_or(true, |d| d.disp_type != "attachment") {
        // Text part (not attachment)
        let charset = ct.params.iter().find(|(k, _)| k == "charset").map(|(_, v)| v.as_str()).unwrap_or("us-ascii");
        let decoded_bytes = decode_cte(&entity.body, &cte, lb);
        let codepoints = decode_charset_to_codepoints(&decoded_bytes, charset);
        let normalized = normalize_newlines(&codepoints);
        let text = codepoints_to_string(&normalized);
        let n = normalized.len();
        println!("{}text/{} charset={} cte={} chars={}", " ".repeat(indent), ct.subtype, charset, cte, n);
        println!("{}{}", " ".repeat(indent + 2), quote_string(&text));
    } else {
        // Other part
        let decoded_bytes = decode_cte(&entity.body, &cte, lb);
        let size = decoded_bytes.len();
        let crc = crc32(&decoded_bytes);
        let name = get_filename(entity);
        let disp_str = disp.as_ref().map(|d| d.disp_type.as_str()).unwrap_or("-");
        let name_str = match &name {
            Some(n) => quote_string(n),
            None => "-".to_string(),
        };
        println!("{}{}/{} cte={} disposition={} name={} size={} crc32={:08x}",
            " ".repeat(indent), ct.type_, ct.subtype, cte, disp_str, name_str, size, crc);
    }
}

use std::env;
use std::fs;
use std::path::Path;

#[derive(Debug, Clone, PartialEq)]
struct Line {
    content: Vec<u8>,
    has_newline: bool,
}

#[derive(Debug, Clone)]
struct Hunk {
    a: usize,
    b: usize,
    c: usize,
    d: usize,
    old_lines: Vec<Line>,
    new_lines: Vec<Line>,
    malformed: bool,
}

#[derive(Debug, Clone, PartialEq)]
enum Kind {
    Create,
    Delete,
    Modify,
}

#[derive(Debug)]
struct Section {
    path: String,
    kind: Kind,
    hunks: Vec<Hunk>,
}

fn content_to_lines(content: &[u8]) -> Vec<Line> {
    if content.is_empty() {
        return vec![];
    }
    let parts: Vec<&[u8]> = content.split(|&b| b == b'\n').collect();
    let n = parts.len();
    let mut lines = Vec::new();
    if n > 1 && parts[n - 1].is_empty() {
        for i in 0..n - 1 {
            lines.push(Line { content: parts[i].to_vec(), has_newline: true });
        }
    } else {
        for i in 0..n - 1 {
            lines.push(Line { content: parts[i].to_vec(), has_newline: true });
        }
        lines.push(Line { content: parts[n - 1].to_vec(), has_newline: false });
    }
    lines
}

fn lines_to_content(lines: &[Line]) -> Vec<u8> {
    let mut result = Vec::new();
    for line in lines {
        result.extend_from_slice(&line.content);
        if line.has_newline {
            result.push(b'\n');
        }
    }
    result
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc = 0xFFFFFFFFu32;
    for &byte in data {
        crc ^= byte as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    crc ^ 0xFFFFFFFF
}

fn parse_hunk_header(line: &[u8]) -> Option<(usize, usize, usize, usize)> {
    let s = std::str::from_utf8(line).ok()?;
    if !s.starts_with("@@ -") {
        return None;
    }
    let rest = &s[4..];

    let space_pos = rest.find(' ')?;
    let old_range = &rest[..space_pos];
    let (a, b) = if let Some(comma) = old_range.find(',') {
        let a: usize = old_range[..comma].parse().ok()?;
        let b: usize = old_range[comma + 1..].parse().ok()?;
        (a, b)
    } else {
        let a: usize = old_range.parse().ok()?;
        (a, 1)
    };

    let rest2 = &rest[space_pos + 1..];
    if !rest2.starts_with('+') {
        return None;
    }
    let rest3 = &rest2[1..];
    let space2 = rest3.find(' ')?;
    let new_range = &rest3[..space2];
    let (c, d) = if let Some(comma) = new_range.find(',') {
        let c: usize = new_range[..comma].parse().ok()?;
        let d: usize = new_range[comma + 1..].parse().ok()?;
        (c, d)
    } else {
        let c: usize = new_range.parse().ok()?;
        (c, 1)
    };

    Some((a, b, c, d))
}

fn parse_diff(diff_content: &[u8]) -> Vec<Section> {
    let all_lines: Vec<&[u8]> = diff_content.split(|&b| b == b'\n').collect();
    let lines: Vec<&[u8]> = if all_lines.len() > 1 && all_lines[all_lines.len() - 1].is_empty() {
        all_lines[..all_lines.len() - 1].to_vec()
    } else {
        all_lines
    };

    let mut sections = Vec::new();
    let mut i = 0;

    while i < lines.len() {
        if !lines[i].starts_with(b"diff --git a/") {
            i += 1;
            continue;
        }

        let s = std::str::from_utf8(lines[i]).unwrap();
        let after = &s["diff --git a/".len()..];
        let space = after.find(" b/").unwrap();
        let path = after[..space].to_string();
        i += 1;

        let mut kind = Kind::Modify;
        loop {
            if i >= lines.len() { break; }
            let l = lines[i];
            if l.starts_with(b"new file mode ") {
                kind = Kind::Create;
                i += 1;
            } else if l.starts_with(b"deleted file mode ") {
                kind = Kind::Delete;
                i += 1;
            } else if l.starts_with(b"index ") {
                i += 1;
            } else {
                break;
            }
        }

        let mut has_hunks = false;
        if i < lines.len() && lines[i].starts_with(b"--- ") {
            i += 1;
            if i < lines.len() && lines[i].starts_with(b"+++ ") {
                i += 1;
                has_hunks = true;
            }
        }

        let mut hunks = Vec::new();
        if has_hunks {
            while i < lines.len() {
                let l = lines[i];
                if l.starts_with(b"@@ ") {
                    if let Some((a, b, c, d)) = parse_hunk_header(l) {
                        i += 1;
                        let mut old_lines: Vec<Line> = Vec::new();
                        let mut new_lines: Vec<Line> = Vec::new();
                        let mut prev_marker: Option<u8> = None;

                        while i < lines.len() {
                            let bl = lines[i];
                            if bl.starts_with(b"@@ ") || bl.starts_with(b"diff --git ") {
                                break;
                            }

                            if bl.is_empty() {
                                old_lines.push(Line { content: vec![], has_newline: true });
                                new_lines.push(Line { content: vec![], has_newline: true });
                                prev_marker = Some(b' ');
                                i += 1;
                            } else if bl[0] == b'\\' {
                                if let Some(m) = prev_marker {
                                    match m {
                                        b' ' => {
                                            if let Some(last) = old_lines.last_mut() { last.has_newline = false; }
                                            if let Some(last) = new_lines.last_mut() { last.has_newline = false; }
                                        }
                                        b'-' => {
                                            if let Some(last) = old_lines.last_mut() { last.has_newline = false; }
                                        }
                                        b'+' => {
                                            if let Some(last) = new_lines.last_mut() { last.has_newline = false; }
                                        }
                                        _ => {}
                                    }
                                }
                                i += 1;
                            } else {
                                let marker = bl[0];
                                let content = bl[1..].to_vec();
                                match marker {
                                    b' ' => {
                                        old_lines.push(Line { content: content.clone(), has_newline: true });
                                        new_lines.push(Line { content, has_newline: true });
                                    }
                                    b'-' => {
                                        old_lines.push(Line { content, has_newline: true });
                                    }
                                    b'+' => {
                                        new_lines.push(Line { content, has_newline: true });
                                    }
                                    _ => {}
                                }
                                prev_marker = Some(marker);
                                i += 1;
                            }
                        }

                        let malformed = old_lines.len() != b || new_lines.len() != d;
                        hunks.push(Hunk { a, b, c, d, old_lines, new_lines, malformed });
                    } else {
                        i += 1;
                    }
                } else {
                    break;
                }
            }
        }

        sections.push(Section { path, kind, hunks });
    }

    sections
}

fn format_offset(k: isize) -> String {
    if k > 0 {
        format!("+{}", k)
    } else if k < 0 {
        format!("{}", k)
    } else {
        "0".to_string()
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let tree_dir = Path::new(dir).join("tree");

    let diff_content = fs::read(Path::new(dir).join("changes.diff")).unwrap();
    let mut sections = parse_diff(&diff_content);

    sections.sort_by(|a, b| a.path.as_bytes().cmp(b.path.as_bytes()));

    let mut output_lines: Vec<String> = Vec::new();

    for section in &sections {
        let file_path = tree_dir.join(&section.path);
        let file_exists = file_path.exists();

        let kind_str = match section.kind {
            Kind::Create => "create",
            Kind::Delete => "delete",
            Kind::Modify => "modify",
        };

        match section.kind {
            Kind::Create => {
                if file_exists {
                    output_lines.push(format!("{}: {}", section.path, kind_str));
                    output_lines.push("  error: already exists".to_string());
                    continue;
                }
            }
            Kind::Modify | Kind::Delete => {
                if !file_exists {
                    output_lines.push(format!("{}: {}", section.path, kind_str));
                    output_lines.push("  error: not found".to_string());
                    continue;
                }
            }
        }

        let content = if file_exists {
            fs::read(&file_path).unwrap_or_default()
        } else {
            vec![]
        };

        let mut lines = content_to_lines(&content);
        let mut delta: isize = 0;
        let mut all_applied = true;

        output_lines.push(format!("{}: {}", section.path, kind_str));

        for (idx, hunk) in section.hunks.iter().enumerate() {
            let hunk_num = idx + 1;

            if hunk.malformed {
                output_lines.push(format!("  hunk {}: malformed", hunk_num));
                all_applied = false;
                continue;
            }

            let p_expected = (hunk.a as isize) + delta;

            if hunk.b == 0 {
                let p = p_expected;
                if p >= 0 && (p as usize) <= lines.len() {
                    for (j, nl) in hunk.new_lines.iter().enumerate() {
                        lines.insert((p as usize) + j, nl.clone());
                    }
                    output_lines.push(format!("  hunk {}: applied at {} (offset 0)", hunk_num, p));
                    delta += hunk.d as isize;
                } else {
                    output_lines.push(format!("  hunk {}: rejected", hunk_num));
                    all_applied = false;
                }
            } else {
                let b = hunk.b;
                let mut found = false;
                let mut found_p: usize = 0;
                let mut found_offset: isize = 0;

                if b <= lines.len() {
                    let mut k: isize = 0;
                    loop {
                        // Try P - k first (earlier position wins on tie)
                        let p_try = p_expected - k;
                        if p_try >= 1 {
                            let p_idx = (p_try - 1) as usize;
                            if p_idx + b <= lines.len() {
                                if lines[p_idx..p_idx + b] == hunk.old_lines[..] {
                                    found = true;
                                    found_p = p_try as usize;
                                    found_offset = -k;
                                    break;
                                }
                            }
                        }

                        if k > 0 {
                            let p_try = p_expected + k;
                            if p_try >= 1 {
                                let p_idx = (p_try - 1) as usize;
                                if p_idx + b <= lines.len() {
                                    if lines[p_idx..p_idx + b] == hunk.old_lines[..] {
                                        found = true;
                                        found_p = p_try as usize;
                                        found_offset = k;
                                        break;
                                    }
                                }
                            }
                        }

                        // Termination: both sides exhausted
                        let left_done = p_expected - k < 1;
                        let right_done = p_expected + k + b as isize - 1 > lines.len() as isize;
                        if left_done && right_done {
                            break;
                        }

                        k += 1;
                        if k > lines.len() as isize + 1 {
                            break;
                        }
                    }
                }

                if found {
                    let p_idx = (found_p - 1) as usize;
                    lines.splice(p_idx..p_idx + b, hunk.new_lines.iter().cloned());
                    output_lines.push(format!(
                        "  hunk {}: applied at {} (offset {})",
                        hunk_num, found_p, format_offset(found_offset)
                    ));
                    delta += hunk.d as isize - hunk.b as isize;
                } else {
                    output_lines.push(format!("  hunk {}: rejected", hunk_num));
                    all_applied = false;
                }
            }
        }

        // Result line
        if section.kind == Kind::Delete && all_applied {
            let final_content = lines_to_content(&lines);
            if final_content.is_empty() {
                output_lines.push("  result: deleted".to_string());
            } else {
                let n = lines.len();
                let crc = crc32(&final_content);
                output_lines.push(format!("  result: {} lines, crc32 {:08x}", n, crc));
            }
        } else {
            let final_content = lines_to_content(&lines);
            let n = lines.len();
            let crc = crc32(&final_content);
            output_lines.push(format!("  result: {} lines, crc32 {:08x}", n, crc));
        }
    }

    for line in &output_lines {
        println!("{}", line);
    }
}

import java.util.*;
import java.io.*;
import java.nio.file.*;

public class Main {

    enum TokType {
        INT, STR, IDENT,
        PLUS, MINUS, STAR, SLASH, PCT,
        EQ, NEQ, LT, LE, GT, GE,
        ASSIGN, LPAREN, RPAREN, LBRACKET, RBRACKET, LBRACE, RBRACE,
        COMMA, SEMI,
        LET, FN, IF, ELSE, WHILE, FOR, IN, RET, BRK, CONT,
        AND, OR, NOT, TRUE, FALSE, NIL, EOF
    }

    static final Map<String, TokType> KW = new HashMap<>();
    static {
        KW.put("let", TokType.LET); KW.put("fn", TokType.FN);
        KW.put("if", TokType.IF); KW.put("else", TokType.ELSE);
        KW.put("while", TokType.WHILE); KW.put("for", TokType.FOR);
        KW.put("in", TokType.IN); KW.put("return", TokType.RET);
        KW.put("break", TokType.BRK); KW.put("continue", TokType.CONT);
        KW.put("and", TokType.AND); KW.put("or", TokType.OR);
        KW.put("not", TokType.NOT); KW.put("true", TokType.TRUE);
        KW.put("false", TokType.FALSE); KW.put("nil", TokType.NIL);
    }

    static class Tok {
        TokType type; String text; long ival; String sval; int line;
        Tok(TokType t, String x, int l) { type=t; text=x; line=l; }
    }

    // ---- Lexer ----
    static List<Tok> lex(String src) {
        List<Tok> toks = new ArrayList<>();
        int pos = 0, line = 1, n = src.length();
        while (pos < n) {
            char c = src.charAt(pos);
            if (c=='\n') { line++; pos++; continue; }
            if (c==' '||c=='\t'||c=='\r') { pos++; continue; }
            if (c=='#') { while(pos<n && src.charAt(pos)!='\n') pos++; continue; }
            if (Character.isDigit(c)) {
                int s=pos; while(pos<n && Character.isDigit(src.charAt(pos))) pos++;
                Tok t=new Tok(TokType.INT, src.substring(s,pos), line);
                t.ival=Long.parseLong(t.text); toks.add(t); continue;
            }
            if (c=='"') {
                pos++; StringBuilder sb=new StringBuilder();
                while(pos<n && src.charAt(pos)!='"') {
                    if(src.charAt(pos)=='\\') { pos++; char e=src.charAt(pos);
                        if(e=='n') sb.append('\n'); else if(e=='t') sb.append('\t');
                        else if(e=='"') sb.append('"'); else sb.append('\\');
                    } else sb.append(src.charAt(pos));
                    pos++;
                }
                pos++; Tok t=new Tok(TokType.STR, sb.toString(), line); t.sval=sb.toString(); toks.add(t); continue;
            }
            if (Character.isLetter(c)||c=='_') {
                int s=pos; while(pos<n&&(Character.isLetterOrDigit(src.charAt(pos))||src.charAt(pos)=='_')) pos++;
                String w=src.substring(s,pos); toks.add(new Tok(KW.getOrDefault(w,TokType.IDENT),w,line)); continue;
            }
            if(c=='='&&pos+1<n&&src.charAt(pos+1)=='='){toks.add(new Tok(TokType.EQ,"==",line));pos+=2;continue;}
            if(c=='!'&&pos+1<n&&src.charAt(pos+1)=='='){toks.add(new Tok(TokType.NEQ,"!=",line));pos+=2;continue;}
            if(c=='<'&&pos+1<n&&src.charAt(pos+1)=='='){toks.add(new Tok(TokType.LE,"<=",line));pos+=2;continue;}
            if(c=='>'&&pos+1<n&&src.charAt(pos+1)=='='){toks.add(new Tok(TokType.GE,">=",line));pos+=2;continue;}
            TokType tt; String tx;
            switch(c){
                case'+':tt=TokType.PLUS;tx="+";break; case'-':tt=TokType.MINUS;tx="-";break;
                case'*':tt=TokType.STAR;tx="*";break; case'/':tt=TokType.SLASH;tx="/";break;
                case'%':tt=TokType.PCT;tx="%";break; case'=':tt=TokType.ASSIGN;tx="=";break;
                case'<':tt=TokType.LT;tx="<";break; case'>':tt=TokType.GT;tx=">";break;
                case'(':tt=TokType.LPAREN;tx="(";break; case')':tt=TokType.RPAREN;tx=")";break;
                case'[':tt=TokType.LBRACKET;tx="[";break; case']':tt=TokType.RBRACKET;tx="]";break;
                case'{':tt=TokType.LBRACE;tx="{";break; case'}':tt=TokType.RBRACE;tx="}";break;
                case',':tt=TokType.COMMA;tx=",";break; case';':tt=TokType.SEMI;tx=";";break;
                default:pos++;continue;
            }
            toks.add(new Tok(tt,tx,line)); pos++;
        }
        toks.add(new Tok(TokType.EOF,"",line));
        return toks;
    }

    // ---- AST ----
    abstract static class Expr { int line; }
    static class IntLit extends Expr{long v;IntLit(long v,int l){this.v=v;line=l;}}
    static class StrLit extends Expr{String v;StrLit(String v,int l){this.v=v;line=l;}}
    static class BoolLit extends Expr{boolean v;BoolLit(boolean v,int l){this.v=v;line=l;}}
    static class NilLit extends Expr{NilLit(int l){line=l;}}
    static class IdentE extends Expr{String n;IdentE(String n,int l){this.n=n;line=l;}}
    static class BinE extends Expr{String op;Expr l,r;BinE(String o,Expr l,Expr r,int ln){op=o;this.l=l;this.r=r;line=ln;}}
    static class NegE extends Expr{Expr e;NegE(Expr e,int l){this.e=e;line=l;}}
    static class NotE extends Expr{Expr e;NotE(Expr e,int l){this.e=e;line=l;}}
    static class AndE extends Expr{Expr l,r;AndE(Expr l,Expr r,int ln){this.l=l;this.r=r;line=ln;}}
    static class OrE extends Expr{Expr l,r;OrE(Expr l,Expr r,int ln){this.l=l;this.r=r;line=ln;}}
    static class CallE extends Expr{Expr fn;List<Expr> args;CallE(Expr f,List<Expr> a,int l){fn=f;args=a;line=l;}}
    static class IdxE extends Expr{Expr obj,idx;IdxE(Expr o,Expr i,int l){obj=o;idx=i;line=l;}}
    static class ListE extends Expr{List<Expr> elems;ListE(List<Expr> e,int l){elems=e;line=l;}}
    static class FnE extends Expr{List<String> params;Block body;FnE(List<String> p,Block b,int l){params=p;body=b;line=l;}}

    abstract static class Stmt { int line; }
    static class LetS extends Stmt{String n;Expr v;LetS(String n,Expr v,int l){this.n=n;this.v=v;line=l;}}
    static class FnS extends Stmt{String n;List<String> params;Block body;FnS(String n,List<String> p,Block b,int l){this.n=n;params=p;body=b;line=l;}}
    static class IfS extends Stmt{Expr cond;Block thenB;Block elseB;Stmt elseIf;IfS(Expr c,Block t,Block eb,Stmt ei,int l){cond=c;thenB=t;elseB=eb;elseIf=ei;line=l;}}
    static class WhileS extends Stmt{Expr cond;Block body;WhileS(Expr c,Block b,int l){cond=c;body=b;line=l;}}
    static class ForS extends Stmt{String var;Expr iter;Block body;ForS(String v,Expr it,Block b,int l){var=v;iter=it;body=b;line=l;}}
    static class RetS extends Stmt{Expr v;RetS(Expr v,int l){this.v=v;line=l;}}
    static class BrkS extends Stmt{BrkS(int l){line=l;}}
    static class ContS extends Stmt{ContS(int l){line=l;}}
    static class AsgS extends Stmt{String n;Expr v;AsgS(String n,Expr v,int l){this.n=n;this.v=v;line=l;}}
    static class IdxAsgS extends Stmt{Expr obj,idx,val;IdxAsgS(Expr o,Expr i,Expr v,int l){obj=o;idx=i;val=v;line=l;}}
    static class ExprS extends Stmt{Expr e;ExprS(Expr e,int l){this.e=e;line=l;}}
    static class Block{List<Stmt> stmts;Block(List<Stmt> s){stmts=s;}}

    // ---- Parser ----
    static class Parser {
        List<Tok> toks; int p;
        Parser(List<Tok> t){toks=t;p=0;}
        Tok peek(){return toks.get(p);}
        Tok next(){return toks.get(p++);}
        boolean at(TokType t){return peek().type==t;}
        Tok expect(TokType t){return toks.get(p++);}

        Block parseBlock(){
            expect(TokType.LBRACE); List<Stmt> ss=new ArrayList<>();
            while(!at(TokType.RBRACE)) ss.add(parseStmt());
            expect(TokType.RBRACE); return new Block(ss);
        }

        Stmt parseStmt(){
            Tok t=peek();
            switch(t.type){
                case LET:{next();Tok nm=expect(TokType.IDENT);expect(TokType.ASSIGN);Expr v=parseExpr();expect(TokType.SEMI);return new LetS(nm.text,v,nm.line);}
                case FN:{next();Tok nm=expect(TokType.IDENT);expect(TokType.LPAREN);List<String> ps=parseParams();expect(TokType.RPAREN);Block b=parseBlock();return new FnS(nm.text,ps,b,nm.line);}
                case IF: return parseIf();
                case WHILE:{next();Expr c=parseExpr();Block b=parseBlock();return new WhileS(c,b,t.line);}
                case FOR:{next();Tok v=expect(TokType.IDENT);expect(TokType.IN);Expr it=parseExpr();Block b=parseBlock();return new ForS(v.text,it,b,t.line);}
                case RET:{next();Expr v=null;if(!at(TokType.SEMI))v=parseExpr();expect(TokType.SEMI);return new RetS(v,t.line);}
                case BRK:{next();expect(TokType.SEMI);return new BrkS(t.line);}
                case CONT:{next();expect(TokType.SEMI);return new ContS(t.line);}
                default:{
                    Expr e=parseExpr();
                    if(at(TokType.ASSIGN)){next();Expr v=parseExpr();expect(TokType.SEMI);
                        if(e instanceof IdentE)return new AsgS(((IdentE)e).n,v,e.line);
                        if(e instanceof IdxE)return new IdxAsgS(((IdxE)e).obj,((IdxE)e).idx,v,e.line);
                        return new ExprS(e,e.line);
                    }
                    expect(TokType.SEMI); return new ExprS(e,e.line);
                }
            }
        }

        Stmt parseIf(){
            Tok t=next(); Expr c=parseExpr(); Block tb=parseBlock();
            Block eb=null; Stmt ei=null;
            if(at(TokType.ELSE)){next();if(at(TokType.IF))ei=parseIf();else eb=parseBlock();}
            return new IfS(c,tb,eb,ei,t.line);
        }

        List<String> parseParams(){
            List<String> ps=new ArrayList<>();
            if(!at(TokType.RPAREN)){ps.add(expect(TokType.IDENT).text);while(at(TokType.COMMA)){next();ps.add(expect(TokType.IDENT).text);}}
            return ps;
        }

        Expr parseExpr(){return parseOr();}
        Expr parseOr(){Expr l=parseAnd();while(at(TokType.OR)){Tok o=next();l=new OrE(l,parseAnd(),o.line);}return l;}
        Expr parseAnd(){Expr l=parseNot();while(at(TokType.AND)){Tok o=next();l=new AndE(l,parseNot(),o.line);}return l;}
        Expr parseNot(){if(at(TokType.NOT)){Tok o=next();return new NotE(parseNot(),o.line);}return parseCmp();}
        Expr parseCmp(){Expr l=parseAdd();while(at(TokType.EQ)||at(TokType.NEQ)||at(TokType.LT)||at(TokType.LE)||at(TokType.GT)||at(TokType.GE)){Tok o=next();l=new BinE(o.text,l,parseAdd(),o.line);}return l;}
        Expr parseAdd(){Expr l=parseMul();while(at(TokType.PLUS)||at(TokType.MINUS)){Tok o=next();l=new BinE(o.text,l,parseMul(),o.line);}return l;}
        Expr parseMul(){Expr l=parseUnary();while(at(TokType.STAR)||at(TokType.SLASH)||at(TokType.PCT)){Tok o=next();l=new BinE(o.text,l,parseUnary(),o.line);}return l;}
        Expr parseUnary(){if(at(TokType.MINUS)){Tok o=next();return new NegE(parseUnary(),o.line);}return parsePostfix();}
        Expr parsePostfix(){
            Expr e=parsePrimary();
            while(true){
                if(at(TokType.LPAREN)){Tok op=next();List<Expr> as=new ArrayList<>();if(!at(TokType.RPAREN)){as.add(parseExpr());while(at(TokType.COMMA)){next();as.add(parseExpr());}}expect(TokType.RPAREN);e=new CallE(e,as,op.line);}
                else if(at(TokType.LBRACKET)){Tok op=next();Expr ix=parseExpr();expect(TokType.RBRACKET);e=new IdxE(e,ix,op.line);}
                else break;
            }
            return e;
        }
        Expr parsePrimary(){
            Tok t=peek();
            switch(t.type){
                case INT:next();return new IntLit(t.ival,t.line);
                case STR:next();return new StrLit(t.sval,t.line);
                case TRUE:next();return new BoolLit(true,t.line);
                case FALSE:next();return new BoolLit(false,t.line);
                case NIL:next();return new NilLit(t.line);
                case IDENT:next();return new IdentE(t.text,t.line);
                case LPAREN:{next();Expr e=parseExpr();expect(TokType.RPAREN);return e;}
                case LBRACKET:{next();List<Expr> es=new ArrayList<>();if(!at(TokType.RBRACKET)){es.add(parseExpr());while(at(TokType.COMMA)){next();es.add(parseExpr());}}expect(TokType.RBRACKET);return new ListE(es,t.line);}
                case FN:{next();expect(TokType.LPAREN);List<String> ps=parseParams();expect(TokType.RPAREN);Block b=parseBlock();return new FnE(ps,b,t.line);}
                default:next();return new NilLit(t.line);
            }
        }
    }

    // ---- Runtime ----
    static class Scope {
        HashMap<String,Object> vars=new HashMap<>();
        Scope parent;
        Scope(Scope p){parent=p;}
        boolean has(String n){Scope s=this;while(s!=null){if(s.vars.containsKey(n))return true;s=s.parent;}return false;}
        Object get(String n){Scope s=this;while(s!=null){if(s.vars.containsKey(n))return s.vars.get(n);s=s.parent;}return null;}
        void define(String n,Object v){vars.put(n,v);}
        void assign(String n,Object v){Scope s=this;while(s!=null){if(s.vars.containsKey(n)){s.vars.put(n,v);return;}s=s.parent;}}
    }

    abstract static class Fn{abstract Object call(List<Object> args,int line);}
    static class UserFn extends Fn{
        List<String> params; Block body; Scope cap;
        UserFn(List<String> p,Block b,Scope c){params=p;body=b;cap=c;}
        Object call(List<Object> args,int line){
            if(args.size()!=params.size()) throw new TernErr("expected "+params.size()+" arguments, got "+args.size(),line);
            Scope sc=new Scope(cap);
            for(int i=0;i<params.size();i++) sc.define(params.get(i),args.get(i));
            try{execBlock(body,sc);}catch(RetSig r){return r.val;}
            return null;
        }
    }
    static class BuiltinFn extends Fn{
        String name; int arity; BImpl impl;
        BuiltinFn(String n,int a,BImpl i){name=n;arity=a;impl=i;}
        Object call(List<Object> args,int line){
            if(arity>=0&&args.size()!=arity) throw new TernErr("expected "+arity+" arguments, got "+args.size(),line);
            return impl.apply(args,line);
        }
    }
    interface BImpl{Object apply(List<Object> args,int line);}

    static class TernErr extends RuntimeException{int line;TernErr(String m,int l){super(m);line=l;}}
    static class BrkSig extends Exception{}
    static class ContSig extends Exception{}
    static class RetSig extends Exception{Object val;RetSig(Object v){val=v;}}

    static StringBuilder out=new StringBuilder();

    static boolean truthy(Object v){
        if(v==null)return false;
        if(v instanceof Boolean)return(Boolean)v;
        if(v instanceof Long)return(Long)v!=0;
        if(v instanceof String)return!((String)v).isEmpty();
        if(v instanceof List)return!((List<?>)v).isEmpty();
        return true;
    }

    static String tname(Object v){
        if(v==null)return"nil";
        if(v instanceof Long)return"int";
        if(v instanceof Boolean)return"bool";
        if(v instanceof String)return"string";
        if(v instanceof List)return"list";
        if(v instanceof Fn)return"function";
        return"unknown";
    }

    static String disp(Object v,boolean inner,Set<List> vis){
        if(v==null)return"nil";
        if(v instanceof Boolean)return(Boolean)v?"true":"false";
        if(v instanceof Long)return v.toString();
        if(v instanceof String){if(inner)return quote((String)v);return(String)v;}
        if(v instanceof List){
            @SuppressWarnings("unchecked") List<Object> l=(List<Object>)v;
            if(vis.contains(l))return"[...]";
            vis.add(l);
            StringBuilder sb=new StringBuilder("[");
            for(int i=0;i<l.size();i++){if(i>0)sb.append(", ");sb.append(disp(l.get(i),true,vis));}
            sb.append("]"); vis.remove(l); return sb.toString();
        }
        if(v instanceof Fn)return"<fn>";
        return"???";
    }
    static String disp(Object v){return disp(v,false,newIdentitySet());}
    static Set<List> newIdentitySet(){return Collections.newSetFromMap(new IdentityHashMap<>());}

    static String quote(String s){
        StringBuilder sb=new StringBuilder("\"");
        for(int i=0;i<s.length();i++){char c=s.charAt(i);
            if(c=='\\')sb.append("\\\\");else if(c=='"')sb.append("\\\"");
            else if(c=='\n')sb.append("\\n");else if(c=='\t')sb.append("\\t");
            else sb.append(c);}
        sb.append("\"");return sb.toString();
    }

    static boolean ternEq(Object a,Object b){
        if(a==null&&b==null)return true;
        if(a==null||b==null)return false;
        if(a instanceof Long&&b instanceof Long)return a.equals(b);
        if(a instanceof Boolean&&b instanceof Boolean)return a.equals(b);
        if(a instanceof String&&b instanceof String)return a.equals(b);
        if(a instanceof List&&b instanceof List){
            List<Object> la=(List<Object>)a,lb=(List<Object>)b;
            if(la.size()!=lb.size())return false;
            for(int i=0;i<la.size();i++)if(!ternEq(la.get(i),lb.get(i)))return false;
            return true;
        }
        if(a instanceof Fn&&b instanceof Fn)return a==b;
        return false;
    }

    static Object eval(Expr e,Scope sc){
        if(e instanceof IntLit)return((IntLit)e).v;
        if(e instanceof StrLit)return((StrLit)e).v;
        if(e instanceof BoolLit)return((BoolLit)e).v;
        if(e instanceof NilLit)return null;
        if(e instanceof IdentE){
            IdentE id=(IdentE)e;
            if(!sc.has(id.n))throw new TernErr("undefined variable "+id.n,id.line);
            return sc.get(id.n);
        }
        if(e instanceof BinE){BinE b=(BinE)e;return binOp(b.op,eval(b.l,sc),eval(b.r,sc),b.line);}
        if(e instanceof NegE){
            Object o=eval(((NegE)e).e,sc);
            if(!(o instanceof Long))throw new TernErr("cannot apply - to "+tname(o),e.line);
            long v=(Long)o;
            if(v==Long.MIN_VALUE)throw new TernErr("integer overflow",e.line);
            return-v;
        }
        if(e instanceof NotE)return!truthy(eval(((NotE)e).e,sc));
        if(e instanceof AndE){Object l=eval(((AndE)e).l,sc);return truthy(l)?eval(((AndE)e).r,sc):l;}
        if(e instanceof OrE){Object l=eval(((OrE)e).l,sc);return truthy(l)?l:eval(((OrE)e).r,sc);}
        if(e instanceof CallE){
            CallE c=(CallE)e;
            Object fn=eval(c.fn,sc);
            List<Object> args=new ArrayList<>(c.args.size());
            for(Expr a:c.args)args.add(eval(a,sc));
            if(!(fn instanceof Fn))throw new TernErr("cannot call "+tname(fn),c.line);
            return((Fn)fn).call(args,c.line);
        }
        if(e instanceof IdxE){
            IdxE ix=(IdxE)e;
            Object obj=eval(ix.obj,sc); Object idx=eval(ix.idx,sc);
            if(!(obj instanceof List)&&!(obj instanceof String))
                throw new TernErr("cannot index "+tname(obj)+" with "+tname(idx),ix.line);
            if(!(idx instanceof Long))
                throw new TernErr("cannot index "+tname(obj)+" with "+tname(idx),ix.line);
            long i=(Long)idx;
            int len=obj instanceof List?((List<?>)obj).size():((String)obj).length();
            if(i<0||i>=len)throw new TernErr("index "+i+" out of range for length "+len,ix.line);
            if(obj instanceof List)return((List<?>)obj).get((int)i);
            return String.valueOf(((String)obj).charAt((int)i));
        }
        if(e instanceof ListE){
            List<Object> res=new ArrayList<>();
            for(Expr el:((ListE)e).elems)res.add(eval(el,sc));
            return res;
        }
        if(e instanceof FnE){FnE f=(FnE)e;return new UserFn(f.params,f.body,sc);}
        throw new RuntimeException("bad expr");
    }

    static Object binOp(String op,Object a,Object b,int line){
        if(op.equals("=="))return ternEq(a,b);
        if(op.equals("!="))return!ternEq(a,b);
        if(op.equals("+")){
            if(a instanceof Long&&b instanceof Long){
                long x=(Long)a,y=(Long)b;
                if((y>0&&x>Long.MAX_VALUE-y)||(y<0&&x<Long.MIN_VALUE-y))throw new TernErr("integer overflow",line);
                return x+y;
            }
            if(a instanceof String&&b instanceof String)return(String)a+(String)b;
            if(a instanceof List&&b instanceof List){List<Object> r=new ArrayList<>((List<?>)a);r.addAll((List<?>)b);return r;}
            throw new TernErr("cannot apply + to "+tname(a)+" and "+tname(b),line);
        }
        if(op.equals("-")||op.equals("*")||op.equals("/")||op.equals("%")){
            if(!(a instanceof Long)||!(b instanceof Long))
                throw new TernErr("cannot apply "+op+" to "+tname(a)+" and "+tname(b),line);
            long x=(Long)a,y=(Long)b;
            if(op.equals("-")){
                if((y>0&&x<Long.MIN_VALUE+y)||(y<0&&x>Long.MAX_VALUE+y))throw new TernErr("integer overflow",line);
                return x-y;
            }
            if(op.equals("*")){
                if(x!=0&&y!=0){long r=x*y;if(r/x!=y)throw new TernErr("integer overflow",line);}
                return x*y;
            }
            if(op.equals("/")){
                if(y==0)throw new TernErr("division by zero",line);
                if(x==Long.MIN_VALUE&&y==-1)throw new TernErr("integer overflow",line);
                return x/y;
            }
            if(op.equals("%")){
                if(y==0)throw new TernErr("division by zero",line);
                if(y==-1)return 0L;
                return x%y;
            }
        }
        if(op.equals("<")||op.equals("<=")||op.equals(">")||op.equals(">=")){
            if(a instanceof Long&&b instanceof Long){
                long x=(Long)a,y=(Long)b;
                if(op.equals("<"))return x<y; if(op.equals("<="))return x<=y;
                if(op.equals(">"))return x>y; return x>=y;
            }
            if(a instanceof String&&b instanceof String){
                int c=((String)a).compareTo((String)b);
                if(op.equals("<"))return c<0; if(op.equals("<="))return c<=0;
                if(op.equals(">"))return c>0; return c>=0;
            }
            throw new TernErr("cannot apply "+op+" to "+tname(a)+" and "+tname(b),line);
        }
        throw new TernErr("cannot apply "+op+" to "+tname(a)+" and "+tname(b),line);
    }

    static void exec(Stmt s,Scope sc){
        if(s instanceof LetS){LetS ls=(LetS)s;sc.define(ls.n,eval(ls.v,sc));}
        else if(s instanceof FnS){FnS fs=(FnS)s;sc.define(fs.n,new UserFn(fs.params,fs.body,sc));}
        else if(s instanceof IfS){
            IfS is=(IfS)s;
            if(truthy(eval(is.cond,sc))){execBlock(is.thenB,new Scope(sc));}
            else if(is.elseB!=null){execBlock(is.elseB,new Scope(sc));}
            else if(is.elseIf!=null){exec(is.elseIf,sc);}
        }
        else if(s instanceof WhileS){
            WhileS ws=(WhileS)s;
            while(truthy(eval(ws.cond,sc))){
                try{execBlock(ws.body,new Scope(sc));}catch(BrkSig b){break;}catch(ContSig c){}
            }
        }
        else if(s instanceof ForS){
            ForS fs=(ForS)s;
            Object it=eval(fs.iter,sc);
            if(!(it instanceof List))throw new TernErr("cannot iterate "+tname(it),fs.line);
            @SuppressWarnings("unchecked") List<Object> list=(List<Object>)it;
            int i=0;
            while(i<list.size()){
                Scope isc=new Scope(sc);
                isc.define(fs.var,list.get(i));
                try{execBlock(fs.body,isc);}catch(BrkSig b){break;}catch(ContSig c){}
                i++;
            }
        }
        else if(s instanceof RetS){RetS rs=(RetS)s;throw new RetSig(rs.v!=null?eval(rs.v,sc):null);}
        else if(s instanceof BrkS)throw new BrkSig();
        else if(s instanceof ContS)throw new ContSig();
        else if(s instanceof AsgS){AsgS as=(AsgS)s;Object v=eval(as.v,sc);if(!sc.has(as.n))throw new TernErr("undefined variable "+as.n,as.line);sc.assign(as.n,v);}
        else if(s instanceof IdxAsgS){
            IdxAsgS ia=(IdxAsgS)s;
            Object obj=eval(ia.obj,sc); Object idx=eval(ia.idx,sc); Object val=eval(ia.val,sc);
            if(!(obj instanceof List))throw new TernErr("cannot assign into "+tname(obj),ia.line);
            if(!(idx instanceof Long))throw new TernErr("cannot index list with "+tname(idx),ia.line);
            long i=(Long)idx; List<Object> list=(List<Object>)obj;
            if(i<0||i>=list.size())throw new TernErr("index "+i+" out of range for length "+list.size(),ia.line);
            list.set((int)i,val);
        }
        else if(s instanceof ExprS){eval(((ExprS)s).e,sc);}
    }

    static void execBlock(Block b,Scope sc){for(Stmt s:b.stmts)exec(s,sc);}

    static Scope mkGlobals(){
        Scope g=new Scope(null);
        Scope bi=new Scope(null);
        bi.define("print",new BuiltinFn("print",-1,(args,line)->{
            StringBuilder sb=new StringBuilder();
            for(int i=0;i<args.size();i++){if(i>0)sb.append(' ');sb.append(disp(args.get(i)));}
            sb.append('\n'); out.append(sb); return null;
        }));
        bi.define("str",new BuiltinFn("str",1,(args,line)->disp(args.get(0))));
        bi.define("type",new BuiltinFn("type",1,(args,line)->tname(args.get(0))));
        bi.define("len",new BuiltinFn("len",1,(args,line)->{
            Object v=args.get(0);
            if(v instanceof String)return(long)((String)v).length();
            if(v instanceof List)return(long)((List<?>)v).size();
            throw new TernErr("bad argument to len",line);
        }));
        bi.define("push",new BuiltinFn("push",2,(args,line)->{
            Object v=args.get(0);
            if(!(v instanceof List))throw new TernErr("bad argument to push",line);
            ((List<Object>)v).add(args.get(1)); return null;
        }));
        bi.define("pop",new BuiltinFn("pop",1,(args,line)->{
            Object v=args.get(0);
            if(!(v instanceof List))throw new TernErr("bad argument to pop",line);
            List<Object> l=(List<Object>)v;
            if(l.isEmpty())throw new TernErr("bad argument to pop",line);
            return l.remove(l.size()-1);
        }));
        bi.define("range",new BuiltinFn("range",2,(args,line)->{
            Object a=args.get(0),b=args.get(1);
            if(!(a instanceof Long)||!(b instanceof Long))throw new TernErr("bad argument to range",line);
            long s=(Long)a,e=(Long)b;
            List<Object> r=new ArrayList<>();
            for(long i=s;i<e;i++)r.add(i);
            return r;
        }));
        bi.define("slice",new BuiltinFn("slice",3,(args,line)->{
            Object x=args.get(0),a=args.get(1),b=args.get(2);
            if(!(a instanceof Long)||!(b instanceof Long))throw new TernErr("bad argument to slice",line);
            long s=(Long)a,e=(Long)b;
            if(x instanceof List){
                List<Object> l=(List<Object>)x;
                if(s<0||e>l.size()||s>e)throw new TernErr("bad argument to slice",line);
                return new ArrayList<>(l.subList((int)s,(int)e));
            }
            if(x instanceof String){
                String str=(String)x;
                if(s<0||e>str.length()||s>e)throw new TernErr("bad argument to slice",line);
                return str.substring((int)s,(int)e);
            }
            throw new TernErr("bad argument to slice",line);
        }));
        g.parent=bi;
        return g;
    }

    public static void main(String[] args)throws Exception{
        String dir=args[0];
        String src=new String(Files.readAllBytes(Paths.get(dir,"program.tern")));
        List<Tok> toks=lex(src);
        Parser parser=new Parser(toks);
        List<Stmt> prog=new ArrayList<>();
        while(!parser.at(TokType.EOF))prog.add(parser.parseStmt());
        Scope gs=mkGlobals();
        try{for(Stmt s:prog)exec(s,gs);}
        catch(TernErr e){out.append("error at line ").append(e.line).append(": ").append(e.getMessage()).append('\n');}
        System.out.print(out.toString());
    }
}

import java.io.*;
import java.nio.file.*;
import java.awt.image.*;
import javax.imageio.*;
import java.util.*;

public class Main {
    static class JsonParser {
        String s;
        int pos;

        JsonParser(String s) { this.s = s; this.pos = 0; }

        void skipWhitespace() {
            while (pos < s.length() && Character.isWhitespace(s.charAt(pos))) pos++;
        }

        Object parse() {
            skipWhitespace();
            char c = s.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (c == '-' || Character.isDigit(c)) return parseNumber();
            throw new RuntimeException("Unexpected char: " + c);
        }

        Map<String, Object> parseObject() {
            Map<String, Object> map = new LinkedHashMap<>();
            pos++;
            skipWhitespace();
            if (s.charAt(pos) == '}') { pos++; return map; }
            while (true) {
                skipWhitespace();
                String key = parseString();
                skipWhitespace();
                pos++; // skip :
                Object val = parse();
                map.put(key, val);
                skipWhitespace();
                if (s.charAt(pos) == ',') { pos++; continue; }
                if (s.charAt(pos) == '}') { pos++; break; }
            }
            return map;
        }

        List<Object> parseArray() {
            List<Object> list = new ArrayList<>();
            pos++;
            skipWhitespace();
            if (s.charAt(pos) == ']') { pos++; return list; }
            while (true) {
                Object val = parse();
                list.add(val);
                skipWhitespace();
                if (s.charAt(pos) == ',') { pos++; continue; }
                if (s.charAt(pos) == ']') { pos++; break; }
            }
            return list;
        }

        String parseString() {
            pos++;
            StringBuilder sb = new StringBuilder();
            while (s.charAt(pos) != '"') {
                if (s.charAt(pos) == '\\') {
                    pos++;
                    char c = s.charAt(pos);
                    switch (c) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'n': sb.append('\n'); break;
                        case 't': sb.append('\t'); break;
                        case 'r': sb.append('\r'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'u': sb.append((char) Integer.parseInt(s.substring(pos + 1, pos + 5), 16)); pos += 4; break;
                        default: sb.append(c);
                    }
                } else {
                    sb.append(s.charAt(pos));
                }
                pos++;
            }
            pos++;
            return sb.toString();
        }

        long parseNumber() {
            int start = pos;
            if (s.charAt(pos) == '-') pos++;
            while (pos < s.length() && Character.isDigit(s.charAt(pos))) pos++;
            return Long.parseLong(s.substring(start, pos));
        }
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        String dir = args[0];
        String json = new String(Files.readAllBytes(Paths.get(dir, "scene.json")));

        JsonParser parser = new JsonParser(json);
        Map<String, Object> scene = (Map<String, Object>) parser.parse();

        int width = ((Number) scene.get("width")).intValue();
        int height = ((Number) scene.get("height")).intValue();
        List<Object> bgList = (List<Object>) scene.get("background");
        int bgR = ((Number) bgList.get(0)).intValue();
        int bgG = ((Number) bgList.get(1)).intValue();
        int bgB = ((Number) bgList.get(2)).intValue();

        int[][] canvasR = new int[height][width];
        int[][] canvasG = new int[height][width];
        int[][] canvasB = new int[height][width];
        for (int y = 0; y < height; y++) {
            Arrays.fill(canvasR[y], bgR);
            Arrays.fill(canvasG[y], bgG);
            Arrays.fill(canvasB[y], bgB);
        }

        List<Object> shapes = (List<Object>) scene.get("shapes");
        StringBuilder output = new StringBuilder();

        for (int i = 0; i < shapes.size(); i++) {
            Map<String, Object> shape = (Map<String, Object>) shapes.get(i);
            String type = (String) shape.get("type");
            List<Object> colorList = (List<Object>) shape.get("color");
            int sR = ((Number) colorList.get(0)).intValue();
            int sG = ((Number) colorList.get(1)).intValue();
            int sB = ((Number) colorList.get(2)).intValue();
            int A = ((Number) colorList.get(3)).intValue();

            int count = 0;

            for (int py = 0; py < height; py++) {
                for (int px = 0; px < width; px++) {
                    boolean covered = false;

                    switch (type) {
                        case "rect": {
                            int rx = ((Number) shape.get("x")).intValue();
                            int ry = ((Number) shape.get("y")).intValue();
                            int w = ((Number) shape.get("w")).intValue();
                            int h = ((Number) shape.get("h")).intValue();
                            covered = (px >= rx && px < rx + w && py >= ry && py < ry + h);
                            break;
                        }
                        case "circle": {
                            int cx = ((Number) shape.get("cx")).intValue();
                            int cy = ((Number) shape.get("cy")).intValue();
                            int r = ((Number) shape.get("r")).intValue();
                            long dx = (long) px - cx;
                            long dy = (long) py - cy;
                            covered = (dx * dx + dy * dy <= (long) r * r);
                            break;
                        }
                        case "triangle": {
                            List<Object> points = (List<Object>) shape.get("points");
                            int x0 = ((Number) ((List<Object>) points.get(0)).get(0)).intValue();
                            int y0 = ((Number) ((List<Object>) points.get(0)).get(1)).intValue();
                            int x1 = ((Number) ((List<Object>) points.get(1)).get(0)).intValue();
                            int y1 = ((Number) ((List<Object>) points.get(1)).get(1)).intValue();
                            int x2 = ((Number) ((List<Object>) points.get(2)).get(0)).intValue();
                            int y2 = ((Number) ((List<Object>) points.get(2)).get(1)).intValue();

                            long e0 = (long) (x1 - x0) * (py - y0) - (long) (y1 - y0) * (px - x0);
                            long e1 = (long) (x2 - x1) * (py - y1) - (long) (y2 - y1) * (px - x1);
                            long e2 = (long) (x0 - x2) * (py - y2) - (long) (y0 - y2) * (px - x2);

                            covered = (e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0);
                            break;
                        }
                        case "line": {
                            int x1 = ((Number) shape.get("x1")).intValue();
                            int y1 = ((Number) shape.get("y1")).intValue();
                            int x2 = ((Number) shape.get("x2")).intValue();
                            int y2 = ((Number) shape.get("y2")).intValue();
                            int r = ((Number) shape.get("r")).intValue();

                            long ldx = x2 - x1;
                            long ldy = y2 - y1;
                            long L = ldx * ldx + ldy * ldy;
                            long t = (long) (px - x1) * ldx + (long) (py - y1) * ldy;

                            if (t <= 0) {
                                long ddx = (long) px - x1;
                                long ddy = (long) py - y1;
                                covered = (ddx * ddx + ddy * ddy <= (long) r * r);
                            } else if (t >= L) {
                                long ddx = (long) px - x2;
                                long ddy = (long) py - y2;
                                covered = (ddx * ddx + ddy * ddy <= (long) r * r);
                            } else {
                                long c = (long) (px - x1) * ldy - (long) (py - y1) * ldx;
                                covered = (c * c <= (long) r * r * L);
                            }
                            break;
                        }
                    }

                    if (covered) {
                        count++;
                        if (A > 0) {
                            canvasR[py][px] = (sR * A + canvasR[py][px] * (255 - A) + 127) / 255;
                            canvasG[py][px] = (sG * A + canvasG[py][px] * (255 - A) + 127) / 255;
                            canvasB[py][px] = (sB * A + canvasB[py][px] * (255 - A) + 127) / 255;
                        }
                    }
                }
            }

            output.append(i + 1).append(" ").append(type).append(" ").append(count).append("\n");
        }

        Set<Integer> colorSet = new HashSet<>();
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                colorSet.add((canvasR[y][x] << 16) | (canvasG[y][x] << 8) | canvasB[y][x]);
            }
        }
        output.append("colors ").append(colorSet.size()).append("\n");

        System.out.print(output);

        BufferedImage img = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                int rgb = (canvasR[y][x] << 16) | (canvasG[y][x] << 8) | canvasB[y][x];
                img.setRGB(x, y, rgb);
            }
        }

        ImageIO.write(img, "png", new File("out.png"));
    }
}

import * as fs from 'fs';
import * as path from 'path';

// CRC-32 table
const crcTable: number[] = [];
for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) {
        c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    }
    crcTable[n] = c;
}

function crc32(data: Uint8Array): number {
    let c = 0xFFFFFFFF;
    for (let i = 0; i < data.length; i++) {
        c = crcTable[(c ^ data[i]) & 0xFF] ^ (c >>> 8);
    }
    return (c ^ 0xFFFFFFFF) >>> 0;
}

function adler32(data: Uint8Array): number {
    let s1 = 1, s2 = 0;
    for (let i = 0; i < data.length; i++) {
        s1 = (s1 + data[i]) % 65521;
        s2 = (s2 + s1) % 65521;
    }
    return ((s2 << 16) | s1) >>> 0;
}

function writeChunk(type: string, data: Uint8Array): Uint8Array {
    const typeBytes = new Uint8Array(4);
    for (let i = 0; i < 4; i++) typeBytes[i] = type.charCodeAt(i);

    const lengthBytes = new Uint8Array(4);
    lengthBytes[0] = (data.length >>> 24) & 0xFF;
    lengthBytes[1] = (data.length >>> 16) & 0xFF;
    lengthBytes[2] = (data.length >>> 8) & 0xFF;
    lengthBytes[3] = data.length & 0xFF;

    const crcInput = new Uint8Array(4 + data.length);
    crcInput.set(typeBytes, 0);
    crcInput.set(data, 4);
    const crc = crc32(crcInput);

    const crcBytes = new Uint8Array(4);
    crcBytes[0] = (crc >>> 24) & 0xFF;
    crcBytes[1] = (crc >>> 16) & 0xFF;
    crcBytes[2] = (crc >>> 8) & 0xFF;
    crcBytes[3] = crc & 0xFF;

    const result = new Uint8Array(4 + 4 + data.length + 4);
    result.set(lengthBytes, 0);
    result.set(typeBytes, 4);
    result.set(data, 8);
    result.set(crcBytes, 8 + data.length);
    return result;
}

function deflateStored(data: Uint8Array): Uint8Array {
    const parts: Uint8Array[] = [];
    let offset = 0;
    if (data.length === 0) {
        const header = new Uint8Array(5);
        header[0] = 1;
        header[1] = 0; header[2] = 0;
        header[3] = 0xFF; header[4] = 0xFF;
        parts.push(header);
    } else {
        while (offset < data.length) {
            const blockLen = Math.min(data.length - offset, 65535);
            const isLast = (offset + blockLen >= data.length) ? 1 : 0;
            const header = new Uint8Array(5);
            header[0] = isLast;
            header[1] = blockLen & 0xFF;
            header[2] = (blockLen >>> 8) & 0xFF;
            header[3] = (~blockLen) & 0xFF;
            header[4] = (~blockLen >>> 8) & 0xFF;
            parts.push(header);
            parts.push(data.slice(offset, offset + blockLen));
            offset += blockLen;
        }
    }
    const totalLen = parts.reduce((s, p) => s + p.length, 0);
    const result = new Uint8Array(totalLen);
    let pos = 0;
    for (const p of parts) {
        result.set(p, pos);
        pos += p.length;
    }
    return result;
}

// Main program
const args = process.argv.slice(2);
const dir = args[0];
const scenePath = path.join(dir, 'scene.json');
const sceneJson = fs.readFileSync(scenePath, 'utf-8');
const scene = JSON.parse(sceneJson);

const width: number = scene.width;
const height: number = scene.height;
const bg: number[] = scene.background;

// Canvas: flat array of RGB
const canvas = new Uint8Array(width * height * 3);
for (let i = 0; i < width * height; i++) {
    canvas[i * 3] = bg[0];
    canvas[i * 3 + 1] = bg[1];
    canvas[i * 3 + 2] = bg[2];
}

const shapes = scene.shapes || [];
const outputs: string[] = [];

for (let si = 0; si < shapes.length; si++) {
    const shape = shapes[si];
    const color = shape.color;
    const A = color[3];
    let count = 0;

    if (shape.type === 'rect') {
        const rx = shape.x, ry = shape.y, w = shape.w, h = shape.h;
        const x0 = Math.max(0, rx);
        const x1 = Math.min(width - 1, rx + w - 1);
        const y0 = Math.max(0, ry);
        const y1 = Math.min(height - 1, ry + h - 1);
        if (x0 <= x1 && y0 <= y1) {
            for (let y = y0; y <= y1; y++) {
                for (let x = x0; x <= x1; x++) {
                    count++;
                    if (A > 0) {
                        const idx = (y * width + x) * 3;
                        canvas[idx] = Math.floor((color[0] * A + canvas[idx] * (255 - A) + 127) / 255);
                        canvas[idx + 1] = Math.floor((color[1] * A + canvas[idx + 1] * (255 - A) + 127) / 255);
                        canvas[idx + 2] = Math.floor((color[2] * A + canvas[idx + 2] * (255 - A) + 127) / 255);
                    }
                }
            }
        }
    } else if (shape.type === 'circle') {
        const cx = shape.cx, cy = shape.cy, r = shape.r;
        const x0 = Math.max(0, cx - r);
        const x1 = Math.min(width - 1, cx + r);
        const y0 = Math.max(0, cy - r);
        const y1 = Math.min(height - 1, cy + r);
        const r2 = r * r;
        for (let y = y0; y <= y1; y++) {
            for (let x = x0; x <= x1; x++) {
                const ddx = x - cx, ddy = y - cy;
                if (ddx * ddx + ddy * ddy <= r2) {
                    count++;
                    if (A > 0) {
                        const idx = (y * width + x) * 3;
                        canvas[idx] = Math.floor((color[0] * A + canvas[idx] * (255 - A) + 127) / 255);
                        canvas[idx + 1] = Math.floor((color[1] * A + canvas[idx + 1] * (255 - A) + 127) / 255);
                        canvas[idx + 2] = Math.floor((color[2] * A + canvas[idx + 2] * (255 - A) + 127) / 255);
                    }
                }
            }
        }
    } else if (shape.type === 'triangle') {
        const pts = shape.points;
        const px0 = pts[0][0], py0 = pts[0][1];
        const px1 = pts[1][0], py1 = pts[1][1];
        const px2 = pts[2][0], py2 = pts[2][1];
        const bx0 = Math.max(0, Math.min(px0, px1, px2));
        const bx1 = Math.min(width - 1, Math.max(px0, px1, px2));
        const by0 = Math.max(0, Math.min(py0, py1, py2));
        const by1 = Math.min(height - 1, Math.max(py0, py1, py2));
        for (let y = by0; y <= by1; y++) {
            for (let x = bx0; x <= bx1; x++) {
                const e0 = (px1 - px0) * (y - py0) - (py1 - py0) * (x - px0);
                const e1 = (px2 - px1) * (y - py1) - (py2 - py1) * (x - px1);
                const e2 = (px0 - px2) * (y - py2) - (py0 - py2) * (x - px2);
                if ((e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0)) {
                    count++;
                    if (A > 0) {
                        const idx = (y * width + x) * 3;
                        canvas[idx] = Math.floor((color[0] * A + canvas[idx] * (255 - A) + 127) / 255);
                        canvas[idx + 1] = Math.floor((color[1] * A + canvas[idx + 1] * (255 - A) + 127) / 255);
                        canvas[idx + 2] = Math.floor((color[2] * A + canvas[idx + 2] * (255 - A) + 127) / 255);
                    }
                }
            }
        }
    } else if (shape.type === 'line') {
        const lx1 = shape.x1, ly1 = shape.y1, lx2 = shape.x2, ly2 = shape.y2, r = shape.r;
        const bx0 = Math.max(0, Math.min(lx1, lx2) - r);
        const bx1 = Math.min(width - 1, Math.max(lx1, lx2) + r);
        const by0 = Math.max(0, Math.min(ly1, ly2) - r);
        const by1 = Math.min(height - 1, Math.max(ly1, ly2) + r);
        const dx = lx2 - lx1, dy = ly2 - ly1;
        const L = dx * dx + dy * dy;
        const r2 = r * r;
        for (let y = by0; y <= by1; y++) {
            for (let x = bx0; x <= bx1; x++) {
                let covered = false;
                if (L === 0) {
                    const ddx = x - lx1, ddy = y - ly1;
                    covered = ddx * ddx + ddy * ddy <= r2;
                } else {
                    const t = (x - lx1) * dx + (y - ly1) * dy;
                    if (t <= 0) {
                        const ddx = x - lx1, ddy = y - ly1;
                        covered = ddx * ddx + ddy * ddy <= r2;
                    } else if (t >= L) {
                        const ddx = x - lx2, ddy = y - ly2;
                        covered = ddx * ddx + ddy * ddy <= r2;
                    } else {
                        const c = (x - lx1) * dy - (y - ly1) * dx;
                        covered = c * c <= r2 * L;
                    }
                }
                if (covered) {
                    count++;
                    if (A > 0) {
                        const idx = (y * width + x) * 3;
                        canvas[idx] = Math.floor((color[0] * A + canvas[idx] * (255 - A) + 127) / 255);
                        canvas[idx + 1] = Math.floor((color[1] * A + canvas[idx + 1] * (255 - A) + 127) / 255);
                        canvas[idx + 2] = Math.floor((color[2] * A + canvas[idx + 2] * (255 - A) + 127) / 255);
                    }
                }
            }
        }
    }

    outputs.push(`${si + 1} ${shape.type} ${count}`);
}

// Count distinct colors
const colorSet = new Set<number>();
for (let i = 0; i < width * height; i++) {
    const r = canvas[i * 3], g = canvas[i * 3 + 1], b = canvas[i * 3 + 2];
    colorSet.add((r << 16) | (g << 8) | b);
}
outputs.push(`colors ${colorSet.size}`);

// Write output
process.stdout.write(outputs.join('\n') + '\n');

// Build PNG
const signature = new Uint8Array([137, 80, 78, 71, 13, 10, 26, 10]);

// IHDR
const ihdrData = new Uint8Array(13);
ihdrData[0] = (width >>> 24) & 0xFF;
ihdrData[1] = (width >>> 16) & 0xFF;
ihdrData[2] = (width >>> 8) & 0xFF;
ihdrData[3] = width & 0xFF;
ihdrData[4] = (height >>> 24) & 0xFF;
ihdrData[5] = (height >>> 16) & 0xFF;
ihdrData[6] = (height >>> 8) & 0xFF;
ihdrData[7] = height & 0xFF;
ihdrData[8] = 8;   // bit depth
ihdrData[9] = 2;   // color type RGB
ihdrData[10] = 0;  // compression method
ihdrData[11] = 0;  // filter method
ihdrData[12] = 0;  // interlace method

// Raw image data with filter bytes
const rawSize = height * (1 + width * 3);
const rawData = new Uint8Array(rawSize);
let pos = 0;
for (let y = 0; y < height; y++) {
    rawData[pos++] = 0; // filter type None
    for (let x = 0; x < width; x++) {
        const idx = (y * width + x) * 3;
        rawData[pos++] = canvas[idx];
        rawData[pos++] = canvas[idx + 1];
        rawData[pos++] = canvas[idx + 2];
    }
}

// Zlib compress with stored blocks
const compressed = deflateStored(rawData);
const adler = adler32(rawData);

const zlibData = new Uint8Array(2 + compressed.length + 4);
zlibData[0] = 0x78; // CMF: deflate, 32K window
zlibData[1] = 0x01; // FLG: FCHECK makes CMF*256+FLG divisible by 31
for (let i = 0; i < compressed.length; i++) {
    zlibData[2 + i] = compressed[i];
}
zlibData[2 + compressed.length] = (adler >>> 24) & 0xFF;
zlibData[2 + compressed.length + 1] = (adler >>> 16) & 0xFF;
zlibData[2 + compressed.length + 2] = (adler >>> 8) & 0xFF;
zlibData[2 + compressed.length + 3] = adler & 0xFF;

// Assemble PNG
const ihdrChunk = writeChunk('IHDR', ihdrData);
const idatChunk = writeChunk('IDAT', zlibData);
const iendChunk = writeChunk('IEND', new Uint8Array(0));

const pngSize = signature.length + ihdrChunk.length + idatChunk.length + iendChunk.length;
const png = new Uint8Array(pngSize);
let p = 0;
png.set(signature, p); p += signature.length;
png.set(ihdrChunk, p); p += ihdrChunk.length;
png.set(idatChunk, p); p += idatChunk.length;
png.set(iendChunk, p); p += iendChunk.length;

