                }
            } else {
                int byteIdx = bitPos / 8;
                int bitInByte = bitPos % 8;
                int b = recon[row * scanBytes + byteIdx] & 0xFF;
                int shift = 8 - bitInByte - depth;
                int mask = (1 << depth) - 1;
                samples[c] = (b >> shift) & mask;
            }
            bitPos += depth;
        }
        return samples;
    }

    public static void main(String[] args) throws Exception {
        Path dir = Paths.get(args[0]);
        List<Path> files = new ArrayList<>();
        try (DirectoryStream<Path> ds = Files.newDirectoryStream(dir)) {
            for (Path p : ds) {
                if (Files.isRegularFile(p) && p.getFileName().toString().endsWith(".png"))
                    files.add(p);
            }
        }
        files.sort((a, b) -> {
            byte[] ab = a.getFileName().toString().getBytes(StandardCharsets.ISO_8859_1);
            byte[] bb = b.getFileName().toString().getBytes(StandardCharsets.ISO_8859_1);
            return Arrays.compare(ab, bb);
        });

        for (Path file : files) {
            byte[] raw = Files.readAllBytes(file);
            String fname = file.getFileName().toString();
            System.out.println("== " + fname);

            int pos = 8;
            List<String> types = new ArrayList<>();
            List<byte[]> datas = new ArrayList<>();
            boolean crcErr = false;
            int crcChunk = -1;
            String crcType = "";
            int chunkNum = 0;

            while (pos + 8 <= raw.length) {
                int len = (raw[pos] & 0xFF) << 24 | (raw[pos + 1] & 0xFF) << 16 |
                          (raw[pos + 2] & 0xFF) << 8 | (raw[pos + 3] & 0xFF);
                String type = new String(raw, pos + 4, 4, StandardCharsets.ISO_8859_1);
                byte[] cd = Arrays.copyOfRange(raw, pos + 8, pos + 8 + len);
                int storedCrc = (raw[pos + 8 + len] & 0xFF) << 24 | (raw[pos + 8 + len + 1] & 0xFF) << 16 |
                               (raw[pos + 8 + len + 2] & 0xFF) << 8 | (raw[pos + 8 + len + 3] & 0xFF);
                CRC32 crc = new CRC32();
                crc.update(raw, pos + 4, 4 + len);
                chunkNum++;
                if ((int) crc.getValue() != storedCrc && !crcErr) {
                    crcErr = true; crcChunk = chunkNum; crcType = type;
                }
                types.add(type);
                datas.add(cd);
                pos += 12 + len;
                if (type.equals("IEND")) break;
            }

            if (crcErr) {
                System.out.println("error: CRC mismatch in chunk " + crcChunk + " " + crcType);
                continue;
            }

            byte[] ih = datas.get(0);
            int W = (ih[0] & 0xFF) << 24 | (ih[1] & 0xFF) << 16 | (ih[2] & 0xFF) << 8 | (ih[3] & 0xFF);
            int H = (ih[4] & 0xFF) << 24 | (ih[5] & 0xFF) << 16 | (ih[6] & 0xFF) << 8 | (ih[7] & 0xFF);
            int depth = ih[8] & 0xFF;
            int ct = ih[9] & 0xFF;

            System.out.println("IHDR " + W + "x" + H + " depth=" + depth + " color=" + ct);

            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < types.size(); i++) {
                if (sb.length() > 0) sb.append(' ');
                String t = types.get(i);
                int cnt = 1;
                while (i + 1 < types.size() && types.get(i + 1).equals(t)) { cnt++; i++; }
                sb.append(t);
                if (cnt > 1) sb.append('*').append(cnt);
            }
            System.out.println("chunks " + sb);

            ByteArrayOutputStream idat = new ByteArrayOutputStream();
            for (int i = 0; i < types.size(); i++) {
                if (types.get(i).equals("IDAT")) idat.write(datas.get(i));
            }
            byte[] comp = idat.toByteArray();

            int[] bc = new int[3];
            BitReader br = new BitReader(comp, 2);
            byte[] decompressed = inflate(br, bc);

            int storedAdler = (comp[comp.length - 4] & 0xFF) << 24 | (comp[comp.length - 3] & 0xFF) << 16 |
                              (comp[comp.length - 2] & 0xFF) << 8 | (comp[comp.length - 1] & 0xFF);
            int calcAdler = adler32(decompressed, decompressed.length);
            if (storedAdler != calcAdler) {
                System.out.println("error: Adler-32 mismatch");
                continue;
            }

            System.out.println("deflate stored=" + bc[0] + " fixed=" + bc[1] + " dynamic=" + bc[2]);

            int ch = channels(ct);
            int bitsPerPixel = ch * depth;
            int scanBytes = (W * bitsPerPixel + 7) / 8;
            int bpp = Math.max(1, (bitsPerPixel + 7) / 8);
            int[] filtCount = new int[5];

            byte[] recon = new byte[H * scanBytes];
            int dp = 0;
            for (int row = 0; row < H; row++) {
                int ft = decompressed[dp++] & 0xFF;
                filtCount[ft]++;
                int rowOff = row * scanBytes;
                int prevOff = (row - 1) * scanBytes;
                for (int x = 0; x < scanBytes; x++) {
                    int f = decompressed[dp++] & 0xFF;
                    int a = (x >= bpp) ? (recon[rowOff + x - bpp] & 0xFF) : 0;
                    int b = (row > 0) ? (recon[prevOff + x] & 0xFF) : 0;
                    int c = (row > 0 && x >= bpp) ? (recon[prevOff + x - bpp] & 0xFF) : 0;
                    int val;
                    switch (ft) {
                        case 0: val = f; break;
                        case 1: val = (f + a) & 0xFF; break;
                        case 2: val = (f + b) & 0xFF; break;
                        case 3: val = (f + (a + b) / 2) & 0xFF; break;
                        case 4:
                            int p = a + b - c;
                            int pa = Math.abs(p - a), pb = Math.abs(p - b), pc = Math.abs(p - c);
                            val = (f + ((pa <= pb && pa <= pc) ? a : (pb <= pc) ? b : c)) & 0xFF;
                            break;
                        default: val = f;
                    }
                    recon[rowOff + x] = (byte) val;
                }
            }

            System.out.println("filters none=" + filtCount[0] + " sub=" + filtCount[1] + " up=" + filtCount[2] +
                              " average=" + filtCount[3] + " paeth=" + filtCount[4]);

            byte[] plte = null;
            byte[] trns = null;
            for (int i = 0; i < types.size(); i++) {
                if (types.get(i).equals("PLTE")) plte = datas.get(i);
                if (types.get(i).equals("tRNS")) trns = datas.get(i);
            }

            long[] sums = new long[4];
            byte[] rgbaBuf = new byte[W * H * 4];
            int rp = 0;

            for (int row = 0; row < H; row++) {
                for (int col = 0; col < W; col++) {
                    int[] samples = extractSamples(recon, row, col, ch, depth, scanBytes);
                    int R, G, B, A;

                    if (ct == 0) {
                        int gray = samples[0];
                        int g8 = convertGray(gray, depth);
                        R = G = B = g8;
                        if (trns != null) {
                            int tv = ((trns[0] & 0xFF) << 8) | (trns[1] & 0xFF);
                            A = (gray == tv) ? 0 : 255;
                        } else A = 255;
                    } else if (ct == 2) {
                        R = convertSample(samples[0], depth);
                        G = convertSample(samples[1], depth);
                        B = convertSample(samples[2], depth);
                        if (trns != null) {
                            int tr = ((trns[0] & 0xFF) << 8) | (trns[1] & 0xFF);
                            int tg = ((trns[2] & 0xFF) << 8) | (trns[3] & 0xFF);
                            int tb = ((trns[4] & 0xFF) << 8) | (trns[5] & 0xFF);
                            A = (samples[0] == tr && samples[1] == tg && samples[2] == tb) ? 0 : 255;
                        } else A = 255;
                    } else if (ct == 3) {
                        int idx = samples[0];
                        R = plte[idx * 3] & 0xFF;
                        G = plte[idx * 3 + 1] & 0xFF;
                        B = plte[idx * 3 + 2] & 0xFF;
                        if (trns != null && idx < trns.length) A = trns[idx] & 0xFF;
                        else A = 255;
                    } else if (ct == 4) {
                        R = G = B = convertGray(samples[0], depth);
                        A = convertGray(samples[1], depth);
                    } else {
                        R = convertSample(samples[0], depth);
                        G = convertSample(samples[1], depth);
                        B = convertSample(samples[2], depth);
                        A = convertSample(samples[3], depth);
                    }

                    rgbaBuf[rp++] = (byte) R;
                    rgbaBuf[rp++] = (byte) G;
                    rgbaBuf[rp++] = (byte) B;
                    rgbaBuf[rp++] = (byte) A;
                    sums[0] += R; sums[1] += G; sums[2] += B; sums[3] += A;
                }
            }

            CRC32 rcrc = new CRC32();
            rcrc.update(rgbaBuf);
            System.out.println("rgba sum=" + sums[0] + "," + sums[1] + "," + sums[2] + "," + sums[3] +
                              " crc32=" + String.format("%08x", rcrc.getValue()));
        }
    }
}

use std::collections::HashMap;
use std::rc::Rc;
use std::cell::RefCell;
use std::io::{self, Write};
use std::env;
use std::process;
use std::path::Path;

// ============ TOKENS ============

#[derive(Debug, Clone, PartialEq)]
enum TokKind {
    IntLit, StrLit, Ident,
    Let, Fn, If, Else, While, For, In, Return, Break, Continue,
    And, Or, Not, True, False, Nil,
    Eq, Ne, Lt, Le, Gt, Ge,
    Assign, Plus, Minus, Star, Slash, Percent,
    LParen, RParen, LBracket, RBracket, LBrace, RBrace,
    Comma, Semicolon,
    EOF,
}

#[derive(Debug, Clone)]
struct Token {
    kind: TokKind,
    line: usize,
    text: String,
}

// ============ LEXER ============

fn tokenize(src: &str) -> Vec<Token> {
    let bytes = src.as_bytes();
    let mut tokens = Vec::new();
    let mut pos = 0;
    let mut line = 1usize;
    while pos < bytes.len() {
        let c = bytes[pos];
        if c == b' ' || c == b'\t' || c == b'\r' { pos += 1; continue; }
        if c == b'\n' { line += 1; pos += 1; continue; }
        if c == b'#' { while pos < bytes.len() && bytes[pos] != b'\n' { pos += 1; } continue; }
        let sl = line;
        if c.is_ascii_digit() {
            let s = pos;
            while pos < bytes.len() && bytes[pos].is_ascii_digit() { pos += 1; }
            tokens.push(Token { kind: TokKind::IntLit, line: sl, text: String::from_utf8_lossy(&bytes[s..pos]).into_owned() });
            continue;
        }
        if c == b'"' {
            pos += 1;
            let mut s = String::new();
            while pos < bytes.len() && bytes[pos] != b'"' {
                if bytes[pos] == b'\\' {
                    pos += 1;
                    match bytes[pos] {
                        b'n' => s.push('\n'),
                        b't' => s.push('\t'),
                        b'"' => s.push('"'),
                        b'\\' => s.push('\\'),
                        _ => s.push(bytes[pos] as char),
                    }
                } else { s.push(bytes[pos] as char); }
                pos += 1;
            }
            pos += 1;
            tokens.push(Token { kind: TokKind::StrLit, line: sl, text: s });
            continue;
        }
        if c.is_ascii_alphabetic() || c == b'_' {
            let s = pos;
            while pos < bytes.len() && (bytes[pos].is_ascii_alphanumeric() || bytes[pos] == b'_') { pos += 1; }
            let txt: String = String::from_utf8_lossy(&bytes[s..pos]).into_owned();
            let kind = match txt.as_str() {
                "let" => TokKind::Let, "fn" => TokKind::Fn, "if" => TokKind::If,
                "else" => TokKind::Else, "while" => TokKind::While, "for" => TokKind::For,
                "in" => TokKind::In, "return" => TokKind::Return, "break" => TokKind::Break,
                "continue" => TokKind::Continue, "and" => TokKind::And, "or" => TokKind::Or,
                "not" => TokKind::Not, "true" => TokKind::True, "false" => TokKind::False,
                "nil" => TokKind::Nil, _ => TokKind::Ident,
            };
            tokens.push(Token { kind, line: sl, text: txt });
            continue;
        }
        let next = if pos + 1 < bytes.len() { bytes[pos + 1] } else { 0 };
        let (kind, len) = match (c, next) {
            (b'=', b'=') => (TokKind::Eq, 2),
            (b'!', b'=') => (TokKind::Ne, 2),
            (b'<', b'=') => (TokKind::Le, 2),
            (b'>', b'=') => (TokKind::Ge, 2),
            (b'<', _) => (TokKind::Lt, 1),
            (b'>', _) => (TokKind::Gt, 1),
            (b'=', _) => (TokKind::Assign, 1),
            (b'+', _) => (TokKind::Plus, 1),
            (b'-', _) => (TokKind::Minus, 1),
            (b'*', _) => (TokKind::Star, 1),
            (b'/', _) => (TokKind::Slash, 1),
            (b'%', _) => (TokKind::Percent, 1),
            (b'(', _) => (TokKind::LParen, 1),
            (b')', _) => (TokKind::RParen, 1),
            (b'[', _) => (TokKind::LBracket, 1),
            (b']', _) => (TokKind::RBracket, 1),
            (b'{', _) => (TokKind::LBrace, 1),
            (b'}', _) => (TokKind::RBrace, 1),
            (b',', _) => (TokKind::Comma, 1),
            (b';', _) => (TokKind::Semicolon, 1),
            _ => { pos += 1; continue; }
        };
        tokens.push(Token { kind, line: sl, text: String::from_utf8_lossy(&bytes[pos..pos+len]).into_owned() });
        pos += len;
    }
    tokens.push(Token { kind: TokKind::EOF, line, text: String::new() });
    tokens
}

// ============ AST ============

#[derive(Debug, Clone, Copy, PartialEq)]
enum BinOp { Add, Sub, Mul, Div, Mod, Eq, Ne, Lt, Le, Gt, Ge, And, Or }

#[derive(Debug, Clone, Copy, PartialEq)]
enum UnOp { Neg, Not }

#[derive(Debug, Clone)]
enum Expr {
    IntLit(i64),
    StrLit(String),
    BoolLit(bool),
    NilLit,
    Ident(String, usize),
    Binary(BinOp, Box<Expr>, Box<Expr>, usize),
    Unary(UnOp, Box<Expr>, usize),
    Call(Box<Expr>, Vec<Expr>, usize),
    Index(Box<Expr>, Box<Expr>, usize),
    ListLit(Vec<Expr>),
    FnExpr(Vec<String>, Vec<Stmt>),
}

#[derive(Debug, Clone)]
enum ElseClause {
    Block(Vec<Stmt>),
    If(Stmt),
}

#[derive(Debug, Clone)]
enum Stmt {
    Let(String, Expr),
    FnDecl(String, Vec<String>, Vec<Stmt>),
    If(Expr, Vec<Stmt>, Option<ElseClause>),
    While(Expr, Vec<Stmt>, usize),
    For(String, Expr, Vec<Stmt>, usize),
    Return(Option<Expr>, usize),
    Break(usize),
    Continue(usize),
    Assign(String, Expr),
    IndexAssign(Box<Expr>, Expr, Expr, usize),
    ExprStmt(Expr),
}

// ============ PARSER ============

struct Parser { tokens: Vec<Token>, pos: usize }

impl Parser {
    fn new(tokens: Vec<Token>) -> Self { Parser { tokens, pos: 0 } }
    fn peek(&self) -> &Token { &self.tokens[self.pos] }
    fn advance(&mut self) -> Token { let t = self.tokens[self.pos].clone(); self.pos += 1; t }
    fn expect(&mut self, k: TokKind) -> Token { self.advance() }

    fn parse_program(&mut self) -> Vec<Stmt> {
        let mut s = Vec::new();
        while self.peek().kind != TokKind::EOF { s.push(self.parse_stmt()); }
        s
    }

    fn parse_block(&mut self) -> Vec<Stmt> {
        self.expect(TokKind::LBrace);
        let mut s = Vec::new();
        while self.peek().kind != TokKind::RBrace { s.push(self.parse_stmt()); }
        self.expect(TokKind::RBrace);
        s
    }

    fn parse_params(&mut self) -> Vec<String> {
        self.expect(TokKind::LParen);
        let mut p = Vec::new();
        if self.peek().kind != TokKind::RParen {
            p.push(self.expect(TokKind::Ident).text);
            while self.peek().kind == TokKind::Comma { self.advance(); p.push(self.expect(TokKind::Ident).text); }
        }
        self.expect(TokKind::RParen);
        p
    }

    fn parse_stmt(&mut self) -> Stmt {
        match self.peek().kind {
            TokKind::Let => {
                self.advance();
                let name = self.expect(TokKind::Ident).text;
                self.expect(TokKind::Assign);
                let e = self.parse_expr();
                self.expect(TokKind::Semicolon);
                Stmt::Let(name, e)
            }
            TokKind::Fn => {
                self.advance();
                let name = self.expect(TokKind::Ident).text;
                let params = self.parse_params();
                let body = self.parse_block();
                Stmt::FnDecl(name, params, body)
            }
            TokKind::If => {
                self.advance();
                let cond = self.parse_expr();
                let body = self.parse_block();
                let ec = if self.peek().kind == TokKind::Else {
                    self.advance();
                    if self.peek().kind == TokKind::If {
                        Some(ElseClause::If(self.parse_stmt()))
                    } else {
                        Some(ElseClause::Block(self.parse_block()))
                    }
                } else { None };
                Stmt::If(cond, body, ec)
            }
            TokKind::While => {
                let ln = self.peek().line; self.advance();
                let cond = self.parse_expr();
                let body = self.parse_block();
                Stmt::While(cond, body, ln)
            }
            TokKind::For => {
                let ln = self.peek().line; self.advance();
                let var = self.expect(TokKind::Ident).text;
                self.expect(TokKind::In);
                let e = self.parse_expr();
                let body = self.parse_block();
                Stmt::For(var, e, body, ln)
            }
            TokKind::Return => {
                let ln = self.peek().line; self.advance();
                let e = if self.peek().kind == TokKind::Semicolon { None } else { Some(self.parse_expr()) };
                self.expect(TokKind::Semicolon);
                Stmt::Return(e, ln)
            }
            TokKind::Break => { let ln = self.peek().line; self.advance(); self.expect(TokKind::Semicolon); Stmt::Break(ln) }
            TokKind::Continue => { let ln = self.peek().line; self.advance(); self.expect(TokKind::Semicolon); Stmt::Continue(ln) }
            _ => {
                let e = self.parse_expr();
                if self.peek().kind == TokKind::Assign {
                    self.advance();
                    let val = self.parse_expr();
                    self.expect(TokKind::Semicolon);
                    match e {
                        Expr::Ident(name, _) => Stmt::Assign(name, val),
                        Expr::Index(obj, idx, ln) => Stmt::IndexAssign(obj, *idx, val, ln),
                        _ => unreachable!(),
                    }
                } else {
                    self.expect(TokKind::Semicolon);
                    Stmt::ExprStmt(e)
                }
            }
        }
    }

    fn parse_expr(&mut self) -> Expr { self.parse_or() }
    fn parse_or(&mut self) -> Expr {
        let mut l = self.parse_and();
        while self.peek().kind == TokKind::Or { let ln = self.peek().line; self.advance(); let r = self.parse_and(); l = Expr::Binary(BinOp::Or, Box::new(l), Box::new(r), ln); }
        l
    }
    fn parse_and(&mut self) -> Expr {
        let mut l = self.parse_not();
        while self.peek().kind == TokKind::And { let ln = self.peek().line; self.advance(); let r = self.parse_not(); l = Expr::Binary(BinOp::And, Box::new(l), Box::new(r), ln); }
        l
    }
    fn parse_not(&mut self) -> Expr {
        if self.peek().kind == TokKind::Not { let ln = self.peek().line; self.advance(); let e = self.parse_not(); Expr::Unary(UnOp::Not, Box::new(e), ln) }
        else { self.parse_cmp() }
    }
    fn parse_cmp(&mut self) -> Expr {
        let mut l = self.parse_add();
        loop {
            let op = match self.peek().kind {
                TokKind::Eq => BinOp::Eq, TokKind::Ne => BinOp::Ne,
                TokKind::Lt => BinOp::Lt, TokKind::Le => BinOp::Le,
                TokKind::Gt => BinOp::Gt, TokKind::Ge => BinOp::Ge,
                _ => break,
            };
            let ln = self.peek().line; self.advance();
            let r = self.parse_add();
            l = Expr::Binary(op, Box::new(l), Box::new(r), ln);
        }
        l
    }
    fn parse_add(&mut self) -> Expr {
        let mut l = self.parse_mul();
        loop {
            let op = match self.peek().kind { TokKind::Plus => BinOp::Add, TokKind::Minus => BinOp::Sub, _ => break };
            let ln = self.peek().line; self.advance();
            let r = self.parse_mul();
            l = Expr::Binary(op, Box::new(l), Box::new(r), ln);
        }
        l
    }
    fn parse_mul(&mut self) -> Expr {
        let mut l = self.parse_unary();
        loop {
            let op = match self.peek().kind { TokKind::Star => BinOp::Mul, TokKind::Slash => BinOp::Div, TokKind::Percent => BinOp::Mod, _ => break };
            let ln = self.peek().line; self.advance();
            let r = self.parse_unary();
            l = Expr::Binary(op, Box::new(l), Box::new(r), ln);
        }
        l
    }
    fn parse_unary(&mut self) -> Expr {
        if self.peek().kind == TokKind::Minus { let ln = self.peek().line; self.advance(); let e = self.parse_unary(); Expr::Unary(UnOp::Neg, Box::new(e), ln) }
        else { self.parse_postfix() }
    }
    fn parse_postfix(&mut self) -> Expr {
        let mut e = self.parse_primary();
        loop {
            match self.peek().kind {
                TokKind::LParen => {
                    let ln = self.peek().line; self.advance();
                    let mut args = Vec::new();
                    if self.peek().kind != TokKind::RParen {
                        args.push(self.parse_expr());
                        while self.peek().kind == TokKind::Comma { self.advance(); args.push(self.parse_expr()); }
                    }
                    self.expect(TokKind::RParen);
                    e = Expr::Call(Box::new(e), args, ln);
                }
                TokKind::LBracket => {
                    let ln = self.peek().line; self.advance();
                    let idx = self.parse_expr();
                    self.expect(TokKind::RBracket);
                    e = Expr::Index(Box::new(e), Box::new(idx), ln);
                }
                _ => break,
            }
        }
        e
    }
    fn parse_primary(&mut self) -> Expr {
        match self.peek().kind {
            TokKind::IntLit => { let t = self.advance(); Expr::IntLit(t.text.parse::<i64>().unwrap()) }
            TokKind::StrLit => { let t = self.advance(); Expr::StrLit(t.text) }
            TokKind::True => { self.advance(); Expr::BoolLit(true) }
            TokKind::False => { self.advance(); Expr::BoolLit(false) }
            TokKind::Nil => { self.advance(); Expr::NilLit }
            TokKind::Ident => { let t = self.advance(); Expr::Ident(t.text, t.line) }
            TokKind::LParen => { self.advance(); let e = self.parse_expr(); self.expect(TokKind::RParen); e }
            TokKind::LBracket => {
                self.advance();
                let mut elems = Vec::new();
                if self.peek().kind != TokKind::RBracket {
                    elems.push(self.parse_expr());
                    while self.peek().kind == TokKind::Comma { self.advance(); elems.push(self.parse_expr()); }
                }
                self.expect(TokKind::RBracket);
                Expr::ListLit(elems)
            }
            TokKind::Fn => { self.advance(); let params = self.parse_params(); let body = self.parse_block(); Expr::FnExpr(params, body) }
            _ => unreachable!(),
        }
    }
}

// ============ VALUES & SCOPES ============

#[derive(Clone)]
enum Value {
    Int(i64),
    Bool(bool),
    Str(String),
    List(Rc<RefCell<Vec<Value>>>),
    Func(Rc<FuncVal>),
    Nil,
}

#[derive(Clone)]
enum FuncVal {
    User { params: Vec<String>, body: Vec<Stmt>, scope: ScopeRef },
    Builtin { name: &'static str, arity: Option<usize>, func: fn(&[Value]) -> Result<Value, TernError> },
}

type ScopeRef = Rc<RefCell<Scope>>;

struct Scope {
    vars: HashMap<String, Value>,
    parent: Option<ScopeRef>,
}

struct TernError { line: usize, message: String }

fn new_scope(parent: Option<ScopeRef>) -> ScopeRef {
    Rc::new(RefCell::new(Scope { vars: HashMap::new(), parent }))
}

fn lookup(scope: &ScopeRef, name: &str) -> Option<Value> {
    let s = scope.borrow();
    if let Some(v) = s.vars.get(name) { return Some(v.clone()); }
    if let Some(ref p) = s.parent { return lookup(p, name); }
    None
}

fn assign(scope: &ScopeRef, name: &str, val: Value) -> bool {
    let s = scope.borrow();
    if s.vars.contains_key(name) { drop(s); scope.borrow_mut().vars.insert(name.to_string(), val); return true; }
    if let Some(ref p) = s.parent { drop(s); return assign(p, name, val); }
    false
}

fn type_name(v: &Value) -> &'static str {
    match v {
        Value::Int(_) => "int", Value::Bool(_) => "bool", Value::Str(_) => "string",
        Value::List(_) => "list", Value::Func(_) => "function", Value::Nil => "nil",
    }
}

fn truthy(v: &Value) -> bool {
    match v {
        Value::Bool(b) => *b,
        Value::Nil => false,
        Value::Int(n) => *n != 0,
        Value::Str(s) => !s.is_empty(),
        Value::List(l) => !l.borrow().is_empty(),
        Value::Func(_) => true,
    }
}

fn val_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Int(x), Value::Int(y)) => x == y,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Nil, Value::Nil) => true,
        (Value::Func(x), Value::Func(y)) => Rc::ptr_eq(x, y),
        (Value::List(x), Value::List(y)) => {
            let xa = x.borrow(); let ya = y.borrow();
            if xa.len() != ya.len() { return false; }
            for i in 0..xa.len() { if !val_eq(&xa[i], &ya[i]) { return false; } }
            true
        }
        _ => false,
    }
}

fn escape_str(s: &str) -> String {
    let mut r = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '\\' => r.push_str("\\\\"),
            '"' => r.push_str("\\\""),
            '\n' => r.push_str("\\n"),
            '\t' => r.push_str("\\t"),
            _ => r.push(c),
        }
    }
    r
}

fn display(v: &Value, in_list: bool, seen: &mut Vec<usize>) -> String {
    match v {
        Value::Int(n) => n.to_string(),
        Value::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
        Value::Nil => "nil".to_string(),
        Value::Func(_) => "<fn>".to_string(),
        Value::Str(s) => {
            if in_list { format!("\"{}\"", escape_str(s)) } else { s.clone() }
        }
        Value::List(l) => {
            let ptr = Rc::as_ptr(l) as usize;
            if seen.contains(&ptr) { return "[...]".to_string(); }
            seen.push(ptr);
            let elems: Vec<String> = l.borrow().iter().map(|e| display(e, true, seen)).collect();
            seen.pop();
            format!("[{}]", elems.join(", "))
        }
    }
}

// ============ INTERPRETER ============

enum CF { Normal, Break, Continue, Return(Value) }
type Result<T> = std::result::Result<T, TernError>;

fn err(line: usize, msg: String) -> TernError { TernError { line, message: msg } }

fn eval(e: &Expr, scope: &ScopeRef) -> Result<Value> {
    match e {
        Expr::IntLit(n) => Ok(Value::Int(*n)),
        Expr::StrLit(s) => Ok(Value::Str(s.clone())),
        Expr::BoolLit(b) => Ok(Value::Bool(*b)),
        Expr::NilLit => Ok(Value::Nil),
        Expr::Ident(name, ln) => {
            lookup(scope, name).ok_or_else(|| err(*ln, format!("undefined variable {}", name)))
        }
        Expr::Binary(op, l, r, ln) => {
            match op {
                BinOp::And => {
                    let lv = eval(l, scope)?;
                    if !truthy(&lv) { Ok(lv) } else { eval(r, scope) }
                }
                BinOp::Or => {
                    let lv = eval(l, scope)?;
                    if truthy(&lv) { Ok(lv) } else { eval(r, scope) }
                }
                _ => {
                    let lv = eval(l, scope)?;
                    let rv = eval(r, scope)?;
                    eval_bin(*op, lv, rv, *ln)
                }
            }
        }
        Expr::Unary(op, inner, ln) => {
            let v = eval(inner, scope)?;
            match op {
                UnOp::Not => Ok(Value::Bool(!truthy(&v))),
                UnOp::Neg => {
                    match v {
                        Value::Int(n) => n.checked_neg().map(Value::Int).ok_or_else(|| err(*ln, "integer overflow".to_string())),
                        other => Err(err(*ln, format!("cannot apply - to {}", type_name(&other)))),
                    }
                }
            }
        }
        Expr::Call(callee, args, ln) => {
            let cv = eval(callee, scope)?;
            let mut vals = Vec::with_capacity(args.len());
            for a in args { vals.push(eval(a, scope)?); }
            call_func(cv, vals, *ln)
        }
        Expr::Index(obj, idx, ln) => {
            let ov = eval(obj, scope)?;
            let iv = eval(idx, scope)?;
            index_read(ov, iv, *ln)
        }
        Expr::ListLit(elems) => {
            let mut v = Vec::with_capacity(elems.len());
            for e in elems { v.push(eval(e, scope)?); }
            Ok(Value::List(Rc::new(RefCell::new(v))))
        }
        Expr::FnExpr(params, body) => {
            Ok(Value::Func(Rc::new(FuncVal::User { params: params.clone(), body: body.clone(), scope: scope.clone() })))
        }
    }
}

fn eval_bin(op: BinOp, lv: Value, rv: Value, ln: usize) -> Result<Value> {
    match op {
        BinOp::Add => match (&lv, &rv) {
            (Value::Int(a), Value::Int(b)) => a.checked_add(*b).map(Value::Int).ok_or_else(|| err(ln, "integer overflow".to_string())),
            (Value::Str(a), Value::Str(b)) => Ok(Value::Str(format!("{}{}", a, b))),
            (Value::List(a), Value::List(b)) => {
                let mut v: Vec<Value> = a.borrow().clone();
                v.extend(b.borrow().iter().cloned());
                Ok(Value::List(Rc::new(RefCell::new(v))))
            }
            _ => Err(err(ln, format!("cannot apply + to {} and {}", type_name(&lv), type_name(&rv)))),
        },
        BinOp::Sub => match (&lv, &rv) {
            (Value::Int(a), Value::Int(b)) => a.checked_sub(*b).map(Value::Int).ok_or_else(|| err(ln, "integer overflow".to_string())),
            _ => Err(err(ln, format!("cannot apply - to {} and {}", type_name(&lv), type_name(&rv)))),
        },
        BinOp::Mul => match (&lv, &rv) {
            (Value::Int(a), Value::Int(b)) => a.checked_mul(*b).map(Value::Int).ok_or_else(|| err(ln, "integer overflow".to_string())),
            _ => Err(err(ln, format!("cannot apply * to {} and {}", type_name(&lv), type_name(&rv)))),
        },
        BinOp::Div => match (&lv, &rv) {
            (Value::Int(a), Value::Int(b)) => {
                if *b == 0 { return Err(err(ln, "division by zero".to_string())); }
                a.checked_div(*b).map(Value::Int).ok_or_else(|| err(ln, "integer overflow".to_string()))
            }
            _ => Err(err(ln, format!("cannot apply / to {} and {}", type_name(&lv), type_name(&rv)))),
        },
        BinOp::Mod => match (&lv, &rv) {
            (Value::Int(a), Value::Int(b)) => {
                if *b == 0 { return Err(err(ln, "division by zero".to_string())); }
                if *b == -1 { return Ok(Value::Int(0)); }
                Ok(Value::Int(a.wrapping_rem(*b)))
            }
            _ => Err(err(ln, format!("cannot apply % to {} and {}", type_name(&lv), type_name(&rv)))),
        },
        BinOp::Eq => Ok(Value::Bool(val_eq(&lv, &rv))),
        BinOp::Ne => Ok(Value::Bool(!val_eq(&lv, &rv))),
        BinOp::Lt | BinOp::Le | BinOp::Gt | BinOp::Ge => {
            match (&lv, &rv) {
                (Value::Int(a), Value::Int(b)) => {
                    let r = match op { BinOp::Lt => a < b, BinOp::Le => a <= b, BinOp::Gt => a > b, _ => a >= b };
                    Ok(Value::Bool(r))
                }
                (Value::Str(a), Value::Str(b)) => {
                    let r = match op { BinOp::Lt => a < b, BinOp::Le => a <= b, BinOp::Gt => a > b, _ => a >= b };
                    Ok(Value::Bool(r))
                }
                _ => Err(err(ln, format!("cannot apply {} to {} and {}", op_str(op), type_name(&lv), type_name(&rv)))),
            }
        }
        _ => unreachable!(),
    }
}

fn op_str(op: BinOp) -> &'static str {
    match op {
        BinOp::Add => "+", BinOp::Sub => "-", BinOp::Mul => "*", BinOp::Div => "/", BinOp::Mod => "%",
        BinOp::Eq => "==", BinOp::Ne => "!=", BinOp::Lt => "<", BinOp::Le => "<=", BinOp::Gt => ">", BinOp::Ge => ">=",
        BinOp::And => "and", BinOp::Or => "or",
    }
}

fn index_read(ov: Value, iv: Value, ln: usize) -> Result<Value> {
    match (&ov, &iv) {
        (Value::List(l), Value::Int(i)) => {
            let l = l.borrow();
            if *i < 0 || *i >= l.len() as i64 {
                return Err(err(ln, format!("index {} out of range for length {}", i, l.len())));
            }
            Ok(l[*i as usize].clone())
        }
        (Value::Str(s), Value::Int(i)) => {
            let chars: Vec<char> = s.chars().collect();
            if *i < 0 || *i >= chars.len() as i64 {
                return Err(err(ln, format!("index {} out of range for length {}", i, chars.len())));
            }
            Ok(Value::Str(chars[*i as usize].to_string()))
        }
        (Value::List(_), _) => Err(err(ln, format!("cannot index list with {}", type_name(&iv)))),
        (Value::Str(_), _) => Err(err(ln, format!("cannot index string with {}", type_name(&iv)))),
        _ => Err(err(ln, format!("cannot index {} with {}", type_name(&ov), type_name(&iv)))),
    }
}

fn call_func(cv: Value, args: Vec<Value>, ln: usize) -> Result<Value> {
    match cv {
        Value::Func(f) => {
            match &*f {
                FuncVal::User { params, body, scope } => {
                    if args.len() != params.len() {
                        return Err(err(ln, format!("expected {} arguments, got {}", params.len(), args.len())));
                    }
                    let call_scope = new_scope(Some(scope.clone()));
                    for (i, p) in params.iter().enumerate() {
                        call_scope.borrow_mut().vars.insert(p.clone(), args[i].clone());
                    }
                    match run_block(body, &call_scope) {
                        Ok(CF::Return(v)) => Ok(v),
                        Ok(_) => Ok(Value::Nil),
                        Err(e) => Err(e),
                    }
                }
                FuncVal::Builtin { name, arity, func } => {
                    if let Some(n) = arity {
                        if args.len() != *n {
                            return Err(err(ln, format!("expected {} arguments, got {}", n, args.len())));
                        }
                    }
                    func(&args)
                }
            }
        }
        other => Err(err(ln, format!("cannot call {}", type_name(&other)))),
    }
}

fn run_block(stmts: &[Stmt], scope: &ScopeRef) -> Result<CF> {
    for s in stmts {
        match run_stmt(s, scope)? {
            CF::Normal => {}
            other => return Ok(other),
        }
    }
    Ok(CF::Normal)
}

fn run_stmt(s: &Stmt, scope: &ScopeRef) -> Result<CF> {
    match s {
        Stmt::Let(name, expr) => {
            let v = eval(expr, scope)?;
            scope.borrow_mut().vars.insert(name.clone(), v);
            Ok(CF::Normal)
        }
        Stmt::FnDecl(name, params, body) => {
            let fv = Value::Func(Rc::new(FuncVal::User { params: params.clone(), body: body.clone(), scope: scope.clone() }));
            scope.borrow_mut().vars.insert(name.clone(), fv);
            Ok(CF::Normal)
        }
        Stmt::If(cond, body, ec) => {
            let cv = eval(cond, scope)?;
            if truthy(&cv) {
                let ns = new_scope(Some(scope.clone()));
                run_block(body, &ns)
            } else {
                match ec {
                    Some(ElseClause::Block(b)) => { let ns = new_scope(Some(scope.clone())); run_block(b, &ns) }
                    Some(ElseClause::If(stmt)) => run_stmt(stmt, scope),
                    None => Ok(CF::Normal),
                }
            }
        }
        Stmt::While(cond, body, _) => {
            loop {
                let cv = eval(cond, scope)?;
                if !truthy(&cv) { break; }
                let ns = new_scope(Some(scope.clone()));
                match run_block(body, &ns)? {
                    CF::Break => break,
                    CF::Return(v) => return Ok(CF::Return(v)),
                    CF::Continue => {}
                    CF::Normal => {}
                }
            }
            Ok(CF::Normal)
        }
        Stmt::For(var, expr, body, ln) => {
            let list_val = eval(expr, scope)?;
            let list_ref = match &list_val {
                Value::List(l) => l.clone(),
                other => return Err(err(*ln, format!("cannot iterate {}", type_name(other)))),
            };
            let mut i: i64 = 0;
            loop {
                let len = list_ref.borrow().len() as i64;
                if i >= len { break; }
                let elem = list_ref.borrow()[i as usize].clone();
                let ns = new_scope(Some(scope.clone()));
                ns.borrow_mut().vars.insert(var.clone(), elem);
                match run_block(body, &ns)? {
                    CF::Break => break,
                    CF::Return(v) => return Ok(CF::Return(v)),
                    CF::Continue => {}
                    CF::Normal => {}
                }
                i += 1;
            }
            Ok(CF::Normal)
        }
        Stmt::Return(expr, _) => {
            let v = match expr { Some(e) => eval(e, scope)?, None => Value::Nil };
            Ok(CF::Return(v))
        }
        Stmt::Break(_) => Ok(CF::Break),
        Stmt::Continue(_) => Ok(CF::Continue),
        Stmt::Assign(name, expr) => {
            let v = eval(expr, scope)?;
            if !assign(scope, name, v) {
                return Err(err(0, format!("undefined variable {}", name)));
            }
            Ok(CF::Normal)
        }
        Stmt::IndexAssign(obj, idx, val, ln) => {
            let ov = eval(obj, scope)?;
            let iv = eval(idx, scope)?;
            let vv = eval(val, scope)?;
            match &ov {
                Value::List(l) => {
                    match &iv {
                        Value::Int(i) => {
                            let l = l.borrow();
                            if *i < 0 || *i >= l.len() as i64 {
                                return Err(err(*ln, format!("index {} out of range for length {}", i, l.len())));
                            }
                            let idx_u = *i as usize;
                            drop(l);
                            l.borrow_mut()[idx_u] = vv;
                            Ok(CF::Normal)
                        }
                        other => Err(err(*ln, format!("cannot index list with {}", type_name(other)))),
                    }
                }
                other => Err(err(*ln, format!("cannot assign into {}", type_name(other)))),
            }
        }
        Stmt::ExprStmt(expr) => {
            eval(expr, scope)?;
            Ok(CF::Normal)
        }
    }
}

// ============ BUILTINS ============

fn create_builtins() -> ScopeRef {
    let scope = new_scope(None);
    let mut vars = HashMap::new();

    vars.insert("print".to_string(), Value::Func(Rc::new(FuncVal::Builtin {
        name: "print", arity: None,
        func: |args: &[Value]| -> Result<Value> {
            let mut seen: Vec<usize> = Vec::new();
            let mut out = String::new();
            for (i, a) in args.iter().enumerate() {
                if i > 0 { out.push(' '); }
                out.push_str(&display(a, false, &mut seen));
            }
            out.push('\n');
            io::stdout().write_all(out.as_bytes()).unwrap();
            Ok(Value::Nil)
        },
    })));

    vars.insert("str".to_string(), Value::Func(Rc::new(FuncVal::Builtin {
        name: "str", arity: Some(1),
        func: |args: &[Value]| -> Result<Value> {
            let mut seen: Vec<usize> = Vec::new();
            Ok(Value::Str(display(&args[0], false, &mut seen)))
        },
    })));

    vars.insert("type".to_string(), Value::Func(Rc::new(FuncVal::Builtin {
        name: "type", arity: Some(1),
        func: |args: &[Value]| -> Result<Value> {
            Ok(Value::Str(type_name(&args[0]).to_string()))
        },
    })));

    vars.insert("len".to_string(), Value::Func(Rc::new(FuncVal::Builtin {
        name: "len", arity: Some(1),
        func: |args: &[Value]| -> Result<Value> {
            match &args[0] {
                Value::Str(s) => Ok(Value::Int(s.chars().count() as i64)),
                Value::List(l) => Ok(Value::Int(l.borrow().len() as i64)),
                _ => Err(err(0, "bad argument to len".to_string())),
            }
        },
    })));

    vars.insert("push".to_string(), Value::Func(Rc::new(FuncVal::Builtin {
        name: "push", arity: Some(2),
        func: |args: &[Value]| -> Result<Value> {
            match &args[0] {
                Value::List(l) => { l.borrow_mut().push(args[1].clone()); Ok(Value::Nil) }
                _ => Err(err(0, "bad argument to push".to_string())),
            }
        },
    })));

    vars.insert("pop".to_string(), Value::Func(Rc::new(FuncVal::Builtin {
        name: "pop", arity: Some(1),
        func: |args: &[Value]| -> Result<Value> {
            match &args[0] {
                Value::List(l) => {
                    match l.borrow_mut().pop() {
                        Some(v) => Ok(v),
                        None => Err(err(0, "bad argument to pop".to_string())),
                    }
                }
                _ => Err(err(0, "bad argument to pop".to_string())),
            }
        },
    })));

    vars.insert("range".to_string(), Value::Func(Rc::new(FuncVal::Builtin {
        name: "range", arity: Some(2),
        func: |args: &[Value]| -> Result<Value> {
            match (&args[0], &args[1]) {
                (Value::Int(a), Value::Int(b)) => {
                    let mut v = Vec::new();
                    let mut i = *a;
                    while i < *b { v.push(Value::Int(i)); i += 1; }
                    Ok(Value::List(Rc::new(RefCell::new(v))))
                }
                _ => Err(err(0, "bad argument to range".to_string())),
            }
        },
    })));

    vars.insert("slice".to_string(), Value::Func(Rc::new(FuncVal::Builtin {
        name: "slice", arity: Some(3),
        func: |args: &[Value]| -> Result<Value> {
            let (a, b) = match (&args[1], &args[2]) {
                (Value::Int(a), Value::Int(b)) => (*a as usize, *b as usize),
                _ => return Err(err(0, "bad argument to slice".to_string())),
            };
            match &args[0] {
                Value::Str(s) => {
                    let chars: Vec<char> = s.chars().collect();
                    Ok(Value::Str(chars[a..b].iter().collect()))
                }
                Value::List(l) => {
                    let l = l.borrow();
                    Ok(Value::List(Rc::new(RefCell::new(l[a..b].to_vec()))))
                }
                _ => Err(err(0, "bad argument to slice".to_string())),
            }
        },
    })));

    scope.borrow_mut().vars = vars;
    scope
}

// ============ MAIN ============

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let path = Path::new(dir).join("program.tern");
    let src = std::fs::read_to_string(&path).unwrap();
    let tokens = tokenize(&src);
    let mut parser = Parser::new(tokens);
    let program = parser.parse_program();

    let builtins = create_builtins();
    let global = new_scope(Some(builtins));

    match run_block(&program, &global) {
        Ok(_) => {}
        Err(e) => {
            io::stdout().flush().unwrap();
            println!("error at line {}: {}", e.line, e.message);
            io::stdout().flush().unwrap();
        }
    }
    process::exit(0);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <ctype.h>
#include <stdarg.h>
#include <setjmp.h>

/* ===== Tokens ===== */
enum {
    TK_INT,TK_STR,TK_IDENT,TK_LET,TK_FN,TK_IF,TK_ELSE,TK_WHILE,TK_FOR,TK_IN,
    TK_RETURN,TK_BREAK,TK_CONTINUE,TK_AND,TK_OR,TK_NOT,TK_TRUE,TK_FALSE,TK_NIL,
    TK_EQ,TK_NE,TK_LE,TK_GE,TK_LT,TK_GT,TK_ASSIGN,TK_PLUS,TK_MINUS,TK_STAR,
    TK_SLASH,TK_PCT,TK_LP,TK_RP,TK_LB,TK_RB,TK_LC,TK_RC,TK_COMMA,TK_SEMI,TK_EOF
};
typedef struct{int type;int64_t ival;char*sval;int slen;int line;}Token;

/* ===== AST ===== */
enum{
    N_INT,N_STR,N_BOOL,N_NIL,N_IDENT,N_BIN,N_UN,N_CALL,N_INDEX,N_LIST,N_FN,
    S_LET,S_FNDECL,S_IF,S_WHILE,S_FOR,S_RETURN,S_BREAK,S_CONTINUE,
    S_ASSIGN,S_IDXASSIGN,S_EXPR,S_BLOCK
};
typedef struct ASTNode{
    int type,line;
    union{
        int64_t ival;
        struct{char*data;int len;}sval;
        struct{char*name;}ident;
        struct{int op;struct ASTNode*l,*r;}bin;
        struct{int op;struct ASTNode*operand;}un;
        struct{struct ASTNode*callee;struct ASTNode**args;int nargs;}call;
        struct{struct ASTNode*obj,*idx;}index;
        struct{struct ASTNode**elems;int nelem;}listlit;
        struct{char**params;int nparams;struct ASTNode*body;}fnlit;
        struct{char*name;struct ASTNode*val;}letstmt;
        struct{char*name;struct ASTNode*body;int nparams;char**params;}fndecl;
        struct{struct ASTNode*cond,*thenb,*elseb;}ifstmt;
        struct{struct ASTNode*cond,*body;}whilestmt;
        struct{char*var;struct ASTNode*iter,*body;}forstmt;
        struct{struct ASTNode*val;}retstmt;
        struct{char*name;struct ASTNode*val;}assign;
        struct{struct ASTNode*obj,*idx,*val;}idxassign;
        struct{struct ASTNode*expr;}exprstmt;
        struct{struct ASTNode**stmts;int nstmts;}block;
    };
}ASTNode;

/* ===== Values ===== */
enum{V_INT,V_BOOL,V_STR,V_LIST,V_FN,V_NIL};
typedef struct List List;
typedef struct FuncVal FuncVal;
typedef struct Scope Scope;
typedef struct{int type;union{int64_t i;bool b;struct{char*data;int len;}s;List*list;FuncVal*fn;};}Value;
struct List{Value*items;int len,cap;};
struct FuncVal{char**params;int nparams;ASTNode*body;Scope*captured;int builtin_id;};

/* ===== Scope ===== */
typedef struct Binding{char*name;Value val;struct Binding*next;}Binding;
struct Scope{Binding*bindings;Scope*parent;};

/* ===== Globals ===== */
static const char*g_src;static int g_src_len,g_src_pos,g_line;
static Token*g_toks;static int g_ntok,g_pos;
static int g_cf;static Value g_retval;
static jmp_buf g_jmp;static int g_eline;static char g_emsg[512];
static Scope*g_builtins;

static void err(int line,const char*fmt,...){
    va_list ap;va_start(ap,fmt);vsnprintf(g_emsg,sizeof(g_emsg),fmt,ap);va_end(ap);
    g_eline=line;longjmp(g_jmp,1);
}

/* ===== Lexer ===== */
static void skipws(void){
    while(g_src_pos<g_src_len){
        char c=g_src[g_src_pos];
        if(c=='\n'){g_line++;g_src_pos++;}
        else if(c==' '||c=='\t'||c=='\r')g_src_pos++;
        else if(c=='#'){while(g_src_pos<g_src_len&&g_src[g_src_pos]!='\n')g_src_pos++;}
        else break;
    }
}
static Token lex(void){
    skipws();
    Token t={0};t.line=g_line;
    if(g_src_pos>=g_src_len){t.type=TK_EOF;return t;}
    char c=g_src[g_src_pos];
    if(isdigit(c)){
        int64_t v=0;
        while(g_src_pos<g_src_len&&isdigit(g_src[g_src_pos])){v=v*10+(g_src[g_src_pos]-'0');g_src_pos++;}
        t.type=TK_INT;t.ival=v;return t;
    }
    if(c=='"'){
        g_src_pos++;int cap=64,len=0;char*buf=malloc(cap);
        while(g_src_pos<g_src_len&&g_src[g_src_pos]!='"'){
            if(g_src[g_src_pos]=='\\'){
                g_src_pos++;char e=g_src[g_src_pos];
                if(e=='n')buf[len++]='\n';else if(e=='t')buf[len++]='\t';
                else if(e=='"')buf[len++]='"';else if(e=='\\')buf[len++]='\\';
                g_src_pos++;
            }else buf[len++]=g_src[g_src_pos++];
            if(len>=cap){cap*=2;buf=realloc(buf,cap);}
        }
        g_src_pos++;t.type=TK_STR;t.sval=buf;t.slen=len;return t;
    }
    if(isalpha(c)||c=='_'){
        int st=g_src_pos;
        while(g_src_pos<g_src_len&&(isalnum(g_src[g_src_pos])||g_src[g_src_pos]=='_'))g_src_pos++;
        int len=g_src_pos-st;char*nm=malloc(len+1);memcpy(nm,g_src+st,len);nm[len]=0;
        t.sval=nm;t.slen=len;
        switch(len){
            case 2:if(!strcmp(nm,"if"))t.type=TK_IF;else if(!strcmp(nm,"in"))t.type=TK_IN;else if(!strcmp(nm,"fn"))t.type=TK_FN;else t.type=TK_IDENT;break;
            case 3:if(!strcmp(nm,"let"))t.type=TK_LET;else if(!strcmp(nm,"and"))t.type=TK_AND;else if(!strcmp(nm,"for"))t.type=TK_FOR;else if(!strcmp(nm,"not"))t.type=TK_NOT;else if(!strcmp(nm,"nil"))t.type=TK_NIL;else t.type=TK_IDENT;break;
            case 4:if(!strcmp(nm,"else"))t.type=TK_ELSE;else if(!strcmp(nm,"true"))t.type=TK_TRUE;else if(!strcmp(nm,"while"))t.type=TK_WHILE;else if(!strcmp(nm,"or"))t.type=TK_OR;else t.type=TK_IDENT;break;
            case 5:if(!strcmp(nm,"false"))t.type=TK_FALSE;else if(!strcmp(nm,"break"))t.type=TK_BREAK;else t.type=TK_IDENT;break;
            case 6:if(!strcmp(nm,"return"))t.type=TK_RETURN;else t.type=TK_IDENT;break;
            case 8:if(!strcmp(nm,"continue"))t.type=TK_CONTINUE;else t.type=TK_IDENT;break;
            default:t.type=TK_IDENT;
        }
        return t;
    }
    g_src_pos++;
    switch(c){
        case'=':if(g_src_pos<g_src_len&&g_src[g_src_pos]=='='){g_src_pos++;t.type=TK_EQ;}else t.type=TK_ASSIGN;break;
        case'!':if(g_src_pos<g_src_len&&g_src[g_src_pos]=='='){g_src_pos++;t.type=TK_NE;}else t.type=TK_NE;break;
        case'<':if(g_src_pos<g_src_len&&g_src[g_src_pos]=='='){g_src_pos++;t.type=TK_LE;}else t.type=TK_LT;break;
        case'>':if(g_src_pos<g_src_len&&g_src[g_src_pos]=='='){g_src_pos++;t.type=TK_GE;}else t.type=TK_GT;break;
        case'+':t.type=TK_PLUS;break;case'-':t.type=TK_MINUS;break;case'*':t.type=TK_STAR;break;
        case'/':t.type=TK_SLASH;break;case'%':t.type=TK_PCT;break;
        case'(':t.type=TK_LP;break;case')':t.type=TK_RP;break;
        case'[':t.type=TK_LB;break;case']':t.type=TK_RB;break;
        case'{':t.type=TK_LC;break;case'}':t.type=TK_RC;break;
        case',':t.type=TK_COMMA;break;case';':t.type=TK_SEMI;break;
        default:t.type=TK_EOF;break;
    }
    return t;
}
static void tokenize(void){
    g_ntok=0;int cap=4096;g_toks=malloc(cap*sizeof(Token));
    for(;;){
        Token t=lex();
        if(g_ntok>=cap){cap*=2;g_toks=realloc(g_toks,cap*sizeof(Token));}
        g_toks[g_ntok++]=t;
        if(t.type==TK_EOF)break;
    }
    g_pos=0;
}
static Token*peek(void){return&g_toks[g_pos];}
static Token*advance(void){return&g_toks[g_pos++];}
static int match(int t){if(g_toks[g_pos].type==t){g_pos++;return 1;}return 0;}
static void expect(int t){if(g_toks[g_pos].type!=t){g_pos++;}g_pos++;}
static int check(int t){return g_toks[g_pos].type==t;}

/* ===== Parser ===== */
static ASTNode*new_node(int type){ASTNode*n=calloc(1,sizeof(ASTNode));n->type=type;n->line=g_toks[g_pos].line;return n;}

static ASTNode*parse_expr(void);
static ASTNode*parse_block(void);
static ASTNode*parse_stmt(void);

static ASTNode*parse_params(char***out,int*np){
    if(check(TK_RP)){*out=NULL;*np=0;return NULL;}
    int cap=8;char**ps=malloc(cap*sizeof(char*));int cnt=0;
    for(;;){
        Token*t=advance();
        if(cnt>=cap){cap*=2;ps=realloc(ps,cap*sizeof(char*));}
        ps[cnt++]=t->sval;
        if(!match(TK_COMMA))break;
    }
    *out=ps;*np=cnt;return NULL;
}

static ASTNode*parse_primary(void){
    Token*t=peek();
    if(t->type==TK_INT){advance();ASTNode*n=new_node(N_INT);n->ival=t->ival;n->line=t->line;return n;}
    if(t->type==TK_STR){advance();ASTNode*n=new_node(N_STR);n->sval.data=t->sval;n->sval.len=t->slen;n->line=t->line;return n;}
    if(t->type==TK_TRUE){advance();ASTNode*n=new_node(N_BOOL);n->ival=1;n->line=t->line;return n;}
    if(t->type==TK_FALSE){advance();ASTNode*n=new_node(N_BOOL);n->ival=0;n->line=t->line;return n;}
    if(t->type==TK_NIL){advance();ASTNode*n=new_node(N_NIL);n->line=t->line;return n;}
    if(t->type==TK_IDENT){advance();ASTNode*n=new_node(N_IDENT);n->ident.name=t->sval;n->line=t->line;return n;}
    if(t->type==TK_LP){advance();ASTNode*e=parse_expr();match(TK_RP);return e;}
    if(t->type==TK_LB){
        advance();ASTNode*n=new_node(N_LIST);n->line=t->line;
        int cap=8;ASTNode**elems=malloc(cap*sizeof(ASTNode*));int cnt=0;
        if(!check(TK_RB)){
            for(;;){
                if(cnt>=cap){cap*=2;elems=realloc(elems,cap*sizeof(ASTNode*));}
                elems[cnt++]=parse_expr();
                if(!match(TK_COMMA))break;
            }
        }
        match(TK_RB);n->listlit.elems=elems;n->listlit.nelem=cnt;return n;
    }
    if(t->type==TK_FN){
        advance();match(TK_LP);
        ASTNode*n=new_node(N_FN);n->line=t->line;
        char**ps;int np;parse_params(&ps,&np);
        match(TK_RP);n->fnlit.params=ps;n->fnlit.nparams=np;n->fnlit.body=parse_block();
        return n;
    }
    /* shouldn't reach */
    advance();ASTNode*n=new_node(N_NIL);return n;
}

static ASTNode*parse_postfix(void){
    ASTNode*e=parse_primary();
    for(;;){
        if(check(TK_LP)){
            int ln=peek()->line;advance();
            ASTNode*n=new_node(N_CALL);n->line=ln;n->call.callee=e;
            int cap=8;ASTNode**args=malloc(cap*sizeof(ASTNode*));int cnt=0;
            if(!check(TK_RP)){
                for(;;){
                    if(cnt>=cap){cap*=2;args=realloc(args,cap*sizeof(ASTNode*));}
                    args[cnt++]=parse_expr();
                    if(!match(TK_COMMA))break;
                }
            }
            match(TK_RP);n->call.args=args;n->call.nargs=cnt;e=n;
        }else if(check(TK_LB)){
            int ln=peek()->line;advance();
            ASTNode*n=new_node(N_INDEX);n->line=ln;n->index.obj=e;n->index.idx=parse_expr();
            match(TK_RB);e=n;
        }else break;
    }
    return e;
}

static ASTNode*parse_unary(void){
    if(check(TK_MINUS)){
        int ln=peek()->line;advance();
        ASTNode*n=new_node(N_UN);n->line=ln;n->un.op=TK_MINUS;n->un.operand=parse_unary();return n;
    }
    return parse_postfix();
}

static ASTNode*parse_mul(void){
    ASTNode*l=parse_unary();
    while(check(TK_STAR)||check(TK_SLASH)||check(TK_PCT)){
        int ln=peek()->line;int op=advance()->type;
        ASTNode*n=new_node(N_BIN);n->line=ln;n->bin.op=op;n->bin.l=l;n->bin.r=parse_unary();l=n;
    }
    return l;
}

static ASTNode*parse_add(void){
    ASTNode*l=parse_mul();
    while(check(TK_PLUS)||check(TK_MINUS)){
        int ln=peek()->line;int op=advance()->type;
        ASTNode*n=new_node(N_BIN);n->line=ln;n->bin.op=op;n->bin.l=l;n->bin.r=parse_mul();l=n;
    }
    return l;
}

static ASTNode*parse_cmp(void){
    ASTNode*l=parse_add();
    while(check(TK_EQ)||check(TK_NE)||check(TK_LT)||check(TK_LE)||check(TK_GT)||check(TK_GE)){
        int ln=peek()->line;int op=advance()->type;
        ASTNode*n=new_node(N_BIN);n->line=ln;n->bin.op=op;n->bin.l=l;n->bin.r=parse_add();l=n;
    }
    return l;
}

static ASTNode*parse_not(void){
    if(check(TK_NOT)){
        int ln=peek()->line;advance();
        ASTNode*n=new_node(N_UN);n->line=ln;n->un.op=TK_NOT;n->un.operand=parse_not();return n;
    }
    return parse_cmp();
}

static ASTNode*parse_and(void){
    ASTNode*l=parse_not();
    while(check(TK_AND)){
        int ln=peek()->line;advance();
        ASTNode*n=new_node(N_BIN);n->line=ln;n->bin.op=TK_AND;n->bin.l=l;n->bin.r=parse_not();l=n;
    }
    return l;
}

static ASTNode*parse_or(void){
    ASTNode*l=parse_and();
    while(check(TK_OR)){
        int ln=peek()->line;advance();
        ASTNode*n=new_node(N_BIN);n->line=ln;n->bin.op=TK_OR;n->bin.l=l;n->bin.r=parse_and();l=n;
    }
    return l;
}

static ASTNode*parse_expr(void){return parse_or();}

static ASTNode*parse_block(void){
    match(TK_LC);ASTNode*n=new_node(S_BLOCK);n->line=g_toks[g_pos-1].line;
    int cap=16;ASTNode**stmts=malloc(cap*sizeof(ASTNode*));int cnt=0;
    while(!check(TK_RC)&&!check(TK_EOF)){
        if(cnt>=cap){cap*=2;stmts=realloc(stmts,cap*sizeof(ASTNode*));}
        stmts[cnt++]=parse_stmt();
    }
    match(TK_RC);n->block.stmts=stmts;n->block.nstmts=cnt;return n;
}

static ASTNode*parse_stmt(void){
    Token*t=peek();
    if(t->type==TK_LET){
        advance();Token*nm=advance();match(TK_ASSIGN);ASTNode*val=parse_expr();match(TK_SEMI);
        ASTNode*n=new_node(S_LET);n->line=t->line;n->letstmt.name=nm->sval;n->letstmt.val=val;return n;
    }
    if(t->type==TK_FN){
        Token*nx=g_toks[g_pos+1];
        if(nx->type==TK_IDENT){
            advance();Token*nm=advance();match(TK_LP);
            char**ps;int np;parse_params(&ps,&np);match(TK_RP);
            ASTNode*body=parse_block();
            ASTNode*n=new_node(S_FNDECL);n->line=t->line;n->fndecl.name=nm->sval;
            n->fndecl.params=ps;n->fndecl.nparams=np;n->fndecl.body=body;return n;
        }
    }
    if(t->type==TK_IF){
        advance();ASTNode*cond=parse_expr();ASTNode*thenb=parse_block();ASTNode*elseb=NULL;
        if(check(TK_ELSE)){
            advance();
            if(check(TK_IF))elseb=parse_stmt();
            else elseb=parse_block();
        }
        ASTNode*n=new_node(S_IF);n->line=t->line;n->ifstmt.cond=cond;n->ifstmt.thenb=thenb;n->ifstmt.elseb=elseb;return n;
    }
    if(t->type==TK_WHILE){
        advance();ASTNode*cond=parse_expr();ASTNode*body=parse_block();
        ASTNode*n=new_node(S_WHILE);n->line=t->line;n->whilestmt.cond=cond;n->whilestmt.body=body;return n;
    }
    if(t->type==TK_FOR){
        advance();Token*nm=advance();match(TK_IN);ASTNode*iter=parse_expr();ASTNode*body=parse_block();
        ASTNode*n=new_node(S_FOR);n->line=t->line;n->forstmt.var=nm->sval;n->forstmt.iter=iter;n->forstmt.body=body;return n;
    }
    if(t->type==TK_RETURN){
        advance();ASTNode*n=new_node(S_RETURN);n->line=t->line;n->retstmt.val=NULL;
        if(!check(TK_SEMI))n->retstmt.val=parse_expr();
        match(TK_SEMI);return n;
    }
    if(t->type==TK_BREAK){advance();match(TK_SEMI);ASTNode*n=new_node(S_BREAK);n->line=t->line;return n;}
    if(t->type==TK_CONTINUE){advance();match(TK_SEMI);ASTNode*n=new_node(S_CONTINUE);n->line=t->line;return n;}
    /* assignment or expression */
    if(t->type==TK_IDENT){
        /* check for IDENT = expr ; */
        if(g_toks[g_pos+1].type==TK_ASSIGN){
            advance();Token*nm=advance();match(TK_ASSIGN);ASTNode*val=parse_expr();match(TK_SEMI);
            ASTNode*n=new_node(S_ASSIGN);n->line=t->line;n->assign.name=nm->sval;n->assign.val=val;return n;
        }
        /* check for IDENT [ expr ] = expr ; */
        if(g_toks[g_pos+1].type==TK_LB){
            /* could be index-assign or expr starting with ident */
            /* save pos, try to parse as index-assign */
            int save=g_pos;
            advance(); /* ident */
            advance(); /* [ */
            ASTNode*idx=parse_expr();
            if(check(TK_RB)&&g_toks[g_pos+1].type==TK_ASSIGN){
                advance(); /* ] */
                advance(); /* = */
                ASTNode*val=parse_expr();match(TK_SEMI);
                ASTNode*obj=new_node(N_IDENT);obj->line=t->line;obj->ident.name=t->sval;
                ASTNode*n=new_node(S_IDXASSIGN);n->line=t->line;n->idxassign.obj=obj;n->idxassign.idx=idx;n->idxassign.val=val;
                return n;
            }
            g_pos=save; /* backtrack */
        }
    }
    /* general index-assign: postfix [ expr ] = expr ; */
    /* Actually we need to handle: expr [ expr ] = expr ; where expr is a postfix */
    /* Let me re-approach: parse as expression, then check if next is [ */
    /* Actually the grammar says: postfix "[" expr "]" "=" expr ";" */
    /* So we parse a postfix expression, then if followed by [ we have index-assign */
    /* But we already handle IDENT[...] above. For general postfix[...]... */
    /* Let me try a different approach: parse expression, if followed by [ then it's index-assign */
    /* Hmm, but that conflicts with indexing in expressions. */
    /* The key insight: index-assign is only at statement level. */
    /* So: parse a postfix expression. If followed by '[', parse index, then expect '=', parse value, ';'. */
    /* Otherwise it's an expression statement. */

    /* Actually, let me re-think. The grammar for stmt includes:
       postfix "[" expr "]" "=" expr ";"
       expr ";"
       The postfix in the first case is the object being indexed. */

    /* Let me try: parse an expression. If after parsing we see '[', it might be index-assign. */
    /* But that's ambiguous with normal indexing. */

    /* Better approach: try to parse as index-assign. If it fails (no '=' after ']'), backtrack. */
    /* Actually, let me just parse normally and handle it differently. */

    /* Simplest correct approach: */
    /* Parse a postfix expression. Then check if next token is '['. If so, this is index-assign. */
    /* But wait, postfix already consumes [...]. So after parse_expr, if we see '[', it's NOT part of the expr. */
    /* Hmm, actually in the grammar, postfix includes [...]. So `a[0]` is a postfix expression. */
    /* And `a[0] = v` is: postfix(a) [ expr(0) ] = expr(v). Wait no. */
    /* Let me re-read: postfix "[" expr "]" "=" expr ";" */
    /* So the postfix is just the base (without the [...]). Then [ expr ] = expr. */
    /* But postfix already includes [...]. So `a[0][1] = v` would be: postfix(a[0]) [ expr(1) ] = expr(v). */
    /* Actually I think the grammar means: parse a postfix expression, then if followed by [expr]=expr, it's an index-assign. */

    /* Let me just use the approach: parse expression. If next is '[', it's index-assign. */
    /* But parse_expr already consumes [...]. So after parse_expr, we won't see '['. */
    /* Unless... the last thing parsed was NOT an index. Like `foo[0]` - parse_expr gives us the whole thing. */
    /* Then `foo[0] = v` - after parse_expr we have the value foo[0], and next token is '='. */
    /* But we need the AST to know what was indexed. */

    /* OK let me use a different approach: save position, try to parse as index-assign, backtrack if fails. */

    /* Actually, the cleanest approach for the parser: */
    /* At statement level, parse a postfix expression. Then: */
    /*   if next is '[': it's index-assign. Parse [ expr ] = expr ; */
    /*   if next is '=': it's simple assign (but we already handled IDENT= above) */
    /*   otherwise: expr ; */

    /* But wait, parse_postfix already consumes [...]. So after parse_postfix, we won't see '['. */
    /* Unless the postfix is something like `f(x)` and then `[0]` follows. */
    /* In that case, parse_postfix would consume `f(x)[0]` as part of the postfix chain. */

    /* I think the issue is: how does the parser distinguish `a[0]` (index read) from `a[0] = v` (index write)? */
    /* Answer: lookahead. After parsing the postfix chain, if the next token is '=', we need to restructure. */
    /* But that's complex. */

    /* Alternative: handle it at statement level. */
    /* Parse expression. If next token is '=', then the expression must be an index node. */
    /* Convert it to an index-assign. */

    /* Let me try this approach: */
    ASTNode*expr=parse_expr();
    if(check(TK_ASSIGN)){
        advance();
        ASTNode*val=parse_expr();match(TK_SEMI);
        /* expr should be an N_INDEX node */
        if(expr->type==N_INDEX){
            ASTNode*n=new_node(S_IDXASSIGN);n->line=expr->line;
            n->idxassign.obj=expr->index.obj;n->idxassign.idx=expr->index.idx;n->idxassign.val=val;
            return n;
        }
        /* If it's an IDENT, it's a simple assign (shouldn't reach here due to earlier check) */
        if(expr->type==N_IDENT){
            ASTNode*n=new_node(S_ASSIGN);n->line=expr->line;n->assign.name=expr->ident.name;n->assign.val=val;
            return n;
        }
        /* fallback: shouldn't happen in valid programs */
        ASTNode*n=new_node(S_EXPR);n->line=expr->line;n->exprstmt.expr=expr;return n;
    }
    match(TK_SEMI);
    ASTNode*n=new_node(S_EXPR);n->line=t->line;n->exprstmt.expr=expr;return n;
}

static ASTNode*parse_program(void){
    ASTNode*n=new_node(S_BLOCK);n->line=1;
    int cap=64;ASTNode**stmts=malloc(cap*sizeof(ASTNode*));int cnt=0;
    while(!check(TK_EOF)){
        if(cnt>=cap){cap*=2;stmts=realloc(stmts,cap*sizeof(ASTNode*));}
        stmts[cnt++]=parse_stmt();
    }
    n->block.stmts=stmts;n->block.nstmts=cnt;return n;
}

/* ===== Value helpers ===== */
static Value mk_int(int64_t i){Value v={V_INT,.i=i};return v;}
static Value mk_bool(bool b){Value v={V_BOOL,.b=b};return v;}
static Value mk_str(const char*d,int len){Value v={V_STR};v.s.data=malloc(len);memcpy(v.s.data,d,len);v.s.len=len;return v;}
static Value mk_nil(void){Value v={V_NIL};return v;}
static Value mk_list(List*l){Value v={V_LIST,.list=l};return v;}
static Value mk_fn(FuncVal*f){Value v={V_FN,.fn=f};return v;}

static List*list_new(void){List*l=malloc(sizeof(List));l->items=NULL;l->len=0;l->cap=0;return l;}
static void list_push(List*l,Value v){
    if(l->len>=l->cap){l->cap=l->cap?l->cap*2:8;l->items=realloc(l->items,l->cap*sizeof(Value));}
    l->items[l->len++]=v;
}

/* ===== Scope ===== */
static Scope*scope_new(Scope*parent){Scope*s=malloc(sizeof(Scope));s->bindings=NULL;s->parent=parent;return s;}
static void scope_decl(Scope*s,const char*name,Value val){
    Binding*b=malloc(sizeof(Binding));b->name=(char*)name;b->val=val;b->next=s->bindings;s->bindings=b;
}
static Binding*scope_lookup(Scope*s,const char*name){
    while(s){
        for(Binding*b=s->bindings;b;b=b->next)if(strcmp(b->name,name)==0)return b;
        s=s->parent;
    }
    return NULL;
}
static const char*type_name(int t){
    switch(t){case V_INT:return"int";case V_BOOL:return"bool";case V_STR:return"string";
    case V_LIST:return"list";case V_FN:return"function";default:return"nil";}
}

/* ===== Display ===== */
static List*disp_stack[256];static int disp_top=0;

static void sb_putc(char**buf,int*len,int*cap,char c){
    if(*len>=*cap){*cap=*cap?*cap*2:64;*buf=realloc(*buf,*cap);}
    (*buf)[(*len)++]=c;
}
static void sb_puts(char**buf,int*len,int*cap,const char*s){while(*s)sb_putc(buf,len,cap,*s++);}
static void sb_putint(char**buf,int*len,int*cap,int64_t v){
    char tmp[24];int n=0;bool neg=false;
    if(v<0){neg=true;/* handle INT64_MIN */
        unsigned long long uv=-(unsigned long long)v;
        do{tmp[n++]='0'+(uv%10);uv/=10;}while(uv);
    }else{do{tmp[n++]='0'+(v%10);v/=10;}while(v);}
    if(neg)sb_putc(buf,len,cap,'-');
    for(int i=n-1;i>=0;i--)sb_putc(buf,len,cap,tmp[i]);
}

static void display_sb(char**buf,int*len,int*cap,Value v,int in_list){
    switch(v.type){
        case V_INT:sb_putint(buf,len,cap,v.i);break;
        case V_BOOL:sb_puts(buf,len,cap,v.b?"true":"false");break;
        case V_NIL:sb_puts(buf,len,cap,"nil");break;
        case V_STR:
            if(in_list){
                sb_putc(buf,len,cap,'"');
                for(int i=0;i<v.s.len;i++){
                    char c=v.s.data[i];
                    if(c=='\\')sb_puts(buf,len,cap,"\\\\");
                    else if(c=='"')sb_puts(buf,len,cap,"\\\"");
                    else if(c=='\n')sb_puts(buf,len,cap,"\\n");
                    else if(c=='\t')sb_puts(buf,len,cap,"\\t");
                    else sb_putc(buf,len,cap,c);
                }
                sb_putc(buf,len,cap,'"');
            }else{
                for(int i=0;i<v.s.len;i++)sb_putc(buf,len,cap,v.s.data[i]);
            }
            break;
        case V_LIST:
            for(int i=0;i<disp_top;i++)if(disp_stack[i]==v.list){sb_puts(buf,len,cap,"[...]");return;}
            disp_stack[disp_top++]=v.list;
            sb_putc(buf,len,cap,'[');
            for(int i=0;i<v.list->len;i++){
                if(i)sb_puts(buf,len,cap,", ");
                display_sb(buf,len,cap,v.list->items[i],1);
            }
            sb_putc(buf,len,cap,']');
            disp_top--;
            break;
        case V_FN:sb_puts(buf,len,cap,"<fn>");break;
    }
}

static void do_print(Value*args,int nargs){
    char*buf=NULL;int len=0,cap=0;
    for(int i=0;i<nargs;i++){
        if(i)sb_putc(&buf,&len,&cap,' ');
        display_sb(&buf,&len,&cap,args[i],0);
    }
    sb_putc(&buf,&len,&cap,'\n');
    fwrite(buf,1,len,stdout);
    free(buf);
}

static Value do_str(Value v){
    char*buf=NULL;int len=0,cap=0;
    display_sb(&buf,&len,&cap,v,0);
    Value r={V_STR};r.s.data=buf;r.s.len=len;return r;
}

/* ===== Eval ===== */
static void exec_block(ASTNode*blk,Scope*sc);
static Value eval(ASTNode*n,Scope*sc);

static bool truthy(Value v){
    switch(v.type){
        case V_BOOL:return v.b;
        case V_NIL:return false;
        case V_INT:return v.i!=0;
        case V_STR:return v.s.len!=0;
        case V_LIST:return v.list->len!=0;
        default:return true;
    }
}

static bool val_eq(Value a,Value b){
    if(a.type!=b.type)return false;
    switch(a.type){
        case V_INT:return a.i==b.i;
        case V_BOOL:return a.b==b.b;
        case V_NIL:return true;
        case V_STR:
            if(a.s.len!=b.s.len)return false;
            return memcmp(a.s.data,b.s.data,a.s.len)==0;
        case V_LIST:{
            if(a.list->len!=b.list->len)return false;
            for(int i=0;i<a.list->len;i++)if(!val_eq(a.list->items[i],b.list->items[i]))return false;
            return true;
        }
        case V_FN:return a.fn==b.fn;
    }
    return false;
}

static int cmp_str(const char*a,int al,const char*b,int bl){
    int n=al<bl?al:bl;
    for(int i=0;i<n;i++){if((unsigned char)a[i]!=(unsigned char)b[i])return(unsigned char)a[i]<(unsigned char)b[i]?-1:1;}
    if(al==bl)return 0;return al<bl?-1:1;
}

static Value eval(ASTNode*n,Scope*sc){
    switch(n->type){
        case N_INT:return mk_int(n->ival);
        case N_STR:return mk_str(n->sval.data,n->sval.len);
        case N_BOOL:return mk_bool(n->ival);
        case N_NIL:return mk_nil();
        case N_IDENT:{
            Binding*b=scope_lookup(sc,n->ident.name);
            if(!b)err(n->line,"undefined variable %s",n->ident.name);
            return b->val;
        }
        case N_BIN:{
            int op=n->bin.op;
            if(op==TK_AND){
                Value l=eval(n->bin.l,sc);
                if(!truthy(l))return l;
                return eval(n->bin.r,sc);
            }
            if(op==TK_OR){
                Value l=eval(n->bin.l,sc);
                if(truthy(l))return l;
                return eval(n->bin.r,sc);
            }
            Value l=eval(n->bin.l,sc);
            Value r=eval(n->bin.r,sc);
            if(op==TK_EQ)return mk_bool(val_eq(l,r));
            if(op==TK_NE)return mk_bool(!val_eq(l,r));
            if(op==TK_AND||op==TK_OR)return mk_bool(false);/* unreachable */
            /* comparison */
            if(op==TK_LT||op==TK_LE||op==TK_GT||op==TK_GE){
                if(l.type==V_INT&&r.type==V_INT){
                    int c=l.i<r.i?-1:(l.i>r.i?1:0);
                    if(op==TK_LT)return mk_bool(c<0);
                    if(op==TK_LE)return mk_bool(c<=0);
                    if(op==TK_GT)return mk_bool(c>0);
                    return mk_bool(c>=0);
                }
                if(l.type==V_STR&&r.type==V_STR){
                    int c=cmp_str(l.s.data,l.s.len,r.s.data,r.s.len);
                    if(op==TK_LT)return mk_bool(c<0);
                    if(op==TK_LE)return mk_bool(c<=0);
                    if(op==TK_GT)return mk_bool(c>0);
                    return mk_bool(c>=0);
                }
                err(n->line,"cannot apply %s to %s and %s",
                    op==TK_LT?"<":op==TK_LE?"<=":op==TK_GT?">":">=",type_name(l.type),type_name(r.type));
            }
            /* arithmetic */
            if(op==TK_PLUS){
                if(l.type==V_INT&&r.type==V_INT){
                    int64_t res;if(__builtin_add_overflow(l.i,r.i,&res))err(n->line,"integer overflow");
                    return mk_int(res);
                }
                if(l.type==V_STR&&r.type==V_STR){
                    int nl=l.s.len+r.s.len;char*nd=malloc(nl);
                    memcpy(nd,l.s.data,l.s.len);memcpy(nd+l.s.len,r.s.data,r.s.len);
                    Value v={V_STR};v.s.data=nd;v.s.len=nl;return v;
                }
                if(l.type==V_LIST&&r.type==V_LIST){
                    List*nl=list_new();nl->cap=l.list->len+r.list->len;
                    nl->items=malloc(nl->cap*sizeof(Value));nl->len=0;
                    for(int i=0;i<l.list->len;i++)list_push(nl,l.list->items[i]);
                    for(int i=0;i<r.list->len;i++)list_push(nl,r.list->items[i]);
                    return mk_list(nl);
                }
                err(n->line,"cannot apply + to %s and %s",type_name(l.type),type_name(r.type));
            }
            if(op==TK_MINUS||op==TK_STAR||op==TK_SLASH||op==TK_PCT){
                if(l.type!=V_INT||r.type!=V_INT)
                    err(n->line,"cannot apply %s to %s and %s",
                        op==TK_MINUS?"-":op==TK_STAR?"*":op==TK_SLASH?"/":"%",type_name(l.type),type_name(r.type));
                int64_t res;
                if(op==TK_MINUS){if(__builtin_sub_overflow(l.i,r.i,&res))err(n->line,"integer overflow");return mk_int(res);}
                if(op==TK_STAR){if(__builtin_mul_overflow(l.i,r.i,&res))err(n->line,"integer overflow");return mk_int(res);}
                if(op==TK_SLASH){
                    if(r.i==0)err(n->line,"division by zero");
                    if(l.i==INT64_MIN&&r.i==-1)err(n->line,"integer overflow");
                    return mk_int(l.i/r.i);
                }
                if(op==TK_PCT){
                    if(r.i==0)err(n->line,"division by zero");
                    if(r.i==-1)return mk_int(0);
                    return mk_int(l.i%r.i);
                }
            }
            return mk_nil();
        }
        case N_UN:{
            Value v=eval(n->un.operand,sc);
            if(n->un.op==TK_NOT)return mk_bool(!truthy(v));
            if(n->un.op==TK_MINUS){
                if(v.type!=V_INT)err(n->line,"cannot apply - to %s",type_name(v.type));
                if(v.i==INT64_MIN)err(n->line,"integer overflow");
                return mk_int(-v.i);
            }
            return mk_nil();
        }
        case N_INDEX:{
            Value obj=eval(n->index.obj,sc);
            Value idx=eval(n->index.idx,sc);
            if(obj.type!=V_LIST&&obj.type!=V_STR)
                err(n->line,"cannot index %s with %s",type_name(obj.type),type_name(idx.type));
            if(idx.type!=V_INT)
                err(n->line,"cannot index %s with %s",type_name(obj.type),type_name(idx.type));
            int64_t i=idx.i;
            int len=obj.type==V_LIST?obj.list->len:obj.s.len;
            if(i<0||i>=len)err(n->line,"index %lld out of range for length %d",(long long)i,len);
            if(obj.type==V_LIST)return obj.list->items[i];
            return mk_str(obj.s.data+i,1);
        }
        case N_LIST:{
            List*l=list_new();
            for(int i=0;i<n->listlit.nelem;i++)list_push(l,eval(n->listlit.elems[i],sc));
            return mk_list(l);
        }
        case N_FN:{
            FuncVal*f=malloc(sizeof(FuncVal));
            f->params=n->fnlit.params;f->nparams=n->fnlit.nparams;
            f->body=n->fnlit.body;f->captured=sc;f->builtin_id=-1;
            return mk_fn(f);
        }
        case N_CALL:{
            Value callee=eval(n->call.callee,sc);
            Value args[64];int nargs=n->call.nargs;
            for(int i=0;i<nargs;i++)args[i]=eval(n->call.args[i],sc);
            if(callee.type!=V_FN)err(n->line,"cannot call %s",type_name(callee.type));
            FuncVal*f=callee.fn;
            if(f->builtin_id>=0){
                /* builtin */
                int expected=f->nparams;
                if(expected>=0&&nargs!=expected)err(n->line,"expected %d arguments, got %d",expected,nargs);
                switch(f->builtin_id){
                    case 0:/* print */
                        do_print(args,nargs);return mk_nil();
                    case 1:/* str */
                        return do_str(args[0]);
                    case 2:/* type */
                        return mk_str(type_name(args[0].type),strlen(type_name(args[0].type)));
                    case 3:{/* len */
                        if(args[0].type!=V_STR&&args[0].type!=V_LIST)err(n->line,"bad argument to len");
                        int l=args[0].type==V_STR?args[0].s.len:args[0].list->len;
                        return mk_int(l);
                    }
                    case 4:{/* push */
                        if(args[0].type!=V_LIST)err(n->line,"bad argument to push");
                        list_push(args[0].list,args[1]);return mk_nil();
                    }
                    case 5:{/* pop */
                        if(args[0].type!=V_LIST)err(n->line,"bad argument to pop");
                        if(args[0].list->len==0)err(n->line,"bad argument to pop");
                        return args[0].list->items[--args[0].list->len];
                    }
                    case 6:{/* range */
                        if(args[0].type!=V_INT||args[1].type!=V_INT)err(n->line,"bad argument to range");
                        int64_t a=args[0].i,b=args[1].i;
                        List*l=list_new();
                        if(b>a){l->cap=(int)(b-a);l->items=malloc(l->cap*sizeof(Value));l->len=0;
                            for(int64_t x=a;x<b;x++)list_push(l,mk_int(x));}
                        return mk_list(l);
                    }
                    case 7:{/* slice */
                        if(args[0].type!=V_STR&&args[0].type!=V_LIST)err(n->line,"bad argument to slice");
                        if(args[1].type!=V_INT||args[2].type!=V_INT)err(n->line,"bad argument to slice");
                        int64_t a=args[1].i,b=args[2].i;
                        int xl=args[0].type==V_STR?args[0].s.len:args[0].list->len;
                        if(a<0||b>xl||a>b)err(n->line,"bad argument to slice");
                        if(args[0].type==V_STR){
                            int nl=(int)(b-a);char*nd=malloc(nl>0?nl:1);
                            if(nl>0)memcpy(nd,args[0].s.data+a,nl);
                            Value v={V_STR};v.s.data=nd;v.s.len=nl;return v;
                        }else{
                            List*nl=list_new();nl->cap=(int)(b-a);nl->items=malloc(nl->cap*sizeof(Value));nl->len=0;
                            for(int64_t i=a;i<b;i++)list_push(nl,args[0].list->items[i]);
                            return mk_list(nl);
                        }
                    }
                }
                return mk_nil();
            }
            /* user function */
            if(nargs!=f->nparams)err(n->line,"expected %d arguments, got %d",f->nparams,nargs);
            Scope*call_sc=scope_new(f->captured);
            for(int i=0;i<f->nparams;i++)scope_decl(call_sc,f->params[i],args[i]);
            exec_block(f->body,call_sc);
            Value ret=mk_nil();
            if(g_cf==3){ret=g_retval;g_cf=0;}
            return ret;
        }
        default:return mk_nil();
    }
}

static void exec_block(ASTNode*blk,Scope*sc){
    for(int i=0;i<blk->block.nstmts;i++){
        ASTNode*s=blk->block.stmts[i];
        switch(s->type){
            case S_LET:eval(s->letstmt.val,sc);scope_decl(sc,s->letstmt.name,eval(s->letstmt.val,sc));break;
            /* wait, that evaluates twice! Let me fix. */
            default:break;
        }
        break;
    }
}

/* Let me redo exec_block properly */
static void exec_stmt(ASTNode*s,Scope*sc){
    switch(s->type){
        case S_LET:{
            Value v=eval(s->letstmt.val,sc);
            scope_decl(sc,s->letstmt.name,v);
            break;
        }
        case S_FNDECL:{
            FuncVal*f=malloc(sizeof(FuncVal));
            f->params=s->fndecl.params;f->nparams=s->fndecl.nparams;
            f->body=s->fndecl.body;f->captured=sc;f->builtin_id=-1;
            scope_decl(sc,s->fndecl.name,mk_fn(f));
            break;
        }
        case S_IF:{
            Value c=eval(s->ifstmt.cond,sc);
            if(truthy(c)){Scope*sc2=scope_new(sc);exec_block(s->ifstmt.thenb,sc2);}
            else if(s->ifstmt.elseb){
                if(s->ifstmt.elseb->type==S_IF){exec_stmt(s->ifstmt.elseb,sc);}
                else{Scope*sc2=scope_new(sc);exec_block(s->ifstmt.elseb,sc2);}
            }
            break;
        }
        case S_WHILE:{
            while(truthy(eval(s->whilestmt.cond,sc))){
                Scope*sc2=scope_new(sc);
                exec_block(s->whilestmt.body,sc2);
                if(g_cf==1){g_cf=0;break;}
                if(g_cf==2){g_cf=0;continue;}
                if(g_cf==3)break;
            }
            break;
        }
        case S_FOR:{
            Value iter=eval(s->forstmt.iter,sc);
            if(iter.type!=V_LIST)err(s->line,"cannot iterate %s",type_name(iter.type));
            List*lst=iter.list;
            int64_t i=0;
            while(i<lst->len){
                Scope*sc2=scope_new(sc);
                scope_decl(sc2,s->forstmt.var,lst->items[i]);
                exec_block(s->forstmt.body,sc2);
                if(g_cf==1){g_cf=0;break;}
                if(g_cf==2){g_cf=0;}
                if(g_cf==3)break;
                i++;
            }
            break;
        }
        case S_RETURN:{
            g_cf=3;g_retval=s->retstmt.val?eval(s->retstmt.val,sc):mk_nil();
            break;
        }
        case S_BREAK:g_cf=1;break;
        case S_CONTINUE:g_cf=2;break;
        case S_ASSIGN:{
            Value v=eval(s->assign.val,sc);
            Binding*b=scope_lookup(sc,s->assign.name);
            if(!b)err(s->line,"undefined variable %s",s->assign.name);
            b->val=v;
            break;
        }
        case S_IDXASSIGN:{
            Value obj=eval(s->idxassign.obj,sc);
            Value idx=eval(s->idxassign.idx,sc);
            Value val=eval(s->idxassign.val,sc);
            if(obj.type!=V_LIST)err(s->line,"cannot assign into %s",type_name(obj.type));
            if(idx.type!=V_INT)err(s->line,"cannot index list with %s",type_name(idx.type));
            int64_t i=idx.i;
            if(i<0||i>=obj.list->len)err(s->line,"index %lld out of range for length %d",(long long)i,obj.list->len);
            obj.list->items[i]=val;
            break;
        }
        case S_EXPR:eval(s->exprstmt.expr,sc);break;
        case S_BLOCK:{Scope*sc2=scope_new(sc);exec_block(s,sc2);break;}
        default:break;
    }
}

static void exec_block(ASTNode*blk,Scope*sc){
    for(int i=0;i<blk->block.nstmts;i++){
        exec_stmt(blk->block.stmts[i],sc);
        if(g_cf!=0)return;
    }
}

/* ===== Builtins setup ===== */
static void setup_builtins(void){
    g_builtins=scope_new(NULL);
    const char*names[]={"print","str","type","len","push","pop","range","slice"};
    int nparams[]={-1,1,1,1,2,1,2,3};
    for(int i=0;i<8;i++){
        FuncVal*f=malloc(sizeof(FuncVal));
        f->params=NULL;f->nparams=nparams[i];f->body=NULL;f->captured=NULL;f->builtin_id=i;
        scope_decl(g_builtins,names[i],mk_fn(f));
    }
}

