// Encode PNG
var pngData: [UInt8] = []

// PNG signature
pngData.append(contentsOf: [137, 80, 78, 71, 13, 10, 26, 10])

// IHDR chunk
var ihdrData: [UInt8] = []
ihdrData.append(contentsOf: writeBE32(UInt32(width)))
ihdrData.append(contentsOf: writeBE32(UInt32(height)))
ihdrData.append(8)  // bit depth
ihdrData.append(2)  // color type: RGB
ihdrData.append(0)  // compression method
ihdrData.append(0)  // filter method
ihdrData.append(0)  // interlace method
pngData.append(contentsOf: makeChunk(type: "IHDR", data: ihdrData))

// Build raw image data (scanlines with filter byte 0)
var rawData: [UInt8] = []
rawData.reserveCapacity(height * (1 + width * 3))
for y in 0..<height {
    rawData.append(0) // filter type None
    let rowStart = y * width * 3
    for x in 0..<width {
        let idx = rowStart + x * 3
        rawData.append(UInt8(canvas[idx]))
        rawData.append(UInt8(canvas[idx + 1]))
        rawData.append(UInt8(canvas[idx + 2]))
    }
}

// Zlib encode with stored blocks
var zlibData: [UInt8] = []
zlibData.append(0x78) // CMF: deflate, window 32K
zlibData.append(0x01) // FLG: check bits so (CMF*256+FLG)%31==0

let maxBlock = 65535
var offset = 0
if rawData.isEmpty {
    zlibData.append(0x01) // BFINAL=1, BTYPE=00
    zlibData.append(contentsOf: writeLE16(0))
    zlibData.append(contentsOf: writeLE16(0xFFFF))
} else {
    while offset < rawData.count {
        let blockLen = min(maxBlock, rawData.count - offset)
        let isFinal: UInt8 = (offset + blockLen >= rawData.count) ? 1 : 0
        zlibData.append(isFinal) // BFINAL in bit 0, BTYPE=00
        zlibData.append(contentsOf: writeLE16(UInt16(blockLen)))
        zlibData.append(contentsOf: writeLE16(~UInt16(blockLen)))
        zlibData.append(contentsOf: rawData[offset..<(offset + blockLen)])
        offset += blockLen
    }
}

// Adler-32 checksum of uncompressed data
zlibData.append(contentsOf: writeBE32(adler32(rawData)))

pngData.append(contentsOf: makeChunk(type: "IDAT", data: zlibData))

// IEND chunk
pngData.append(contentsOf: makeChunk(type: "IEND", data: []))

// Write output file
FileManager.default.createFile(atPath: "out.png", contents: Data(pngData))

import Foundation

let crcTable: [UInt32] = {
    var table = [UInt32](repeating: 0, count: 256)
    for i in 0..<256 {
        var c = UInt32(i)
        for _ in 0..<8 {
            if c & 1 != 0 {
                c = 0xEDB88320 ^ (c >> 1)
            } else {
                c = c >> 1
            }
        }
        table[i] = c
    }
    return table
}()

func crc32(_ data: [UInt8]) -> UInt32 {
    var c: UInt32 = 0xFFFFFFFF
    for b in data {
        c = crcTable[Int((c ^ UInt32(b)) & 0xFF)] ^ (c >> 8)
    }
    return c ^ 0xFFFFFFFF
}

func adler32(_ data: [UInt8]) -> UInt32 {
    var a: UInt32 = 1
    var b: UInt32 = 0
    for byte in data {
        a = (a + UInt32(byte)) % 65521
        b = (b + a) % 65521
    }
    return (b << 16) | a
}

func writeBE32(_ value: UInt32) -> [UInt8] {
    return [UInt8(value >> 24), UInt8(value >> 16), UInt8(value >> 8), UInt8(value & 0xFF)]
}

func writeLE16(_ value: UInt16) -> [UInt8] {
    return [UInt8(value & 0xFF), UInt8(value >> 8)]
}

func makeChunk(type: String, data: [UInt8]) -> [UInt8] {
    var chunk: [UInt8] = []
    let typeBytes = Array(type.utf8)
    chunk.append(contentsOf: writeBE32(UInt32(data.count)))
    chunk.append(contentsOf: typeBytes)
    chunk.append(contentsOf: data)
    let crcData = typeBytes + data
    chunk.append(contentsOf: writeBE32(crc32(crcData)))
    return chunk
}

func blend(_ s: Int, _ d: Int, _ a: Int) -> Int {
    return (s * a + d * (255 - a) + 127) / 255
}

