        let ex2 = Int64(px0 - px2), ey2 = Int64(py0 - py2)
        if xStart <= xEnd && yStart <= yEnd {
            for y in yStart...yEnd {
                let iy0 = Int64(y - py0)
                let iy1 = Int64(y - py1)
                let iy2 = Int64(y - py2)
                for x in xStart...xEnd {
