        let ly1 = shape.y1!
        let lx2 = shape.x2!
        let ly2 = shape.y2!
        let lr = shape.r!
        let dx = Int64(lx2 - lx1)
        let dy = Int64(ly2 - ly1)
        let L = dx * dx + dy * dy
        let r2 = Int64(lr) * Int64(lr)
        let xStart = max(0, min(lx1, lx2) - lr)
        let xEnd = min(width - 1, max(lx1, lx2) + lr)
        let yStart = max(0, min(ly1, ly2) - lr)
        let yEnd = min(height - 1, max(ly1, ly2) + lr)
        if xStart <= xEnd && yStart <= yEnd {
            for y in yStart...yEnd {
                let iy1 = Int64(y - ly1)
                let iy2 = Int64(y - ly2)
                for x in xStart...xEnd {
                    let ix1 = Int64(x - lx1)
                    let ix2 = Int64(x - lx2)
                    var covered = false
                    if L == 0 {
                        covered = ix1 * ix1 + iy1 * iy1 <= r2
                    } else {
                        let t = ix1 * dx + iy1 * dy
                        if t <= 0 {
                            covered = ix1 * ix1 + iy1 * iy1 <= r2
