// CRC-32
static uint32_t crc_table[256];

void init_crc(void) {
    for (uint32_t i = 0; i < 256; i++) {
        uint32_t c = i;
        for (int k = 0; k < 8; k++)
            c = (c & 1) ? (0xEDB88320 ^ (c >> 1)) : (c >> 1);
        crc_table[i] = c;
    }
}

uint32_t crc32(uint32_t crc, const uint8_t *buf, size_t len) {
    crc ^= 0xFFFFFFFF;
    for (size_t i = 0; i < len; i++)
        crc = crc_table[(crc ^ buf[i]) & 0xFF] ^ (crc >> 8);
    return crc ^ 0xFFFFFFFF;
}

// Actually, for PNG chunk CRC, we compute CRC over type+data bytes.
// The standard CRC-32 starts with 0xFFFFFFFF and ends with XOR 0xFFFFFFFF.
// Let me verify: PNG CRC is computed using the same algorithm as zlib's crc32.
// zlib's crc32(0, buf, len) computes CRC-32 with initial value 0 (which internally uses 0xFFFFFFFF).
// PNG chunk CRC = crc32(0, type_and_data, type_and_data_length)

// Let me redo:
uint32_t crc32_compute(const uint8_t *buf, size_t len) {
    uint32_t crc = 0xFFFFFFFF;
    for (size_t i = 0; i < len; i++)
        crc = crc_table[(crc ^ buf[i]) & 0xFF] ^ (crc >> 8);
    return crc ^ 0xFFFFFFFF;
}

// Adler-32
uint32_t adler32_compute(const uint8_t *data, size_t len) {
    uint32_t s1 = 1, s2 = 0;
    for (size_t i = 0; i < len; i++) {
        s1 = (s1 + data[i]) % 65521;
        s2 = (s2 + s1) % 65521;
    }
    return (s2 << 16) | s1;
}

// Bit reader for DEFLATE
typedef struct {
    const uint8_t *data;
    size_t len;
    size_t pos;
    int bit;
} BitReader;

static inline int read_bit(BitReader *br) {
    int b = (br->data[br->pos] >> br->bit) & 1;
    if (++br->bit == 8) { br->bit = 0; br->pos++; }
    return b;
}

static inline int read_bits_lsb(BitReader *br, int n) {
    int val = 0;
    for (int i = 0; i < n; i++)
        val |= read_bit(br) << i;
    return val;
}

static inline void align_byte(BitReader *br) {
    if (br->bit != 0) { br->bit = 0; br->pos++; }
}

// Huffman tree
typedef struct {
    int max_bits;
    int count[16];
    int min_code[16];
    int symbol[288];
} HuffTree;

void build_huff(HuffTree *t, const int *lengths, int n) {
    memset(t, 0, sizeof(*t));
    t->max_bits = 0;
    for (int i = 0; i < n; i++) {
        if (lengths[i] > 0) {
            t->count[lengths[i]]++;
            if (lengths[i] > t->max_bits) t->max_bits = lengths[i];
        }
    }
    int code = 0;
    for (int len = 1; len <= 15; len++) {
        t->min_code[len] = code;
        code = (code + t->count[len]) << 1;
    }
    int idx = 0;
    for (int len = 1; len <= 15; len++)
        for (int i = 0; i < n; i++)
            if (lengths[i] == len)
                t->symbol[idx++] = i;
}

int decode_huff(HuffTree *t, BitReader *br) {
    int code = 0;
    for (int len = 1; len <= t->max_bits; len++) {
        code = (code << 1) | read_bit(br);
        if (code - t->min_code[len] < t->count[len]) {
            // offset into symbol array
            int off = 0;
            for (int l = 1; l < len; l++) off += t->count[l];
            return t->symbol[off + (code - t->min_code[len])];
        }
    }
    return -1;
}

// Fixed Huffman tables
static int fixed_lit_lengths[288];
static int fixed_dist_lengths[30];
static HuffTree fixed_lit, fixed_dist;

void init_fixed(void) {
    for (int i = 0; i < 144; i++) fixed_lit_lengths[i] = 8;
    for (int i = 144; i < 256; i++) fixed_lit_lengths[i] = 9;
    for (int i = 256; i < 280; i++) fixed_lit_lengths[i] = 7;
    for (int i = 280; i < 288; i++) fixed_lit_lengths[i] = 8;
    for (int i = 0; i < 30; i++) fixed_dist_lengths[i] = 5;
    build_huff(&fixed_lit, fixed_lit_lengths, 288);
    build_huff(&fixed_dist, fixed_dist_lengths, 30);
}

