// Output buffer for decompressed data
typedef struct {
    uint8_t *data;
    size_t len;
    size_t cap;
} OutBuf;

void obuf_init(OutBuf *ob, size_t cap) {
    ob->data = malloc(cap);
    ob->len = 0;
    ob->cap = cap;
}

void obuf_push(OutBuf *ob, uint8_t b) {
    if (ob->len >= ob->cap) {
        ob->cap *= 2;
        ob->data = realloc(ob->data, ob->cap);
    }
    ob->data[ob->len++] = b;
}

// DEFLATE decoder
typedef struct {
    int stored, fixed, dynamic;
} BlockCounts;

int inflate(BitReader *br, OutBuf *ob, BlockCounts *bc) {
    bc->stored = bc->fixed = bc->dynamic = 0;
    int bfinal;
    do {
        bfinal = read_bit(br);
        int btype = read_bits_lsb(br, 2);

        if (btype == 0) {
            // Stored
            bc->stored++;
            align_byte(br);
            int len = read_bits_lsb(br, 16);
            int nlen = read_bits_lsb(br, 16);
            (void)nlen;
            for (int i = 0; i < len; i++)
                obuf_push(ob, read_bits_lsb(br, 8));
        } else if (btype == 1) {
            // Fixed Huffman
            bc->fixed++;
            while (1) {
                int sym = decode_huff(&fixed_lit, br);
                if (sym < 256) {
                    obuf_push(ob, (uint8_t)sym);
                } else if (sym == 256) {
                    break;
                } else {
                    // Length
                    int li = sym - 257;
                    int length = length_base[li] + read_bits_lsb(br, length_extra[li]);
                    int dsym = decode_huff(&fixed_dist, br);
                    int dist = dist_base[dsym] + read_bits_lsb(br, dist_extra[dsym]);
                    for (int i = 0; i < length; i++)
                        obuf_push(ob, ob->data[ob->len - dist]);
                }
            }
        } else if (btype == 2) {
            // Dynamic Huffman
            bc->dynamic++;
            int hlit = read_bits_lsb(br, 5) + 257;
            int hdist = read_bits_lsb(br, 5) + 1;
            int hclen = read_bits_lsb(br, 4) + 4;

            int clcl[19] = {0};
            for (int i = 0; i < hclen; i++)
                clcl[clcl_order[i]] = read_bits_lsb(br, 3);

            HuffTree clcl_tree;
            build_huff(&clcl_tree, clcl, 19);

            int lengths[288 + 30];
            int total = hlit + hdist;
            int i = 0;
            while (i < total) {
                int sym = decode_huff(&clcl_tree, br);
                if (sym < 16) {
                    lengths[i++] = sym;
                } else if (sym == 16) {
                    int prev = lengths[i-1];
                    int rep = 3 + read_bits_lsb(br, 2);
                    for (int j = 0; j < rep; j++) lengths[i++] = prev;
                } else if (sym == 17) {
                    int rep = 3 + read_bits_lsb(br, 3);
                    for (int j = 0; j < rep; j++) lengths[i++] = 0;
                } else if (sym == 18) {
                    int rep = 11 + read_bits_lsb(br, 7);
                    for (int j = 0; j < rep; j++) lengths[i++] = 0;
                }
            }

            HuffTree lit_tree, dist_tree;
            build_huff(&lit_tree, lengths, hlit);
            build_huff(&dist_tree, lengths + hlit, hdist);

            while (1) {
                int sym = decode_huff(&lit_tree, br);
                if (sym < 256) {
                    obuf_push(ob, (uint8_t)sym);
                } else if (sym == 256) {
                    break;
                } else {
                    int li = sym - 257;
                    int length = length_base[li] + read_bits_lsb(br, length_extra[li]);
                    int dsym = decode_huff(&dist_tree, br);
                    int dist = dist_base[dsym] + read_bits_lsb(br, dist_extra[dsym]);
                    for (int j = 0; j < length; j++)
                        obuf_push(ob, ob->data[ob->len - dist]);
                }
            }
        }
    } while (!bfinal);

    return 0;
}

// Paeth predictor
static inline int paeth(int a, int b, int c) {
    int p = a + b - c;
    int pa = p > a ? p - a : a - p;
    int pb = p > b ? p - b : b - p;
    int pc = p > c ? p - c : c - p;
    if (pa <= pb && pa <= pc) return a;
    if (pb <= pc) return b;
    return c;
}

// Compare function for qsort
int cmp_str(const void *a, const void *b) {
    return strcmp(*(const char**)a, *(const char**)b);
}

int main(int argc, char *argv[]) {
    init_crc();
    init_fixed();

    if (argc < 2) return 1;

    DIR *dir = opendir(argv[1]);
    if (!dir) return 1;

    // Collect .png filenames
    char **files = NULL;
    int nfiles = 0, fcap = 0;
    struct dirent *de;
    while ((de = readdir(dir))) {
        size_t nlen = strlen(de->d_name);
        if (nlen > 4 && strcmp(de->d_name + nlen - 4, ".png") == 0) {
            if (nfiles >= fcap) {
                fcap = fcap ? fcap * 2 : 16;
                files = realloc(files, fcap * sizeof(char*));
            }
            files[nfiles++] = strdup(de->d_name);
        }
    }
    closedir(dir);

    qsort(files, nfiles, sizeof(char*), cmp_str);

    for (int fi = 0; fi < nfiles; fi++) {
        char *fname = files[fi];

        // Read file
        char path[4096];
        snprintf(path, sizeof(path), "%s/%s", argv[1], fname);
        FILE *fp = fopen(path, "rb");
        if (!fp) continue;
        fseek(fp, 0, SEEK_END);
        long fsize = ftell(fp);
        fseek(fp, 0, SEEK_SET);
        uint8_t *fdata = malloc(fsize);
        fread(fdata, 1, fsize, fp);
        fclose(fp);

        printf("== %s\n", fname);

        // Check PNG signature
        // 89 50 4E 47 0D 0A 1A 0A
        size_t pos = 8; // skip signature

        // Parse chunks
        typedef struct {
            char type[5];
            size_t data_start;
            size_t data_len;
        } Chunk;

        Chunk *chunks = NULL;
        int nchunks = 0, ccap = 0;

        int crc_error = 0;
        int crc_chunk_num = 0;
        char crc_chunk_type[5];

        while (pos + 12 <= (size_t)fsize) {
            uint32_t clen = (fdata[pos] << 24) | (fdata[pos+1] << 16) | (fdata[pos+2] << 8) | fdata[pos+3];
            char ctype[5];
            memcpy(ctype, fdata + pos + 4, 4);
            ctype[4] = '\0';

            // Check CRC
            uint32_t stored_crc = (fdata[pos + 8 + clen] << 24) | (fdata[pos + 8 + clen + 1] << 16) | 
                                  (fdata[pos + 8 + clen + 2] << 8) | fdata[pos + 8 + clen + 3];
            uint32_t computed_crc = crc32_compute(fdata + pos + 4, 4 + clen);

            if (computed_crc != stored_crc) {
                crc_error = 1;
                crc_chunk_num = nchunks + 1; // 1-based
                memcpy(crc_chunk_type, ctype, 5);
            }

            if (nchunks >= ccap) {
                ccap = ccap ? ccap * 2 : 32;
                chunks = realloc(chunks, ccap * sizeof(Chunk));
            }
            memcpy(chunks[nchunks].type, ctype, 5);
            chunks[nchunks].data_start = pos + 8;
            chunks[nchunks].data_len = clen;
            nchunks++;

            pos += 12 + clen;

            if (strcmp(ctype, "IEND") == 0) break;
        }

        if (crc_error) {
            printf("error: CRC mismatch in chunk %d %s\n", crc_chunk_num, crc_chunk_type);
            free(fdata);
            free(chunks);
            free(fname);
            continue;
        }

        // Extract IHDR
        uint32_t width = 0, height = 0;
        int bit_depth = 0, color_type = 0;
        for (int i = 0; i < nchunks; i++) {
            if (strcmp(chunks[i].type, "IHDR") == 0) {
                uint8_t *d = fdata + chunks[i].data_start;
                width = (d[0] << 24) | (d[1] << 16) | (d[2] << 8) | d[3];
                height = (d[4] << 24) | (d[5] << 16) | (d[6] << 8) | d[7];
                bit_depth = d[8];
                color_type = d[9];
                break;
            }
        }

        // Extract PLTE
        uint8_t *plte = NULL;
        int plte_count = 0;
        for (int i = 0; i < nchunks; i++) {
            if (strcmp(chunks[i].type, "PLTE") == 0) {
                plte = fdata + chunks[i].data_start;
                plte_count = chunks[i].data_len / 3;
                break;
            }
        }

        // Extract tRNS
        uint8_t *trns = NULL;
        int trns_len = 0;
        for (int i = 0; i < nchunks; i++) {
            if (strcmp(chunks[i].type, "tRNS") == 0) {
                trns = fdata + chunks[i].data_start;
                trns_len = chunks[i].data_len;
                break;
            }
        }

        // Concatenate IDAT data
        uint8_t *idat_data = malloc(fsize); // upper bound
        size_t idat_len = 0;
        for (int i = 0; i < nchunks; i++) {
            if (strcmp(chunks[i].type, "IDAT") == 0) {
                memcpy(idat_data + idat_len, fdata + chunks[i].data_start, chunks[i].data_len);
                idat_len += chunks[i].data_len;
            }
        }

        // Parse zlib header
        // CMF (1 byte) + FLG (1 byte)
        // CMF: CM = CMF & 0x0F (should be 8 for DEFLATE), CINFO = CMF >> 4
        // FLG: FCHECK = FLG & 0x1F, FDICT = (FLG >> 5) & 1, FLEVEL = (FLG >> 6) & 3
        // (CMF * 256 + FLG) % 31 == 0
        size_t zpos = 2; // skip zlib header
        // Check FDICT
        if (idat_data[1] & 0x20) {
            zpos += 4; // skip DICTID
        }

        // Inflate
        int samples_per_pixel;
        switch (color_type) {
            case 0: samples_per_pixel = 1; break;
            case 2: samples_per_pixel = 3; break;
            case 3: samples_per_pixel = 1; break;
            case 4: samples_per_pixel = 2; break;
            case 6: samples_per_pixel = 4; break;
            default: samples_per_pixel = 1; break;
        }
        int bits_per_pixel = samples_per_pixel * bit_depth;
        int bpp = (bits_per_pixel + 7) / 8;
        if (bpp < 1) bpp = 1;
        size_t scanline_bytes = (width * bits_per_pixel + 7) / 8;
        size_t total_uncompressed = height * (1 + scanline_bytes);

        OutBuf ob;
        obuf_init(&ob, total_uncompressed + 1024);

        BitReader br;
        br.data = idat_data + zpos;
        br.len = idat_len - zpos;
        br.pos = 0;
        br.bit = 0;

        BlockCounts bc;
        inflate(&br, &ob, &bc);

        // Check Adler-32
        // Adler-32 is at the end of the zlib stream, big-endian
        // It's after the DEFLATE data. We need to find where the DEFLATE data ends.
        // Actually, the Adler-32 is the last 4 bytes of the zlib stream.
        // But we don't know exactly where the DEFLATE data ends from the BitReader position alone...
        // Actually, we do: after inflate() returns, br.pos and br.bit tell us where we are.
        // The remaining bytes after the current position are the Adler-32.

        // Hmm, actually the Adler-32 is at a byte boundary after the DEFLATE data.
        // Let me compute: the DEFLATE data ends at byte position br.pos (if br.bit == 0) or br.pos+1... 
        // Actually, after inflate, the bit reader is positioned right after the last DEFLATE block.
        // The Adler-32 follows immediately. But it might not be at a byte boundary if the DEFLATE 
        // stream doesn't end on a byte boundary... Actually, DEFLATE streams always end on a byte 
        // boundary? No, they don't necessarily. The last block's final bits might not align.

        // Wait, actually in zlib format, the Adler-32 is always at a byte boundary after the DEFLATE data.
        // But the DEFLATE data itself might not end on a byte boundary.
        // Hmm, let me re-read the zlib spec.

        // Actually, looking at zlib more carefully: the Adler-32 checksum is stored as the last 4 bytes 
        // of the zlib stream. The DEFLATE data occupies everything between the zlib header and the 
        // Adler-32. So the Adler-32 is at position idat_len - 4 in the IDAT data.

        // But wait, the DEFLATE data might have trailing bits that aren't part of any block. 
        // In practice, the DEFLATE encoder pads the last block to a byte boundary before the Adler-32.
        // But the spec says the Adler-32 is just the last 4 bytes.

        // Let me just take the last 4 bytes of the IDAT data as Adler-32.
        uint32_t stored_adler = (idat_data[idat_len - 4] << 24) | (idat_data[idat_len - 3] << 16) | 
                                 (idat_data[idat_len - 2] << 8) | idat_data[idat_len - 1];
        uint32_t computed_adler = adler32_compute(ob.data, ob.len);

        if (stored_adler != computed_adler) {
            printf("error: Adler-32 mismatch\n");
            free(fdata);
            free(chunks);
            free(idat_data);
            free(ob.data);
            free(fname);
            continue;
        }

        // Apply filters
        uint8_t *scanlines = malloc(total_uncompressed);
        memcpy(scanlines, ob.data, ob.len);

        int filter_counts[5] = {0};

        for (uint32_t y = 0; y < height; y++) {
            size_t row_start = y * (1 + scanline_bytes);
            int ftype = scanlines[row_start];
            filter_counts[ftype]++;

            uint8_t *row = scanlines + row_start + 1;
            uint8_t *prev_row = (y > 0) ? scanlines + (y-1) * (1 + scanline_bytes) + 1 : NULL;

            for (size_t x = 0; x < scanline_bytes; x++) {
                int a = (x >= (size_t)bpp) ? row[x - bpp] : 0;
                int b = prev_row ? prev_row[x] : 0;
                int c = (prev_row && x >= (size_t)bpp) ? prev_row[x - bpp] : 0;

                switch (ftype) {
                    case 0: break; // None
                    case 1: row[x] = (row[x] + a) & 0xFF; break; // Sub
                    case 2: row[x] = (row[x] + b) & 0xFF; break; // Up
                    case 3: row[x] = (row[x] + (a + b) / 2) & 0xFF; break; // Average
                    case 4: row[x] = (row[x] + paeth(a, b, c)) & 0xFF; break; // Paeth
                }
            }
        }

        // Convert to RGBA
        uint8_t *rgba = malloc((size_t)width * height * 4);
        uint64_t sum_r = 0, sum_g = 0, sum_b = 0, sum_a = 0;

        for (uint32_t y = 0; y < height; y++) {
            uint8_t *row = scanlines + y * (1 + scanline_bytes) + 1;
            for (uint32_t x = 0; x < width; x++) {
                uint8_t r, g, b, a;

                if (bit_depth == 8) {
                    switch (color_type) {
                        case 0: {
                            uint8_t gray = row[x];
                            r = g = b = gray;
                            a = 255;
                            if (trns) {
                                uint16_t trns_val = (trns[0] << 8) | trns[1];
                                if (gray == trns_val) a = 0;
                            }
                            break;
                        }
                        case 2: {
                            r = row[x*3]; g = row[x*3+1]; b = row[x*3+2];
                            a = 255;
                            if (trns) {
                                uint16_t tr = (trns[0] << 8) | trns[1];
                                uint16_t tg = (trns[2] << 8) | trns[3];
                                uint16_t tb = (trns[4] << 8) | trns[5];
                                if (r == tr && g == tg && b == tb) a = 0;
                            }
                            break;
                        }
                        case 3: {
                            uint8_t idx = row[x];
                            r = plte[idx*3]; g = plte[idx*3+1]; b = plte[idx*3+2];
                            a = 255;
                            if (trns && idx < trns_len) a = trns[idx];
                            break;
                        }
                        case 4: {
                            uint8_t gray = row[x*2];
                            r = g = b = gray;
                            a = row[x*2+1];
                            break;
                        }
                        case 6: {
                            r = row[x*4]; g = row[x*4+1]; b = row[x*4+2]; a = row[x*4+3];
                            break;
                        }
                    }
                } else if (bit_depth == 16) {
                    switch (color_type) {
                        case 0: {
                            uint16_t gray = (row[x*2] << 8) | row[x*2+1];
                            r = g = b = gray >> 8;
                            a = 255;
                            if (trns) {
                                uint16_t trns_val = (trns[0] << 8) | trns[1];
                                if (gray == trns_val) a = 0;
                            }
                            break;
                        }
                        case 2: {
                            uint16_t sr = (row[x*6] << 8) | row[x*6+1];
                            uint16_t sg = (row[x*6+2] << 8) | row[x*6+3];
                            uint16_t sb = (row[x*6+4] << 8) | row[x*6+5];
                            r = sr >> 8; g = sg >> 8; b = sb >> 8;
                            a = 255;
                            if (trns) {
                                uint16_t tr = (trns[0] << 8) | trns[1];
                                uint16_t tg = (trns[2] << 8) | trns[3];
                                uint16_t tb = (trns[4] << 8) | trns[5];
                                if (sr == tr && sg == tg && sb == tb) a = 0;
                            }
                            break;
                        }
                        case 3: {
                            uint8_t idx = row[x*2]; // 16-bit palette index? 
                            // Wait, for palette, bit depth is 1, 2, 4, or 8. Not 16.
                            // Actually, the spec says palette color type supports bit depths 1, 2, 4, 8.
                            // So this case shouldn't happen. But let me handle it anyway.
                            r = g = b = 0; a = 255;
                            break;
                        }
                        case 4: {
                            uint16_t gray = (row[x*4] << 8) | row[x*4+1];
                            uint16_t alpha = (row[x*4+2] << 8) | row[x*4+3];
                            r = g = b = gray >> 8;
                            a = alpha >> 8;
                            break;
                        }
                        case 6: {
                            uint16_t sr = (row[x*8] << 8) | row[x*8+1];
                            uint16_t sg = (row[x*8+2] << 8) | row[x*8+3];
                            uint16_t sb = (row[x*8+4] << 8) | row[x*8+5];
                            uint16_t sa = (row[x*8+6] << 8) | row[x*8+7];
                            r = sr >> 8; g = sg >> 8; b = sb >> 8; a = sa >> 8;
                            break;
                        }
                    }
                } else {
