                    int mask = (1 << bit_depth) - 1;
                    int pixels_per_byte = 8 / bit_depth;

                    switch (color_type) {
                        case 0: {
                            int byte_idx = x / pixels_per_byte;
                            int bit_offset = (pixels_per_byte - 1 - (x % pixels_per_byte)) * bit_depth;
                            int gray = (row[byte_idx] >> bit_offset) & mask;
                            gray = gray * 255 / mask;
                            r = g = b = gray;
                            a = 255;
                            if (trns) {
                                // tRNS for grayscale: 2 bytes, big-endian value at original bit depth
                                uint16_t trns_val = (trns[0] << 8) | trns[1];
                                // Compare at original bit depth
                                if (gray * mask / 255 == trns_val) a = 0;
                                // Hmm, this is tricky. The tRNS value is at the original bit depth.
                                // The pixel value before expansion is gray_raw.
                                // We need to compare gray_raw with trns_val.
                                // But we already expanded gray. Let me restructure.
                            }
                            break;
                        }
                        // ... similar for other types
                    }
                }

                rgba[(y * width + x) * 4 + 0] = r;
                rgba[(y * width + x) * 4 + 1] = g;
                rgba[(y * width + x) * 4 + 2] = b;
                rgba[(y * width + x) * 4 + 3] = a;

                sum_r += r; sum_g += g; sum_b += b; sum_a += a;
            }
