fn composite(s: u8, a: u8, d: u8) -> u8 {
    ((s as u32 * a as u32 + d as u32 * (255 - a as u32) + 127) / 255) as u8
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let scene_path = format!("{}/scene.json", dir);
    let content = fs::read_to_string(&scene_path).unwrap();

    let mut parser = JsonParser::new(&content);
    let scene = parser.parse_value();

    let scene_obj = match &scene {
        JsonValue::Object(obj) => obj,
        _ => panic!("Expected object"),
    };

    let width = get_int(scene_obj, "width") as usize;
    let height = get_int(scene_obj, "height") as usize;
    let bg = get_int_array(scene_obj, "background");
    let bg_r = bg[0] as u8;
    let bg_g = bg[1] as u8;
    let bg_b = bg[2] as u8;

    let shapes_val = match get_obj(scene_obj, "shapes") {
        JsonValue::Array(arr) => arr.clone(),
        _ => vec![],
    };

    // Initialize canvas
    let mut canvas: Vec<u8> = vec![0; width * height * 3];
    for i in 0..width * height {
        canvas[i * 3] = bg_r;
        canvas[i * 3 + 1] = bg_g;
        canvas[i * 3 + 2] = bg_b;
    }

    let mut counts: Vec<usize> = Vec::new();
    let mut type_names: Vec<String> = Vec::new();

    for shape_val in &shapes_val {
        let shape_obj = match shape_val {
            JsonValue::Object(obj) => obj,
            _ => continue,
        };

        let shape_type = match get_obj(shape_obj, "type") {
            JsonValue::Str(s) => s.clone(),
            _ => continue,
        };

        let color = get_int_array(shape_obj, "color");
        let sr = color[0] as u8;
        let sg = color[1] as u8;
        let sb = color[2] as u8;
        let sa = color[3] as u8;

        let mut count = 0usize;

        match shape_type.as_str() {
            "rect" => {
                let rx = get_int(shape_obj, "x");
                let ry = get_int(shape_obj, "y");
                let rw = get_int(shape_obj, "w");
                let rh = get_int(shape_obj, "h");

                let x_start = std::cmp::max(0, rx);
                let y_start = std::cmp::max(0, ry);
                let x_end = std::cmp::min(width as i64, rx + rw);
                let y_end = std::cmp::min(height as i64, ry + rh);

                if x_start < x_end && y_start < y_end {
                    for y in y_start..y_end {
                        for x in x_start..x_end {
                            count += 1;
                            let idx = (y as usize * width + x as usize) * 3;
                            canvas[idx] = composite(sr, sa, canvas[idx]);
                            canvas[idx + 1] = composite(sg, sa, canvas[idx + 1]);
                            canvas[idx + 2] = composite(sb, sa, canvas[idx + 2]);
                        }
                    }
                }
            }
            "circle" => {
                let cx = get_int(shape_obj, "cx");
                let cy = get_int(shape_obj, "cy");
                let r = get_int(shape_obj, "r");

                let x_start = std::cmp::max(0, cx - r);
                let y_start = std::cmp::max(0, cy - r);
                let x_end = std::cmp::min(width as i64 - 1, cx + r);
                let y_end = std::cmp::min(height as i64 - 1, cy + r);

                let r2 = r * r;

                if x_start <= x_end && y_start <= y_end {
                    for y in y_start..=y_end {
                        for x in x_start..=x_end {
                            let dx = x - cx;
                            let dy = y - cy;
                            if dx * dx + dy * dy <= r2 {
                                count += 1;
                                let idx = (y as usize * width + x as usize) * 3;
                                canvas[idx] = composite(sr, sa, canvas[idx]);
                                canvas[idx + 1] = composite(sg, sa, canvas[idx + 1]);
                                canvas[idx + 2] = composite(sb, sa, canvas[idx + 2]);
                            }
                        }
                    }
                }
            }
            "triangle" => {
                let points_val = match get_obj(shape_obj, "points") {
                    JsonValue::Array(arr) => arr.clone(),
                    _ => vec![],
                };

                let mut px = [0i64; 3];
                let mut py = [0i64; 3];
                for i in 0..3 {
                    if let JsonValue::Array(pt) = &points_val[i] {
                        px[i] = match &pt[0] { JsonValue::Num(n) => *n, _ => 0 };
                        py[i] = match &pt[1] { JsonValue::Num(n) => *n, _ => 0 };
                    }
                }

                let min_x = std::cmp::min(px[0], std::cmp::min(px[1], px[2]));
                let max_x = std::cmp::max(px[0], std::cmp::max(px[1], px[2]));
                let min_y = std::cmp::min(py[0], std::cmp::min(py[1], py[2]));
                let max_y = std::cmp::max(py[0], std::cmp::max(py[1], py[2]));

                let x_start = std::cmp::max(0, min_x);
                let y_start = std::cmp::max(0, min_y);
                let x_end = std::cmp::min(width as i64 - 1, max_x);
                let y_end = std::cmp::min(height as i64 - 1, max_y);

                if x_start <= x_end && y_start <= y_end {
                    for y in y_start..=y_end {
                        for x in x_start..=x_end {
                            let e0 = (px[1] - px[0]) * (y - py[0]) - (py[1] - py[0]) * (x - px[0]);
                            let e1 = (px[2] - px[1]) * (y - py[1]) - (py[2] - py[1]) * (x - px[1]);
                            let e2 = (px[0] - px[2]) * (y - py[2]) - (py[0] - py[2]) * (x - px[2]);

                            if (e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0) {
                                count += 1;
                                let idx = (y as usize * width + x as usize) * 3;
                                canvas[idx] = composite(sr, sa, canvas[idx]);
                                canvas[idx + 1] = composite(sg, sa, canvas[idx + 1]);
                                canvas[idx + 2] = composite(sb, sa, canvas[idx + 2]);
                            }
                        }
                    }
                }
            }
            "line" => {
                let x1 = get_int(shape_obj, "x1");
                let y1 = get_int(shape_obj, "y1");
                let x2 = get_int(shape_obj, "x2");
                let y2 = get_int(shape_obj, "y2");
                let r = get_int(shape_obj, "r");

                let dx = x2 - x1;
                let dy = y2 - y1;
                let l = dx * dx + dy * dy;
                let r2 = r * r;

                let x_start = std::cmp::max(0, std::cmp::min(x1, x2) - r);
                let y_start = std::cmp::max(0, std::cmp::min(y1, y2) - r);
                let x_end = std::cmp::min(width as i64 - 1, std::cmp::max(x1, x2) + r);
                let y_end = std::cmp::min(height as i64 - 1, std::cmp::max(y1, y2) + r);

                if x_start <= x_end && y_start <= y_end {
                    for y in y_start..=y_end {
                        for x in x_start..=x_end {
                            let t = (x - x1) * dx + (y - y1) * dy;
                            let covered = if t <= 0 {
                                (x - x1) * (x - x1) + (y - y1) * (y - y1) <= r2
                            } else if t >= l {
                                (x - x2) * (x - x2) + (y - y2) * (y - y2) <= r2
                            } else {
                                let c = (x - x1) * dy - (y - y1) * dx;
                                c * c <= r2 * l
                            };

                            if covered {
                                count += 1;
                                let idx = (y as usize * width + x as usize) * 3;
                                canvas[idx] = composite(sr, sa, canvas[idx]);
                                canvas[idx + 1] = composite(sg, sa, canvas[idx + 1]);
                                canvas[idx + 2] = composite(sb, sa, canvas[idx + 2]);
                            }
                        }
                    }
                }
            }
            _ => {}
        }

        counts.push(count);
        type_names.push(shape_type);
    }

    // Print summary
    for (i, count) in counts.iter().enumerate() {
        println!("{} {} {}", i + 1, type_names[i], count);
    }

    // Count distinct colors
    let mut color_set: HashSet<(u8, u8, u8)> = HashSet::new();
    for i in 0..width * height {
        color_set.insert((canvas[i * 3], canvas[i * 3 + 1], canvas[i * 3 + 2]));
    }
    println!("colors {}", color_set.len());

    // Write PNG
    write_png("out.png", width, height, &canvas).unwrap();
}

use std::env;
use std::fs;
use std::io::Write;
use std::collections::HashSet;

enum JsonValue {
    Null,
    Num(i64),
    Str(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

struct JsonParser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> JsonParser<'a> {
    fn new(input: &'a str) -> Self {
        JsonParser { input: input.as_bytes(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn parse_value(&mut self) -> JsonValue {
        self.skip_ws();
        if self.pos >= self.input.len() {
            return JsonValue::Null;
        }
        match self.input[self.pos] {
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b'"' => JsonValue::Str(self.parse_string()),
            b't' => { self.pos += 4; JsonValue::Null }
            b'f' => { self.pos += 5; JsonValue::Null }
            b'n' => { self.pos += 4; JsonValue::Null }
            _ => self.parse_number(),
        }
    }

    fn parse_string(&mut self) -> String {
        self.pos += 1;
        let start = self.pos;
        while self.pos < self.input.len() && self.input[self.pos] != b'"' {
            if self.input[self.pos] == b'\\' {
                self.pos += 2;
            } else {
                self.pos += 1;
            }
        }
        let s = String::from_utf8_lossy(&self.input[start..self.pos]).to_string();
        self.pos += 1;
        s
    }

    fn parse_number(&mut self) -> JsonValue {
        let start = self.pos;
        if self.pos < self.input.len() && self.input[self.pos] == b'-' {
            self.pos += 1;
        }
        while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() {
            self.pos += 1;
        }
        if self.pos < self.input.len() && self.input[self.pos] == b'.' {
            self.pos += 1;
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() {
                self.pos += 1;
            }
        }
        if self.pos < self.input.len() && (self.input[self.pos] == b'e' || self.input[self.pos] == b'E') {
            self.pos += 1;
            if self.pos < self.input.len() && (self.input[self.pos] == b'+' || self.input[self.pos] == b'-') {
                self.pos += 1;
            }
            while self.pos < self.input.len() && self.input[self.pos].is_ascii_digit() {
                self.pos += 1;
            }
        }
        let s = std::str::from_utf8(&self.input[start..self.pos]).unwrap();
        JsonValue::Num(s.parse::<i64>().unwrap_or(0))
    }

    fn parse_array(&mut self) -> JsonValue {
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == b']' {
            self.pos += 1;
            return JsonValue::Array(items);
        }
        loop {
            items.push(self.parse_value());
            self.skip_ws();
            if self.pos < self.input.len() && self.input[self.pos] == b',' {
                self.pos += 1;
            } else {
                break;
            }
        }
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == b']' {
            self.pos += 1;
        }
        JsonValue::Array(items)
    }

    fn parse_object(&mut self) -> JsonValue {
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == b'}' {
            self.pos += 1;
            return JsonValue::Object(items);
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            if self.pos < self.input.len() && self.input[self.pos] == b':' {
                self.pos += 1;
            }
            let val = self.parse_value();
            items.push((key, val));
            self.skip_ws();
            if self.pos < self.input.len() && self.input[self.pos] == b',' {
                self.pos += 1;
            } else {
                break;
            }
        }
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == b'}' {
            self.pos += 1;
        }
        JsonValue::Object(items)
    }
}

fn get_obj<'a>(obj: &'a [(String, JsonValue)], key: &str) -> &'a JsonValue {
    for (k, v) in obj {
        if k == key {
            return v;
        }
    }
    &JsonValue::Null
}

fn get_int(obj: &[(String, JsonValue)], key: &str) -> i64 {
    match get_obj(obj, key) {
        JsonValue::Num(n) => *n,
        _ => 0,
    }
}

fn get_int_array(obj: &[(String, JsonValue)], key: &str) -> Vec<i64> {
    match get_obj(obj, key) {
        JsonValue::Array(arr) => arr.iter().map(|v| match v {
            JsonValue::Num(n) => *n,
            _ => 0,
        }).collect(),
        _ => vec![],
    }
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc = 0xFFFFFFFFu32;
    for &b in data {
        crc ^= b as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    crc ^ 0xFFFFFFFF
}

fn adler32(data: &[u8]) -> u32 {
    let mut a: u32 = 1;
    let mut b: u32 = 0;
    for &byte in data {
        a = (a + byte as u32) % 65521;
        b = (b + a) % 65521;
    }
    (b << 16) | a
}

fn write_chunk(file: &mut fs::File, chunk_type: &[u8; 4], data: &[u8]) -> std::io::Result<()> {
    file.write_all(&(data.len() as u32).to_be_bytes())?;
    file.write_all(chunk_type)?;
    file.write_all(data)?;
    let mut crc_input = Vec::with_capacity(4 + data.len());
    crc_input.extend_from_slice(chunk_type);
    crc_input.extend_from_slice(data);
    file.write_all(&crc32(&crc_input).to_be_bytes())?;
    Ok(())
}

