public class Main {

    static Map<String, MessageDef> messages = new LinkedHashMap<>();
    static Map<String, EnumDef> enums = new LinkedHashMap<>();
    static String rootType;

    static final Set<String> SCALAR_TYPES = new HashSet<>(Arrays.asList(
        "int32","int64","uint32","uint64","sint32","sint64",
        "bool","string","bytes","fixed32","fixed64","sfixed32","sfixed64"
    ));

    static class FieldDef {
        String name;
        int number;
        String type;
        boolean repeated;
        boolean optional;
        String oneof;
        String mapKeyType;
        String mapValueType;
    }

    static class MessageDef {
        String name;
        List<FieldDef> fields = new ArrayList<>();
        Map<Integer, FieldDef> byNum = new HashMap<>();
    }

    static class EnumDef {
        String name;
        Map<Integer, String> numToName = new LinkedHashMap<>();
    }

    static class Decoded {
        Map<Integer, Object> vals = new LinkedHashMap<>();
        Set<Integer> occurred = new HashSet<>();
        Map<String, Integer> oneofSet = new HashMap<>();
    }

    // Tokenizer
    enum TT { IDENT, NUM, STR, PUNCT, EOF }

    static class Token {
        TT type;
        String text;
        Token(TT t, String s) { type = t; text = s; }
    }

    static List<Token> tokens;
    static int tp; // token position

    static List<Token> tokenize(String input) {
        List<Token> result = new ArrayList<>();
        int i = 0, n = input.length();
        while (i < n) {
            char c = input.charAt(i);
            if (Character.isWhitespace(c)) { i++; continue; }
            if (c == '/' && i+1 < n && input.charAt(i+1) == '/') {
                i += 2;
                while (i < n && input.charAt(i) != '\n') i++;
                continue;
            }
            if (c == '/' && i+1 < n && input.charAt(i+1) == '*') {
                i += 2;
                while (i+1 < n && !(input.charAt(i) == '*' && input.charAt(i+1) == '/')) i++;
                i += 2;
                continue;
            }
            if (c == '"') {
                i++;
                StringBuilder sb = new StringBuilder();
                while (i < n && input.charAt(i) != '"') {
                    sb.append(input.charAt(i));
                    i++;
                }
                i++; // skip closing "
                result.add(new Token(TT.STR, sb.toString()));
                continue;
            }
            if (Character.isLetter(c) || c == '_') {
                int s = i;
                while (i < n && (Character.isLetterOrDigit(input.charAt(i)) || input.charAt(i) == '_')) i++;
                result.add(new Token(TT.IDENT, input.substring(s, i)));
                continue;
            }
            if (Character.isDigit(c)) {
                int s = i;
                while (i < n && Character.isDigit(input.charAt(i))) i++;
                result.add(new Token(TT.NUM, input.substring(s, i)));
                continue;
            }
            result.add(new Token(TT.PUNCT, String.valueOf(c)));
            i++;
        }
        result.add(new Token(TT.EOF, ""));
        return result;
    }

    static Token peek() { return tokens.get(tp); }
    static Token next() { return tokens.get(tp++); }
    static boolean match(TT t, String s) {
        if (peek().type == t && peek().text.equals(s)) { tp++; return true; }
        return false;
    }
    static void expect(TT t, String s) {
        if (!match(t, s)) throw new RuntimeException("Expected '" + s + "' got '" + peek().text + "'");
    }
    static int parseInt() {
        String s = next().text;
        return Integer.parseInt(s);
    }

    static void parseProto(String input) {
        tokens = tokenize(input);
        tp = 0;
        parseFile();
    }

    static void parseFile() {
        while (peek().type != TT.EOF) {
            if (peek().type == TT.IDENT) {
                String kw = peek().text;
                switch (kw) {
                    case "syntax":
                        next(); expect(TT.PUNCT, "="); next(); expect(TT.PUNCT, ";");
                        break;
                    case "package":
                        next();
                        while (peek().type == TT.IDENT) { next(); if (peek().text.equals(".")) next(); }
                        expect(TT.PUNCT, ";");
                        break;
                    case "option":
                        next();
                        skipToSemicolon();
                        break;
                    case "message":
                        next();
                        String mname = next().text;
                        parseMessage(mname);
                        break;
                    case "enum":
                        next();
                        String ename = next().text;
                        parseEnum(ename);
                        break;
                    case "reserved":
                        next();
                        skipToSemicolon();
                        break;
                    default:
                        next(); // skip unknown top-level
                        break;
                }
            } else {
                next();
            }
        }
    }

    static void skipToSemicolon() {
        while (peek().type != TT.EOF && !(peek().type == TT.PUNCT && peek().text.equals(";"))) next();
        next(); // consume ;
    }

    static void parseMessage(String name) {
        MessageDef md = new MessageDef();
        md.name = name;
        messages.put(name, md);
        if (rootType == null) rootType = name; // first top-level message

        expect(TT.PUNCT, "{");
        while (peek().type != TT.EOF && !(peek().type == TT.PUNCT && peek().text.equals("}"))) {
            if (peek().type == TT.IDENT) {
                String kw = peek().text;
                switch (kw) {
                    case "message":
                        next();
                        String nested = next().text;
                        parseMessage(nested);
                        break;
                    case "enum":
                        next();
                        String en = next().text;
                        parseEnum(en);
                        break;
                    case "oneof":
                        next();
                        String oname = next().text;
                        md.oneofNames.add(oname); // hmm, I removed this field
                        parseOneof(md, oname);
                        break;
                    case "reserved":
                        next();
                        skipToSemicolon();
                        break;
                    case "option":
                        next();
                        skipToSemicolon();
                        break;
                    case "extensions":
                        next();
                        skipToSemicolon();
                        break;
                    default:
                        // field declaration
                        parseField(md, null);
                        break;
                }
            } else {
                next(); // skip unexpected
            }
        }
        expect(TT.PUNCT, "}");
    }

    static void parseOneof(MessageDef md, String oneofName) {
        expect(TT.PUNCT, "{");
        while (peek().type != TT.EOF && !(peek().type == TT.PUNCT && peek().text.equals("}"))) {
            if (peek().type == TT.IDENT) {
                String kw = peek().text;
                if (kw.equals("option")) {
                    next();
                    skipToSemicolon();
                } else if (kw.equals("reserved")) {
                    next();
                    skipToSemicolon();
                } else {
                    // field without label
                    parseField(md, oneofName);
                }
            } else {
                next();
            }
        }
        expect(TT.PUNCT, "}");
    }

    static void parseField(MessageDef md, String oneofName) {
        FieldDef fd = new FieldDef();
        fd.oneof = oneofName;

        // Check for label
        if (peek().type == TT.IDENT && peek().text.equals("repeated")) {
            fd.repeated = true;
            next();
        } else if (peek().type == TT.IDENT && peek().text.equals("optional")) {
            fd.optional = true;
            next();
        }

        // Check for map type
        if (peek().type == TT.IDENT && peek().text.equals("map")) {
            next(); // map
            expect(TT.PUNCT, "<");
            fd.mapKeyType = next().text;
            expect(TT.PUNCT, ",");
            fd.mapValueType = next().text;
            expect(TT.PUNCT, ">");
            fd.type = "map";
        } else {
            fd.type = next().text;
        }

        fd.name = next().text;
        expect(TT.PUNCT, "=");
        fd.number = parseInt();

        // Optional field options [...]
        if (peek().type == TT.PUNCT && peek().text.equals("[")) {
            skipFieldOptions();
        }

        expect(TT.PUNCT, ";");

        md.fields.add(fd);
        md.byNum.put(fd.number, fd);
    }

    static void skipFieldOptions() {
        // Skip [...] - just skip to matching ]
        expect(TT.PUNCT, "[");
        int depth = 1;
        while (depth > 0 && peek().type != TT.EOF) {
            if (peek().type == TT.PUNCT && peek().text.equals("[")) depth++;
            else if (peek().type == TT.PUNCT && peek().text.equals("]")) depth--;
            if (depth > 0) next();
        }
        if (peek().type == TT.PUNCT && peek().text.equals("]")) next();
    }

    static void parseEnum(String name) {
        EnumDef ed = new EnumDef();
        ed.name = name;
        enums.put(name, ed);

        expect(TT.PUNCT, "{");
        while (peek().type != TT.EOF && !(peek().type == TT.PUNCT && peek().text.equals("}"))) {
            if (peek().type == TT.IDENT) {
                String kw = peek().text;
                if (kw.equals("option")) {
                    next();
                    skipToSemicolon();
                } else if (kw.equals("reserved")) {
                    next();
                    skipToSemicolon();
                } else {
                    // enum value: NAME = NUMBER [options];
                    String vname = next().text;
                    expect(TT.PUNCT, "=");
                    int vnum = parseEnumValue();
                    ed.numToName.put(vnum, vname);
                    // optional options
                    if (peek().type == TT.PUNCT && peek().text.equals("[")) {
                        skipFieldOptions();
                    }
                    expect(TT.PUNCT, ";");
                }
            } else if (peek().type == TT.PUNCT && peek().text.equals("-")) {
                // negative enum value? Actually the parser should handle this in parseEnumValue
                // Wait, if the value is negative, the token would be "-" then NUM
                // But I tokenize "-" as PUNCT. Let me handle this in parseEnumValue.
                // Actually, let me handle it differently. The enum value line starts with an identifier (the name).
                // So we shouldn't see "-" at the start of a statement inside an enum.
                // Unless... hmm, no. The format is NAME = -NUMBER;
                // The "-" appears after "=", which is handled in parseEnumValue.
                next(); // shouldn't happen, skip
            } else {
                next();
            }
        }
        expect(TT.PUNCT, "}");
    }

    static int parseEnumValue() {
        boolean neg = false;
        if (peek().type == TT.PUNCT && peek().text.equals("-")) {
            neg = true;
            next();
        }
        int val = Integer.parseInt(next().text);
        return neg ? -val : val;
    }

    // Binary decoding
    static long readVarint(byte[] data, int[] pos) {
        long result = 0;
        int shift = 0;
        while (true) {
            byte b = data[pos[0]++];
            result |= ((long)(b & 0x7F)) << shift;
            if ((b & 0x80) == 0) break;
            shift += 7;
        }
        return result;
    }

    static Decoded decodeMessage(byte[] data, String msgName) {
        Decoded dec = new Decoded();
        MessageDef md = messages.get(msgName);
        int[] pos = {0};

        while (pos[0] < data.length) {
            long key = readVarint(data, pos);
            int fieldNum = (int)(key >>> 3);
            int wireType = (int)(key & 7);

            FieldDef fd = md != null ? md.byNum.get(fieldNum) : null;

            if (fd == null) {
                // Unknown field - skip
                skipValue(data, pos, wireType, fieldNum);
                continue;
            }

            // Known field - decode
            decodeKnownField(data, pos, wireType, fd, dec);
        }

        return dec;
    }

    static void skipValue(byte[] data, int[] pos, int wireType, int fieldNum) {
        switch (wireType) {
            case 0: readVarint(data, pos); break;
            case 1: pos[0] += 8; break;
            case 2: {
                int len = (int)readVarint(data, pos);
                pos[0] += len;
                break;
            }
            case 5: pos[0] += 4; break;
            case 3: {
                // start group - skip until matching end group
                skipGroup(data, pos, fieldNum);
                break;
            }
            case 4:
                // end group - shouldn't happen here
                break;
            default:
                break;
        }
    }

    static void skipGroup(byte[] data, int[] pos, int groupFieldNum) {
        while (pos[0] < data.length) {
            long key = readVarint(data, pos);
            int fn = (int)(key >>> 3);
            int wt = (int)(key & 7);
            if (wt == 4 && fn == groupFieldNum) {
                return; // end of group
            }
            skipValue(data, pos, wt, fn);
        }
    }

    static void decodeKnownField(byte[] data, int[] pos, int wireType, FieldDef fd, Decoded dec) {
        // Handle oneof: if setting a different member, clear old
        if (fd.oneof != null) {
            Integer currentSet = dec.oneofSet.get(fd.oneof);
            if (currentSet != null && currentSet != fd.number) {
                // Clear old member
                dec.vals.remove(currentSet);
                dec.occurred.remove(currentSet);
            }
            dec.oneofSet.put(fd.oneof, fd.number);
        }

        if (fd.type.equals("map")) {
            // Map field: wire type 2, each occurrence is an entry
            int len = (int)readVarint(data, pos);
            byte[] entryBytes = Arrays.copyOfRange(data, pos[0], pos[0] + len);
            pos[0] += len;
            decodeMapEntry(entryBytes, fd, dec);
            dec.occurred.add(fd.number);
            return;
        }

        if (fd.repeated) {
            // Repeated field
            if (wireType == 2 && isPackedType(fd.type)) {
                // Packed encoding
                int len = (int)readVarint(data, pos);
                byte[] payload = Arrays.copyOfRange(data, pos[0], pos[0] + len);
                pos[0] += len;
                decodePacked(payload, fd, dec);
            } else {
                // Unpacked: single element
                Object val = decodeScalar(data, pos, wireType, fd.type);
                appendRepeated(dec, fd.number, val);
            }
            dec.occurred.add(fd.number);
            return;
        }

        // Singular field
        if (isMessageType(fd.type)) {
            // Message field
            int len = (int)readVarint(data, pos);
            byte[] subBytes = Arrays.copyOfRange(data, pos[0], pos[0] + len);
            pos[0] += len;
            Decoded sub = decodeMessage(subBytes, fd.type);
            if (dec.occurred.contains(fd.number)) {
                // Merge
                mergeMessages(dec.vals.get(fd.number), sub);
            } else {
                dec.vals.put(fd.number, sub);
            }
            dec.occurred.add(fd.number);
        } else {
            // Scalar field (including enum, bool)
            Object val = decodeScalar(data, pos, wireType, fd.type);
            dec.vals.put(fd.number, val);
            dec.occurred.add(fd.number);
        }
    }

    static boolean isPackedType(String type) {
        return SCALAR_TYPES.contains(type) && !type.equals("string") && !type.equals("bytes");
    }

    static boolean isMessageType(String type) {
        return messages.containsKey(type);
    }

    static boolean isEnumType(String type) {
        return enums.containsKey(type);
    }

    static Object decodeScalar(byte[] data, int[] pos, int wireType, String type) {
        switch (type) {
            case "int32": {
                long v = readVarint(data, pos);
                return (int)v; // low 32 bits as signed
            }
            case "int64": {
                long v = readVarint(data, pos);
                return v;
            }
            case "uint32": {
                long v = readVarint(data, pos);
                return v & 0xFFFFFFFFL;
            }
            case "uint64": {
                return readVarint(data, pos);
            }
            case "sint32": {
                long v = readVarint(data, pos);
                return (int)zigzag32(v);
            }
            case "sint64": {
                long v = readVarint(data, pos);
                return zigzag64(v);
            }
            case "bool": {
                long v = readVarint(data, pos);
                return v != 0;
            }
            case "string": {
                int len = (int)readVarint(data, pos);
                String s = new String(data, pos[0], len, "UTF-8");
                pos[0] += len;
                return s;
            }
            case "bytes": {
                int len = (int)readVarint(data, pos);
                byte[] b = Arrays.copyOfRange(data, pos[0], pos[0] + len);
                pos[0] += len;
                return b;
            }
            case "fixed32": {
                int v = (data[pos[0]] & 0xFF) | ((data[pos[0]+1] & 0xFF) << 8) | ((data[pos[0]+2] & 0xFF) << 16) | ((data[pos[0]+3] & 0xFF) << 24);
                pos[0] += 4;
                return v & 0xFFFFFFFFL;
            }
            case "sfixed32": {
                int v = (data[pos[0]] & 0xFF) | ((data[pos[0]+1] & 0xFF) << 8) | ((data[pos[0]+2] & 0xFF) << 16) | ((data[pos[0]+3] & 0xFF) << 24);
                pos[0] += 4;
                return (long)v; // sign-extended
            }
            case "fixed64": {
                long v = 0;
                for (int i = 0; i < 8; i++) v |= ((long)(data[pos[0]+i] & 0xFF)) << (i*8);
                pos[0] += 8;
                return v;
            }
            case "sfixed64": {
                long v = 0;
                for (int i = 0; i < 8; i++) v |= ((long)(data[pos[0]+i] & 0xFF)) << (i*8);
                pos[0] += 8;
                return v;
            }
            default: {
                // Must be enum type
                long v = readVarint(data, pos);
                return (int)v; // low 32 bits as signed
            }
        }
    }

    static long zigzag32(long n) {
        return ((n >>> 1) ^ -(n & 1)) & 0xFFFFFFFFL; // Hmm, actually for sint32 we want the result as int
    }

    static long zigzag64(long n) {
        return (n >>> 1) ^ -(n & 1);
    }

    // Hmm wait, zigzag32 should return an int value stored as long. Let me reconsider.
    // sint32 decoded: (int)((n >>> 1) ^ -(n & 1))
    // The result is a 32-bit signed value. I'll store it as a long (sign-extended).

    static void decodePacked(byte[] payload, FieldDef fd, Decoded dec) {
        int[] pos = {0};
        while (pos[0] < payload.length) {
            Object val = decodeScalarFromBytes(payload, pos, fd.type);
            appendRepeated(dec, fd.number, val);
        }
    }

    static Object decodeScalarFromBytes(byte[] data, int[] pos, String type) {
        // Same as decodeScalar but without wireType (packed elements use their natural encoding)
        switch (type) {
            case "int32": {
                long v = readVarint(data, pos);
                return (int)v;
            }
            case "int64": {
                return readVarint(data, pos);
            }
            case "uint32": {
                long v = readVarint(data, pos);
                return v & 0xFFFFFFFFL;
            }
            case "uint64": {
                return readVarint(data, pos);
            }
            case "sint32": {
                long v = readVarint(data, pos);
                return (int)((v >>> 1) ^ -(v & 1));
            }
            case "sint64": {
                long v = readVarint(data, pos);
                return (v >>> 1) ^ -(v & 1);
            }
            case "bool": {
                long v = readVarint(data, pos);
                return v != 0;
            }
            case "fixed32": {
                int v = (data[pos[0]] & 0xFF) | ((data[pos[0]+1] & 0xFF) << 8) | ((data[pos[0]+2] & 0xFF) << 16) | ((data[pos[0]+3] & 0xFF) << 24);
                pos[0] += 4;
                return v & 0xFFFFFFFFL;
            }
            case "sfixed32": {
                int v = (data[pos[0]] & 0xFF) | ((data[pos[0]+1] & 0xFF) << 8) | ((data[pos[0]+2] & 0xFF) << 16) | ((data[pos[0]+3] & 0xFF) << 24);
                pos[0] += 4;
                return (long)v;
            }
            case "fixed64": {
                long v = 0;
                for (int i = 0; i < 8; i++) v |= ((long)(data[pos[0]+i] & 0xFF)) << (i*8);
                pos[0] += 8;
                return v;
            }
            case "sfixed64": {
                long v = 0;
                for (int i = 0; i < 8; i++) v |= ((long)(data[pos[0]+i] & 0xFF)) << (i*8);
                pos[0] += 8;
                return v;
            }
            default: {
                // enum
                long v = readVarint(data, pos);
                return (int)v;
            }
        }
    }

    @SuppressWarnings("unchecked")
    static void appendRepeated(Decoded dec, int fieldNum, Object val) {
        List<Object> list = (List<Object>) dec.vals.get(fieldNum);
        if (list == null) {
            list = new ArrayList<>();
            dec.vals.put(fieldNum, list);
        }
        list.add(val);
    }

    @SuppressWarnings("unchecked")
    static void decodeMapEntry(byte[] entryBytes, FieldDef fd, Decoded dec) {
        int[] pos = {0};
        Object key = null;
        Object val = null;

        while (pos[0] < entryBytes.length) {
            long key = readVarint(entryBytes, pos);
            int fn = (int)(key >>> 3);
            int wt = (int)(key & 7);

            if (fn == 1) {
                // map key
                key = decodeScalar(entryBytes, pos, wt, fd.mapKeyType);
            } else if (fn == 2) {
                // map value
                if (isMessageType(fd.mapValueType)) {
                    int len = (int)readVarint(entryBytes, pos);
                    byte[] sub = Arrays.copyOfRange(entryBytes, pos[0], pos[0] + len);
                    pos[0] += len;
                    val = decodeMessage(sub, fd.mapValueType);
                } else {
                    val = decodeScalar(entryBytes, pos, wt, fd.mapValueType);
                }
            } else {
                skipValue(entryBytes, pos, wt, fn);
            }
        }

        // Default key/value if missing
        if (key == null) {
            if (fd.mapKeyType.equals("string")) key = "";
            else key = 0; // int32
        }
        if (val == null) {
            val = getDefault(fd.mapValueType);
        }

        // Store in map
        LinkedHashMap<Object, Object> map = (LinkedHashMap<Object, Object>) dec.vals.get(fd.number);
        if (map == null) {
            map = new LinkedHashMap<>();
            dec.vals.put(fd.number, map);
        }
        map.put(key, val);
    }

    static Object getDefault(String type) {
        switch (type) {
            case "string": return "";
            case "bytes": return new byte[0];
            case "bool": return false;
            case "int64": case "uint64": case "sint64": case "fixed64": case "sfixed64": return 0L;
            case "int32": case "uint32": case "sint32": case "fixed32": case "sfixed32": return 0;
            default:
                // enum or message
                if (isMessageType(type)) return new Decoded();
                return 0; // enum default is 0
        }
    }

    @SuppressWarnings("unchecked")
    static void mergeMessages(Object oldVal, Decoded newVal) {
        if (!(oldVal instanceof Decoded)) return;
        Decoded old = (Decoded) oldVal;

        for (Integer fn : newVal.occurred) {
            old.occurred.add(fn);
            Object nv = newVal.vals.get(fn);
            Object ov = old.vals.get(fn);

            if (nv instanceof List) {
                // repeated field: append
                if (ov instanceof List) {
                    ((List<Object>)ov).addAll((List<Object>)nv);
                } else {
                    old.vals.put(fn, nv);
                }
            } else if (nv instanceof LinkedHashMap) {
                // map field: update
                if (ov instanceof LinkedHashMap) {
                    ((LinkedHashMap<Object,Object>)ov).putAll((Map<Object,Object>)nv);
                } else {
                    old.vals.put(fn, nv);
                }
            } else if (nv instanceof Decoded) {
                // message field: merge recursively
                if (ov instanceof Decoded) {
                    mergeMessages(ov, (Decoded)nv);
                } else {
                    old.vals.put(fn, nv);
                }
            } else {
                // scalar: replace
                old.vals.put(fn, nv);
            }
        }

        // Merge oneof sets
        old.oneofSet.putAll(newVal.oneofSet);
    }

    // JSON output
    static String toJson(Decoded dec, String msgName) {
        MessageDef md = messages.get(msgName);
        StringBuilder sb = new StringBuilder("{");

        // Sort fields by number
        List<FieldDef> sorted = new ArrayList<>(md.fields);
        sorted.sort((a, b) -> a.number - b.number);

        boolean first = true;
        for (FieldDef fd : sorted) {
            if (!shouldPrint(dec, fd)) continue;
            if (!first) sb.append(",");
            first = false;
            sb.append("\"").append(escapeJson(camelCase(fd.name))).append("\":");
            sb.append(encodeValue(dec.vals.get(fd.number), fd));
        }

        sb.append("}");
        return sb.toString();
    }

    static boolean shouldPrint(Decoded dec, FieldDef fd) {
        if (fd.repeated) {
            Object val = dec.vals.get(fd.number);
            return val != null && ((List<?>)val).size() > 0;
        }
        if (fd.type.equals("map")) {
            Object val = dec.vals.get(fd.number);
            return val != null && ((Map<?,?>)val).size() > 0;
        }
        // Singular
        if (!dec.occurred.contains(fd.number)) return false;
        if (fd.optional) return true;
        if (fd.oneof != null) {
            Integer set = dec.oneofSet.get(fd.oneof);
            return set != null && set == fd.number;
        }
        // Regular singular scalar: print if non-default
        if (isMessageType(fd.type)) return true; // message always prints if occurred
        // Scalar or enum: print if non-default
        Object val = dec.vals.get(fd.number);
        return isNonDefault(val, fd.type);
    }

    static boolean isNonDefault(Object val, String type) {
        if (val == null) return false;
        if (type.equals("bool")) return (Boolean)val;
        if (type.equals("string")) return !((String)val).isEmpty();
        if (type.equals("bytes")) return ((byte[])val).length > 0;
        // Numeric or enum
        long num;
        if (val instanceof Integer) num = (Integer)val;
        else num = (Long)val;
        return num != 0;
    }

    @SuppressWarnings("unchecked")
    static String encodeValue(Object val, FieldDef fd) {
        if (fd.repeated) {
            List<Object> list = (List<Object>) val;
            StringBuilder sb = new StringBuilder("[");
            for (int i = 0; i < list.size(); i++) {
                if (i > 0) sb.append(",");
                sb.append(encodeSingle(list.get(i), fd.type));
            }
            sb.append("]");
            return sb.toString();
        }
        if (fd.type.equals("map")) {
            LinkedHashMap<Object, Object> map = (LinkedHashMap<Object, Object>) val;
            // Sort keys
            List<Object> keys = new ArrayList<>(map.keySet());
            if (fd.mapKeyType.equals("string")) {
                keys.sort((a, b) -> ((String)a).compareTo((String)b));
            } else {
                // int32
                keys.sort((a, b) -> Integer.compare((Integer)a, (Integer)b));
            }
            StringBuilder sb = new StringBuilder("{");
            boolean first = true;
            for (Object key : keys) {
                if (!first) sb.append(",");
                first = false;
                String keyStr;
                if (fd.mapKeyType.equals("string")) {
                    keyStr = escapeJson((String)key);
                } else {
                    keyStr = String.valueOf((Integer)key);
                }
                sb.append("\"").append(keyStr).append("\":");
                sb.append(encodeSingle(map.get(key), fd.mapValueType));
            }
            sb.append("}");
            return sb.toString();
        }
        return encodeSingle(val, fd.type);
    }

    static String encodeSingle(Object val, String type) {
        if (val == null) return "null"; // shouldn't happen

        switch (type) {
            case "int32": case "uint32": case "sint32": case "fixed32": case "sfixed32":
                return String.valueOf(((Number)val).longValue());
            case "int64": case "uint64": case "sint64": case "fixed64": case "sfixed64":
                if (type.equals("uint64")) {
                    return "\"" + Long.toUnsignedString((Long)val) + "\"";
                }
                return "\"" + val + "\"";
            case "bool":
                return (Boolean)val ? "true" : "false";
            case "string":
                return "\"" + escapeJson((String)val) + "\"";
            case "bytes":
                return "\"" + Base64.getEncoder().encodeToString((byte[])val) + "\"";
            default:
                // message or enum
                if (isMessageType(type)) {
                    return toJson((Decoded)val, type);
                }
                // enum
                EnumDef ed = enums.get(type);
                int num;
                if (val instanceof Integer) num = (Integer)val;
                else num = ((Long)val).intValue();
                String name = ed.numToName.get(num);
                if (name != null) return "\"" + name + "\"";
                return String.valueOf(num);
        }
    }

    static String camelCase(String name) {
        StringBuilder sb = new StringBuilder();
        boolean upper = false;
        for (int i = 0; i < name.length(); i++) {
            char c = name.charAt(i);
            if (c == '_') {
                upper = true;
            } else {
                if (upper && c >= 'a' && c <= 'z') {
                    sb.append((char)(c - 32));
                } else {
                    sb.append(c);
                }
                upper = false;
            }
        }
        return sb.toString();
    }

    static String escapeJson(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\b': sb.append("\\b"); break;
                case '\t': sb.append("\\t"); break;
                case '\n': sb.append("\\n"); break;
                case '\f': sb.append("\\f"); break;
                case '\r': sb.append("\\r"); break;
                default:
                    if (c < 0x20) {
                        sb.append(String.format("\\u%04x", (int)c));
                    } else {
                        sb.append(c);
                    }
            }
        }
        return sb.toString();
    }
}

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.nio.charset.StandardCharsets;

public class Main {

    static Map<String, MessageDef> messages = new LinkedHashMap<>();
    static Map<String, EnumDef> enums = new LinkedHashMap<>();
    static String rootType;

    static final Set<String> SCALAR_TYPES = new HashSet<>(Arrays.asList(
        "int32","int64","uint32","uint64","sint32","sint64",
        "bool","string","bytes","fixed32","fixed64","sfixed32","sfixed64"
    ));

    static class FieldDef {
        String name;
        int number;
        String type;
        boolean repeated;
        boolean optional;
        String oneof;
        String mapKeyType;
        String mapValueType;
    }

    static class MessageDef {
        String name;
        List<FieldDef> fields = new ArrayList<>();
        Map<Integer, FieldDef> byNum = new HashMap<>();
    }

    static class EnumDef {
        String name;
        Map<Integer, String> numToName = new LinkedHashMap<>();
    }

    static class Decoded {
        String msgName;
        Map<Integer, Object> vals = new LinkedHashMap<>();
        Set<Integer> occurred = new HashSet<>();
        Map<String, Integer> oneofSet = new HashMap<>();
    }

    // Tokenizer
    enum TT { IDENT, NUM, STR, PUNCT, EOF }

    static class Token {
        TT type;
        String text;
        Token(TT t, String s) { type = t; text = s; }
    }

    static List<Token> tokens;
    static int tp;

    static List<Token> tokenize(String input) {
        List<Token> result = new ArrayList<>();
        int i = 0, n = input.length();
        while (i < n) {
            char c = input.charAt(i);
            if (Character.isWhitespace(c)) { i++; continue; }
            if (c == '/' && i+1 < n && input.charAt(i+1) == '/') {
                i += 2;
                while (i < n && input.charAt(i) != '\n') i++;
                continue;
            }
            if (c == '/' && i+1 < n && input.charAt(i+1) == '*') {
                i += 2;
                while (i+1 < n && !(input.charAt(i) == '*' && input.charAt(i+1) == '/')) i++;
                i += 2;
                continue;
            }
            if (c == '"') {
                i++;
                StringBuilder sb = new StringBuilder();
                while (i < n && input.charAt(i) != '"') {
                    sb.append(input.charAt(i));
                    i++;
                }
                i++;
                result.add(new Token(TT.STR, sb.toString()));
                continue;
            }
            if (Character.isLetter(c) || c == '_') {
                int s = i;
                while (i < n && (Character.isLetterOrDigit(input.charAt(i)) || input.charAt(i) == '_')) i++;
                result.add(new Token(TT.IDENT, input.substring(s, i)));
                continue;
            }
            if (Character.isDigit(c)) {
                int s = i;
                while (i < n && Character.isDigit(input.charAt(i))) i++;
                result.add(new Token(TT.NUM, input.substring(s, i)));
                continue;
            }
            result.add(new Token(TT.PUNCT, String.valueOf(c)));
            i++;
        }
        result.add(new Token(TT.EOF, ""));
        return result;
    }

    static Token peek() { return tokens.get(tp); }
    static Token next() { return tokens.get(tp++); }
    static boolean match(TT t, String s) {
        if (peek().type == t && peek().text.equals(s)) { tp++; return true; }
        return false;
    }
    static void expect(TT t, String s) {
        if (!match(t, s)) throw new RuntimeException("Expected '" + s + "' got '" + peek().text + "'");
    }
    static int parseInt() {
        return Integer.parseInt(next().text);
    }

    static void parseProto(String input) {
        tokens = tokenize(input);
        tp = 0;
        parseFile();
    }

    static void parseFile() {
        while (peek().type != TT.EOF) {
            if (peek().type == TT.IDENT) {
                String kw = peek().text;
                switch (kw) {
                    case "syntax":
                        next(); expect(TT.PUNCT, "="); next(); expect(TT.PUNCT, ";");
                        break;
                    case "package":
                        next();
                        while (peek().type == TT.IDENT) { next(); if (peek().text.equals(".")) next(); }
                        expect(TT.PUNCT, ";");
                        break;
                    case "option":
                        next();
                        skipToSemicolon();
                        break;
                    case "message":
                        next();
                        String mname = next().text;
                        parseMessage(mname);
                        break;
                    case "enum":
                        next();
                        String ename = next().text;
                        parseEnum(ename);
                        break;
                    case "reserved":
                        next();
                        skipToSemicolon();
                        break;
                    case "extensions":
                        next();
                        skipToSemicolon();
                        break;
                    default:
                        next();
                        break;
                }
            } else {
                next();
            }
        }
    }

    static void skipToSemicolon() {
        while (peek().type != TT.EOF && !(peek().type == TT.PUNCT && peek().text.equals(";"))) next();
        if (peek().type == TT.PUNCT && peek().text.equals(";")) next();
    }

    static void parseMessage(String name) {
        MessageDef md = new MessageDef();
        md.name = name;
        messages.put(name, md);
        if (rootType == null) rootType = name;

        expect(TT.PUNCT, "{");
        while (peek().type != TT.EOF && !(peek().type == TT.PUNCT && peek().text.equals("}"))) {
            if (peek().type == TT.IDENT) {
                String kw = peek().text;
                switch (kw) {
                    case "message":
                        next();
                        String nested = next().text;
                        parseMessage(nested);
                        break;
                    case "enum":
                        next();
                        String en = next().text;
                        parseEnum(en);
                        break;
                    case "oneof":
                        next();
                        String oname = next().text;
                        parseOneof(md, oname);
                        break;
                    case "reserved":
                        next();
                        skipToSemicolon();
                        break;
                    case "option":
                        next();
                        skipToSemicolon();
                        break;
                    case "extensions":
                        next();
                        skipToSemicolon();
                        break;
                    default:
                        parseField(md, null);
                        break;
                }
            } else {
                next();
            }
        }
        expect(TT.PUNCT, "}");
    }

    static void parseOneof(MessageDef md, String oneofName) {
        expect(TT.PUNCT, "{");
        while (peek().type != TT.EOF && !(peek().type == TT.PUNCT && peek().text.equals("}"))) {
            if (peek().type == TT.IDENT) {
                String kw = peek().text;
                if (kw.equals("option")) {
                    next();
                    skipToSemicolon();
                } else if (kw.equals("reserved")) {
                    next();
                    skipToSemicolon();
                } else {
                    parseField(md, oneofName);
                }
            } else {
                next();
            }
        }
        expect(TT.PUNCT, "}");
    }

    static void parseField(MessageDef md, String oneofName) {
        FieldDef fd = new FieldDef();
        fd.oneof = oneofName;

        if (peek().type == TT.IDENT && peek().text.equals("repeated")) {
            fd.repeated = true;
            next();
        } else if (peek().type == TT.IDENT && peek().text.equals("optional")) {
            fd.optional = true;
            next();
        }

        if (peek().type == TT.IDENT && peek().text.equals("map")) {
            next();
            expect(TT.PUNCT, "<");
            fd.mapKeyType = next().text;
            expect(TT.PUNCT, ",");
            fd.mapValueType = next().text;
            expect(TT.PUNCT, ">");
            fd.type = "map";
        } else {
            fd.type = next().text;
        }

        fd.name = next().text;
        expect(TT.PUNCT, "=");
        fd.number = parseInt();

        if (peek().type == TT.PUNCT && peek().text.equals("[")) {
            skipFieldOptions();
        }

        expect(TT.PUNCT, ";");

        md.fields.add(fd);
        md.byNum.put(fd.number, fd);
    }

    static void skipFieldOptions() {
        expect(TT.PUNCT, "[");
        int depth = 1;
        while (depth > 0 && peek().type != TT.EOF) {
            if (peek().type == TT.PUNCT && peek().text.equals("[")) depth++;
            else if (peek().type == TT.PUNCT && peek().text.equals("]")) depth--;
            if (depth > 0) next();
        }
        if (peek().type == TT.PUNCT && peek().text.equals("]")) next();
    }

    static void parseEnum(String name) {
        EnumDef ed = new EnumDef();
        ed.name = name;
        enums.put(name, ed);

        expect(TT.PUNCT, "{");
        while (peek().type != TT.EOF && !(peek().type == TT.PUNCT && peek().text.equals("}"))) {
            if (peek().type == TT.IDENT) {
                String kw = peek().text;
                if (kw.equals("option")) {
                    next();
                    skipToSemicolon();
                } else if (kw.equals("reserved")) {
                    next();
                    skipToSemicolon();
                } else {
                    String vname = next().text;
                    expect(TT.PUNCT, "=");
                    int vnum = parseEnumValue();
                    ed.numToName.put(vnum, vname);
                    if (peek().type == TT.PUNCT && peek().text.equals("[")) {
                        skipFieldOptions();
                    }
                    expect(TT.PUNCT, ";");
                }
            } else {
                next();
            }
        }
        expect(TT.PUNCT, "}");
    }

    static int parseEnumValue() {
        boolean neg = false;
        if (peek().type == TT.PUNCT && peek().text.equals("-")) {
            neg = true;
            next();
        }
        int val = Integer.parseInt(next().text);
        return neg ? -val : val;
    }

    // Binary decoding
    static long readVarint(byte[] data, int[] pos) {
        long result = 0;
        int shift = 0;
        while (true) {
            byte b = data[pos[0]++];
            result |= ((long)(b & 0x7F)) << shift;
            if ((b & 0x80) == 0) break;
            shift += 7;
        }
        return result;
    }

    static Decoded decodeMessage(byte[] data, String msgName) {
        Decoded dec = new Decoded();
        dec.msgName = msgName;
        MessageDef md = messages.get(msgName);
        int[] pos = {0};

        while (pos[0] < data.length) {
            long key = readVarint(data, pos);
            int fieldNum = (int)(key >>> 3);
            int wireType = (int)(key & 7);

            FieldDef fd = md != null ? md.byNum.get(fieldNum) : null;

            if (fd == null) {
                skipValue(data, pos, wireType, fieldNum);
                continue;
            }

            decodeKnownField(data, pos, wireType, fd, dec);
        }

        return dec;
    }

    static void skipValue(byte[] data, int[] pos, int wireType, int fieldNum) {
        switch (wireType) {
            case 0: readVarint(data, pos); break;
            case 1: pos[0] += 8; break;
            case 2: {
                int len = (int)readVarint(data, pos);
                pos[0] += len;
                break;
            }
            case 5: pos[0] += 4; break;
            case 3:
                skipGroup(data, pos, fieldNum);
                break;
            case 4:
                break;
            default:
                break;
        }
    }

    static void skipGroup(byte[] data, int[] pos, int groupFieldNum) {
        while (pos[0] < data.length) {
            long key = readVarint(data, pos);
            int fn = (int)(key >>> 3);
            int wt = (int)(key & 7);
            if (wt == 4 && fn == groupFieldNum) {
                return;
            }
            skipValue(data, pos, wt, fn);
        }
    }

    static void decodeKnownField(byte[] data, int[] pos, int wireType, FieldDef fd, Decoded dec) {
        if (fd.oneof != null) {
            Integer currentSet = dec.oneofSet.get(fd.oneof);
            if (currentSet != null && currentSet != fd.number) {
                dec.vals.remove(currentSet);
                dec.occurred.remove(currentSet);
            }
            dec.oneofSet.put(fd.oneof, fd.number);
        }

        if (fd.type.equals("map")) {
            int len = (int)readVarint(data, pos);
            byte[] entryBytes = Arrays.copyOfRange(data, pos[0], pos[0] + len);
            pos[0] += len;
            decodeMapEntry(entryBytes, fd, dec);
            dec.occurred.add(fd.number);
            return;
        }

        if (fd.repeated) {
            if (wireType == 2 && isPackedType(fd.type)) {
                int len = (int)readVarint(data, pos);
                byte[] payload = Arrays.copyOfRange(data, pos[0], pos[0] + len);
                pos[0] += len;
                decodePacked(payload, fd, dec);
            } else {
                Object val = decodeScalar(data, pos, wireType, fd.type);
                appendRepeated(dec, fd.number, val);
            }
            dec.occurred.add(fd.number);
            return;
        }

        // Singular field
        if (isMessageType(fd.type)) {
            int len = (int)readVarint(data, pos);
            byte[] subBytes = Arrays.copyOfRange(data, pos[0], pos[0] + len);
            pos[0] += len;
            Decoded sub = decodeMessage(subBytes, fd.type);
            if (dec.occurred.contains(fd.number)) {
                mergeMessages(dec.vals.get(fd.number), sub);
            } else {
                dec.vals.put(fd.number, sub);
            }
            dec.occurred.add(fd.number);
        } else {
            Object val = decodeScalar(data, pos, wireType, fd.type);
            dec.vals.put(fd.number, val);
            dec.occurred.add(fd.number);
        }
    }

    static boolean isPackedType(String type) {
        return SCALAR_TYPES.contains(type) && !type.equals("string") && !type.equals("bytes");
    }

    static boolean isMessageType(String type) {
        return messages.containsKey(type);
    }

    static boolean isEnumType(String type) {
        return enums.containsKey(type);
    }

    static Object decodeScalar(byte[] data, int[] pos, int wireType, String type) {
        switch (type) {
            case "int32": {
                long v = readVarint(data, pos);
                return (int)v;
            }
            case "int64": {
                return readVarint(data, pos);
            }
            case "uint32": {
                long v = readVarint(data, pos);
                return v & 0xFFFFFFFFL;
            }
            case "uint64": {
                return readVarint(data, pos);
            }
            case "sint32": {
                long v = readVarint(data, pos);
                return (int)((v >>> 1) ^ -(v & 1));
            }
            case "sint64": {
                long v = readVarint(data, pos);
                return (v >>> 1) ^ -(v & 1);
            }
            case "bool": {
                long v = readVarint(data, pos);
                return v != 0;
            }
            case "string": {
                int len = (int)readVarint(data, pos);
                String s = new String(data, pos[0], len, StandardCharsets.UTF_8);
                pos[0] += len;
                return s;
            }
            case "bytes": {
                int len = (int)readVarint(data, pos);
                byte[] b = Arrays.copyOfRange(data, pos[0], pos[0] + len);
                pos[0] += len;
                return b;
            }
            case "fixed32": {
                int v = (data[pos[0]] & 0xFF) | ((data[pos[0]+1] & 0xFF) << 8) | ((data[pos[0]+2] & 0xFF) << 16) | ((data[pos[0]+3] & 0xFF) << 24);
                pos[0] += 4;
                return v & 0xFFFFFFFFL;
            }
            case "sfixed32": {
                int v = (data[pos[0]] & 0xFF) | ((data[pos[0]+1] & 0xFF) << 8) | ((data[pos[0]+2] & 0xFF) << 16) | ((data[pos[0]+3] & 0xFF) << 24);
                pos[0] += 4;
                return (long)v;
            }
            case "fixed64": {
                long v = 0;
                for (int i = 0; i < 8; i++) v |= ((long)(data[pos[0]+i] & 0xFF)) << (i*8);
                pos[0] += 8;
                return v;
            }
            case "sfixed64": {
                long v = 0;
                for (int i = 0; i < 8; i++) v |= ((long)(data[pos[0]+i] & 0xFF)) << (i*8);
                pos[0] += 8;
                return v;
            }
            default: {
                // enum
                long v = readVarint(data, pos);
                return (int)v;
            }
        }
    }

    static void decodePacked(byte[] payload, FieldDef fd, Decoded dec) {
        int[] pos = {0};
        while (pos[0] < payload.length) {
            Object val = decodeScalarFromBytes(payload, pos, fd.type);
            appendRepeated(dec, fd.number, val);
        }
    }

    static Object decodeScalarFromBytes(byte[] data, int[] pos, String type) {
        switch (type) {
            case "int32": {
                long v = readVarint(data, pos);
                return (int)v;
            }
            case "int64": {
                return readVarint(data, pos);
            }
            case "uint32": {
                long v = readVarint(data, pos);
                return v & 0xFFFFFFFFL;
            }
            case "uint64": {
                return readVarint(data, pos);
            }
            case "sint32": {
                long v = readVarint(data, pos);
                return (int)((v >>> 1) ^ -(v & 1));
            }
            case "sint64": {
                long v = readVarint(data, pos);
                return (v >>> 1) ^ -(v & 1);
            }
            case "bool": {
                long v = readVarint(data, pos);
                return v != 0;
            }
            case "fixed32": {
                int v = (data[pos[0]] & 0xFF) | ((data[pos[0]+1] & 0xFF) << 8) | ((data[pos[0]+2] & 0xFF) << 16) | ((data[pos[0]+3] & 0xFF) << 24);
                pos[0] += 4;
                return v & 0xFFFFFFFFL;
            }
            case "sfixed32": {
                int v = (data[pos[0]] & 0xFF) | ((data[pos[0]+1] & 0xFF) << 8) | ((data[pos[0]+2] & 0xFF) << 16) | ((data[pos[0]+3] & 0xFF) << 24);
                pos[0] += 4;
                return (long)v;
            }
            case "fixed64": {
                long v = 0;
                for (int i = 0; i < 8; i++) v |= ((long)(data[pos[0]+i] & 0xFF)) << (i*8);
                pos[0] += 8;
                return v;
            }
            case "sfixed64": {
                long v = 0;
                for (int i = 0; i < 8; i++) v |= ((long)(data[pos[0]+i] & 0xFF)) << (i*8);
                pos[0] += 8;
                return v;
            }
            default: {
                // enum
                long v = readVarint(data, pos);
                return (int)v;
            }
        }
    }

    @SuppressWarnings("unchecked")
    static void appendRepeated(Decoded dec, int fieldNum, Object val) {
        List<Object> list = (List<Object>) dec.vals.get(fieldNum);
        if (list == null) {
            list = new ArrayList<>();
            dec.vals.put(fieldNum, list);
        }
        list.add(val);
    }

    @SuppressWarnings("unchecked")
    static void decodeMapEntry(byte[] entryBytes, FieldDef fd, Decoded dec) {
        int[] pos = {0};
        Object mapKey = null;
        Object mapVal = null;

        while (pos[0] < entryBytes.length) {
            long rawKey = readVarint(entryBytes, pos);
            int fn = (int)(rawKey >>> 3);
            int wt = (int)(rawKey & 7);

            if (fn == 1) {
                mapKey = decodeScalar(entryBytes, pos, wt, fd.mapKeyType);
            } else if (fn == 2) {
                if (isMessageType(fd.mapValueType)) {
                    int len = (int)readVarint(entryBytes, pos);
                    byte[] sub = Arrays.copyOfRange(entryBytes, pos[0], pos[0] + len);
                    pos[0] += len;
                    mapVal = decodeMessage(sub, fd.mapValueType);
                } else {
                    mapVal = decodeScalar(entryBytes, pos, wt, fd.mapValueType);
                }
            } else {
                skipValue(entryBytes, pos, wt, fn);
            }
        }

        if (mapKey == null) {
            if (fd.mapKeyType.equals("string")) mapKey = "";
            else mapKey = 0;
        }
        if (mapVal == null) {
            mapVal = getDefault(fd.mapValueType);
        }

        LinkedHashMap<Object, Object> map = (LinkedHashMap<Object, Object>) dec.vals.get(fd.number);
        if (map == null) {
            map = new LinkedHashMap<>();
            dec.vals.put(fd.number, map);
        }
        map.put(mapKey, mapVal);
    }

    static Object getDefault(String type) {
        switch (type) {
            case "string": return "";
            case "bytes": return new byte[0];
            case "bool": return false;
            case "int64": case "uint64": case "sint64": case "fixed64": case "sfixed64": return 0L;
            case "int32": case "uint32": case "sint32": case "fixed32": case "sfixed32": return 0;
            default:
                if (isMessageType(type)) return new Decoded();
                return 0;
        }
    }

    @SuppressWarnings("unchecked")
    static void mergeMessages(Object oldVal, Decoded newVal) {
        if (!(oldVal instanceof Decoded)) return;
        Decoded old = (Decoded) oldVal;

        // Handle oneof conflicts: if new message sets a different oneof member, clear old member
        for (String oneofName : newVal.oneofSet.keySet()) {
            Integer newMember = newVal.oneofSet.get(oneofName);
            Integer oldMember = old.oneofSet.get(oneofName);
            if (oldMember != null && oldMember.intValue() != newMember.intValue()) {
                old.vals.remove(oldMember);
                old.occurred.remove(oldMember);
            }
        }

        for (Integer fn : newVal.occurred) {
            old.occurred.add(fn);
            Object nv = newVal.vals.get(fn);
            Object ov = old.vals.get(fn);

            if (nv instanceof List) {
                if (ov instanceof List) {
                    ((List<Object>)ov).addAll((List<Object>)nv);
                } else {
                    old.vals.put(fn, nv);
                }
            } else if (nv instanceof LinkedHashMap) {
                if (ov instanceof LinkedHashMap) {
                    ((LinkedHashMap<Object,Object>)ov).putAll((Map<Object,Object>)nv);
                } else {
                    old.vals.put(fn, nv);
                }
            } else if (nv instanceof Decoded) {
                if (ov instanceof Decoded) {
                    mergeMessages(ov, (Decoded)nv);
                } else {
                    old.vals.put(fn, nv);
                }
            } else {
                old.vals.put(fn, nv);
            }
        }

        old.oneofSet.putAll(newVal.oneofSet);
    }

    // JSON output
    static String toJson(Decoded dec, String msgName) {
        MessageDef md = messages.get(msgName);
        StringBuilder sb = new StringBuilder("{");

        List<FieldDef> sorted = new ArrayList<>(md.fields);
        sorted.sort((a, b) -> a.number - b.number);

        boolean first = true;
        for (FieldDef fd : sorted) {
            if (!shouldPrint(dec, fd)) continue;
            if (!first) sb.append(",");
            first = false;
            sb.append("\"").append(escapeJson(camelCase(fd.name))).append("\":");
            sb.append(encodeValue(dec.vals.get(fd.number), fd));
        }

        sb.append("}");
        return sb.toString();
    }

    static boolean shouldPrint(Decoded dec, FieldDef fd) {
        if (fd.repeated) {
            Object val = dec.vals.get(fd.number);
            return val != null && ((List<?>)val).size() > 0;
        }
        if (fd.type.equals("map")) {
            Object val = dec.vals.get(fd.number);
            return val != null && ((Map<?,?>)val).size() > 0;
        }
        if (!dec.occurred.contains(fd.number)) return false;
        if (fd.optional) return true;
        if (fd.oneof != null) {
            Integer set = dec.oneofSet.get(fd.oneof);
            return set != null && set.intValue() == fd.number;
        }
        if (isMessageType(fd.type)) return true;
        Object val = dec.vals.get(fd.number);
        return isNonDefault(val, fd.type);
    }

    static boolean isNonDefault(Object val, String type) {
        if (val == null) return false;
        if (type.equals("bool")) return (Boolean)val;
        if (type.equals("string")) return !((String)val).isEmpty();
        if (type.equals("bytes")) return ((byte[])val).length > 0;
        long num;
        if (val instanceof Integer) num = (Integer)val;
        else num = (Long)val;
        return num != 0;
    }

    @SuppressWarnings("unchecked")
    static String encodeValue(Object val, FieldDef fd) {
        if (fd.repeated) {
            List<Object> list = (List<Object>) val;
            StringBuilder sb = new StringBuilder("[");
            for (int i = 0; i < list.size(); i++) {
                if (i > 0) sb.append(",");
                sb.append(encodeSingle(list.get(i), fd.type));
            }
            sb.append("]");
            return sb.toString();
        }
        if (fd.type.equals("map")) {
            LinkedHashMap<Object, Object> map = (LinkedHashMap<Object, Object>) val;
            List<Object> keys = new ArrayList<>(map.keySet());
            if (fd.mapKeyType.equals("string")) {
                keys.sort((a, b) -> {
                    byte[] ba = ((String)a).getBytes(StandardCharsets.UTF_8);
                    byte[] bb = ((String)b).getBytes(StandardCharsets.UTF_8);
                    int len = Math.min(ba.length, bb.length);
                    for (int i = 0; i < len; i++) {
                        int diff = (ba[i] & 0xFF) - (bb[i] & 0xFF);
                        if (diff != 0) return diff;
                    }
                    return ba.length - bb.length;
                });
            } else {
                keys.sort((a, b) -> Integer.compare((Integer)a, (Integer)b));
            }
            StringBuilder sb = new StringBuilder("{");
            boolean first = true;
            for (Object key : keys) {
                if (!first) sb.append(",");
                first = false;
                String keyStr;
                if (fd.mapKeyType.equals("string")) {
                    keyStr = escapeJson((String)key);
                } else {
                    keyStr = String.valueOf((Integer)key);
                }
                sb.append("\"").append(keyStr).append("\":");
                sb.append(encodeSingle(map.get(key), fd.mapValueType));
            }
            sb.append("}");
            return sb.toString();
        }
        return encodeSingle(val, fd.type);
    }

    static String encodeSingle(Object val, String type) {
        if (val == null) return "null";

        switch (type) {
            case "int32": case "uint32": case "sint32": case "fixed32": case "sfixed32":
                return String.valueOf(((Number)val).longValue());
            case "int64": case "sint64": case "sfixed64":
                return "\"" + val + "\"";
            case "uint64": case "fixed64":
                return "\"" + Long.toUnsignedString((Long)val) + "\"";
            case "bool":
                return (Boolean)val ? "true" : "false";
            case "string":
                return "\"" + escapeJson((String)val) + "\"";
            case "bytes":
                return "\"" + Base64.getEncoder().encodeToString((byte[])val) + "\"";
            default:
                if (isMessageType(type)) {
                    return toJson((Decoded)val, type);
                }
                // enum
                EnumDef ed = enums.get(type);
                int num;
                if (val instanceof Integer) num = (Integer)val;
                else num = ((Long)val).intValue();
                String name = ed.numToName.get(num);
                if (name != null) return "\"" + name + "\"";
                return String.valueOf(num);
        }
    }

    static String camelCase(String name) {
        StringBuilder sb = new StringBuilder();
        boolean upper = false;
        for (int i = 0; i < name.length(); i++) {
            char c = name.charAt(i);
            if (c == '_') {
                upper = true;
            } else {
                if (upper && c >= 'a' && c <= 'z') {
                    sb.append((char)(c - 32));
                } else {
                    sb.append(c);
                }
                upper = false;
            }
        }
        return sb.toString();
    }

    static String escapeJson(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\b': sb.append("\\b"); break;
                case '\t': sb.append("\\t"); break;
                case '\n': sb.append("\\n"); break;
                case '\f': sb.append("\\f"); break;
                case '\r': sb.append("\\r"); break;
                default:
                    if (c < 0x20) {
                        sb.append(String.format("\\u%04x", (int)c));
                    } else {
                        sb.append(c);
                    }
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];
        String protoContent = new String(Files.readAllBytes(Paths.get(dir, "schema.proto")), StandardCharsets.UTF_8);
        parseProto(protoContent);

        byte[] binData = Files.readAllBytes(Paths.get(dir, "messages.bin"));
        int[] pos = {0};
        StringBuilder out = new StringBuilder();

        while (pos[0] < binData.length) {
            int recLen = (int)readVarint(binData, pos);
            byte[] recData = Arrays.copyOfRange(binData, pos[0], pos[0] + recLen);
            pos[0] += recLen;

            Decoded dec = decodeMessage(recData, rootType);
            out.append(toJson(dec, rootType)).append("\n");
        }

        System.out.print(out.toString());
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

/* ============ JSON Parser ============ */

typedef enum { J_NULL, J_TRUE, J_FALSE, J_NUM, J_STR, J_ARR, J_OBJ } JType;

typedef struct JV {
    JType type;
    long long num;
    char *str;
    struct JV **items;
    int count;
    char **keys;
} JV;

static const char *jp;

static void skip_ws(void) {
    while (*jp == ' ' || *jp == '\t' || *jp == '\n' || *jp == '\r') jp++;
}

static char *parse_str(void) {
    jp++; /* skip opening " */
    const char *start = jp;
    while (*jp != '"') {
        if (*jp == '\\') jp++;
        jp++;
    }
    int len = (int)(jp - start);
    char *s = (char*)malloc(len + 1);
    memcpy(s, start, len);
    s[len] = '\0';
    jp++; /* skip closing " */
    return s;
}

static JV *parse_val(void);

static JV *parse_val(void) {
    skip_ws();
    JV *v = (JV*)calloc(1, sizeof(JV));
    char c = *jp;
    if (c == '{') {
        jp++;
        v->type = J_OBJ;
        int cap = 16;
        v->keys = (char**)malloc(cap * sizeof(char*));
        v->items = (JV**)malloc(cap * sizeof(JV*));
        v->count = 0;
        skip_ws();
        if (*jp == '}') { jp++; return v; }
        for (;;) {
            skip_ws();
            char *key = parse_str();
            skip_ws();
            jp++; /* ':' */
            JV *val = parse_val();
            if (v->count >= cap) {
                cap *= 2;
                v->keys = (char**)realloc(v->keys, cap * sizeof(char*));
                v->items = (JV**)realloc(v->items, cap * sizeof(JV*));
            }
            v->keys[v->count] = key;
            v->items[v->count] = val;
            v->count++;
            skip_ws();
            if (*jp == '}') { jp++; break; }
            jp++; /* ',' */
        }
    } else if (c == '[') {
        jp++;
        v->type = J_ARR;
        int cap = 16;
        v->items = (JV**)malloc(cap * sizeof(JV*));
        v->count = 0;
        skip_ws();
        if (*jp == ']') { jp++; return v; }
        for (;;) {
            JV *val = parse_val();
            if (v->count >= cap) {
                cap *= 2;
                v->items = (JV**)realloc(v->items, cap * sizeof(JV*));
            }
            v->items[v->count++] = val;
            skip_ws();
            if (*jp == ']') { jp++; break; }
            jp++; /* ',' */
        }
    } else if (c == '"') {
        v->type = J_STR;
        v->str = parse_str();
    } else if (c == 't') {
        jp += 4; v->type = J_TRUE;
    } else if (c == 'f') {
        jp += 5; v->type = J_FALSE;
    } else if (c == 'n') {
        jp += 4; v->type = J_NULL;
    } else {
        v->type = J_NUM;
        char *end;
        v->num = strtoll(jp, &end, 10);
        jp = end;
    }
    return v;
}

static JV *obj_get(JV *obj, const char *key) {
    for (int i = 0; i < obj->count; i++)
        if (strcmp(obj->keys[i], key) == 0) return obj->items[i];
    return NULL;
}

/* ============ PNG helpers ============ */

static uint32_t crc_tab[256];

static void init_crc(void) {
    for (uint32_t i = 0; i < 256; i++) {
        uint32_t c = i;
        for (int j = 0; j < 8; j++)
            c = (c & 1) ? (0xEDB88320u ^ (c >> 1)) : (c >> 1);
        crc_tab[i] = c;
    }
}

static uint32_t crc32(const uint8_t *d, size_t n) {
    uint32_t c = 0xFFFFFFFFu;
    for (size_t i = 0; i < n; i++)
        c = crc_tab[(c ^ d[i]) & 0xFF] ^ (c >> 8);
    return c ^ 0xFFFFFFFFu;
}

static void wbe32(FILE *f, uint32_t v) {
    fputc((v >> 24) & 0xFF, f);
    fputc((v >> 16) & 0xFF, f);
    fputc((v >> 8) & 0xFF, f);
    fputc(v & 0xFF, f);
}

static void write_chunk(FILE *f, const char *type, const uint8_t *data, size_t len) {
    wbe32(f, (uint32_t)len);
    uint8_t hdr[4];
    memcpy(hdr, type, 4);
    uint32_t c = crc32(hdr, 4);
    if (len > 0) {
        /* extend CRC over data */
        c = c ^ 0xFFFFFFFFu; /* undo final xor to continue */
        for (size_t i = 0; i < len; i++)
            c = crc_tab[(c ^ data[i]) & 0xFF] ^ (c >> 8);
        c = c ^ 0xFFFFFFFFu;
    }
    fwrite(type, 1, 4, f);
    if (len > 0) fwrite(data, 1, len, f);
    wbe32(f, c);
}

/* ============ Shape rendering ============ */

#define RECT 0
#define CIRCLE 1
#define TRIANGLE 2
#define LINE 3

typedef struct {
    int type;
    long long x, y, w, h;
    long long cx, cy, r;
    long long pts[6];
    long long x1, y1, x2, y2, lr;
    int col[4];
} Shape;

static int cmp_ll(const void *a, const void *b) {
    long long va = *(const long long*)a, vb = *(const long long*)b;
    return (va < vb) ? -1 : (va > vb) ? 1 : 0;
}

static long long isqrt_ll(long long n) {
    if (n <= 0) return 0;
    long long lo = 0, hi = n;
    if (hi > 4000) hi = 4000;
    while (lo < hi) {
        long long mid = (lo + hi + 1) / 2;
        if (mid * mid <= n) lo = mid;
        else hi = mid - 1;
    }
    return lo;
}

int main(int argc, char *argv[]) {
    if (argc < 2) { fprintf(stderr, "Usage: %s <dir>\n", argv[0]); return 1; }

    char path[4096];
    snprintf(path, sizeof(path), "%s/scene.json", argv[1]);
    FILE *f = fopen(path, "rb");
    if (!f) { perror("scene.json"); return 1; }
    fseek(f, 0, SEEK_END);
    long fsz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char*)malloc(fsz + 1);
    fread(buf, 1, fsz, f);
    buf[fsz] = '\0';
    fclose(f);

    jp = buf;
    JV *root = parse_val();

    int width = (int)obj_get(root, "width")->num;
    int height = (int)obj_get(root, "height")->num;
    JV *bgv = obj_get(root, "background");
    int bgR = (int)bgv->items[0]->num;
    int bgG = (int)bgv->items[1]->num;
    int bgB = (int)bgv->items[2]->num;

    JV *shapesArr = obj_get(root, "shapes");
    int ns = shapesArr->count;
    Shape *shapes = (Shape*)calloc(ns > 0 ? ns : 1, sizeof(Shape));

    const char *type_names[] = {"rect", "circle", "triangle", "line"};

    for (int i = 0; i < ns; i++) {
        JV *s = shapesArr->items[i];
        JV *tv = obj_get(s, "type");
        if (strcmp(tv->str, "rect") == 0) {
            shapes[i].type = RECT;
            shapes[i].x = obj_get(s, "x")->num;
            shapes[i].y = obj_get(s, "y")->num;
            shapes[i].w = obj_get(s, "w")->num;
            shapes[i].h = obj_get(s, "h")->num;
        } else if (strcmp(tv->str, "circle") == 0) {
            shapes[i].type = CIRCLE;
            shapes[i].cx = obj_get(s, "cx")->num;
            shapes[i].cy = obj_get(s, "cy")->num;
            shapes[i].r = obj_get(s, "r")->num;
        } else if (strcmp(tv->str, "triangle") == 0) {
            shapes[i].type = TRIANGLE;
            JV *pts = obj_get(s, "points");
            for (int j = 0; j < 3; j++) {
                shapes[i].pts[j*2]   = pts->items[j]->items[0]->num;
                shapes[i].pts[j*2+1] = pts->items[j]->items[1]->num;
            }
        } else {
            shapes[i].type = LINE;
            shapes[i].x1 = obj_get(s, "x1")->num;
            shapes[i].y1 = obj_get(s, "y1")->num;
            shapes[i].x2 = obj_get(s, "x2")->num;
            shapes[i].y2 = obj_get(s, "y2")->num;
            shapes[i].lr = obj_get(s, "r")->num;
        }
        JV *cv = obj_get(s, "color");
        shapes[i].col[0] = (int)cv->items[0]->num;
        shapes[i].col[1] = (int)cv->items[1]->num;
        shapes[i].col[2] = (int)cv->items[2]->num;
        shapes[i].col[3] = (int)cv->items[3]->num;
    }

    /* Canvas */
    int cpx = width * height;
    uint8_t *canvas = (uint8_t*)malloc((size_t)cpx * 3);
    for (int i = 0; i < cpx; i++) {
        canvas[i*3]   = (uint8_t)bgR;
        canvas[i*3+1] = (uint8_t)bgG;
        canvas[i*3+2] = (uint8_t)bgB;
    }

    /* Render */
    for (int si = 0; si < ns; si++) {
        Shape *s = &shapes[si];
        int A = s->col[3];
        int sR = s->col[0], sG = s->col[1], sB = s->col[2];
        int count = 0;

        long long ylo = 0, yhi = height - 1, xlo = 0, xhi = width - 1;

        if (s->type == RECT) {
            long long rx0 = s->x, rx1 = s->x + s->w - 1;
            long long ry0 = s->y, ry1 = s->y + s->h - 1;
            if (rx0 < xlo) rx0 = xlo;
            if (ry0 < ylo) ry0 = ylo;
            if (rx1 > xhi) rx1 = xhi;
            if (ry1 > yhi) ry1 = yhi;
            for (long long py = ry0; py <= ry1; py++) {
                for (long long px = rx0; px <= rx1; px++) {
                    int idx = (int)(py * width + px) * 3;
                    canvas[idx]   = (uint8_t)((sR * A + canvas[idx]   * (255 - A) + 127) / 255);
                    canvas[idx+1] = (uint8_t)((sG * A + canvas[idx+1] * (255 - A) + 127) / 255);
                    canvas[idx+2] = (uint8_t)((sB * A + canvas[idx+2] * (255 - A) + 127) / 255);
                    count++;
                }
            }
        } else if (s->type == CIRCLE) {
            long long r2 = s->r * s->r;
            long long cy_lo = s->cy - s->r, cy_hi = s->cy + s->r;
            if (cy_lo < ylo) cy_lo = ylo;
            if (cy_hi > yhi) cy_hi = yhi;
            for (long long py = cy_lo; py <= cy_hi; py++) {
                long long dy = py - s->cy;
                long long dy2 = dy * dy;
                if (dy2 > r2) continue;
                long long rem = r2 - dy2;
                long long dxm = isqrt_ll(rem);
                long long lx = s->cx - dxm, rx = s->cx + dxm;
                if (lx < xlo) lx = xlo;
                if (rx > xhi) rx = xhi;
                for (long long px = lx; px <= rx; px++) {
                    long long dx = px - s->cx;
                    if (dx * dx + dy2 <= r2) {
                        int idx = (int)(py * width + px) * 3;
                        canvas[idx]   = (uint8_t)((sR * A + canvas[idx]   * (255 - A) + 127) / 255);
                        canvas[idx+1] = (uint8_t)((sG * A + canvas[idx+1] * (255 - A) + 127) / 255);
                        canvas[idx+2] = (uint8_t)((sB * A + canvas[idx+2] * (255 - A) + 127) / 255);
                        count++;
                    }
                }
            }
        } else if (s->type == TRIANGLE) {
            long long tx0 = s->pts[0], tx1 = s->pts[0];
            long long ty0 = s->pts[1], ty1 = s->pts[1];
            for (int j = 1; j < 3; j++) {
                long long px_ = s->pts[j*2], py_ = s->pts[j*2+1];
                if (px_ < tx0) tx0 = px_; if (px_ > tx1) tx1 = px_;
                if (py_ < ty0) ty0 = py_; if (py_ > ty1) ty1 = py_;
            }
            if (tx0 < xlo) tx0 = xlo;
            if (ty0 < ylo) ty0 = ylo;
            if (tx1 > xhi) tx1 = xhi;
            if (ty1 > yhi) ty1 = yhi;
            long long ax = s->pts[0], ay = s->pts[1];
            long long bx = s->pts[2], by = s->pts[3];
            long long cx_ = s->pts[4], cy_ = s->pts[5];
            long long abx = bx - ax, aby = by - ay;
            long long bcx = cx_ - bx, bcy = cy_ - by;
            long long cax = ax - cx_, cay = ay - cy_;
            for (long long py = ty0; py <= ty1; py++) {
                for (long long px = tx0; px <= tx1; px++) {
                    long long e0 = abx * (py - ay) - aby * (px - ax);
                    long long e1 = bcx * (py - by) - bcy * (px - bx);
                    long long e2 = cax * (py - cy_) - cay * (px - cx_);
                    if ((e0 >= 0 && e1 >= 0 && e2 >= 0) ||
                        (e0 <= 0 && e1 <= 0 && e2 <= 0)) {
                        int idx = (int)(py * width + px) * 3;
                        canvas[idx]   = (uint8_t)((sR * A + canvas[idx]   * (255 - A) + 127) / 255);
                        canvas[idx+1] = (uint8_t)((sG * A + canvas[idx+1] * (255 - A) + 127) / 255);
                        canvas[idx+2] = (uint8_t)((sB * A + canvas[idx+2] * (255 - A) + 127) / 255);
                        count++;
                    }
                }
            }
        } else { /* LINE */
            long long dx = s->x2 - s->x1;
            long long dy = s->y2 - s->y1;
            long long L = dx * dx + dy * dy;
            long long r2 = s->lr * s->lr;
            long long lx = (s->x1 < s->x2 ? s->x1 : s->x2) - s->lr;
            long long rx = (s->x1 > s->x2 ? s->x1 : s->x2) + s->lr;
            long long ly = (s->y1 < s->y2 ? s->y1 : s->y2) - s->lr;
            long long hy = (s->y1 > s->y2 ? s->y1 : s->y2) + s->lr;
            if (lx < xlo) lx = xlo;
            if (ly < ylo) ly = ylo;
            if (rx > xhi) rx = xhi;
            if (hy > yhi) hy = yhi;
            for (long long py = ly; py <= hy; py++) {
                for (long long px = lx; px <= rx; px++) {
                    int cov = 0;
                    long long t = (px - s->x1) * dx + (py - s->y1) * dy;
                    if (t <= 0) {
                        long long ddx = px - s->x1, ddy = py - s->y1;
                        cov = (ddx * ddx + ddy * ddy <= r2);
                    } else if (t >= L) {
                        long long ddx = px - s->x2, ddy = py - s->y2;
                        cov = (ddx * ddx + ddy * ddy <= r2);
                    } else {
                        long long c = (px - s->x1) * dy - (py - s->y1) * dx;
                        cov = (c * c <= r2 * L);
                    }
                    if (cov) {
                        int idx = (int)(py * width + px) * 3;
                        canvas[idx]   = (uint8_t)((sR * A + canvas[idx]   * (255 - A) + 127) / 255);
                        canvas[idx+1] = (uint8_t)((sG * A + canvas[idx+1] * (255 - A) + 127) / 255);
                        canvas[idx+2] = (uint8_t)((sB * A + canvas[idx+2] * (255 - A) + 127) / 255);
                        count++;
                    }
                }
            }
        }
        printf("%d %s %d\n", si + 1, type_names[s->type], count);
    }

    /* Count distinct colors */
    long long *colarr = (long long*)malloc((size_t)cpx * sizeof(long long));
    for (int i = 0; i < cpx; i++)
        colarr[i] = ((long long)canvas[i*3] << 16) | ((long long)canvas[i*3+1] << 8) | (long long)canvas[i*3+2];
    qsort(colarr, (size_t)cpx, sizeof(long long), cmp_ll);
    int ndist = 0;
    for (int i = 0; i < cpx; i++)
        if (i == 0 || colarr[i] != colarr[i-1]) ndist++;
    printf("colors %d\n", ndist);
    free(colarr);

    /* Write PNG */
    init_crc();
    FILE *out = fopen("out.png", "wb");

    /* Signature */
    uint8_t sig[8] = {137,80,78,71,13,10,26,10};
    fwrite(sig, 1, 8, out);

    /* IHDR */
    uint8_t ihdr[13];
    ihdr[0]=(width>>24)&0xFF; ihdr[1]=(width>>16)&0xFF; ihdr[2]=(width>>8)&0xFF; ihdr[3]=width&0xFF;
    ihdr[4]=(height>>24)&0xFF; ihdr[5]=(height>>16)&0xFF; ihdr[6]=(height>>8)&0xFF; ihdr[7]=height&0xFF;
    ihdr[8]=8; ihdr[9]=2; ihdr[10]=0; ihdr[11]=0; ihdr[12]=0;
    write_chunk(out, "IHDR", ihdr, 13);

    /* IDAT: zlib with stored blocks */
    size_t rowlen = 1 + (size_t)width * 3;
    size_t raw_size = rowlen * (size_t)height;
    uint8_t *raw = (uint8_t*)malloc(raw_size);
    for (int y = 0; y < height; y++) {
        raw[y * rowlen] = 0;
        memcpy(raw + y * rowlen + 1, canvas + (size_t)y * width * 3, (size_t)width * 3);
    }

    /* Adler-32 */
    uint32_t s1 = 1, s2 = 0;
    for (size_t i = 0; i < raw_size; i++) {
        s1 = (s1 + raw[i]) % 65521;
        s2 = (s2 + s1) % 65521;
    }
    uint32_t adler = (s2 << 16) | s1;

    /* Build zlib stream */
    size_t nblocks = (raw_size + 65534) / 65535;
    if (nblocks == 0) nblocks = 1;
    size_t idat_cap = 2 + nblocks * 5 + raw_size + 4;
    uint8_t *idat = (uint8_t*)malloc(idat_cap);
    size_t pos = 0;
    idat[pos++] = 0x78;
    idat[pos++] = 0x01;

    size_t rem = raw_size;
    size_t soff = 0;
    if (rem == 0) {
        /* empty stored block */
        idat[pos++] = 0x01;
        idat[pos++] = 0x00; idat[pos++] = 0x00;
        idat[pos++] = 0xFF; idat[pos++] = 0xFF;
    }
    while (rem > 0) {
        size_t bsz = rem > 65535 ? 65535 : rem;
        int last = (rem == bsz);
        idat[pos++] = last ? 0x01 : 0x00;
        idat[pos++] = bsz & 0xFF;
        idat[pos++] = (bsz >> 8) & 0xFF;
        uint16_t nlen = (uint16_t)(~(uint16_t)bsz);
        idat[pos++] = nlen & 0xFF;
        idat[pos++] = (nlen >> 8) & 0xFF;
        memcpy(idat + pos, raw + soff, bsz);
        pos += bsz;
        soff += bsz;
        rem -= bsz;
    }
    idat[pos++] = (adler >> 24) & 0xFF;
    idat[pos++] = (adler >> 16) & 0xFF;
    idat[pos++] = (adler >> 8) & 0xFF;
    idat[pos++] = adler & 0xFF;

    write_chunk(out, "IDAT", idat, pos);
    free(idat);
    free(raw);

    /* IEND */
    write_chunk(out, "IEND", NULL, 0);
    fclose(out);
    free(canvas);
    free(buf);
    free(shapes);
    return 0;
}

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {

    // ==================== JSON Parser ====================
    static class JsonParser {
        private final String input;
        private int pos;

        JsonParser(String input) {
            this.input = input;
            this.pos = 0;
        }

        Object parse() {
            skipWhitespace();
            Object val = parseValue();
            return val;
        }

        private Object parseValue() {
            char c = peek();
            switch (c) {
                case '{': return parseObject();
                case '[': return parseArray();
                case '"': return parseString();
                case 't': pos += 4; return Boolean.TRUE;
                case 'f': pos += 5; return Boolean.FALSE;
                case 'n': pos += 4; return null;
                default:  return parseNumber();
            }
        }

        @SuppressWarnings("unchecked")
        private Map<String, Object> parseObject() {
            Map<String, Object> map = new LinkedHashMap<>();
            expect('{');
            skipWhitespace();
            if (peek() == '}') { pos++; return map; }
            while (true) {
                skipWhitespace();
                String key = parseString();
                skipWhitespace();
                expect(':');
                skipWhitespace();
                map.put(key, parseValue());
                skipWhitespace();
                char c = peek();
                if (c == '}') { pos++; return map; }
                expect(',');
            }
        }

        private List<Object> parseArray() {
            List<Object> list = new ArrayList<>();
            expect('[');
            skipWhitespace();
            if (peek() == ']') { pos++; return list; }
            while (true) {
                skipWhitespace();
                list.add(parseValue());
                skipWhitespace();
                char c = peek();
                if (c == ']') { pos++; return list; }
                expect(',');
            }
        }

        private String parseString() {
            expect('"');
            StringBuilder sb = new StringBuilder();
            while (true) {
                char c = input.charAt(pos++);
                if (c == '"') return sb.toString();
                if (c == '\\') {
                    char esc = input.charAt(pos++);
                    switch (esc) {
                        case '"':  sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/':  sb.append('/'); break;
                        case 'b':  sb.append('\b'); break;
                        case 'f':  sb.append('\f'); break;
                        case 'n':  sb.append('\n'); break;
                        case 'r':  sb.append('\r'); break;
                        case 't':  sb.append('\t'); break;
                        case 'u': {
                            int hi = Integer.parseInt(input.substring(pos, pos + 4), 16);
                            pos += 4;
                            if (hi >= 0xD800 && hi <= 0xDBFF) {
                                if (pos + 1 < input.length() && input.charAt(pos) == '\\' && input.charAt(pos + 1) == 'u') {
                                    pos += 2;
                                    int lo = Integer.parseInt(input.substring(pos, pos + 4), 16);
                                    pos += 4;
                                    int cp = 0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00);
                                    sb.append(Character.toChars(cp));
                                } else {
                                    sb.append((char) hi);
                                }
                            } else {
                                sb.append((char) hi);
                            }
                            break;
                        }
                        default: sb.append(esc);
                    }
                } else {
                    sb.append(c);
                }
            }
        }

        private Number parseNumber() {
            int start = pos;
            if (pos < input.length() && input.charAt(pos) == '-') pos++;
            while (pos < input.length() && input.charAt(pos) >= '0' && input.charAt(pos) <= '9') pos++;
            boolean isFloat = false;
            if (pos < input.length() && input.charAt(pos) == '.') {
                isFloat = true; pos++;
                while (pos < input.length() && input.charAt(pos) >= '0' && input.charAt(pos) <= '9') pos++;
            }
            if (pos < input.length() && (input.charAt(pos) == 'e' || input.charAt(pos) == 'E')) {
                isFloat = true; pos++;
                if (pos < input.length() && (input.charAt(pos) == '+' || input.charAt(pos) == '-')) pos++;
                while (pos < input.length() && input.charAt(pos) >= '0' && input.charAt(pos) <= '9') pos++;
            }
            String numStr = input.substring(start, pos);
            if (isFloat) return Double.parseDouble(numStr);
            long v = Long.parseLong(numStr);
            if (v >= Integer.MIN_VALUE && v <= Integer.MAX_VALUE) return (int) v;
            return v;
        }

        private char peek() { return input.charAt(pos); }
        private void expect(char c) {
            if (input.charAt(pos) != c) throw new RuntimeException("JSON: expected '" + c + "' at pos " + pos);
            pos++;
        }
        private void skipWhitespace() {
            while (pos < input.length()) {
                char c = input.charAt(pos);
                if (c == ' ' || c == '\t' || c == '\n' || c == '\r') pos++;
                else break;
            }
        }
    }

    // ==================== HTTP Client ====================
    static class HttpResponse {
        int status;
        Map<String, String> headers;
        String body;
    }

    private static String readLine(InputStream in) throws IOException {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = in.read()) != -1) {
            if (c == '\n') break;
            if (c == '\r') {
                in.mark(1);
                int next = in.read();
                if (next != '\n' && next != -1) in.reset();
                break;
            }
            sb.append((char) c);
        }
        return sb.toString();
    }

    private static byte[] readNBytes(InputStream in, int n) throws IOException {
        byte[] buf = new byte[n];
        int off = 0;
        while (off < n) {
            int r = in.read(buf, off, n - off);
            if (r == -1) break;
            off += r;
        }
        return Arrays.copyOf(buf, off);
    }

    private static byte[] readChunked(InputStream in) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        while (true) {
            String sizeLine = readLine(in);
            if (sizeLine == null || sizeLine.isEmpty()) {
                // might be trailing empty line after last chunk
                break;
            }
            int semi = sizeLine.indexOf(';');
            if (semi >= 0) sizeLine = sizeLine.substring(0, semi);
            int chunkSize = Integer.parseInt(sizeLine.trim(), 16);
            if (chunkSize == 0) {
                // consume optional trailers + final CRLF
                // read remaining lines until empty
                while (true) {
                    String t = readLine(in);
                    if (t == null || t.isEmpty()) break;
                }
                break;
            }
            byte[] chunk = readNBytes(in, chunkSize);
            baos.write(chunk);
            // consume CRLF after chunk data
            readLine(in);
        }
        return baos.toByteArray();
    }

    @SuppressWarnings("unchecked")
    private static HttpResponse httpRequest(String method, String host, int port, String path,
                                           Map<String, String> extraHeaders, String body) throws IOException {
        Socket socket = new Socket();
        socket.connect(new InetSocketAddress(host, port), 30000);
        socket.setSoTimeout(30000);
        OutputStream out = socket.getOutputStream();
        InputStream in = new BufferedInputStream(socket.getInputStream());

        StringBuilder req = new StringBuilder();
        req.append(method).append(" ").append(path).append(" HTTP/1.1\r\n");
        req.append("Host: ").append(host);
        if (port != 80) req.append(":").append(port);
        req.append("\r\n");
        if (extraHeaders != null) {
            for (Map.Entry<String, String> e : extraHeaders.entrySet()) {
                req.append(e.getKey()).append(": ").append(e.getValue()).append("\r\n");
            }
        }
        byte[] bodyBytes = null;
        if (body != null) {
            bodyBytes = body.getBytes(StandardCharsets.UTF_8);
            req.append("Content-Length: ").append(bodyBytes.length).append("\r\n");
        }
        req.append("\r\n");

        out.write(req.toString().getBytes(StandardCharsets.US_ASCII));
        if (bodyBytes != null) out.write(bodyBytes);
        out.flush();

        String statusLine = readLine(in);
        String[] parts = statusLine.split(" ", 3);
        int status = Integer.parseInt(parts[1]);

        Map<String, String> headers = new LinkedHashMap<>();
        while (true) {
            String line = readLine(in);
            if (line == null || line.isEmpty()) break;
            int colon = line.indexOf(':');
            if (colon < 0) continue;
            String key = line.substring(0, colon).trim().toLowerCase();
            String val = line.substring(colon + 1).trim();
            headers.put(key, val);
        }

        byte[] respBody;
        String te = headers.get("transfer-encoding");
        if (te != null && te.toLowerCase().contains("chunked")) {
            respBody = readChunked(in);
        } else if (headers.containsKey("content-length")) {
            int len = Integer.parseInt(headers.get("content-length"));
            respBody = readNBytes(in, len);
        } else {
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            byte[] buf = new byte[8192];
            int r;
            while ((r = in.read(buf)) != -1) {
                baos.write(buf, 0, r);
            }
            respBody = baos.toByteArray();
        }

        socket.close();

        HttpResponse resp = new HttpResponse();
        resp.status = status;
        resp.headers = headers;
        resp.body = new String(respBody, StandardCharsets.UTF_8);
        return resp;
    }

    // ==================== Encoding Helpers ====================
    private static String formUrlEncode(String s) {
        StringBuilder sb = new StringBuilder();
        byte[] bytes = s.getBytes(StandardCharsets.UTF_8);
        for (byte b : bytes) {
            int c = b & 0xFF;
            if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')
                    || c == '-' || c == '.' || c == '_' || c == '*') {
                sb.append((char) c);
            } else if (c == ' ') {
                sb.append('+');
            } else {
                sb.append(String.format("%%%02X", c));
            }
        }
        return sb.toString();
    }

    private static String percentEncode(String s) {
        StringBuilder sb = new StringBuilder();
        byte[] bytes = s.getBytes(StandardCharsets.UTF_8);
        for (byte b : bytes) {
            int c = b & 0xFF;
            if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')
                    || c == '-' || c == '.' || c == '_' || c == '~') {
                sb.append((char) c);
            } else {
                sb.append(String.format("%%%02X", c));
            }
        }
        return sb.toString();
    }

    // ==================== Amount Helpers ====================
    private static long parseAmountToCents(String s) {
        int i = 0;
        boolean neg = false;
        if (s.charAt(0) == '-') { neg = true; i++; }
        long whole = 0;
        while (i < s.length() && s.charAt(i) >= '0' && s.charAt(i) <= '9') {
            whole = whole * 10 + (s.charAt(i) - '0');
            i++;
        }
        long frac = 0;
        int fracDigits = 0;
        if (i < s.length() && s.charAt(i) == '.') {
            i++;
            while (i < s.length() && s.charAt(i) >= '0' && s.charAt(i) <= '9') {
                frac = frac * 10 + (s.charAt(i) - '0');
                fracDigits++;
                i++;
            }
        }
        if (fracDigits == 1) frac *= 10;
        long cents = whole * 100 + frac;
        return neg ? -cents : cents;
    }

    private static String formatCents(long cents) {
        boolean neg = cents < 0;
        long abs = Math.abs(cents);
        long whole = abs / 100;
        long frac = abs % 100;
        String s = whole + "." + (frac < 10 ? "0" : "") + frac;
        return neg ? "-" + s : s;
    }

    // ==================== Sorting ====================
    private static int compareUtf8(String a, String b) {
        byte[] ab = a.getBytes(StandardCharsets.UTF_8);
        byte[] bb = b.getBytes(StandardCharsets.UTF_8);
        int len = Math.min(ab.length, bb.length);
        for (int i = 0; i < len; i++) {
            int d = (ab[i] & 0xFF) - (bb[i] & 0xFF);
            if (d != 0) return d;
        }
        return ab.length - bb.length;
    }

    // ==================== Main ====================
    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        String dataDir = args[0];
        String baseUrl = args[1];

        URI uri = new URI(baseUrl);
        String host = uri.getHost();
        int port = uri.getPort();
        if (port == -1) port = 80;
        String basePath = uri.getPath();

        // Read client.json
        String clientJsonStr = new String(
                new FileInputStream(dataDir + "/client.json").readAllBytes(),
                StandardCharsets.UTF_8);
        Map<String, Object> client = (Map<String, Object>) new JsonParser(clientJsonStr).parse();

        String clientId = (String) client.get("client_id");
        String clientSecret = (String) client.get("client_secret");
        String scope = (String) client.get("scope");
        int pageSize = ((Number) client.get("page_size")).intValue();

        // Build Basic auth
        String credentials = formUrlEncode(clientId) + ":" + formUrlEncode(clientSecret);
        String basicAuth = "Basic " + Base64.getEncoder().encodeToString(credentials.getBytes(StandardCharsets.UTF_8));

        String tokenPath = basePath + "/oauth/token";
        String tokenBody = "grant_type=client_credentials&scope=" + formUrlEncode(scope);

        Map<String, String> tokenHeaders = new LinkedHashMap<>();
        tokenHeaders.put("Content-Type", "application/x-www-form-urlencoded");
        tokenHeaders.put("Authorization", basicAuth);

        // Step 1: get token
        HttpResponse tokenResp = httpRequest("POST", host, port, tokenPath, tokenHeaders, tokenBody);
        if (tokenResp.status != 200) {
            System.out.println("ERROR " + tokenResp.status + " " + tokenResp.body);
            System.exit(0);
        }
        Map<String, Object> tokenData = (Map<String, Object>) new JsonParser(tokenResp.body).parse();
        String accessToken = (String) tokenData.get("access_token");

        // Step 2: fetch orders
        int ordersCount = 0;
        int pagesCount = 0;
        int retriesCount = 0;
        int reauthCount = 0;

        // key = name + "\0" + currency
        Map<String, Long> totals = new LinkedHashMap<>();
        Map<String, Integer> statusCounts = new LinkedHashMap<>();

        String cursor = null;
        boolean freshToken = true;

        while (true) {
            String path = basePath + "/orders?limit=" + pageSize;
            if (cursor != null) {
                path += "&cursor=" + percentEncode(cursor);
            }

            Map<String, String> headers = new LinkedHashMap<>();
            headers.put("Authorization", "Bearer " + accessToken);

            HttpResponse resp = httpRequest("GET", host, port, path, headers, null);

            if (resp.status == 429) {
                retriesCount++;
                String ra = resp.headers.get("retry-after");
                int waitSec = Integer.parseInt(ra.trim());
                Thread.sleep(waitSec * 1000L);
                continue;
            }

            if (resp.status == 503) {
                retriesCount++;
                Thread.sleep(500);
                continue;
            }

            if (resp.status == 401) {
                if (freshToken) {
                    System.out.println("ERROR " + resp.status + " " + resp.body);
                    System.exit(0);
                }
                reauthCount++;
                tokenResp = httpRequest("POST", host, port, tokenPath, tokenHeaders, tokenBody);
                if (tokenResp.status != 200) {
                    System.out.println("ERROR " + tokenResp.status + " " + tokenResp.body);
                    System.exit(0);
                }
                tokenData = (Map<String, Object>) new JsonParser(tokenResp.body).parse();
                accessToken = (String) tokenData.get("access_token");
                freshToken = true;
                continue;
            }

            if (resp.status != 200) {
                System.out.println("ERROR " + resp.status + " " + resp.body);
                System.exit(0);
            }

            // 200 OK
            freshToken = false;
            pagesCount++;

            Map<String, Object> pageData = (Map<String, Object>) new JsonParser(resp.body).parse();
            List<Object> data = (List<Object>) pageData.get("data");
            if (data != null) {
                ordersCount += data.size();
                for (Object item : data) {
                    Map<String, Object> order = (Map<String, Object>) item;
                    String status = (String) order.get("status");
                    statusCounts.merge(status, 1, Integer::sum);

                    if (!"cancelled".equals(status)) {
                        Map<String, Object> customer = (Map<String, Object>) order.get("customer");
                        String name = (String) customer.get("name");
                        String currency = (String) order.get("currency");
                        String amountStr = (String) order.get("amount");
                        long cents = parseAmountToCents(amountStr);
                        String key = name + "\0" + currency;
                        totals.merge(key, cents, Long::sum);
                    }
                }
            }

            Object nextCursor = pageData.get("next_cursor");
            if (nextCursor == null) {
                break;
            }
            cursor = (String) nextCursor;
        }

        // Output totals
        List<Map.Entry<String, Long>> totalEntries = new ArrayList<>(totals.entrySet());
        totalEntries.sort((a, b) -> {
            String[] pa = a.getKey().split("\0", 2);
            String[] pb = b.getKey().split("\0", 2);
            int cmp = compareUtf8(pa[0], pb[0]);
            if (cmp != 0) return cmp;
            return pa[1].compareTo(pb[1]);
        });

        for (Map.Entry<String, Long> entry : totalEntries) {
            String[] parts = entry.getKey().split("\0", 2);
            System.out.println("total " + parts[1] + " " + formatCents(entry.getValue()) + " " + parts[0]);
        }

        // Output statuses
        List<Map.Entry<String, Integer>> statusEntries = new ArrayList<>(statusCounts.entrySet());
        statusEntries.sort(Map.Entry.comparingByKey());
        for (Map.Entry<String, Integer> entry : statusEntries) {
            System.out.println("status " + entry.getKey() + " " + entry.getValue());
        }

        // Final line
        System.out.println("orders " + ordersCount + " pages " + pagesCount + " retries " + retriesCount + " reauth " + reauthCount);

        System.exit(0);
    }
}

import * as fs from 'fs';
import * as http from 'http';

const args = process.argv.slice(2);
const dataDir = args[0];
const baseUrl = args[1];

interface ClientConfig {
  client_id: string;
  client_secret: string;
  scope: string;
  page_size: number;
}

interface HttpResponse {
  status: number;
  headers: http.IncomingHttpHeaders;
  body: string;
}

function formUrlEncode(s: string): string {
  const bytes = Buffer.from(s, 'utf8');
  let result = '';
  for (const byte of bytes) {
    if ((byte >= 0x41 && byte <= 0x5A) ||
        (byte >= 0x61 && byte <= 0x7A) ||
        (byte >= 0x30 && byte <= 0x39) ||
        byte === 0x2D || byte === 0x2E || byte === 0x5F || byte === 0x2A) {
      result += String.fromCharCode(byte);
    } else if (byte === 0x20) {
      result += '+';
    } else {
      result += '%' + byte.toString(16).toUpperCase().padStart(2, '0');
    }
  }
  return result;
}

function encodeQueryParam(s: string): string {
  const bytes = Buffer.from(s, 'utf8');
  let result = '';
  for (const byte of bytes) {
    if ((byte >= 0x41 && byte <= 0x5A) ||
        (byte >= 0x61 && byte <= 0x7A) ||
        (byte >= 0x30 && byte <= 0x39)) {
      result += String.fromCharCode(byte);
    } else {
      result += '%' + byte.toString(16).toUpperCase().padStart(2, '0');
    }
  }
  return result;
}

const parsedUrl = new URL(baseUrl);
const hostname = parsedUrl.hostname;
const port = parsedUrl.port ? parseInt(parsedUrl.port) : (parsedUrl.protocol === 'https:' ? 443 : 80);
const hostHeader = parsedUrl.host;

function makeRequest(method: string, path: string, headers: Record<string, string>, body?: string): Promise<HttpResponse> {
  return new Promise((resolve, reject) => {
    const options: http.RequestOptions = {
      hostname,
      port,
      path,
      method,
      headers: {
        'Host': hostHeader,
        ...headers
      }
    };
    const req = http.request(options, (res) => {
      const chunks: Buffer[] = [];
      res.on('data', (chunk: Buffer) => chunks.push(chunk));
      res.on('end', () => {
        resolve({
          status: res.statusCode!,
          headers: res.headers,
          body: Buffer.concat(chunks).toString('utf8')
        });
      });
      res.on('error', reject);
    });
    req.on('error', reject);
    if (body !== undefined) {
      req.write(body);
    }
    req.end();
  });
}

function fatal(status: number, body: string): never {
  process.stdout.write('ERROR ' + status + ' ' + body + '\n');
  process.exit(0);
}

async function getToken(config: ClientConfig): Promise<string> {
  const credentials = formUrlEncode(config.client_id) + ':' + formUrlEncode(config.client_secret);
  const b64 = Buffer.from(credentials, 'utf8').toString('base64');
  const body = 'grant_type=client_credentials&scope=' + formUrlEncode(config.scope);
  const contentLength = Buffer.byteLength(body, 'utf8');

  const resp = await makeRequest('POST', baseUrl + '/oauth/token', {
    'Content-Type': 'application/x-www-form-urlencoded',
    'Authorization': 'Basic ' + b64,
    'Content-Length': contentLength.toString()
  }, body);

  if (resp.status !== 200) {
    fatal(resp.status, resp.body);
  }

  const json = JSON.parse(resp.body);
  return json.access_token;
}

function parseAmount(s: string): bigint {
  let negative = false;
  let i = 0;
  if (s[0] === '-') { negative = true; i = 1; }
  let intPart = '';
  while (i < s.length && s[i] !== '.') { intPart += s[i]; i++; }
  let fracPart = '';
  if (i < s.length && s[i] === '.') {
    i++;
    while (i < s.length) { fracPart += s[i]; i++; }
  }
  while (fracPart.length < 2) fracPart += '0';
  fracPart = fracPart.substring(0, 2);
  const value = BigInt(intPart) * 100n + BigInt(fracPart);
  return negative ? -value : value;
}

function formatAmount(cents: bigint): string {
  const negative = cents < 0n;
  const abs = negative ? -cents : cents;
  const intPart = abs / 100n;
  const fracPart = abs % 100n;
  const fracStr = fracPart.toString().padStart(2, '0');
  return (negative ? '-' : '') + intPart.toString() + '.' + fracStr;
}

function compareCodePoints(a: string, b: string): number {
  const bufA = Buffer.from(a, 'utf8');
  const bufB = Buffer.from(b, 'utf8');
  return Buffer.compare(bufA, bufB);
}

function sleep(ms: number): Promise<void> {
  return new Promise(r => setTimeout(r, ms));
}

async function main() {
  const config: ClientConfig = JSON.parse(fs.readFileSync(dataDir + '/client.json', 'utf8'));

  let accessToken = await getToken(config);
  let tokenFresh = true; // true until first successful 200 from /orders
  let cursor: string | null = null;
  let pages = 0;
  let retries = 0;
  let reauths = 0;
  let totalOrders = 0;

  const totals: Map<string, bigint> = new Map();
  const statuses: Map<string, number> = new Map();

  while (true) {
    let query = 'limit=' + config.page_size;
    if (cursor !== null) {
      query += '&cursor=' + encodeQueryParam(cursor);
    }

    let resp: HttpResponse;

    while (true) {
      resp = await makeRequest('GET', baseUrl + '/orders?' + query, {
        'Authorization': 'Bearer ' + accessToken
      });

      if (resp.status === 429) {
        retries++;
        const retryAfter = parseInt(resp.headers['retry-after'] as string, 10);
        await sleep(retryAfter * 1000);
        continue;
      }

      if (resp.status === 503) {
        retries++;
        await sleep(500);
        continue;
      }

      if (resp.status === 401) {
        if (tokenFresh) {
          fatal(401, resp.body);
        }
        accessToken = await getToken(config);
        reauths++;
        tokenFresh = true;
        continue;
      }

      if (resp.status !== 200) {
        fatal(resp.status, resp.body);
      }

      break;
    }

    pages++;
    tokenFresh = false;

    const json = JSON.parse(resp.body);
    const data = json.data as any[];
    totalOrders += data.length;

    for (const order of data) {
      const status: string = order.status;
      statuses.set(status, (statuses.get(status) || 0) + 1);

      if (status !== 'cancelled') {
        const name: string = order.customer.name;
        const currency: string = order.currency;
        const amount = parseAmount(order.amount as string);
        const key = name + '\t' + currency;
        totals.set(key, (totals.get(key) || 0n) + amount);
      }
    }

    cursor = json.next_cursor;
    if (cursor === null) break;
  }

  // Output totals
  const totalEntries: Array<[string, string, bigint]> = [];
  for (const [key, cents] of totals) {
    const tabIdx = key.indexOf('\t');
    const name = key.substring(0, tabIdx);
    const currency = key.substring(tabIdx + 1);
    totalEntries.push([name, currency, cents]);
  }
  totalEntries.sort((a, b) => {
    const cmp = compareCodePoints(a[0], b[0]);
    if (cmp !== 0) return cmp;
    return compareCodePoints(a[1], b[1]);
  });

  for (const [name, currency, cents] of totalEntries) {
    process.stdout.write('total ' + currency + ' ' + formatAmount(cents) + ' ' + name + '\n');
  }

  // Output statuses
  const statusEntries = [...statuses.entries()].sort((a, b) => a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0);
  for (const [status, count] of statusEntries) {
    process.stdout.write('status ' + status + ' ' + count + '\n');
  }

  // Final line
  process.stdout.write('orders ' + totalOrders + ' pages ' + pages + ' retries ' + retries + ' reauth ' + reauths + '\n');
}

main().catch((e) => {
  process.stdout.write('ERROR 0 ' + String(e) + '\n');
  process.exit(0);
});

