// MARK: - URL Parsing

func parseBaseURL(_ url: String) -> (host: String, port: Int, basePath: String) {
    var s = url
    if s.hasPrefix("http://") { s = String(s.dropFirst(7)) }
    else if s.hasPrefix("https://") { s = String(s.dropFirst(8)) }
    let slashIdx = s.firstIndex(of: "/")
    let hostPort: Substring
    let basePath: String
    if let idx = slashIdx {
        hostPort = s[s.startIndex..<idx]
        basePath = String(s[idx...])
    } else {
        hostPort = s[s.startIndex...]
        basePath = ""
    }
    let colonIdx = hostPort.lastIndex(of: ":")
    let host: String
    let port: Int
    if let idx = colonIdx {
        host = String(hostPort[hostPort.startIndex..<idx])
        port = Int(hostPort[hostPort.index(after: idx)...])!
    } else {
        host = String(hostPort)
        port = 80
    }
    return (host, port, basePath)
}

// MARK: - Encoding

func formURLEncode(_ s: String) -> String {
    var result = ""
    for byte in s.utf8 {
        if (byte >= 0x41 && byte <= 0x5A) ||
           (byte >= 0x61 && byte <= 0x7A) ||
           (byte >= 0x30 && byte <= 0x39) ||
           byte == 0x2D || byte == 0x2E || byte == 0x5F || byte == 0x2A {
            result.append(Character(UnicodeScalar(byte)))
        } else if byte == 0x20 {
            result.append("+")
        } else {
            result += String(format: "%%%02X", byte)
        }
    }
    return result
}

func percentEncode(_ s: String) -> String {
    var result = ""
    for byte in s.utf8 {
        if (byte >= 0x41 && byte <= 0x5A) ||
           (byte >= 0x61 && byte <= 0x7A) ||
           (byte >= 0x30 && byte <= 0x39) ||
           byte == 0x2D || byte == 0x2E || byte == 0x5F || byte == 0x7E {
            result.append(Character(UnicodeScalar(byte)))
        } else {
            result += String(format: "%%%02X", byte)
        }
    }
    return result
}

// MARK: - HTTP via raw sockets

func httpReq(host: String, port: Int, method: String, path: String,
             headers: [(String, String)], body: String?) -> (Int, [String: String], Data) {
    let sock = socket(AF_INET, SOCK_STREAM, 0)
    guard sock >= 0 else { fatalError("socket") }

    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = in_port_t(port).bigEndian
    inet_pton(AF_INET, host, &addr.sin_addr)

    let ret = withUnsafePointer(to: &addr) { p in
        p.withMemoryRebound(to: sockaddr.self, capacity: 1) { pp in
            connect(sock, pp, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    guard ret == 0 else { fatalError("connect") }

    var req = "\(method) \(path) HTTP/1.1\r\n"
    req += "Host: \(host):\(port)\r\n"
    for (k, v) in headers { req += "\(k): \(v)\r\n" }
    if let b = body {
        let bd = Data(b.utf8)
        req += "Content-Length: \(bd.count)\r\n"
        req += "\r\n"
        req += b
    } else {
        req += "\r\n"
    }

    let reqData = Data(req.utf8)
    var sent = 0
    while sent < reqData.count {
        let n = reqData.withUnsafeBytes { ptr in
            send(sock, ptr.baseAddress! + sent, reqData.count - sent, 0)
        }
        if n <= 0 { break }
        sent += n
    }

    var respData = Data()
    var buf = [UInt8](repeating: 0, count: 65536)
    while true {
        let n = recv(sock, &buf, buf.count, 0)
        if n <= 0 { break }
        respData.append(contentsOf: buf[0..<n])
    }
    close(sock)

    // Find \r\n\r\n
    let rd = [UInt8](respData)
    var headerEnd = -1
    for i in 0..<(rd.count &- 3) {
        if rd[i] == 13 && rd[i+1] == 10 && rd[i+2] == 13 && rd[i+3] == 10 {
            headerEnd = i + 4
            break
        }
    }
    guard headerEnd > 0 else { return (0, [:], Data()) }

    let headerStr = String(data: respData[0..<headerEnd], encoding: .utf8)!
    let lines = headerStr.components(separatedBy: "\r\n")
    let status = Int(lines[0].split(separator: " ")[1])!

    var hdrs: [String: String] = [:]
    for i in 1..<lines.count {
        if lines[i].isEmpty { continue }
        if let ci = lines[i].firstIndex(of: ":") {
            let k = String(lines[i][lines[i].startIndex..<ci]).lowercased()
            let v = String(lines[i][lines[i].index(after: ci)...]).trimmingCharacters(in: .whitespaces)
            hdrs[k] = v
        }
    }

    var bodyData = Data()
    let rawBody = rd[headerEnd...]

    if let te = hdrs["transfer-encoding"], te.lowercased().contains("chunked") {
        var pos = 0
        while pos < rawBody.count {
            var lineEnd = pos
            while lineEnd + 1 < rawBody.count {
                if rawBody[lineEnd] == 13 && rawBody[lineEnd + 1] == 10 { break }
                lineEnd += 1
            }
            guard lineEnd < rawBody.count else { break }
            let sizeStr = String(data: Data(rawBody[pos..<lineEnd]), encoding: .utf8)!
                .trimmingCharacters(in: .whitespaces)
            // Handle chunk extensions (e.g., "5;ext")
            let cleanSize = sizeStr.split(separator: ";").first.map(String.init) ?? sizeStr
            let chunkSize = Int(cleanSize, radix: 16) ?? 0
            if chunkSize == 0 { break }
            let chunkStart = lineEnd + 2
            let chunkEnd = min(chunkStart + chunkSize, rawBody.count)
            bodyData.append(contentsOf: rawBody[chunkStart..<chunkEnd])
            pos = chunkEnd + 2
        }
    } else if let cl = hdrs["content-length"] {
        let len = Int(cl)!
        let end = min(len, rawBody.count)
        bodyData = Data(rawBody[0..<end])
    } else {
        bodyData = Data(rawBody)
    }

    return (status, hdrs, bodyData)
}

// MARK: - Amount parsing and formatting

func parseAmount(_ s: String) -> Int64 {
    let chars = Array(s)
    var i = 0
    var negative = false
    if chars[0] == "-" { negative = true; i = 1 }
    var intPart: Int64 = 0
    while i < chars.count && chars[i] != "." {
        intPart = intPart * 10 + Int64(chars[i].wholeNumberValue!)
        i += 1
    }
    var fracPart: Int64 = 0
    if i < chars.count && chars[i] == "." {
        i += 1
        var d = 0
        while i < chars.count && d < 2 {
            fracPart = fracPart * 10 + Int64(chars[i].wholeNumberValue!)
            d += 1; i += 1
        }
        if d == 1 { fracPart *= 10 }
    }
    let cents = intPart * 100 + fracPart
    return negative ? -cents : cents
}

func formatCents(_ cents: Int64) -> String {
    let neg = cents < 0
    let ac: Int64 = neg ? -cents : cents
    let ip = ac / 100
    let fp = ac % 100
    let sign = neg ? "-" : ""
    return "\(sign)\(ip).\(String(format: "%02d", fp))"
}

// MARK: - Main

let args = CommandLine.arguments
let dataDir = args[1]
let baseUrl = args[2]

let (host, port, basePath) = parseBaseURL(baseUrl)

// Read client.json
let clientPath = dataDir + "/client.json"
let clientData = try! Data(contentsOf: URL(fileURLWithPath: clientPath))
let client = try! JSONSerialization.jsonObject(with: clientData) as! [String: Any]
let clientId = client["client_id"] as! String
let clientSecret = client["client_secret"] as! String
let scope = client["scope"] as! String
let pageSize = client["page_size"] as! Int

// Build Basic auth header (RFC 6749 §2.3.1)
let encodedId = formURLEncode(clientId)
let encodedSecret = formURLEncode(clientSecret)
let credentials = "\(encodedId):\(encodedSecret)"
let basicAuth = "Basic \(Data(credentials.utf8).base64EncodedString())"

let tokenPath = basePath + "/oauth/token"
let tokenBody = "grant_type=client_credentials&scope=\(formURLEncode(scope))"

func getToken() -> String {
    let (status, _, body) = httpReq(host: host, port: port, method: "POST", path: tokenPath,
                                     headers: [("Content-Type", "application/x-www-form-urlencoded"),
                                             ("Authorization", basicAuth)],
                                     body: tokenBody)
    guard status == 200 else {
        let bodyStr = String(data: body, encoding: .utf8) ?? ""
        print("ERROR \(status) \(bodyStr)")
        exit(0)
    }
    let json = try! JSONSerialization.jsonObject(with: body) as! [String: Any]
    return json["access_token"] as! String
}

// Get first token
var accessToken = getToken()
var tokenUsed = false

// Counters
var totalOrders = 0
var totalPages = 0
var retries = 0
var reauths = 0

// Data collection
var totals: [String: [String: Int64]] = [:] // name -> currency -> cents
var statusCounts: [String: Int] = [:]

var cursor: String? = nil

while true {
    var path = basePath + "/orders?limit=\(pageSize)"
    if let c = cursor {
        path += "&cursor=\(percentEncode(c))"
    }

    let (status, hdrs, body) = httpReq(host: host, port: port, method: "GET", path: path,
                                        headers: [("Authorization", "Bearer \(accessToken)")],
                                        body: nil)

    if status == 200 {
        totalPages += 1
        tokenUsed = true

        let json = try! JSONSerialization.jsonObject(with: body) as! [String: Any]
        let data = json["data"] as! [Any]
        let nextCursor = json["next_cursor"]

        for orderObj in data {
            let order = orderObj as! [String: Any]
            totalOrders += 1

            let statusStr = order["status"] as! String
            statusCounts[statusStr, default: 0] += 1

            if statusStr != "cancelled" {
                let customer = order["customer"] as! [String: Any]
                let name = customer["name"] as! String
                let currency = order["currency"] as! String
                let amount = parseAmount(order["amount"] as! String)
                totals[name, default: [:]][currency, default: 0] += amount
            }
        }

        if let nc = nextCursor as? String {
            cursor = nc
        } else {
            break
        }
    } else if status == 429 {
        retries += 1
        let retryAfter = Int(hdrs["retry-after"] ?? "1") ?? 1
        Thread.sleep(forTimeInterval: TimeInterval(retryAfter))
    } else if status == 503 {
        retries += 1
        Thread.sleep(forTimeInterval: 0.5)
    } else if status == 401 {
        if tokenUsed {
            reauths += 1
            accessToken = getToken()
            tokenUsed = false
        } else {
            let bodyStr = String(data: body, encoding: .utf8) ?? ""
            print("ERROR \(status) \(bodyStr)")
            exit(0)
        }
    } else {
        let bodyStr = String(data: body, encoding: .utf8) ?? ""
        print("ERROR \(status) \(bodyStr)")
        exit(0)
    }
}

// MARK: - Output

// 1. Totals: sort by name (UTF-8 bytes), then currency
var totalLines: [(String, String, Int64)] = []
for (name, currencies) in totals {
    for (currency, cents) in currencies {
        totalLines.append((name, currency, cents))
    }
}
totalLines.sort { a, b in
    let aBytes = Array(a.0.utf8)
    let bBytes = Array(b.0.utf8)
    if aBytes != bBytes { return aBytes < bBytes }
    return a.1 < b.1
}
for (name, currency, cents) in totalLines {
    print("total \(currency) \(formatCents(cents)) \(name)")
}

// 2. Status counts sorted by status
let sortedStatuses = statusCounts.keys.sorted()
for s in sortedStatuses {
    print("status \(s) \(statusCounts[s]!)")
}

// 3. Final line
print("orders \(totalOrders) pages \(totalPages) retries \(retries) reauth \(reauths)")

