func lexicographicCompare(_ a: [UInt8], _ b: [UInt8]) -> Bool {
    let minLen = min(a.count, b.count)
    for i in 0..<minLen {
        if a[i] < b[i] { return true }
        if a[i] > b[i] { return false }
    }
    return a.count < b.count
}

