    }
    var fracPart: Int64 = 0
    if i < chars.count && chars[i] == "." {
        i += 1
        var d = 0
        while i < chars.count && d < 2 {
            fracPart = fracPart * 10 + Int64(chars[i].wholeNumberValue!)
            d += 1; i += 1
        }
        if d == 1 { fracPart *= 10 }
    }
    let cents = intPart * 100 + fracPart
    return negative ? -cents : cents
}

func formatCents(_ cents: Int64) -> String {
    let neg = cents < 0
    let ac: Int64 = neg ? -cents : cents
    let ip = ac / 100
    let fp = ac % 100
    let sign = neg ? "-" : ""
    return "\(sign)\(ip).\(String(format: "%02d", fp))"
}

// MARK: - Main

let args = CommandLine.arguments
let dataDir = args[1]
let baseUrl = args[2]

let (host, port, basePath) = parseBaseURL(baseUrl)

// Read client.json
let clientPath = dataDir + "/client.json"
let clientData = try! Data(contentsOf: URL(fileURLWithPath: clientPath))
let client = try! JSONSerialization.jsonObject(with: clientData) as! [String: Any]
let clientId = client["client_id"] as! String
let clientSecret = client["client_secret"] as! String
let scope = client["scope"] as! String
let pageSize = client["page_size"] as! Int

// Build Basic auth header (RFC 6749 §2.3.1)
let encodedId = formURLEncode(clientId)
let encodedSecret = formURLEncode(clientSecret)
let credentials = "\(encodedId):\(encodedSecret)"
let basicAuth = "Basic \(Data(credentials.utf8).base64EncodedString())"

let tokenPath = basePath + "/oauth/token"
let tokenBody = "grant_type=client_credentials&scope=\(formURLEncode(scope))"

func getToken() -> String {
    let (status, _, body) = httpReq(host: host, port: port, method: "POST", path: tokenPath,
                                     headers: [("Content-Type", "application/x-www-form-urlencoded"),
                                             ("Authorization", basicAuth)],
                                     body: tokenBody)
    guard status == 200 else {
        let bodyStr = String(data: body, encoding: .utf8) ?? ""
        print("ERROR \(status) \(bodyStr)")
        exit(0)
    }
    let json = try! JSONSerialization.jsonObject(with: body) as! [String: Any]
    return json["access_token"] as! String
}

// Get first token
var accessToken = getToken()
var tokenUsed = false

// Counters
var totalOrders = 0
var totalPages = 0
var retries = 0
var reauths = 0

// Data collection
var totals: [String: [String: Int64]] = [:] // name -> currency -> cents
var statusCounts: [String: Int] = [:]

var cursor: String? = nil

while true {
    var path = basePath + "/orders?limit=\(pageSize)"
    if let c = cursor {
        path += "&cursor=\(percentEncode(c))"
    }

    let (status, hdrs, body) = httpReq(host: host, port: port, method: "GET", path: path,
                                        headers: [("Authorization", "Bearer \(accessToken)")],
                                        body: nil)

    if status == 200 {
        totalPages += 1
        tokenUsed = true

        let json = try! JSONSerialization.jsonObject(with: body) as! [String: Any]
        let data = json["data"] as! [Any]
        let nextCursor = json["next_cursor"]

        for orderObj in data {
            let order = orderObj as! [String: Any]
            totalOrders += 1

            let statusStr = order["status"] as! String
            statusCounts[statusStr, default: 0] += 1

            if statusStr != "cancelled" {
                let customer = order["customer"] as! [String: Any]
                let name = customer["name"] as! String
                let currency = order["currency"] as! String
                let amount = parseAmount(order["amount"] as! String)
                totals[name, default: [:]][currency, default: 0] += amount
            }
        }

        if let nc = nextCursor as? String {
            cursor = nc
        } else {
            break
        }
    } else if status == 429 {
        retries += 1
        let retryAfter = Int(hdrs["retry-after"] ?? "1") ?? 1
        Thread.sleep(forTimeInterval: TimeInterval(retryAfter))
    } else if status == 503 {
        retries += 1
        Thread.sleep(forTimeInterval: 0.5)
    } else if status == 401 {
        if tokenUsed {
            reauths += 1
            accessToken = getToken()
            tokenUsed = false
        } else {
            let bodyStr = String(data: body, encoding: .utf8) ?? ""
            print("ERROR \(status) \(bodyStr)")
            exit(0)
        }
    } else {
        let bodyStr = String(data: body, encoding: .utf8) ?? ""
        print("ERROR \(status) \(bodyStr)")
        exit(0)
    }
}

// MARK: - Output

// 1. Totals: sort by name (UTF-8 bytes), then currency
var totalLines: [(String, String, Int64)] = []
for (name, currencies) in totals {
    for (currency, cents) in currencies {
        totalLines.append((name, currency, cents))
    }
}
totalLines.sort { a, b in
    let aBytes = Array(a.0.utf8)
    let bBytes = Array(b.0.utf8)
    if lexicographicCompare(aBytes, bBytes) { return true }
    if lexicographicCompare(bBytes, aBytes) { return false }
    return a.1 < b.1
}
for (name, currency, cents) in totalLines {
    print("total \(currency) \(formatCents(cents)) \(name)")
}

// 2. Status counts sorted by status
let sortedStatuses = statusCounts.keys.sorted()
for s in sortedStatuses {
    print("status \(s) \(statusCounts[s]!)")
}

// 3. Final line
print("orders \(totalOrders) pages \(totalPages) retries \(retries) reauth \(reauths)")

import sys
import os
import struct
import base64

# --- Proto Schema Parsing ---

def remove_comments(text):
    result = []
    i = 0
    while i < len(text):
        if text[i] == '"':
            j = i + 1
            while j < len(text) and text[j] != '"':
                j += 1
            result.append(text[i:j+1])
            i = j + 1
        elif text[i:i+2] == '//':
            while i < len(text) and text[i] != '\n':
                i += 1
        elif text[i:i+2] == '/*':
            i += 2
            while i < len(text) and text[i:i+2] != '*/':
                i += 1
            i += 2
        else:
            result.append(text[i])
            i += 1
    return ''.join(result)

def tokenize(text):
    tokens = []
    i = 0
    while i < len(text):
        if text[i].isspace():
            i += 1
        elif text[i] == '"':
            j = i + 1
            while j < len(text) and text[j] != '"':
                j += 1
            tokens.append(('STR', text[i+1:j]))
            i = j + 1
        elif text[i] == '-' and i + 1 < len(text) and text[i+1].isdigit():
            j = i + 1
            while j < len(text) and text[j].isdigit():
                j += 1
            tokens.append(('NUM', text[i:j]))
            i = j
        elif text[i].isdigit():
            j = i
            while j < len(text) and text[j].isdigit():
                j += 1
            tokens.append(('NUM', text[i:j]))
            i = j
        elif text[i].isalpha() or text[i] == '_':
            j = i
            while j < len(text) and (text[j].isalnum() or text[j] == '_'):
                j += 1
            tokens.append(('ID', text[i:j]))
            i = j
        elif text[i] in '{};=<>[],.':
            tokens.append(('PUNCT', text[i]))
            i += 1
        else:
            i += 1
    return tokens

class FieldDef:
    def __init__(self):
        self.number = 0
        self.name = ""
        self.type = ""
        self.label = ""  # "", "repeated", "optional", "oneof_member"
        self.oneof = None
        self.is_map = False
        self.map_key_type = None
        self.map_value_type = None

class MessageDef:
    def __init__(self, name):
        self.name = name
        self.fields = []

class EnumDef:
    def __init__(self, name):
        self.name = name
        self.values = {}  # number -> name

class ProtoParser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0
        self.messages = {}
        self.enums = {}
        self.root_name = None

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def skip_to_semicolon(self):
        depth = 0
        while self.pos < len(self.tokens):
            tok = self.advance()
            if tok[0] == 'PUNCT':
                if tok[1] == '{':
                    depth += 1
                elif tok[1] == '}':
                    if depth == 0:
                        self.pos -= 1
                        return
                    depth -= 1
                elif tok[1] == ';' and depth == 0:
                    return

    def skip_options(self):
        tok = self.peek()
        if tok and tok[0] == 'PUNCT' and tok[1] == '[':
            self.advance()
            depth = 1
            while self.pos < len(self.tokens) and depth > 0:
                tok = self.advance()
                if tok[0] == 'PUNCT':
                    if tok[1] == '[':
                        depth += 1
                    elif tok[1] == ']':
                        depth -= 1

    def parse(self):
        while self.pos < len(self.tokens):
            tok = self.peek()
            if tok is None:
                break
            if tok[0] == 'ID':
                if tok[1] == 'syntax':
                    self.skip_to_semicolon()
                elif tok[1] == 'package':
                    self.skip_to_semicolon()
                elif tok[1] == 'option':
                    self.skip_to_semicolon()
                elif tok[1] == 'message':
                    self.advance()
                    name = self.advance()[1]
                    if self.root_name is None:
                        self.root_name = name
                    self.parse_message(name)
                elif tok[1] == 'enum':
                    self.advance()
                    name = self.advance()[1]
                    self.parse_enum(name)
                else:
                    self.advance()
            else:
                self.advance()

    def parse_message(self, name):
        msg = MessageDef(name)
        self.advance()  # consume {

        while self.pos < len(self.tokens):
            tok = self.peek()
            if tok is None:
                break
            if tok[0] == 'PUNCT' and tok[1] == '}':
                self.advance()
                break
            if tok[0] == 'ID':
                if tok[1] == 'option':
                    self.skip_to_semicolon()
                elif tok[1] == 'reserved':
                    self.skip_to_semicolon()
                elif tok[1] == 'message':
                    self.advance()
                    nested_name = self.advance()[1]
                    self.parse_message(nested_name)
                elif tok[1] == 'enum':
                    self.advance()
                    nested_name = self.advance()[1]
                    self.parse_enum(nested_name)
                elif tok[1] == 'oneof':
                    self.advance()
                    oneof_name = self.advance()[1]
                    self.advance()  # consume {
                    self.parse_oneof_fields(msg, oneof_name)
                elif tok[1] == 'map':
                    self.advance()  # consume 'map'
                    self.advance()  # consume '<'
                    key_type = self.advance()[1]
                    self.advance()  # consume ','
                    val_type = self.advance()[1]
                    self.advance()  # consume '>'
                    field_name = self.advance()[1]
                    self.advance()  # consume '='
                    field_num = int(self.advance()[1])
                    self.skip_options()
                    self.advance()  # consume ';'
                    field = FieldDef()
                    field.number = field_num
                    field.name = field_name
                    field.type = val_type
                    field.label = 'repeated'
                    field.is_map = True
                    field.map_key_type = key_type
                    field.map_value_type = val_type
                    msg.fields.append(field)
                elif tok[1] in ('repeated', 'optional'):
                    label = tok[1]
                    self.advance()
                    type_name = self.advance()[1]
                    field_name = self.advance()[1]
                    self.advance()  # consume '='
                    field_num = int(self.advance()[1])
                    self.skip_options()
                    self.advance()  # consume ';'
                    field = FieldDef()
                    field.number = field_num
                    field.name = field_name
                    field.type = type_name
                    field.label = label
                    msg.fields.append(field)
                else:
                    # Singular field without label
                    type_name = tok[1]
                    self.advance()
                    field_name = self.advance()[1]
                    self.advance()  # consume '='
                    field_num = int(self.advance()[1])
                    self.skip_options()
                    self.advance()  # consume ';'
                    field = FieldDef()
                    field.number = field_num
                    field.name = field_name
                    field.type = type_name
                    field.label = ''
                    msg.fields.append(field)
            else:
                self.advance()

        self.messages[name] = msg

    def parse_oneof_fields(self, msg, oneof_name):
        while self.pos < len(self.tokens):
            tok = self.peek()
            if tok is None:
                break
            if tok[0] == 'PUNCT' and tok[1] == '}':
                self.advance()
                break
            if tok[0] == 'ID':
                if tok[1] == 'option':
                    self.skip_to_semicolon()
                elif tok[1] == 'map':
                    self.advance()
                    self.advance()  # '<'
                    key_type = self.advance()[1]
                    self.advance()  # ','
                    val_type = self.advance()[1]
                    self.advance()  # '>'
                    field_name = self.advance()[1]
                    self.advance()  # '='
                    field_num = int(self.advance()[1])
                    self.skip_options()
                    self.advance()  # ';'
                    field = FieldDef()
                    field.number = field_num
                    field.name = field_name
                    field.type = val_type
                    field.label = 'repeated'
                    field.is_map = True
                    field.map_key_type = key_type
                    field.map_value_type = val_type
                    field.oneof = oneof_name
                    msg.fields.append(field)
                else:
                    type_name = tok[1]
                    self.advance()
                    field_name = self.advance()[1]
                    self.advance()  # '='
                    field_num = int(self.advance()[1])
                    self.skip_options()
                    self.advance()  # ';'
                    field = FieldDef()
                    field.number = field_num
                    field.name = field_name
                    field.type = type_name
                    field.label = 'oneof_member'
                    field.oneof = oneof_name
                    msg.fields.append(field)
            else:
                self.advance()

    def parse_enum(self, name):
        enum = EnumDef(name)
        self.advance()  # consume {

        while self.pos < len(self.tokens):
            tok = self.peek()
            if tok is None:
                break
            if tok[0] == 'PUNCT' and tok[1] == '}':
                self.advance()
                break
            if tok[0] == 'ID':
                if tok[1] == 'option':
                    self.skip_to_semicolon()
                else:
                    value_name = tok[1]
                    self.advance()
                    self.advance()  # '='
                    num_tok = self.advance()
                    num = int(num_tok[1])
                    self.skip_options()
                    self.advance()  # ';'
                    enum.values[num] = value_name
            else:
                self.advance()

        self.enums[name] = enum

# --- Wire Format Decoding ---

PACKED_TYPES = {'int32', 'int64', 'uint32', 'uint64', 'sint32', 'sint64', 'fixed32', 'fixed64', 'sfixed32', 'sfixed64', 'bool'}
# Note: enum is also packable but we need to check if the type is an enum

def is_packed_type(type_name, enums):
    return type_name in PACKED_TYPES or type_name in enums

def decode_varint(data, pos):
    result = 0
    shift = 0
    for _ in range(10):
        b = data[pos]
        pos += 1
        result |= (b & 0x7f) << shift
        if (b & 0x80) == 0:
            break
        shift += 7
    return result, pos

def skip_field(data, pos, wire_type):
    if wire_type == 0:
        _, pos = decode_varint(data, pos)
    elif wire_type == 1:
        pos += 8
    elif wire_type == 2:
        length, pos = decode_varint(data, pos)
        pos += length
    elif wire_type == 5:
        pos += 4
    elif wire_type == 3:
        while pos < len(data):
            key, pos = decode_varint(data, pos)
            inner_wire_type = key & 7
            if inner_wire_type == 4:
                break
            pos = skip_field(data, pos, inner_wire_type)
    return pos

def zigzag_decode(n):
    return (n >> 1) ^ -(n & 1)

def to_signed_32(n):
    n = n & 0xFFFFFFFF
    if n >= 0x80000000:
        n -= 0x100000000
    return n

def to_signed_64(n):
    n = n & 0xFFFFFFFFFFFFFFFF
    if n >= 0x8000000000000000:
        n -= 0x10000000000000000
    return n

def decode_scalar_value(data, pos, wire_type, type_name, enums):
    """Decode a single scalar value. Returns (value, new_pos)."""
    if type_name in ('int32', 'int64', 'uint32', 'uint64', 'bool') or type_name in enums:
        val, pos = decode_varint(data, pos)
        if type_name == 'int32':
            val = to_signed_32(val)
        elif type_name == 'int64':
            val = to_signed_64(val)
        elif type_name == 'uint32':
            val = val & 0xFFFFFFFF
        elif type_name == 'uint64':
            val = val & 0xFFFFFFFFFFFFFFFF
        elif type_name == 'bool':
            val = val != 0
        elif type_name in enums:
            val = to_signed_64(val)  # enum values are int64 range
        return val, pos
    elif type_name == 'sint32':
        val, pos = decode_varint(data, pos)
        val = zigzag_decode(val)
        return val, pos
    elif type_name == 'sint64':
        val, pos = decode_varint(data, pos)
        val = zigzag_decode(val)
        return val, pos
    elif type_name == 'fixed32':
        val = struct.unpack_from('<I', data, pos)[0]
        pos += 4
        return val, pos
    elif type_name == 'sfixed32':
        val = struct.unpack_from('<i', data, pos)[0]
        pos += 4
        return val, pos
    elif type_name == 'fixed64':
        val = struct.unpack_from('<Q', data, pos)[0]
        pos += 8
        return val, pos
    elif type_name == 'sfixed64':
        val = struct.unpack_from('<q', data, pos)[0]
        pos += 8
        return val, pos
    elif type_name == 'string':
        length, pos = decode_varint(data, pos)
        val = data[pos:pos+length].decode('utf-8')
        pos += length
        return val, pos
    elif type_name == 'bytes':
        length, pos = decode_varint(data, pos)
        val = data[pos:pos+length]
        pos += length
        return val, pos
    else:
        # Should be a message type - handled elsewhere
        raise Exception(f"Unexpected scalar type: {type_name}")

def decode_packed_values(data, pos, end, type_name, enums):
    """Decode packed repeated values from data[pos:end]."""
    values = []
    while pos < end:
        val, pos = decode_scalar_value(data, pos, 0, type_name, enums)
        values.append(val)
    return values

# --- Message Decoding ---

class DecodedMsg:
    def __init__(self):
        self.fields = {}  # field_number -> decoded value
        self.occurred = set()
        self.oneof_set = {}  # oneof_name -> field_number

def decode_message(data, msg_def, messages, enums):
    result = DecodedMsg()
    fields_by_num = {f.number: f for f in msg_def.fields}

    pos = 0
    while pos < len(data):
        key, pos = decode_varint(data, pos)
        field_number = key >> 3
        wire_type = key & 7

        if field_number not in fields_by_num:
            pos = skip_field(data, pos, wire_type)
            continue

        field = fields_by_num[field_number]

        # Handle oneof: clear other members
        if field.oneof is not None:
            if field.oneof in result.oneof_set:
                prev_num = result.oneof_set[field.oneof]
                if prev_num != field_number:
                    if prev_num in result.occurred:
                        result.occurred.discard(prev_num)
                    if prev_num in result.fields:
                        del result.fields[prev_num]
            result.oneof_set[field.oneof] = field_number

        if field.is_map:
            # Decode map entry (wire type 2)
            if wire_type != 2:
                pos = skip_field(data, pos, wire_type)
                continue
            entry_len, pos = decode_varint(data, pos)
            entry_data = data[pos:pos+entry_len]
            pos += entry_len

            # Parse entry: field 1 = key, field 2 = value
            key_val = None
            val_val = None
            epos = 0
            while epos < len(entry_data):
                ekey, epos = decode_varint(entry_data, epos)
                efield_num = ekey >> 3
                ewire_type = ekey & 7

                if efield_num == 1:
                    # key
                    key_val, epos = decode_scalar_value(entry_data, epos, ewire_type, field.map_key_type, enums)
                elif efield_num == 2:
                    # value
                    if field.map_value_type in messages:
                        if ewire_type == 2:
                            sub_len, epos = decode_varint(entry_data, epos)
                            sub_data = entry_data[epos:epos+sub_len]
                            epos += sub_len
                            val_val = decode_message(sub_data, messages[field.map_value_type], messages, enums)
                        else:
                            epos = skip_field(entry_data, epos, ewire_type)
                    else:
                        val_val, epos = decode_scalar_value(entry_data, epos, ewire_type, field.map_value_type, enums)
                else:
                    epos = skip_field(entry_data, epos, ewire_type)

            # Apply defaults
            if key_val is None:
                if field.map_key_type == 'string':
                    key_val = ""
                else:  # int32
                    key_val = 0
            if val_val is None:
                if field.map_value_type == 'string':
                    val_val = ""
                elif field.map_value_type == 'bytes':
                    val_val = b""
                elif field.map_value_type == 'bool':
                    val_val = False
                elif field.map_value_type in enums:
                    val_val = 0
                elif field.map_value_type in messages:
                    val_val = DecodedMsg()
                else:
                    val_val = 0

            if field_number not in result.fields:
                result.fields[field_number] = {}
            result.fields[field_number][key_val] = val_val
            result.occurred.add(field_number)

        elif field.label == 'repeated':
            if field.type in messages:
                # Repeated message field
                if wire_type != 2:
                    pos = skip_field(data, pos, wire_type)
                    continue
                sub_len, pos = decode_varint(data, pos)
                sub_data = data[pos:pos+sub_len]
                pos += sub_len
                sub_msg = decode_message(sub_data, messages[field.type], messages, enums)
                if field_number not in result.fields:
                    result.fields[field_number] = []
                result.fields[field_number].append(sub_msg)
            elif is_packed_type(field.type, enums) and wire_type == 2:
                # Packed
                packed_len, pos = decode_varint(data, pos)
                packed_data = data[pos:pos+packed_len]
                pos += packed_len
                packed_vals = decode_packed_values(packed_data, 0, len(packed_data), field.type, enums)
                if field_number not in result.fields:
                    result.fields[field_number] = []
                result.fields[field_number].extend(packed_vals)
            else:
                # Unpacked single element
                val, pos = decode_scalar_value(data, pos, wire_type, field.type, enums)
                if field_number not in result.fields:
                    result.fields[field_number] = []
                result.fields[field_number].append(val)
            result.occurred.add(field_number)

        elif field.type in messages:
            # Singular message field
            if wire_type != 2:
                pos = skip_field(data, pos, wire_type)
                continue
            sub_len, pos = decode_varint(data, pos)
            sub_data = data[pos:pos+sub_len]
            pos += sub_len
            new_msg = decode_message(sub_data, messages[field.type], messages, enums)

            if field_number in result.fields and field_number in result.occurred:
                # Merge
                merge_messages(result.fields[field_number], new_msg, messages[field.type], messages, enums)
            else:
                result.fields[field_number] = new_msg
            result.occurred.add(field_number)

        else:
            # Singular scalar
            val, pos = decode_scalar_value(data, pos, wire_type, field.type, enums)
            result.fields[field_number] = val
            result.occurred.add(field_number)

    return result

def merge_messages(target, source, msg_def, messages, enums):
    """Merge source into target (source is later, so it takes precedence for scalars)."""
    fields_by_num = {f.number: f for f in msg_def.fields}

    for field_number in source.occurred:
        field = fields_by_num.get(field_number)
        if field is None:
            continue

        if field.is_map:
            if field_number not in target.fields:
                target.fields[field_number] = {}
            if field_number in source.fields:
                target.fields[field_number].update(source.fields[field_number])
        elif field.label == 'repeated':
            if field_number not in target.fields:
                target.fields[field_number] = []
            if field_number in source.fields:
                target.fields[field_number].extend(source.fields[field_number])
        elif field.type in messages:
            if field_number in target.fields and field_number in target.occurred:
                merge_messages(target.fields[field_number], source.fields[field_number], messages[field.type], messages, enums)
            else:
                target.fields[field_number] = source.fields[field_number]
        else:
            target.fields[field_number] = source.fields[field_number]

        target.occurred.add(field_number)

    # Merge oneof_set
    for oneof_name, fn in source.oneof_set.items():
        if oneof_name in target.oneof_set:
            prev_fn = target.oneof_set[oneof_name]
            if prev_fn != fn:
                target.occurred.discard(prev_fn)
                if prev_fn in target.fields:
                    del target.fields[prev_fn]
        target.oneof_set[oneof_name] = fn

class ProtoParser {
    let tokens: [Token]
    var pos: Int = 0
    var topLevelMessageNames: [String] = []

    init(_ tokens: [Token]) {
        self.tokens = tokens
    }

    func peek() -> Token? {
        if pos < tokens.count { return tokens[pos] }
        return nil
    }

    func advance() -> Token {
        let t = tokens[pos]
        pos += 1
        return t
    }

    func peekIs(_ s: String) -> Bool {
        if let t = peek(), case .ident(let id) = t { return id == s }
        return false
    }

    func expectIdent() -> String {
        if case .ident(let id) = advance() { return id }
        fatalError("expected identifier")
    }

    func expectPunct(_ c: Character) {
        if case .punct(let p) = advance() { 
            if p != c { fatalError("expected \(c)") }
        } else { fatalError("expected \(c)") }
    }

    func skipToSemicolon() {
        while pos < tokens.count {
            if case .punct(";") = tokens[pos] { pos += 1; return }
            pos += 1
        }
    }

    func skipBrackets() {
        // Skip [ ... ] including nested brackets
        expectPunct("[")
        var depth = 1
        while pos < tokens.count && depth > 0 {
            if case .punct("[") = tokens[pos] { depth += 1 }
            if case .punct("]") = tokens[pos] { depth -= 1 }
            pos += 1
        }
    }

    func parse() {
        while pos < tokens.count {
            if peekIs("message") {
                let name = parseMessage()
                topLevelMessageNames.append(name)
            } else if peekIs("enum") {
                parseEnum()
            } else if peekIs("syntax") || peekIs("package") || peekIs("option") {
                skipToSemicolon()
            } else {
                pos += 1
            }
        }
        if !topLevelMessageNames.isEmpty {
            rootTypeName = topLevelMessageNames[0]
        }
    }

    func parseMessage() -> String {
        advance() // "message"
        let name = expectIdent()
        expectPunct("{")

        while pos < tokens.count {
            if case .punct("}") = tokens[pos] { pos += 1; break }

            if peekIs("message") {
                parseMessage()
            } else if peekIs("enum") {
                parseEnum()
            } else if peekIs("oneof") {
                parseOneof(name: name)
            } else if peekIs("reserved") {
                skipToSemicolon()
            } else if peekIs("option") {
                skipToSemicolon()
            } else {
                parseField(messageName: name, oneofName: nil)
            }
        }

        return name
    }

    func parseOneof(name: String) {
        advance() // "oneof"
        let oneofName = expectIdent()
        expectPunct("{")

        while pos < tokens.count {
            if case .punct("}") = tokens[pos] { pos += 1; break }

            if peekIs("option") {
                skipToSemicolon()
            } else {
                parseField(messageName: name, oneofName: oneofName)
            }
        }
    }

    func parseField(messageName: String, oneofName: String?) {
        var label = ""

        if peekIs("repeated") {
            advance()
            label = "repeated"
        } else if peekIs("optional") {
            advance()
            label = "optional"
        }

        var typeName = ""
        var isMap = false
        var mapKeyType: String? = nil
        var mapValueType: String? = nil

        if peekIs("map") {
            advance() // "map"
            expectPunct("<")
            mapKeyType = expectIdent()
            expectPunct(",")
            mapValueType = expectIdent()
            expectPunct(">")
            isMap = true
            label = "repeated" // maps are always repeated (but we'll handle them specially)
            typeName = "map"
        } else {
            typeName = expectIdent()
        }

        let fieldName = expectIdent()
        expectPunct("=")

        // field number
        var fieldNumber = 0
        if case .number(let n) = advance() {
            fieldNumber = Int(n) ?? 0
        }

        // skip field options [ ... ]
        if pos < tokens.count, case .punct("[") = tokens[pos] {
            skipBrackets()
        }

        expectPunct(";")

        let fieldDef = FieldDef(
            number: fieldNumber,
            name: fieldName,
            typeName: typeName,
            label: label,
            isMap: isMap,
            mapKeyType: mapKeyType,
            mapValueType: mapValueType,
            oneofName: oneofName
        )

        allMessages[messageName, default: MessageDef()].fields[fieldNumber] = fieldDef
    }

    func parseEnum() {
        advance() // "enum"
        let name = expectIdent()
        expectPunct("{")

        var enumDef = EnumDef()

        while pos < tokens.count {
            if case .punct("}") = tokens[pos] { pos += 1; break }

            if peekIs("option") || peekIs("reserved") {
                skipToSemicolon()
            } else {
                // VALUE_NAME = number;
                let valueName = expectIdent()
                expectPunct("=")
                var value = 0
                if case .number(let n) = advance() {
                    value = Int(n) ?? 0
                }
                // skip value options [ ... ]
                if pos < tokens.count, case .punct("[") = tokens[pos] {
                    skipBrackets()
                }
                expectPunct(";")
                enumDef.values[value] = valueName
            }
        }

        allEnums[name] = enumDef
    }
}

