/* ============ Dynamic String Buffer ============ */
typedef struct { char *data; int len, cap; } strbuf;
static void sb_init(strbuf *sb){sb->cap=512;sb->data=malloc(sb->cap);sb->len=0;sb->data[0]=0;}
static void sb_ensure(strbuf *sb,int n){if(sb->len+n>=sb->cap){while(sb->len+n>=sb->cap)sb->cap*=2;sb->data=realloc(sb->data,sb->cap);}}
static void sb_put(strbuf *sb,const char*s,int n){sb_ensure(sb,n);memcpy(sb->data+sb->len,s,n);sb->len+=n;sb->data[sb->len]=0;}
static void sb_putc(strbuf *sb,char c){sb_ensure(sb,1);sb->data[sb->len++]=c;sb->data[sb->len]=0;}
static void sb_puts(strbuf *sb,const char*s){sb_put(sb,s,(int)strlen(s));}
static char*sb_detach(strbuf *sb){sb->data[sb->len]=0;char*r=sb->data;sb->data=NULL;return r;}

/* ============ Base64 Encode ============ */
static const char b64tab[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static char*base64_encode(const unsigned char*data,int len){
    strbuf sb;sb_init(&sb);
    for(int i=0;i<len;i+=3){
        int n=((unsigned char)data[i]<<16);
        if(i+1<len)n|=(unsigned char)data[i+1]<<8;
        if(i+2<len)n|=(unsigned char)data[i+2];
        sb_putc(&sb,b64tab[(n>>18)&63]);
        sb_putc(&sb,b64tab[(n>>12)&63]);
        sb_putc(&sb,(i+1<len)?b64tab[(n>>6)&63]:'=');
        sb_putc(&sb,(i+2<len)?b64tab[n&63]:'=');
    }
    return sb_detach(&sb);
}

/* ============ Form URL Encode (for form body and Authorization) ============ */
static void form_encode(strbuf *sb,const char*s,int len){
    for(int i=0;i<len;i++){
        unsigned char c=(unsigned char)s[i];
        if(isalnum(c)||c=='-'||c=='.'||c=='_'||c=='*')sb_putc(sb,(char)c);
        else if(c==' ')sb_putc(sb,'+');
        else{sb_putc(sb,'%');sb_putc(sb,"0123456789ABCDEF"[(c>>4)&0xF]);sb_putc(sb,"0123456789ABCDEF"[c&0xF]);}
    }
}

/* ============ Percent-encode for query string (cursor) ============ */
static void query_encode(strbuf *sb,const char*s,int len){
    for(int i=0;i<len;i++){
        unsigned char c=(unsigned char)s[i];
        if(isalnum(c)||c=='-'||c=='.'||c=='_'||c=='~')sb_putc(sb,(char)c);
        else{sb_putc(sb,'%');sb_putc(sb,"0123456789ABCDEF"[(c>>4)&0xF]);sb_putc(sb,"0123456789ABCDEF"[c&0xF]);}
    }
}

/* ============ JSON Parser ============ */
typedef enum{JNULL,JBOOL,JNUM,JSTR,JARR,JOBJ}JType;
typedef struct JVal{
    JType type;
    union{
        int bval;
        double nval;
        char*sval;
        struct{struct JVal**items;int count;}arr;
        struct{char**keys;struct JVal**vals;int count;}obj;
    };
}JVal;

static const char*j_skip_ws(const char*p){while(*p&&(*p==' '||*p=='\t'||*p=='\n'||*p=='\r'))p++;return p;}

static JVal*j_parse(const char**pp);

static char*parse_json_string_raw(const char**pp){
    const char*p=*pp;
    if(*p!='"')return NULL;
    p++;
    strbuf sb;sb_init(&sb);
    while(*p&&*p!='"'){
        if(*p=='\\'){
            p++;
            switch(*p){
                case '"':sb_putc(&sb,'"');p++;break;
                case '\\':sb_putc(&sb,'\\');p++;break;
                case '/':sb_putc(&sb,'/');p++;break;
                case 'b':sb_putc(&sb,'\b');p++;break;
                case 'f':sb_putc(&sb,'\f');p++;break;
                case 'n':sb_putc(&sb,'\n');p++;break;
                case 'r':sb_putc(&sb,'\r');p++;break;
                case 't':sb_putc(&sb,'\t');p++;break;
                case 'u':{
                    p++;
                    unsigned int cp=0;
                    for(int i=0;i<4;i++){
                        cp<<=4;
                        char h=*p++;
                        if(h>='0'&&h<='9')cp|=h-'0';
                        else if(h>='a'&&h<='f')cp|=h-'a'+10;
                        else if(h>='A'&&h<='F')cp|=h-'A'+10;
                    }
                    /* surrogate pair */
                    if(cp>=0xD800&&cp<=0xDBFF&&*p=='\\'&&*(p+1)=='u'){
                        p+=2;
                        unsigned int lo=0;
                        for(int i=0;i<4;i++){
                            lo<<=4;
                            char h=*p++;
                            if(h>='0'&&h<='9')lo|=h-'0';
                            else if(h>='a'&&h<='f')lo|=h-'a'+10;
                            else if(h>='A'&&h<='F')lo|=h-'A'+10;
                        }
                        cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                    }
                    /* encode UTF-8 */
                    if(cp<0x80)sb_putc(&sb,(char)cp);
                    else if(cp<0x800){sb_putc(&sb,(char)(0xC0|(cp>>6)));sb_putc(&sb,(char)(0x80|(cp&0x3F)));}
                    else if(cp<0x10000){sb_putc(&sb,(char)(0xE0|(cp>>12)));sb_putc(&sb,(char)(0x80|((cp>>6)&0x3F)));sb_putc(&sb,(char)(0x80|(cp&0x3F)));}
                    else{sb_putc(&sb,(char)(0xF0|(cp>>18)));sb_putc(&sb,(char)(0x80|((cp>>12)&0x3F)));sb_putc(&sb,(char)(0x80|((cp>>6)&0x3F)));sb_putc(&sb,(char)(0x80|(cp&0x3F)));}
                    break;
                }
                default:sb_putc(&sb,*p);p++;break;
            }
        }else{
            sb_putc(&sb,*p);p++;
        }
    }
    if(*p=='"')p++;
    *pp=p;
    return sb_detach(&sb);
}

static JVal*j_parse(const char**pp){
    const char*p=j_skip_ws(*pp);
    JVal*v=malloc(sizeof(JVal));
    if(*p=='"'){v->type=JSTR;v->sval=parse_json_string_raw(&p);*pp=p;return v;}
    if(*p=='{'){
        p++;v->type=JOBJ;
        int cap=8;v->obj.keys=malloc(cap*sizeof(char*));v->obj.vals=malloc(cap*sizeof(JVal*));v->obj.count=0;
        p=j_skip_ws(p);
        if(*p=='}'){p++;*pp=p;return v;}
        while(1){
            p=j_skip_ws(p);
            char*key=parse_json_string_raw(&p);
            p=j_skip_ws(p);
            if(*p==':')p++;
            p=j_skip_ws(p);
            JVal*val=j_parse(&p);
            if(v->obj.count>=cap){cap*=2;v->obj.keys=realloc(v->obj.keys,cap*sizeof(char*));v->obj.vals=realloc(v->obj.vals,cap*sizeof(JVal*));}
            v->obj.keys[v->obj.count]=key;v->obj.vals[v->obj.count]=val;v->obj.count++;
            p=j_skip_ws(p);
            if(*p==','){p++;continue;}
            if(*p=='}'){p++;break;}
            break;
        }
        *pp=p;return v;
    }
    if(*p=='['){
        p++;v->type=JARR;
        int cap=8;v->arr.items=malloc(cap*sizeof(JVal*));v->arr.count=0;
        p=j_skip_ws(p);
        if(*p==']'){p++;*pp=p;return v;}
        while(1){
            p=j_skip_ws(p);
            JVal*val=j_parse(&p);
            if(v->arr.count>=cap){cap*=2;v->arr.items=realloc(v->arr.items,cap*sizeof(JVal*));}
            v->arr.items[v->arr.count++]=val;
            p=j_skip_ws(p);
            if(*p==','){p++;continue;}
            if(*p==']'){p++;break;}
            break;
        }
        *pp=p;return v;
    }
    if(*p=='t'){v->type=JBOOL;v->bval=1;p+=4;*pp=p;return v;}
    if(*p=='f'){v->type=JBOOL;v->bval=0;p+=5;*pp=p;return v;}
    if(*p=='n'){v->type=JNULL;p+=4;*pp=p;return v;}
    /* number */
    {
        const char*start=p;
        if(*p=='-')p++;
        while(isdigit(*p))p++;
        if(*p=='.'){p++;while(isdigit(*p))p++;}
        if(*p=='e'||*p=='E'){p++;if(*p=='+'||*p=='-')p++;while(isdigit(*p))p++;}
        v->type=JNUM;
        int n=(int)(p-start);
        char*tmp=malloc(n+1);memcpy(tmp,start,n);tmp[n]=0;
        v->nval=atof(tmp);free(tmp);
        *pp=p;return v;
    }
}

static JVal*j_obj_get(JVal*obj,const char*key){
    if(!obj||obj->type!=JOBJ)return NULL;
    for(int i=0;i<obj->obj.count;i++)
        if(strcmp(obj->obj.keys[i],key)==0)return obj->obj.vals[i];
    return NULL;
}

/* ============ HTTP Client ============ */
typedef struct{
    int status;
    char*body;
    char*retry_after;
    char*www_auth;
}HttpResponse;

static char*read_file(const char*path){
    FILE*f=fopen(path,"rb");
    if(!f)return NULL;
    fseek(f,0,SEEK_END);long sz=ftell(f);fseek(f,0,SEEK_SET);
    char*buf=malloc(sz+1);
    fread(buf,1,sz,f);buf[sz]=0;fclose(f);
    return buf;
}

static int parse_url(const char*url,char*host,int*port,char*path,int pathsz){
    /* http://host:port/path or http://host/path */
    const char*p=url;
    if(strncmp(p,"http://",7)==0)p+=7;
    const char*slash=strchr(p,'/');
    const char*colon=strchr(p,':');
    int hlen;
    if(slash&&colon&&colon<slash){
        hlen=(int)(colon-p);
        *port=atoi(colon+1);
    }else if(slash){
        hlen=(int)(slash-p);
        *port=80;
    }else if(colon){
        hlen=(int)(colon-p);
        *port=atoi(colon+1);
    }else{
        hlen=(int)strlen(p);
        *port=80;
    }
    memcpy(host,p,hlen);host[hlen]=0;
    if(slash)strncpy(path,slash,pathsz-1);else{path[0]='/';path[1]=0;}
    path[pathsz-1]=0;
    return 0;
}

static HttpResponse http_request(const char*method,const char*url,const char*extra_headers,const char*body){
    HttpResponse resp={0};
    resp.body=NULL;resp.retry_after=NULL;resp.www_auth=NULL;
    char host[256],path[4096];int port;
    parse_url(url,host,&port,path,4096);

    struct addrinfo hints={0},*res=NULL;
    hints.ai_family=AF_INET;hints.ai_socktype=SOCK_STREAM;
    char ports[16];snprintf(ports,sizeof(ports),"%d",port);
    if(getaddrinfo(host,ports,&hints,&res)!=0){resp.status=-1;return resp;}

    int fd=socket(res->ai_family,res->ai_socktype,res->ai_protocol);
    if(fd<0){freeaddrinfo(res);resp.status=-1;return resp;}
    if(connect(fd,res->ai_addr,res->ai_addrlen)<0){close(fd);freeaddrinfo(res);resp.status=-1;return resp;}
    freeaddrinfo(res);

    /* build request */
    strbuf req;sb_init(&req);
    sb_puts(&req,method);sb_putc(&req,' ');sb_puts(&req,path);sb_puts(&req," HTTP/1.1\r\n");
    sb_puts(&req,"Host: ");sb_puts(&req,host);
    if(port!=80){char ps[16];snprintf(ps,sizeof(ps),":%d",port);sb_puts(&req,ps);}
    sb_puts(&req,"\r\n");
    if(extra_headers)sb_puts(&req,extra_headers);
    if(body){
        sb_puts(&req,"Content-Length: ");
        char cl[32];snprintf(cl,sizeof(cl),"%d",(int)strlen(body));
        sb_puts(&req,cl);sb_puts(&req,"\r\n");
    }
    sb_puts(&req,"Connection: close\r\n\r\n");
    if(body)sb_puts(&req,body);

    /* send */
    int total=sb.len,sent=0;
    while(sent<total){
        int n=write(fd,sb.data+sent,total-sent);
        if(n<=0)break;
        sent+=n;
    }
    free(sb.data);

    /* read response */
    strbuf raw;sb_init(&raw);
    char tmp[8192];
    while(1){
        int n=read(fd,tmp,sizeof(tmp));
        if(n<=0)break;
        sb_put(&raw,tmp,n);
    }
    close(fd);

    /* parse */
    raw.data[raw.len]=0;
    char*hdr_end=strstr(raw.data,"\r\n\r\n");
    if(!hdr_end){free(raw.data);resp.status=-1;return resp;}
    int hdr_len=(int)(hdr_end-raw.data);
    char*hdrs=strndup(raw.data,hdr_len);
    char*raw_body=hdr_end+4;
    int raw_body_len=raw.len-hdr_len-4;

    /* status line */
    resp.status=atoi(hdrs+9);

    /* parse headers */
    char*line=hdrs;
    /* skip status line */
    char*nl=strstr(line,"\r\n");
    if(nl)line=nl+2;
    while(line&&*line){
        nl=strstr(line,"\r\n");
        if(!nl)nl=line+strlen(line);
        int llen=(int)(nl-line);
        if(strncasecmp(line,"Transfer-Encoding:",18)==0){
            /* chunked */
            char*val=line+18;while(*val==' ')val++;
            if(strcasestr(val,"chunked")){
                /* decode chunked body */
                strbuf out;sb_init(&out);
                char*bp=raw_body;
                int remaining=raw_body_len;
                while(remaining>0){
                    /* read hex size */
                    char*nl2=strstr(bp,"\r\n");
                    if(!nl2)break;
                    char hex[32]={0};
                    int hlen2=(int)(nl2-bp);
                    if(hlen2>31)hlen2=31;
                    memcpy(hex,bp,hlen2);
                    unsigned int csz=(unsigned int)strtoul(hex,NULL,16);
                    bp=nl2+2;remaining-=(int)(bp-raw_body);
                    if(csz==0)break;
                    if((int)csz<=remaining){
                        sb_put(&out,bp,(int)csz);
                        bp+=csz;remaining-=(int)csz;
                        /* skip \r\n after chunk data */
                        if(remaining>=2&&bp[0]=='\r'&&bp[1]=='\n'){bp+=2;remaining-=2;}
                    }else{
                        sb_put(&out,bp,remaining);
                        bp+=remaining;remaining=0;
                    }
                }
                resp.body=sb_detach(&out);
            }
        }else if(strncasecmp(line,"Content-Length:",15)==0){
            char*val=line+15;while(*val==' ')val++;
            int clen=atoi(val);
            if(!resp.body){
                if(clen<=raw_body_len){
                    resp.body=malloc(clen+1);memcpy(resp.body,raw_body,clen);resp.body[clen]=0;
                }else{
                    resp.body=malloc(raw_body_len+1);memcpy(resp.body,raw_body,raw_body_len);resp.body[raw_body_len]=0;
                }
            }
        }else if(strncasecmp(line,"Retry-After:",12)==0){
            char*val=line+12;while(*val==' ')val++;
            nl=strstr(val,"\r\n");if(!nl)nl=val+strlen(val);
            int vlen=(int)(nl-val);
            resp.retry_after=malloc(vlen+1);memcpy(resp.retry_after,val,vlen);resp.retry_after[vlen]=0;
        }else if(strncasecmp(line,"WWW-Authenticate:",17)==0){
            char*val=line+17;while(*val==' ')val++;
            nl=strstr(val,"\r\n");if(!nl)nl=val+strlen(val);
            int vlen=(int)(nl-val);
            resp.www_auth=malloc(vlen+1);memcpy(resp.www_auth,val,vlen);resp.www_auth[vlen]=0;
        }
        if(!*nl)break;
        line=nl+2;
    }

    /* if still no body and not chunked, use raw body */
    if(!resp.body){
        resp.body=malloc(raw_body_len+1);
        memcpy(resp.body,raw_body,raw_body_len);
        resp.body[raw_body_len]=0;
    }

    free(hdrs);free(raw.data);
    return resp;
}

/* ============ Amount Parsing ============ */
static int64_t parse_amount(const char*s){
    int64_t cents=0;
    int neg=0;
    const char*p=s;
    if(*p=='-'){neg=1;p++;}
    /* integer part */
    int64_t ipart=0;
    while(isdigit(*p)){ipart=ipart*10+(*p-'0');p++;}
    cents=ipart*100;
    /* fractional part */
    if(*p=='.'){
        p++;
        int fpart=0,fdigits=0;
        while(isdigit(*p)&&fdigits<2){fpart=fpart*10+(*p-'0');fdigits++;p++;}
        while(fdigits<2){fpart*=10;fdigits++;}
        cents+=fpart;
    }
    return neg?-cents:cents;
}

static void format_cents(int64_t cents,char*out,int outsz){
    if(cents<0){
        snprintf(out,outsz,"-%lld.%02lld",(long long)((-cents)/100),(long long)((-cents)%100));
    }else{
        snprintf(out,outsz,"%lld.%02lld",(long long)(cents/100),(long long)(cents%100));
    }
}

/* ============ Totals / Status tracking ============ */
typedef struct{char*name;char*currency;int64_t cents;}TotalEntry;
typedef struct{char*status;int count;}StatusEntry;

static TotalEntry*totals=NULL;static int total_count=0,total_cap=0;
static StatusEntry*statuses=NULL;static int status_count=0,status_cap=0;

static void add_total(const char*name,const char*currency,int64_t cents){
    for(int i=0;i<total_count;i++){
        if(strcmp(totals[i].name,name)==0&&strcmp(totals[i].currency,currency)==0){
            totals[i].cents+=cents;return;
        }
    }
    if(total_count>=total_cap){total_cap=total_cap?total_cap*2:64;totals=realloc(totals,total_cap*sizeof(TotalEntry));}
    totals[total_count].name=strdup(name);
    totals[total_count].currency=strdup(currency);
    totals[total_count].cents=cents;
    total_count++;
}

static void add_status(const char*status){
    for(int i=0;i<status_count;i++){
        if(strcmp(statuses[i].status,status)==0){statuses[i].count++;return;}
    }
    if(status_count>=status_cap){status_cap=status_cap?status_cap*2:16;statuses=realloc(statuses,status_cap*sizeof(StatusEntry));}
    statuses[status_count].status=strdup(status);
    statuses[status_count].count=1;
    status_count++;
}

static int cmp_total(const void*a,const void*b){
    TotalEntry*ta=(TotalEntry*)a,*tb=(TotalEntry*)b;
    int c=strcmp(ta->name,tb->name);
    if(c)return c;
    return strcmp(ta->currency,tb->currency);
}
static int cmp_status(const void*a,const void*b){
    return strcmp(((StatusEntry*)a)->status,((StatusEntry*)b)->status);
}

/* ============ Fatal error ============ */
static void fatal(int status,const char*body){
    printf("ERROR %d %s\n",status,body?body:"");
    exit(0);
}

/* ============ Main ============ */
int main(int argc,char**argv){
    if(argc<3){return 1;}
    char*data_dir=argv[1];
    char*base_url=argv[2];

    /* Read client.json */
    char cpath[4096];
    snprintf(cpath,sizeof(cpath),"%s/client.json",data_dir);
    char*cjson=read_file(cpath);
    if(!cjson){printf("ERROR 0 \n");return 0;}

    const char*jp=cjson;
    JVal*cfg=j_parse(&jp);

    JVal*jcid=j_obj_get(cfg,"client_id");
    JVal*jsec=j_obj_get(cfg,"client_secret");
    JVal*jscope=j_obj_get(cfg,"scope");
    JVal*jps=j_obj_get(cfg,"page_size");

    const char*client_id=jcid->sval;
    const char*client_secret=jsec->sval;
    const char*scope=jscope->sval;
    int page_size=(int)jps->nval;

    /* Build Authorization header for token endpoint */
    strbuf cred;sb_init(&cred);
    form_encode(&cred,client_id,(int)strlen(client_id));
    sb_putc(&cred,':');
    form_encode(&cred,client_secret,(int)strlen(client_secret));
    char*cred_str=sb_detach(&cred);
    char*b64=base64_encode((unsigned char*)cred_str,(int)strlen(cred_str));
    free(cred_str);

    /* Build token URL */
    char token_url[4096];
    snprintf(token_url,sizeof(token_url),"%s/oauth/token",base_url);

    /* Build token request body */
    strbuf tok_body;sb_init(&tok_body);
    sb_puts(&tok_body,"grant_type=client_credentials&scope=");
    form_encode(&tok_body,scope,(int)strlen(scope));
    char*body_str=sb_detach(&tok_body);

    /* Build token request headers */
    strbuf tok_hdr;sb_init(&tok_hdr);
    sb_puts(&tok_hdr,"Content-Type: application/x-www-form-urlencoded\r\n");
    sb_puts(&tok_hdr,"Authorization: Basic ");sb_puts(&tok_hdr,b64);sb_puts(&tok_hdr,"\r\n");
    char*hdr_str=sb_detach(&tok_hdr);

    /* Step 1: get token */
    HttpResponse tok_resp=http_request("POST",token_url,hdr_str,body_str);
    free(hdr_str);free(body_str);free(b64);

    if(tok_resp.status!=200)fatal(tok_resp.status,tok_resp.body);

    const char*tp=tok_resp.body;
    JVal*tok_json=j_parse(&tp);
    JVal*jat=j_obj_get(tok_json,"access_token");
    if(!jat||jat->type!=JSTR)fatal(0,"");
    char*access_token=strdup(jat->sval);
    free(tok_resp.body);free(tok_resp.retry_after);free(tok_resp.www_auth);

    /* Counters */
    int orders_received=0,pages_ok=0,retries=0,reauth=0;

    /* Step 2: fetch orders */
    char*cursor=NULL;
    int token_used_ok=0; /* whether current token has been used successfully on /orders */

    while(1){
        /* Build orders URL */
        char orders_url[8192];
        if(cursor){
            strbuf q;sb_init(&q);
            snprintf(orders_url,sizeof(orders_url),"%s/orders?limit=%d&cursor=",base_url,page_size);
            sb_init(&q);
            query_encode(&q,cursor,(int)strlen(cursor));
            char*enc=sb_detach(&q);
            snprintf(orders_url,sizeof(orders_url),"%s/orders?limit=%d&cursor=%s",base_url,page_size,enc);
            free(enc);
        }else{
            snprintf(orders_url,sizeof(orders_url),"%s/orders?limit=%d",base_url,page_size);
        }

        /* Build auth header */
        strbuf ah;sb_init(&ah);
        sb_puts(&ah,"Authorization: Bearer ");sb_puts(&ah,access_token);sb_puts(&ah,"\r\n");
        char*auth_hdr=sb_detach(&ah);

        HttpResponse resp=http_request("GET",orders_url,auth_hdr,NULL);
        free(auth_hdr);

        if(resp.status==429){
            retries++;
            int wait=1;
            if(resp.retry_after)wait=atoi(resp.retry_after);
            free(resp.body);free(resp.retry_after);free(resp.www_auth);
            sleep(wait);
            continue;
        }
        if(resp.status==503){
            retries++;
            free(resp.body);free(resp.retry_after);free(resp.www_auth);
            usleep(500000);
            continue;
        }
        if(resp.status==401){
            if(!token_used_ok){
                /* first request with this token got 401 → fatal */
                fatal(401,resp.body);
            }
            /* re-auth */
            reauth++;
            free(resp.body);free(resp.retry_after);free(resp.www_auth);

            /* get new token */
            strbuf cred2;sb_init(&cred2);
            form_encode(&cred2,client_id,(int)strlen(client_id));
            sb_putc(&cred2,':');
            form_encode(&cred2,client_secret,(int)strlen(client_secret));
            char*cred2_str=sb_detach(&cred2);
            char*b642=base64_encode((unsigned char*)cred2_str,(int)strlen(cred2_str));
            free(cred2_str);

            strbuf tok_hdr2;sb_init(&tok_hdr2);
            sb_puts(&tok_hdr2,"Content-Type: application/x-www-form-urlencoded\r\n");
            sb_puts(&tok_hdr2,"Authorization: Basic ");sb_puts(&tok_hdr2,b642);sb_puts(&tok_hdr2,"\r\n");
            char*hdr2=sb_detach(&tok_hdr2);

            strbuf tok_body2;sb_init(&tok_body2);
            sb_puts(&tok_body2,"grant_type=client_credentials&scope=");
            form_encode(&tok_body2,scope,(int)strlen(scope));
            char*body2=sb_detach(&tok_body2);

            HttpResponse tok_resp2=http_request("POST",token_url,hdr2,body2);
            free(hdr2);free(body2);free(b642);

            if(tok_resp2.status!=200)fatal(tok_resp2.status,tok_resp2.body);
            const char*tp2=tok_resp2.body;
            JVal*tok_json2=j_parse(&tp2);
            JVal*jat2=j_obj_get(tok_json2,"access_token");
            if(!jat2||jat2->type!=JSTR)fatal(0,"");
            free(access_token);
            access_token=strdup(jat2->sval);
            free(tok_resp2.body);free(tok_resp2.retry_after);free(tok_resp2.www_auth);
            token_used_ok=0;
            continue;
        }
        if(resp.status!=200){
            fatal(resp.status,resp.body);
        }

        /* 200 OK */
        token_used_ok=1;
        pages_ok++;

        const char*bp=resp.body;
        JVal*page=j_parse(&bp);
        JVal*jdata=j_obj_get(page,"data");
        JVal*jnext=j_obj_get(page,"next_cursor");

        if(jdata&&jdata->type==JARR){
            for(int i=0;i<jdata->arr.count;i++){
                JVal*ord=jdata->arr.items[i];
                orders_received++;

                JVal*jstatus=j_obj_get(ord,"status");
                const char*status_str=jstatus&&jstatus->type==JSTR?jstatus->sval:"";
                add_status(status_str);

                if(strcmp(status_str,"cancelled")!=0){
                    JVal*jcust=j_obj_get(ord,"customer");
                    JVal*jname=jcust?j_obj_get(jcust,"name"):NULL;
                    JVal*jcurrency=j_obj_get(ord,"currency");
                    JVal*jamount=j_obj_get(ord,"amount");
                    if(jname&&jname->type==JSTR&&jcurrency&&jcurrency->type==JSTR&&jamount&&jamount->type==JSTR){
                        int64_t cents=parse_amount(jamount->sval);
                        add_total(jname->sval,jcurrency->sval,cents);
                    }
                }
            }
        }

        free(resp.body);free(resp.retry_after);free(resp.www_auth);

        if(jnext&&jnext->type==JSTR){
            free(cursor);
            cursor=strdup(jnext->sval);
        }else{
            /* next_cursor is null or missing → last page */
            free(cursor);cursor=NULL;
            break;
        }
    }

    /* Output */
    qsort(totals,total_count,sizeof(TotalEntry),cmp_total);
    qsort(statuses,status_count,sizeof(StatusEntry),cmp_status);

    for(int i=0;i<total_count;i++){
        char amt[64];
        format_cents(totals[i].cents,amt,sizeof(amt));
        printf("total %s %s %s\n",totals[i].currency,amt,totals[i].name);
    }
    for(int i=0;i<status_count;i++){
        printf("status %s %d\n",statuses[i].status,statuses[i].count);
    }
    printf("orders %d pages %d retries %d reauth %d\n",orders_received,pages_ok,retries,reauth);

    return 0;
}

