]);

// Tokenizer
type Token = { type: 'id' | 'num' | 'str' | 'punct', value: string };

function tokenize(input: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < input.length) {
    // Skip whitespace
    if (/\s/.test(input[i])) { i++; continue; }
    // Comments
    if (input[i] === '/' && i + 1 < input.length) {
      if (input[i + 1] === '/') {
        while (i < input.length && input[i] !== '\n') i++;
        continue;
      }
      if (input[i + 1] === '*') {
        i += 2;
        while (i + 1 < input.length && !(input[i] === '*' && input[i + 1] === '/')) i++;
        i += 2;
        continue;
      }
    }
    // String literal
    if (input[i] === '"') {
      i++;
      let s = '';
      while (i < input.length && input[i] !== '"') {
        if (input[i] === '\\') {
          s += input[i] + input[i + 1];
          i += 2;
        } else {
          s += input[i];
          i++;
        }
      }
      i++; // skip closing quote
      tokens.push({ type: 'str', value: s });
      continue;
    }
    // Numbers (including negative)
    if (/[0-9]/.test(input[i]) || (input[i] === '-' && i + 1 < input.length && /[0-9]/.test(input[i + 1]))) {
      let s = '';
      if (input[i] === '-') { s += '-'; i++; }
      while (i < input.length && /[0-9.eExXa-fA-F]/.test(input[i])) { s += input[i]; i++; }
      tokens.push({ type: 'num', value: s });
      continue;
    }
    // Identifiers
    if (/[a-zA-Z_]/.test(input[i])) {
      let s = '';
      while (i < input.length && /[a-zA-Z0-9_]/.test(input[i])) { s += input[i]; i++; }
      tokens.push({ type: 'id', value: s });
      continue;
    }
    // Punctuation
    if ('{};=<>()[],.'.includes(input[i])) {
      tokens.push({ type: 'punct', value: input[i] });
      i++;
      continue;
    }
    // Skip unknown characters
    i++;
  }
  return tokens;
}

class ProtoParser {
  tokens: Token[];
  pos: number;

  constructor(tokens: Token[]) {
    this.tokens = tokens;
    this.pos = 0;
  }

  peek(): Token | null {
    if (this.pos < this.tokens.length) return this.tokens[this.pos];
    return null;
  }

  next(): Token {
    return this.tokens[this.pos++];
  }

  expect(type: string, value?: string): Token {
    const t = this.next();
    if (t.type !== type || (value !== undefined && t.value !== value)) {
      throw new Error(`Expected ${type} ${value}, got ${t.type} ${t.value}`);
    }
    return t;
  }

