    char name[MAX_NAME];
    struct { int number; char name[MAX_NAME]; } values[MAX_EV];
    int nvalues;
} EnumDef;

static MsgDef g_msgs[MAX_MSG];
static int g_nmsgs;
static EnumDef g_enums[MAX_ENM];
static int g_nenums;

/* ========== Parser ========== */

static const char *src;
static int spos, slen;

static void skipws(void) {
    while (spos < slen) {
        char c = src[spos];
        if (c==' '||c=='\t'||c=='\r'||c=='\n') { spos++; }
        else if (c=='/' && spos+1<slen) {
            if (src[spos+1]=='/') { spos+=2; while(spos<slen && src[spos]!='\n') spos++; }
            else if (src[spos+1]=='*') { spos+=2; while(spos+1<slen && !(src[spos]=='*'&&src[spos+1]=='/')) spos++; if(spos+1<slen) spos+=2; }
            else break;
        } else break;
    }
}

static int isid(char c) { return isalnum((unsigned char)c)||c=='_'; }

static void rdid(char *b, int mx) {
    int j=0; while(spos<slen&&isid(src[spos])&&j<mx-1) b[j++]=src[spos++]; b[j]=0;
}

static void rdstr(char *b, int mx) {
    spos++; int j=0; while(spos<slen&&src[spos]!='"'&&j<mx-1) b[j++]=src[spos++]; if(spos<slen) spos++; b[j]=0;
}

static int64_t rdint(void) {
    int neg=0; if(spos<slen&&src[spos]=='-'){neg=1;spos++;}
    int64_t v=0; while(spos<slen&&isdigit(src[spos])) v=v*10+(src[spos++]-'0');
    return neg?-v:v;
}

static void skiptosemi(void) {
    while(spos<slen) {
        if(src[spos]=='"'){spos++;while(spos<slen&&src[spos]!='"')spos++;if(spos<slen)spos++;}
        else if(src[spos]==';'){spos++;return;}
        else spos++;
    }
}

static void skipbrackets(void) {
    spos++; int d=1;
    while(spos<slen&&d>0){
        if(src[spos]=='"'){spos++;while(spos<slen&&src[spos]!='"')spos++;if(spos<slen)spos++;}
        else if(src[spos]=='['){d++;spos++;}
        else if(src[spos]==']'){d--;spos++;}
        else spos++;
    }
}

static void skipopt(void) { skiptosemi(); }

static int kw(const char *k) {
    int kl=strlen(k);
    if(spos+kl>slen) return 0;
    if(memcmp(src+spos,k,kl)!=0) return 0;
    if(spos+kl<slen && isid(src[spos+kl])) return 0;
    spos+=kl;
    return 1;
}

static void parse_enum_body(int ei) {
    skipws(); if(spos<slen&&src[spos]=='{') spos++;
    while(1){
        skipws(); if(spos>=slen) break;
        if(src[spos]=='}'){spos++;break;}
        if(kw("reserved")){skiptosemi();continue;}
        if(kw("option")){skipopt();continue;}
        char nm[MAX_NAME]; rdid(nm,MAX_NAME); skipws();
        if(spos<slen&&src[spos]=='=')spos++; skipws();
        int64_t v=rdint(); skipws();
        if(spos<slen&&src[spos]=='[')skipbrackets();
        skipws(); if(spos<slen&&src[spos]==';')spos++;
        if(g_enums[ei].nvalues<MAX_EV){
            g_enums[ei].values[g_enums[ei].nvalues].number=(int)v;
            strncpy(g_enums[ei].values[g_enums[ei].nvalues].name,nm,MAX_NAME-1);
            g_enums[ei].nvalues++;
        }
    }
}

static void parse_msg_body(int mi) {
    skipws(); if(spos<slen&&src[spos]=='{') spos++;
    while(1){
        skipws(); if(spos>=slen) break;
        if(src[spos]=='}'){spos++;break;}
        if(kw("reserved")){skiptosemi();continue;}
        if(kw("option")){skipopt();continue;}
        if(kw("oneof")){
            skipws(); char on[MAX_NAME]; rdid(on,MAX_NAME);
            int oi=g_msgs[mi].noneofs; if(oi<MAX_ONEOF){strncpy(g_msgs[mi].oneofs[oi],on,MAX_NAME-1);g_msgs[mi].noneofs++;}
            skipws(); if(spos<slen&&src[spos]=='{')spos++;
            while(1){
                skipws(); if(spos>=slen)break;
                if(src[spos]=='}'){spos++;break;}
                if(kw("option")){skipopt();continue;}
                if(kw("reserved")){skiptosemi();continue;}
                if(g_msgs[mi].nfields<MAX_FLD){
                    FieldDef *fd=&g_msgs[mi].fields[g_msgs[mi].nfields];
                    memset(fd,0,sizeof(*fd));
                    fd->oneof_idx=oi; fd->label=3; fd->oneof_idx=oi;
                    rdid(fd->type_name,MAX_NAME); skipws();
                    rdid(fd->name,MAX_NAME); skipws();
                    if(spos<slen&&src[spos]=='=')spos++; skipws();
                    fd->number=(int)rdint(); skipws();
                    if(spos<slen&&src[spos]=='[')skipbrackets();
                    skipws(); if(spos<slen&&src[spos]==';')spos++;
                    g_msgs[mi].nfields++;
                }
            }
            continue;
        }
        if(kw("message")){
            skipws(); char mn[MAX_NAME]; rdid(mn,MAX_NAME);
            int ni=g_nmsgs; if(ni<MAX_MSG){strncpy(g_msgs[ni].name,mn,MAX_NAME-1);g_msgs[ni].nfields=0;g_msgs[ni].noneofs=0;g_nmsgs++;}
            parse_msg_body(ni); continue;
        }
        if(kw("enum")){
            skipws(); char en[MAX_NAME]; rdid(en,MAX_NAME);
            int ni=g_nenums; if(ni<MAX_ENM){strncpy(g_enums[ni].name,en,MAX_NAME-1);g_enums[ni].nvalues=0;g_nenums++;}
            parse_enum_body(ni); continue;
        }
        if(kw("map")){
            skipws(); if(spos<slen&&src[spos]=='<')spos++; skipws();
            char kn[MAX_NAME]; rdid(kn,MAX_NAME); skipws();
            if(spos<slen&&src[spos]==',')spos++; skipws();
            char vn[MAX_NAME]; rdid(vn,MAX_NAME); skipws();
            if(spos<slen&&src[spos]=='>')spos++; skipws();
            if(g_msgs[mi].nfields<MAX_FLD){
                FieldDef *fd=&g_msgs[mi].fields[g_msgs[mi].nfields];
                memset(fd,0,sizeof(*fd));
                fd->is_map=1; fd->label=1; fd->oneof_idx=-1;
                strncpy(fd->map_key_name,kn,MAX_NAME-1);
                strncpy(fd->map_val_name,vn,MAX_NAME-1);
                rdid(fd->name,MAX_NAME); skipws();
                if(spos<slen&&src[spos]=='=')spos++; skipws();
                fd->number=(int)rdint(); skipws();
                if(spos<slen&&src[spos]=='[')skipbrackets();
                skipws(); if(spos<slen&&src[spos]==';')spos++;
                g_msgs[mi].nfields++;
            }
            continue;
        }
        // regular field
        int lab=0;
        if(kw("repeated")){lab=1;skipws();}
        else if(kw("optional")){lab=2;skipws();}
        char tn[MAX_NAME],fn[MAX_NAME];
        rdid(tn,MAX_NAME); skipws(); rdid(fn,MAX_NAME); skipws();
        if(spos<slen&&src[spos]=='=')spos++; skipws();
        int fnum=(int)rdint(); skipws();
        if(spos<slen&&src[spos]=='[')skipbrackets();
        skipws(); if(spos<slen&&src[spos]==';')spos++;
        if(g_msgs[mi].nfields<MAX_FLD){
            FieldDef *fd=&g_msgs[mi].fields[g_msgs[mi].nfields];
            memset(fd,0,sizeof(*fd));
            fd->number=fnum; strncpy(fd->name,fn,MAX_NAME-1); strncpy(fd->type_name,tn,MAX_NAME-1);
            fd->label=lab; fd->oneof_idx=-1;
            g_msgs[mi].nfields++;
        }
    }
}

static void parse_schema(void) {
    g_nmsgs=0; g_nenums=0;
    while(1){
        skipws(); if(spos>=slen) break;
        if(kw("syntax")){skiptosemi();continue;}
        if(kw("package")){skiptosemi();continue;}
        if(kw("option")){skipopt();continue;}
        if(kw("message")){
            skipws(); char mn[MAX_NAME]; rdid(mn,MAX_NAME);
            int ni=g_nmsgs; if(ni<MAX_MSG){strncpy(g_msgs[ni].name,mn,MAX_NAME-1);g_msgs[ni].nfields=0;g_msgs[ni].noneofs=0;g_nmsgs++;}
            parse_msg_body(ni); continue;
        }
        if(kw("enum")){
            skipws(); char en[MAX_NAME]; rdid(en,MAX_NAME);
            int ni=g_nenums; if(ni<MAX_ENM){strncpy(g_enums[ni].name,en,MAX_NAME-1);g_enums[ni].nvalues=0;g_nenums++;}
            parse_enum_body(ni); continue;
        }
        spos++; // skip unknown
    }
}

/* ========== Type Resolution ========== */

static FieldType resov(const char *n, int *mi, int *ei) {
    if(!strcmp(n,"int32"))return T_INT32;
    if(!strcmp(n,"int64"))return T_INT64;
    if(!strcmp(n,"uint32"))return T_UINT32;
    if(!strcmp(n,"uint64"))return T_UINT64;
    if(!strcmp(n,"sint32"))return T_SINT32;
    if(!strcmp(n,"sint64"))return T_SINT64;
    if(!strcmp(n,"bool"))return T_BOOL;
    if(!strcmp(n,"string"))return T_STRING;
    if(!strcmp(n,"bytes"))return T_BYTES;
    if(!strcmp(n,"fixed32"))return T_FIXED32;
    if(!strcmp(n,"fixed64"))return T_FIXED64;
    if(!strcmp(n,"sfixed32"))return T_SFIXED32;
    if(!strcmp(n,"sfixed64"))return T_SFIXED64;
    for(int i=0;i<g_nmsgs;i++) if(!strcmp(n,g_msgs[i].name)){if(mi)*mi=i;return T_MESSAGE;}
    for(int i=0;i<g_nenums;i++) if(!strcmp(n,g_enums[i].name)){if(ei)*ei=i;return T_ENUM;}
    return T_INT32;
}

static void resolve_all(void) {
    for(int mi=0;mi<g_nmsgs;mi++){
        for(int fi=0;fi<g_msgs[mi].nfields;fi++){
            FieldDef *fd=&g_msgs[mi].fields[fi];
            if(fd->is_map){
                fd->map_kt=resov(fd->map_key_name,NULL,NULL);
                fd->map_vt=resov(fd->map_val_name,&fd->map_msg_idx,&fd->map_enum_idx);
            } else {
                fd->ftype=resov(fd->type_name,&fd->msg_idx,&fd->enum_idx);
            }
        }
    }
}

/* ========== Binary Reading ========== */

static int read_varint(const unsigned char *d, int len, int pos, uint64_t *out) {
    uint64_t v=0; int shift=0;
    for(int i=0;i<10&&pos<len;i++){
        uint64_t b=d[pos++];
        v|=(b&0x7f)<<shift;
        if(!(b&0x80)) break;
        shift+=7;
    }
    *out=v;
    return pos;
}

static int skip_val(const unsigned char *d, int len, int pos, int wt) {
    switch(wt){
        case 0: while(pos<len&&(d[pos]&0x80))pos++; pos++; break;
        case 1: pos+=8; break;
        case 2: {uint64_t sl;pos=read_varint(d,len,pos,&sl);pos+=(int)sl;} break;
        case 5: pos+=4; break;
        case 3: {int dep=1;while(pos<len&&dep>0){uint64_t k;pos=read_varint(d,len,pos,&k);int w=(int)(k&7);if(w==4)dep--;else if(w==3)dep++;else pos=skip_val(d,len,pos,w);}} break;
        case 4: break;
    }
    return pos;
}

static int is_packed(FieldType t) {
    return t==T_INT32||t==T_INT64||t==T_UINT32||t==T_UINT64||t==T_SINT32||t==T_SINT64||
           t==T_BOOL||t==T_FIXED32||t==T_FIXED64||t==T_SFIXED32||t==T_SFIXED64||t==T_ENUM;
}

/* ========== Decoded Message Structure ========== */

typedef struct {
    int64_t i64;
    uint64_t u64;
    bool b;
    unsigned char *bytes;
    int blen;
    struct DecMsg *msg;
} Val;

typedef struct { Val key; Val value; } MapEntry;

typedef struct DecMsg {
    int msg_idx;
    int nfields;
    struct {
        int present;
        Val val;
        Val *elems; int nelems; int ecap;
        MapEntry *maps; int nmaps; int mcap;
    } f[MAX_FLD];
    int oneof_set[MAX_ONEOF];
} DecMsg;

static DecMsg *new_decmsg(int mi) {
    DecMsg *dm = calloc(1, sizeof(DecMsg));
    dm->msg_idx = mi;
    dm->nfields = g_msgs[mi].nfields;
    for(int i=0;i<MAX_ONEOF;i++) dm->oneof_set[i]=-1;
    return dm;
}

static void free_val(Val *v) {
    if(v->bytes) free(v->bytes);
    if(v->msg) free_decmsg(v->msg); // forward decl issue
}

// Hmm, I need forward declarations. Let me restructure.

static void free_decmsg(DecMsg *dm) {
    for(int i=0;i<dm->nfields;i++){
        if(dm->f[i].val.bytes) free(dm->f[i].val.bytes);
        if(dm->f[i].val.msg) free_decmsg(dm->f[i].val.msg);
        for(int j=0;j<dm->f[i].nelems;j++){
            if(dm->f[i].elems[j].bytes) free(dm->f[i].elems[j].bytes);
            if(dm->f[i].elems[j].msg) free_decmsg(dm->f[i].elems[j].msg);
        }
        if(dm->f[i].elems) free(dm->f[i].elems);
        for(int j=0;j<dm->f[i].nmaps;j++){
            if(dm->f[i].maps[j].key.bytes) free(dm->f[i].maps[j].key.bytes);
            if(dm->f[i].maps[j].value.bytes) free(dm->f[i].maps[j].value.bytes);
            if(dm->f[i].maps[j].value.msg) free_decmsg(dm->f[i].maps[j].value.msg);
        }
        if(dm->f[i].maps) free(dm->f[i].maps);
    }
    free(dm);
}

def parse(pattern):
    pos = [0]
    group_count = [0]

    def cur():
        return pattern[pos[0]] if pos[0] < len(pattern) else None

    def adv():
        pos[0] += 1

    def parse_regex():
        branches = [parse_branch()]
        while cur() == '|':
            adv()
            branches.append(parse_branch())
        if len(branches) == 1:
            return branches[0]
        return Alt(branches)

    def parse_branch():
        pieces = []
        while cur() is not None and cur() not in '|)':
            pieces.append(parse_piece())
        if len(pieces) == 0:
            return None  # empty branch
        if len(pieces) == 1:
            return pieces[0]
        return Concat(pieces)

    def parse_piece():
        atom = parse_atom()
        if cur() in '*+?{':
            quant = parse_quantifier()
            return Repeat(atom, *quant)
        return atom

    def parse_atom():
        c = cur()
        if c == '(':
            adv()
            if cur() == '?' and pos[0]+1 < len(pattern) and pattern[pos[0]+1] == ':':
                adv(); adv()  # consume (?:
                inner = parse_regex()
                assert cur() == ')'
                adv()
                return Group(inner, 0)  # non-capturing
            else:
                group_count[0] += 1
                num = group_count[0]
                inner = parse_regex()
                assert cur() == ')'
                adv()
                return Group(inner, num)
        elif c == '.':
            adv()
            return Any()
        elif c == '^':
            adv()
            return Bol()
        elif c == '$':
            adv()
            return Eol()
        elif c == '[':
            return parse_class()
        elif c == '\\':
            adv()
            c2 = cur()
            adv()
            if c2 in 'dDwWsS':
                return ClassEsc(c2)
            else:
                return Char(c2)
        else:
            adv()
            return Char(c)

    def parse_quantifier():
        c = cur()
        greedy = True
        if c == '*':
            adv()
            min_val, max_val = 0, None
        elif c == '+':
            adv()
            min_val, max_val = 1, None
        elif c == '?':
            adv()
            min_val, max_val = 0, 1
        elif c == '{':
            adv()
            # parse m
            m_start = pos[0]
            while cur() is not None and cur().isdigit():
                adv()
            m = int(pattern[m_start:pos[0]])
            if cur() == ',':
                adv()
                if cur() == '}':
                    n = None
                else:
                    n_start = pos[0]
                    while cur() is not None and cur().isdigit():
                        adv()
                    n = int(pattern[n_start:pos[0]])
            else:
                n = m
            assert cur() == '}'
            adv()
            min_val, max_val = m, n
        # Check for lazy '?'
        if cur() == '?':
            adv()
            greedy = False
        return min_val, max_val, greedy

    def parse_class():
        adv()  # consume '['
        negated = False
        if cur() == '^':
            negated = True
            adv()
        items = []
        # Parse items until ']'
        # First char can be ']' (literal)
        # Actually, the problem says "An item is a single character, a range x-y, or one of the six class escapes"
        # And "Inside a class the characters \, ], [, and - (except as the range dash) always appear escaped"
        # So ']' always appears as '\]' inside a class (except possibly as the first char after '[' or '[^')

        # Wait, the problem says "]\, ], [, and - (except as the range dash) always appear escaped with \"
        # So ']' inside a class is always '\]'. And '-' is either a range dash or '\-'.
        # And '[' is always '\['.

        # Hmm, but what about ']' as the first character? In many regex flavors, `[]]` matches ']'.
        # But the problem says ']' always appears escaped. So we don't need to handle that case.

        # Let me parse items:
        while cur() != ']':
            # Parse one item
            item = parse_class_item()
            # Check for range
            if cur() == '-' and pos[0]+1 < len(pattern) and pattern[pos[0]+1] != ']':
                # It's a range
                adv()  # consume '-'
                hi = parse_class_item_char()
                items.append(('range', item, hi))
            else:
                items.append(('char', item))
        adv()  # consume ']'
        return Class(items, negated)

    def parse_class_item():
        c = cur()
        if c == '\\':
            adv()
            c2 = cur()
            adv()
            if c2 in 'dDwWsS':
                return ('esc', c2)
            else:
                return ('char', c2)
        else:
            adv()
            return ('char', c)

    def parse_class_item_char():
        # Parse a single character (possibly escaped) for range endpoint
        c = cur()
        if c == '\\':
            adv()
            c2 = cur()
            adv()
            return c2
        else:
            adv()
            return c

    ast = parse_regex()
    return ast, group_count[0]

boolean matchStarGreedy(Node X, int pos, int[] caps) {
    // Try one more iteration (greedy: prefer iterating)
    int[] savedCaps = caps.clone();
    int newPos = pos;
    if (matchNode(X, newPos, caps)) {
        // X matched, possibly consuming characters
        if (newPos > pos) {
            // Consumed chars, try more iterations
            if (matchStarGreedy(X, newPos, caps)) return true;
        } else {
            // Empty match, stop loop (k > min=0)
            // Actually k=1 > min=0, so stop
        }
    }
    // Restore caps (X's match is undone)
    System.arraycopy(savedCaps, 0, caps, 0, caps.length);
    // Stop the loop, continue with what follows
    // But wait, "what follows" is handled by the caller
    return true; // ???
}

// NFA states: CHAR(c), CLASS(set), SPLIT(left, right), SAVE(slot, next), MATCH, ANCHOR(type)

boolean match(int state, int pos, int[] caps) {
    if (pos > subjectLen) return false;  // can't go past end
    if (memo[state][pos] == FAIL) return false;

    State s = states[state];

    switch (s.type) {
        case MATCH:
            return true;
        case CHAR:
            if (pos < subjectLen && subject[pos] == s.ch) {
                return match(s.next, pos + 1, caps);
            }
            memo[state][pos] = FAIL;
            return false;
        case CLASS:
            if (pos < subjectLen && s.set.contains(subject[pos])) {
                return match(s.next, pos + 1, caps);
            }
            memo[state][pos] = FAIL;
            return false;
        case SPLIT:
            // Try left first (higher priority)
            int[] savedCaps = caps.clone();
            if (match(s.left, pos, caps)) return true;
            // Left failed, restore caps and try right
            System.arraycopy(savedCaps, 0, caps, 0, caps.length);
            if (match(s.right, pos, caps)) return true;
            memo[state][pos] = FAIL;
            return false;
        case SAVE:
            int saved = caps[s.slot];
            caps[s.slot] = pos;
            if (match(s.next, pos, caps)) return true;
            caps[s.slot] = saved;
            memo[state][pos] = FAIL;
            return false;
        case ANCHOR_START:
            if (pos == 0) return match(s.next, pos, caps);
            memo[state][pos] = FAIL;
            return false;
        case ANCHOR_END:
            if (pos == subjectLen) return match(s.next, pos, caps);
            memo[state][pos] = FAIL;
            return false;
    }
}

