      // Advance all threads by one character
      next_threads = []
      for each thread in threads:
        if thread.state can match subject[pos]:
          add_thread(thread.state.next, thread.captures, pos+1, next_threads)

      threads = next_threads

    // Check at end position too
    for each thread in threads:
      if thread.state == MATCH: return match at (start_pos, len(subject), captures)

  return no match

function add_thread(state_id, captures, pos, threads):
  // Epsilon closure
  while state is epsilon:
    if state is SAVE(slot): captures[slot] = pos; state = state.next
    if state is SPLIT(low, high): 
      add_thread(low, copy(captures), pos, threads)
      state = high  // continue with high
    if state is ASSERT_START: if pos != 0: return; state = state.next
    if state is ASSERT_END: if pos != len: return; state = state.next
    if state is MATCH: threads.push((state, captures)); return

  threads.push((state, captures))

