import sys
import json
import csv
import io
import os
import urllib.request
import urllib.error
from urllib.parse import urlparse


def parse_csv(filepath):
    with open(filepath, 'rb') as f:
        raw = f.read()
    if raw.startswith(b'\xef\xbb\xbf'):
        raw = raw[3:]
    text = raw.decode('utf-8')
    reader = csv.reader(io.StringIO(text, newline=''))
    rows = list(reader)
    return rows


def json_escape_string(s):
    result = []
    for ch in s:
        cp = ord(ch)
        if ch == '"':
            result.append('\\"')
        elif ch == '\\':
            result.append('\\\\')
        elif ch == '\x08':
            result.append('\\b')
        elif ch == '\x0c':
            result.append('\\f')
        elif ch == '\n':
            result.append('\\n')
        elif ch == '\r':
            result.append('\\r')
        elif ch == '\t':
            result.append('\\t')
        elif cp < 0x20:
            result.append('\\u%04x' % cp)
        else:
            result.append(ch)
    return ''.join(result)


def serialize_result(d):
    parts = ['{']
    for i, (k, v) in enumerate(d.items()):
        if i > 0:
            parts.append(',')
        parts.append('"' + json_escape_string(k) + '"')
        parts.append(':')
        if isinstance(v, int):
            parts.append(str(v))
        elif isinstance(v, str):
            parts.append('"' + json_escape_string(v) + '"')
    parts.append('}')
    return ''.join(parts)


def execute_tool(name, args, inventory_dict, rates):
    if name == 'inventory_lookup':
        sku = args['sku']
        if sku in inventory_dict:
            row = inventory_dict[sku]
            result = {
                'sku': row['sku'],
                'name': row['name'],
                'price_cents': row['price_cents'],
                'currency': row['currency'],
                'stock': row['stock'],
            }
            return serialize_result(result)
        else:
            return serialize_result({'error': 'unknown sku: ' + sku})
    elif name == 'convert_currency':
        amount = args['amount_cents']
        from_c = args['from']
        to_c = args['to']
        rate_from = rates[from_c]
        rate_to = rates[to_c]
        converted = (2 * amount * rate_to + rate_from) // (2 * rate_from)
        return serialize_result({'amount_cents': converted, 'currency': to_c})
    else:
        return serialize_result({'error': 'unknown tool: ' + name})


def main():
    data_dir = sys.argv[1]
    base_url = sys.argv[2]

    with open(os.path.join(data_dir, 'task.json'), 'r', encoding='utf-8') as f:
        task = json.load(f)

    api_key = task['api_key']
    model = task['model']
    system_msg = task['system']
    user_msg = task['user']
    tools = task['tools']

    rows = parse_csv(os.path.join(data_dir, 'inventory.csv'))
    inventory_dict = {}
    for row in rows[1:]:
        if len(row) >= 5:
            inventory_dict[row[0]] = {
                'sku': row[0],
                'name': row[1],
                'price_cents': int(row[2]),
                'currency': row[3],
                'stock': int(row[4]),
            }

    with open(os.path.join(data_dir, 'rates.json'), 'r', encoding='utf-8') as f:
        rates_data = json.load(f)
    rates = rates_data['rates']

    messages = [
        {"role": "system", "content": system_msg},
        {"role": "user", "content": user_msg},
    ]

    total_prompt = 0
    total_completion = 0
    total_total = 0
    num_requests = 0
    output_lines = []

    url = base_url + "/chat/completions"
    parsed_url = urlparse(url)
    host = parsed_url.hostname
    port = parsed_url.port
    host_header = host if port is None else f"{host}:{port}"

    while True:
        body_obj = {
            "model": model,
            "messages": messages,
            "tools": tools,
            "tool_choice": "auto",
        }
        body_str = json.dumps(body_obj, ensure_ascii=False)
        body_bytes = body_str.encode('utf-8')

        req = urllib.request.Request(
            url,
            data=body_bytes,
            headers={
                'Authorization': 'Bearer ' + api_key,
                'Content-Type': 'application/json',
                'Host': host_header,
                'Content-Length': str(len(body_bytes)),
            },
            method='POST',
        )

        try:
            resp = urllib.request.urlopen(req)
            status = resp.getcode()
        except urllib.error.HTTPError as e:
            status = e.code
            resp = e

        num_requests += 1
        resp_body = resp.read().decode('utf-8')
        resp_json = json.loads(resp_body)

        if status != 200:
            error_msg = resp_json.get('error', {}).get('message', '')
            for line in output_lines:
                print(line)
            print(f"ERROR {status} {error_msg}")
            sys.exit(0)

        usage = resp_json.get('usage', {})
        total_prompt += usage.get('prompt_tokens', 0)
        total_completion += usage.get('completion_tokens', 0)
        total_total += usage.get('total_tokens', 0)

        choice = resp_json['choices'][0]
        finish_reason = choice['finish_reason']
        msg = choice['message']

        if finish_reason == 'tool_calls':
            content = msg.get('content')
            if isinstance(content, str):
                output_lines.append(f"SAY {content}")

            tool_calls = msg['tool_calls']

            assistant_msg = {"role": "assistant", "content": content, "tool_calls": tool_calls}
            messages.append(assistant_msg)

            for tc in tool_calls:
                call_id = tc['id']
                func_name = tc['function']['name']
                output_lines.append(f"CALL {call_id} {func_name}")

            for tc in tool_calls:
                call_id = tc['id']
                func_name = tc['function']['name']
                args_str = tc['function']['arguments']
                args = json.loads(args_str)
                result_str = execute_tool(func_name, args, inventory_dict, rates)
                output_lines.append(f"RESULT {call_id} {result_str}")
                messages.append({
                    "role": "tool",
                    "tool_call_id": call_id,
                    "content": result_str,
                })

        elif finish_reason == 'stop':
            content = msg.get('content', '')
            output_lines.append(f"FINAL {content}")
            break

    for line in output_lines:
        print(line)
    print(f"USAGE prompt={total_prompt} completion={total_completion} total={total_total} requests={num_requests}")
    sys.exit(0)


if __name__ == '__main__':
    main()

fn compile(node: &Node, prog: &mut Vec<Inst>) {
    match node {
        Node::Empty => {}
        Node::Literal(c) => { prog.push(Inst::Char(*c)); }
        Node::Any => { prog.push(Inst::Any); }
        Node::Class(ranges, neg) => { prog.push(Inst::Class(ranges.clone(), *neg)); }
        Node::Start => { prog.push(Inst::Start); }
        Node::End => { prog.push(Inst::End); }
        Node::Group(num, inner) => {
            prog.push(Inst::Save(2 * num));
            compile(inner, prog);
            prog.push(Inst::Save(2 * num + 1));
        }
        Node::NonCapGroup(inner) => { compile(inner, prog); }
        Node::Concat(nodes) => {
            for n in nodes { compile(n, prog); }
        }
        Node::Alt(branches) => {
            // Build: Split(b1, b2) ... Jump(end) b2: ... Jump(end) ... bN: ... end:
            let mut split_pcs = vec![];
            let mut jump_pcs = vec![];

            for (i, branch) in branches.iter().enumerate() {
                if i < branches.len() - 1 {
                    let split_pc = prog.len();
                    prog.push(Inst::Split(0, 0)); // placeholder
                    split_pcs.push(split_pc);
                    compile(branch, prog);
                    jump_pcs.push(prog.len());
                    prog.push(Inst::Jump(0)); // placeholder
                } else {
                    compile(branch, prog);
                }
            }

            let end = prog.len();
            // Patch splits: split_pcs[i].high = split_pcs[i]+1 (start of branch i)
            //              split_pcs[i].low = start of branch i+1
            // Patch jumps: jump_pcs[i] → end

            // Actually, let me redo this.
            // For A|B|C:
            //   Split(start_A, start_B)
            //   A_instructions
            //   Jump(end)
            //   start_B: Split(start_B, start_C)  -- wait no
            //   
            // Let me think again. For A|B|C with priority A > B > C:
            //   Split(1, X)  -- try A (pc=1) first, then B (pc=X)
            //   [A]
            //   Jump(end)
            //   X: Split(X+1, Y)  -- try B (pc=X+1) first, then C (pc=Y)
