use std::env;
use std::fs;

#[derive(Clone, Debug)]
enum Node {
    Empty,
    Literal(char),
    Any,
    Class(Vec<(u8, u8)>, bool),
    Start,
    End,
    Group(usize, Box<Node>),
    NonCapGroup(Box<Node>),
    Concat(Vec<Node>),
    Alt(Vec<Node>),
    Repeat(Box<Node>, usize, Option<usize>, bool),
}

#[derive(Clone, Debug)]
enum Inst {
    Char(u8),
    Any,
    Class(Vec<(u8, u8)>, bool),
    Save(usize),
    Split(usize, usize),
    Jump(usize),
    AnchorStart,
    AnchorEnd,
    Match,
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
    num_groups: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { chars: s.chars().collect(), pos: 0, num_groups: 0 }
    }

    fn peek(&self) -> Option<char> { self.chars.get(self.pos).copied() }
    fn peek_at(&self, offset: usize) -> Option<char> { self.chars.get(self.pos + offset).copied() }
    fn advance(&mut self) -> Option<char> { let c = self.chars.get(self.pos).copied(); if c.is_some() { self.pos += 1; } c }

    fn parse(&mut self) -> Node {
        let node = self.parse_regex();
        node
    }

    fn parse_regex(&mut self) -> Node {
        let mut branches = vec![self.parse_branch()];
        while self.peek() == Some('|') {
            self.advance();
            branches.push(self.parse_branch());
        }
        if branches.len() == 1 { branches.remove(0) } else { Node::Alt(branches) }
    }

    fn parse_branch(&mut self) -> Node {
        let mut pieces = vec![];
        loop {
            match self.peek() {
                Some('|') | Some(')') | None => break,
                _ => pieces.push(self.parse_piece()),
            }
        }
        if pieces.len() == 1 { pieces.remove(0) }
        else if pieces.is_empty() { Node::Empty }
        else { Node::Concat(pieces) }
    }

    fn parse_piece(&mut self) -> Node {
        let atom = self.parse_atom();
        // anchors are never quantified
        let is_anchor = matches!(atom, Node::Start | Node::End);
        if is_anchor { return atom; }
        if let Some((min, max, lazy)) = self.parse_quantifier() {
            Node::Repeat(Box::new(atom), min, max, lazy)
        } else {
            atom
        }
    }

    fn parse_quantifier(&mut self) -> Option<(usize, Option<usize>, bool)> {
        let (min, max) = match self.peek() {
            Some('*') => { self.advance(); (0, None) }
            Some('+') => { self.advance(); (1, None) }
            Some('?') => { self.advance(); (0, Some(1)) }
            Some('{') => {
                let save = self.pos;
                self.advance(); // '{'
                if let Some(m) = self.parse_int() {
                    if self.peek() == Some(',') {
                        self.advance(); // ','
                        let n = self.parse_int();
                        if self.peek() == Some('}') {
                            self.advance(); // '}'
                            (m, n) // n could be None for {m,}
                        } else {
                            self.pos = save; return None;
                        }
                    } else if self.peek() == Some('}') {
                        self.advance(); // '}'
                        (m, Some(m))
                    } else {
                        self.pos = save; return None;
                    }
                } else {
                    self.pos = save; return None;
                }
            }
            _ => return None,
        };
        let lazy = self.peek() == Some('?');
        if lazy { self.advance(); }
        Some((min, max, lazy))
    }

    fn parse_int(&mut self) -> Option<usize> {
        let mut n: usize = 0;
        let mut found = false;
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                n = n * 10 + (c as usize - '0' as usize);
                self.advance();
                found = true;
            } else { break; }
        }
        if found { Some(n) } else { None }
    }

    fn parse_atom(&mut self) -> Node {
        match self.peek() {
            Some('(') => {
                self.advance();
                if self.peek() == Some('?') && self.peek_at(1) == Some(':') {
                    self.advance(); self.advance();
                    let inner = self.parse_regex();
                    self.advance(); // ')'
                    Node::NonCapGroup(Box::new(inner))
                } else {
                    self.num_groups += 1;
                    let num = self.num_groups;
                    let inner = self.parse_regex();
                    self.advance(); // ')'
                    Node::Group(num, Box::new(inner))
                }
            }
            Some('.') => { self.advance(); Node::Any }
            Some('^') => { self.advance(); Node::Start }
            Some('$') => { self.advance(); Node::End }
            Some('[') => self.parse_class(),
            Some('\\') => self.parse_escape(),
            Some(c) => { self.advance(); Node::Literal(c) }
            None => Node::Empty,
        }
    }

    fn parse_escape(&mut self) -> Node {
        self.advance(); // '\'
        match self.advance() {
            Some('d') => Node::Class(vec![('0' as u8, '9' as u8)], false),
            Some('D') => Node::Class(vec![('0' as u8, '9' as u8)], true),
            Some('w') => Node::Class(vec![('0' as u8, '9' as u8), ('A' as u8, 'Z' as u8), ('_' as u8, '_' as u8), ('a' as u8, 'z' as u8)], false),
            Some('W') => Node::Class(vec![('0' as u8, '9' as u8), ('A' as u8, 'Z' as u8), ('_' as u8, '_' as u8), ('a' as u8, 'z' as u8)], true),
            Some('s') => Node::Class(vec![(' ' as u8, ' ' as u8), ('\t' as u8, '\r' as u8)], false),
            Some('S') => Node::Class(vec![(' ' as u8, ' ' as u8), ('\t' as u8, '\r' as u8)], true),
            Some(c) => Node::Literal(c),
            None => Node::Literal('\\'),
        }
    }

    fn parse_class(&mut self) -> Node {
        self.advance(); // '['
        let neg = self.peek() == Some('^');
        if neg { self.advance(); }
        let mut ranges: Vec<(u8, u8)> = vec![];
        loop {
            if self.peek() == Some(']') {
                self.advance();
                break;
            }
            // Check for class escape
            if self.peek() == Some('\\') && self.pos + 1 < self.chars.len() {
                let next = self.chars[self.pos + 1];
                if "dDwWsS".contains(next) {
                    self.advance(); self.advance();
                    match next {
                        'd' => ranges.push(('0' as u8, '9' as u8)),
                        'D' => { ranges.push(('\0' as u8, '/' as u8)); ranges.push((':' as u8, '\x7F' as u8)); }
                        'w' => { ranges.push(('0' as u8, '9' as u8)); ranges.push(('A' as u8, 'Z' as u8)); ranges.push(('_' as u8, '_' as u8)); ranges.push(('a' as u8, 'z' as u8)); }
                        'W' => { ranges.push(('\0' as u8, '/' as u8)); ranges.push((':' as u8, '@' as u8)); ranges.push(('[' as u8, '^' as u8)); ranges.push(('`' as u8, '`' as u8)); ranges.push(('{' as u8, '\x7F' as u8)); }
                        's' => { ranges.push((' ' as u8, ' ' as u8)); ranges.push(('\t' as u8, '\r' as u8)); }
                        'S' => { ranges.push(('\0' as u8, '\x08' as u8)); ranges.push(('\x0E' as u8, '\x1F' as u8)); ranges.push(('!' as u8, '\x7F' as u8)); }
                        _ => unreachable!(),
                    }
                    continue;
                }
            }
            // Parse single char (possibly escaped)
            let lo = self.parse_class_single();
            // Check for range
            if self.peek() == Some('-') && self.peek_at(1) != Some(']') {
                self.advance(); // '-'
                let hi = self.parse_class_single();
                ranges.push((lo, hi));
            } else {
                ranges.push((lo, lo));
            }
        }
        Node::Class(ranges, neg)
    }

    fn parse_class_single(&mut self) -> u8 {
        if self.peek() == Some('\\') {
            self.advance(); // '\'
            match self.advance() {
                Some(c) => c as u8,
                None => b'\\',
            }
        } else {
            self.advance().unwrap() as u8
        }
    }
}

