        if b == 0x0A {
            if !cur.isEmpty && cur.last == 0x0D { cur.removeLast() }
            lines.append(String(decoding: cur, as: UTF8.self))
            cur.removeAll()
        } else {
            cur.append(b)
        }
    }
    if !cur.isEmpty {
        lines.append(String(decoding: cur, as: UTF8.self))
    }

    // Parse SSE events
    var eventType = ""
    var dataLines: [String] = []
    var blocks: [Int: ContentBlock] = [:]

    func flushEvent() {
        guard !dataLines.isEmpty else { return }
        let dataStr = dataLines.joined(separator: "\n")
        guard let data = dataStr.data(using: .utf8),
              let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else { return }

        switch eventType {
        case "message_start":
            if let msg = json["message"] as? [String: Any],
               let usage = msg["usage"] as? [String: Any] {
                result.inputTokens += usage["input_tokens"] as? Int ?? 0
                result.cacheReadTokens += usage["cache_read_input_tokens"] as? Int ?? 0
            }
        case "content_block_start":
            let idx = json["index"] as? Int ?? 0
            if let cb = json["content_block"] as? [String: Any] {
                var block = ContentBlock()
                block.type = cb["type"] as? String ?? ""
                block.id = cb["id"] as? String ?? ""
                block.name = cb["name"] as? String ?? ""
                blocks[idx] = block
            }
        case "content_block_delta":
            let idx = json["index"] as? Int ?? 0
            if let delta = json["delta"] as? [String: Any] {
                let dt = delta["type"] as? String ?? ""
                switch dt {
                case "thinking_delta":
                    blocks[idx]?.thinking += delta["thinking"] as? String ?? ""
                case "signature_delta":
                    blocks[idx]?.signature += delta["signature"] as? String ?? ""
                case "text_delta":
                    blocks[idx]?.text += delta["text"] as? String ?? ""
                case "input_json_delta":
                    blocks[idx]?.inputJson += delta["partial_json"] as? String ?? ""
                default: break
                }
            }
        case "message_delta":
            if let delta = json["delta"] as? [String: Any] {
                result.stopReason = delta["stop_reason"] as? String ?? ""
            }
            if let usage = json["usage"] as? [String: Any] {
                result.outputTokens += usage["output_tokens"] as? Int ?? 0
            }
        case "message_stop":
            break
        default:
            break
        }
    }

    for line in lines {
        if line.isEmpty {
            flushEvent()
            eventType = ""
            dataLines.removeAll()
        } else if line.hasPrefix(":") {
            // comment
        } else if line.hasPrefix("event:") {
            var v = String(line.dropFirst(6))
            if v.hasPrefix(" ") { v = String(v.dropFirst(1)) }
            eventType = v
        } else if line.hasPrefix("data:") {
            var v = String(line.dropFirst(5))
            if v.hasPrefix(" ") { v = String(v.dropFirst(1)) }
            dataLines.append(v)
        }
    }
    flushEvent()

    let sortedIdx = blocks.keys.sorted()
    for i in sortedIdx {
        if let b = blocks[i] { result.blocks.append(b) }
    }

    return result
}

func executeTool(name: String, input: [String: Any]) -> (String, Bool) {
    switch name {
    case "measure":
        let text = input["text"] as? String ?? ""
        let unit = input["unit"] as? String ?? ""
        switch unit {
        case "code_points":
            return (String(text.unicodeScalars.count), false)
        case "utf8_bytes":
            return (String(text.utf8.count), false)
        case "utf16_units":
            return (String(text.utf16.count), false)
        default:
            return ("unsupported unit: \(unit)", true)
        }
    case "reverse":
        let text = input["text"] as? String ?? ""
        let reversed = String(text.unicodeScalars.reversed())
        return (reversed, false)
    default:
        return ("unknown tool: \(name)", true)
    }
}

func sendRequest(host: String, port: Int, path: String, apiKey: String, body: Data) -> (Int, [String: String], ByteReader) {
    let fd = connectTo(host: host, port: port)
    var reqStr = "POST \(path) HTTP/1.1\r\n"
    reqStr += "Host: \(host):\(port)\r\n"
    reqStr += "Content-Length: \(body.count)\r\n"
    reqStr += "x-api-key: \(apiKey)\r\n"
    reqStr += "anthropic-version: 2023-06-01\r\n"
    reqStr += "content-type: application/json\r\n"
    reqStr += "\r\n"
    let fullReq = Array(reqStr.utf8) + Array(body)
    sendAll(fd, fullReq)

    let reader = ByteReader(fd: fd)

    guard let statusLine = reader.readLine() else { fatalError("no status line") }
    let statusStr = String(decoding: statusLine, as: UTF8.self)
    let statusCode = Int(statusStr.split(separator: " ")[1]) ?? 0

    var headers: [String: String] = [:]
    while true {
        guard let line = reader.readLine() else { break }
        if line.isEmpty { break }
        let lineStr = String(decoding: line, as: UTF8.self)
        if let ci = lineStr.firstIndex(of: ":") {
            let key = String(lineStr[lineStr.startIndex..<ci]).lowercased()
            let val = String(lineStr[lineStr.index(after: ci)...]).trimmingCharacters(in: .whitespaces)
            headers[key] = val
        }
    }

    return (statusCode, headers, reader)
}

func printBlocks(_ blocks: [ContentBlock]) {
    for block in blocks {
        switch block.type {
        case "thinking":
            print("thinking \(escapeStr(block.thinking))")
            print("signature \(escapeStr(block.signature))")
        case "text":
            print("text \(escapeStr(block.text))")
        case "tool_use":
            print("tool_use \(block.id) \(block.name) \(escapeStr(block.inputJson))")
        default: break
        }
    }
}

