import Foundation
import Darwin

func escapeStr(_ s: String) -> String {
    var r = ""
    for c in s.unicodeScalars {
        switch c {
        case "\\": r += "\\\\"
        case "\n": r += "\\n"
        case "\r": r += "\\r"
        case "\t": r += "\\t"
        default: r.unicodeScalars.append(c)
        }
    }
    return r
}

class ByteReader {
    let fd: Int32
    var buf: [UInt8] = []
    var off: Int = 0

    init(fd: Int32) { self.fd = fd }

    private func fill() -> Bool {
        if off > 0 { buf.removeFirst(off); off = 0 }
        var tmp = [UInt8](repeating: 0, count: 65536)
        let n = recv(fd, &tmp, tmp.count, 0)
        if n <= 0 { return false }
        buf.append(contentsOf: tmp[0..<n])
        return true
    }

    func readByte() -> UInt8? {
        if off >= buf.count {
            if !fill() { return nil }
        }
        let b = buf[off]; off += 1
        return b
    }

    func readBytes(_ n: Int) -> [UInt8]? {
        while buf.count - off < n {
            if !fill() { return nil }
        }
        let r = Array(buf[off..<off + n]); off += n
        return r
    }

    func readLine() -> [UInt8]? {
        var line: [UInt8] = []
        while true {
            guard let b = readByte() else { return line.isEmpty ? nil : line }
            if b == 0x0A {
                if !line.isEmpty && line.last == 0x0D { line.removeLast() }
                return line
            }
            line.append(b)
        }
    }
}

func connectTo(host: String, port: Int) -> Int32 {
    let fd = socket(AF_INET, SOCK_STREAM, 0)
    var addr = sockaddr_in()
    addr.sin_family = sa_family_t(AF_INET)
    addr.sin_port = in_port_t(port).bigEndian
    inet_pton(AF_INET, host, &addr.sin_addr)
    let ret = withUnsafePointer(to: &addr) { ptr in
        ptr.withMemoryRebound(to: sockaddr.self, capacity: 1) {
            Darwin.connect(fd, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
        }
    }
    if ret != 0 { fatalError("connect failed") }
    return fd
}

func sendAll(_ fd: Int32, _ data: [UInt8]) {
    var sent = 0
    while sent < data.count {
        let n = data[sent...].withUnsafeBufferPointer { ptr in
            Darwin.send(fd, ptr.baseAddress!, ptr.count, 0)
        }
        if n <= 0 { fatalError("send failed") }
        sent += n
    }
}

struct ContentBlock {
    var type: String = ""
    var thinking: String = ""
    var signature: String = ""
    var text: String = ""
    var inputJson: String = ""
    var id: String = ""
    var name: String = ""
}

struct StreamResult {
    var blocks: [ContentBlock] = []
    var stopReason: String = ""
    var inputTokens: Int = 0
    var outputTokens: Int = 0
    var cacheReadTokens: Int = 0
    var error: String? = nil
}

func processResponse(reader: ByteReader, statusCode: Int, headers: [String: String]) -> StreamResult {
    var result = StreamResult()

    if statusCode != 200 {
        let contentLength = Int(headers["content-length"] ?? "") ?? 0
        guard let bodyBytes = reader.readBytes(contentLength) else {
            result.error = "ERROR \(statusCode) unknown: failed to read body"
            return result
        }
        let bodyStr = String(decoding: bodyBytes, as: UTF8.self)
        if let data = bodyStr.data(using: .utf8),
           let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
           let error = json["error"] as? [String: Any] {
            let errorType = error["type"] as? String ?? ""
            let errorMessage = error["message"] as? String ?? ""
            result.error = "ERROR \(statusCode) \(errorType): \(errorMessage)"
        } else {
            result.error = "ERROR \(statusCode) unknown: parse failure"
        }
        return result
    }

    // Read chunked body
    var body: [UInt8] = []
    while true {
        guard let sizeLine = reader.readLine() else { break }
        let hexStr = String(decoding: sizeLine, as: UTF8.self)
        let hexOnly = hexStr.components(separatedBy: ";")[0].trimmingCharacters(in: .whitespaces)
        let chunkSize = Int(hexOnly, radix: 16) ?? 0
        if chunkSize == 0 {
            _ = reader.readLine()
            break
        }
        guard let data = reader.readBytes(chunkSize) else { break }
        body.append(contentsOf: data)
        _ = reader.readLine()
    }

    // Split body into lines
    var lines: [String] = []
    var cur: [UInt8] = []
    for b in body {
        if b == 0x0A {
            if !cur.isEmpty && cur.last == 0x0D { cur.removeLast() }
            lines.append(String(decoding: cur, as: UTF8.self))
            cur.removeAll()
        } else {
            cur.append(b)
        }
    }
    if !cur.isEmpty {
        lines.append(String(decoding: cur, as: UTF8.self))
    }

    // Parse SSE events
    var eventType = ""
    var dataLines: [String] = []
    var blocks: [Int: ContentBlock] = [:]

    func flushEvent() {
        guard !dataLines.isEmpty else { return }
        let dataStr = dataLines.joined(separator: "\n")
        guard let data = dataStr.data(using: .utf8),
              let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else { return }

        switch eventType {
        case "message_start":
            if let msg = json["message"] as? [String: Any],
               let usage = msg["usage"] as? [String: Any] {
                result.inputTokens += usage["input_tokens"] as? Int ?? 0
                result.cacheReadTokens += usage["cache_read_input_tokens"] as? Int ?? 0
            }
        case "content_block_start":
            let idx = json["index"] as? Int ?? 0
            if let cb = json["content_block"] as? [String: Any] {
                var block = ContentBlock()
                block.type = cb["type"] as? String ?? ""
                block.id = cb["id"] as? String ?? ""
                block.name = cb["name"] as? String ?? ""
                blocks[idx] = block
            }
        case "content_block_delta":
            let idx = json["index"] as? Int ?? 0
            if let delta = json["delta"] as? [String: Any] {
                let dt = delta["type"] as? String ?? ""
                switch dt {
                case "thinking_delta":
                    blocks[idx]?.thinking += delta["thinking"] as? String ?? ""
                case "signature_delta":
                    blocks[idx]?.signature += delta["signature"] as? String ?? ""
                case "text_delta":
                    blocks[idx]?.text += delta["text"] as? String ?? ""
                case "input_json_delta":
                    blocks[idx]?.inputJson += delta["partial_json"] as? String ?? ""
                default: break
                }
            }
        case "message_delta":
            if let delta = json["delta"] as? [String: Any] {
                result.stopReason = delta["stop_reason"] as? String ?? ""
            }
            if let usage = json["usage"] as? [String: Any] {
                result.outputTokens += usage["output_tokens"] as? Int ?? 0
            }
        case "message_stop":
            break
        default:
            break
        }
    }

    for line in lines {
        if line.isEmpty {
            flushEvent()
            eventType = ""
            dataLines.removeAll()
        } else if line.hasPrefix(":") {
            // comment
        } else if line.hasPrefix("event:") {
            var v = String(line.dropFirst(6))
            if v.hasPrefix(" ") { v = String(v.dropFirst(1)) }
            eventType = v
        } else if line.hasPrefix("data:") {
            var v = String(line.dropFirst(5))
            if v.hasPrefix(" ") { v = String(v.dropFirst(1)) }
            dataLines.append(v)
        }
    }
    flushEvent()

    let sortedIdx = blocks.keys.sorted()
    for i in sortedIdx {
        if let b = blocks[i] { result.blocks.append(b) }
    }

    return result
}

func executeTool(name: String, input: [String: Any]) -> (String, Bool) {
    switch name {
    case "measure":
        let text = input["text"] as? String ?? ""
        let unit = input["unit"] as? String ?? ""
        switch unit {
        case "code_points":
            return (String(text.unicodeScalars.count), false)
        case "utf8_bytes":
            return (String(text.utf8.count), false)
        case "utf16_units":
            return (String(text.utf16.count), false)
        default:
            return ("unsupported unit: \(unit)", true)
        }
    case "reverse":
        let text = input["text"] as? String ?? ""
        var reversed = ""
        for scalar in text.unicodeScalars.reversed() {
            reversed.unicodeScalars.append(scalar)
        }
        return (reversed, false)
    default:
        return ("unknown tool: \(name)", true)
    }
}

func sendRequest(host: String, port: Int, path: String, apiKey: String, body: Data) -> (Int, [String: String], ByteReader) {
    let fd = connectTo(host: host, port: port)
    var reqStr = "POST \(path) HTTP/1.1\r\n"
    reqStr += "Host: \(host):\(port)\r\n"
    reqStr += "Content-Length: \(body.count)\r\n"
    reqStr += "x-api-key: \(apiKey)\r\n"
    reqStr += "anthropic-version: 2023-06-01\r\n"
    reqStr += "content-type: application/json\r\n"
    reqStr += "\r\n"
    let fullReq = Array(reqStr.utf8) + Array(body)
    sendAll(fd, fullReq)

    let reader = ByteReader(fd: fd)

    guard let statusLine = reader.readLine() else { fatalError("no status line") }
    let statusStr = String(decoding: statusLine, as: UTF8.self)
    let statusCode = Int(statusStr.split(separator: " ")[1]) ?? 0

    var headers: [String: String] = [:]
    while true {
        guard let line = reader.readLine() else { break }
        if line.isEmpty { break }
        let lineStr = String(decoding: line, as: UTF8.self)
        if let ci = lineStr.firstIndex(of: ":") {
            let key = String(lineStr[lineStr.startIndex..<ci]).lowercased()
            let val = String(lineStr[lineStr.index(after: ci)...]).trimmingCharacters(in: .whitespaces)
            headers[key] = val
        }
    }

    return (statusCode, headers, reader)
}

