#!/usr/bin/env python3
import sys
import json
import http.client
from urllib.parse import urlparse


def escape(s):
    result = []
    for ch in s:
        if ch == '\\':
            result.append('\\\\')
        elif ch == '\n':
            result.append('\\n')
        elif ch == '\r':
            result.append('\\r')
        elif ch == '\t':
            result.append('\\t')
        else:
            result.append(ch)
    return ''.join(result)


def parse_sse(data_bytes):
    text = data_bytes.decode('utf-8')
    text = text.replace('\r\n', '\n')
    lines = text.split('\n')

    events = []
    current_event = None
    current_data_lines = []

    for line in lines:
        if line == '':
            if current_event is not None or current_data_lines:
                event_name = current_event if current_event else ''
                data_str = '\n'.join(current_data_lines)
                events.append((event_name, data_str))
                current_event = None
                current_data_lines = []
        elif line.startswith(':'):
            pass
        elif line.startswith('event:'):
            val = line[6:]
            if val.startswith(' '):
                val = val[1:]
            current_event = val
        elif line.startswith('data:'):
            val = line[5:]
            if val.startswith(' '):
                val = val[1:]
            current_data_lines.append(val)

    return events


def execute_tool(name, input_obj):
    if name == 'measure':
        text = input_obj.get('text', '')
        unit = input_obj.get('unit', '')
        if unit == 'code_points':
            return str(len(text)), False
        elif unit == 'utf8_bytes':
            return str(len(text.encode('utf-8'))), False
        elif unit == 'utf16_units':
            count = 0
            for ch in text:
                if ord(ch) > 0xFFFF:
                    count += 2
                else:
                    count += 1
            return str(count), False
        else:
            return f'unsupported unit: {unit}', True
    elif name == 'reverse':
        text = input_obj.get('text', '')
        return text[::-1], False
    else:
        return f'unknown tool: {name}', True


def process_stream(resp):
    body = resp.read()
    events = parse_sse(body)

    blocks = {}
    stop_reason = None
    usage = {'input_tokens': 0, 'output_tokens': 0, 'cache_read_input_tokens': 0}

    for event_name, data_str in events:
        if event_name == 'message_start':
            obj = json.loads(data_str)
            msg = obj.get('message', {})
            u = msg.get('usage', {})
            usage['input_tokens'] += u.get('input_tokens', 0)
            usage['cache_read_input_tokens'] += u.get('cache_read_input_tokens', 0)
        elif event_name == 'content_block_start':
            obj = json.loads(data_str)
            idx = obj['index']
            cb = obj['content_block']
            blocks[idx] = {
                'type': cb['type'],
                'thinking': '',
                'signature': '',
                'text': '',
                'partial_json': '',
                'id': cb.get('id', ''),
                'name': cb.get('name', ''),
            }
        elif event_name == 'content_block_delta':
            obj = json.loads(data_str)
            idx = obj['index']
            delta = obj['delta']
            dtype = delta['type']
            if dtype == 'thinking_delta':
                blocks[idx]['thinking'] += delta.get('thinking', '')
            elif dtype == 'signature_delta':
                blocks[idx]['signature'] += delta.get('signature', '')
            elif dtype == 'text_delta':
                blocks[idx]['text'] += delta.get('text', '')
            elif dtype == 'input_json_delta':
                blocks[idx]['partial_json'] += delta.get('partial_json', '')
        elif event_name == 'message_delta':
            obj = json.loads(data_str)
            d = obj.get('delta', {})
            if 'stop_reason' in d:
                stop_reason = d['stop_reason']
            u = obj.get('usage', {})
            usage['output_tokens'] += u.get('output_tokens', 0)
        elif event_name == 'message_stop':
            pass

    return blocks, stop_reason, usage


def print_reply(blocks, stop_reason):
    for idx in sorted(blocks.keys()):
        b = blocks[idx]
        if b['type'] == 'thinking':
            print(f'thinking {escape(b["thinking"])}')
            print(f'signature {escape(b["signature"])}')
        elif b['type'] == 'text':
            print(f'text {escape(b["text"])}')
        elif b['type'] == 'tool_use':
            print(f'tool_use {b["id"]} {b["name"]} {escape(b["partial_json"])}')
    print(f'stop_reason {stop_reason}')


def main():
    data_dir = sys.argv[1]
    base_url = sys.argv[2]

    with open(f'{data_dir}/request.json', 'r') as f:
        req_data = json.load(f)

    api_key = req_data['api_key']
    model = req_data['model']
    max_tokens = req_data['max_tokens']
    thinking_budget = req_data['thinking_budget']
    system = req_data['system']
    prompt = req_data['prompt']
    tools = req_data['tools']

    parsed = urlparse(base_url)
    host = parsed.hostname
    port = parsed.port or 80
    path_prefix = parsed.path.rstrip('/')

    def make_body(messages):
        return json.dumps({
            'model': model,
            'max_tokens': max_tokens,
            'stream': True,
            'thinking': {'type': 'enabled', 'budget_tokens': thinking_budget},
            'system': system,
            'tools': tools,
            'messages': messages
        })

    # --- Request 1 ---
    body1 = make_body([{'role': 'user', 'content': prompt}])
    body1_bytes = body1.encode('utf-8')

    conn1 = http.client.HTTPConnection(host, port)
    conn1.request('POST', f'{path_prefix}/v1/messages', body=body1_bytes, headers={
        'Host': f'{host}:{port}',
        'Content-Length': str(len(body1_bytes)),
        'x-api-key': api_key,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
    })
    resp1 = conn1.getresponse()

    if resp1.status != 200:
        error_body = resp1.read().decode('utf-8')
        error_obj = json.loads(error_body)
        print(f'ERROR {resp1.status} {error_obj["error"]["type"]}: {error_obj["error"]["message"]}')
        sys.exit(0)

    blocks1, stop_reason1, usage1 = process_stream(resp1)
    conn1.close()

    print('request 1')
    print_reply(blocks1, stop_reason1)

    # Build assistant content and execute tools
    assistant_content = []
    tool_use_blocks = []
    for idx in sorted(blocks1.keys()):
        b = blocks1[idx]
        if b['type'] == 'thinking':
            assistant_content.append({
                'type': 'thinking',
                'thinking': b['thinking'],
                'signature': b['signature']
            })
        elif b['type'] == 'text':
            assistant_content.append({
                'type': 'text',
                'text': b['text']
            })
        elif b['type'] == 'tool_use':
            input_obj = json.loads(b['partial_json'])
            assistant_content.append({
                'type': 'tool_use',
                'id': b['id'],
                'name': b['name'],
                'input': input_obj
            })
            tool_use_blocks.append((b['id'], b['name'], input_obj))

    tool_results = []
    for tool_id, tool_name, tool_input in tool_use_blocks:
        result_str, is_error = execute_tool(tool_name, tool_input)
        tool_results.append((tool_id, result_str, is_error))
        if is_error:
            print(f'error {tool_id} {escape(result_str)}')
        else:
            print(f'result {tool_id} {escape(result_str)}')

    tool_result_content = []
    for tool_id, result_str, is_error in tool_results:
        block = {
            'type': 'tool_result',
            'tool_use_id': tool_id,
            'content': result_str
        }
        if is_error:
            block['is_error'] = True
        tool_result_content.append(block)

    # --- Request 2 ---
    body2 = make_body([
        {'role': 'user', 'content': prompt},
        {'role': 'assistant', 'content': assistant_content},
        {'role': 'user', 'content': tool_result_content}
    ])
    body2_bytes = body2.encode('utf-8')

    conn2 = http.client.HTTPConnection(host, port)
    conn2.request('POST', f'{path_prefix}/v1/messages', body=body2_bytes, headers={
        'Host': f'{host}:{port}',
        'Content-Length': str(len(body2_bytes)),
        'x-api-key': api_key,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
    })
    resp2 = conn2.getresponse()

    if resp2.status != 200:
        error_body = resp2.read().decode('utf-8')
        error_obj = json.loads(error_body)
        print(f'ERROR {resp2.status} {error_obj["error"]["type"]}: {error_obj["error"]["message"]}')
        sys.exit(0)

    blocks2, stop_reason2, usage2 = process_stream(resp2)
    conn2.close()

    print('request 2')
    print_reply(blocks2, stop_reason2)

    total_input = usage1['input_tokens'] + usage2['input_tokens']
    total_output = usage1['output_tokens'] + usage2['output_tokens']
    total_cache_read = usage1['cache_read_input_tokens'] + usage2['cache_read_input_tokens']

    print(f'usage input={total_input} output={total_output} cache_read={total_cache_read}')


if __name__ == '__main__':
    main()

