            while ti < rest.endIndex && (rest[ti].isLetter || rest[ti].isNumber || rest[ti] == "_") {
                typeWord.append(rest[ti]); ti = rest.index(after: ti)
            }
            if typeWord.uppercased() == "INTEGER" {
                isAlias = true
            }
        }

        columns.append(ColumnInfo(name: colName, isRowidAlias: isAlias))
    }
    return columns
}

// MARK: - Value formatting
func formatDouble(_ d: Double) -> String {
    if d.isNaN { return "NaN" }
    if d.isInfinite { return d > 0 ? "Inf" : "-Inf" }
    var s = String(format: "%.8f", d)
    if s.contains(".") {
        while s.hasSuffix("0") { s.removeLast() }
        if s.hasSuffix(".") { s.append("0") }
    }
    return s
}

func formatText(_ bytes: [UInt8]) -> String {
    guard let str = String(bytes: bytes, encoding: .utf8) else {
        // Fallback: shouldn't happen with valid UTF-8 TEXT
        var r = "\""
        for b in bytes {
            if b == 0x5C { r += "\\\\" }
            else if b == 0x22 { r += "\\\"" }
            else if b == 0x0A { r += "\\n" }
            else if b == 0x0D { r += "\\r" }
            else if b == 0x09 { r += "\\t" }
            else if b < 0x20 || b == 0x7F { r += String(format: "\\x%02X", b) }
            else { r.append(Character(UnicodeScalar(b))) }
        }
        r += "\""
        return r
    }
    var result = "\""
    for ch in str {
        if ch == "\\" { result += "\\\\" }
        else if ch == "\"" { result += "\\\"" }
        else if ch == "\n" { result += "\\n" }
        else if ch == "\r" { result += "\\r" }
        else if ch == "\t" { result += "\\t" }
        else {
            let sv = ch.unicodeScalars.first!.value
            if sv < 0x20 || sv == 0x7F {
                result += String(format: "\\x%02X", sv)
            } else {
                result.append(ch)
            }
        }
    }
    result += "\""
    return result
}

func formatBlob(_ bytes: [UInt8]) -> String {
    var r = "X'"
    for b in bytes { r += String(format: "%02X", b) }
    r += "'"
    return r
}

func formatValue(_ v: Value, isRowidAlias: Bool, rowid: Int64) -> String {
    if isRowidAlias { return String(rowid) }
    switch v {
    case .null: return "NULL"
    case .integer(let i): return String(i)
    case .real(let d): return formatDouble(d)
    case .text(let bytes):
        if bytes.count <= 100 { return formatText(bytes) }
        else { return "<TEXT len=\(bytes.count) crc32=\(String(format: "%08x", crc32(bytes)))>" }
    case .blob(let bytes):
        if bytes.count <= 100 { return formatBlob(bytes) }
        else { return "<BLOB len=\(bytes.count) crc32=\(String(format: "%08x", crc32(bytes)))>" }
    }
}

// MARK: - Main
func main() {
    initCRC()
    let args = CommandLine.arguments
    guard args.count >= 2 else { exit(1) }
    let dir = args[1]
    let path = dir + "/db.sqlite"
    guard let fileData = FileManager.default.contents(atPath: path) else { exit(1) }
    let data = [UInt8](fileData)
    guard data.count >= 100 else { exit(1) }

    // Header
    let rawPageSize = readBE16(data, 16)
    let pageSize = rawPageSize == 1 ? 65536 : rawPageSize
    let reserved = Int(data[20])

    // Read schema (rooted at page 1)
    let schemaRows = walkTableBTree(data, 1, pageSize, reserved)

    struct TableInfo {
        var name: String
        var rootPage: Int
        var sql: String
    }

    var tables: [TableInfo] = []
    for (_, payload) in schemaRows {
        let values = parseRecord(payload)
        guard values.count >= 5 else { continue }

        guard case .text(let typeBytes) = values[0],
              let typeStr = String(bytes: typeBytes, encoding: .utf8),
              typeStr == "table" else { continue }

        guard case .text(let nameBytes) = values[1],
              let nameStr = String(bytes: nameBytes, encoding: .utf8),
              !nameStr.hasPrefix("sqlite_") else { continue }

        guard case .integer(let rootVal) = values[3] else { continue }
        let rootPage = Int(rootVal)
        guard rootPage >= 1 else { continue }

        guard case .text(let sqlBytes) = values[4],
              let sqlStr = String(bytes: sqlBytes, encoding: .utf8) else { continue }

        tables.append(TableInfo(name: nameStr, rootPage: rootPage, sql: sqlStr))
    }

    // Sort by name byte-wise ascending
    tables.sort { a, b in
        let ab = Array(a.name.utf8)
        let bb = Array(b.name.utf8)
        return ab.lexicographicallyPrecedes(bb)
    }

    var first = true
    for table in tables {
        if !first { print("") }
        first = false

        let columns = parseColumns(sql: table.sql)
        let rows = walkTableBTree(data, table.rootPage, pageSize, reserved)

        print("TABLE \(table.name) rows=\(rows.count)")
        print("COLUMNS \(columns.map { $0.name }.joined(separator: ", "))")

        let sortedRows = rows.sorted { $0.0 < $1.0 }
        for (rowid, payload) in sortedRows {
            let values = parseRecord(payload)
            var parts: [String] = []
            for i in 0..<columns.count {
                let v: Value = i < values.count ? values[i] : .null
                parts.append(formatValue(v, isRowidAlias: columns[i].isRowidAlias, rowid: rowid))
            }
            print("\(rowid): \(parts.joined(separator: ", "))")
        }
    }
}

