import Foundation

// MARK: - CRC-32 (zlib/PNG variant)
var crcTable: [UInt32] = []
func initCRC() {
    crcTable = [UInt32](repeating: 0, count: 256)
    for i in 0..<256 {
        var c = UInt32(i)
        for _ in 0..<8 {
            if c & 1 != 0 { c = (c >> 1) ^ 0xEDB88320 }
            else { c >>= 1 }
        }
        crcTable[i] = c
    }
}

func crc32(_ data: [UInt8]) -> UInt32 {
    var c: UInt32 = 0xFFFFFFFF
    for b in data {
        c = crcTable[Int((c ^ UInt32(b)) & 0xFF)] ^ (c >> 8)
    }
    return c ^ 0xFFFFFFFF
}

// MARK: - Value type
enum Value {
    case null
    case integer(Int64)
    case real(Double)
    case text([UInt8])
    case blob([UInt8])
}

// MARK: - Big-endian readers
func readBE16(_ d: [UInt8], _ o: Int) -> Int {
    Int(d[o]) << 8 | Int(d[o+1])
}
func readBE32(_ d: [UInt8], _ o: Int) -> Int {
    Int(d[o]) << 24 | Int(d[o+1]) << 16 | Int(d[o+2]) << 8 | Int(d[o+3])
}
func readBE64(_ d: [UInt8], _ o: Int) -> UInt64 {
    var r: UInt64 = 0
    for i in 0..<8 { r = (r << 8) | UInt64(d[o+i]) }
    return r
}
func readSignedInt(_ d: [UInt8], _ o: Int, _ size: Int) -> Int64 {
    var r: UInt64 = 0
    for i in 0..<size { r = (r << 8) | UInt64(d[o+i]) }
    let shift = 64 - size * 8
    return Int64(bitPattern: (r << shift) >> shift)
}
func readDouble(_ d: [UInt8], _ o: Int) -> Double {
    Double(bitPattern: readBE64(d, o))
}

// MARK: - Varint
func readVarint(_ d: [UInt8], _ offset: Int) -> (UInt64, Int) {
    var result: UInt64 = 0
    var i = offset
    for j in 0..<9 {
        if i >= d.count { break }
        let b = d[i]
        if j == 8 {
            result = (result << 8) | UInt64(b)
            i += 1
            break
        }
        result = (result << 7) | UInt64(b & 0x7F)
        i += 1
        if b & 0x80 == 0 { break }
    }
    return (result, i)
}

// MARK: - Page helpers
func getPage(_ fileData: [UInt8], _ pageNum: Int, _ pageSize: Int) -> [UInt8] {
    let start = (pageNum - 1) * pageSize
    let end = min(start + pageSize, fileData.count)
    if start >= end { return [] }
    return Array(fileData[start..<end])
}

// MARK: - Overflow payload
func readOverflow(_ fileData: [UInt8], _ firstPage: Int, _ totalSize: Int, _ pageSize: Int, _ reserved: Int) -> [UInt8] {
    let overflowDataSize = pageSize - reserved - 4
    var result = [UInt8]()
    var page = firstPage
    var remaining = totalSize
    while page != 0 && remaining > 0 {
        let pd = getPage(fileData, page, pageSize)
        if pd.count < 4 { break }
        let nextPage = readBE32(pd, 0)
        let take = min(overflowDataSize, remaining)
        if pd.count >= 4 + take {
            result.append(contentsOf: pd[4..<(4 + take)])
        }
        remaining -= take
        page = nextPage
    }
    return result
}

// MARK: - Compute local payload size
func computeLocalSize(_ P: Int, _ isLeaf: Bool, _ usableSize: Int) -> Int {
    let K = isLeaf ? (usableSize - 35) : (usableSize - 40)
    if P <= K { return P }
    var minLocal = ((usableSize - 12) * 32 / 255) - 23
    if minLocal > K { minLocal = K }
    var local = minLocal + ((P - minLocal) % (usableSize - 4))
    if local > K { local = K }
    return local
}

// MARK: - Read full payload from a cell
func readPayload(_ fileData: [UInt8], _ pageData: [UInt8], _ cellOffset: Int, _ isLeaf: Bool, _ pageSize: Int, _ reserved: Int) -> ([UInt8], Int) {
    let usableSize = pageSize - reserved
    var offset = cellOffset
    let (payloadSizeU, off1) = readVarint(pageData, offset)
    offset = off1
    let P = Int(payloadSizeU)
    let localSize = computeLocalSize(P, isLeaf, usableSize)

    var payload = [UInt8]()
    if offset + localSize <= pageData.count {
        payload.append(contentsOf: pageData[offset..<(offset + localSize)])
    }
    offset += localSize

    if P > localSize {
        if offset + 4 <= pageData.count {
            let overflowPage = readBE32(pageData, offset)
            offset += 4
            let overflowSize = P - localSize
            let od = readOverflow(fileData, overflowPage, overflowSize, pageSize, reserved)
            payload.append(contentsOf: od)
        }
    }
    return (payload, offset)
}

// MARK: - Parse record
func parseRecord(_ data: [UInt8]) -> [Value] {
    if data.isEmpty { return [] }
    var offset = 0
    let (headerSizeU, off1) = readVarint(data, offset)
    offset = off1
    let headerSize = Int(headerSizeU)

    var serialTypes: [Int] = []
    while offset < headerSize && offset < data.count {
        let (st, newOff) = readVarint(data, offset)
        serialTypes.append(Int(st))
        offset = newOff
    }

    var values: [Value] = []
    for st in serialTypes {
        if st == 0 {
            values.append(.null)
        } else if st >= 1 && st <= 4 {
            let sizes = [0, 1, 2, 3, 4]
            let sz = sizes[st]
            if offset + sz <= data.count {
                values.append(.integer(readSignedInt(data, offset, sz)))
                offset += sz
            } else { values.append(.null) }
        } else if st == 5 {
            if offset + 6 <= data.count {
                values.append(.integer(readSignedInt(data, offset, 6)))
                offset += 6
            } else { values.append(.null) }
        } else if st == 6 {
            if offset + 8 <= data.count {
                values.append(.integer(readSignedInt(data, offset, 8)))
                offset += 8
            } else { values.append(.null) }
        } else if st == 7 {
            if offset + 8 <= data.count {
                values.append(.real(readDouble(data, offset)))
                offset += 8
            } else { values.append(.null) }
        } else if st == 8 {
            values.append(.integer(0))
        } else if st == 9 {
            values.append(.integer(1))
        } else if st >= 12 && st % 2 == 0 {
            let len = (st - 12) / 2
            if offset + len <= data.count {
                values.append(.blob(Array(data[offset..<(offset + len)])))
                offset += len
            } else { values.append(.null) }
        } else if st >= 13 && st % 2 == 1 {
            let len = (st - 13) / 2
            if offset + len <= data.count {
                values.append(.text(Array(data[offset..<(offset + len)])))
                offset += len
            } else { values.append(.null) }
        } else {
            values.append(.null)
        }
    }
    return values
}

// MARK: - Walk table b-tree
func walkTableBTree(_ fileData: [UInt8], _ rootPage: Int, _ pageSize: Int, _ reserved: Int) -> [(Int64, [UInt8])] {
    var results: [(Int64, [UInt8])] = []

    func walk(_ pageNum: Int) {
        guard pageNum >= 1 else { return }
        let pageData = getPage(fileData, pageNum, pageSize)
        guard !pageData.isEmpty else { return }
        let hOff = (pageNum == 1) ? 100 : 0
        guard hOff < pageData.count else { return }
        let pageType = pageData[hOff]

        if pageType == 0x0D {
            // Leaf table page
            guard hOff + 4 <= pageData.count else { return }
            let numCells = readBE16(pageData, hOff + 3)
            let cellPtrStart = hOff + 8
            for i in 0..<numCells {
                let ptrOff = cellPtrStart + i * 2
                guard ptrOff + 2 <= pageData.count else { break }
                let cellPtr = readBE16(pageData, ptrOff)
                guard cellPtr < pageData.count else { break }
                var off = cellPtr
                let (payloadSizeU, o1) = readVarint(pageData, off)
                off = o1
                let (rowidU, o2) = readVarint(pageData, off)
                off = o2
                let P = Int(payloadSizeU)
                let usableSize = pageSize - reserved
                let localSize = computeLocalSize(P, true, usableSize)

                var payload = [UInt8]()
                if off + localSize <= pageData.count {
                    payload.append(contentsOf: pageData[off..<(off + localSize)])
                }
                off += localSize
                if P > localSize && off + 4 <= pageData.count {
                    let overflowPage = readBE32(pageData, off)
                    let overflowSize = P - localSize
                    let od = readOverflow(fileData, overflowPage, overflowSize, pageSize, reserved)
                    payload.append(contentsOf: od)
                }

                let rowid = Int64(bitPattern: rowidU)
                results.append((rowid, payload))
            }
        } else if pageType == 0x02 {
            // Interior table page
            guard hOff + 12 <= pageData.count else { return }
            let numCells = readBE16(pageData, hOff + 3)
            let cellPtrStart = hOff + 12
            for i in 0..<numCells {
                let ptrOff = cellPtrStart + i * 2
                guard ptrOff + 2 <= pageData.count else { break }
                let cellPtr = readBE16(pageData, ptrOff)
                guard cellPtr + 4 <= pageData.count else { break }
                let childPage = readBE32(pageData, cellPtr)
                walk(childPage)
            }
            // Rightmost child
            let rightChild = readBE32(pageData, hOff + 8)
            walk(rightChild)
        }
    }

    if rootPage >= 1 { walk(rootPage) }
    return results
}

// MARK: - Column info
struct ColumnInfo {
    var name: String
    var isRowidAlias: Bool
}

func parseColumns(sql: String) -> [ColumnInfo] {
    let upper = sql.uppercased()
    guard let range = upper.range(of: "CREATE TABLE") else { return [] }
    var i = range.upperBound

    func skipWS() {
        while i < sql.endIndex && (sql[i] == " " || sql[i] == "\t" || sql[i] == "\n" || sql[i] == "\r") {
            i = sql.index(after: i)
        }
    }
    skipWS()

    // Skip table name
    if i < sql.endIndex && sql[i] == "\"" {
        i = sql.index(after: i)
        while i < sql.endIndex && sql[i] != "\"" { i = sql.index(after: i) }
        if i < sql.endIndex { i = sql.index(after: i) }
    } else {
        while i < sql.endIndex && (sql[i].isLetter || sql[i].isNumber || sql[i] == "_" || sql[i] == "$" || sql[i] == "@") {
            i = sql.index(after: i)
        }
    }
    skipWS()

    // Optional "IF NOT EXISTS"
    if i < sql.endIndex && sql[i...].hasPrefix("IF") {
        let ifRange = sql.range(of: "IF", options: [], range: i..<sql.endIndex)
        if let ir = ifRange {
            i = ir.upperBound
            skipWS()
            if sql[i...].hasPrefix("NOT") {
                let nr = sql.range(of: "NOT", options: [], range: i..<sql.endIndex)!
                i = nr.upperBound
                skipWS()
            }
            if sql[i...].hasPrefix("EXISTS") {
                let er = sql.range(of: "EXISTS", options: [], range: i..<sql.endIndex)!
                i = er.upperBound
                skipWS()
            }
        }
    }

    guard i < sql.endIndex && sql[i] == "(" else { return [] }
    i = sql.index(after: i)

    // Split by commas at depth 0
    var defs: [String] = []
    var current = ""
    var depth = 0
    while i < sql.endIndex {
        let ch = sql[i]
        if ch == "(" {
            depth += 1
            current.append(ch)
        } else if ch == ")" {
            if depth == 0 { break }
            depth -= 1
            current.append(ch)
        } else if ch == "," && depth == 0 {
            defs.append(current)
            current = ""
        } else {
            current.append(ch)
        }
        i = sql.index(after: i)
    }
    if !current.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
        defs.append(current)
    }

    var columns: [ColumnInfo] = []
    for def in defs {
        let trimmed = def.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { continue }

        var colName: String
        var ci = trimmed.startIndex
        if ci < trimmed.endIndex && trimmed[ci] == "\"" {
            ci = trimmed.index(after: ci)
            var ns = ""
            while ci < trimmed.endIndex && trimmed[ci] != "\"" {
                ns.append(trimmed[ci]); ci = trimmed.index(after: ci)
            }
            if ci < trimmed.endIndex { ci = trimmed.index(after: ci) }
            colName = ns
        } else {
            var ns = ""
            while ci < trimmed.endIndex && (trimmed[ci].isLetter || trimmed[ci].isNumber || trimmed[ci] == "_" || trimmed[ci] == "$" || trimmed[ci] == "@") {
                ns.append(trimmed[ci]); ci = trimmed.index(after: ci)
            }
            colName = ns
        }

        let rest = String(trimmed[ci...]).trimmingCharacters(in: .whitespacesAndNewlines)
        let restUpper = rest.uppercased()
        let hasPK = restUpper.contains("PRIMARY KEY")

        var isAlias = false
        if hasPK {
            // Extract first word (type name) from rest
            var typeWord = ""
            var ti = rest.startIndex
            while ti < rest.endIndex && (rest[ti].isLetter || rest[ti].isNumber || rest[ti] == "_") {
                typeWord.append(rest[ti]); ti = rest.index(after: ti)
            }
            if typeWord.uppercased() == "INTEGER" {
                isAlias = true
            }
        }

        columns.append(ColumnInfo(name: colName, isRowidAlias: isAlias))
    }
    return columns
}

// MARK: - Value formatting
func formatDouble(_ d: Double) -> String {
    if d.isNaN { return "NaN" }
    if d.isInfinite { return d > 0 ? "Inf" : "-Inf" }
    var s = String(format: "%.8f", d)
    if s.contains(".") {
        while s.hasSuffix("0") { s.removeLast() }
        if s.hasSuffix(".") { s.append("0") }
    }
    return s
}

func formatText(_ bytes: [UInt8]) -> String {
    guard let str = String(bytes: bytes, encoding: .utf8) else {
        var r = "\""
        for b in bytes {
            if b == 0x5C { r += "\\\\" }
            else if b == 0x22 { r += "\\\"" }
            else if b == 0x0A { r += "\\n" }
            else if b == 0x0D { r += "\\r" }
            else if b == 0x09 { r += "\\t" }
            else if b < 0x20 || b == 0x7F { r += String(format: "\\x%02X", b) }
            else { r.append(Character(UnicodeScalar(b))) }
        }
        r += "\""
        return r
    }
    var result = "\""
    for ch in str {
        if ch == "\\" { result += "\\\\" }
        else if ch == "\"" { result += "\\\"" }
        else if ch == "\n" { result += "\\n" }
        else if ch == "\r" { result += "\\r" }
        else if ch == "\t" { result += "\\t" }
        else {
            let sv = ch.unicodeScalars.first!.value
            if sv < 0x20 || sv == 0x7F {
                result += String(format: "\\x%02X", sv)
            } else {
                result.append(ch)
            }
        }
    }
    result += "\""
    return result
}

func formatBlob(_ bytes: [UInt8]) -> String {
    var r = "X'"
    for b in bytes { r += String(format: "%02X", b) }
    r += "'"
    return r
}

func formatValue(_ v: Value, isRowidAlias: Bool, rowid: Int64) -> String {
    if isRowidAlias { return String(rowid) }
    switch v {
    case .null: return "NULL"
    case .integer(let i): return String(i)
    case .real(let d): return formatDouble(d)
    case .text(let bytes):
        if bytes.count <= 100 { return formatText(bytes) }
        else { return "<TEXT len=\(bytes.count) crc32=\(String(format: "%08x", crc32(bytes)))>" }
    case .blob(let bytes):
        if bytes.count <= 100 { return formatBlob(bytes) }
        else { return "<BLOB len=\(bytes.count) crc32=\(String(format: "%08x", crc32(bytes)))>" }
    }
}

