function parseCSV(text: string): string[][] {
  // Remove UTF-8 BOM if present
  if (text.charCodeAt(0) === 0xFEFF) {
    text = text.slice(1);
  }
  const records: string[][] = [];
  let i = 0;
  while (i < text.length) {
    const record: string[] = [];
    let field = '';
    let inQuotes = false;
    let endOfRecord = false;
    while (!endOfRecord) {
      if (i >= text.length) {
        record.push(field);
        endOfRecord = true;
      } else if (inQuotes) {
        const ch = text[i];
        if (ch === '"') {
          if (i + 1 < text.length && text[i + 1] === '"') {
            field += '"';
            i += 2;
          } else {
            inQuotes = false;
            i++;
          }
        } else {
          field += ch;
          i++;
        }
      } else {
        const ch = text[i];
        if (ch === '"') {
          inQuotes = true;
          i++;
        } else if (ch === ',') {
          record.push(field);
          field = '';
          i++;
        } else if (ch === '\r' && i + 1 < text.length && text[i + 1] === '\n') {
          record.push(field);
          field = '';
          i += 2;
          endOfRecord = true;
        } else if (ch === '\n') {
          record.push(field);
          field = '';
          i++;
          endOfRecord = true;
        } else {
          field += ch;
          i++;
        }
      }
    }
    if (record.length > 0) {
      records.push(record);
    }
  }
  return records;
}

interface InventoryRow {
  sku: string;
  name: string;
  price_cents: number;
  currency: string;
  stock: number;
}

function executeTool(
  name: string,
  argsStr: string,
  inventory: Map<string, InventoryRow>,
  rates: { scale: number; rates: Record<string, number> }
): string {
  if (name === 'inventory_lookup') {
    const args = JSON.parse(argsStr);
    const sku = args.sku as string;
    const row = inventory.get(sku);
    if (row) {
      return JSON.stringify({
        sku: row.sku,
        name: row.name,
        price_cents: row.price_cents,
        currency: row.currency,
        stock: row.stock,
      });
    } else {
      return JSON.stringify({ error: `unknown sku: ${sku}` });
    }
  } else if (name === 'convert_currency') {
    const args = JSON.parse(argsStr);
    const amountCents = args.amount_cents as number;
    const from = args.from as string;
    const to = args.to as string;
    const rateFrom = BigInt(rates.rates[from]);
    const rateTo = BigInt(rates.rates[to]);
    const amount = BigInt(amountCents);
    // HALF_UP: (2 * amount * rateTo + rateFrom) / (2 * rateFrom), integer division (floor)
    const converted = (2n * amount * rateTo + rateFrom) / (2n * rateFrom);
    return JSON.stringify({ amount_cents: Number(converted), currency: to });
  } else {
    return JSON.stringify({ error: `unknown tool: ${name}` });
  }
}

function httpRequest(
  url: URL,
  headers: Record<string, string>,
  body: string
): Promise<{ status: number; body: string }> {
  return new Promise((resolve, reject) => {
    const port = url.port ? parseInt(url.port, 10) : 80;
    const req = http.request(
      {
        hostname: url.hostname,
        port,
        path: url.pathname,
        method: 'POST',
        headers: {
          Host: url.port ? `${url.hostname}:${url.port}` : url.hostname,
          ...headers,
          'Content-Length': Buffer.byteLength(body).toString(),
        },
      },
      (res) => {
        const chunks: Buffer[] = [];
        res.on('data', (chunk: Buffer) => chunks.push(chunk));
        res.on('end', () => {
          resolve({
            status: res.statusCode || 0,
            body: Buffer.concat(chunks).toString('utf-8'),
          });
        });
        res.on('error', reject);
      }
    );
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

async function main(): Promise<void> {
  const dataDir = process.argv[2];
  const baseUrl = process.argv[3];

  // Read input files
  const task = JSON.parse(fs.readFileSync(path.join(dataDir, 'task.json'), 'utf-8'));
  const csvRaw = fs.readFileSync(path.join(dataDir, 'inventory.csv'), 'utf-8');
  const rates = JSON.parse(fs.readFileSync(path.join(dataDir, 'rates.json'), 'utf-8'));

  // Parse inventory CSV
  const csvRecords = parseCSV(csvRaw);
  const inventory = new Map<string, InventoryRow>();
  for (let i = 1; i < csvRecords.length; i++) {
    const rec = csvRecords[i];
    if (rec.length >= 5) {
      inventory.set(rec[0], {
        sku: rec[0],
        name: rec[1],
        price_cents: parseInt(rec[2], 10),
        currency: rec[3],
        stock: parseInt(rec[4], 10),
      });
    }
  }

  // Build endpoint URL
  const url = new URL(baseUrl + '/chat/completions');

  // Build conversation
  const messages: any[] = [
    { role: 'system', content: task.system },
    { role: 'user', content: task.user },
  ];

  const outputLines: string[] = [];
  let totalPrompt = 0;
  let totalCompletion = 0;
  let totalTotal = 0;
  let requestCount = 0;

  // Tool-calling loop
  while (true) {
    const body = JSON.stringify({
      model: task.model,
      messages: messages,
      tools: task.tools,
      tool_choice: 'auto',
    });

    const res = await httpRequest(url, {
      Authorization: `Bearer ${task.api_key}`,
      'Content-Type': 'application/json',
    }, body);

    requestCount++;

    if (res.status !== 200) {
      for (const line of outputLines) {
        console.log(line);
      }
      try {
        const errBody = JSON.parse(res.body);
        console.log(`ERROR ${res.status} ${errBody.error.message}`);
      } catch {
        console.log(`ERROR ${res.status} `);
      }
      process.exit(0);
    }

    const resp = JSON.parse(res.body);

    // Accumulate usage
    if (resp.usage) {
      totalPrompt += resp.usage.prompt_tokens || 0;
      totalCompletion += resp.usage.completion_tokens || 0;
      totalTotal += resp.usage.total_tokens || 0;
    }

    const choice = resp.choices[0];
    const finishReason = choice.finish_reason;
    const msg = choice.message;

    if (finishReason === 'stop') {
      outputLines.push(`FINAL ${msg.content}`);
      for (const line of outputLines) {
        console.log(line);
      }
      console.log(
        `USAGE prompt=${totalPrompt} completion=${totalCompletion} total=${totalTotal} requests=${requestCount}`
      );
      process.exit(0);
    }

    // finish_reason === 'tool_calls'
    if (msg.content !== null && msg.content !== undefined) {
      outputLines.push(`SAY ${msg.content}`);
    }

    // Append assistant message exactly as received (keep role, content, tool_calls)
    const assistantMsg: any = { role: 'assistant', content: msg.content };
    if (msg.tool_calls && msg.tool_calls.length > 0) {
      assistantMsg.tool_calls = msg.tool_calls.map((tc: any) => ({
        id: tc.id,
        type: tc.type,
        function: { name: tc.function.name, arguments: tc.function.arguments },
      }));
    }
    messages.push(assistantMsg);

    // Print CALL lines
    for (const tc of msg.tool_calls) {
      outputLines.push(`CALL ${tc.id} ${tc.function.name}`);
    }

    // Execute tools and print RESULT lines
    for (const tc of msg.tool_calls) {
      const result = executeTool(tc.function.name, tc.function.arguments, inventory, rates);
      outputLines.push(`RESULT ${tc.id} ${result}`);
      messages.push({ role: 'tool', tool_call_id: tc.id, content: result });
    }
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {

    // ─── JSON Parser ───────────────────────────────────────────────────────────
    static class JsonParser {
        private final String s;
        private int pos;

        JsonParser(String s) { this.s = s; this.pos = 0; }

        Object parse() { skipWs(); Object v = val(); skipWs(); return v; }

        private Object val() {
            skipWs();
            char c = s.charAt(pos);
            if (c == '{') return obj();
            if (c == '[') return arr();
            if (c == '"') return str();
            if (c == 't') { pos += 4; return Boolean.TRUE; }
            if (c == 'f') { pos += 5; return Boolean.FALSE; }
            if (c == 'n') { pos += 4; return null; }
            return num();
        }

        private Map<String, Object> obj() {
            Map<String, Object> m = new LinkedHashMap<>();
            pos++;
            skipWs();
            if (pos < s.length() && s.charAt(pos) == '}') { pos++; return m; }
            while (true) {
                skipWs();
                String k = str();
                skipWs();
                pos++; // ':'
                m.put(k, val());
                skipWs();
                if (pos >= s.length()) break;
                if (s.charAt(pos) == ',') { pos++; continue; }
                if (s.charAt(pos) == '}') { pos++; break; }
                break;
            }
            return m;
        }

        private List<Object> arr() {
            List<Object> a = new ArrayList<>();
            pos++;
            skipWs();
            if (pos < s.length() && s.charAt(pos) == ']') { pos++; return a; }
            while (true) {
                a.add(val());
                skipWs();
                if (pos >= s.length()) break;
                if (s.charAt(pos) == ',') { pos++; continue; }
                if (s.charAt(pos) == ']') { pos++; break; }
                break;
            }
            return a;
        }

        private String str() {
            pos++;
            StringBuilder sb = new StringBuilder();
            while (pos < s.length()) {
                char c = s.charAt(pos);
                if (c == '"') { pos++; return sb.toString(); }
                if (c == '\\') {
                    pos++;
                    char e = s.charAt(pos);
                    switch (e) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u': {
                            int hi = Integer.parseInt(s.substring(pos + 1, pos + 5), 16);
                            pos += 4;
                            if (Character.isHighSurrogate((char) hi)
                                    && pos + 1 < s.length() && s.charAt(pos + 1) == '\\') {
                                pos++; // skip '\'
                                pos++; // skip 'u'
                                int lo = Integer.parseInt(s.substring(pos + 1, pos + 5), 16);
                                pos += 4;
                                sb.appendCodePoint(Character.toCodePoint((char) hi, (char) lo));
                            } else {
                                sb.append((char) hi);
                            }
                            break;
                        }
                        default: sb.append(e);
                    }
                } else {
                    sb.append(c);
                }
                pos++;
            }
            throw new RuntimeException("Unterminated string");
        }

        private Number num() {
            int start = pos;
            if (pos < s.length() && s.charAt(pos) == '-') pos++;
            while (pos < s.length() && s.charAt(pos) >= '0' && s.charAt(pos) <= '9') pos++;
            boolean fl = false;
            if (pos < s.length() && s.charAt(pos) == '.') { fl = true; pos++;
                while (pos < s.length() && s.charAt(pos) >= '0' && s.charAt(pos) <= '9') pos++; }
            if (pos < s.length() && (s.charAt(pos) == 'e' || s.charAt(pos) == 'E')) { fl = true; pos++;
                if (pos < s.length() && (s.charAt(pos) == '+' || s.charAt(pos) == '-')) pos++;
                while (pos < s.length() && s.charAt(pos) >= '0' && s.charAt(pos) <= '9') pos++; }
            String ns = s.substring(start, pos);
            return fl ? (Number) Double.parseDouble(ns) : (Number) Long.parseLong(ns);
        }

        private void skipWs() {
            while (pos < s.length()) {
                char c = s.charAt(pos);
                if (c == ' ' || c == '\t' || c == '\n' || c == '\r') pos++; else break;
            }
        }
    }

    // ─── JSON Serializer ───────────────────────────────────────────────────────
    @SuppressWarnings("unchecked")
    static String toJson(Object obj) {
        StringBuilder sb = new StringBuilder();
        wj(sb, obj);
        return sb.toString();
    }

    @SuppressWarnings("unchecked")
    static void wj(StringBuilder sb, Object obj) {
        if (obj == null) { sb.append("null"); return; }
        if (obj instanceof String) {
            sb.append('"');
            String str = (String) obj;
            for (int i = 0; i < str.length(); i++) {
                char c = str.charAt(i);
                switch (c) {
                    case '"': sb.append("\\\""); break;
                    case '\\': sb.append("\\\\"); break;
                    case '\n': sb.append("\\n"); break;
                    case '\r': sb.append("\\r"); break;
                    case '\t': sb.append("\\t"); break;
                    case '\b': sb.append("\\b"); break;
                    case '\f': sb.append("\\f"); break;
                    default:
                        if (c < 0x20) sb.append(String.format("\\u%04x", (int) c));
                        else sb.append(c);
                }
            }
            sb.append('"');
        } else if (obj instanceof Long || obj instanceof Integer) {
            sb.append(obj);
        } else if (obj instanceof Double) {
            double d = (Double) obj;
            if (d == Math.floor(d) && !Double.isInfinite(d)) sb.append((long) d);
            else sb.append(d);
        } else if (obj instanceof Boolean) {
            sb.append(obj);
        } else if (obj instanceof Map) {
            sb.append('{');
            boolean first = true;
            for (Map.Entry<String, Object> e : ((Map<String, Object>) obj).entrySet()) {
                if (!first) sb.append(',');
                first = false;
                sb.append('"');
                for (int i = 0; i < e.getKey().length(); i++) {
                    char c = e.getKey().charAt(i);
                    if (c == '"') sb.append("\\\"");
                    else if (c == '\\') sb.append("\\\\");
                    else sb.append(c);
                }
                sb.append("\":");
                wj(sb, e.getValue());
            }
            sb.append('}');
        } else if (obj instanceof List) {
            sb.append('[');
            boolean first = true;
            for (Object item : (List<Object>) obj) {
                if (!first) sb.append(',');
                first = false;
                wj(sb, item);
            }
            sb.append(']');
        }
    }

    // ─── Output escaping ───────────────────────────────────────────────────────
    static String esc(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '\\') sb.append("\\\\");
            else if (c == '\n') sb.append("\\n");
            else if (c == '\r') sb.append("\\r");
            else if (c == '\t') sb.append("\\t");
            else sb.append(c);
        }
        return sb.toString();
    }

    // ─── HTTP ──────────────────────────────────────────────────────────────────
    static class HttpResponse { int status; String body; }

    static HttpResponse sendRequest(String host, int port, String path, String apiKey, String body) throws Exception {
        Socket sock = new Socket(host, port);
        try {
            OutputStream out = sock.getOutputStream();
            byte[] bb = body.getBytes(StandardCharsets.UTF_8);
            StringBuilder h = new StringBuilder();
            h.append("POST ").append(path).append(" HTTP/1.1\r\n");
            h.append("Host: ").append(host);
            if (port != 80) h.append(':').append(port);
            h.append("\r\n");
            h.append("Content-Length: ").append(bb.length).append("\r\n");
            h.append("x-api-key: ").append(apiKey).append("\r\n");
            h.append("anthropic-version: 2023-06-01\r\n");
            h.append("content-type: application/json\r\n");
            h.append("\r\n");
            out.write(h.toString().getBytes(StandardCharsets.UTF_8));
            out.write(bb);
            out.flush();

            InputStream in = sock.getInputStream();
            HttpResponse resp = new HttpResponse();
            String sl = readLine(in);
            resp.status = Integer.parseInt(sl.split(" ")[1]);

            Map<String, String> hdrs = new LinkedHashMap<>();
            String ln;
            while ((ln = readLine(in)) != null && !ln.isEmpty()) {
                int ci = ln.indexOf(':');
                if (ci >= 0) hdrs.put(ln.substring(0, ci).trim().toLowerCase(), ln.substring(ci + 1).trim());
            }

            if ("chunked".equalsIgnoreCase(hdrs.get("transfer-encoding"))) {
                resp.body = new String(readChunked(in), StandardCharsets.UTF_8);
            } else if (hdrs.containsKey("content-length")) {
                resp.body = new String(readN(in, Integer.parseInt(hdrs.get("content-length"))), StandardCharsets.UTF_8);
            } else {
                resp.body = new String(readAll(in), StandardCharsets.UTF_8);
            }
            return resp;
        } finally { sock.close(); }
    }

    static String readLine(InputStream in) throws IOException {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = in.read()) != -1) {
            if (c == '\n') break;
            if (c == '\r') { in.mark(1); int n = in.read(); if (n != '\n' && n != -1) in.reset(); break; }
            sb.append((char) c);
        }
        if (c == -1 && sb.length() == 0) return null;
        return sb.toString();
    }

    static byte[] readChunked(InputStream in) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        while (true) {
            String ln = readLine(in);
            if (ln == null) break;
            int si = ln.indexOf(';');
            String sz = (si >= 0 ? ln.substring(0, si) : ln).trim();
            if (sz.isEmpty()) continue;
            int cs = Integer.parseInt(sz, 16);
            if (cs == 0) { while ((ln = readLine(in)) != null && !ln.isEmpty()) {} break; }
            baos.write(readN(in, cs));
            readLine(in);
        }
        return baos.toByteArray();
    }

    static byte[] readN(InputStream in, int n) throws IOException {
        byte[] buf = new byte[n]; int off = 0;
        while (off < n) { int r = in.read(buf, off, n - off); if (r == -1) break; off += r; }
        return Arrays.copyOf(buf, off);
    }

    static byte[] readAll(InputStream in) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        byte[] buf = new byte[65536]; int r;
        while ((r = in.read(buf)) != -1) baos.write(buf, 0, r);
        return baos.toByteArray();
    }

    // ─── SSE Parsing ───────────────────────────────────────────────────────────
    @SuppressWarnings("unchecked")
    static List<Map<String, Object>> parseSse(String data) {
        List<Map<String, Object>> events = new ArrayList<>();
        String[] lines = data.split("\r?\n", -1);
        String evType = null;
        List<String> dataLines = new ArrayList<>();
        for (String line : lines) {
            if (line.isEmpty()) {
                if (evType != null || !dataLines.isEmpty()) {
                    String d = String.join("\n", dataLines);
                    if (!d.isEmpty()) {
                        try {
                            Map<String, Object> ev = (Map<String, Object>) new JsonParser(d).parse();
                            ev.put("_ev", evType);
                            events.add(ev);
                        } catch (Exception ignored) {}
                    }
                    evType = null;
                    dataLines.clear();
                }
            } else if (line.charAt(0) == ':') {
                // comment
            } else if (line.startsWith("event:")) {
                evType = line.substring(6);
                if (!evType.isEmpty() && evType.charAt(0) == ' ') evType = evType.substring(1);
            } else if (line.startsWith("data:")) {
                String v = line.substring(5);
                if (!v.isEmpty() && v.charAt(0) == ' ') v = v.substring(1);
                dataLines.add(v);
            }
        }
        if (evType != null || !dataLines.isEmpty()) {
            String d = String.join("\n", dataLines);
            if (!d.isEmpty()) {
                try {
                    Map<String, Object> ev = (Map<String, Object>) new JsonParser(d).parse();
                    ev.put("_ev", evType);
                    events.add(ev);
                } catch (Exception ignored) {}
            }
        }
        return events;
    }

    // ─── Content Blocks ────────────────────────────────────────────────────────
    static class Block {
        int index;
        String type;
        StringBuilder thinking = new StringBuilder();
        StringBuilder signature = new StringBuilder();
        StringBuilder text = new StringBuilder();
        String toolId;
        String toolName;
        StringBuilder inputJson = new StringBuilder();
    }

    static class ReplyResult {
        List<Block> blocks = new ArrayList<>();
        String stopReason;
        long inputTokens, outputTokens, cacheReadTokens;
    }

    @SuppressWarnings("unchecked")
    static ReplyResult processEvents(List<Map<String, Object>> events) {
        ReplyResult rr = new ReplyResult();
        Map<Integer, Block> bm = new LinkedHashMap<>();
        for (Map<String, Object> ev : events) {
            String type = (String) ev.get("_ev");
            if (type == null) continue;
            switch (type) {
                case "message_start": {
                    Map<String, Object> msg = (Map<String, Object>) ev.get("message");
                    if (msg != null) {
                        Map<String, Object> u = (Map<String, Object>) msg.get("usage");
                        if (u != null) {
                            if (u.containsKey("input_tokens")) rr.inputTokens += ((Number) u.get("input_tokens")).longValue();
                            if (u.containsKey("cache_read_input_tokens")) rr.cacheReadTokens += ((Number) u.get("cache_read_input_tokens")).longValue();
                        }
                    }
                    break;
                }
                case "content_block_start": {
                    int idx = ((Number) ev.get("index")).intValue();
                    Map<String, Object> cb = (Map<String, Object>) ev.get("content_block");
                    Block b = new Block();
                    b.index = idx;
                    b.type = (String) cb.get("type");
                    if ("tool_use".equals(b.type)) {
                        b.toolId = (String) cb.get("id");
                        b.toolName = (String) cb.get("name");
                    }
                    bm.put(idx, b);
                    break;
                }
                case "content_block_delta": {
                    int idx = ((Number) ev.get("index")).intValue();
                    Block b = bm.get(idx);
                    if (b == null) break;
                    Map<String, Object> d = (Map<String, Object>) ev.get("delta");
                    String dt = (String) d.get("type");
                    if ("thinking_delta".equals(dt)) b.thinking.append((String) d.get("thinking"));
                    else if ("signature_delta".equals(dt)) b.signature.append((String) d.get("signature"));
                    else if ("text_delta".equals(dt)) b.text.append((String) d.get("text"));
                    else if ("input_json_delta".equals(dt)) b.inputJson.append((String) d.get("partial_json"));
                    break;
                }
                case "content_block_stop": break;
                case "message_delta": {
                    Map<String, Object> d = (Map<String, Object>) ev.get("delta");
                    if (d != null && d.containsKey("stop_reason")) rr.stopReason = (String) d.get("stop_reason");
                    Map<String, Object> u = (Map<String, Object>) ev.get("usage");
                    if (u != null && u.containsKey("output_tokens")) rr.outputTokens += ((Number) u.get("output_tokens")).longValue();
                    break;
                }
                default: break;
            }
        }
        rr.blocks = new ArrayList<>(bm.values());
        rr.blocks.sort(Comparator.comparingInt(b -> b.index));
        return rr;
    }

    // ─── Tools ─────────────────────────────────────────────────────────────────
    static String[] executeTool(String name, Map<String, Object> input) {
        // returns {result, isError("true"/"false")}
        if ("measure".equals(name)) {
            String text = (String) input.get("text");
            String unit = (String) input.get("unit");
            if ("code_points".equals(unit))
                return new String[]{String.valueOf(text.codePointCount(0, text.length())), "false"};
            else if ("utf8_bytes".equals(unit))
                return new String[]{String.valueOf(text.getBytes(StandardCharsets.UTF_8).length), "false"};
            else if ("utf16_units".equals(unit))
                return new String[]{String.valueOf(text.length()), "false"};
            else
                return new String[]{"unsupported unit: " + unit, "true"};
        } else if ("reverse".equals(name)) {
            String text = (String) input.get("text");
            int[] cps = text.codePoints().toArray();
            StringBuilder sb = new StringBuilder();
            for (int i = cps.length - 1; i >= 0; i--) sb.appendCodePoint(cps[i]);
            return new String[]{sb.toString(), "false"};
        } else {
            return new String[]{"unknown tool: " + name, "true"};
        }
    }

    // ─── Print helpers ─────────────────────────────────────────────────────────
    static void printBlocks(List<Block> blocks) {
        for (Block b : blocks) {
            if ("thinking".equals(b.type)) {
                System.out.println("thinking " + esc(b.thinking.toString()));
                System.out.println("signature " + esc(b.signature.toString()));
            } else if ("text".equals(b.type)) {
                System.out.println("text " + esc(b.text.toString()));
            } else if ("tool_use".equals(b.type)) {
                System.out.println("tool_use " + b.toolId + " " + b.toolName + " " + esc(b.inputJson.toString()));
            }
        }
    }

    @SuppressWarnings("unchecked")
    static List<Object> buildAssistantContent(List<Block> blocks) {
        List<Object> content = new ArrayList<>();
        for (Block b : blocks) {
            Map<String, Object> cb = new LinkedHashMap<>();
            if ("thinking".equals(b.type)) {
                cb.put("type", "thinking");
                cb.put("thinking", b.thinking.toString());
                cb.put("signature", b.signature.toString());
            } else if ("text".equals(b.type)) {
                cb.put("type", "text");
                cb.put("text", b.text.toString());
            } else if ("tool_use".equals(b.type)) {
                cb.put("type", "tool_use");
                cb.put("id", b.toolId);
                cb.put("name", b.toolName);
                cb.put("input", new JsonParser(b.inputJson.toString()).parse());
            }
            content.add(cb);
        }
        return content;
    }

    static List<Object> buildToolResults(List<Block> blocks, List<String[]> results) {
        List<Object> content = new ArrayList<>();
        int ri = 0;
        for (Block b : blocks) {
            if ("tool_use".equals(b.type)) {
                Map<String, Object> tr = new LinkedHashMap<>();
                tr.put("type", "tool_result");
                tr.put("tool_use_id", b.toolId);
                tr.put("content", results.get(ri)[0]);
                if ("true".equals(results.get(ri)[1])) tr.put("is_error", true);
                content.add(tr);
                ri++;
            }
        }
        return content;
    }

    // ─── Main ──────────────────────────────────────────────────────────────────
    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws Exception {
        String dataDir = args[0];
        String baseUrl = args[1];

        URL url = new URL(baseUrl + "/v1/messages");
        String host = url.getHost();
        int port = url.getPort() == -1 ? url.getDefaultPort() : url.getPort();
        String path = url.getPath();

        String reqJson = new String(Files.readAllBytes(Path.of(dataDir, "request.json")), StandardCharsets.UTF_8);
        Map<String, Object> req = (Map<String, Object>) new JsonParser(reqJson).parse();

        String apiKey = (String) req.get("api_key");
        Object model = req.get("model");
        Object maxTokens = req.get("max_tokens");
        Object thinkingBudget = req.get("thinking_budget");
        Object system = req.get("system");
        String prompt = (String) req.get("prompt");
        Object tools = req.get("tools");

        // Request 1
        Map<String, Object> userMsg = new LinkedHashMap<>();
        userMsg.put("role", "user");
        userMsg.put("content", prompt);

        List<Object> messages1 = new ArrayList<>();
        messages1.add(userMsg);

        Map<String, Object> body1 = new LinkedHashMap<>();
        body1.put("model", model);
        body1.put("max_tokens", maxTokens);
        body1.put("stream", true);
