        th.put("budget_tokens", thinkingBudget);
        body1.put("thinking", th);
        body1.put("system", system);
        body1.put("tools", tools);
        body1.put("messages", messages1);

        System.out.println("request 1");
        HttpResponse resp1 = sendRequest(host, port, path, apiKey, toJson(body1));
