        List<String[]> toolResults = new ArrayList<>();
        for (Block b : rr1.blocks) {
            if ("tool_use".equals(b.type)) {
                Map<String, Object> input = (Map<String, Object>) new JsonParser(b.inputJson.toString()).parse();
                String[] res = executeTool(b.toolName, input);
                toolResults.add(res);
                if ("true".equals(res[1]))
                    System.out.println("error " + b.toolId + " " + esc(res[0]));
                else
                    System.out.println("result " + b.toolId + " " + esc(res[0]));
            }
        }

        // Request 2
        List<Object> messages2 = new ArrayList<>();
        messages2.add(userMsg);
        Map<String, Object> asMsg = new LinkedHashMap<>();
        asMsg.put("role", "assistant");
        asMsg.put("content", buildAssistantContent(rr1.blocks));
        messages2.add(asMsg);
        Map<String, Object> trMsg = new LinkedHashMap<>();
        trMsg.put("role", "user");
        trMsg.put("content", buildToolResults(rr1.blocks, toolResults));
        messages2.add(trMsg);

        Map<String, Object> body2 = new LinkedHashMap<>();
        body2.put("model", model);
        body2.put("max_tokens", maxTokens);
        body2.put("stream", true);
        Map<String, Object> th2 = new LinkedHashMap<>();
        th2.put("type", "enabled");
        th2.put("budget_tokens", thinkingBudget);
        body2.put("thinking", th2);
        body2.put("system", system);
        body2.put("tools", tools);
        body2.put("messages", messages2);

        System.out.println("request 2");
        HttpResponse resp2 = sendRequest(host, port, path, apiKey, toJson(body2));
        if (resp2.status != 200) {
            Map<String, Object> eb = (Map<String, Object>) new JsonParser(resp2.body).parse();
            Map<String, Object> er = (Map<String, Object>) eb.get("error");
            System.out.println("ERROR " + resp2.status + " " + er.get("type") + ": " + er.get("message"));
            return;
        }

        ReplyResult rr2 = processEvents(parseSse(resp2.body));
        printBlocks(rr2.blocks);
        System.out.println("stop_reason " + rr2.stopReason);

        System.out.println("usage input=" + (rr1.inputTokens + rr2.inputTokens)
                + " output=" + (rr1.outputTokens + rr2.outputTokens)
                + " cache_read=" + (rr1.cacheReadTokens + rr2.cacheReadTokens));
    }
