            if(nmsgs+1>mcap){mcap*=2;msgs=realloc(msgs,mcap*sizeof(char*));}
            memmove(&msgs[tool_start+1],&msgs[tool_start],ntc*sizeof(char*));
            msgs[tool_start]=as_raw;
            nmsgs++;

        }else{
            /* finish_reason == "stop" */
            JV*j_content=jget(j_msg,"content");
            const char*final_content=j_content&&j_content->type==J_STR?j_content->s:"";
            sb_puts(&out,"FINAL ");sb_puts(&out,final_content);sb_putc(&out,'\n');
            break;
        }
    }

    /* Print output */
    fwrite(out.data,1,out.len,stdout);
    printf("USAGE prompt=%lld completion=%lld total=%lld requests=%d\n",tot_prompt,tot_comp,tot_total,nreq);
    fflush(stdout);
    return 0;
}

