        int type = data[pageStart + headerOffset] & 0xFF;
        int numCells = readUint16(pageStart + headerOffset + 3);
        int cellPtrStart = pageStart + headerOffset + (type == 5 ? 12 : 8);

        if (type == 13) {
            // Leaf table b-tree
            for (int i = 0; i < numCells; i++) {
                int cellPtr = readUint16(cellPtrStart + i * 2);
                int cellOffset = pageStart + cellPtr;

                long[] vr = readVarint(data, cellOffset);
                long totalPayload = vr[0];
                int pos = (int) vr[1];

                vr = readVarint(data, pos);
                long rowid = vr[0];
                pos = (int) vr[1];

                int maxLocal = usableSize - 35;
                int localSize;
                if (totalPayload <= maxLocal) {
                    localSize = (int) totalPayload;
                } else {
                    long k = maxLocal + (totalPayload - maxLocal) % (usableSize - 4);
                    if (k <= maxLocal) {
                        localSize = (int) k;
                    } else {
                        localSize = maxLocal;
                    }
                }

                byte[] payload = Arrays.copyOfRange(data, pos, pos + localSize);

                if (totalPayload > maxLocal) {
                    int overflowPage = readUint32(pos + localSize);
                    byte[] fullPayload = new byte[(int) totalPayload];
                    System.arraycopy(payload, 0, fullPayload, 0, localSize);
                    int remaining = (int)(totalPayload - localSize);
                    int written = localSize;
                    while (overflowPage != 0 && remaining > 0) {
                        int opStart = (overflowPage - 1) * pageSize;
                        int chunkSize = Math.min(remaining, usableSize - 4);
                        System.arraycopy(data, opStart + 4, fullPayload, written, chunkSize);
                        written += chunkSize;
                        remaining -= chunkSize;
                        overflowPage = readUint32(opStart);
                    }
                    payload = fullPayload;
                }

                rowids.add(rowid);
                payloads.add(payload);
            }
        } else if (type == 5) {
            // Interior table b-tree
            int rightmost = readUint32(pageStart + headerOffset + 8);
            for (int i = 0; i < numCells; i++) {
                int cellPtr = readUint16(cellPtrStart + i * 2);
                int cellOffset = pageStart + cellPtr;
                int leftChild = readUint32(cellOffset);
                walkBTree(leftChild, 0, rowids, payloads);
            }
            walkBTree(rightmost, 0, rowids, payloads);
        }
