    static int readUint16(int offset) {
        return ((data[offset] & 0xFF) << 8) | (data[offset + 1] & 0xFF);
    }

    static int readUint32(int offset) {
        return ((data[offset] & 0xFF) << 24) | ((data[offset + 1] & 0xFF) << 16) |
               ((data[offset + 2] & 0xFF) << 8) | (data[offset + 3] & 0xFF);
    }

    static long[] readVarint(byte[] buf, int pos) {
        long result = 0;
        for (int i = 0; i < 8; i++) {
            byte b = buf[pos + i];
            result = (result << 7) | (b & 0x7F);
            if ((b & 0x80) == 0) {
                return new long[]{result, pos + i + 1};
            }
        }
        result = (result << 8) | (buf[pos + 8] & 0xFF);
        return new long[]{result, pos + 9};
    }

    static List<Val> parseRecord(byte[] payload) {
        List<Val> values = new ArrayList<>();
        int pos = 0;

        long[] vr = readVarint(payload, pos);
        int headerSize = (int) vr[0];
        pos = (int) vr[1];

        List<Long> serialTypes = new ArrayList<>();
        while (pos < headerSize) {
            vr = readVarint(payload, pos);
            serialTypes.add(vr[0]);
            pos = (int) vr[1];
        }

        for (long st : serialTypes) {
            if (st == 0) {
                values.add(Val.nul());
            } else if (st >= 1 && st <= 4) {
                int numBytes = (int) st;
                long val = 0;
                for (int i = 0; i < numBytes; i++) {
                    val = (val << 8) | (payload[pos + i] & 0xFF);
                }
                if ((val & (1L << (numBytes * 8 - 1))) != 0) {
                    val -= (1L << (numBytes * 8));
                }
                values.add(Val.integer(val));
                pos += numBytes;
            } else if (st == 5) {
                long val = 0;
                for (int i = 0; i < 8; i++) {
                    val = (val << 8) | (payload[pos + i] & 0xFF);
                }
                values.add(Val.integer(val));
                pos += 8;
            } else if (st == 6) {
                long bits = 0;
                for (int i = 0; i < 8; i++) {
                    bits = (bits << 8) | (payload[pos + i] & 0xFF);
                }
                values.add(Val.real(Double.longBitsToDouble(bits)));
                pos += 8;
            } else if (st == 7) {
                values.add(Val.integer(0));
            } else if (st == 8) {
                values.add(Val.integer(1));
            } else if (st >= 13 && st % 2 == 1) {
                int len = (int)((st - 13) / 2);
                byte[] blob = Arrays.copyOfRange(payload, pos, pos + len);
                values.add(Val.blob(blob));
                pos += len;
            } else if (st >= 12 && st % 2 == 0) {
                int len = (int)((st - 12) / 2);
                byte[] text = Arrays.copyOfRange(payload, pos, pos + len);
                values.add(Val.text(text));
                pos += len;
            } else {
                values.add(Val.nul());
            }
        }
        return values;
    }

    static void parseColumns(String sql, List<String> colNames, List<Boolean> isRowidAlias) {
        String upper = sql.toUpperCase();
        int idx = upper.indexOf("CREATE TABLE");
        if (idx < 0) return;
        idx += "CREATE TABLE".length();

        while (idx < sql.length() && Character.isWhitespace(sql.charAt(idx))) idx++;

        // Skip table name
        if (idx < sql.length() && sql.charAt(idx) == '"') {
            idx++;
            while (idx < sql.length() && sql.charAt(idx) != '"') idx++;
            idx++;
        } else {
            while (idx < sql.length() && !Character.isWhitespace(sql.charAt(idx)) && sql.charAt(idx) != '(') idx++;
        }

        while (idx < sql.length() && Character.isWhitespace(sql.charAt(idx))) idx++;

        if (idx >= sql.length() || sql.charAt(idx) != '(') return;
