    sb_adds(&b,",\"stream\":true");
    sb_adds(&b,",\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":");snprintf(t,32,"%ld",think_bud);sb_adds(&b,t);sb_adds(&b,"}");
    sb_adds(&b,",\"system\":");jser_str(&b,sys);
    sb_adds(&b,",\"tools\":");sb_adds(&b,tools_json);
    sb_adds(&b,",\"messages\":");sb_adds(&b,msgs_json);
    sb_addc(&b,'}');
    return b.data;}

/* ===== Print blocks ===== */
static void print_blocks(resp_t*r){
    for(int i=0;i<r->nblk;i++){cblk*b=&r->blocks[i];
        if(!strcmp(b->type,"thinking")){printf("thinking ");print_esc(b->thinking.data?b->thinking.data:"");printf("\n");
            printf("signature ");print_esc(b->signature.data?b->signature.data:"");printf("\n");}
        else if(!strcmp(b->type,"text")){printf("text ");print_esc(b->text.data?b->text.data:"");printf("\n");}
        else if(!strcmp(b->type,"tool_use")){printf("tool_use ");printf("%s ",b->id);printf("%s ",b->name);
            print_esc(b->input_json.data?b->input_json.data:"");printf("\n");}}
    printf("stop_reason %s\n",r->stop_reason);}

/* ===== Main ===== */
int main(int argc,char**argv){
    if(argc<3){fprintf(stderr,"usage: %s <data_dir> <base_url>\n",argv[0]);return 1;}
    const char*data_dir=argv[1],*base_url=argv[2];

    /* read request.json */
    char fpath[4096];snprintf(fpath,4096,"%s/request.json",data_dir);
    FILE*f=fopen(fpath,"rb");if(!f){perror("open");return 1;}
    fseek(f,0,SEEK_END);long fsz=ftell(f);fseek(f,0,SEEK_SET);
    char*fbuf=malloc(fsz+1);fread(fbuf,1,fsz,f);fbuf[fsz]=0;fclose(f);

    jc jc={fbuf,0,(size_t)fsz};jv*cfg=jparse(&jc);
    const char*api_key=jget(cfg,"api_key")->s;
    const char*model=jget(cfg,"model")->s;
    long max_tok=(long)jget(cfg,"max_tokens")->n;
    long think_bud=(long)jget(cfg,"thinking_budget")->n;
    const char*sys=jget(cfg,"system")->s;
    const char*prompt=jget(cfg,"prompt")->s;
    jv*tools=jget(cfg,"tools");

    /* serialize tools to JSON text */
    sbuf tools_json={0};jser(&tools_json,tools);

    /* Request 1 */
    sbuf m1={0};sb_adds(&m1,"[{\"role\":\"user\",\"content\":");jser_str(&m1,prompt);sb_adds(&m1,"}]");
    char*body1=build_body(model,max_tok,think_bud,sys,tools_json.data,m1.data);

    resp_t r1;send_req(base_url,api_key,body1,&r1);
    printf("request 1\n");
    if(r1.status!=200){print_blocks(&r1);printf("ERROR %d %s: %s\n",r1.status,r1.err_type,r1.err_msg);free(body1);sb_free(&m1);sb_free(&tools_json);free(fbuf);return 0;}
    print_blocks(&r1);

    /* Execute tools */
    typedef struct{char*result;int is_err;}tool_res;
    tool_res tres[64];int nres=0;
    for(int i=0;i<r1.nblk;i++){cblk*b=&r1.blocks[i];
        if(strcmp(b->type,"tool_use"))continue;
        const char*ij=b->input_json.data?b->input_json.data:"{}";
        jc jc2={ij,0,strlen(ij)};jv*inp=jparse(&jc2);
        int ie;char*res=exec_tool(b->name,inp,&ie);
        tres[nres].result=res;tres[nres].is_err=ie;nres++;}

    for(int i=0;i<nres;i++){
        /* find the tool_use block id */
        int bi=0;for(bi=0;bi<r1.nblk;bi++)if(!strcmp(r1.blocks[bi].type,"tool_use")){if(bi==0||1){int cnt=0;for(int j=0;j<r1.nblk;j++)if(!strcmp(r1.blocks[j].type,"tool_use")){if(cnt==i){bi=j;break;}cnt++;}}break;}
        /* simpler: iterate tool_use blocks */
    }
    /* redo tool result printing properly */
    nres=0;
    for(int i=0;i<r1.nblk;i++){cblk*b=&r1.blocks[i];
        if(strcmp(b->type,"tool_use"))continue;
        const char*ij=b->input_json.data?b->input_json.data:"{}";
        jc jc2={ij,0,strlen(ij)};jv*inp=jparse(&jc2);
        int ie;char*res=exec_tool(b->name,inp,&ie);
        if(ie)printf("error ");else printf("result ");
        printf("%s ",b->id);print_esc(res);printf("\n");
        tres[nres].result=res;tres[nres].is_err=ie;nres++;}

    /* Request 2 */
    sbuf m2={0};
    sb_adds(&m2,"[{\"role\":\"user\",\"content\":");jser_str(&m2,prompt);sb_adds(&m2,"},{\"role\":\"assistant\",\"content\":[");
    int first=1;
    for(int i=0;i<r1.nblk;i++){cblk*b=&r1.blocks[i];
        if(!first)sb_addc(&m2,',');first=0;
        if(!strcmp(b->type,"thinking")){sb_adds(&m2,"{\"type\":\"thinking\",\"thinking\":");jser_str(&m2,b->thinking.data?b->thinking.data:"");
            sb_adds(&m2,",\"signature\":");jser_str(&m2,b->signature.data?b->signature.data:"");sb_addc(&m2,'}');}
        else if(!strcmp(b->type,"text")){sb_adds(&m2,"{\"type\":\"text\",\"text\":");jser_str(&m2,b->text.data?b->text.data:"");sb_addc(&m2,'}');}
        else if(!strcmp(b->type,"tool_use")){sb_adds(&m2,"{\"type\":\"tool_use\",\"id\":");jser_str(&m2,b->id);
            sb_adds(&m2,",\"name\":");jser_str(&m2,b->name);sb_adds(&m2,",\"input\":");
            const char*ij=b->input_json.data?b->input_json.data:"{}";
            jc jc3={ij,0,strlen(ij)};jv*pv=jparse(&jc3);jser(&m2,pv);sb_addc(&m2,'}');}}
    sb_adds(&m2,"]},{\"role\":\"user\",\"content\":[");
    int ti=0;first=1;
    for(int i=0;i<r1.nblk;i++){cblk*b=&r1.blocks[i];
        if(strcmp(b->type,"tool_use"))continue;
        if(!first)sb_addc(&m2,',');first=0;
        sb_adds(&m2,"{\"type\":\"tool_result\",\"tool_use_id\":");jser_str(&m2,b->id);
        sb_adds(&m2,",\"content\":");jser_str(&m2,tres[ti].result);
        if(tres[ti].is_err)sb_adds(&m2,",\"is_error\":true");
        sb_addc(&m2,'}');ti++;}
    sb_adds(&m2,"]}]");

    char*body2=build_body(model,max_tok,think_bud,sys,tools_json.data,m2.data);
    resp_t r2;send_req(base_url,api_key,body2,&r2);
    printf("request 2\n");
    if(r2.status!=200){print_blocks(&r2);printf("ERROR %d %s: %s\n",r2.status,r2.err_type,r2.err_msg);
        free(body1);free(body2);sb_free(&m1);sb_free(&m2);sb_free(&tools_json);free(fbuf);return 0;}
    print_blocks(&r2);

    printf("usage input=%ld output=%ld cache_read=%ld\n",r1.in_tok+r2.in_tok,r1.out_tok+r2.out_tok,r1.cr_tok+r2.cr_tok);

    free(body1);free(body2);sb_free(&m1);sb_free(&m2);sb_free(&tools_json);free(fbuf);
    return 0;}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include <ctype.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netdb.h>
#include <stdint.h>
#include <math.h>

/* ===== Dynamic String Buffer ===== */
typedef struct { char *data; size_t len, cap; } sbuf;
static void sb_init(sbuf *s){s->data=NULL;s->len=0;s->cap=0;}
static void sb_free(sbuf *s){free(s->data);s->data=NULL;s->len=0;s->cap=0;}
static void sb_ensure(sbuf *s,size_t x){if(s->len+x+1>s->cap){size_t n=(s->len+x+1)*2;if(n<256)n=256;s->data=realloc(s->data,n);s->cap=n;}}
static void sb_add(sbuf *s,const char *p,size_t n){sb_ensure(s,n);memcpy(s->data+s->len,p,n);s->len+=n;s->data[s->len]=0;}
static void sb_adds(sbuf *s,const char *p){sb_add(s,p,strlen(p));}
static void sb_addc(sbuf *s,char c){sb_ensure(s,1);s->data[s->len++]=c;s->data[s->len]=0;}

/* ===== JSON ===== */
typedef enum{JN,JB,JM,JS,JA,JO}jt;
typedef struct jv{jt t;int b;double n;char*s;struct{struct jv**items;int cnt;}ar;struct{char**keys;struct jv**vals;int cnt;}ob;}jv;
static jv*jnew(jt t){jv*v=calloc(1,sizeof(jv));v->t=t;return v;}

typedef struct{const char*p;size_t pos,len;}jctx;
static void jws(jctx*c){while(c->pos<c->len&&isspace((unsigned char)c->p[c->pos]))c->pos++;}
static jv*jparse(jctx*c);

static jv*jstr(jctx*c){
    c->pos++;sbuf s={0};
    while(c->pos<c->len&&c->p[c->pos]!='"'){
        char ch=c->p[c->pos];
        if(ch=='\\'){c->pos++;char e=c->p[c->pos];
            if(e=='"')sb_addc(&s,'"');
            else if(e=='\\')sb_addc(&s,'\\');
            else if(e=='/')sb_addc(&s,'/');
            else if(e=='b')sb_addc(&s,'\b');
            else if(e=='f')sb_addc(&s,'\f');
            else if(e=='n')sb_addc(&s,'\n');
            else if(e=='r')sb_addc(&s,'\r');
            else if(e=='t')sb_addc(&s,'\t');
            else if(e=='u'){c->pos++;unsigned int cp=0;
                for(int i=0;i<4&&c->pos<c->len;i++,c->pos++){char h=c->p[c->pos];cp<<=4;
                    if(h>='0'&&h<='9')cp|=h-'0';else if(h>='a'&&h<='f')cp|=h-'a'+10;else if(h>='A'&&h<='F')cp|=h-'A'+10;}
                c->pos--;
                if(cp>=0xD800&&cp<=0xDBFF&&c->pos+1<c->len&&c->p[c->pos+1]=='\\'&&c->pos+2<c->len&&c->p[c->pos+2]=='u'){
                    c->pos+=3;unsigned int lo=0;
                    for(int i=0;i<4&&c->pos<c->len;i++,c->pos++){char h=c->p[c->pos];lo<<=4;
                        if(h>='0'&&h<='9')lo|=h-'0';else if(h>='a'&&h<='f')lo|=h-'a'+10;else if(h>='A'&&h<='F')lo|=h-'A'+10;}
                    c->pos--;
                    if(lo>=0xDC00&&lo<=0xDFFF)cp=0x10000+((cp-0xD800)<<10)+(lo-0xDC00);
                }
                if(cp<0x80)sb_addc(&s,(char)cp);
                else if(cp<0x800){sb_addc(&s,(char)(0xC0|(cp>>6)));sb_addc(&s,(char)(0x80|(cp&0x3F)));}
                else if(cp<0x10000){sb_addc(&s,(char)(0xE0|(cp>>12)));sb_addc(&s,(char)(0x80|((cp>>6)&0x3F)));sb_addc(&s,(char)(0x80|(cp&0x3F)));}
                else{sb_addc(&s,(char)(0xF0|(cp>>18)));sb_addc(&s,(char)(0x80|((cp>>12)&0x3F)));sb_addc(&s,(char)(0x80|((cp>>6)&0x3F)));sb_addc(&s,(char)(0x80|(cp&0x3F)));}
            }
            else sb_addc(&s,e);
        }else sb_addc(&s,ch);
        c->pos++;
    }
    c->pos++;jv*v=jnew(JS);v->s=s.data?s.data:strdup("");return v;
}

static jv*jnum(jctx*c){size_t st=c->pos;if(c->pos<c->len&&c->p[c->pos]=='-')c->pos++;
    while(c->pos<c->len&&isdigit((unsigned char)c->p[c->pos]))c->pos++;
    if(c->pos<c->len&&c->p[c->pos]=='.'){c->pos++;while(c->pos<c->len&&isdigit((unsigned char)c->p[c->pos]))c->pos++;}
    if(c->pos<c->len&&(c->p[c->pos]=='e'||c->p[c->pos]=='E')){c->pos++;if(c->pos<c->len&&(c->p[c->pos]=='+'||c->p[c->pos]=='-'))c->pos++;while(c->pos<c->len&&isdigit((unsigned char)c->p[c->pos]))c->pos++;}
    char*tmp=strndup(c->p+st,c->pos-st);jv*v=jnew(JM);v->n=strtod(tmp,NULL);free(tmp);return v;}

static jv*jarr(jctx*c){c->pos++;jv*v=jnew(JA);int cap=8;v->ar.items=malloc(cap*sizeof(jv*));v->ar.cnt=0;
    jws(c);if(c->pos<c->len&&c->p[c->pos]==']'){c->pos++;return v;}
    while(1){jv*it=jparse(c);if(v->ar.cnt>=cap){cap*=2;v->ar.items=realloc(v->ar.items,cap*sizeof(jv*));}
        v->ar.items[v->ar.cnt++]=it;jws(c);if(c->pos<c->len&&c->p[c->pos]==','){c->pos++;jws(c);}else break;}
    if(c->pos<c->len&&c->p[c->pos]==']')c->pos++;return v;}

static jv*jobj(jctx*c){c->pos++;jv*v=jnew(JO);int cap=8;v->ob.keys=malloc(cap*sizeof(char*));v->ob.vals=malloc(cap*sizeof(jv*));v->ob.cnt=0;
    jws(c);if(c->pos<c->len&&c->p[c->pos]=='}'){c->pos++;return v;}
    while(1){jws(c);jv*k=jstr(c);jws(c);c->pos++;jws(c);jv*val=jparse(c);
        if(v->ob.cnt>=cap){cap*=2;v->ob.keys=realloc(v->ob.keys,cap*sizeof(char*));v->ob.vals=realloc(v->ob.vals,cap*sizeof(jv*));}
        v->ob.keys[v->ob.cnt]=k->s;v->ob.vals[v->ob.cnt]=val;free(k);v->ob.cnt++;
        jws(c);if(c->pos<c->len&&c->p[c->pos]==','){c->pos++;}else break;}
    if(c->pos<c->len&&c->p[c->pos]=='}')c->pos++;return v;}

static jv*jparse(jctx*c){jws(c);if(c->pos>=c->len)return jnew(JN);
    char ch=c->p[c->pos];
    if(ch=='"')return jstr(c);if(ch=='{')return jobj(c);if(ch=='[')return jarr(c);
    if(ch=='t'){c->pos+=4;jv*v=jnew(JB);v->b=1;return v;}
    if(ch=='f'){c->pos+=5;jv*v=jnew(JB);v->b=0;return v;}
    if(ch=='n'){c->pos+=4;return jnew(JN);}
    return jnum(c);}

static jv*jget(jv*o,const char*k){if(!o||o->t!=JO)return NULL;for(int i=0;i<o->ob.cnt;i++)if(!strcmp(o->ob.keys[i],k))return o->ob.vals[i];return NULL;}

/* ===== JSON Serializer ===== */
static void jser_str(sbuf*s,const char*p){sb_addc(s,'"');
    while(*p){unsigned char c=(unsigned char)*p;
        if(c=='"')sb_adds(s,"\\\"");else if(c=='\\')sb_adds(s,"\\\\");
        else if(c=='\n')sb_adds(s,"\\n");else if(c=='\r')sb_adds(s,"\\r");
        else if(c=='\t')sb_adds(s,"\\t");
        else if(c<0x20){char t[8];snprintf(t,8,"\\u%04x",c);sb_adds(s,t);}
        else sb_addc(s,*p);
        p++;}
    sb_addc(s,'"');}

static void jser(sbuf*s,jv*v){
    if(!v){sb_adds(s,"null");return;}
    switch(v->t){
    case JN:sb_adds(s,"null");break;
    case JB:sb_adds(s,v->b?"true":"false");break;
    case JM:{if(v->n==(long long)v->n&&fabs(v->n)<1e15){char t[32];snprintf(t,32,"%lld",(long long)v->n);sb_adds(s,t);}else{char t[64];snprintf(t,64,"%.17g",v->n);sb_adds(s,t);}break;}
    case JS:jser_str(s,v->s);break;
    case JA:sb_addc(s,'[');for(int i=0;i<v->ar.cnt;i++){if(i)sb_addc(s,',');jser(s,v->ar.items[i]);}sb_addc(s,']');break;
    case JO:sb_addc(s,'{');for(int i=0;i<v->ob.cnt;i++){if(i)sb_addc(s,',');jser_str(s,v->ob.keys[i]);sb_addc(s,':');jser(s,v->ob.vals[i]);}sb_addc(s,'}');break;}}

/* ===== UTF-8 ===== */
static int u8dec(const char*s,unsigned int*cp){unsigned char c=(unsigned char)s[0];
    if(c<0x80){*cp=c;return 1;}
    if((c&0xE0)==0xC0){*cp=((c&0x1F)<<6)|((unsigned char)s[1]&0x3F);return 2;}
    if((c&0xF0)==0xE0){*cp=((c&0x0F)<<12)|(((unsigned char)s[1]&0x3F)<<6)|((unsigned char)s[2]&0x3F);return 3;}
    if((c&0xF8)==0xF0){*cp=((c&0x07)<<18)|(((unsigned char)s[1]&0x3F)<<12)|(((unsigned char)s[2]&0x3F)<<6)|((unsigned char)s[3]&0x3F);return 4;}
    *cp=c;return 1;}

static int u8enc(unsigned int cp,char*o){
    if(cp<0x80){o[0]=(char)cp;return 1;}
    if(cp<0x800){o[0]=(char)(0xC0|(cp>>6));o[1]=(char)(0x80|(cp&0x3F));return 2;}
    if(cp<0x10000){o[0]=(char)(0xE0|(cp>>12));o[1]=(char)(0x80|((cp>>6)&0x3F));o[2]=(char)(0x80|(cp&0x3F));return 3;}
    o[0]=(char)(0xF0|(cp>>18));o[1]=(char)(0x80|((cp>>12)&0x3F));o[2]=(char)(0x80|((cp>>6)&0x3F));o[3]=(char)(0x80|(cp&0x3F));return 4;}

/* ===== Tools ===== */
static char*exec_tool(const char*name,jv*input,int*is_err){
    *is_err=0;
    if(!strcmp(name,"measure")){
        jv*tv=jget(input,"text"),*uv=jget(input,"unit");
        if(!tv||tv->t!=JS||!uv||uv->t!=JS){*is_err=1;return strdup("invalid input");}
        const char*text=tv->s,*unit=uv->s;long res;
        if(!strcmp(unit,"code_points")){res=0;const char*p=text;while(*p){unsigned int cp;p+=u8dec(p,&cp);res++;}}
        else if(!strcmp(unit,"utf8_bytes"))res=(long)strlen(text);
        else if(!strcmp(unit,"utf16_units")){res=0;const char*p=text;while(*p){unsigned int cp;p+=u8dec(p,&cp);res+=(cp>0xFFFF)?2:1;}}
        else{*is_err=1;char m[512];snprintf(m,512,"unsupported unit: %s",unit);return strdup(m);}
        char buf[32];snprintf(buf,32,"%ld",res);return strdup(buf);}
    if(!strcmp(name,"reverse")){
        jv*tv=jget(input,"text");if(!tv||tv->t!=JS){*is_err=1;return strdup("invalid input");}
        const char*p=tv->s;int n=0;const char*q=p;while(*q){unsigned int cp;q+=u8dec(q,&cp);n++;}
        unsigned int*cps=malloc(n*sizeof(unsigned int));int i=0;p=tv->s;while(*p){unsigned int cp;p+=u8dec(p,&cp);cps[i++]=cp;}
        for(i=0;i<n/2;i++){unsigned int t=cps[i];cps[i]=cps[n-1-i];cps[n-1-i]=t;}
        sbuf out={0};for(i=0;i<n;i++){char tmp[4];int l=u8enc(cps[i],tmp);sb_add(&out,tmp,l);}
        free(cps);return out.data?out.data:strdup("");}
    *is_err=1;char m[512];snprintf(m,512,"unknown tool: %s",name);return strdup(m);}

/* ===== Output escape ===== */
static void print_esc(const char*s){while(*s){unsigned char c=(unsigned char)*s;
    if(c=='\\')printf("\\\\");else if(c=='\n')printf("\\n");else if(c=='\r')printf("\\r");
    else if(c=='\t')printf("\\t");else putchar(c);s++;}}

/* ===== Buffered Reader ===== */
typedef struct{int fd;char buf[65536];size_t pos,len;int eof;}brdr;
static void bi_init(brdr*b,int fd){b->fd=fd;b->pos=0;b->len=0;b->eof=0;}
static int bi_getc(brdr*b){if(b->pos>=b->len){ssize_t r=read(b->fd,b->buf,sizeof(b->buf));if(r<=0){b->eof=1;return -1;}b->pos=0;b->len=(size_t)r;}return(unsigned char)b->buf[b->pos++];}

/* ===== Content Block ===== */
typedef struct{int index;char type[32];sbuf thinking,signature,text,input_json;char id[256],name[256];}cblk;

/* ===== Response ===== */
typedef struct{int status;int nblk;cblk blocks[64];char stop_reason[64];
    long in_tok,out_tok,cr_tok;char err_type[256],err_msg[1024];}resp_t;

/* ===== SSE event processing ===== */
static void process_event(resp_t*r,const char*etype,const char*edata){
    if(!etype||!edata)return;
    jctx ctx={edata,0,strlen(edata)};jv*e=jparse(&ctx);
    if(!strcmp(etype,"message_start")){
        jv*msg=jget(e,"message");if(!msg)return;jv*us=jget(msg,"usage");if(!us)return;
        jv*it=jget(us,"input_tokens"),*cr=jget(us,"cache_read_input_tokens");
        if(it&&it->t==JM)r->in_tok+=(long)it->n;
        if(cr&&cr->t==JM)r->cr_tok+=(long)cr->n;
    }else if(!strcmp(etype,"content_block_start")){
        jv*iv=jget(e,"index"),*cb=jget(e,"content_block");if(!iv||!cb)return;
        int idx=(int)iv->n;cblk*blk=NULL;
        for(int i=0;i<r->nblk;i++)if(r->blocks[i].index==idx){blk=&r->blocks[i];break;}
        if(!blk){blk=&r->blocks[r->nblk++];memset(blk,0,sizeof(cblk));blk->index=idx;}
        jv*tv=jget(cb,"type");if(tv&&tv->t==JS)strncpy(blk->type,tv->s,31);
        if(!strcmp(blk->type,"tool_use")){jv*id=jget(cb,"id"),*nm=jget(cb,"name");
            if(id&&id->t==JS)strncpy(blk->id,id->s,255);if(nm&&nm->t==JS)strncpy(blk->name,nm->s,255);}
    }else if(!strcmp(etype,"content_block_delta")){
        jv*iv=jget(e,"index"),*d=jget(e,"delta");if(!iv||!d)return;
        int idx=(int)iv->n;cblk*blk=NULL;
        for(int i=0;i<r->nblk;i++)if(r->blocks[i].index==idx){blk=&r->blocks[i];break;}
        if(!blk)return;jv*dt=jget(d,"type");if(!dt||dt->t!=JS)return;
        if(!strcmp(dt->s,"thinking_delta")){jv*t=jget(d,"thinking");if(t&&t->t==JS)sb_adds(&blk->thinking,t->s);}
        else if(!strcmp(dt->s,"signature_delta")){jv*t=jget(d,"signature");if(t&&t->t==JS)sb_adds(&blk->signature,t->s);}
        else if(!strcmp(dt->s,"text_delta")){jv*t=jget(d,"text");if(t&&t->t==JS)sb_adds(&blk->text,t->s);}
        else if(!strcmp(dt->s,"input_json_delta")){jv*t=jget(d,"partial_json");if(t&&t->t==JS)sb_adds(&blk->input_json,t->s);}
    }else if(!strcmp(etype,"message_delta")){
        jv*d=jget(e,"delta");if(d){jv*sr=jget(d,"stop_reason");if(sr&&sr->t==JS)strncpy(r->stop_reason,sr->s,63);}
        jv*us=jget(e,"usage");if(us){jv*ot=jget(us,"output_tokens");if(ot&&ot->t==JM)r->out_tok+=(long)ot->n;}
    }
}

/* ===== Case-insensitive substring search ===== */
static int contains_ci(const char*hay,const char*needle){
    size_t hl=strlen(hay),nl=strlen(needle);
    for(size_t i=0;i+nl<=hl;i++){
        int ok=1;
        for(size_t j=0;j<nl;j++){
            if(tolower((unsigned char)hay[i+j])!=tolower((unsigned char)needle[j])){ok=0;break;}
        }
        if(ok)return 1;
    }
    return 0;
}

/* ===== Send request and parse response ===== */
static void send_req(const char*base_url,const char*api_key,const char*body,resp_t*r){
    memset(r,0,sizeof(resp_t));
    /* parse URL */
    char host[256]="",path[1024]="/";int port=80;
    const char*p=base_url;if(!strncmp(p,"http://",7))p+=7;
    const char*sl=strchr(p,'/');const char*co=strchr(p,':');
    if(co&&(!sl||co<sl)){size_t hl=co-p;if(hl>255)hl=255;memcpy(host,p,hl);host[hl]=0;port=atoi(co+1);}
    else{size_t hl=sl?(size_t)(sl-p):strlen(p);if(hl>255)hl=255;memcpy(host,p,hl);host[hl]=0;}
    if(sl)strncpy(path,sl,1023);
    char ep[1024];snprintf(ep,1024,"%s/v1/messages",path);

    struct addrinfo hints={0},*res;hints.ai_family=AF_INET;hints.ai_socktype=SOCK_STREAM;
    char ps[8];snprintf(ps,8,"%d",port);
    if(getaddrinfo(host,ps,&hints,&res)){r->status=-1;return;}
    int fd=socket(res->ai_family,res->ai_socktype,res->ai_protocol);
    if(fd<0){freeaddrinfo(res);r->status=-1;return;}
    if(connect(fd,res->ai_addr,res->ai_addrlen)<0){close(fd);freeaddrinfo(res);r->status=-1;return;}
    freeaddrinfo(res);

    /* build request */
    sbuf rq={0};
    sb_adds(&rq,"POST ");sb_adds(&rq,ep);sb_adds(&rq," HTTP/1.1\r\n");
    sb_adds(&rq,"Host: ");sb_adds(&rq,host);sb_addc(&rq,':');
    char cl[16];snprintf(cl,16,"%d",port);sb_adds(&rq,cl);sb_adds(&rq,"\r\n");
    sb_adds(&rq,"Content-Length: ");snprintf(cl,16,"%zu",strlen(body));sb_adds(&rq,cl);sb_adds(&rq,"\r\n");
    sb_adds(&rq,"x-api-key: ");sb_adds(&rq,api_key);sb_adds(&rq,"\r\n");
    sb_adds(&rq,"anthropic-version: 2023-06-01\r\n");
    sb_adds(&rq,"content-type: application/json\r\n\r\n");
    sb_adds(&rq,body);

    size_t sent=0;while(sent<rq.len){ssize_t w=write(fd,rq.data+sent,rq.len-sent);if(w<=0)break;sent+=(size_t)w;}
    sb_free(&rq);

    /* read response */
    brdr b;bi_init(&b,fd);
    char line[4096];int li;
    /* status line */
    li=0;while(1){int c=bi_getc(&b);if(c<0)break;if(c=='\n')break;if(c!='\r')line[li++]=c;}line[li]=0;
    r->status=0;if(!strncmp(line,"HTTP/1.1 ",9)||!strncmp(line,"HTTP/1.0 ",9))r->status=atoi(line+9);

    int chunked=0;long clen=-1;
    while(1){li=0;while(1){int c=bi_getc(&b);if(c<0)break;if(c=='\n')break;if(c!='\r')line[li++]=c;}line[li]=0;
        if(li==0)break;
        if(!strncasecmp(line,"Transfer-Encoding:",16)){if(contains_ci(line,"chunked"))chunked=1;}
        if(!strncasecmp(line,"Content-Length:",15))clen=atol(line+15);}

    sbuf bd={0};
    if(chunked){
        while(1){li=0;while(1){int c=bi_getc(&b);if(c<0)goto bd_done;if(c=='\n')break;if(c!='\r')line[li++]=c;}line[li]=0;
            size_t csz=0;for(int i=0;i<li;i++){char ch=line[i];if(ch==';')break;
                if(isdigit((unsigned char)ch))csz=csz*16+(ch-'0');else if(ch>='a'&&ch<='f')csz=csz*16+(ch-'a'+10);else if(ch>='A'&&ch<='F')csz=csz*16+(ch-'A'+10);}
            if(csz==0)break;
            for(size_t i=0;i<csz;i++){int c=bi_getc(&b);if(c<0)goto bd_done;sb_addc(&bd,(char)c);}
            int c=bi_getc(&b);if(c=='\r')bi_getc(&b);}
    }else if(clen>=0){for(long i=0;i<clen;i++){int c=bi_getc(&b);if(c<0)break;sb_addc(&bd,(char)c);}}
    else{while(!b.eof){int c=bi_getc(&b);if(c<0)break;sb_addc(&bd,(char)c);}}
bd_done:close(fd);

    if(r->status!=200){
        if(bd.data){jctx ctx2={bd.data,0,bd.len};jv*ev=jparse(&ctx2);jv*eo=jget(ev,"error");
            if(eo){jv*t=jget(eo,"type"),*m=jget(eo,"message");
                if(t&&t->t==JS)strncpy(r->err_type,t->s,255);if(m&&m->t==JS)strncpy(r->err_msg,m->s,1023);}}
        sb_free(&bd);return;}

    /* parse SSE */
    char*cur_ev=NULL;sbuf cur_data={0};int has_data=0;
    size_t pos=0;char*raw=bd.data;size_t rlen=bd.len;
    while(pos<rlen){
        sbuf ln={0};
        while(pos<rlen){char c=raw[pos++];if(c=='\n')break;if(c=='\r'){if(pos<rlen&&raw[pos]=='\n')pos++;break;}sb_addc(&ln,c);}
        if(ln.len==0){
            if(has_data&&cur_data.data)process_event(r,cur_ev,cur_data.data);
            free(cur_ev);cur_ev=NULL;sb_free(&cur_data);has_data=0;sb_free(&ln);continue;}
        if(ln.data[0]==':'){sb_free(&ln);continue;}
        if(!strncmp(ln.data,"event:",6)){char*v=ln.data+6;if(*v==' ')v++;free(cur_ev);cur_ev=strdup(v);}
        else if(!strncmp(ln.data,"data:",5)){char*v=ln.data+5;if(*v==' ')v++;
            if(has_data)sb_addc(&cur_data,'\n');sb_adds(&cur_data,v);has_data=1;}
        sb_free(&ln);}
    if(has_data&&cur_data.data)process_event(r,cur_ev,cur_data.data);
    free(cur_ev);sb_free(&cur_data);sb_free(&bd);
}

/* ===== Build request body ===== */
static char*build_body(const char*model,long max_tok,long think_bud,const char*sys,const char*tools_json,const char*msgs_json){
    sbuf b={0};
    sb_addc(&b,'{');
    sb_adds(&b,"\"model\":");jser_str(&b,model);
    sb_adds(&b,",\"max_tokens\":");char t[32];snprintf(t,32,"%ld",max_tok);sb_adds(&b,t);
    sb_adds(&b,",\"stream\":true");
    sb_adds(&b,",\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":");snprintf(t,32,"%ld",think_bud);sb_adds(&b,t);sb_adds(&b,"}");
    sb_adds(&b,",\"system\":");jser_str(&b,sys);
    sb_adds(&b,",\"tools\":");sb_adds(&b,tools_json);
    sb_adds(&b,",\"messages\":");sb_adds(&b,msgs_json);
    sb_addc(&b,'}');
    return b.data;}

/* ===== Print blocks ===== */
static void print_blocks(resp_t*r){
    for(int i=0;i<r->nblk;i++){cblk*b=&r->blocks[i];
        if(!strcmp(b->type,"thinking")){printf("thinking ");print_esc(b->thinking.data?b->thinking.data:"");printf("\n");
            printf("signature ");print_esc(b->signature.data?b->signature.data:"");printf("\n");}
        else if(!strcmp(b->type,"text")){printf("text ");print_esc(b->text.data?b->text.data:"");printf("\n");}
        else if(!strcmp(b->type,"tool_use")){printf("tool_use ");printf("%s ",b->id);printf("%s ",b->name);
            print_esc(b->input_json.data?b->input_json.data:"");printf("\n");}}
    printf("stop_reason %s\n",r->stop_reason);}

/* ===== Main ===== */
int main(int argc,char**argv){
    if(argc<3){fprintf(stderr,"usage: %s <data_dir> <base_url>\n",argv[0]);return 1;}
    const char*data_dir=argv[1],*base_url=argv[2];

    /* read request.json */
    char fpath[4096];snprintf(fpath,4096,"%s/request.json",data_dir);
    FILE*f=fopen(fpath,"rb");if(!f){perror("open");return 1;}
    fseek(f,0,SEEK_END);long fsz=ftell(f);fseek(f,0,SEEK_SET);
    char*fbuf=malloc(fsz+1);fread(fbuf,1,fsz,f);fbuf[fsz]=0;fclose(f);

    jctx ctx={fbuf,0,(size_t)fsz};jv*cfg=jparse(&ctx);
    const char*api_key=jget(cfg,"api_key")->s;
    const char*model=jget(cfg,"model")->s;
    long max_tok=(long)jget(cfg,"max_tokens")->n;
    long think_bud=(long)jget(cfg,"thinking_budget")->n;
    const char*sys=jget(cfg,"system")->s;
    const char*prompt=jget(cfg,"prompt")->s;
    jv*tools=jget(cfg,"tools");

    /* serialize tools to JSON text */
    sbuf tools_json={0};jser(&tools_json,tools);

    /* Request 1 */
    sbuf m1={0};sb_adds(&m1,"[{\"role\":\"user\",\"content\":");jser_str(&m1,prompt);sb_adds(&m1,"}]");
    char*body1=build_body(model,max_tok,think_bud,sys,tools_json.data,m1.data);

    resp_t r1;send_req(base_url,api_key,body1,&r1);
    printf("request 1\n");
    if(r1.status!=200){print_blocks(&r1);printf("ERROR %d %s: %s\n",r1.status,r1.err_type,r1.err_msg);free(body1);sb_free(&m1);sb_free(&tools_json);free(fbuf);return 0;}
    print_blocks(&r1);

    /* Execute tools and print results */
    typedef struct{char*result;int is_err;}tool_res;
    tool_res tres[64];int nres=0;
    for(int i=0;i<r1.nblk;i++){cblk*b=&r1.blocks[i];
        if(strcmp(b->type,"tool_use"))continue;
        const char*ij=b->input_json.data?b->input_json.data:"{}";
        jctx ctx2={ij,0,strlen(ij)};jv*inp=jparse(&ctx2);
        int ie;char*res=exec_tool(b->name,inp,&ie);
        if(ie)printf("error ");else printf("result ");
        printf("%s ",b->id);print_esc(res);printf("\n");
        tres[nres].result=res;tres[nres].is_err=ie;nres++;}

    /* Request 2 */
    sbuf m2={0};
    sb_adds(&m2,"[{\"role\":\"user\",\"content\":");jser_str(&m2,prompt);sb_adds(&m2,"},{\"role\":\"assistant\",\"content\":[");
    int first=1;
    for(int i=0;i<r1.nblk;i++){cblk*b=&r1.blocks[i];
        if(!first)sb_addc(&m2,',');first=0;
        if(!strcmp(b->type,"thinking")){sb_adds(&m2,"{\"type\":\"thinking\",\"thinking\":");jser_str(&m2,b->thinking.data?b->thinking.data:"");
            sb_adds(&m2,",\"signature\":");jser_str(&m2,b->signature.data?b->signature.data:"");sb_addc(&m2,'}');}
        else if(!strcmp(b->type,"text")){sb_adds(&m2,"{\"type\":\"text\",\"text\":");jser_str(&m2,b->text.data?b->text.data:"");sb_addc(&m2,'}');}
        else if(!strcmp(b->type,"tool_use")){sb_adds(&m2,"{\"type\":\"tool_use\",\"id\":");jser_str(&m2,b->id);
            sb_adds(&m2,",\"name\":");jser_str(&m2,b->name);sb_adds(&m2,",\"input\":");
            const char*ij=b->input_json.data?b->input_json.data:"{}";
            jctx ctx3={ij,0,strlen(ij)};jv*pv=jparse(&ctx3);jser(&m2,pv);sb_addc(&m2,'}');}}
    sb_adds(&m2,"]},{\"role\":\"user\",\"content\":[");
    int ti=0;first=1;
    for(int i=0;i<r1.nblk;i++){cblk*b=&r1.blocks[i];
        if(strcmp(b->type,"tool_use"))continue;
        if(!first)sb_addc(&m2,',');first=0;
        sb_adds(&m2,"{\"type\":\"tool_result\",\"tool_use_id\":");jser_str(&m2,b->id);
        sb_adds(&m2,",\"content\":");jser_str(&m2,tres[ti].result);
        if(tres[ti].is_err)sb_adds(&m2,",\"is_error\":true");
        sb_addc(&m2,'}');ti++;}
    sb_adds(&m2,"]}]");

    char*body2=build_body(model,max_tok,think_bud,sys,tools_json.data,m2.data);
    resp_t r2;send_req(base_url,api_key,body2,&r2);
    printf("request 2\n");
    if(r2.status!=200){print_blocks(&r2);printf("ERROR %d %s: %s\n",r2.status,r2.err_type,r2.err_msg);
        free(body1);free(body2);sb_free(&m1);sb_free(&m2);sb_free(&tools_json);free(fbuf);return 0;}
    print_blocks(&r2);

    printf("usage input=%ld output=%ld cache_read=%ld\n",r1.in_tok+r2.in_tok,r1.out_tok+r2.out_tok,r1.cr_tok+r2.cr_tok);

    free(body1);free(body2);sb_free(&m1);sb_free(&m2);sb_free(&tools_json);free(fbuf);
    return 0;}

import Foundation

let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]

let fm = FileManager.default
guard let entries = try? fm.contentsOfDirectory(atPath: dir) else { exit(1) }

let wavFiles = entries.filter { $0.hasSuffix(".wav") }.sorted { a, b in
    Array(a.utf8).lexicographicallyPrecedes(Array(b.utf8))
}

let lowFreqs: [Double] = [697, 770, 852, 941]
let highFreqs: [Double] = [1209, 1336, 1477, 1633]

let keypad: [[String]] = [
    ["1", "2", "3", "A"],
    ["4", "5", "6", "B"],
    ["7", "8", "9", "C"],
    ["*", "0", "#", "D"]
]

func readUInt16LE(_ data: [UInt8], _ offset: Int) -> Int {
    return Int(data[offset]) | (Int(data[offset + 1]) << 8)
}

func readUInt32LE(_ data: [UInt8], _ offset: Int) -> Int {
    return Int(data[offset]) | (Int(data[offset + 1]) << 8) | (Int(data[offset + 2]) << 16) | (Int(data[offset + 3]) << 24)
}

func readInt16LE(_ data: [UInt8], _ offset: Int) -> Int {
    let val = Int(data[offset]) | (Int(data[offset + 1]) << 8)
    if val >= 32768 { return val - 65536 }
    return val
}

var first = true

for name in wavFiles {
    if !first { print("") }
    first = false

    let path = dir + "/" + name
    guard let fileData = fm.contents(atPath: path) else {
        print("\(name): unsupported")
        continue
    }

    let bytes = [UInt8](fileData)

    guard bytes.count >= 12 else {
        print("\(name): unsupported")
        continue
    }
    guard bytes[0] == 0x52 && bytes[1] == 0x49 && bytes[2] == 0x46 && bytes[3] == 0x46 else {
        print("\(name): unsupported")
        continue
    }
    guard bytes[8] == 0x57 && bytes[9] == 0x41 && bytes[10] == 0x56 && bytes[11] == 0x45 else {
        print("\(name): unsupported")
        continue
    }

    // Parse chunks
    var pos = 12
    var fmtBody: [UInt8]? = nil
    var dataOffset = -1
    var dataSize = 0

    while pos + 8 <= bytes.count {
        let chunkId = String(bytes: bytes[pos..<pos+4], encoding: .ascii) ?? ""
        let chunkSize = readUInt32LE(bytes, pos + 4)
        let bodyStart = pos + 8
        let bodyEnd = bodyStart + chunkSize
        guard bodyEnd <= bytes.count else { break }

        if chunkId == "fmt " {
            fmtBody = Array(bytes[bodyStart..<bodyEnd])
        } else if chunkId == "data" {
            dataOffset = bodyStart
            dataSize = chunkSize
        }

        pos = bodyEnd
        if chunkSize % 2 == 1 { pos += 1 }
    }

    guard let fmt = fmtBody, fmt.count >= 16, dataOffset >= 0 else {
        print("\(name): unsupported")
        continue
    }

    let formatTag = readUInt16LE(fmt, 0)
    let channels = readUInt16LE(fmt, 2)
    let sampleRate = readUInt32LE(fmt, 4)
    let bitsPerSample = readUInt16LE(fmt, 14)

    var effectiveFormat = formatTag
    if formatTag == 0xFFFE {
        guard fmt.count >= 26 else {
            print("\(name): unsupported")
            continue
        }
        effectiveFormat = readUInt16LE(fmt, 24)
    }

    guard effectiveFormat == 1 && bitsPerSample == 16 &&
          (channels == 1 || channels == 2) &&
          (sampleRate == 8000 || sampleRate == 16000) else {
        print("\(name): unsupported")
        continue
    }

    let totalFrames = dataSize / (2 * channels)
    let N = sampleRate / 50
    let numBlocks = totalFrames / N

    // Extract left channel samples
    var samples = [Int](repeating: 0, count: totalFrames)
    for i in 0..<totalFrames {
        let offset = dataOffset + i * 2 * channels
        samples[i] = readInt16LE(bytes, offset)
    }

    // Process blocks
    var labels = [String?](repeating: nil, count: numBlocks)

    for block in 0..<numBlocks {
        let startIdx = block * N

        // Energy
        var E: Double = 0
        for n in 0..<N {
            let x = Double(samples[startIdx + n])
            E += x * x
        }

        if E < 1000000.0 * Double(N) {
            continue
        }

        // Goertzel
        func goertzel(_ f: Double) -> Double {
            let c = 2.0 * cos(2.0 * Double.pi * f / Double(sampleRate))
            var s1 = 0.0
            var s2 = 0.0
            for n in 0..<N {
                let s = Double(samples[startIdx + n]) + c * s1 - s2
                s2 = s1
                s1 = s
            }
            return s1 * s1 + s2 * s2 - c * s1 * s2
        }

        var maxLowR: Double = -1
        var maxLowIdx = 0
        var maxHighR: Double = -1
        var maxHighIdx = 0

        for i in 0..<4 {
            let P = goertzel(lowFreqs[i])
            let r = 2.0 * P / (Double(N) * E)
            if r > maxLowR {
                maxLowR = r
                maxLowIdx = i
            }
        }

        for i in 0..<4 {
            let P = goertzel(highFreqs[i])
            let r = 2.0 * P / (Double(N) * E)
            if r > maxHighR {
                maxHighR = r
                maxHighIdx = i
            }
        }

        if maxLowR >= 0.1 && maxHighR >= 0.1 && maxLowR + maxHighR >= 0.6 {
            labels[block] = keypad[maxLowIdx][maxHighIdx]
        }
    }

    // Bridging (use original labels for neighbor checks)
    var bridged = labels
    if numBlocks >= 3 {
        for i in 1..<numBlocks - 1 {
            if labels[i] == nil {
                if let prev = labels[i - 1], let next = labels[i + 1], prev == next {
                    bridged[i] = prev
                }
            }
        }
    }

    // Events
    var events: [(String, Int, Int)] = []
    var i = 0
    while i < numBlocks {
        guard let d = bridged[i] else { i += 1; continue }
        var j = i + 1
        while j < numBlocks && bridged[j] == d { j += 1 }
        if j - i >= 2 {
            events.append((d, 20 * i, 20 * j))
        }
        i = j
    }

    // Output
    print("\(name): \(sampleRate) Hz, \(channels) ch, \(numBlocks) blocks")
    for (digit, start, end) in events {
        print("\(digit) \(start) \(end)")
    }
    let allDigits = events.map { $0.0 }.joined()
    print("digits: \(allDigits)")
}

def compute_max_local(payload_size, page_size, reserved, is_leaf_table):
    U = page_size - reserved
    if is_leaf_table:
        X = U - 35
    else:
        X = ((U - 12) * 64 // 255) - 23

    if payload_size <= X:
        return payload_size

    M = ((U - 12) * 32 // 255) - 23
    K = M + ((payload_size - M) % (U - 4))
    if K <= X:
        return K
    else:
        return M  # BUG: should be X

#include <stdio.h>
