#include <stdint.h>

static uint32_t read_u32(const unsigned char *p) {
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

static uint16_t read_u16(const unsigned char *p) {
    return (uint16_t)p[0] | ((uint16_t)p[1] << 8);
}

static int16_t read_i16(const unsigned char *p) {
    return (int16_t)(p[0] | (p[1] << 8));
}

static const double low_freqs[4] = {697.0, 770.0, 852.0, 941.0};
static const double high_freqs[4] = {1209.0, 1336.0, 1477.0, 1633.0};

static const char keypad[4][4] = {
    {'1', '2', '3', 'A'},
    {'4', '5', '6', 'B'},
    {'7', '8', '9', 'C'},
    {'*', '0', '#', 'D'}
};

static double goertzel(const int16_t *x, int N, double rate, double freq) {
    double c = 2.0 * cos(2.0 * M_PI * freq / rate);
    double s1 = 0.0, s2 = 0.0;
    for (int n = 0; n < N; n++) {
        double s = (double)x[n] + c * s1 - s2;
        s2 = s1;
        s1 = s;
    }
    return s1 * s1 + s2 * s2 - c * s1 * s2;
}

static int cmp_str(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}

int main(int argc, char *argv[]) {
    if (argc < 2) return 1;

    const char *dir = argv[1];
    DIR *d = opendir(dir);
    if (!d) return 1;

    char **files = NULL;
    int nfiles = 0;
    struct dirent *ent;
    while ((ent = readdir(d)) != NULL) {
        const char *name = ent->d_name;
        size_t len = strlen(name);
        if (len >= 4 && strcmp(name + len - 4, ".wav") == 0) {
            files = realloc(files, (nfiles + 1) * sizeof(char *));
            files[nfiles++] = strdup(name);
        }
    }
    closedir(d);

    if (nfiles > 0)
        qsort(files, nfiles, sizeof(char *), cmp_str);

    for (int fi = 0; fi < nfiles; fi++) {
        if (fi > 0) printf("\n");

        const char *name = files[fi];

        char path[4096];
        snprintf(path, sizeof(path), "%s/%s", dir, name);
        FILE *fp = fopen(path, "rb");
        if (!fp) {
            printf("%s: unsupported\n", name);
            continue;
        }

        fseek(fp, 0, SEEK_END);
        long fsize = ftell(fp);
        fseek(fp, 0, SEEK_SET);

        unsigned char *buf = (unsigned char *)malloc(fsize);
        if (!buf) { fclose(fp); printf("%s: unsupported\n", name); continue; }
        fread(buf, 1, fsize, fp);
        fclose(fp);

        if (fsize < 12 || memcmp(buf, "RIFF", 4) != 0 || memcmp(buf + 8, "WAVE", 4) != 0) {
            printf("%s: unsupported\n", name);
            free(buf);
            continue;
        }

        int fmt_found = 0, data_found = 0;
        unsigned char *fmt_body = NULL;
        int fmt_size = 0;
        unsigned char *data_body = NULL;
        int data_size = 0;

        long pos = 12;
        while (pos + 8 <= fsize) {
            uint32_t chunk_size = read_u32(buf + pos + 4);
            long body_start = pos + 8;

            if (memcmp(buf + pos, "fmt ", 4) == 0) {
                fmt_body = buf + body_start;
                fmt_size = (int)chunk_size;
                fmt_found = 1;
            } else if (memcmp(buf + pos, "data", 4) == 0) {
                data_body = buf + body_start;
                data_size = (int)chunk_size;
                data_found = 1;
            }

            long next = body_start + (long)chunk_size;
            if (chunk_size % 2 != 0) next++;
            pos = next;
        }

        if (!fmt_found || !data_found || fmt_size < 16) {
            printf("%s: unsupported\n", name);
            free(buf);
            continue;
        }

        uint16_t format_tag = read_u16(fmt_body);
        uint16_t channels = read_u16(fmt_body + 2);
        uint32_t rate = read_u32(fmt_body + 4);
        uint16_t bits = read_u16(fmt_body + 14);

        uint16_t effective_format = format_tag;
        if (format_tag == 0xFFFE && fmt_size >= 26) {
            effective_format = read_u16(fmt_body + 24);
        }

        if (effective_format != 1 || bits != 16) {
            printf("%s: unsupported\n", name);
            free(buf);
            continue;
        }

        if (channels != 1 && channels != 2) {
            printf("%s: unsupported\n", name);
            free(buf);
            continue;
        }

        if (rate != 8000 && rate != 16000) {
            printf("%s: unsupported\n", name);
            free(buf);
            continue;
        }

        int N = (int)rate / 50;
        int total_frames = data_size / (2 * (int)channels);
        int blocks = total_frames / N;

        printf("%s: %u Hz, %u ch, %d blocks\n", name, rate, channels, blocks);

        /* Extract left channel */
        int16_t *left = (int16_t *)malloc(total_frames * sizeof(int16_t));
        int bytes_per_frame = 2 * (int)channels;
        for (int i = 0; i < total_frames; i++) {
            left[i] = read_i16(data_body + i * bytes_per_frame);
        }

        /* Step 3: detect digit per block */
        int *labels = (int *)malloc(blocks * sizeof(int));

        for (int b = 0; b < blocks; b++) {
            const int16_t *blk = left + b * N;

            double E = 0.0;
            for (int n = 0; n < N; n++) {
                double v = (double)blk[n];
                E += v * v;
            }

            if (E < 1000000.0 * (double)N) {
                labels[b] = -1;
                continue;
            }

            double r_low[4], r_high[4];
            for (int i = 0; i < 4; i++) {
                double P = goertzel(blk, N, (double)rate, low_freqs[i]);
                r_low[i] = 2.0 * P / ((double)N * E);
            }
            for (int i = 0; i < 4; i++) {
                double P = goertzel(blk, N, (double)rate, high_freqs[i]);
                r_high[i] = 2.0 * P / ((double)N * E);
            }

            int best_low = 0, best_high = 0;
            for (int i = 1; i < 4; i++) {
                if (r_low[i] > r_low[best_low]) best_low = i;
                if (r_high[i] > r_high[best_high]) best_high = i;
            }

            if (r_low[best_low] >= 0.1 && r_high[best_high] >= 0.1 &&
                r_low[best_low] + r_high[best_high] >= 0.6) {
                labels[b] = best_low * 4 + best_high;
            } else {
                labels[b] = -1;
            }
        }

        /* Step 4: bridging (use original labels for neighbor checks) */
        int *bridged = (int *)malloc(blocks * sizeof(int));
        memcpy(bridged, labels, blocks * sizeof(int));
        for (int b = 1; b < blocks - 1; b++) {
            if (labels[b] == -1 && labels[b - 1] != -1 && labels[b + 1] != -1 &&
                labels[b - 1] == labels[b + 1]) {
                bridged[b] = labels[b - 1];
            }
        }

        /* Step 5: events */
        char digits[65536];
        int dpos = 0;

        int b = 0;
        while (b < blocks) {
            if (bridged[b] == -1) { b++; continue; }
            int d = bridged[b];
            int start = b;
            while (b < blocks && bridged[b] == d) b++;
            int end = b; /* exclusive */
            if (end - start >= 2) {
                char ch = keypad[d / 4][d % 4];
                printf("%c %d %d\n", ch, 20 * start, 20 * end);
                digits[dpos++] = ch;
            }
        }
        digits[dpos] = '\0';
        printf("digits: %s\n", digits);

        free(left);
        free(labels);
        free(bridged);
        free(buf);
    }

    for (int i = 0; i < nfiles; i++) free(files[i]);
    free(files);

    return 0;
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        File dir = new File(args[0]);
        File[] files = dir.listFiles();

        List<File> wavFiles = new ArrayList<>();
        if (files != null) {
            for (File f : files) {
                if (f.isFile() && f.getName().endsWith(".wav")) {
                    wavFiles.add(f);
                }
            }
        }

        wavFiles.sort((a, b) -> {
            byte[] ba = a.getName().getBytes(StandardCharsets.UTF_8);
            byte[] bb = b.getName().getBytes(StandardCharsets.UTF_8);
            return Arrays.compare(ba, bb);
        });

        int[] lowFreqs = {697, 770, 852, 941};
        int[] highFreqs = {1209, 1336, 1477, 1633};
        char[][] keypad = {
            {'1', '2', '3', 'A'},
            {'4', '5', '6', 'B'},
            {'7', '8', '9', 'C'},
            {'*', '0', '#', 'D'}
        };

        boolean firstFile = true;

        for (File f : wavFiles) {
            if (!firstFile) {
                System.out.println();
            }
            firstFile = false;

            String name = f.getName();
            byte[] fileData = Files.readAllBytes(f.toPath());

            // Validate RIFF header
            if (fileData.length < 12 ||
                fileData[0] != 'R' || fileData[1] != 'I' || fileData[2] != 'F' || fileData[3] != 'F' ||
                fileData[8] != 'W' || fileData[9] != 'A' || fileData[10] != 'V' || fileData[11] != 'E') {
                System.out.println(name + ": unsupported");
                continue;
            }

            // Parse chunks
            byte[] fmtBody = null;
            byte[] dataBody = null;
            int pos = 12;

            while (pos + 8 <= fileData.length) {
                String chunkId = new String(fileData, pos, 4, StandardCharsets.ISO_8859_1);
                int chunkSize = (fileData[pos + 4] & 0xFF) |
                              ((fileData[pos + 5] & 0xFF) << 8) |
                              ((fileData[pos + 6] & 0xFF) << 16) |
                              ((fileData[pos + 7] & 0xFF) << 24);
                pos += 8;

                int end = pos + chunkSize;
                if (end > fileData.length) break;

                if (chunkId.equals("fmt ")) {
                    fmtBody = Arrays.copyOfRange(fileData, pos, end);
                } else if (chunkId.equals("data")) {
                    dataBody = Arrays.copyOfRange(fileData, pos, end);
                }

                pos = end;
                if (chunkSize % 2 != 0) pos++;
            }

            if (fmtBody == null || dataBody == null) {
                System.out.println(name + ": unsupported");
                continue;
            }

            // Parse fmt body
            int formatTag = (fmtBody[0] & 0xFF) | ((fmtBody[1] & 0xFF) << 8);
            int channels = (fmtBody[2] & 0xFF) | ((fmtBody[3] & 0xFF) << 8);
            int sampleRate = (fmtBody[4] & 0xFF) | ((fmtBody[5] & 0xFF) << 8) |
                           ((fmtBody[6] & 0xFF) << 16) | ((fmtBody[7] & 0xFF) << 24);
            int bitsPerSample = (fmtBody[10] & 0xFF) | ((fmtBody[11] & 0xFF) << 8);

            int effectiveFormat = formatTag;
            if (formatTag == 0xFFFE && fmtBody.length >= 26) {
                effectiveFormat = (fmtBody[24] & 0xFF) | ((fmtBody[25] & 0xFF) << 8);
            }

            if (effectiveFormat != 1 || bitsPerSample != 16 ||
                (channels != 1 && channels != 2) ||
                (sampleRate != 8000 && sampleRate != 16000)) {
                System.out.println(name + ": unsupported");
                continue;
            }

            // Extract left channel samples
            int bytesPerFrame = 2 * channels;
            int totalFrames = dataBody.length / bytesPerFrame;

            short[] samples = new short[totalFrames];
            for (int i = 0; i < totalFrames; i++) {
                int offset = i * bytesPerFrame;
                samples[i] = (short) ((dataBody[offset] & 0xFF) | ((dataBody[offset + 1] & 0xFF) << 8));
            }

            // DTMF detection
            int N = sampleRate / 50;
            int numBlocks = totalFrames / N;

            char[] labels = new char[numBlocks]; // 0 = no digit

            for (int b = 0; b < numBlocks; b++) {
                int startIdx = b * N;

                // Energy
                long E = 0;
                for (int n = 0; n < N; n++) {
                    long x = samples[startIdx + n];
                    E += x * x;
                }

                if (E < 1000000L * N) {
                    labels[b] = 0;
                    continue;
                }

                // Goertzel for all 8 frequencies
                double maxLowR = -1, maxHighR = -1;
                int maxLowIdx = -1, maxHighIdx = -1;

                for (int fi = 0; fi < 4; fi++) {
                    double r = goertzel(samples, startIdx, N, lowFreqs[fi], sampleRate, E);
                    if (r > maxLowR) {
                        maxLowR = r;
                        maxLowIdx = fi;
                    }
                }

                for (int fi = 0; fi < 4; fi++) {
                    double r = goertzel(samples, startIdx, N, highFreqs[fi], sampleRate, E);
                    if (r > maxHighR) {
                        maxHighR = r;
                        maxHighIdx = fi;
                    }
                }

                if (maxLowR >= 0.1 && maxHighR >= 0.1 && maxLowR + maxHighR >= 0.6) {
                    labels[b] = keypad[maxLowIdx][maxHighIdx];
                } else {
                    labels[b] = 0;
                }
            }

            // Bridging (use original labels for neighbor checks)
            char[] bridged = Arrays.copyOf(labels, labels.length);
            for (int i = 1; i < numBlocks - 1; i++) {
                if (labels[i] == 0 && labels[i - 1] != 0 && labels[i + 1] != 0 && labels[i - 1] == labels[i + 1]) {
                    bridged[i] = labels[i - 1];
                }
            }

            // Events: maximal runs of same digit, length >= 2
            List<String[]> events = new ArrayList<>();
            int i = 0;
            while (i < numBlocks) {
                if (bridged[i] != 0) {
                    int j = i;
                    while (j < numBlocks && bridged[j] == bridged[i]) {
                        j++;
                    }
                    if (j - i >= 2) {
                        events.add(new String[]{
                            String.valueOf(bridged[i]),
                            String.valueOf(20 * i),
                            String.valueOf(20 * j)
                        });
                    }
                    i = j;
                } else {
                    i++;
                }
            }

            // Output
            System.out.println(name + ": " + sampleRate + " Hz, " + channels + " ch, " + numBlocks + " blocks");
            StringBuilder digits = new StringBuilder();
            for (String[] ev : events) {
                System.out.println(ev[0] + " " + ev[1] + " " + ev[2]);
                digits.append(ev[0]);
            }
            System.out.println("digits: " + digits.toString());
        }
    }

    static double goertzel(short[] samples, int start, int N, int freq, int rate, long E) {
        double c = 2.0 * Math.cos(2.0 * Math.PI * freq / rate);
        double s1 = 0, s2 = 0;
        for (int n = 0; n < N; n++) {
            double s = samples[start + n] + c * s1 - s2;
            s2 = s1;
            s1 = s;
        }
        double P = s1 * s1 + s2 * s2 - c * s1 * s2;
        return 2.0 * P / (N * (double) E);
    }
}

