import Foundation

// JSON value
enum JV {
    case str(String)
    case num(String)
    case bool(Bool)
    case nul
    case arr([JV])
    case obj([(String, JV)])
    case raw(Data)  // raw JSON bytes to embed as-is
}

// Parsed with position
struct PJ {
    let v: JV
    let s: Int  // start byte offset
    let e: Int  // end byte offset (one past)
}

// Parser
final class JP {
    let b: [UInt8]
    var p: Int
    init(_ d: Data) { b = Array(d); p = 0 }

    func go() -> PJ { ws(); return pv() }

    func pv() -> PJ {
        ws()
        let st = p
        let v: JV
        switch b[p] {
        case 0x7B: v = po().0
        case 0x5B: v = .arr(pa())
        case 0x22: v = .str(ps())
        case 0x74: ex("true"); v = .bool(true)
        case 0x66: ex("false"); v = .bool(false)
        case 0x6E: ex("null"); v = .nul
        default: v = .num(pn())
        }
        return PJ(v: v, s: st, e: p)
    }

    func po() -> (JV, [(String, PJ)]) {
        p += 1; var pairs: [(String,JV)] = []; var pp: [(String,PJ)] = []
        ws(); if p < b.count && b[p] == 0x7D { p += 1; return (.obj(pairs), pp) }
        while true {
            ws(); let k = ps(); ws(); p += 1; let vp = pv()
            pairs.append((k, vp.v)); pp.append((k, vp))
            ws()
            if b[p] == 0x2C { p += 1 } else if b[p] == 0x7D { p += 1; break } else { fatalError("obj") }
        }
        return (.obj(pairs), pp)
    }

    func pa() -> [JV] {
        p += 1; var a: [JV] = []
        ws(); if p < b.count && b[p] == 0x5D { p += 1; return a }
        while true {
            a.append(pv().v); ws()
            if b[p] == 0x2C { p += 1 } else if b[p] == 0x5D { p += 1; break } else { fatalError("arr") }
        }
        return a
    }

    func ps() -> String {
        p += 1; var r = ""
        while p < b.count {
            let c = b[p]
            if c == 0x22 { p += 1; return r }
            if c == 0x5C {
                p += 1; let e = b[p]
                switch e {
                case 0x22: r.append("\""); p+=1
                case 0x5C: r.append("\\"); p+=1
                case 0x2F: r.append("/"); p+=1
                case 0x62: r.append("\u{08}"); p+=1
                case 0x66: r.append("\u{0C}"); p+=1
                case 0x6E: r.append("\n"); p+=1
                case 0x72: r.append("\r"); p+=1
                case 0x74: r.append("\t"); p+=1
                case 0x75:
                    p+=1; let cp = ph4()
                    if cp >= 0xD800 && cp <= 0xDBFF { p+=1; p+=1; let cp2 = ph4(); r.append(Character(UnicodeScalar(0x10000+(cp-0xD800)*0x400+(cp2-0xDC00))!)) }
                    else { r.append(Character(UnicodeScalar(cp)!)) }
                default: p+=1
                }
            } else if c < 0x80 { r.append(Character(UnicodeScalar(c))); p+=1 }
            else {
                let s=p; if c<0xE0{p+=2}else if c<0xF0{p+=3}else{p+=4}
                r += String(bytes: b[s..<p], encoding: .utf8)!
            }
        }
        fatalError("str")
    }

    func pn() -> String { let s=p; while p<b.count { let c=b[p]; if (c>=0x30&&c<=0x39)||c==0x2D||c==0x2B||c==0x2E||c==0x65||c==0x45{p+=1}else{break}}; return String(bytes:b[s..<p],encoding:.utf8)! }

    func ws() { while p<b.count { let c=b[p]; if c==0x20||c==0x09||c==0x0A||c==0x0D{p+=1}else{break}} }
    func ex(_ s:String) { for ch in s.utf8 { guard p<b.count&&b[p]==ch else{fatalError("ex")}; p+=1 } }
    func ph4() -> UInt32 { var v:UInt32=0; for _ in 0..<4 { let c=b[p]; v<<=4; if c>=0x30&&c<=0x39{v|=UInt32(c-0x30)}else if c>=0x61&&c<=0x66{v|=UInt32(c-0x61+10)}else if c>=0x41&&c<=0x46{v|=UInt32(c-0x41+10)}else{fatalError("hex")}; p+=1 }; return v }
}

// Serializer
func esc(_ s: String) -> String {
    var r = ""
    for u in s.unicodeScalars {
        switch u.value {
        case 0x22: r += "\\\""
        case 0x5C: r += "\\\\"
        case 0x08: r += "\\b"
        case 0x0C: r += "\\f"
        case 0x0A: r += "\\n"
        case 0x0D: r += "\\r"
        case 0x09: r += "\\t"
        default: if u.value < 0x20 { r += String(format: "\\u%04x", u.value) } else { r.unicodeScalars.append(u) }
        }
    }
    return r
}

func ser(_ v: JV) -> String {
    switch v {
    case .str(let s): return "\"\(esc(s))\""
    case .num(let s): return s
    case .bool(let b): return b ? "true" : "false"
    case .nul: return "null"
    case .arr(let a): return "[" + a.map{ser($0)}.joined(separator:",") + "]"
    case .obj(let p): return "{" + p.map{"\"\(esc($0.0))\":\(ser($0.1))"}.joined(separator:",") + "}"
    case .raw(let d): return String(data: d, encoding: .utf8)!
    }
}

// CSV
struct IR { let sku:String; let name:String; let pc:Int; let cur:String; let stk:Int }

func parseCSV(_ d: Data) -> [IR] {
    var b = Array(d)
    if b.count>=3 && b[0]==0xEF && b[1]==0xBB && b[2]==0xBF { b=Array(b[3...]) }
    var rows:[IR]=[]; var p=0; var first=true
    while p<b.count { let (f,_)=rr(b,&p); if first{first=false;continue}; if f.count>=5{rows.append(IR(sku:f[0],name:f[1],pc:Int(f[2])??0,cur:f[3],stk:Int(f[4])??0))} }
    return rows
}

func rr(_ b:[UInt8],_ p:inout Int)->([String],Bool){var f:[String]=[];while true{let(v,e)=rf(b,&p);f.append(v);if e{return(f,true)}}}

func rf(_ b:[UInt8],_ p:inout Int)->(String,Bool){
    if p>=b.count{return("",true)}
    if b[p]==0x22{p+=1;var v=""
        while p<b.count{if b[p]==0x22{if p+1<b.count&&b[p+1]==0x22{v.append("\"");p+=2}else{p+=1;if p>=b.count{return(v,true)};if b[p]==0x0D{p+=1;if p<b.count&&b[p]==0x0A{p+=1};return(v,true)};if b[p]==0x0A{p+=1;return(v,true)};if b[p]==0x2C{p+=1;return(v,false)};return(v,true)}}else{let c=b[p];if c<0x80{v.append(Character(UnicodeScalar(c)));p+=1}else if c<0xE0{let s=p;p+=2;v+=String(bytes:b[s..<p],encoding:.utf8)!}else if c<0xF0{let s=p;p+=3;v+=String(bytes:b[s..<p],encoding:.utf8)!}else{let s=p;p+=4;v+=String(bytes:b[s..<p],encoding:.utf8)!}}}
        return(v,true)
    }else{var v=""
        while p<b.count{let c=b[p];if c==0x2C{p+=1;return(v,false)};if c==0x0D{p+=1;if p<b.count&&b[p]==0x0A{p+=1};return(v,true)};if c==0x0A{p+=1;return(v,true)};if c<0x80{v.append(Character(UnicodeScalar(c)));p+=1}else if c<0xE0{let s=p;p+=2;v+=String(bytes:b[s..<p],encoding:.utf8)!}else if c<0xF0{let s=p;p+=3;v+=String(bytes:b[s..<p],encoding:.utf8)!}else{let s=p;p+=4;v+=String(bytes:b[s..<p],encoding:.utf8)!}}
        return(v,true)
    }
}

// HTTP
func post(_ u:String,_ h:[(String,String)],_ body:Data)->(Int,Data){
    let url=URL(string:u)!; var req=URLRequest(url:url); req.httpMethod="POST"
    for(k,v)in h{req.setValue(v,forHTTPHeaderField:k)}; req.httpBody=body
    let sem=DispatchSemaphore(value:0); var code=0; var rd=Data()
    URLSession.shared.dataTask(with:req){d,r,_ in if let hr=r as? HTTPURLResponse{code=hr.statusCode};if let d=d{rd=d};sem.signal()}.resume()
    sem.wait(); return(code,rd)
}

