import Foundation

// --- JSON Parser with byte position tracking ---

enum JV {
    case str(String)
    case num(String)
    case bool(Bool)
    case nul
    case arr([JV])
    case obj([(String, JV)])
}

struct JP {
    let v: JV
    let s: Int
    let e: Int
}

final class Parser {
    let b: [UInt8]
    var p: Int

    init(_ d: Data) { b = Array(d); p = 0 }

    func ws() {
        while p < b.count {
            let c = b[p]
            if c == 0x20 || c == 0x09 || c == 0x0A || c == 0x0D { p += 1 } else { break }
        }
    }

    func parse() -> JP { ws(); return pv() }

    func pv() -> JP {
        ws()
        let st = p
        let v: JV
        guard p < b.count else { fatalError("eof") }
        switch b[p] {
        case 0x7B: v = po().0
        case 0x5B: v = pa()
        case 0x22: v = .str(ps())
        case 0x74: ex("true"); v = .bool(true)
        case 0x66: ex("false"); v = .bool(false)
        case 0x6E: ex("null"); v = .nul
        default: v = .num(pn())
        }
        return JP(v: v, s: st, e: p)
    }

    func po() -> (JV, [(String, JP)]) {
        p += 1
        var pairs: [(String, JV)] = []
        var posPairs: [(String, JP)] = []
        ws()
        if p < b.count && b[p] == 0x7D { p += 1; return (.obj(pairs), posPairs) }
        while true {
            ws()
            let k = ps()
            ws(); p += 1
            let vp = pv()
            pairs.append((k, vp.v))
            posPairs.append((k, vp))
            ws()
            if p < b.count && b[p] == 0x2C { p += 1 }
            else if p < b.count && b[p] == 0x7D { p += 1; break }
            else { fatalError("obj") }
        }
        return (.obj(pairs), posPairs)
    }

    func pa() -> JV {
        p += 1
        var arr: [JV] = []
        ws()
        if p < b.count && b[p] == 0x5D { p += 1; return .array(arr) }
        while true {
            arr.append(pv().v)
            ws()
            if p < b.count && b[p] == 0x2C { p += 1 }
            else if p < b.count && b[p] == 0x5D { p += 1; break }
            else { fatalError("arr") }
        }
        return .array(arr)
    }

    func ps() -> String {
        p += 1
        var r = ""
        while p < b.count {
            let c = b[p]
            if c == 0x22 { p += 1; return r }
            if c == 0x5C {
                p += 1
                let e = b[p]
                switch e {
                case 0x22: r.append("\""); p += 1
                case 0x5C: r.append("\\"); p += 1
                case 0x2F: r.append("/"); p += 1
                case 0x62: r.append("\u{08}"); p += 1
                case 0x66: r.append("\u{0C}"); p += 1
                case 0x6E: r.append("\n"); p += 1
                case 0x72: r.append("\r"); p += 1
                case 0x74: r.append("\t"); p += 1
                case 0x75:
                    p += 1
                    let cp = ph4()
                    if cp >= 0xD800 && cp <= 0xDBFF {
                        p += 1; p += 1
                        let cp2 = ph4()
                        let full = 0x10000 + (cp - 0xD800) * 0x400 + (cp2 - 0xDC00)
                        r.append(Character(UnicodeScalar(full)!))
                    } else {
                        r.append(Character(UnicodeScalar(cp)!))
                    }
                default: p += 1
                }
            } else if c < 0x80 {
                r.append(Character(UnicodeScalar(c))); p += 1
            } else {
                let s = p
                if c < 0xE0 { p += 2 } else if c < 0xF0 { p += 3 } else { p += 4 }
                r += String(bytes: Array(b[s..<p]), encoding: .utf8)!
            }
        }
        fatalError("unterminated string")
    }

    func pn() -> String {
        let s = p
        while p < b.count {
            let c = b[p]
            if (c >= 0x30 && c <= 0x39) || c == 0x2D || c == 0x2B || c == 0x2E || c == 0x65 || c == 0x45 { p += 1 }
            else { break }
        }
        return String(bytes: Array(b[s..<p]), encoding: .utf8)!
    }

    func ex(_ s: String) {
        for ch in s.utf8 {
            guard p < b.count && b[p] == ch else { fatalError("expect") }
            p += 1
        }
    }

    func ph4() -> UInt32 {
        var v: UInt32 = 0
        for _ in 0..<4 {
            let c = b[p]
            v <<= 4
            if c >= 0x30 && c <= 0x39 { v |= UInt32(c - 0x30) }
            else if c >= 0x61 && c <= 0x66 { v |= UInt32(c - 0x61 + 10) }
            else if c >= 0x41 && c <= 0x46 { v |= UInt32(c - 0x41 + 10) }
            else { fatalError("hex") }
            p += 1
        }
        return v
    }
}

// --- JSON string escaping for output ---

func escStr(_ s: String) -> String {
    var r = ""
    for u in s.unicodeScalars {
        switch u.value {
        case 0x22: r += "\\\""
        case 0x5C: r += "\\\\"
        case 0x08: r += "\\b"
        case 0x0C: r += "\\f"
        case 0x0A: r += "\\n"
        case 0x0D: r += "\\r"
        case 0x09: r += "\\t"
        default:
            if u.value < 0x20 { r += String(format: "\\u%04x", u.value) }
            else { r.unicodeScalars.append(u) }
        }
    }
    return r
}

// --- CSV Parser (RFC 4180) ---

func parseCSV(_ data: Data) -> [[String]] {
    var bytes = Array(data)
    if bytes.count >= 3 && bytes[0] == 0xEF && bytes[1] == 0xBB && bytes[2] == 0xBF {
        bytes = Array(bytes[3...])
    }
    var rows: [[String]] = []
    var i = 0
    while i < bytes.count {
        var fields: [String] = []
        var rowDone = false
        while !rowDone {
            var field = ""
            var fieldDone = false
            if i < bytes.count && bytes[i] == 0x22 {
                i += 1
                while i < bytes.count {
                    if bytes[i] == 0x22 {
                        if i + 1 < bytes.count && bytes[i + 1] == 0x22 {
                            field.append("\"")
                            i += 2
                        } else {
                            i += 1
                            if i >= bytes.count { rowDone = true; fieldDone = true }
                            else if bytes[i] == 0x2C { i += 1; fieldDone = true }
                            else if bytes[i] == 0x0D {
                                i += 1
                                if i < bytes.count && bytes[i] == 0x0A { i += 1 }
                                rowDone = true; fieldDone = true
                            } else if bytes[i] == 0x0A { i += 1; rowDone = true; fieldDone = true }
                            else { fieldDone = true }
                        }
                    } else {
                        let c = bytes[i]
                        if c < 0x80 { field.append(Character(UnicodeScalar(c))); i += 1 }
                        else if c < 0xE0 { let s = i; i += 2; field += String(bytes: Array(bytes[s..<i]), encoding: .utf8)! }
                        else if c < 0xF0 { let s = i; i += 3; field += String(bytes: Array(bytes[s..<i]), encoding: .utf8)! }
                        else { let s = i; i += 4; field += String(bytes: Array(bytes[s..<i]), encoding: .utf8)! }
                    }
                }
                if !fieldDone { fieldDone = true; rowDone = true }
            } else {
                while i < bytes.count {
                    let c = bytes[i]
                    if c == 0x2C { i += 1; fieldDone = true; break }
                    if c == 0x0D {
                        i += 1
                        if i < bytes.count && bytes[i] == 0x0A { i += 1 }
                        rowDone = true; fieldDone = true; break
                    }
                    if c == 0x0A { i += 1; rowDone = true; fieldDone = true; break }
                    if c < 0x80 { field.append(Character(UnicodeScalar(c))); i += 1 }
                    else if c < 0xE0 { let s = i; i += 2; field += String(bytes: Array(bytes[s..<i]), encoding: .utf8)! }
                    else if c < 0xF0 { let s = i; i += 3; field += String(bytes: Array(bytes[s..<i]), encoding: .utf8)! }
                    else { let s = i; i += 4; field += String(bytes: Array(bytes[s..<i]), encoding: .utf8)! }
                }
                if !fieldDone { fieldDone = true; rowDone = true }
            }
            fields.append(field)
            if fieldDone { break }
        }
        if !fields.isEmpty { rows.append(fields) }
    }
    return rows
}

// --- HTTP ---

func httpPost(_ urlString: String, headers: [(String, String)], body: Data) -> (Int, Data) {
    let url = URL(string: urlString)!
    var req = URLRequest(url: url)
    req.httpMethod = "POST"
    req.setValue("HTTP/1.1", forHTTPHeaderField: "X-HTTP-Version")
    for (k, v) in headers { req.setValue(v, forHTTPHeaderField: k) }
    req.httpBody = body
    let sem = DispatchSemaphore(value: 0)
    var statusCode = 0
    var respData = Data()
    let task = URLSession.shared.dataTask(with: req) { d, r, _ in
        if let hr = r as? HTTPURLResponse { statusCode = hr.statusCode }
        if let d = d { respData = d }
        sem.signal()
    }
    task.resume()
    sem.wait()
    return (statusCode, respData)
}

