func serJV(_ v: JV) -> String {
    switch v {
    case .str(let s): return "\"\(escStr(s))\""
    case .num(let s): return s
    case .bool(let b): return b ? "true" : "false"
    case .nul: return "null"
    case .arr(let a): return "[" + a.map { serJV($0) }.joined(separator: ",") + "]"
    case .obj(let p): return "{" + p.map { "\"\(escStr($0.0))\":\(serJV($0.1))" }.joined(separator: ",") + "}"
    }
}

