func executeTool(name: String, argsRaw: String) -> String {
    // Parse arguments
    let argsData = Data(argsRaw.utf8)
    let argsJP = Parser(argsData).parse()

    var argsDict: [String: JV] = [:]
    if case .obj(let pairs) = argsJP.v {
        for (k, v) in pairs { argsDict[k] = v }
    }

    if name == "inventory_lookup" {
        var sku = ""
        if case .str(let s)? = argsDict["sku"] { sku = s }
        if let entry = invMap[sku] {
            return "{\"sku\":\"\(escStr(sku))\",\"name\":\"\(escStr(entry.name))\",\"price_cents\":\(entry.pc),\"currency\":\"\(escStr(entry.cur))\",\"stock\":\(entry.stk)}"
        } else {
            return "{\"error\":\"unknown sku: \(escStr(sku))\"}"
        }
    } else if name == "convert_currency" {
        var amountCents = 0
        var from = ""
        var to = ""
        if case .num(let ns)? = argsDict["amount_cents"] { amountCents = Int(ns) ?? 0 }
        if case .str(let s)? = argsDict["from"] { from = s }
        if case .str(let s)? = argsDict["to"] { to = s }
        let rateFrom = rates[from] ?? 1000000
        let rateTo = rates[to] ?? 1000000
        // HALF_UP: (2 * amount * rates[to] + rates[from]) / (2 * rates[from])
        let numerator = 2 * amountCents * rateTo + rateFrom
        let denominator = 2 * rateFrom
        let converted = numerator / denominator
        return "{\"amount_cents\":\(converted),\"currency\":\"\(escStr(to))\"}"
    } else {
        return "{\"error\":\"unknown tool: \(escStr(name))\"}"
    }
}

import * as fs from 'fs';

const dir = process.argv[2];
const data = fs.readFileSync(dir + '/db.sqlite');

// Parse file header
const pageSizeRaw = data.readUInt16BE(16);
const pageSize = pageSizeRaw === 1 ? 65536 : pageSizeRaw;
const reservedBytes = data[20];
const usableSize = pageSize - reservedBytes;

function getPage(pageNum: number): Buffer {
    return data.subarray((pageNum - 1) * pageSize, pageNum * pageSize);
}

function readVarint(buf: Buffer, offset: number): [bigint, number] {
    let result = 0n;
    let i = offset;
    let byteCount = 0;
    while (i < buf.length) {
        const byte = buf[i];
        if (byteCount === 8) {
            result = (result << 8n) | BigInt(byte);
            i++;
            break;
        } else {
            result = (result << 7n) | BigInt(byte & 0x7F);
            i++;
            if (byte < 0x80) break;
            byteCount++;
        }
    }
    return [result, i - offset];
}

interface PageHeader {
    type: number;
    numCells: number;
    cellContentStart: number;
    rightMost: number;
    cellPointers: number[];
}

function readPageHeader(page: Buffer, pageNum: number): PageHeader {
    const off = pageNum === 1 ? 100 : 0;
    const type = page[off];
    const numCells = page.readUInt16BE(off + 3);
    const cellContentStart = page.readUInt16BE(off + 5);
    const isInterior = type === 2 || type === 5;
    const rightMost = isInterior ? page.readUInt32BE(off + 8) : 0;
    const cpStart = off + (isInterior ? 12 : 8);
    const cellPointers: number[] = [];
    for (let i = 0; i < numCells; i++) {
        cellPointers.push(page.readUInt16BE(cpStart + i * 2));
    }
    return { type, numCells, cellContentStart, rightMost, cellPointers };
}

function readOverflowPayload(page: Buffer, cellOffset: number): Buffer {
    const overflowPage = page.readUInt32BE(cellOffset);
    const [payloadLen, plLen] = readVarint(page, cellOffset + 4);
    const pLen = Number(payloadLen);
    const maxLocal = usableSize - 35;

    let localSize: number;
    if (pLen <= maxLocal) {
        localSize = pLen;
    } else {
        localSize = Math.min(35 + ((pLen - 35) % (usableSize - 4)), maxLocal);
    }

    if (overflowPage === 0) {
        return Buffer.from(page.subarray(cellOffset + 4 + plLen, cellOffset + 4 + plLen + pLen));
    }

    const result = Buffer.alloc(pLen);
    page.copy(result, 0, cellOffset + 4 + plLen, cellOffset + 4 + plLen + localSize);

    let remaining = pLen - localSize;
    let curPage = overflowPage;
    let wOff = localSize;

    while (curPage !== 0 && remaining > 0) {
        const op = getPage(curPage);
        const next = op.readUInt32BE(0);
        const chunk = Math.min(remaining, usableSize - 4);
        op.copy(result, wOff, 4, 4 + chunk);
        wOff += chunk;
        remaining -= chunk;
        curPage = next;
    }

    return result;
}

function readRecord(payload: Buffer): any[] {
    let offset = 0;
    const [headerSize, hsLen] = readVarint(payload, 0);
    const hs = Number(headerSize);
    offset += hsLen;

    const serialTypes: number[] = [];
    while (offset < hs) {
        const [st, len] = readVarint(payload, offset);
        serialTypes.push(Number(st));
        offset += len;
    }

    const values: any[] = [];
    for (const st of serialTypes) {
        if (st === 0) {
