        } else if (st >= 1 && st <= 4) {
            let b = 0n;
            for (let i = 0; i < st; i++) b = (b << 8n) | BigInt(payload[offset + i]);
            values.push({ class: 'INTEGER', value: BigInt.asIntN(st * 8, b) });
            offset += st;
        } else if (st === 5) {
            let b = 0n;
            for (let i = 0; i < 6; i++) b = (b << 8n) | BigInt(payload[offset + i]);
            values.push({ class: 'INTEGER', value: BigInt.asIntN(48, b) });
            offset += 6;
        } else if (st === 6) {
            let b = 0n;
            for (let i = 0; i < 8; i++) b = (b << 8n) | BigInt(payload[offset + i]);
            values.push({ class: 'INTEGER', value: b });
            offset += 8;
        } else if (st === 7) {
            values.push({ class: 'REAL', value: payload.readDoubleBE(offset) });
            offset += 8;
        } else if (st === 8) {
            values.push({ class: 'INTEGER', value: 0n });
        } else if (st === 9) {
            values.push({ class: 'INTEGER', value: 1n });
        } else if (st >= 12 && st % 2 === 0) {
