function crc32(buf: Buffer): number {
    let crc = 0xFFFFFFFF;
    for (let i = 0; i < buf.length; i++) {
        crc ^= buf[i];
        for (let j = 0; j < 8; j++) {
            crc = (crc & 1) ? ((crc >>> 1) ^ 0xEDB88320) : (crc >>> 1);
        }
    }
    return (crc ^ 0xFFFFFFFF) >>> 0;
}

function formatReal(value: number): string {
    const neg = value < 0 || Object.is(value, -0);
    const abs = Math.abs(value);
    const intPart = Math.floor(abs);
    const fracPart = abs - intPart;
    let fracDigits = Math.round(fracPart * 1e8);
    if (fracDigits >= 100000000) fracDigits = 0;
    let fracStr = fracDigits.toString().padStart(8, '0').replace(/0+$/, '');
    if (fracStr === '') fracStr = '0';
    return (neg ? '-' : '') + intPart.toString() + '.' + fracStr;
}

function formatTextBuf(data: Buffer): Buffer {
    const parts: Buffer[] = [Buffer.from('"')];
    for (let i = 0; i < data.length; i++) {
        const b = data[i];
        if (b === 0x5C) parts.push(Buffer.from('\\\\'));
        else if (b === 0x22) parts.push(Buffer.from('\\"'));
        else if (b === 0x0A) parts.push(Buffer.from('\\n'));
        else if (b === 0x0D) parts.push(Buffer.from('\\r'));
        else if (b === 0x09) parts.push(Buffer.from('\\t'));
        else if (b < 0x20 || b === 0x7F) parts.push(Buffer.from('\\x' + b.toString(16).padStart(2, '0').toUpperCase()));
        else parts.push(Buffer.from([b]));
    }
    parts.push(Buffer.from('"'));
    return Buffer.concat(parts);
}

function formatBlobBuf(data: Buffer): Buffer {
    let hex = '';
    for (let i = 0; i < data.length; i++) {
        hex += data[i].toString(16).toUpperCase().padStart(2, '0');
    }
    return Buffer.from("X'" + hex + "'");
}

function formatValue(val: any): Buffer {
    if (val.class === 'NULL') return Buffer.from('NULL');
    if (val.class === 'INTEGER') return Buffer.from(val.value.toString());
    if (val.class === 'REAL') return Buffer.from(formatReal(val.value));
    if (val.class === 'TEXT') {
        if (val.data.length <= 100) return formatTextBuf(val.data);
        return Buffer.from(`<TEXT len=${val.data.length} crc32=${crc32(val.data).toString(16).padStart(8, '0')}>`);
    }
    if (val.class === 'BLOB') {
        if (val.data.length <= 100) return formatBlobBuf(val.data);
        return Buffer.from(`<BLOB len=${val.data.length} crc32=${crc32(val.data).toString(16).padStart(8, '0')}>`);
    }
    return Buffer.from('NULL');
}

function traverseTableBTree(rootPageNum: number): Array<{ rowid: bigint; payload: Buffer }> {
    const rows: Array<{ rowid: bigint; payload: Buffer }> = [];

    function go(pageNum: number) {
        if (pageNum === 0) return;
        const page = getPage(pageNum);
        const hdr = readPageHeader(page, pageNum);

        if (hdr.type === 13) {
            for (const cellOff of hdr.cellPointers) {
                const overflowPage = page.readUInt32BE(cellOff);
                const [payloadLen, plLen] = readVarint(page, cellOff + 4);
                const pLen = Number(payloadLen);
                const maxLocal = usableSize - 35;

                let localSize: number;
                if (pLen <= maxLocal) localSize = pLen;
                else localSize = Math.min(35 + ((pLen - 35) % (usableSize - 4)), maxLocal);

                const rowidOff = cellOff + 4 + plLen + localSize;
                const [rowidRaw] = readVarint(page, rowidOff);
                const rowid = BigInt.asIntN(64, rowidRaw);

                const payload = readOverflowPayload(page, cellOff);
                rows.push({ rowid, payload });
            }
        } else if (hdr.type === 2) {
            for (const cellOff of hdr.cellPointers) {
                const child = page.readUInt32BE(cellOff);
                go(child);
            }
            go(hdr.rightMost);
        }
    }

    go(rootPageNum);
    return rows;
}

function parseCreateTable(sql: string): { columns: string[]; rowidAlias: number } {
    // Find first '(' not inside double quotes
    let parenStart = -1;
    let inQ = false;
    for (let i = 0; i < sql.length; i++) {
        if (sql[i] === '"') inQ = !inQ;
        else if (!inQ && sql[i] === '(') { parenStart = i; break; }
    }

    // Find matching ')'
    let depth = 0;
    inQ = false;
    let parenEnd = -1;
    for (let i = parenStart; i < sql.length; i++) {
        if (sql[i] === '"') inQ = !inQ;
        else if (!inQ) {
            if (sql[i] === '(') depth++;
            else if (sql[i] === ')') { depth--; if (depth === 0) { parenEnd = i; break; } }
        }
    }

    const defs = sql.substring(parenStart + 1, parenEnd);

    // Split by top-level commas (not inside parens or quotes)
    const parts: string[] = [];
    depth = 0;
    inQ = false;
    let cur = '';
    for (let i = 0; i < defs.length; i++) {
        const c = defs[i];
        if (c === '"') { inQ = !inQ; cur += c; }
        else if (!inQ) {
            if (c === '(') { depth++; cur += c; }
            else if (c === ')') { depth--; cur += c; }
            else if (c === ',' && depth === 0) { parts.push(cur.trim()); cur = ''; }
            else cur += c;
        } else cur += c;
    }
    if (cur.trim()) parts.push(cur.trim());

    const columns: string[] = [];
    let rowidAlias = -1;

    for (let idx = 0; idx < parts.length; idx++) {
        const def = parts[idx];
        let colName: string;
        let rest: string;

        if (def.startsWith('"')) {
            const eq = def.indexOf('"', 1);
            colName = def.substring(1, eq);
            rest = def.substring(eq + 1).trim();
        } else {
            const m = def.match(/^(\S+)/);
            colName = m![1];
            rest = def.substring(colName.length).trim();
        }

        columns.push(colName);

        // Check rowid alias: type is exactly INTEGER (case insensitive) and contains PRIMARY KEY
        const restUpper = rest.toUpperCase();
        const typeMatch = rest.match(/^([A-Za-z0-9_]+)/);
        const typeName = typeMatch ? typeMatch[1].toUpperCase() : '';

        if (typeName === 'INTEGER' && restUpper.includes('PRIMARY') && restUpper.includes('KEY')) {
            rowidAlias = idx;
        }
    }

    return { columns, rowidAlias };
}

