const usableSize = pageSize - reservedBytes;

function getPage(pageNum: number): Buffer {
    return data.subarray((pageNum - 1) * pageSize, pageNum * pageSize);
}

function readVarint(buf: Buffer, offset: number): [number, number] {
    let result = 0;
    let i = offset;
    let shift = 0;
    while (i < buf.length) {
        const byte = buf[i];
        if (shift === 56) {
            result += byte * 2**56;
            i++;
            break;
        } else {
            result += (byte & 0x7F) * 2**shift;
            i++;
            shift += 7;
            if (byte < 0x80) break;
        }
    }
    return [result, i - offset];
}

function readVarintBig(buf: Buffer, offset: number): [bigint, number] {
    let result = 0n;
    let i = offset;
    let byteCount = 0;
    while (i < buf.length) {
        const byte = buf[i];
        if (byteCount === 8) {
            result = (result << 8n) | BigInt(byte);
            i++;
            break;
        } else {
            result = (result << 7n) | BigInt(byte & 0x7F);
            i++;
            if (byte < 0x80) break;
            byteCount++;
        }
    }
    return [result, i - offset];
}

function computeLocalSize(payloadSize: number): number {
    const minLocal = Math.floor(((usableSize - 35) * 32) / 255) - 23;
    const maxLocal = usableSize - 12;
    if (payloadSize <= maxLocal) {
        return payloadSize;
    }
    const diff = maxLocal - minLocal;
    const mod = payloadSize % (usableSize - 4);
    return minLocal + Math.floor((diff * mod) / diff);
