}

/* CRC32 (zlib/PNG) */
static uint32_t crc32_compute(const unsigned char *data, size_t len) {
    static uint32_t tab[256];
    static int init = 0;
    if (!init) {
        for (uint32_t i = 0; i < 256; i++) {
            uint32_t c = i;
            for (int j = 0; j < 8; j++)
                c = (c & 1) ? (0xEDB88320 ^ (c >> 1)) : (c >> 1);
            tab[i] = c;
        }
        init = 1;
    }
    uint32_t crc = 0xFFFFFFFF;
    for (size_t i = 0; i < len; i++)
        crc = tab[(crc ^ data[i]) & 0xFF] ^ (crc >> 8);
    return crc ^ 0xFFFFFFFF;
}

/* Value types */
enum { V_NULL, V_INT, V_REAL, V_TEXT, V_BLOB };

typedef struct {
    int type;
    int64_t ival;
    double dval;
    unsigned char *data;
    int data_len;
} Value;

typedef struct {
    int64_t rowid;
    int nvals;
    Value *vals;
} Row;

/* Dynamic array for rows */
typedef struct {
    Row *items;
    int count;
    int cap;
} RowList;

static void rowlist_add(RowList *rl, Row r) {
    if (rl->count >= rl->cap) {
        rl->cap = rl->cap ? rl->cap * 2 : 64;
        rl->items = realloc(rl->items, rl->cap * sizeof(Row));
    }
    rl->items[rl->count++] = r;
}

static int cmp_row(const void *a, const void *b) {
    int64_t ra = ((const Row *)a)->rowid;
    int64_t rb = ((const Row *)b)->rowid;
    return (ra < rb) ? -1 : (ra > rb) ? 1 : 0;
}

/* Parse a record (payload) into values */
static void parse_record(const unsigned char *payload, int plen, Row *row) {
    int pos = 0;
    uint64_t hdr_size;
    int n = read_varint(payload + pos, plen - pos, &hdr_size);
    pos += n;

    /* Count serial types */
    int nvals = 0;
    int tmp = n;
    while (tmp < (int)hdr_size && tmp < plen) {
        uint64_t st;
        tmp += read_varint(payload + tmp, plen - tmp, &st);
        nvals++;
    }

    row->nvals = nvals;
    row->vals = calloc(nvals > 0 ? nvals : 1, sizeof(Value));

    pos = n; /* restart after header size varint */
    for (int i = 0; i < nvals; i++) {
        uint64_t st;
        pos += read_varint(payload + pos, plen - pos, &st);
        Value *v = &row->vals[i];

        if (st == 0) { v->type = V_NULL; }
        else if (st == 1) { v->type = V_INT; v->ival = (int8_t)payload[pos]; pos += 1; }
        else if (st == 2) { v->type = V_INT; v->ival = (int16_t)be16(payload + pos); pos += 2; }
        else if (st == 3) {
            v->type = V_INT;
            int32_t x = ((int32_t)payload[pos] << 16) | (int32_t)be16(payload + pos + 1);
            if (x & 0x800000) x |= (int32_t)0xFF000000;
            v->ival = x;
            pos += 3;
        }
        else if (st == 4) { v->type = V_INT; v->ival = (int32_t)be32(payload + pos); pos += 4; }
        else if (st == 5) {
            v->type = V_INT;
            int64_t x = ((int64_t)be32(payload + pos) << 16) | (int64_t)be16(payload + pos + 4);
            if (x & 0x800000000000LL) x |= ~0xFFFFFFFFFFFFLL;
            v->ival = x;
            pos += 6;
        }
        else if (st == 6) { v->type = V_INT; v->ival = be64(payload + pos); pos += 8; }
        else if (st == 7) {
            v->type = V_REAL;
            uint64_t bits = be64(payload + pos);
            memcpy(&v->dval, &bits, 8);
            pos += 8;
        }
        else if (st == 8) { v->type = V_INT; v->ival = 0; }
        else if (st == 9) { v->type = V_INT; v->ival = 1; }
        else if (st >= 12 && (st & 1) == 0) {
            v->type = V_BLOB;
            v->data_len = (int)((st - 12) / 2);
            v->data = malloc(v->data_len > 0 ? v->data_len : 1);
            memcpy(v->data, payload + pos, v->data_len);
            pos += v->data_len;
        }
        else if (st >= 13) {
            v->type = V_TEXT;
            v->data_len = (int)((st - 13) / 2);
            v->data = malloc(v->data_len > 0 ? v->data_len : 1);
            memcpy(v->data, payload + pos, v->data_len);
            pos += v->data_len;
        }
    }
}

/* Compute local payload bytes for leaf table page */
static int local_payload(int P) {
    int X = g_usable - 35;
    int M = ((g_usable - 12) * 64 / 255) - 23;
    if (P <= X) return P;
    int K = M + ((P - M) % (g_usable - 4));
    return (K <= X) ? K : M;
}

/* Walk a table b-tree, collecting rows */
static void walk_table(int page_num, RowList *rl) {
    if (page_num <= 0) return;
    unsigned char *pg = page_ptr(page_num);
    int off = bt_off(page_num);
    int ptype = pg[off];

    if (ptype == 13) { /* leaf table */
        int ncells = be16(pg + off + 3);
        int cptr_off = off + 8;
        for (int i = 0; i < ncells; i++) {
            int cell_off = be16(pg + cptr_off + i * 2);
            const unsigned char *c = pg + cell_off;

            uint64_t P;
            int n = read_varint(c, g_usable - cell_off, &P);
            c += n;

            uint64_t rid_u;
            n = read_varint(c, g_usable - cell_off - n, &rid_u);
            c += n;

            int payload_sz = (int)P;
            int local = local_payload(payload_sz);

            unsigned char *payload = malloc(payload_sz > 0 ? payload_sz : 1);
            memcpy(payload, c, local);

            if (payload_sz > local) {
                uint32_t ovf = be32(c + local);
                int got = local;
                while (ovf != 0 && got < payload_sz) {
                    unsigned char *op = page_ptr(ovf);
                    int chunk = g_usable - 4;
                    if (chunk > payload_sz - got) chunk = payload_sz - got;
                    memcpy(payload + got, op + 4, chunk);
                    got += chunk;
                    ovf = be32(op);
                }
            }

            Row r;
            r.rowid = (int64_t)rid_u;
            parse_record(payload, payload_sz, &r);
            rowlist_add(rl, r);
            free(payload);
        }
    } else if (ptype == 5) { /* interior table */
        int ncells = be16(pg + off + 3);
        int cptr_off = off + 12;
        for (int i = 0; i < ncells; i++) {
            int cell_off = be16(pg + cptr_off + i * 2);
            const unsigned char *c = pg + cell_off;
            uint64_t child;
            read_varint(c, g_usable - cell_off, &child);
            walk_table((int)child, rl);
        }
        uint32_t right = be32(pg + off + 8);
        walk_table((int)right, rl);
    }
}

/* Schema entry */
typedef struct {
    char *name;
    int rootpage;
    char *sql;
} SchemaEntry;

static int cmp_schema(const void *a, const void *b) {
    return strcmp(((const SchemaEntry *)a)->name, ((const SchemaEntry *)b)->name);
}

/* Dynamic array for schema entries */
typedef struct {
    SchemaEntry *items;
    int count, cap;
} SchemaList;

static void schemalist_add(SchemaList *sl, SchemaEntry e) {
    if (sl->count >= sl->cap) {
        sl->cap = sl->cap ? sl->cap * 2 : 16;
        sl->items = realloc(sl->items, sl->cap * sizeof(SchemaEntry));
    }
    sl->items[sl->count++] = e;
}

/* Walk schema b-tree (rooted at page 1) */
static void walk_schema(int page_num, SchemaList *sl) {
    if (page_num <= 0) return;
    unsigned char *pg = page_ptr(page_num);
    int off = bt_off(page_num);
    int ptype = pg[off];

    if (ptype == 13) {
        int ncells = be16(pg + off + 3);
        int cptr_off = off + 8;
        for (int i = 0; i < ncells; i++) {
            int cell_off = be16(pg + cptr_off + i * 2);
            const unsigned char *c = pg + cell_off;

            uint64_t P;
            int n = read_varint(c, g_usable - cell_off, &P);
            c += n;
            uint64_t rid_u;
            n = read_varint(c, g_usable - cell_off - n, &rid_u);
            c += n;

            int payload_sz = (int)P;
            int local = local_payload(payload_sz);

            unsigned char *payload = malloc(payload_sz > 0 ? payload_sz : 1);
            memcpy(payload, c, local);

            if (payload_sz > local) {
                uint32_t ovf = be32(c + local);
                int got = local;
                while (ovf != 0 && got < payload_sz) {
                    unsigned char *op = page_ptr(ovf);
                    int chunk = g_usable - 4;
                    if (chunk > payload_sz - got) chunk = payload_sz - got;
                    memcpy(payload + got, op + 4, chunk);
                    got += chunk;
                    ovf = be32(op);
                }
            }

            Row r;
            parse_record(payload, payload_sz, &r);
            free(payload);

            /* Extract columns: type(0), name(1), tbl_name(2), rootpage(3), sql(4) */
            if (r.nvals >= 5) {
                Value *vtype = &r.vals[0];
                Value *vname = &r.vals[1];
                Value *vroot = &r.vals[3];
                Value *vsql = &r.vals[4];

                if (vtype->type == V_TEXT && vtype->data_len == 5 &&
                    memcmp(vtype->data, "table", 5) == 0) {
                    if (vname->type == V_TEXT && vname->data_len > 0) {
                        /* Check name doesn't start with "sqlite_" */
                        if (vname->data_len >= 7 && memcmp(vname->data, "sqlite_", 7) == 0) {
                            /* skip */
                        } else {
                            SchemaEntry se;
                            se.name = strndup((char *)vname->data, vname->data_len);
                            se.rootpage = (vroot->type == V_INT) ? (int)vroot->ival : 0;
                            if (vsql->type == V_TEXT)
                                se.sql = strndup((char *)vsql->data, vsql->data_len);
                            else
                                se.sql = strdup("");
                            schemalist_add(sl, se);
                        }
                    }
                }
            }

            /* Free row values */
            for (int j = 0; j < r.nvals; j++) {
                if (r.vals[j].type == V_TEXT || r.vals[j].type == V_BLOB)
                    free(r.vals[j].data);
            }
            free(r.vals);
        }
    } else if (ptype == 5) {
        int ncells = be16(pg + off + 3);
        int cptr_off = off + 12;
        for (int i = 0; i < ncells; i++) {
            int cell_off = be16(pg + cptr_off + i * 2);
            const unsigned char *c = pg + cell_off;
            uint64_t child;
            read_varint(c, g_usable - cell_off, &child);
            walk_schema((int)child, sl);
        }
        uint32_t right = be32(pg + off + 8);
        walk_schema((int)right, sl);
    }
}

/* SQL parsing helpers */
static const char *skip_ws(const char *s) {
    while (*s && isspace((unsigned char)*s)) s++;
    return s;
}

static int match_kw(const char **s, const char *kw) {
    int len = strlen(kw);
    if (strncasecmp(*s, kw, len) == 0) {
        char next = (*s)[len];
        if (next == '\0' || (!isalnum((unsigned char)next) && next != '_')) {
            *s += len;
            return 1;
        }
    }
    return 0;
}

static int contains_primary_key(const char *s) {
    while (*s) {
        if (strncasecmp(s, "PRIMARY", 7) == 0) {
            char next = s[7];
            if (next == '\0' || (!isalnum((unsigned char)next) && next != '_')) {
                const char *after = skip_ws(s + 7);
                if (strncasecmp(after, "KEY", 3) == 0) {
                    char k = after[3];
                    if (k == '\0' || (!isalnum((unsigned char)k) && k != '_'))
                        return 1;
                }
            }
        }
        s++;
    }
    return 0;
}

/* Read identifier (bare or double-quoted) */
static const char *read_ident(const char *s, char **out) {
    s = skip_ws(s);
    if (*s == '"') {
        s++;
        const char *start = s;
        while (*s && *s != '"') s++;
        *out = strndup(start, s - start);
        if (*s == '"') s++;
        return s;
    } else {
        const char *start = s;
        while (*s && (isalnum((unsigned char)*s) || *s == '_')) s++;
        *out = strndup(start, s - start);
        return s;
    }
}

/* Column info */
typedef struct {
    char *name;
    int is_rowid_alias;
} ColInfo;

/* Parse CREATE TABLE SQL */
static void parse_create_table(const char *sql, ColInfo **cols, int *ncols) {
    const char *s = sql;
    s = skip_ws(s);
    match_kw(&s, "CREATE");
    s = skip_ws(s);
    /* optional TEMP or TEMPORARY */
    match_kw(&s, "TEMP");
    s = skip_ws(s);
    match_kw(&s, "TEMPORARY");
    s = skip_ws(s);
    match_kw(&s, "TABLE");
    s = skip_ws(s);
    /* optional IF NOT EXISTS */
    if (match_kw(&s, "IF")) {
        s = skip_ws(s);
        match_kw(&s, "NOT");
        s = skip_ws(s);
        match_kw(&s, "EXISTS");
        s = skip_ws(s);
    }
    /* table name */
    char *tname;
    s = read_ident(s, &tname);
    free(tname);
    s = skip_ws(s);

    if (*s != '(') { *cols = NULL; *ncols = 0; return; }
    s++; /* skip '(' */

    /* Find matching ')' */
    const char *start = s;
    int depth = 1;
    while (*s && depth > 0) {
        if (*s == '(') depth++;
        else if (*s == ')') depth--;
        if (depth > 0) s++;
    }
    const char *end = s; /* points to ')' */

    /* Split by top-level commas */
    int count = 1;
    depth = 0;
    for (const char *p = start; p < end; p++) {
        if (*p == '(') depth++;
        else if (*p == ')') depth--;
        else if (*p == ',' && depth == 0) count++;
    }

    ColInfo *ci = malloc(count * sizeof(ColInfo));
    int idx = 0;
    const char *seg_start = start;
    depth = 0;
    for (const char *p = start; p <= end; p++) {
        if (p == end || (*p == ',' && depth == 0)) {
            /* Parse segment [seg_start, p) */
            const char *d = seg_start;
            d = skip_ws(d);

            /* Read column name */
            char *cname;
            d = read_ident(d, &cname);

            /* Check INTEGER PRIMARY KEY */
            int is_alias = 0;
            const char *after_name = skip_ws(d);
            const char *ts = after_name;
            while (*ts && (isalnum((unsigned char)*ts) || *ts == '_')) ts++;
            int tlen = ts - after_name;
            if (tlen == 7 && strncasecmp(after_name, "INTEGER", 7) == 0) {
                const char *after_type = skip_ws(ts);
                if (*after_type != '(') {
                    /* Check if segment contains PRIMARY KEY */
                    char *seg = strndup(seg_start, p - seg_start);
                    if (contains_primary_key(seg)) is_alias = 1;
                    free(seg);
                }
            }

            ci[idx].name = cname;
            ci[idx].is_rowid_alias = is_alias;
            idx++;

            seg_start = p + 1;
        } else {
            if (*p == '(') depth++;
            else if (*p == ')') depth--;
        }
    }

    *cols = ci;
    *ncols = idx;
}

/* Format a REAL value */
static void format_real(double val, char *buf, int bufsz) {
    snprintf(buf, bufsz, "%.8f", val);
    /* Trim trailing zeros, keep at least one after '.' */
    int len = strlen(buf);
    int dot = -1;
    for (int i = 0; i < len; i++) if (buf[i] == '.') { dot = i; break; }
    if (dot >= 0) {
        int newlen = len;
        while (newlen > dot + 2 && buf[newlen - 1] == '0') newlen--;
        buf[newlen] = '\0';
    }
}

/* Format a value for output */
static void print_value(Value *v) {
    if (v->type == V_NULL) {
        printf("NULL");
    } else if (v->type == V_INT) {
        printf("%lld", (long long)v->ival);
    } else if (v->type == V_REAL) {
        char buf[400];
        format_real(v->dval, buf, sizeof(buf));
        printf("%s", buf);
    } else if (v->type == V_TEXT) {
        if (v->data_len > 100) {
            uint32_t crc = crc32_compute(v->data, v->data_len);
            printf("<TEXT len=%d crc32=%08x>", v->data_len, crc);
        } else {
            printf("\"");
            for (int i = 0; i < v->data_len; i++) {
                unsigned char c = v->data[i];
                if (c == '\\') printf("\\\\");
                else if (c == '"') printf("\\\"");
                else if (c == '\n') printf("\\n");
                else if (c == '\r') printf("\\r");
                else if (c == '\t') printf("\\t");
                else if (c < 0x20 || c == 0x7F) printf("\\x%02X", c);
                else putchar(c);
            }
            printf("\"");
        }
    } else if (v->type == V_BLOB) {
        if (v->data_len > 100) {
            uint32_t crc = crc32_compute(v->data, v->data_len);
            printf("<BLOB len=%d crc32=%08x>", v->data_len, crc);
        } else {
            printf("X'");
            for (int i = 0; i < v->data_len; i++)
                printf("%02X", v->data[i]);
            printf("'");
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) { fprintf(stderr, "Usage: %s <dir>\n", argv[0]); return 1; }

    char path[4096];
    snprintf(path, sizeof(path), "%s/db.sqlite", argv[1]);

    FILE *f = fopen(path, "rb");
    if (!f) { perror(path); return 1; }

    fseek(f, 0, SEEK_END);
    g_file_size = ftell(f);
    fseek(f, 0, SEEK_SET);
    g_data = malloc(g_file_size);
    fread(g_data, 1, g_file_size, f);
    fclose(f);

    /* Parse header */
    int ps = be16(g_data + 16);
    g_page_size = (ps == 1) ? 65536 : ps;
    g_reserved = g_data[20];
    g_usable = g_page_size - g_reserved;

    /* Walk schema */
    SchemaList sl = {NULL, 0, 0};
    walk_schema(1, &sl);

    /* Sort by name */
    qsort(sl.items, sl.count, sizeof(SchemaEntry), cmp_schema);

    /* Process each table */
    for (int t = 0; t < sl.count; t++) {
        if (t > 0) printf("\n");

        SchemaEntry *se = &sl.items[t];

        /* Parse CREATE TABLE */
        ColInfo *cols;
        int ncols;
        parse_create_table(se->sql, &cols, &ncols);

        /* Walk table b-tree */
        RowList rl = {NULL, 0, 0};
        walk_table(se->rootpage, &rl);

        /* Sort rows by rowid */
        qsort(rl.items, rl.count, sizeof(Row), cmp_row);

        /* Print header */
        printf("TABLE %s rows=%d\n", se->name, rl.count);
        printf("COLUMNS");
        for (int c = 0; c < ncols; c++) {
            printf("%s %s", c == 0 ? " " : ", ", cols[c].name);
        }
        printf("\n");

        /* Print rows */
        for (int r = 0; r < rl.count; r++) {
            Row *row = &rl.items[r];
            printf("%lld:", (long long)row->rowid);
            for (int c = 0; c < ncols; c++) {
                printf(" ");
                if (cols[c].is_rowid_alias) {
                    printf("%lld", (long long)row->rowid);
                } else if (c < row->nvals) {
                    print_value(&row->vals[c]);
                } else {
                    printf("NULL");
                }
            }
            printf("\n");
        }

        /* Cleanup */
        for (int r = 0; r < rl.count; r++) {
            for (int v = 0; v < rl.items[r].nvals; v++) {
                if (rl.items[r].vals[v].type == V_TEXT || rl.items[r].vals[v].type == V_BLOB)
                    free(rl.items[r].vals[v].data);
            }
            free(rl.items[r].vals);
        }
        free(rl.items);
        for (int c = 0; c < ncols; c++) free(cols[c].name);
        free(cols);
    }

    free(g_data);
    return 0;
}

import sys
import socket
import hashlib
import base64
import os
import struct


def parse_ws_url(url):
    prefix = "ws://"
    rest = url[len(prefix):]
    slash_idx = rest.index('/')
    hostport = rest[:slash_idx]
    path = rest[slash_idx:]
    if ':' in hostport:
        host, port_str = hostport.rsplit(':', 1)
        port = int(port_str)
    else:
        host = hostport
        port = 80
    return host, port, path


def generate_ws_key():
    return base64.b64encode(os.urandom(16)).decode('ascii')


def compute_accept(key):
    magic = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
    sha1_digest = hashlib.sha1((key + magic).encode('ascii')).digest()
    return base64.b64encode(sha1_digest).decode('ascii')


def encode_frame(opcode, payload, mask=True):
    frame = bytearray()
    frame.append(0x80 | opcode)
    mask_bit = 0x80 if mask else 0
    length = len(payload)
    if length <= 125:
        frame.append(mask_bit | length)
    elif length <= 65535:
        frame.append(mask_bit | 126)
        frame.extend(struct.pack('!H', length))
    else:
        frame.append(mask_bit | 127)
        frame.extend(struct.pack('!Q', length))
    if mask:
        while True:
            mask_key = os.urandom(4)
            if mask_key != b'\x00\x00\x00\x00':
                break
        frame.extend(mask_key)
        masked = bytearray(length)
        for i in range(length):
            masked[i] = payload[i] ^ mask_key[i % 4]
        frame.extend(masked)
    return bytes(frame)


class WebSocketClient:
    def __init__(self, sock):
        self.sock = sock
        self.buf = bytearray()
        self.sent_close = False

    def read_bytes(self, n):
        while len(self.buf) < n:
            data = self.sock.recv(65536)
            if not data:
                raise ConnectionError("Connection closed")
            self.buf.extend(data)
        result = bytes(self.buf[:n])
        self.buf = self.buf[n:]
        return result

    def read_line(self):
        while b'\r\n' not in self.buf:
            data = self.sock.recv(65536)
            if not data:
                raise ConnectionError("Connection closed")
            self.buf.extend(data)
        idx = self.buf.index(b'\r\n')
        line = bytes(self.buf[:idx])
        self.buf = self.buf[idx + 2:]
        return line

    def handshake(self, host, port, path):
        key = generate_ws_key()
        request = (
            f"GET {path} HTTP/1.1\r\n"
            f"Host: {host}:{port}\r\n"
            f"Upgrade: websocket\r\n"
            f"Connection: Upgrade\r\n"
            f"Sec-WebSocket-Version: 13\r\n"
            f"Sec-WebSocket-Key: {key}\r\n"
            f"\r\n"
        )
        self.sock.sendall(request.encode('ascii'))

        status_line = self.read_line().decode('ascii')
        parts = status_line.split(' ', 2)
        status_code = int(parts[1])
        reason = parts[2] if len(parts) > 2 else ''

        headers = {}
        while True:
            line = self.read_line()
            if line == b'':
                break
            decoded = line.decode('ascii')
            colon_idx = decoded.index(':')
            name = decoded[:colon_idx].strip().lower()
            value = decoded[colon_idx + 1:].strip()
            headers[name] = value

        if status_code != 101:
