        """Read a complete message, handling fragmentation, pings, and pongs.
        Returns (opcode, payload) where opcode is 1 (text), 2 (binary), or 8 (close)."""
        while True:
            fin, opcode, payload = self.read_frame()

            if opcode == 9:  # Ping
                self.send_frame(10, payload)
