const BASE: u64 = 1_000_000_000;

#[derive(Debug, Clone)]
enum Value {
    Null,
    Integer(i64),
    Real(f64),
    Text(Vec<u8>),
    Blob(Vec<u8>),
}

fn read_u16_be(data: &[u8], offset: usize) -> u16 {
    ((data[offset] as u16) << 8) | (data[offset + 1] as u16)
}

fn read_u32_be(data: &[u8], offset: usize) -> u32 {
    ((data[offset] as u32) << 24) | ((data[offset + 1] as u32) << 16) |
    ((data[offset + 2] as u32) << 8) | (data[offset + 3] as u32)
}

fn read_i64_be(data: &[u8], offset: usize, nbytes: usize) -> i64 {
    let mut val: i64 = 0;
    for i in 0..nbytes {
        val = (val << 8) | (data[offset + i] as i64);
    }
    if nbytes < 8 {
        let shift = 64 - (nbytes * 8);
        val = (val << shift) >> shift;
    }
    val
}

fn read_varint(data: &[u8], offset: usize) -> (u64, usize) {
    let mut result: u64 = 0;
    let mut pos = offset;
    for i in 0..9 {
        let byte = data[pos] as u64;
        pos += 1;
        if i == 8 {
            result = (result << 8) | byte;
            break;
        } else {
            result = (result << 7) | (byte & 0x7F);
            if byte & 0x80 == 0 {
                break;
            }
        }
    }
    (result, pos - offset)
}

fn varint_size(val: u64) -> usize {
