// Big integer operations (base 10^9, little-endian)
fn bignum_mul_small(a: &mut Vec<u32>, m: u32) {
    let mut carry: u64 = 0;
    for i in 0..a.len() {
        let prod = a[i] as u64 * m as u64 + carry;
        a[i] = (prod % BASE) as u32;
        carry = prod / BASE;
    }
    while carry > 0 {
        a.push((carry % BASE) as u32);
        carry /= BASE;
    }
}

fn bignum_to_string(a: &[u32]) -> String {
    if a.is_empty() || (a.len() == 1 && a[0] == 0) {
        return "0".to_string();
    }
    let mut s = a[a.len() - 1].to_string();
    for i in (0..a.len() - 1).rev() {
        s.push_str(&format!("{:09}", a[i]));
    }
    s
}

fn format_real(d: f64) -> String {
    let bits = d.to_bits();
    let negative = bits >> 63 != 0;
    let exp_bits = ((bits >> 52) & 0x7FF) as i32;
    let mantissa = (bits & 0xFFFFFFFFFFFFF) as u64;

    let (m, e);
    if exp_bits == 0 {
        m = mantissa;
        e = -1074;
    } else {
        m = mantissa | (1u64 << 52);
        e = exp_bits - 1075;
    }

    let sign_str = if negative { "-" } else { "" };

    if m == 0 {
        return format!("{}0.0", sign_str);
    }

    if e >= 0 {
        // Integer: m * 2^e
        let mut bn: Vec<u32> = vec![(m % BASE) as u32];
        if m >= BASE { bn.push((m / BASE) as u32); }
        for _ in 0..e {
            bignum_mul_small(&mut bn, 2);
        }
        let int_str = bignum_to_string(&bn);
        format!("{}{}.0", sign_str, int_str)
    } else {
        // Fractional: m * 5^(-e) / 10^(-e)
        let frac_digits = (-e) as usize;
        let mut bn: Vec<u32> = vec![(m % BASE) as u32];
        if m >= BASE { bn.push((m / BASE) as u32); }
        for _ in 0..frac_digits {
            bignum_mul_small(&mut bn, 5);
        }
        let num_str = bignum_to_string(&bn);
        let total_digits = num_str.len();

        let int_part: String;
        let frac_part: String;

        if total_digits > frac_digits {
            int_part = num_str[..total_digits - frac_digits].to_string();
            frac_part = num_str[total_digits - frac_digits..].to_string();
        } else {
            int_part = "0".to_string();
            let pad = frac_digits - total_digits;
            frac_part = format!("{}{}", "0".repeat(pad), num_str);
        }

        // Remove trailing zeros from frac_part (keep at least one)
        let mut frac = frac_part;
        while frac.len() > 1 && frac.ends_with('0') {
            frac.pop();
        }

        // Remove leading zeros from int_part (but keep "0")
        let int_clean = int_part.trim_start_matches('0');
        let int_clean = if int_clean.is_empty() { "0" } else { int_clean };

        format!("{}{}.{}", sign_str, int_clean, frac)
    }
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc: u32 = 0xFFFFFFFF;
    for &byte in data {
        crc ^= byte as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    crc ^ 0xFFFFFFFF
}

fn escape_text(data: &[u8]) -> String {
    let mut result: Vec<u8> = Vec::new();
    result.push(b'"');
    for &b in data {
        match b {
            b'\\' => result.extend_from_slice(b"\\\\"),
            b'"' => result.extend_from_slice(b"\\\""),
            b'\n' => result.extend_from_slice(b"\\n"),
            b'\r' => result.extend_from_slice(b"\\r"),
            b'\t' => result.extend_from_slice(b"\\t"),
            _ if b < 0x20 || b == 0x7F => {
                result.extend_from_slice(format!("\\x{:02X}", b).as_bytes());
            }
            _ => result.push(b),
        }
    }
    result.push(b'"');
    String::from_utf8(result).unwrap()
}

fn format_value(v: &Value) -> String {
    match v {
        Value::Null => "NULL".to_string(),
        Value::Integer(n) => n.to_string(),
        Value::Real(d) => format_real(*d),
        Value::Text(bytes) => {
            if bytes.len() <= 100 {
                escape_text(bytes)
            } else {
                let crc = crc32(bytes);
                format!("<TEXT len={} crc32={:08x}>", bytes.len(), crc)
            }
        }
        Value::Blob(bytes) => {
            if bytes.len() <= 100 {
                let hex: String = bytes.iter().map(|b| format!("{:02X}", b)).collect();
                format!("X'{}'", hex)
            } else {
                let crc = crc32(bytes);
                format!("<BLOB len={} crc32={:08x}>", bytes.len(), crc)
            }
        }
    }
}

fn decode_record(payload: &[u8]) -> Vec<Value> {
    let mut values = Vec::new();
    let (header_size, _) = read_varint(payload, 0);
    let header_size = header_size as usize;

    // Read serial types
    let mut pos = 0;
    let (_, hdr_varint_size) = read_varint(payload, 0);
    let serial_start = hdr_varint_size;

    pos = serial_start;
    let mut serial_types = Vec::new();
    while pos < header_size {
        let (st, sz) = read_varint(payload, pos);
        serial_types.push(st);
        pos += sz;
    }

    // Read values
    let mut data_pos = header_size;
    for &st in &serial_types {
        match st {
            0 => values.push(Value::Null),
            1 => {
                let v = read_i64_be(payload, data_pos, 1);
                values.push(Value::Integer(v));
                data_pos += 1;
            }
            2 => {
                let v = read_i64_be(payload, data_pos, 2);
                values.push(Value::Integer(v));
                data_pos += 2;
            }
            3 => {
                let v = read_i64_be(payload, data_pos, 3);
                values.push(Value::Integer(v));
                data_pos += 3;
            }
            4 => {
                let v = read_i64_be(payload, data_pos, 4);
                values.push(Value::Integer(v));
                data_pos += 4;
            }
            5 => {
                let v = read_i64_be(payload, data_pos, 6);
                values.push(Value::Integer(v));
                data_pos += 6;
            }
            6 => {
                let v = read_i64_be(payload, data_pos, 8);
                values.push(Value::Integer(v));
                data_pos += 8;
            }
            7 => {
                let bits = read_u32_be(payload, data_pos) as u64;
                let bits = (bits << 32) | (read_u32_be(payload, data_pos + 4) as u64);
                let d = f64::from_bits(bits);
                values.push(Value::Real(d));
                data_pos += 8;
            }
            8 => values.push(Value::Integer(0)),
            9 => values.push(Value::Integer(1)),
            n if n >= 12 && n % 2 == 0 => {
                let len = ((n - 12) / 2) as usize;
                values.push(Value::Blob(payload[data_pos..data_pos + len].to_vec()));
                data_pos += len;
            }
            n if n >= 13 => {
                let len = ((n - 13) / 2) as usize;
                values.push(Value::Text(payload[data_pos..data_pos + len].to_vec()));
                data_pos += len;
            }
            _ => values.push(Value::Null), // reserved types
        }
    }

    values
}

fn walk_btree(data: &[u8], page_num: u32, page_size: usize, reserved: usize, rows: &mut Vec<(i64, Vec<u8>)>) {
    let page_start = (page_num as usize - 1) * page_size;
    let hdr_offset = if page_num == 1 { 100 } else { 0 };
    let page_type = data[page_start + hdr_offset];
    let usable = page_size - reserved;

    let ncells = read_u16_be(data, page_start + hdr_offset + 3) as usize;

    if page_type == 0x0D {
        // Leaf table page
        for i in 0..ncells {
            let cell_offset = read_u16_be(data, page_start + hdr_offset + 8 + i * 2) as usize;
            let cell_pos = page_start + cell_offset;

            let (payload_size, vsize1) = read_varint(data, cell_pos);
            let (rowid_raw, vsize2) = read_varint(data, cell_pos + vsize1);
            let rowid = rowid_raw as i64;

            let max_local = usable - vsize1 - vsize2;
            let (local_size, overflow_page) = if (payload_size as usize) <= max_local {
                (payload_size as usize, 0u32)
            } else {
                let ls = max_local - 4;
                let op = read_u32_be(data, cell_pos + vsize1 + vsize2 + ls);
                (ls, op)
            };

            let mut payload = Vec::new();
            let local_start = cell_pos + vsize1 + vsize2;
            payload.extend_from_slice(&data[local_start..local_start + local_size]);

            let mut remaining = payload_size as usize - local_size;
            let mut opage = overflow_page;
            while opage != 0 && remaining > 0 {
                let opage_start = (opage as usize - 1) * page_size;
                let next_page = read_u32_be(data, opage_start);
                let chunk = remaining.min(usable - 4);
                payload.extend_from_slice(&data[opage_start + 4..opage_start + 4 + chunk]);
                remaining -= chunk;
                opage = next_page;
            }

            rows.push((rowid, payload));
        }
    } else if page_type == 0x05 {
        // Interior table page
        let leftmost = read_u32_be(data, page_start + hdr_offset + 8);
        walk_btree(data, leftmost, page_size, reserved, rows);
        for i in 0..ncells {
            let cell_offset = read_u16_be(data, page_start + hdr_offset + 8 + i * 2) as usize;
            let cell_pos = page_start + cell_offset;
            let child_page = read_u32_be(data, cell_pos);
            walk_btree(data, child_page, page_size, reserved, rows);
        }
    }
    // Ignore other page types (index pages, freelist, etc.)
}

fn parse_columns(sql: &str) -> (Vec<String>, Vec<bool>) {
    let mut columns = Vec::new();
    let mut is_rowid = Vec::new();

    let bytes = sql.as_bytes();
    let sql_lower = sql.to_ascii_lowercase();

    // Find "create table"
    let create_pos = sql_lower.find("create").unwrap_or(0);
    let table_pos = sql_lower.find("table", create_pos).unwrap_or(0);
    let mut pos = table_pos + 5;

    // Skip whitespace
    while pos < bytes.len() && bytes[pos].is_ascii_whitespace() { pos += 1; }

    // Skip table name (might be quoted)
    if pos < bytes.len() && bytes[pos] == b'"' {
        pos += 1;
        while pos < bytes.len() && bytes[pos] != b'"' { pos += 1; }
        pos += 1;
    } else {
        while pos < bytes.len() && (bytes[pos].is_alphanumeric() || bytes[pos] == b'_') { pos += 1; }
    }

    // Skip whitespace
    while pos < bytes.len() && bytes[pos].is_ascii_whitespace() { pos += 1; }

    // Expect '('
    if pos >= bytes.len() || bytes[pos] != b'(' {
        return (columns, is_rowid);
    }
    pos += 1;

    // Parse definitions
    let mut depth = 0usize;
    let mut def_start = pos;

    while pos < bytes.len() {
        let b = bytes[pos];
        if b == b'(' {
            depth += 1;
            pos += 1;
        } else if b == b')' {
            if depth == 0 {
                // End of definitions
                let def = sql[def_start..pos].trim();
                if !def.is_empty() {
                    columns.push(parse_col_name(def));
                    is_rowid.push(check_integer_pk(def));
                }
                break;
            }
            depth -= 1;
            pos += 1;
        } else if b == b',' && depth == 0 {
            let def = sql[def_start..pos].trim();
            if !def.is_empty() {
                columns.push(parse_col_name(def));
                is_rowid.push(check_integer_pk(def));
            }
            pos += 1;
            def_start = pos;
        } else {
            pos += 1;
        }
    }

    (columns, is_rowid)
}

fn parse_col_name(def: &str) -> String {
    let bytes = def.as_bytes();
    let mut pos = 0;
    while pos < bytes.len() && bytes[pos].is_ascii_whitespace() { pos += 1; }

    if pos < bytes.len() && bytes[pos] == b'"' {
        pos += 1;
        let start = pos;
        while pos < bytes.len() && bytes[pos] != b'"' { pos += 1; }
        def[start..pos].to_string()
    } else {
        let start = pos;
        while pos < bytes.len() && (bytes[pos].is_alphanumeric() || bytes[pos] == b'_') { pos += 1; }
        def[start..pos].to_string()
    }
}

fn is_constraint_kw(word: &str) -> bool {
    let w = word.to_ascii_uppercase();
    matches!(w.as_str(),
        "PRIMARY" | "NOT" | "NULL" | "UNIQUE" | "CHECK" | "DEFAULT" |
        "COLLATE" | "REFERENCES" | "GENERATED" | "AS" | "VIRTUAL" | "STORED" |
        "CONSTRAINT"
    )
}

fn check_integer_pk(def: &str) -> bool {
    let bytes = def.as_bytes();
    let mut pos = 0;

    // Skip leading whitespace
    while pos < bytes.len() && bytes[pos].is_ascii_whitespace() { pos += 1; }

    // Skip column name
    if pos < bytes.len() && bytes[pos] == b'"' {
        pos += 1;
        while pos < bytes.len() && bytes[pos] != b'"' { pos += 1; }
        pos += 1;
    } else {
        while pos < bytes.len() && (bytes[pos].is_alphanumeric() || bytes[pos] == b'_') { pos += 1; }
    }

    // Skip whitespace
    while pos < bytes.len() && bytes[pos].is_ascii_whitespace() { pos += 1; }

    // Read type words (non-keyword alphabetic words)
    let mut type_words: Vec<String> = Vec::new();
    let mut has_paren = false;

    while pos < bytes.len() && bytes[pos].is_alphabetic() {
        let word_start = pos;
        while pos < bytes.len() && bytes[pos].is_alphabetic() { pos += 1; }
        let word = &def[word_start..pos];
        if is_constraint_kw(word) { break; }
        type_words.push(word.to_string());

        // Skip whitespace
        let ws_start = pos;
        while pos < bytes.len() && bytes[pos].is_ascii_whitespace() { pos += 1; }

        // Check for '('
        if pos < bytes.len() && bytes[pos] == b'(' {
            has_paren = true;
            pos += 1;
            let mut d = 1;
            while pos < bytes.len() && d > 0 {
                if bytes[pos] == b'(' { d += 1; }
                else if bytes[pos] == b')' { d -= 1; }
                pos += 1;
            }
            break;
        }

        // If no more alphabetic chars follow, stop
        if pos >= bytes.len() || !bytes[pos].is_alphabetic() {
            // Restore pos to after whitespace if we consumed it but next isn't alpha
            // Actually, we already advanced past whitespace. If next isn't alpha, we're done.
            break;
        }
    }

    // Check if type is exactly "INTEGER" (one word, no paren)
    if type_words.len() != 1 { return false; }
    if type_words[0].to_ascii_uppercase() != "INTEGER" { return false; }
    if has_paren { return false; }

    // Check for PRIMARY KEY (as consecutive words, case-insensitive)
    // Search in the part after the column name
    let rest = &def[pos.min(def.len())..]; // Hmm, this isn't right
    // Actually, let me search the whole definition for PRIMARY KEY
    has_primary_key(def)
}

fn has_primary_key(s: &str) -> bool {
    let words: Vec<&str> = s.split_whitespace().collect();
    for i in 0..words.len().saturating_sub(1) {
        if words[i].eq_ignore_ascii_case("primary") && words[i + 1].eq_ignore_ascii_case("key") {
            return true;
        }
    }
    false
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];
    let path = format!("{}/db.sqlite", dir);
    let data = fs::read(&path).unwrap();

    // Parse header
    let mut page_size = read_u16_be(&data, 16) as usize;
    if page_size == 1 { page_size = 65536; }
    let reserved = data[20] as usize;

    // Walk schema table (root at page 1)
    let mut raw_rows = Vec::new();
    walk_btree(&data, 1, page_size, reserved, &mut raw_rows);

    let mut tables: Vec<(String, u32, String)> = Vec::new(); // (name, rootpage, sql)

    for (_rowid, payload) in &raw_rows {
        let fields = decode_record(payload);
        // Schema columns: type(0), name(1), tbl_name(2), rootpage(3), sql(4)
        if fields.len() < 5 { continue; }

        let col_type = match &fields[0] {
            Value::Text(b) => String::from_utf8_lossy(b).to_string(),
            _ => continue,
        };
        let name = match &fields[1] {
            Value::Text(b) => String::from_utf8_lossy(b).to_string(),
            _ => continue,
        };
        let rootpage = match &fields[3] {
            Value::Integer(n) => *n as u32,
            _ => continue,
        };
        let sql = match &fields[4] {
            Value::Text(b) => String::from_utf8_lossy(b).to_string(),
            _ => String::new(),
        };

        if col_type == "table" && !name.starts_with("sqlite_") {
            tables.push((name, rootpage, sql));
        }
    }

    // Sort by name (byte-wise ascending)
    tables.sort_by(|a, b| a.0.as_bytes().cmp(b.0.as_bytes()));

    let mut first = true;
    for (name, rootpage, sql) in &tables {
        if !first { println!(); }
        first = false;

        let (columns, is_rowid) = parse_columns(sql);
        let num_cols = columns.len();

        let mut raw = Vec::new();
        walk_btree(&data, *rootpage, page_size, reserved, &mut raw);

        let mut rows: Vec<(i64, Vec<Value>)> = Vec::new();
        for (rowid, payload) in &raw {
            let mut vals = decode_record(payload);
            // Pad with NULL
            while vals.len() < num_cols {
                vals.push(Value::Null);
            }
            // Replace NULL with rowid for INTEGER PRIMARY KEY columns
            for i in 0..num_cols {
                if is_rowid[i] {
                    vals[i] = Value::Integer(*rowid);
                }
            }
            rows.push((*rowid, vals));
        }

        println!("TABLE {} rows={}", name, rows.len());
        println!("COLUMNS {}", columns.join(", "));
        for (rowid, vals) in &rows {
            let formatted: Vec<String> = vals.iter().map(|v| format_value(v)).collect();
            println!("{}: {}", rowid, formatted.join(", "));
        }
    }
}

import * as net from 'net';
import * as crypto from 'crypto';

interface Frame {
    fin: boolean;
    opcode: number;
    payload: Buffer;
}

class Connection {
    socket: net.Socket;
    buffer: Buffer = Buffer.alloc(0);
    ended: boolean = false;
    private pendingResolve: (() => void) | null = null;

    constructor(socket: net.Socket) {
        this.socket = socket;
        socket.on('data', (data: Buffer) => {
            this.buffer = Buffer.concat([this.buffer, data]);
            if (this.pendingResolve) {
                const r = this.pendingResolve;
                this.pendingResolve = null;
                r();
            }
        });
        socket.on('end', () => {
            this.ended = true;
            if (this.pendingResolve) {
                const r = this.pendingResolve;
                this.pendingResolve = null;
                r();
            }
        });
        socket.on('error', () => {
            this.ended = true;
            if (this.pendingResolve) {
                const r = this.pendingResolve;
                this.pendingResolve = null;
                r();
            }
        });
    }

    async waitForData(): Promise<void> {
        if (this.ended) return;
        await new Promise<void>((resolve) => {
            this.pendingResolve = resolve;
        });
    }

    async ensureBytes(n: number): Promise<boolean> {
        while (this.buffer.length < n) {
            if (this.ended) return false;
            await this.waitForData();
        }
        return true;
    }

    consume(n: number): void {
        this.buffer = this.buffer.subarray(n);
    }

    write(data: Buffer): void {
        this.socket.write(data);
    }

    close(): void {
        this.socket.destroy();
    }
}

function randomMaskKey(): Buffer {
    let key: Buffer;
    do {
        key = crypto.randomBytes(4);
    } while (key[0] === 0 && key[1] === 0 && key[2] === 0 && key[3] === 0);
    return key;
}

function buildFrame(opcode: number, payload: Buffer): Buffer {
    const maskKey = randomMaskKey();
    let headerSize: number;

    if (payload.length <= 125) {
        headerSize = 2;
    } else if (payload.length <= 65535) {
        headerSize = 4;
    } else {
        headerSize = 10;
    }

    const frame = Buffer.alloc(headerSize + 4 + payload.length);
    frame[0] = 0x80 | opcode;

    if (payload.length <= 125) {
        frame[1] = 0x80 | payload.length;
    } else if (payload.length <= 65535) {
        frame[1] = 0x80 | 126;
        frame.writeUInt16BE(payload.length, 2);
    } else {
        frame[1] = 0x80 | 127;
        frame.writeBigUInt64BE(BigInt(payload.length), 2);
    }

    maskKey.copy(frame, headerSize);
    for (let i = 0; i < payload.length; i++) {
        frame[headerSize + 4 + i] = payload[i] ^ maskKey[i % 4];
    }

    return frame;
}

async function readFrame(conn: Connection): Promise<Frame | null> {
    if (!await conn.ensureBytes(2)) return null;

    const b0 = conn.buffer[0];
    const b1 = conn.buffer[1];

    const fin = (b0 & 0x80) !== 0;
    const opcode = b0 & 0x0F;
    let payloadLength = b1 & 0x7F;
    let headerSize = 2;

    if (payloadLength === 126) {
        if (!await conn.ensureBytes(4)) return null;
        payloadLength = conn.buffer.readUInt16BE(2);
        headerSize = 4;
    } else if (payloadLength === 127) {
        if (!await conn.ensureBytes(10)) return null;
        payloadLength = Number(conn.buffer.readBigUInt64BE(2));
        headerSize = 10;
    }

    if (!await conn.ensureBytes(headerSize + payloadLength)) return null;
    const payload = Buffer.from(conn.buffer.subarray(headerSize, headerSize + payloadLength));
    conn.consume(headerSize + payloadLength);

    return { fin, opcode, payload };
}

async function readHttpHeaders(conn: Connection): Promise<string | null> {
    while (true) {
        const idx = conn.buffer.indexOf('\r\n\r\n');
        if (idx !== -1) {
            const header = conn.buffer.subarray(0, idx + 4).toString('ascii');
            conn.consume(idx + 4);
            return header;
        }
        if (conn.ended) return null;
        await conn.waitForData();
    }
}

function handleTextCommand(text: string): { reply?: string; action?: 'sha1' | 'bye' } {
    if (text === 'BYE') {
        return { action: 'bye' };
    }
    if (text === 'SHA1') {
        return { action: 'sha1' };
    }
    if (text.startsWith('ADD ')) {
        const parts = text.substring(4).split(' ');
        const a = BigInt(parts[0]);
        const b = BigInt(parts[1]);
        const sum = (a + b).toString();
        return { reply: sum };
    }
    if (text.startsWith('REV ')) {
        const textToReverse = text.substring(4);
        const reversed = [...textToReverse].reverse().join('');
        return { reply: reversed };
    }
    return {};
}

async function processSession(urlStr: string, sessionNum: number): Promise<void> {
    console.log(`session ${sessionNum}`);

    const url = new URL(urlStr);
    const port = parseInt(url.port) || 80;
    const host = url.hostname;
    const requestTarget = url.pathname + url.search;

    const socket: net.Socket = await new Promise((resolve, reject) => {
        const s = net.createConnection({ host, port }, () => resolve(s));
        s.on('error', reject);
    });

    const conn = new Connection(socket);

    const wsKey = crypto.randomBytes(16).toString('base64');

    const handshake = `GET ${requestTarget} HTTP/1.1\r\n` +
        `Host: ${host}:${port}\r\n` +
        `Upgrade: websocket\r\n` +
        `Connection: Upgrade\r\n` +
        `Sec-WebSocket-Version: 13\r\n` +
        `Sec-WebSocket-Key: ${wsKey}\r\n` +
        `\r\n`;
    conn.write(Buffer.from(handshake, 'ascii'));

    const headerBlock = await readHttpHeaders(conn);
    if (headerBlock === null) {
        conn.close();
        return;
    }

    const lines = headerBlock.split('\r\n');
    const statusLine = lines[0];
    const statusMatch = statusLine.match(/^HTTP\/\d\.\d (\d{3}) (.*)$/);
    if (!statusMatch) {
        conn.close();
        return;
    }

    const statusCode = parseInt(statusMatch[1]);
    const reasonPhrase = statusMatch[2];

    if (statusCode !== 101) {
        console.log(`handshake failed: ${statusCode} ${reasonPhrase}`);
        conn.close();
        return;
    }

    let acceptValue: string | undefined;
    for (let i = 1; i < lines.length; i++) {
        const colonIdx = lines[i].indexOf(':');
        if (colonIdx === -1) continue;
        const name = lines[i].substring(0, colonIdx).trim().toLowerCase();
        const value = lines[i].substring(colonIdx + 1).trim();
        if (name === 'sec-websocket-accept') {
            acceptValue = value;
        }
    }

    const expectedAccept = crypto.createHash('sha1')
        .update(wsKey + '258EAFA5-E914-47DA-95CA-C5AB0DC85B11')
        .digest('base64');

    if (acceptValue !== expectedAccept) {
        console.log('handshake failed: bad Sec-WebSocket-Accept');
        conn.close();
        return;
    }

    // WebSocket frame processing loop
    let hasSentClose = false;
    let waitingForSHA1 = false;
    let currentOpcode = -1;
    let fragments: Buffer[] = [];

    while (true) {
        const frame = await readFrame(conn);
        if (frame === null) break;

        if (frame.opcode === 9) {
            conn.write(buildFrame(10, frame.payload));
            continue;
        }

        if (frame.opcode === 10) {
            continue;
        }

        if (frame.opcode === 8) {
            let code: number;
            let reason: string;
            if (frame.payload.length >= 2) {
                code = frame.payload.readUInt16BE(0);
                reason = frame.payload.subarray(2).toString('utf8');
            } else {
                code = 1005;
                reason = '';
            }
            if (reason === '') {
                console.log(`closed ${code}`);
            } else {
                console.log(`closed ${code} ${reason}`);
            }
            if (!hasSentClose) {
                const closePayload = Buffer.alloc(2);
                closePayload.writeUInt16BE(code, 0);
                conn.write(buildFrame(8, closePayload));
                hasSentClose = true;
            }
            break;
        }

        if (frame.opcode === 1 || frame.opcode === 2) {
            if (frame.fin) {
                const data = frame.payload;
                if (waitingForSHA1 && frame.opcode === 2) {
                    const hash = crypto.createHash('sha1').update(data).digest('hex');
                    conn.write(buildFrame(1, Buffer.from(hash, 'utf8')));
                    console.log(`SHA1 ${data.length} -> ${hash}`);
                    waitingForSHA1 = false;
                } else if (frame.opcode === 1) {
                    const text = data.toString('utf8');
                    const result = handleTextCommand(text);
                    if (result.action === 'bye') {
                        conn.write(buildFrame(8, Buffer.from([0x03, 0xE8])));
                        hasSentClose = true;
                    } else if (result.action === 'sha1') {
                        waitingForSHA1 = true;
                    } else if (result.reply !== undefined) {
                        conn.write(buildFrame(1, Buffer.from(result.reply, 'utf8')));
                        console.log(`${text} -> ${result.reply}`);
                    }
                }
            } else {
                currentOpcode = frame.opcode;
                fragments = [frame.payload];
            }
            continue;
        }

        if (frame.opcode === 0) {
            fragments.push(frame.payload);
            if (frame.fin) {
                const data = Buffer.concat(fragments);
                if (waitingForSHA1 && currentOpcode === 2) {
                    const hash = crypto.createHash('sha1').update(data).digest('hex');
                    conn.write(buildFrame(1, Buffer.from(hash, 'utf8')));
                    console.log(`SHA1 ${data.length} -> ${hash}`);
                    waitingForSHA1 = false;
                } else if (currentOpcode === 1) {
                    const text = data.toString('utf8');
                    const result = handleTextCommand(text);
                    if (result.action === 'bye') {
                        conn.write(buildFrame(8, Buffer.from([0x03, 0xE8])));
                        hasSentClose = true;
                    } else if (result.action === 'sha1') {
                        waitingForSHA1 = true;
                    } else if (result.reply !== undefined) {
                        conn.write(buildFrame(1, Buffer.from(result.reply, 'utf8')));
                        console.log(`${text} -> ${result.reply}`);
                    }
                }
            }
            continue;
        }
    }

    conn.close();
}

