use std::env;
use std::fs;

fn read_i32_be(data: &[u8], pos: usize) -> i32 {
    i32::from_be_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3]])
}

fn read_i64_be(data: &[u8], pos: usize) -> i64 {
    i64::from_be_bytes([data[pos], data[pos+1], data[pos+2], data[pos+3],
                       data[pos+4], data[pos+5], data[pos+6], data[pos+7]])
}

fn days_from_civil(y: i64, m: u32, d: u32) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = if m > 2 { (m - 3) as i64 } else { (m + 9) as i64 };
    let doy = (153 * mp + 2) / 5 + d as i64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { (mp + 3) as u32 } else { (mp - 9) as u32 };
    (if m <= 2 { y + 1 } else { y }, m, d)
}

fn epoch_to_civil(epoch: i64) -> (i64, u32, u32, u32, u32, u32) {
    let days = if epoch >= 0 { epoch / 86400 } else { (epoch - 86399) / 86400 };
    let secs_of_day = epoch - days * 86400;
    let (y, m, d) = civil_from_days(days);
    let h = (secs_of_day / 3600) as u32;
    let mi = ((secs_of_day % 3600) / 60) as u32;
    let s = (secs_of_day % 60) as u32;
    (y, m, d, h, mi, s)
}

fn civil_to_epoch(y: i64, m: u32, d: u32, h: u32, mi: u32, s: u32) -> i64 {
    days_from_civil(y, m, d) * 86400 + h as i64 * 3600 + mi as i64 * 60 + s as i64
}

fn day_of_week(epoch_days: i64) -> u32 {
    // 1970-01-01 (epoch day 0) was Thursday
    // 0=Sun, 1=Mon, ..., 6=Sat
    let dow = ((epoch_days % 7) + 4 + 7) % 7;
    dow as u32
}

fn days_in_month(y: i64, m: u32) -> u32 {
    match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if (y % 4 == 0 && y % 100 != 0) || y % 400 == 0 { 29 } else { 28 }
        }
        _ => unreachable!(),
    }
}

fn nth_weekday(y: i64, m: u32, n: u32, dow: u32) -> u32 {
    let first_epoch = days_from_civil(y, m, 1);
    let first_dow = day_of_week(first_epoch);
    let offset = ((dow as i64 - first_dow as i64) + 7) % 7;
    let mut day = 1 + offset as u32;
    if n == 5 {
        let dim = days_in_month(y, m);
        day = dim - ((dim as i64 - day as i64) % 7) as u32;
    } else {
        day += (n - 1) * 7;
    }
    day
}

#[derive(Clone, Debug)]
struct TzType {
    gmtoff: i32,
    isdst: bool,
    abbr: String,
}

#[derive(Clone, Debug)]
struct MWD {
    month: u32,
    week: u32,
    dow: u32,
    time: i32, // seconds within day
}

#[derive(Clone, Debug)]
struct TzifData {
    transitions: Vec<i64>,
    type_indices: Vec<usize>,
    types: Vec<TzType>,
    footer_std_idx: usize,
    footer_dst_idx: Option<usize>,
    dst_start: Option<MWD>,
    dst_end: Option<MWD>,
    std_gmtoff: i32,
    dst_gmtoff: Option<i32>,
}

fn extract_abbr(chars: &[u8], idx: usize) -> String {
    let mut end = idx;
    while end < chars.len() && chars[end] != 0 {
        end += 1;
    }
    String::from_utf8_lossy(&chars[idx..end]).to_string()
}

fn parse_posix_offset(s: &str) -> (i32, usize) {
    // Returns (offset_in_seconds, chars_consumed)
    // Offset is what you ADD to local to get UTC
    let mut pos = 0;
    let mut sign = 1i32;
    if pos < s.len() {
        if s.as_bytes()[pos] == b'-' { sign = -1; pos += 1; }
        else if s.as_bytes()[pos] == b'+' { pos += 1; }
    }
    let mut hours = 0i32;
    let mut minutes = 0i32;
    let mut seconds = 0i32;

    // Parse hours (1 or 2 digits)
    let h_start = pos;
    while pos < s.len() && s.as_bytes()[pos].is_ascii_digit() {
        pos += 1;
    }
    hours = s[h_start..pos].parse::<i32>().unwrap();

    if pos < s.len() && s.as_bytes()[pos] == b':' {
        pos += 1;
        let m_start = pos;
        while pos < s.len() && s.as_bytes()[pos].is_ascii_digit() {
            pos += 1;
        }
        minutes = s[m_start..pos].parse::<i32>().unwrap();

        if pos < s.len() && s.as_bytes()[pos] == b':' {
            pos += 1;
            let s_start = pos;
            while pos < s.len() && s.as_bytes()[pos].is_ascii_digit() {
                pos += 1;
            }
            seconds = s[s_start..pos].parse::<i32>().unwrap();
        }
    }

    (sign * (hours * 3600 + minutes * 60 + seconds), pos)
}

fn parse_posix_name(s: &str) -> (String, usize) {
    if s.starts_with('<') {
        let end = s.find('>').unwrap();
        (s[1..end].to_string(), end + 1)
    } else {
        let mut pos = 0;
        while pos < s.len() && s.as_bytes()[pos].is_ascii_alphabetic() {
            pos += 1;
        }
        (s[..pos].to_string(), pos)
    }
}

fn parse_mwd(s: &str) -> (MWD, usize) {
    // Mm.w.d[/time]
    let mut pos = 0;
    assert_eq!(s.as_bytes()[pos], b'M'); pos += 1;

    let m_start = pos;
    while pos < s.len() && s.as_bytes()[pos].is_ascii_digit() { pos += 1; }
    let month = s[m_start..pos].parse::<u32>().unwrap();

    assert_eq!(s.as_bytes()[pos], b'.'); pos += 1;
    let w_start = pos;
    while pos < s.len() && s.as_bytes()[pos].is_ascii_digit() { pos += 1; }
    let week = s[w_start..pos].parse::<u32>().unwrap();

    assert_eq!(s.as_bytes()[pos], b'.'); pos += 1;
    let d_start = pos;
    while pos < s.len() && s.as_bytes()[pos].is_ascii_digit() { pos += 1; }
    let dow = s[d_start..pos].parse::<u32>().unwrap();

    let mut time = 2 * 3600; // default 02:00:00
    if pos < s.len() && s.as_bytes()[pos] == b'/' {
        pos += 1;
        let (t, consumed) = parse_posix_offset(&s[pos..]);
        time = t;
        pos += consumed;
    }

    (MWD { month, week, dow, time }, pos)
}

fn parse_posix_tz(s: &str) -> (String, i32, Option<String>, Option<i32>, Option<MWD>, Option<MWD>) {
    // std offset [dst [offset] [,start[/time],end[/time]]]
    let mut pos = 0;

    // Parse std name
    let (std_name, consumed) = parse_posix_name(&s[pos..]);
    pos += consumed;

    // Parse std offset (required)
    let (std_offset_posix, consumed) = parse_posix_offset(&s[pos..]);
    pos += consumed;
    let std_gmtoff = -std_offset_posix; // gmtoff = -posix_offset

    let mut dst_name = None;
    let mut dst_gmtoff = None;
    let mut dst_start = None;
    let mut dst_end = None;

    if pos < s.len() && s.as_bytes()[pos] != b',' {
        // Parse dst name
        let (dn, consumed) = parse_posix_name(&s[pos..]);
        pos += consumed;
        dst_name = Some(dn);

        // Try to parse dst offset
        if pos < s.len() && (s.as_bytes()[pos] == b'-' || s.as_bytes()[pos] == b'+' || s.as_bytes()[pos].is_ascii_digit()) {
            // Check if it's actually an offset (starts with digit, +, or -)
            // But we need to be careful: after the name, if next char is digit/+/-, it's an offset
            let (dst_offset_posix, consumed) = parse_posix_offset(&s[pos..]);
            pos += consumed;
            dst_gmtoff = Some(-dst_offset_posix);
        } else {
            // Default: dst = std + 1 hour
            dst_gmtoff = Some(std_gmtoff + 3600);
        }

        // Parse start,end
        if pos < s.len() && s.as_bytes()[pos] == b',' {
            pos += 1;
            let (start, consumed) = parse_mwd(&s[pos..]);
            pos += consumed;
            dst_start = Some(start);

            assert_eq!(s.as_bytes()[pos], b','); pos += 1;

            let (end, consumed) = parse_mwd(&s[pos..]);
            pos += consumed;
            dst_end = Some(end);
        }
    }

    (std_name, std_gmtoff, dst_name, dst_gmtoff, dst_start, dst_end)
}

fn parse_tzif(path: &str) -> TzifData {
    let data = fs::read(path).unwrap();
    let mut pos: usize = 0;

    // First header
    assert_eq!(&data[0..4], b"TZif");
    pos = 20;
    let isutcnt1 = read_i32_be(&data, pos) as usize; pos += 4;
    let isstdcnt1 = read_i32_be(&data, pos) as usize; pos += 4;
    let leapcnt1 = read_i32_be(&data, pos) as usize; pos += 4;
    let timecnt1 = read_i32_be(&data, pos) as usize; pos += 4;
    let typecnt1 = read_i32_be(&data, pos) as usize; pos += 4;
    let charcnt1 = read_i32_be(&data, pos) as usize; pos += 4;

    // Skip first data block
    pos += timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1;

    // Second header
    assert_eq!(&data[pos..pos+4], b"TZif");
    pos += 20;
    let isutcnt = read_i32_be(&data, pos) as usize; pos += 4;
    let isstdcnt = read_i32_be(&data, pos) as usize; pos += 4;
    let leapcnt = read_i32_be(&data, pos) as usize; pos += 4;
    let timecnt = read_i32_be(&data, pos) as usize; pos += 4;
    let typecnt = read_i32_be(&data, pos) as usize; pos += 4;
    let charcnt = read_i32_be(&data, pos) as usize; pos += 4;

    // Transition times (64-bit)
    let mut transitions = Vec::with_capacity(timecnt);
    for _ in 0..timecnt {
        transitions.push(read_i64_be(&data, pos));
        pos += 8;
    }

    // Type indices
    let mut type_indices = Vec::with_capacity(timecnt);
    for _ in 0..timecnt {
        type_indices.push(data[pos] as usize);
        pos += 1;
    }

    // Type records
    let mut raw_types = Vec::with_capacity(typecnt);
    for _ in 0..typecnt {
        let gmtoff = read_i32_be(&data, pos); pos += 4;
        let isdst = data[pos] != 0; pos += 1;
        let abbr_idx = data[pos] as usize; pos += 1;
        raw_types.push((gmtoff, isdst, abbr_idx));
    }

    // Abbreviation characters
    let abbr_chars = &data[pos..pos+charcnt];
    pos += charcnt;

    // Skip leap seconds, isstd, isut
    pos += leapcnt * 12 + isstdcnt + isutcnt;

    // Footer
    assert_eq!(data[pos], b'\n'); pos += 1;
    let footer_start = pos;
    while pos < data.len() && data[pos] != b'\n' { pos += 1; }
    let tz_string = std::str::from_utf8(&data[footer_start..pos]).unwrap().to_string();

    // Build types
    let mut types: Vec<TzType> = raw_types.iter().map(|(gmtoff, isdst, abbr_idx)| {
        TzType { gmtoff: *gmtoff, isdst: *isdst, abbr: extract_abbr(abbr_chars, *abbr_idx) }
    }).collect();

    // Parse footer
    let (std_name, std_gmtoff, dst_name_opt, dst_gmtoff_opt, dst_start, dst_end) = parse_posix_tz(&tz_string);

    // Add footer types
    let footer_std_idx = types.len();
    types.push(TzType {
        gmtoff: std_gmtoff,
        isdst: false,
        abbr: std_name,
    });

    let footer_dst_idx = if let Some(ref dn) = dst_name_opt {
        let idx = types.len();
        types.push(TzType {
            gmtoff: dst_gmtoff_opt.unwrap(),
            isdst: true,
            abbr: dn.clone(),
        });
        Some(idx)
    } else {
        None
    };

    TzifData {
        transitions,
        type_indices,
        types,
        footer_std_idx,
        footer_dst_idx,
        dst_start,
        dst_end,
        std_gmtoff,
        dst_gmtoff: dst_gmtoff_opt,
    }
}

impl TzifData {
    fn type_at(&self, t: i64) -> &TzType {
        if self.transitions.is_empty() {
            return &self.types[0];
        }
        if t < self.transitions[0] {
            return &self.types[0];
        }
        let last = *self.transitions.last().unwrap();
        if t >= last {
            return self.footer_type_at(t);
        }
        // Binary search
        let mut lo = 0;
        let mut hi = self.transitions.len() - 1;
        while lo < hi {
            let mid = (lo + hi + 1) / 2;
            if self.transitions[mid] <= t {
                lo = mid;
            } else {
                hi = mid - 1;
            }
        }
        &self.types[self.type_indices[lo]]
    }

    fn footer_type_at(&self, t: i64) -> &TzType {
        match (self.dst_start.as_ref(), self.dst_end.as_ref(), self.dst_gmtoff) {
            (Some(start), Some(end), Some(_dst_gmtoff)) => {
                let (year, _, _, _, _, _) = epoch_to_civil(t);
                let start_unix = self.compute_mwd_unix(year, start, self.std_gmtoff);
                let end_unix = self.compute_mwd_unix(year, end, self.dst_gmtoff.unwrap());

                if start_unix < end_unix {
                    if t >= start_unix && t < end_unix {
                        &self.types[self.footer_dst_idx.unwrap()]
                    } else {
                        &self.types[self.footer_std_idx]
                    }
                } else {
                    if t >= start_unix || t < end_unix {
                        &self.types[self.footer_dst_idx.unwrap()]
                    } else {
                        &self.types[self.footer_std_idx]
                    }
                }
            }
            _ => &self.types[self.footer_std_idx],
        }
    }

    fn compute_mwd_unix(&self, year: i64, rule: &MWD, gmtoff: i32) -> i64 {
        let day = nth_weekday(year, rule.month, rule.week, rule.dow);
        let local_epoch = civil_to_epoch(year, rule.month, day, 0, 0, 0) + rule.time as i64;
        local_epoch - gmtoff as i64
    }
}

fn format_offset(gmtoff: i32) -> String {
    let sign = if gmtoff >= 0 { '+' } else { '-' };
    let abs = gmtoff.abs();
    let h = abs / 3600;
    let m = (abs % 3600) / 60;
    let s = abs % 60;
    if s != 0 {
        format!("{}{:02}:{:02}:{:02}", sign, h, m, s)
    } else {
        format!("{}{:02}:{:02}", sign, h, m)
    }
}

fn format_local(t: i64, gmtoff: i32) -> String {
    let local = t + gmtoff as i64;
    let (y, mo, d, h, mi, s) = epoch_to_civil(local);
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}", y, mo, d, h, mi, s)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let queries_path = format!("{}/queries.txt", dir);
    let content = fs::read_to_string(&queries_path).unwrap();

    // Cache parsed TZif files
    let mut tz_cache: std::collections::HashMap<String, TzifData> = std::collections::HashMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() { continue; }

        let fields: Vec<&str> = line.split(' ').collect();
        let query_type = fields[0];
        let file_name = fields[1];

        let tz = tz_cache.entry(file_name.to_string())
            .or_insert_with(|| parse_tzif(&format!("{}/{}", dir, file_name)));

        if query_type == "UTC" {
            let t: i64 = fields[2].parse().unwrap();
            let typ = tz.type_at(t);
            let local_str = format_local(t, typ.gmtoff);
            let offset_str = format_offset(typ.gmtoff);
            println!("{} -> {}{} {}", line, local_str, offset_str, typ.abbr);
        } else { // LOCAL
            let wall_str = fields[2];
            // Parse wall-clock time to seconds (treating as UTC for arithmetic)
            let (wy, wmo, wd, wh, wmi, ws) = parse_datetime(wall_str);
            let wall_seconds = civil_to_epoch(wy, wmo, wd, wh, wmi, ws);

            // Collect all possible offsets
            let mut offsets: Vec<i32> = Vec::new();
            for typ in &tz.types {
                if !offsets.contains(&typ.gmtoff) {
                    offsets.push(typ.gmtoff);
                }
            }
            // Also add footer offsets
            if !offsets.contains(&tz.std_gmtoff) {
                offsets.push(tz.std_gmtoff);
            }
            if let Some(dg) = tz.dst_gmtoff {
                if !offsets.contains(&dg) {
                    offsets.push(dg);
                }
            }

            // Find all valid candidates
            let mut candidates: Vec<(i64, i32, String)> = Vec::new(); // (t, gmtoff, abbr)
            for &off in &offsets {
                let t_candidate = wall_seconds - off as i64;
                let typ = tz.type_at(t_candidate);
                if typ.gmtoff == off {
                    candidates.push((t_candidate, off, typ.abbr.clone()));
                }
            }

            if candidates.len() == 1 {
                let (t, off, abbr) = &candidates[0];
                let offset_str = format_offset(*off);
                println!("{} -> {} {} {}", line, t, offset_str, abbr);
            } else if candidates.len() == 2 {
                // Sort by t
                candidates.sort_by_key(|&(t, _, _)| t);
                let (t1, off1, abbr1) = &candidates[0];
                let (t2, off2, abbr2) = &candidates[1];
                println!("{} -> {} {} {} | {} {} {}", line, t1, format_offset(*off1), abbr1, t2, format_offset(*off2), abbr2);
            } else {
                // Gap
                // Find the transition that caused the gap
                let (t_gap, off_before, off_after, abbr_after) = find_gap(tz, wall_seconds);
                let local_str = format_local(t_gap, off_after);
                let offset_str = format_offset(off_after);
                println!("{} -> GAP {} {}{} {}", line, t_gap, local_str, offset_str, abbr_after);
            }
        }
    }
}

fn parse_datetime(s: &str) -> (i64, u32, u32, u32, u32, u32) {
    // YYYY-MM-DDTHH:MM:SS
    let y: i64 = s[0..4].parse().unwrap();
    let mo: u32 = s[5..7].parse().unwrap();
    let d: u32 = s[8..10].parse().unwrap();
    let h: u32 = s[11..13].parse().unwrap();
    let mi: u32 = s[14..16].parse().unwrap();
    let sec: u32 = s[17..19].parse().unwrap();
    (y, mo, d, h, mi, sec)
}

fn find_gap(tz: &TzifData, wall_seconds: i64) -> (i64, i32, i32, String) {
    // Returns (t, off_before, off_after, abbr_after)
    // t = wall_seconds - off_before
    // Find the spring-forward transition that skips wall_seconds

    // Check explicit transitions
    for i in 0..tz.transitions.len() {
        let t = tz.transitions[i];
        let off_after = tz.types[tz.type_indices[i]].gmtoff;
        let off_before = if i == 0 {
            tz.types[0].gmtoff
        } else {
            tz.types[tz.type_indices[i - 1]].gmtoff
        };
        if off_after > off_before {
            let gap_start = t + off_before as i64;
            let gap_end = t + off_after as i64;
            if wall_seconds >= gap_start && wall_seconds < gap_end {
                let t_gap = wall_seconds - off_before as i64;
                let abbr = tz.types[tz.type_indices[i]].abbr.clone();
                return (t_gap, off_before, off_after, abbr);
            }
        }
    }

    // Check footer transitions
    if let (Some(start), Some(end), Some(dst_gmtoff)) = (tz.dst_start.as_ref(), tz.dst_end.as_ref(), tz.dst_gmtoff) {
        let (year_approx, _, _, _, _, _) = epoch_to_civil(wall_seconds);
        let last_t = tz.transitions.last().copied().unwrap_or(i64::MIN);

        for y in (year_approx - 1)..=(year_approx + 1) {
            let start_unix = tz.compute_mwd_unix(y, start, tz.std_gmtoff);
            // Start transition: std → dst (spring forward if dst > std)
            if start_unix > last_t && dst_gmtoff > tz.std_gmtoff {
                let gap_start = start_unix + tz.std_gmtoff as i64;
                let gap_end = start_unix + dst_gmtoff as i64;
                if wall_seconds >= gap_start && wall_seconds < gap_end {
                    let t_gap = wall_seconds - tz.std_gmtoff as i64;
                    let abbr = tz.types[tz.footer_dst_idx.unwrap()].abbr.clone();
                    return (t_gap, tz.std_gmtoff, dst_gmtoff, abbr);
                }
            }

            // End transition: dst → std (fall back, not a gap)
            // Unless dst < std (unusual), skip
        }
    }

    // Should not reach here for valid input
    panic!("Gap not found");
}

import * as fs from 'fs';
import * as path from 'path';

// --- Date/time utilities ---

function isLeap(y: number): boolean {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function daysInMonth(y: number, m: number): number {
  const dm = [31,28,31,30,31,30,31,31,30,31,30,31];
  if (m === 2 && isLeap(y)) return 29;
  return dm[m - 1];
}

function daysFromCivil(y: number, m: number, d: number): number {
  y = y - (m <= 2 ? 1 : 0);
  const era = Math.floor(y / 400);
  const yoe = y - era * 400;
  const mp = m + (m > 2 ? -3 : 9);
  const doy = Math.floor((153 * mp + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}

function civilFromDays(z: number): { y: number; m: number; d: number } {
  z += 719468;
  const era = Math.floor(z / 146097);
  const doe = z - era * 146097;
  const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
  const y = yoe + era * 400;
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
  const mp = Math.floor((5 * doy + 2) / 153);
  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
  const m = mp + (mp < 10 ? 3 : -9);
  return { y: y + (m <= 2 ? 1 : 0), m, d };
}

function unixToComponents(t: number): { y: number; m: number; d: number; h: number; mi: number; s: number } {
  let days = Math.floor(t / 86400);
  let rem = t - days * 86400;
  const { y, m, d } = civilFromDays(days);
  const h = Math.floor(rem / 3600);
  const mi = Math.floor((rem % 3600) / 60);
  const s = rem % 60;
  return { y, m, d, h, mi, s };
}

function componentsToUnix(y: number, m: number, d: number, h: number, mi: number, s: number): number {
  return daysFromCivil(y, m, d) * 86400 + h * 3600 + mi * 60 + s;
}

function pad2(n: number): string {
  return n.toString().padStart(2, '0');
}

function formatLocal(y: number, m: number, d: number, h: number, mi: number, s: number): string {
  return `${y}-${pad2(m)}-${pad2(d)}T${pad2(h)}:${pad2(mi)}:${pad2(s)}`;
}

function formatOffset(offset: number): string {
  const sign = offset >= 0 ? '+' : '-';
  const abs = Math.abs(offset);
  const h = Math.floor(abs / 3600);
  const m = Math.floor((abs % 3600) / 60);
  const s = abs % 60;
  let result = `${sign}${pad2(h)}:${pad2(m)}`;
  if (s !== 0) result += `:${pad2(s)}`;
  return result;
}

function dayOfWeek(y: number, m: number, d: number): number {
  const t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4];
  if (m < 3) y = y - 1;
  return ((y + Math.floor(y / 4) - Math.floor(y / 100) + Math.floor(y / 400) + t[m - 1] + d) % 7 + 7) % 7;
}

// --- TZif parsing ---

interface TypeRecord {
  gmtoff: number;
  isdst: number;
  abbrIndex: number;
}

interface TZifData {
  transitions: number[];
  typeIndices: number[];
  types: TypeRecord[];
  abbreviations: string[];
  footer: string;
}

function parseTZif(filePath: string): TZifData {
  const buf = fs.readFileSync(filePath);
  let pos = 0;

  // First header (44 bytes)
  pos += 4; // magic
  pos += 1; // version
  pos += 15; // unused
  const isutcnt1 = buf.readInt32BE(pos); pos += 4;
  const isstdcnt1 = buf.readInt32BE(pos); pos += 4;
  const leapcnt1 = buf.readInt32BE(pos); pos += 4;
  const timecnt1 = buf.readInt32BE(pos); pos += 4;
  const typecnt1 = buf.readInt32BE(pos); pos += 4;
  const charcnt1 = buf.readInt32BE(pos); pos += 4;

  // First data block
  pos += timecnt1 * 4;
  pos += timecnt1 * 1;
  pos += typecnt1 * 6;
  pos += charcnt1;
  pos += leapcnt1 * 8;
  pos += isstdcnt1;
  pos += isutcnt1;

  // Second header (44 bytes)
  pos += 4; // magic
  pos += 1; // version
  pos += 15; // unused
  const isutcnt2 = buf.readInt32BE(pos); pos += 4;
  const isstdcnt2 = buf.readInt32BE(pos); pos += 4;
  const leapcnt2 = buf.readInt32BE(pos); pos += 4;
  const timecnt2 = buf.readInt32BE(pos); pos += 4;
  const typecnt2 = buf.readInt32BE(pos); pos += 4;
  const charcnt2 = buf.readInt32BE(pos); pos += 4;

  // Second data block (64-bit)
  const transitions: number[] = [];
  for (let i = 0; i < timecnt2; i++) {
    transitions.push(Number(buf.readBigInt64BE(pos))); pos += 8;
  }

  const typeIndices: number[] = [];
  for (let i = 0; i < timecnt2; i++) {
    typeIndices.push(buf[pos]); pos += 1;
  }

  const types: TypeRecord[] = [];
  for (let i = 0; i < typecnt2; i++) {
    const gmtoff = buf.readInt32BE(pos); pos += 4;
    const isdst = buf[pos]; pos += 1;
    const abbrIndex = buf[pos]; pos += 1;
    types.push({ gmtoff, isdst, abbrIndex });
  }

  // Abbreviations
  const abbrBuf = buf.slice(pos, pos + charcnt2); pos += charcnt2;
  const abbreviations: string[] = [];
  let abbrStart = 0;
  for (let i = 0; i < charcnt2; i++) {
    if (abbrBuf[i] === 0) {
      abbreviations.push(abbrBuf.toString('ascii', abbrStart, i));
      abbrStart = i + 1;
    }
  }

  // Leap seconds
  pos += leapcnt2 * 12;
  pos += isstdcnt2;
  pos += isutcnt2;

  // Footer
  pos += 1; // leading \n
  const footerEnd = buf.indexOf(0x0A, pos);
  const footer = footerEnd >= 0 ? buf.toString('ascii', pos, footerEnd) : '';

  return { transitions, typeIndices, types, abbreviations, footer };
}

// --- POSIX TZ string parsing ---

interface PosixRule {
  month: number;
  week: number;
  day: number;
  time: number;
}

interface PosixTZ {
  stdName: string;
  stdOffset: number;
  dstName: string;
  dstOffset: number;
  start: PosixRule;
  end: PosixRule;
  hasDst: boolean;
  hasRules: boolean;
}

function parsePosixTZ(s: string): PosixTZ {
  let pos = 0;

  function readName(): string {
    if (pos < s.length && s[pos] === '<') {
      pos++;
      let name = '';
      while (pos < s.length && s[pos] !== '>') { name += s[pos]; pos++; }
      pos++;
      return name;
    } else {
      let name = '';
      while (pos < s.length && /[A-Za-z]/.test(s[pos])) { name += s[pos]; pos++; }
      return name;
    }
  }

  function readOffsetVal(): number {
    let sign = 1;
    if (pos < s.length && (s[pos] === '+' || s[pos] === '-')) {
      if (s[pos] === '-') sign = -1;
      pos++;
    }
    let h = 0, m = 0, sec = 0;
    let numStr = '';
    while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
    h = parseInt(numStr) || 0;
    if (pos < s.length && s[pos] === ':') {
      pos++;
      numStr = '';
      while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
      m = parseInt(numStr) || 0;
      if (pos < s.length && s[pos] === ':') {
        pos++;
        numStr = '';
        while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
        sec = parseInt(numStr) || 0;
      }
    }
    return sign * (h * 3600 + m * 60 + sec);
  }

  function readTime(): number {
    let sign = 1;
    if (pos < s.length && (s[pos] === '+' || s[pos] === '-')) {
      if (s[pos] === '-') sign = -1;
      pos++;
    }
    let h = 0, m = 0, sec = 0;
    let numStr = '';
    while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
    h = parseInt(numStr) || 0;
    if (pos < s.length && s[pos] === ':') {
      pos++;
      numStr = '';
      while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
      m = parseInt(numStr) || 0;
      if (pos < s.length && s[pos] === ':') {
        pos++;
        numStr = '';
        while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
        sec = parseInt(numStr) || 0;
      }
    }
    return sign * (h * 3600 + m * 60 + sec);
  }

  function readRule(): PosixRule {
    pos++; // skip 'M'
    let numStr = '';
    while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
    const month = parseInt(numStr);
    pos++; // skip '.'
    numStr = '';
    while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
    const week = parseInt(numStr);
    pos++; // skip '.'
    numStr = '';
    while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
    const day = parseInt(numStr);
    let time = 2 * 3600;
    if (pos < s.length && s[pos] === '/') {
      pos++;
      time = readTime();
    }
    return { month, week, day, time };
  }

  const stdName = readName();
  const stdOffsetVal = readOffsetVal();
  const stdOffset = -stdOffsetVal;

  let hasDst = false;
  let dstName = '';
  let dstOffset = stdOffset;
  let start: PosixRule = { month: 0, week: 0, day: 0, time: 0 };
  let end: PosixRule = { month: 0, week: 0, day: 0, time: 0 };
  let hasRules = true;

  if (pos < s.length && (/[A-Za-z<]/.test(s[pos]))) {
    hasDst = true;
    dstName = readName();
    if (pos < s.length && (s[pos] === '+' || s[pos] === '-' || /\d/.test(s[pos]))) {
      const dstOffsetVal = readOffsetVal();
      dstOffset = -dstOffsetVal;
    } else {
      dstOffset = stdOffset + 3600;
    }
    if (pos < s.length && s[pos] === ',') {
      pos++;
      start = readRule();
      pos++;
      end = readRule();
    } else {
      hasRules = false;
    }
  }

  return { stdName, stdOffset, dstName, dstOffset, start, end, hasDst, hasRules };
}

// --- Core logic ---

function computeDayOfMonth(y: number, rule: PosixRule): number {
  const { month, week, day } = rule;
  const dim = daysInMonth(y, month);
  const dowFirst = dayOfWeek(y, month, 1);
  let firstDay: number;
  if (dowFirst <= day) {
    firstDay = 1 + (day - dowFirst);
  } else {
    firstDay = 1 + (7 - dowFirst + day);
  }
  let d = firstDay + (week - 1) * 7;
  if (d > dim) d -= 7;
  return d;
}

function computeTransitionUtc(y: number, rule: PosixRule, utcOffset: number): number {
  const d = computeDayOfMonth(y, rule);
  const localUnix = componentsToUnix(y, rule.month, d, 0, 0, 0) + rule.time;
  return localUnix - utcOffset;
}

function isDstAt(t: number, posix: PosixTZ): boolean {
  if (!posix.hasDst) return false;
  if (!posix.hasRules) return true;

  const comp = unixToComponents(t);
  const year = comp.y;

  const trans: { time: number; toDst: boolean }[] = [];
  for (let y = year - 1; y <= year + 1; y++) {
    trans.push({ time: computeTransitionUtc(y, posix.start, posix.stdOffset), toDst: true });
    trans.push({ time: computeTransitionUtc(y, posix.end, posix.dstOffset), toDst: false });
  }
  trans.sort((a, b) => a.time - b.time);

  let isdst = false;
  for (const tr of trans) {
    if (tr.time <= t) {
      isdst = tr.toDst;
    } else {
      break;
    }
  }
  return isdst;
}

function getOffsetAtTime(tzif: TZifData, posix: PosixTZ | null, t: number): { offset: number; abbr: string; isdst: boolean } {
  const { transitions, typeIndices, types, abbreviations } = tzif;

  if (transitions.length === 0) {
    if (posix) {
      if (isDstAt(t, posix)) {
        return { offset: posix.dstOffset, abbr: posix.dstName, isdst: true };
      } else {
        return { offset: posix.stdOffset, abbr: posix.stdName, isdst: false };
      }
    }
    const type = types[0];
    return { offset: type.gmtoff, abbr: abbreviations[type.abbrIndex], isdst: type.isdst === 1 };
  }

  if (t < transitions[0]) {
    const type = types[0];
    return { offset: type.gmtoff, abbr: abbreviations[type.abbrIndex], isdst: type.isdst === 1 };
  }

  if (t > transitions[transitions.length - 1]) {
    if (posix) {
      if (isDstAt(t, posix)) {
        return { offset: posix.dstOffset, abbr: posix.dstName, isdst: true };
      } else {
        return { offset: posix.stdOffset, abbr: posix.stdName, isdst: false };
      }
    }
    const type = types[typeIndices[transitions.length - 1]];
    return { offset: type.gmtoff, abbr: abbreviations[type.abbrIndex], isdst: type.isdst === 1 };
  }

  // Binary search: find latest transition <= t
  let lo = 0, hi = transitions.length - 1;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (transitions[mid] <= t) {
      lo = mid;
    } else {
      hi = mid - 1;
    }
  }
  const type = types[typeIndices[lo]];
  return { offset: type.gmtoff, abbr: abbreviations[type.abbrIndex], isdst: type.isdst === 1 };
}

// --- Main ---

const dir = process.argv[2];
const queryFile = path.join(dir, 'queries.txt');
const content = fs.readFileSync(queryFile, 'utf8');
const lines = content.split('\n');

const tzifCache: Map<string, { tzif: TZifData; posix: PosixTZ | null }> = new Map();

function getTZif(fileName: string): { tzif: TZifData; posix: PosixTZ | null } {
  if (tzifCache.has(fileName)) return tzifCache.get(fileName)!;
  const filePath = path.join(dir, fileName);
  const tzif = parseTZif(filePath);
  let posix: PosixTZ | null = null;
  if (tzif.footer.length > 0) {
    posix = parsePosixTZ(tzif.footer);
  }
  const result = { tzif, posix };
  tzifCache.set(fileName, result);
  return result;
}

const output: string[] = [];

for (const line of lines) {
  if (!line.trim()) continue;
  const parts = line.split(' ');

  if (parts[0] === 'UTC') {
    const fileName = parts[1];
    const t = parseInt(parts[2]);
    const { tzif, posix } = getTZif(fileName);
    const { offset, abbr } = getOffsetAtTime(tzif, posix, t);
    const localUnix = t + offset;
    const comp = unixToComponents(localUnix);
    const localStr = formatLocal(comp.y, comp.m, comp.d, comp.h, comp.mi, comp.s);
    const offsetStr = formatOffset(offset);
    output.push(`${line} -> ${localStr}${offsetStr} ${abbr}`);

  } else if (parts[0] === 'LOCAL') {
    const fileName = parts[1];
    const wallStr = parts[2];
    const { tzif, posix } = getTZif(fileName);

    const [datePart, timePart] = wallStr.split('T');
    const [wy, wm, wd] = datePart.split('-').map(Number);
    const [wh, wmi, ws] = timePart.split(':').map(Number);
    const wallAsNumber = componentsToUnix(wy, wm, wd, wh, wmi, ws);

    // Collect all possible UTC offsets
    const offsets = new Set<number>();
    for (const type of tzif.types) {
      offsets.add(type.gmtoff);
    }
    if (posix) {
      offsets.add(posix.stdOffset);
      if (posix.hasDst) offsets.add(posix.dstOffset);
    }

    // Compute candidates
    const validCandidates: { t: number; offset: number; abbr: string }[] = [];
    for (const off of offsets) {
      const t = wallAsNumber - off;
      const { offset: actualOffset, abbr } = getOffsetAtTime(tzif, posix, t);
      if (actualOffset === off) {
        const localUnix = t + actualOffset;
        if (localUnix === wallAsNumber) {
          validCandidates.push({ t, offset: off, abbr });
        }
      }
    }

    validCandidates.sort((a, b) => a.t - b.t);

    if (validCandidates.length === 1) {
      const c = validCandidates[0];
      const offsetStr = formatOffset(c.offset);
      output.push(`${line} -> ${c.t} ${offsetStr} ${c.abbr}`);
    } else if (validCandidates.length === 2) {
      const c1 = validCandidates[0];
      const c2 = validCandidates[1];
      const offsetStr1 = formatOffset(c1.offset);
      const offsetStr2 = formatOffset(c2.offset);
      output.push(`${line} -> ${c1.t} ${offsetStr1} ${c1.abbr} | ${c2.t} ${offsetStr2} ${c2.abbr}`);
    } else {
      // Gap: find the transition that caused it
      const allTransitions: { time: number; oldOffset: number; newOffset: number }[] = [];

      // Data block transitions
      for (let i = 0; i < tzif.transitions.length; i++) {
        const tr = tzif.transitions[i];
        const newType = tzif.types[tzif.typeIndices[i]];
        const oldType = i > 0 ? tzif.types[tzif.typeIndices[i - 1]] : tzif.types[0];
        allTransitions.push({ time: tr, oldOffset: oldType.gmtoff, newOffset: newType.gmtoff });
      }

      // Footer transitions
      if (posix && posix.hasDst && posix.hasRules) {
        const comp = unixToComponents(wallAsNumber);
        for (let y = comp.y - 2; y <= comp.y + 2; y++) {
          const startT = computeTransitionUtc(y, posix.start, posix.stdOffset);
          const endT = computeTransitionUtc(y, posix.end, posix.dstOffset);
          allTransitions.push({ time: startT, oldOffset: posix.stdOffset, newOffset: posix.dstOffset });
          allTransitions.push({ time: endT, oldOffset: posix.dstOffset, newOffset: posix.stdOffset });
        }
      }

      let gapTransition: { time: number; oldOffset: number; newOffset: number } | null = null;
      for (const tr of allTransitions) {
        if (tr.newOffset > tr.oldOffset) {
          if (wallAsNumber >= tr.time + tr.oldOffset && wallAsNumber < tr.time + tr.newOffset) {
            gapTransition = tr;
            break;
          }
        }
      }

      if (gapTransition) {
        const t = wallAsNumber - gapTransition.oldOffset;
        const { offset, abbr } = getOffsetAtTime(tzif, posix, t);
        const localUnix = t + offset;
        const comp = unixToComponents(localUnix);
        const localStr = formatLocal(comp.y, comp.m, comp.d, comp.h, comp.mi, comp.s);
        const offsetStr = formatOffset(offset);
        output.push(`${line} -> GAP ${t} ${localStr}${offsetStr} ${abbr}`);
      }
    }
  }
}

console.log(output.join('\n'));

import * as fs from 'fs';
