function civilFromDays(z: number): { y: number; m: number; d: number } {
  z += 719468;
  const era = Math.floor(z / 146097);
  const doe = z - era * 146097;
  const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
  const y = yoe + era * 400;
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
  const mp = Math.floor((5 * doy + 2) / 153);
  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
  const m = mp + (mp < 10 ? 3 : -9);
  return { y: y + (m <= 2 ? 1 : 0), m, d };
}

function unixToComponents(t: number): { y: number; m: number; d: number; h: number; mi: number; s: number } {
  let days = Math.floor(t / 86400);
  let rem = t - days * 86400;
  const { y, m, d } = civilFromDays(days);
  const h = Math.floor(rem / 3600);
  const mi = Math.floor((rem % 3600) / 60);
  const s = rem % 60;
  return { y, m, d, h, mi, s };
}

function componentsToUnix(y: number, m: number, d: number, h: number, mi: number, s: number): number {
  return daysFromCivil(y, m, d) * 86400 + h * 3600 + mi * 60 + s;
}

function pad2(n: number): string {
  return n.toString().padStart(2, '0');
}

function formatLocal(y: number, m: number, d: number, h: number, mi: number, s: number): string {
  return `${y}-${pad2(m)}-${pad2(d)}T${pad2(h)}:${pad2(mi)}:${pad2(s)}`;
}

function formatOffset(offset: number): string {
  const sign = offset >= 0 ? '+' : '-';
  const abs = Math.abs(offset);
  const h = Math.floor(abs / 3600);
  const m = Math.floor((abs % 3600) / 60);
  const s = abs % 60;
  let result = `${sign}${pad2(h)}:${pad2(m)}`;
  if (s !== 0) result += `:${pad2(s)}`;
  return result;
}

function dayOfWeek(y: number, m: number, d: number): number {
  const t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4];
  if (m < 3) y = y - 1;
  return ((y + Math.floor(y / 4) - Math.floor(y / 100) + Math.floor(y / 400) + t[m - 1] + d) % 7 + 7) % 7;
}

// --- TZif parsing ---

interface TypeRecord {
  gmtoff: number;
  isdst: number;
  abbrIndex: number;
}

interface TZifData {
  transitions: number[];
  typeIndices: number[];
  types: TypeRecord[];
  abbrBuf: Buffer;
  footer: string;
}

function getAbbr(abbrBuf: Buffer, abbrIndex: number): string {
  let end = abbrIndex;
  while (end < abbrBuf.length && abbrBuf[end] !== 0) end++;
  return abbrBuf.toString('ascii', abbrIndex, end);
}

function parseTZif(filePath: string): TZifData {
  const buf = fs.readFileSync(filePath);
  let pos = 0;

  // First header (44 bytes)
  pos += 4; // magic
  pos += 1; // version
  pos += 15; // unused
  const isutcnt1 = buf.readInt32BE(pos); pos += 4;
  const isstdcnt1 = buf.readInt32BE(pos); pos += 4;
  const leapcnt1 = buf.readInt32BE(pos); pos += 4;
  const timecnt1 = buf.readInt32BE(pos); pos += 4;
  const typecnt1 = buf.readInt32BE(pos); pos += 4;
  const charcnt1 = buf.readInt32BE(pos); pos += 4;

  // First data block
  pos += timecnt1 * 4;
  pos += timecnt1 * 1;
  pos += typecnt1 * 6;
  pos += charcnt1;
  pos += leapcnt1 * 8;
  pos += isstdcnt1;
  pos += isutcnt1;

  // Second header (44 bytes)
  pos += 4; // magic
  pos += 1; // version
  pos += 15; // unused
  const isutcnt2 = buf.readInt32BE(pos); pos += 4;
  const isstdcnt2 = buf.readInt32BE(pos); pos += 4;
  const leapcnt2 = buf.readInt32BE(pos); pos += 4;
  const timecnt2 = buf.readInt32BE(pos); pos += 4;
  const typecnt2 = buf.readInt32BE(pos); pos += 4;
  const charcnt2 = buf.readInt32BE(pos); pos += 4;

  // Second data block (64-bit)
  const transitions: number[] = [];
  for (let i = 0; i < timecnt2; i++) {
    transitions.push(Number(buf.readBigInt64BE(pos))); pos += 8;
  }

  const typeIndices: number[] = [];
  for (let i = 0; i < timecnt2; i++) {
    typeIndices.push(buf[pos]); pos += 1;
  }

  const types: TypeRecord[] = [];
  for (let i = 0; i < typecnt2; i++) {
    const gmtoff = buf.readInt32BE(pos); pos += 4;
    const isdst = buf[pos]; pos += 1;
    const abbrIndex = buf[pos]; pos += 1;
    types.push({ gmtoff, isdst, abbrIndex });
  }

  // Abbreviation buffer (raw)
  const abbrBuf = buf.slice(pos, pos + charcnt2); pos += charcnt2;

  // Leap seconds
  pos += leapcnt2 * 12;
  pos += isstdcnt2;
  pos += isutcnt2;

  // Footer
  pos += 1; // leading \n
  const footerEnd = buf.indexOf(0x0A, pos);
  const footer = footerEnd >= 0 ? buf.toString('ascii', pos, footerEnd) : '';

  return { transitions, typeIndices, types, abbrBuf, footer };
}

// --- POSIX TZ string parsing ---

interface PosixRule {
  month: number;
  week: number;
  day: number;
  time: number;
}

interface PosixTZ {
  stdName: string;
  stdOffset: number;
  dstName: string;
  dstOffset: number;
  start: PosixRule;
  end: PosixRule;
  hasDst: boolean;
  hasRules: boolean;
}

function parsePosixTZ(s: string): PosixTZ {
  let pos = 0;

  function readName(): string {
    if (pos < s.length && s[pos] === '<') {
      pos++;
      let name = '';
      while (pos < s.length && s[pos] !== '>') { name += s[pos]; pos++; }
      pos++;
      return name;
    } else {
      let name = '';
      while (pos < s.length && /[A-Za-z]/.test(s[pos])) { name += s[pos]; pos++; }
      return name;
    }
  }

  function readOffsetVal(): number {
    let sign = 1;
    if (pos < s.length && (s[pos] === '+' || s[pos] === '-')) {
      if (s[pos] === '-') sign = -1;
      pos++;
    }
    let h = 0, m = 0, sec = 0;
    let numStr = '';
    while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
    h = parseInt(numStr) || 0;
    if (pos < s.length && s[pos] === ':') {
      pos++;
      numStr = '';
      while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
      m = parseInt(numStr) || 0;
      if (pos < s.length && s[pos] === ':') {
        pos++;
        numStr = '';
        while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
        sec = parseInt(numStr) || 0;
      }
    }
    return sign * (h * 3600 + m * 60 + sec);
  }

  function readTime(): number {
    let sign = 1;
    if (pos < s.length && (s[pos] === '+' || s[pos] === '-')) {
      if (s[pos] === '-') sign = -1;
      pos++;
    }
    let h = 0, m = 0, sec = 0;
    let numStr = '';
    while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
    h = parseInt(numStr) || 0;
    if (pos < s.length && s[pos] === ':') {
      pos++;
      numStr = '';
      while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
      m = parseInt(numStr) || 0;
      if (pos < s.length && s[pos] === ':') {
        pos++;
        numStr = '';
        while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
        sec = parseInt(numStr) || 0;
      }
    }
    return sign * (h * 3600 + m * 60 + sec);
  }

  function readRule(): PosixRule {
    pos++; // skip 'M'
    let numStr = '';
    while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
    const month = parseInt(numStr);
    pos++; // skip '.'
    numStr = '';
    while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
    const week = parseInt(numStr);
    pos++; // skip '.'
    numStr = '';
    while (pos < s.length && /\d/.test(s[pos])) { numStr += s[pos]; pos++; }
    const day = parseInt(numStr);
    let time = 2 * 3600;
    if (pos < s.length && s[pos] === '/') {
      pos++;
      time = readTime();
    }
    return { month, week, day, time };
  }

  const stdName = readName();
  const stdOffsetVal = readOffsetVal();
  const stdOffset = -stdOffsetVal;

  let hasDst = false;
  let dstName = '';
  let dstOffset = stdOffset;
  let start: PosixRule = { month: 0, week: 0, day: 0, time: 0 };
  let end: PosixRule = { month: 0, week: 0, day: 0, time: 0 };
  let hasRules = true;

  if (pos < s.length && (/[A-Za-z<]/.test(s[pos]))) {
    hasDst = true;
    dstName = readName();
    if (pos < s.length && (s[pos] === '+' || s[pos] === '-' || /\d/.test(s[pos]))) {
      const dstOffsetVal = readOffsetVal();
      dstOffset = -dstOffsetVal;
    } else {
      dstOffset = stdOffset + 3600;
    }
    if (pos < s.length && s[pos] === ',') {
      pos++;
      start = readRule();
      pos++;
      end = readRule();
    } else {
      hasRules = false;
    }
  }

  return { stdName, stdOffset, dstName, dstOffset, start, end, hasDst, hasRules };
}

// --- Core logic ---

function computeDayOfMonth(y: number, rule: PosixRule): number {
  const { month, week, day } = rule;
  const dim = daysInMonth(y, month);
  const dowFirst = dayOfWeek(y, month, 1);
  let firstDay: number;
  if (dowFirst <= day) {
    firstDay = 1 + (day - dowFirst);
  } else {
    firstDay = 1 + (7 - dowFirst + day);
  }
  let d = firstDay + (week - 1) * 7;
  if (d > dim) d -= 7;
  return d;
}

function computeTransitionUtc(y: number, rule: PosixRule, utcOffset: number): number {
  const d = computeDayOfMonth(y, rule);
  const localUnix = componentsToUnix(y, rule.month, d, 0, 0, 0) + rule.time;
  return localUnix - utcOffset;
}

function isDstAt(t: number, posix: PosixTZ): boolean {
  if (!posix.hasDst) return false;
  if (!posix.hasRules) return true;

  const comp = unixToComponents(t);
  const year = comp.y;

  const trans: { time: number; toDst: boolean }[] = [];
  for (let y = year - 1; y <= year + 1; y++) {
    trans.push({ time: computeTransitionUtc(y, posix.start, posix.stdOffset), toDst: true });
    trans.push({ time: computeTransitionUtc(y, posix.end, posix.dstOffset), toDst: false });
  }
  trans.sort((a, b) => a.time - b.time);

  let isdst = false;
  for (const tr of trans) {
    if (tr.time <= t) {
      isdst = tr.toDst;
    } else {
      break;
    }
  }
  return isdst;
}

function getOffsetAtTime(tzif: TZifData, posix: PosixTZ | null, t: number): { offset: number; abbr: string; isdst: boolean } {
  const { transitions, typeIndices, types, abbrBuf } = tzif;

  if (transitions.length === 0) {
    if (posix) {
      if (isDstAt(t, posix)) {
        return { offset: posix.dstOffset, abbr: posix.dstName, isdst: true };
      } else {
        return { offset: posix.stdOffset, abbr: posix.stdName, isdst: false };
      }
    }
    const type = types[0];
    return { offset: type.gmtoff, abbr: getAbbr(abbrBuf, type.abbrIndex), isdst: type.isdst === 1 };
  }

  if (t < transitions[0]) {
    const type = types[0];
    return { offset: type.gmtoff, abbr: getAbbr(abbrBuf, type.abbrIndex), isdst: type.isdst === 1 };
  }

  if (t > transitions[transitions.length - 1]) {
    if (posix) {
      if (isDstAt(t, posix)) {
        return { offset: posix.dstOffset, abbr: posix.dstName, isdst: true };
      } else {
        return { offset: posix.stdOffset, abbr: posix.stdName, isdst: false };
      }
    }
    const type = types[typeIndices[transitions.length - 1]];
    return { offset: type.gmtoff, abbr: getAbbr(abbrBuf, type.abbrIndex), isdst: type.isdst === 1 };
  }

  // Binary search: find latest transition <= t
  let lo = 0, hi = transitions.length - 1;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (transitions[mid] <= t) {
      lo = mid;
    } else {
      hi = mid - 1;
    }
  }
  const type = types[typeIndices[lo]];
  return { offset: type.gmtoff, abbr: getAbbr(abbrBuf, type.abbrIndex), isdst: type.isdst === 1 };
}

// --- Main ---

const dir = process.argv[2];
const queryFile = path.join(dir, 'queries.txt');
const content = fs.readFileSync(queryFile, 'utf8');
const lines = content.split('\n');

const tzifCache: Map<string, { tzif: TZifData; posix: PosixTZ | null }> = new Map();

function getTZif(fileName: string): { tzif: TZifData; posix: PosixTZ | null } {
  if (tzifCache.has(fileName)) return tzifCache.get(fileName)!;
  const filePath = path.join(dir, fileName);
  const tzif = parseTZif(filePath);
  let posix: PosixTZ | null = null;
  if (tzif.footer.length > 0) {
    posix = parsePosixTZ(tzif.footer);
  }
  const result = { tzif, posix };
  tzifCache.set(fileName, result);
  return result;
}

const output: string[] = [];

for (const line of lines) {
  if (!line.trim()) continue;
  const parts = line.split(' ');

  if (parts[0] === 'UTC') {
    const fileName = parts[1];
    const t = parseInt(parts[2]);
    const { tzif, posix } = getTZif(fileName);
    const { offset, abbr } = getOffsetAtTime(tzif, posix, t);
    const localUnix = t + offset;
    const comp = unixToComponents(localUnix);
    const localStr = formatLocal(comp.y, comp.m, comp.d, comp.h, comp.mi, comp.s);
    const offsetStr = formatOffset(offset);
    output.push(`${line} -> ${localStr}${offsetStr} ${abbr}`);

  } else if (parts[0] === 'LOCAL') {
    const fileName = parts[1];
    const wallStr = parts[2];
    const { tzif, posix } = getTZif(fileName);

    const [datePart, timePart] = wallStr.split('T');
    const [wy, wm, wd] = datePart.split('-').map(Number);
    const [wh, wmi, ws] = timePart.split(':').map(Number);
    const wallAsNumber = componentsToUnix(wy, wm, wd, wh, wmi, ws);

    // Collect all possible UTC offsets
    const offsets = new Set<number>();
    for (const type of tzif.types) {
      offsets.add(type.gmtoff);
    }
    if (posix) {
      offsets.add(posix.stdOffset);
      if (posix.hasDst) offsets.add(posix.dstOffset);
    }

    // Compute candidates
    const validCandidates: { t: number; offset: number; abbr: string }[] = [];
    for (const off of offsets) {
      const t = wallAsNumber - off;
      const { offset: actualOffset, abbr } = getOffsetAtTime(tzif, posix, t);
      if (actualOffset === off) {
        const localUnix = t + actualOffset;
        if (localUnix === wallAsNumber) {
          validCandidates.push({ t, offset: off, abbr });
        }
      }
    }

    validCandidates.sort((a, b) => a.t - b.t);

    if (validCandidates.length === 1) {
      const c = validCandidates[0];
      const offsetStr = formatOffset(c.offset);
      output.push(`${line} -> ${c.t} ${offsetStr} ${c.abbr}`);
    } else if (validCandidates.length === 2) {
      const c1 = validCandidates[0];
      const c2 = validCandidates[1];
      const offsetStr1 = formatOffset(c1.offset);
      const offsetStr2 = formatOffset(c2.offset);
      output.push(`${line} -> ${c1.t} ${offsetStr1} ${c1.abbr} | ${c2.t} ${offsetStr2} ${c2.abbr}`);
    } else {
      // Gap: find the transition that caused it
      const allTransitions: { time: number; oldOffset: number; newOffset: number }[] = [];

      // Data block transitions
      for (let i = 0; i < tzif.transitions.length; i++) {
        const tr = tzif.transitions[i];
        const newType = tzif.types[tzif.typeIndices[i]];
        const oldType = i > 0 ? tzif.types[tzif.typeIndices[i - 1]] : tzif.types[0];
        allTransitions.push({ time: tr, oldOffset: oldType.gmtoff, newOffset: newType.gmtoff });
      }

      // Footer transitions
      if (posix && posix.hasDst && posix.hasRules) {
        const comp = unixToComponents(wallAsNumber);
        for (let y = comp.y - 2; y <= comp.y + 2; y++) {
          const startT = computeTransitionUtc(y, posix.start, posix.stdOffset);
          const endT = computeTransitionUtc(y, posix.end, posix.dstOffset);
          allTransitions.push({ time: startT, oldOffset: posix.stdOffset, newOffset: posix.dstOffset });
          allTransitions.push({ time: endT, oldOffset: posix.dstOffset, newOffset: posix.stdOffset });
        }
      }

      let gapTransition: { time: number; oldOffset: number; newOffset: number } | null = null;
      for (const tr of allTransitions) {
        if (tr.newOffset > tr.oldOffset) {
          if (wallAsNumber >= tr.time + tr.oldOffset && wallAsNumber < tr.time + tr.newOffset) {
            gapTransition = tr;
            break;
          }
        }
      }

      if (gapTransition) {
        const t = wallAsNumber - gapTransition.oldOffset;
        const { offset, abbr } = getOffsetAtTime(tzif, posix, t);
        const localUnix = t + offset;
        const comp = unixToComponents(localUnix);
        const localStr = formatLocal(comp.y, comp.m, comp.d, comp.h, comp.mi, comp.s);
        const offsetStr = formatOffset(offset);
        output.push(`${line} -> GAP ${t} ${localStr}${offsetStr} ${abbr}`);
      }
    }
  }
}

console.log(output.join('\n'));

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.Base64;

public class Main {
    static final SecureRandom RNG = new SecureRandom();

    public static void main(String[] args) throws Exception {
        for (int i = 0; i < args.length; i++) {
            System.out.println("session " + (i + 1));
            processUrl(args[i]);
        }
    }

    static void processUrl(String url) throws Exception {
        String rest = url.substring(5); // strip "ws://"
        int slashIdx = rest.indexOf('/');
        String hostPort, path;
        if (slashIdx >= 0) {
            hostPort = rest.substring(0, slashIdx);
            path = rest.substring(slashIdx);
        } else {
            hostPort = rest;
            path = "/";
        }

        String host;
        int port;
        int colonIdx = hostPort.lastIndexOf(':');
        if (colonIdx >= 0) {
            host = hostPort.substring(0, colonIdx);
            port = Integer.parseInt(hostPort.substring(colonIdx + 1));
        } else {
            host = hostPort;
            port = 80;
        }

        Socket socket = new Socket(host, port);
        socket.setTcpNoDelay(true);
        BufferedInputStream in = new BufferedInputStream(socket.getInputStream());
        OutputStream out = socket.getOutputStream();

        byte[] keyBytes = new byte[16];
        RNG.nextBytes(keyBytes);
        String wsKey = Base64.getEncoder().encodeToString(keyBytes);

        StringBuilder req = new StringBuilder();
        req.append("GET ").append(path).append(" HTTP/1.1\r\n");
        req.append("Host: ").append(host).append(":").append(port).append("\r\n");
        req.append("Upgrade: websocket\r\n");
        req.append("Connection: Upgrade\r\n");
        req.append("Sec-WebSocket-Version: 13\r\n");
        req.append("Sec-WebSocket-Key: ").append(wsKey).append("\r\n");
        req.append("\r\n");
        out.write(req.toString().getBytes(StandardCharsets.US_ASCII));
        out.flush();

        String statusLine = readLine(in);
        int sp1 = statusLine.indexOf(' ');
        String afterVer = statusLine.substring(sp1 + 1);
        int sp2 = afterVer.indexOf(' ');
        int statusCode;
        String reasonPhrase;
        if (sp2 >= 0) {
            statusCode = Integer.parseInt(afterVer.substring(0, sp2));
            reasonPhrase = afterVer.substring(sp2 + 1);
        } else {
            statusCode = Integer.parseInt(afterVer);
            reasonPhrase = "";
        }

        if (statusCode != 101) {
            System.out.println("handshake failed: " + statusCode + " " + reasonPhrase);
            socket.close();
            return;
        }

        String acceptValue = null;
        while (true) {
            String line = readLine(in);
            if (line.isEmpty()) break;
            int colon = line.indexOf(':');
            if (colon >= 0) {
                String name = line.substring(0, colon).trim();
                String value = line.substring(colon + 1).trim();
                if (name.equalsIgnoreCase("Sec-WebSocket-Accept")) {
                    acceptValue = value;
                }
            }
        }

        String expectedAccept = computeAccept(wsKey);
        if (acceptValue == null || !acceptValue.equals(expectedAccept)) {
            System.out.println("handshake failed: bad Sec-WebSocket-Accept");
            socket.close();
            return;
        }

        processFrames(in, out, socket);
    }

    static String computeAccept(String key) throws Exception {
        MessageDigest sha1 = MessageDigest.getInstance("SHA-1");
        sha1.update((key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11").getBytes(StandardCharsets.US_ASCII));
        return Base64.getEncoder().encodeToString(sha1.digest());
    }

    static String readLine(InputStream in) throws IOException {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = in.read()) != -1) {
            if (c == '\r') {
                int next = in.read();
                if (next == '\n') break;
                sb.append((char) c);
                if (next != -1) sb.append((char) next);
            } else if (c == '\n') {
                break;
            } else {
                sb.append((char) c);
            }
        }
        return sb.toString();
    }

    static void processFrames(InputStream in, OutputStream out, Socket socket) throws Exception {
        boolean sentClose = false;
        boolean sha1Waiting = false;
        boolean assembling = false;
        int assembleOpcode = -1;
        ByteArrayOutputStream assembleBuf = null;

        while (true) {
            int b0 = in.read();
            if (b0 == -1) break;
            boolean fin = (b0 & 0x80) != 0;
            int opcode = b0 & 0x0F;

            int b1 = in.read();
            if (b1 == -1) break;
            long payloadLen = b1 & 0x7F;
            if (payloadLen == 126) payloadLen = readBE(in, 2);
            else if (payloadLen == 127) payloadLen = readBE(in, 8);

            byte[] payload = new byte[(int) payloadLen];
            if (payloadLen > 0) readFully(in, payload);

            // Control frames
            if (opcode == 8) { // Close
                int closeCode = 0;
                String closeReason = "";
                if (payload.length >= 2) {
                    closeCode = ((payload[0] & 0xFF) << 8) | (payload[1] & 0xFF);
                    if (payload.length > 2) {
                        closeReason = new String(payload, 2, payload.length - 2, StandardCharsets.UTF_8);
                    }
                }
                if (closeReason.isEmpty()) {
                    System.out.println("closed " + closeCode);
                } else {
                    System.out.println("closed " + closeCode + " " + closeReason);
                }
                if (!sentClose) {
                    sendFrame(out, 8, new byte[]{(byte) (closeCode >> 8), (byte) (closeCode & 0xFF)});
                    sentClose = true;
                }
                socket.close();
                return;
            } else if (opcode == 9) { // Ping
                sendFrame(out, 10, payload);
                continue;
            } else if (opcode == 10) { // Pong
                continue;
            }

            // Data frames
            if (opcode == 1 || opcode == 2) {
                assembling = true;
                assembleOpcode = opcode;
                assembleBuf = new ByteArrayOutputStream();
                assembleBuf.write(payload);
            } else if (opcode == 0) { // Continuation
                if (!assembling) continue;
                assembleBuf.write(payload);
            } else {
                continue;
            }

            if (!fin) continue;

            // Complete message assembled
            assembling = false;
            byte[] msgData = assembleBuf.toByteArray();
            int msgOp = assembleOpcode;

            if (sha1Waiting) {
                sha1Waiting = false;
                MessageDigest md = MessageDigest.getInstance("SHA-1");
                md.update(msgData);
                String hex = bytesToHex(md.digest());
                sendFrame(out, 1, hex.getBytes(StandardCharsets.UTF_8));
                System.out.println("SHA1 " + msgData.length + " -> " + hex);
                continue;
            }

            if (msgOp == 1) {
                String text = new String(msgData, StandardCharsets.UTF_8);

                if (text.equals("BYE")) {
                    sendFrame(out, 8, new byte[]{0x03, (byte) 0xE8});
                    sentClose = true;
                    continue;
                }

                if (text.equals("SHA1")) {
                    sha1Waiting = true;
                    continue;
                }

                if (text.startsWith("ADD ")) {
                    String[] parts = text.split(" ", 3);
                    long a = Long.parseLong(parts[1]);
                    long b = Long.parseLong(parts[2]);
                    long sum = a + b;
                    String reply = String.valueOf(sum);
                    sendFrame(out, 1, reply.getBytes(StandardCharsets.UTF_8));
                    System.out.println(text + " -> " + reply);
                } else if (text.startsWith("REV ")) {
                    String arg = text.substring(4);
                    String reversed = reverseCodePoints(arg);
                    sendFrame(out, 1, reversed.getBytes(StandardCharsets.UTF_8));
                    System.out.println(text + " -> " + reversed);
                }
            }
            // Binary message not for SHA1: ignore
        }

        if (!socket.isClosed()) socket.close();
    }

    static void sendFrame(OutputStream out, int opcode, byte[] payload) throws IOException {
        byte[] maskKey = new byte[4];
        do {
            RNG.nextBytes(maskKey);
        } while (maskKey[0] == 0 && maskKey[1] == 0 && maskKey[2] == 0 && maskKey[3] == 0);

        int len = payload.length;
        int headerSize = 2;
        if (len > 125 && len <= 65535) headerSize += 2;
        else if (len > 65535) headerSize += 8;
        headerSize += 4; // mask key

        byte[] frame = new byte[headerSize + len];
        int pos = 0;

        frame[pos++] = (byte) (0x80 | opcode); // FIN=1, RSV=0

        if (len <= 125) {
            frame[pos++] = (byte) (0x80 | len);
        } else if (len <= 65535) {
            frame[pos++] = (byte) (0x80 | 126);
            frame[pos++] = (byte) (len >> 8);
            frame[pos++] = (byte) (len & 0xFF);
        } else {
            frame[pos++] = (byte) (0x80 | 127);
            long len64 = len & 0xFFFFFFFFL;
            for (int i = 7; i >= 0; i--) {
                frame[pos++] = (byte) ((len64 >> (i * 8)) & 0xFF);
            }
        }

        frame[pos++] = maskKey[0];
        frame[pos++] = maskKey[1];
        frame[pos++] = maskKey[2];
        frame[pos++] = maskKey[3];

        for (int i = 0; i < len; i++) {
            frame[pos++] = (byte) (payload[i] ^ maskKey[i & 3]);
        }

        out.write(frame);
        out.flush();
    }

    static long readBE(InputStream in, int n) throws IOException {
        long val = 0;
        for (int i = 0; i < n; i++) {
            int b = in.read();
            if (b == -1) throw new IOException("EOF");
            val = (val << 8) | (b & 0xFF);
        }
        return val;
    }

    static void readFully(InputStream in, byte[] buf) throws IOException {
        int off = 0;
        while (off < buf.length) {
            int n = in.read(buf, off, buf.length - off);
            if (n == -1) throw new IOException("EOF");
            off += n;
        }
    }

    static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder(bytes.length * 2);
        for (byte b : bytes) {
            sb.append(String.format("%02x", b & 0xFF));
        }
        return sb.toString();
    }

    static String reverseCodePoints(String s) {
        int[] cps = s.codePoints().toArray();
        StringBuilder sb = new StringBuilder(cps.length);
        for (int i = cps.length - 1; i >= 0; i--) {
            sb.appendCodePoint(cps[i]);
        }
        return sb.toString();
    }
}

import Foundation
import Darwin
import CommonCrypto

// Buffered socket reader
class SocketReader {
    var buffer: [UInt8] = []
    var pos: Int = 0
    let fd: Int32

    init(fd: Int32) {
        self.fd = fd
    }

    func ensure(_ n: Int) -> Bool {
        while buffer.count - pos < n {
            if pos > 4096 {
                buffer.removeFirst(pos)
                pos = 0
            }
            let needed = n - (buffer.count - pos)
            let toRead = max(needed, 65536)
            var tmp = [UInt8](repeating: 0, count: toRead)
            let bytesRead = tmp.withUnsafeMutableBytes { ptr -> Int in
                Darwin.read(fd, ptr.baseAddress, toRead)
            }
            if bytesRead < 0 {
                if errno == EINTR { continue }
                return false
            }
            if bytesRead == 0 { return false }
            buffer.append(contentsOf: tmp[0..<bytesRead])
        }
        return true
    }

    func readByte() -> UInt8? {
        guard ensure(1) else { return nil }
        let b = buffer[pos]
        pos += 1
        return b
    }

    func readBytes(_ n: Int) -> [UInt8]? {
        guard ensure(n) else { return nil }
        let result = Array(buffer[pos..<pos + n])
        pos += n
        return result
    }
}

func writeAll(fd: Int32, data: [UInt8]) {
    var offset = 0
    data.withUnsafeBytes { ptr in
        while offset < data.count {
            let n = Darwin.write(fd, ptr.baseAddress! + offset, data.count - offset)
            if n < 0 {
                if errno == EINTR { continue }
                break
            }
            offset += n
        }
    }
}

func randomMaskKey() -> [UInt8] {
    var key = [UInt8](repeating: 0, count: 4)
    repeat {
        arc4random_buf(&key, 4)
    } while key[0] == 0 && key[1] == 0 && key[2] == 0 && key[3] == 0
    return key
}

func randomKey() -> String {
    var bytes = [UInt8](repeating: 0, count: 16)
    arc4random_buf(&bytes, 16)
    return Data(bytes).base64EncodedString()
}

func sha1Hex(_ data: [UInt8]) -> String {
    var digest = [UInt8](repeating: 0, count: Int(CC_SHA1_DIGEST_LENGTH))
    if data.isEmpty {
        CC_SHA1(nil, 0, &digest)
    } else {
        data.withUnsafeBytes { ptr in
            CC_SHA1(ptr.baseAddress, CC_LONG(data.count), &digest)
        }
    }
    return digest.map { String(format: "%02x", $0) }.joined()
}

func computeAccept(key: String) -> String {
    let combined = key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
    let bytes = Array(combined.utf8)
    var digest = [UInt8](repeating: 0, count: Int(CC_SHA1_DIGEST_LENGTH))
    bytes.withUnsafeBytes { ptr in
        CC_SHA1(ptr.baseAddress, CC_LONG(bytes.count), &digest)
    }
    return Data(digest).base64EncodedString()
}

func sendFrame(fd: Int32, opcode: UInt8, payload: [UInt8]) {
    var frame: [UInt8] = []
    frame.append(0x80 | opcode)

    let len = payload.count
    if len <= 125 {
        frame.append(0x80 | UInt8(len))
    } else if len <= 65535 {
        frame.append(0x80 | 126)
        frame.append(UInt8(len >> 8))
        frame.append(UInt8(len & 0xFF))
    } else {
        frame.append(0x80 | 127)
        for i in stride(from: 56, through: 0, by: -8) {
            frame.append(UInt8((len >> i) & 0xFF))
        }
    }

    let maskKey = randomMaskKey()
    frame.append(contentsOf: maskKey)

    for i in 0..<payload.count {
        frame.append(payload[i] ^ maskKey[i % 4])
    }

    writeAll(fd: fd, data: frame)
}

