use std::io::{Read, Write, BufReader};
use std::net::TcpStream;
use std::fs;
use std::process;
use std::collections::HashMap;

// --- JSON Value ---
#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

// --- JSON Parser ---
struct Parser<'a> {
    data: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(data: &'a [u8]) -> Self { Parser { data, pos: 0 } }

    fn skip_ws(&mut self) {
        while self.pos < self.data.len() {
            match self.data[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn parse_value(&mut self) -> Result<JsonValue, String> {
        self.skip_ws();
        if self.pos >= self.data.len() { return Err("eof".into()); }
        match self.data[self.pos] {
            b'"' => self.parse_string().map(JsonValue::Str),
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b't' => { self.expect_lit(b"true")?; Ok(JsonValue::Bool(true)) }
            b'f' => { self.expect_lit(b"false")?; Ok(JsonValue::Bool(false)) }
            b'n' => { self.expect_lit(b"null")?; Ok(JsonValue::Null) }
            c if c == b'-' || c.is_ascii_digit() => self.parse_number(),
            _ => Err(format!("unexpected: {}", c)),
        }
    }

    fn expect_lit(&mut self, lit: &[u8]) -> Result<(), String> {
        if self.pos + lit.len() > self.data.len() || &self.data[self.pos..self.pos+lit.len()] != lit {
            return Err("literal mismatch".into());
        }
        self.pos += lit.len();
        Ok(())
    }

    fn parse_string(&mut self) -> Result<String, String> {
        self.pos += 1;
        let mut s = String::new();
        loop {
            if self.pos >= self.data.len() { return Err("unterminated string".into()); }
            let c = self.data[self.pos];
            if c == b'"' { self.pos += 1; return Ok(s); }
            if c == b'\\' {
                self.pos += 1;
                if self.pos >= self.data.len() { return Err("unterminated escape".into()); }
                let e = self.data[self.pos];
                self.pos += 1;
                match e {
                    b'"' => s.push('"'),
                    b'\\' => s.push('\\'),
                    b'/' => s.push('/'),
                    b'b' => s.push('\u{0008}'),
                    b'f' => s.push('\u{000C}'),
                    b'n' => s.push('\n'),
                    b'r' => s.push('\r'),
                    b't' => s.push('\t'),
                    b'u' => {
                        let cp = self.parse_hex4()?;
                        if cp >= 0xD800 && cp <= 0xDBFF {
                            if self.pos + 1 < self.data.len() && self.data[self.pos] == b'\\' && self.data[self.pos+1] == b'u' {
                                self.pos += 2;
                                let low = self.parse_hex4()?;
                                if low >= 0xDC00 && low <= 0xDFFF {
                                    let code = 0x10000u32 + ((cp as u32 - 0xD800) << 10) + (low as u32 - 0xDC00);
                                    s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                                } else {
                                    s.push('\u{FFFD}');
                                    s.push('\u{FFFD}');
                                }
                            } else {
                                s.push('\u{FFFD}');
                            }
                        } else if cp >= 0xDC00 && cp <= 0xDFFF {
                            s.push('\u{FFFD}');
                        } else {
                            s.push(char::from_u32(cp as u32).unwrap_or('\u{FFFD}'));
                        }
                    }
                    _ => return Err(format!("bad escape \\{}", e as char)),
                }
            } else {
                let start = self.pos;
                while self.pos < self.data.len() && self.data[self.pos] != b'"' && self.data[self.pos] != b'\\' {
                    self.pos += 1;
                }
                s.push_str(std::str::from_utf8(&self.data[start..self.pos]).unwrap_or(""));
            }
        }
    }

    fn parse_hex4(&mut self) -> Result<u16, String> {
        if self.pos + 4 > self.data.len() { return Err("eof in hex".into()); }
        let hex = std::str::from_utf8(&self.data[self.pos..self.pos+4]).map_err(|_| "bad hex")?;
        self.pos += 4;
        u16::from_str_radix(hex, 16).map_err(|_| "bad hex".into())
    }

    fn parse_number(&mut self) -> Result<JsonValue, String> {
        let start = self.pos;
        if self.pos < self.data.len() && self.data[self.pos] == b'-' { self.pos += 1; }
        while self.pos < self.data.len() && self.data[self.pos].is_ascii_digit() { self.pos += 1; }
        let mut is_float = false;
        if self.pos < self.data.len() && self.data[self.pos] == b'.' {
            is_float = true; self.pos += 1;
            while self.pos < self.data.len() && self.data[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        if self.pos < self.data.len() && (self.data[self.pos] == b'e' || self.data[self.pos] == b'E') {
            is_float = true; self.pos += 1;
            if self.pos < self.data.len() && (self.data[self.pos] == b'+' || self.data[self.pos] == b'-') { self.pos += 1; }
            while self.pos < self.data.len() && self.data[self.pos].is_ascii_digit() { self.pos += 1; }
        }
        let s = std::str::from_utf8(&self.data[start..self.pos]).unwrap();
        if is_float { Ok(JsonValue::Float(s.parse::<f64>().unwrap())) }
        else { Ok(JsonValue::Int(s.parse::<i64>().unwrap())) }
    }

    fn parse_object(&mut self) -> Result<JsonValue, String> {
        self.pos += 1; // {
        let mut entries = Vec::new();
        self.skip_ws();
        if self.pos < self.data.len() && self.data[self.pos] == b'}' { self.pos += 1; return Ok(JsonValue::Object(entries)); }
        loop {
            self.skip_ws();
            let key = self.parse_string()?;
            self.skip_ws();
            if self.pos >= self.data.len() || self.data[self.pos] != b':' { return Err("expected :".into()); }
            self.pos += 1;
            let val = self.parse_value()?;
            entries.push((key, val));
            self.skip_ws();
            if self.pos < self.data.len() && self.data[self.pos] == b',' { self.pos += 1; } else { break; }
        }
        self.skip_ws();
        if self.pos < self.data.len() && self.data[self.pos] == b'}' { self.pos += 1; }
        Ok(JsonValue::Object(entries))
    }

    fn parse_array(&mut self) -> Result<JsonValue, String> {
        self.pos += 1; // [
        let mut items = Vec::new();
        self.skip_ws();
        if self.pos < self.data.len() && self.data[self.pos] == b']' { self.pos += 1; return Ok(JsonValue::Array(items)); }
        loop {
            let val = self.parse_value()?;
            items.push(val);
            self.skip_ws();
            if self.pos < self.data.len() && self.data[self.pos] == b',' { self.pos += 1; } else { break; }
        }
        self.skip_ws();
        if self.pos < self.data.len() && self.data[self.pos] == b']' { self.pos += 1; }
        Ok(JsonValue::Array(items))
    }
}

fn parse_json(s: &str) -> JsonValue {
    let mut p = Parser::new(s.as_bytes());
    p.parse_value().expect("json parse error")
}

// --- JSON Serialization (compact, spec escaping) ---
fn json_escape_str(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    for ch in s.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{0008}' => out.push_str("\\b"),
            '\u{000C}' => out.push_str("\\f"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => out.push(c),
        }
    }
    out
}

fn json_str(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    out.push_str(&json_escape_str(s));
    out.push('"');
    out
}

fn serialize_json(value: &JsonValue) -> String {
    match value {
        JsonValue::Null => "null".to_string(),
        JsonValue::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
        JsonValue::Int(n) => n.to_string(),
        JsonValue::Float(f) => {
            if *f == f.floor() && f.abs() < 1e15 { format!("{}", *f as i64) }
            else { format!("{}", f) }
        }
        JsonValue::Str(s) => json_str(s),
        JsonValue::Array(arr) => {
            let items: Vec<String> = arr.iter().map(|v| serialize_json(v)).collect();
            format!("[{}]", items.join(","))
        }
        JsonValue::Object(entries) => {
            let items: Vec<String> = entries.iter().map(|(k, v)| format!("{}:{}", json_str(k), serialize_json(v))).collect();
            format!("{{{}}}", items.join(","))
        }
    }
}

// --- Helpers for JsonValue access ---
fn obj_get<'a>(v: &'a JsonValue, key: &str) -> &'a JsonValue {
    if let JsonValue::Object(entries) = v {
        for (k, val) in entries {
            if k == key { return val; }
        }
    }
    &JsonValue::Null
}

fn get_str_val(v: &JsonValue) -> &str {
    if let JsonValue::Str(s) = v { s } else { "" }
}

fn get_int_val(v: &JsonValue) -> i64 {
    match v {
        JsonValue::Int(n) => *n,
        JsonValue::Float(f) => *f as i64,
        _ => 0,
    }
}

fn get_arr_val<'a>(v: &'a JsonValue) -> &'a [JsonValue] {
    if let JsonValue::Array(arr) = v { arr } else { &[] }
}

fn get_opt_str(v: &JsonValue) -> Option<String> {
    match v {
        JsonValue::Str(s) => Some(s.clone()),
        JsonValue::Null => None,
        _ => None,
    }
}

// --- HTTP Client ---
struct HttpResponse {
    status: u16,
    body: String,
}

fn http_post(host: &str, port: u16, path: &str, auth: &str, body: &str) -> HttpResponse {
    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(&addr).expect("connect failed");
    stream.set_read_timeout(Some(30000)).ok();
    stream.set_write_timeout(Some(30000)).ok();

    let mut req = format!("POST {} HTTP/1.1\r\n", path);
    req.push_str(&format!("Host: {}:{}\r\n", host, port));
    req.push_str(&format!("Authorization: Bearer {}\r\n", auth));
    req.push_str("Content-Type: application/json\r\n");
    req.push_str(&format!("Content-Length: {}\r\n", body.len()));
    req.push_str("\r\n");
    req.push_str(body);

    stream.write_all(req.as_bytes()).expect("write failed");
    stream.flush().expect("flush failed");

    let mut reader = BufReader::new(&mut stream);

    // Status line
    let mut status_line = String::new();
    reader.read_line(&mut status_line).unwrap();
    let parts: Vec<&str> = status_line.split_whitespace().collect();
    let status: u16 = parts[1].parse().unwrap();

    // Headers
    let mut content_length: usize = 0;
    loop {
        let mut line = String::new();
        reader.read_line(&mut line).unwrap();
        if line == "\r\n" || line == "\n" || line.is_empty() { break; }
        let lower = line.to_lowercase();
        if lower.starts_with("content-length:") {
            content_length = line["content-length:".len()..].trim().parse().unwrap();
        }
    }

    // Body
    let mut body_bytes = vec![0u8; content_length];
    let mut read_so_far = 0;
    while read_so_far < content_length {
        let n = reader.read(&mut body_bytes[read_so_far..]).unwrap();
        if n == 0 { break; }
        read_so_far += n;
    }
    body_bytes.truncate(read_so_far);

    HttpResponse { status, body: String::from_utf8_lossy(&body_bytes).to_string() }
}

// --- CSV Parser ---
fn parse_csv(data: &[u8]) -> Vec<Vec<String>> {
    let mut records: Vec<Vec<String>> = Vec::new();
    let mut i = 0;

    // Skip BOM
    if data.len() >= 3 && data[0] == 0xEF && data[1] == 0xBB && data[2] == 0xBF {
        i = 3;
    }

    while i < data.len() {
        // Skip trailing whitespace/CRLF
        let mut j = i;
        while j < data.len() && (data[j] == b'\r' || data[j] == b'\n' || data[j] == b' ' || data[j] == b'\t') {
            j += 1;
        }
        if j >= data.len() { break; }
        i = j;

        let (fields, next_i) = parse_csv_record(data, i);
        records.push(fields);
        i = next_i;
    }
    records
}

fn parse_csv_record(data: &[u8], mut i: usize) -> (Vec<String>, usize) {
    let mut fields: Vec<String> = Vec::new();

    loop {
        if i < data.len() && data[i] == b'"' {
            // Quoted field
            i += 1;
            let mut field = String::new();
            loop {
                if i >= data.len() { break; }
                if data[i] == b'"' {
                    if i + 1 < data.len() && data[i + 1] == b'"' {
                        field.push('"');
                        i += 2;
                    } else {
                        i += 1; // closing quote
                        break;
                    }
                } else {
                    let start = i;
                    while i < data.len() && data[i] != b'"' {
                        i += 1;
                    }
                    field.push_str(std::str::from_utf8(&data[start..i]).unwrap_or(""));
                }
            }
            fields.push(field);
        } else {
            // Unquoted field
            let start = i;
            while i < data.len() && data[i] != b',' && data[i] != b'\r' && data[i] != b'\n' {
                i += 1;
            }
            fields.push(String::from_utf8_lossy(&data[start..i]).to_string());
        }

        // Check for more fields or end of record
        if i < data.len() && data[i] == b',' {
            i += 1; // skip comma
        } else {
            // End of record - consume CRLF or LF
            if i < data.len() && data[i] == b'\r' {
                i += 1;
                if i < data.len() && data[i] == b'\n' { i += 1; }
            } else if i < data.len() && data[i] == b'\n' {
                i += 1;
            }
            break;
        }
    }

    (fields, i)
}

// --- Message structures ---
struct ToolCallData {
    id: String,
    call_type: String,
    name: String,
    arguments: String,
}

struct Msg {
    role: String,
    content: Option<String>,
    tool_calls: Option<Vec<ToolCallData>>,
    tool_call_id: Option<String>,
}

// --- Serialize message for request ---
fn serialize_msg(msg: &Msg) -> String {
    let mut s = String::new();
    s.push('{');
    s.push_str(&format!("\"role\":{}", json_str(&msg.role)));

    if msg.role == "assistant" {
        match &msg.content {
            Some(c) => s.push_str(&format!(",\"content\":{}", json_str(c))),
            None => s.push_str(",\"content\":null"),
        }
        if let Some(ref tcs) = msg.tool_calls {
            s.push_str(",\"tool_calls\":[");
            for (idx, tc) in tcs.iter().enumerate() {
                if idx > 0 { s.push(','); }
                s.push_str(&format!("{{\"id\":{},\"type\":{},\"function\":{{\"name\":{},\"arguments\":{}}}}}",
                    json_str(&tc.id), json_str(&tc.call_type), json_str(&tc.name), json_str(&tc.arguments)));
            }
            s.push(']');
        }
    } else if msg.role == "tool" {
        s.push_str(&format!(",\"tool_call_id\":{}", json_str(msg.tool_call_id.as_ref().unwrap())));
        s.push_str(&format!(",\"content\":{}", json_str(msg.content.as_ref().unwrap())));
    } else {
        // system or user
        s.push_str(&format!(",\"content\":{}", json_str(msg.content.as_ref().unwrap())));
    }

    s.push('}');
    s
}

fn build_request_body(model: &str, messages: &[Msg], tools_json: &str) -> String {
    let mut body = String::new();
    body.push('{');
    body.push_str(&format!("\"model\":{}", json_str(model)));
    body.push_str(",\"messages\":[");
    for (i, msg) in messages.iter().enumerate() {
        if i > 0 { body.push(','); }
        body.push_str(&serialize_msg(msg));
    }
    body.push_str("]");
    body.push_str(",\"tools\":");
    body.push_str(tools_json);
    body.push_str(",\"tool_choice\":\"auto\"");
    body.push('}');
    body
}

// --- Tool execution ---
fn execute_tool(name: &str, args_json: &str, inventory: &[Vec<String>], rates: &HashMap<String, i64>) -> String {
    match name {
        "inventory_lookup" => {
            let args = parse_json(args_json);
            let sku = get_str_val(obj_get(&args, "sku"));
            // Skip header row (index 0)
            for row in inventory.iter().skip(1) {
                if row.len() >= 5 && row[0] == sku {
                    let price: i64 = row[2].parse().unwrap_or(0);
                    let stock: i64 = row[4].parse().unwrap_or(0);
                    return format!("{{\"sku\":{},\"name\":{},\"price_cents\":{},\"currency\":{},\"stock\":{}}}",
                        json_str(&row[0]), json_str(&row[1]), price, json_str(&row[3]), stock);
                }
            }
            format!("{{\"error\":\"unknown sku: {}\"}}", json_escape_str(sku))
        }
        "convert_currency" => {
            let args = parse_json(args_json);
            let amount = get_int_val(obj_get(&args, "amount_cents"));
            let from = get_str_val(obj_get(&args, "from"));
            let to = get_str_val(obj_get(&args, "to"));
            let rate_from = *rates.get(from).unwrap_or(&1000000);
            let rate_to = *rates.get(to).unwrap_or(&1000000);
            // HALF_UP: (2 * amount * rate_to + rate_from) / (2 * rate_from)
            let numerator = 2i128 * (amount as i128) * (rate_to as i128) + (rate_from as i128);
            let denominator = 2i128 * (rate_from as i128);
            let converted = (numerator / denominator) as i64;
            format!("{{\"amount_cents\":{},\"currency\":{}}}", converted, json_str(to))
        }
        _ => {
            format!("{{\"error\":\"unknown tool: {}\"}}", json_escape_str(name))
        }
    }
}

// --- URL parsing ---
fn parse_url(url: &str) -> (String, u16, String) {
    // http://host:port/path
    let rest = if url.starts_with("http://") { &url[7..] }
               else if url.starts_with("https://") { &url[8..] }
               else { url };
    let (authority, path) = match rest.find('/') {
        Some(idx) => (&rest[..idx], &rest[idx..]),
        None => (rest, ""),
    };
    let (host, port) = match authority.rfind(':') {
        Some(idx) => {
            let p: u16 = authority[idx+1..].parse().unwrap_or(80);
            (authority[..idx].to_string(), p)
        }
        None => (authority.to_string(), 80),
    };
    (host, port, path.to_string())
}

// --- Main ---
fn main() {
    let args: Vec<String> = std::env::args().collect();
    let data_dir = &args[1];
    let base_url = &args[2];

    // Read task.json
    let task_text = fs::read_to_string(format!("{}/task.json", data_dir)).expect("read task.json");
    let task = parse_json(&task_text);
    let api_key = get_str_val(obj_get(&task, "api_key")).to_string();
    let model = get_str_val(obj_get(&task, "model")).to_string();
    let system = get_str_val(obj_get(&task, "system")).to_string();
    let user = get_str_val(obj_get(&task, "user")).to_string();
    let tools_json = serialize_json(obj_get(&task, "tools"));

    // Read inventory.csv
    let inv_data = fs::read(format!("{}/inventory.csv", data_dir)).expect("read inventory.csv");
    let inventory = parse_csv(&inv_data);

    // Read rates.json
    let rates_text = fs::read_to_string(format!("{}/rates.json", data_dir)).expect("read rates.json");
    let rates_val = parse_json(&rates_text);
    let mut rates: HashMap<String, i64> = HashMap::new();
    if let JsonValue::Object(entries) = obj_get(&rates_val, "rates") {
        for (k, v) in entries {
            rates.insert(k.clone(), get_int_val(v));
        }
    }

    // Parse URL
    let (host, port, base_path) = parse_url(base_url);
    let path = format!("{}/chat/completions", base_path);

    // Initial conversation
    let mut messages: Vec<Msg> = vec![
        Msg { role: "system".into(), content: Some(system), tool_calls: None, tool_call_id: None },
        Msg { role: "user".into(), content: Some(user), tool_calls: None, tool_call_id: None },
    ];

    let mut total_prompt: i64 = 0;
    let mut total_completion: i64 = 0;
    let mut total_total: i64 = 0;
    let mut num_requests: i64 = 0;

    loop {
        let body = build_request_body(&model, &messages, &tools_json);
        let resp = http_post(&host, port, &path, &api_key, &body);
        num_requests += 1;

        if resp.status != 200 {
            // Print error
            let err_json = parse_json(&resp.body);
            let err_msg = get_str_val(obj_get(obj_get(&err_json, "error"), "message"));
            println!("ERROR {} {}", resp.status, err_msg);
            process::exit(0);
        }

        let resp_json = parse_json(&resp.body);

        // Accumulate usage
        let usage = obj_get(&resp_json, "usage");
        total_prompt += get_int_val(obj_get(usage, "prompt_tokens"));
        total_completion += get_int_val(obj_get(usage, "completion_tokens"));
        total_total += get_int_val(obj_get(usage, "total_tokens"));

        // Get first choice
        let choices = get_arr_val(obj_get(&resp_json, "choices"));
        let choice = &choices[0];
        let finish_reason = get_str_val(obj_get(choice, "finish_reason"));
        let message = obj_get(choice, "message");

        if finish_reason == "tool_calls" {
            let content = get_opt_str(obj_get(message, "content"));
            if let Some(ref c) = content {
                println!("SAY {}", c);
            }

            let tool_calls = get_arr_val(obj_get(message, "tool_calls"));
            let mut tool_results: Vec<String> = Vec::new();
            let mut tc_data: Vec<ToolCallData> = Vec::new();

            for tc in tool_calls {
                let id = get_str_val(obj_get(tc, "id")).to_string();
                let func = obj_get(tc, "function");
                let name = get_str_val(obj_get(func, "name")).to_string();
                let arguments = get_str_val(obj_get(func, "arguments")).to_string();

                println!("CALL {} {}", id, name);

                let result = execute_tool(&name, &arguments, &inventory, &rates);
                println!("RESULT {} {}", id, result);
                tool_results.push(result);
                tc_data.push(ToolCallData {
                    id: id.clone(),
                    call_type: "function".to_string(),
                    name,
                    arguments,
                });
            }

            // Append assistant message
            messages.push(Msg {
                role: "assistant".into(),
                content: content.clone(),
                tool_calls: Some(tc_data),
                tool_call_id: None,
            });

            // Append tool response messages
            for (tc, result) in tool_calls.iter().zip(tool_results.iter()) {
                let id = get_str_val(obj_get(tc, "id")).to_string();
                messages.push(Msg {
                    role: "tool".into(),
                    content: Some(result.clone()),
                    tool_calls: None,
                    tool_call_id: Some(id),
                });
            }
        } else {
            // stop
            let content = get_str_val(obj_get(message, "content"));
            println!("FINAL {}", content);
            break;
        }
    }

    println!("USAGE prompt={} completion={} total={} requests={}",
        total_prompt, total_completion, total_total, num_requests);
}

