const B64: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

fn b64_encode(data: &[u8]) -> String {
    let mut s = String::new();
    let mut i = 0;
    while i < data.len() {
        let n = if i + 2 < data.len() {
            ((data[i] as u32) << 16) | ((data[i + 1] as u32) << 8) | (data[i + 2] as u32)
        } else if i + 1 < data.len() {
            ((data[i] as u32) << 16) | ((data[i + 1] as u32) << 8)
        } else {
            (data[i] as u32) << 16
        };
        s.push(B64[((n >> 18) & 63) as usize] as char);
        s.push(B64[((n >> 12) & 63) as usize] as char);
        if i + 1 < data.len() {
            s.push(B64[((n >> 6) & 63) as usize] as char);
        } else {
            s.push('=');
        }
        if i + 2 < data.len() {
            s.push(B64[(n & 63) as usize] as char);
        } else {
            s.push('=');
        }
        i += 3;
    }
    s
}

fn sha1(data: &[u8]) -> [u8; 20] {
    let mut h: [u32; 5] = [0x67452301, 0xEFCDAB89, 0x98BADCFE, 0x10325476, 0xC3D2E1F0];
    let msg_len = data.len();
    let bit_len = (msg_len as u64) * 8;
    let pad_len = if msg_len % 64 <= 55 {
        55 - msg_len % 64
    } else {
        119 - msg_len % 64
    };
    let mut padded = Vec::with_capacity(msg_len + 1 + pad_len + 8);
    padded.extend_from_slice(data);
    padded.push(0x80);
    for _ in 0..pad_len {
        padded.push(0);
    }
    padded.extend_from_slice(&bit_len.to_be_bytes());

    for block in padded.chunks(64) {
        let mut w = [0u32; 80];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([block[i * 4], block[i * 4 + 1], block[i * 4 + 2], block[i * 4 + 3]]);
        }
        for i in 16..80 {
            w[i] = (w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16]).rotate_left(1);
        }
        let mut a = h[0];
        let mut b = h[1];
        let mut c = h[2];
        let mut d = h[3];
        let mut e = h[4];
        for i in 0..80 {
            let (f, k) = if i < 20 {
                ((b & c) | ((!b) & d), 0x5A827999u32)
            } else if i < 40 {
                (b ^ c ^ d, 0x6ED9EBA1u32)
            } else if i < 60 {
                ((b & c) | (b & d) | (c & d), 0x8F1BBCDCu32)
            } else {
                (b ^ c ^ d, 0xCA62C1D6u32)
            };
            let temp = a.rotate_left(5).wrapping_add(f).wrapping_add(e).wrapping_add(k).wrapping_add(w[i]);
            e = d;
            d = c;
            c = b.rotate_left(30);
            b = a;
            a = temp;
        }
        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
    }
    let mut result = [0u8; 20];
    for i in 0..5 {
        let bytes = h[i].to_be_bytes();
        result[i * 4] = bytes[0];
        result[i * 4 + 1] = bytes[1];
        result[i * 4 + 2] = bytes[2];
        result[i * 4 + 3] = bytes[3];
    }
    result
}

fn random_bytes(n: usize) -> Vec<u8> {
    let mut file = std::fs::File::open("/dev/urandom").expect("open urandom");
    let mut buf = vec![0u8; n];
    file.read_exact(&mut buf).expect("read urandom");
    buf
}

fn parse_url(url: &str) -> (String, u16, String) {
    let rest = url.strip_prefix("ws://").expect("bad url");
    let slash_pos = rest.find('/').unwrap_or(rest.len());
    let host_port = &rest[..slash_pos];
    let path = if slash_pos < rest.len() { &rest[slash_pos..] } else { "/" };
    let colon_pos = host_port.rfind(':').expect("no port");
    let host = host_port[..colon_pos].to_string();
    let port: u16 = host_port[colon_pos + 1..].parse().expect("bad port");
    (host, port, path.to_string())
}

fn compute_accept(key: &str) -> String {
    let input = format!("{}258EAFA5-E914-47DA-95CA-C5AB0DC85B11", key);
    let digest = sha1(input.as_bytes());
    b64_encode(&digest)
}

fn read_frame<R: Read>(reader: &mut R) -> Option<(bool, u8, Vec<u8>)> {
    let mut hdr = [0u8; 2];
    if reader.read_exact(&mut hdr).is_err() {
        return None;
    }
    let fin = (hdr[0] & 0x80) != 0;
    let opcode = hdr[0] & 0x0F;
    let masked = (hdr[1] & 0x80) != 0;
    let len7 = hdr[1] & 0x7F;
    let payload_len: u64 = if len7 == 126 {
        let mut b = [0u8; 2];
        if reader.read_exact(&mut b).is_err() { return None; }
        u16::from_be_bytes(b) as u64
    } else if len7 == 127 {
        let mut b = [0u8; 8];
        if reader.read_exact(&mut b).is_err() { return None; }
        u64::from_be_bytes(b)
    } else {
        len7 as u64
    };
    let mut mask_key = [0u8; 4];
    if masked {
        if reader.read_exact(&mut mask_key).is_err() { return None; }
    }
    let mut payload = vec![0u8; payload_len as usize];
    if payload_len > 0 {
        if reader.read_exact(&mut payload).is_err() { return None; }
    }
    if masked {
        for i in 0..payload.len() {
            payload[i] ^= mask_key[i & 3];
        }
    }
    Some((fin, opcode, payload))
}

fn send_frame<W: Write>(writer: &mut W, opcode: u8, payload: &[u8]) {
    let mut frame = Vec::new();
    frame.push(0x80 | opcode);
    let len = payload.len();
    if len <= 125 {
        frame.push(0x80 | len as u8);
    } else if len <= 65535 {
        frame.push(0x80 | 126);
        frame.extend_from_slice(&(len as u16).to_be_bytes());
    } else {
        frame.push(0x80 | 127);
        frame.extend_from_slice(&(len as u64).to_be_bytes());
    }
    let key = loop {
        let k = random_bytes(4);
        if k != [0u8; 4] { break k; }
    };
    frame.extend_from_slice(&key);
    for (i, &b) in payload.iter().enumerate() {
        frame.push(b ^ key[i & 3]);
    }
    writer.write_all(&frame).unwrap();
    writer.flush().unwrap();
}

fn handle_session(url: &str) {
    let (host, port, path) = parse_url(url);
    let stream = match TcpStream::connect(format!("{}:{}", host, port)) {
        Ok(s) => s,
        Err(_) => return,
    };
    let mut reader = BufReader::new(stream.try_clone().unwrap());
    let mut writer = stream;

    let key_bytes = random_bytes(16);
    let ws_key = b64_encode(&key_bytes);

    let request = format!(
        "GET {} HTTP/1.1\r\nHost: {}:{}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: {}\r\n\r\n",
        path, host, port, ws_key
    );
    writer.write_all(request.as_bytes()).unwrap();
    writer.flush().unwrap();

    let mut status_line = String::new();
    if reader.read_line(&mut status_line).unwrap() == 0 {
        return;
    }
    let status_line_t = status_line.trim_end_matches("\r\n");
    let parts: Vec<&str> = status_line_t.splitn(3, ' ').collect();
    let status_code: u16 = parts[1].parse().unwrap_or(0);
    let reason_phrase = if parts.len() >= 3 { parts[2] } else { "" };

    let mut headers: Vec<(String, String)> = Vec::new();
    loop {
        let mut line = String::new();
        let n = reader.read_line(&mut line).unwrap();
        if n == 0 { break; }
        if line == "\r\n" || line == "\n" { break; }
        if let Some(colon) = line.find(':') {
            let name = line[..colon].trim().to_lowercase();
            let value = line[colon + 1..].trim().to_string();
            headers.push((name, value));
        }
    }

    if status_code != 101 {
        println!("handshake failed: {} {}", status_code, reason_phrase);
        return;
    }

    let expected_accept = compute_accept(&ws_key);
    let accept_ok = headers.iter().any(|(name, value)| {
        name == "sec-websocket-accept" && value == expected_accept
    });
    if !accept_ok {
        println!("handshake failed: bad Sec-WebSocket-Accept");
        return;
    }

    let mut sent_close = false;
    let mut expecting_sha1 = false;
    let mut frag_opcode: u8 = 0;
    let mut frag_payload: Vec<u8> = Vec::new();

    loop {
        let (fin, opcode, payload) = match read_frame(&mut reader) {
            Some(f) => f,
            None => break,
        };

        match opcode {
            0x9 => {
                send_frame(&mut writer, 0xA, &payload);
            }
            0xA => {}
            0x8 => {
                let code = if payload.len() >= 2 {
                    u16::from_be_bytes([payload[0], payload[1]])
                } else {
                    1005
                };
                let reason = if payload.len() > 2 {
                    String::from_utf8_lossy(&payload[2..]).to_string()
                } else {
                    String::new()
                };
                if reason.is_empty() {
                    println!("closed {}", code);
                } else {
                    println!("closed {} {}", code, reason);
                }
                if !sent_close {
                    let cp = code.to_be_bytes().to_vec();
                    send_frame(&mut writer, 0x8, &cp);
                }
                break;
            }
            0x0 => {
                frag_payload.extend_from_slice(&payload);
                if fin {
                    process_message(frag_opcode, &frag_payload, &mut writer, &mut sent_close, &mut expecting_sha1);
                }
            }
            0x1 | 0x2 => {
                if fin {
                    process_message(opcode, &payload, &mut writer, &mut sent_close, &mut expecting_sha1);
                } else {
                    frag_opcode = opcode;
                    frag_payload = payload;
                }
            }
            _ => {}
        }
    }
}

fn process_message(opcode: u8, payload: &[u8], writer: &mut TcpStream, sent_close: &mut bool, expecting_sha1: &mut bool) {
    if *expecting_sha1 {
        let digest = sha1(payload);
        let hex: String = digest.iter().map(|b| format!("{:02x}", b)).collect();
        println!("SHA1 {} -> {}", payload.len(), hex);
        send_frame(writer, 0x1, hex.as_bytes());
        *expecting_sha1 = false;
        return;
    }

    if opcode == 0x1 {
        let cmd = String::from_utf8_lossy(payload).to_string();

        if cmd == "BYE" {
            send_frame(writer, 0x8, &[0x03, 0xE8]);
            *sent_close = true;
        } else if cmd.starts_with("ADD ") {
            let params = &cmd[4..];
            let parts: Vec<&str> = params.split_whitespace().collect();
            let a: i64 = parts[0].parse().unwrap();
            let b: i64 = parts[1].parse().unwrap();
            let sum = a + b;
            println!("{} -> {}", cmd, sum);
            send_frame(writer, 0x1, sum.to_string().as_bytes());
        } else if cmd.starts_with("REV ") {
            let text = &cmd[4..];
            let reversed: String = text.chars().rev().collect();
            println!("{} -> {}", cmd, reversed);
            send_frame(writer, 0x1, reversed.as_bytes());
        } else if cmd == "SHA1" {
            *expecting_sha1 = true;
        }
    }
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    for (idx, url) in args.iter().enumerate() {
        println!("session {}", idx + 1);
        handle_session(url);
    }
    std::process::exit(0);
}

