                    println!("closed {}", code);
                } else {
                    println!("closed {} {}", code, reason);
                }
                if !sent_close {
                    let cp = code.to_be_bytes().to_vec();
                    send_frame(&mut writer, 0x8, &cp);
                }
                break;
            }
            0x0 => {
                frag_payload.extend_from_slice(&payload);
                if fin {
                    process_message(frag_opcode, &frag_payload, &mut writer, &mut sent_close, &mut expecting_sha1);
                }
            }
            0x1 | 0x2 => {
                if fin {
                    process_message(opcode, &payload, &mut writer, &mut sent_close, &mut expecting_sha1);
                } else {
                    frag_opcode = opcode;
                    frag_payload = payload;
                }
            }
            _ => {}
        }
    }
}

fn process_message(opcode: u8, payload: &[u8], writer: &mut TcpStream, sent_close: &mut bool, expecting_sha1: &mut bool) {
    if *expecting_sha1 {
        let digest = sha1(payload);
        let hex: String = digest.iter().map(|b| format!("{:02x}", b)).collect();
        println!("SHA1 {} -> {}", payload.len(), hex);
        send_frame(writer, 0x1, hex.as_bytes());
        *expecting_sha1 = false;
        return;
    }

    if opcode == 0x1 {
        let cmd = String::from_utf8_lossy(payload).to_string();

        if cmd == "BYE" {
            send_frame(writer, 0x8, &[0x03, 0xE8]);
            *sent_close = true;
        } else if cmd.starts_with("ADD ") {
            let params = &cmd[4..];
            let parts: Vec<&str> = params.split_whitespace().collect();
            let a: i64 = parts[0].parse().unwrap();
            let b: i64 = parts[1].parse().unwrap();
            let sum = a + b;
            println!("{} -> {}", cmd, sum);
            send_frame(writer, 0x1, sum.to_string().as_bytes());
        } else if cmd.starts_with("REV ") {
            let text = &cmd[4..];
            let reversed: String = text.chars().rev().collect();
            println!("{} -> {}", cmd, reversed);
            send_frame(writer, 0x1, reversed.as_bytes());
        } else if cmd == "SHA1" {
            *expecting_sha1 = true;
        }
    }
}

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    for (idx, url) in args.iter().enumerate() {
        println!("session {}", idx + 1);
        handle_session(url);
    }
    std::process::exit(0);
}

use std::env;
use std::fs;
use std::path::Path;

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = &args[1];

    let mut files: Vec<String> = Vec::new();
    for entry in fs::read_dir(dir).unwrap() {
        let entry = entry.unwrap();
        let name = entry.file_name().to_string_lossy().to_string();
        if name.ends_with(".wav") {
            files.push(name);
        }
    }
    files.sort();

    let low_freqs: [f64; 4] = [697.0, 770.0, 852.0, 941.0];
    let high_freqs: [f64; 4] = [1209.0, 1336.0, 1477.0, 1633.0];

    let keypad: [[char; 4]; 4] = [
        ['1', '2', '3', 'A'],
        ['4', '5', '6', 'B'],
        ['7', '8', '9', 'C'],
        ['*', '0', '#', 'D'],
    ];

    let mut first_output = true;

    for name in &files {
        let path = Path::new(dir).join(name);
        let data = fs::read(&path).unwrap();

        let result = parse_wav(&data);

        match result {
            Some((rate, channels, samples)) => {
                if !first_output {
                    println!();
                }
                first_output = false;

                let n = rate / 50;
                let blocks = samples.len() / n;

                println!("{}: {} Hz, {} ch, {} blocks", name, rate, channels, blocks);

                let mut labels: Vec<Option<char>> = Vec::with_capacity(blocks);

                for i in 0..blocks {
                    let start = i * n;
                    let block = &samples[start..start + n];

                    // Energy check
                    let e: i64 = block.iter().map(|&x| (x as i64) * (x as i64)).sum();

                    if e < 1000000i64 * n as i64 {
                        labels.push(None);
                        continue;
                    }

                    let e_f = e as f64;
                    let n_f = n as f64;

                    let mut r_low = [0.0f64; 4];
                    let mut r_high = [0.0f64; 4];

                    for fi in 0..4 {
                        r_low[fi] = goertzel(block, low_freqs[fi], rate as f64, n_f, e_f);
                        r_high[fi] = goertzel(block, high_freqs[fi], rate as f64, n_f, e_f);
                    }

                    let mut best_low_idx = 0usize;
                    let mut best_low_r = r_low[0];
                    for fi in 1..4 {
                        if r_low[fi] > best_low_r {
                            best_low_r = r_low[fi];
                            best_low_idx = fi;
                        }
                    }

                    let mut best_high_idx = 0usize;
                    let mut best_high_r = r_high[0];
                    for fi in 1..4 {
                        if r_high[fi] > best_high_r {
                            best_high_r = r_high[fi];
                            best_high_idx = fi;
                        }
                    }

                    if best_low_r >= 0.1 && best_high_r >= 0.1 && best_low_r + best_high_r >= 0.6 {
                        labels.push(Some(keypad[best_low_idx][best_high_idx]));
                    } else {
                        labels.push(None);
                    }
                }

                // Bridging: use original labels from step 3
                let original_labels = labels.clone();
                let mut bridged_labels = labels.clone();
                if blocks >= 3 {
                    for i in 1..blocks - 1 {
                        if original_labels[i].is_none() {
                            if original_labels[i - 1].is_some()
                                && original_labels[i + 1].is_some()
                                && original_labels[i - 1] == original_labels[i + 1]
                            {
                                bridged_labels[i] = original_labels[i - 1];
                            }
                        }
                    }
                }

                // Events: maximal runs of same digit >= 2 blocks
                let mut events: Vec<(char, usize, usize)> = Vec::new();
                let mut i = 0;
                while i < blocks {
                    if let Some(d) = bridged_labels[i] {
                        let start = i;
                        while i < blocks && bridged_labels[i] == Some(d) {
                            i += 1;
                        }
                        let end = i;
                        if end - start >= 2 {
                            events.push((d, start * 20, end * 20));
                        }
                    } else {
                        i += 1;
                    }
                }

                let mut all_digits = String::new();
                for (d, s, e) in &events {
                    println!("{} {} {}", d, s, e);
                    all_digits.push(*d);
                }
                println!("digits: {}", all_digits);
            }
            None => {
                if !first_output {
                    println!();
                }
                first_output = false;
                println!("{}: unsupported", name);
            }
        }
    }
}

fn goertzel(block: &[i16], freq: f64, rate: f64, n_f: f64, e_f: f64) -> f64 {
    let c = 2.0 * (2.0 * std::f64::consts::PI * freq / rate).cos();
    let mut s1 = 0.0f64;
    let mut s2 = 0.0f64;
    for &x in block {
        let s = x as f64 + c * s1 - s2;
        s2 = s1;
        s1 = s;
    }
    let p = s1 * s1 + s2 * s2 - c * s1 * s2;
    2.0 * p / (n_f * e_f)
}

fn parse_wav(data: &[u8]) -> Option<(usize, usize, Vec<i16>)> {
    if data.len() < 12 {
        return None;
    }
    if &data[0..4] != b"RIFF" || &data[8..12] != b"WAVE" {
        return None;
    }

    let mut pos = 12;
    let mut fmt_tag: u16 = 0;
    let mut bits_per_sample: u16 = 0;
    let mut channels: usize = 0;
    let mut rate: usize = 0;
    let mut data_bytes: &[u8] = &[];

    while pos + 8 <= data.len() {
        let chunk_id = &data[pos..pos + 4];
        let chunk_size =
            u32::from_le_bytes([data[pos + 4], data[pos + 5], data[pos + 6], data[pos + 7]])
                as usize;
        let body_start = pos + 8;
        let body_end = body_start + chunk_size;

        if body_end > data.len() {
            break;
        }

        if chunk_id == b"fmt " {
            if chunk_size < 16 {
                return None;
            }
            let body = &data[body_start..body_end];
            fmt_tag = u16::from_le_bytes([body[0], body[1]]);
            channels = u16::from_le_bytes([body[2], body[3]]) as usize;
            rate =
                u32::from_le_bytes([body[4], body[5], body[6], body[7]]) as usize;
            bits_per_sample = u16::from_le_bytes([body[10], body[11]]);

            if fmt_tag == 0xFFFE && chunk_size >= 26 {
                fmt_tag = u16::from_le_bytes([body[24], body[25]]);
            }
        } else if chunk_id == b"data" {
            data_bytes = &data[body_start..body_end];
        }

        pos = body_end + (if chunk_size % 2 == 1 { 1 } else { 0 });
    }

    if fmt_tag != 1 || bits_per_sample != 16 {
        return None;
    }
    if channels != 1 && channels != 2 {
        return None;
    }
    if rate != 8000 && rate != 16000 {
        return None;
    }

    let frame_size = 2 * channels;
    let num_frames = data_bytes.len() / frame_size;
    let mut samples = Vec::with_capacity(num_frames);

    for i in 0..num_frames {
        let offset = i * frame_size;
        let sample = i16::from_le_bytes([data_bytes[offset], data_bytes[offset + 1]]);
        samples.push(sample);
    }

    Some((rate, channels, samples))
}

