import java.io.*;
import java.nio.file.*;
import java.nio.ByteBuffer;
import java.time.*;
import java.util.*;

public class Main {

    static class TzifData {
        long[] transTimes;
        int[] transTypes;
        int[] typeOffsets; // UTC offsets (add to UTC to get local)
        boolean[] typeIsDst;
        String[] typeAbbrs;

        // POSIX TZ parsed
        String stdName;
        int stdPosixOff; // POSIX offset (add to local to get UTC)
        String dstName;
        int dstPosixOff;
        boolean hasDst;
        boolean hasDstRule;
        int startMonth, startWeek, startDay, startTimeSec;
        int endMonth, endWeek, endDay, endTimeSec;

        int getOffset(long t) {
            if (transTimes.length == 0) {
                return posixOffset(t);
            }
            if (t < transTimes[0]) {
                return typeOffsets[0];
            }
            if (t >= transTimes[transTimes.length - 1]) {
                return posixOffset(t);
            }
            // Binary search
            int lo = 0, hi = transTimes.length - 1;
            while (lo < hi) {
                int mid = (lo + hi + 1) / 2;
                if (transTimes[mid] <= t) lo = mid;
                else hi = mid - 1;
            }
            return typeOffsets[transTypes[lo]];
        }

        String getAbbr(long t) {
            if (transTimes.length == 0) {
                return posixAbbr(t);
            }
            if (t < transTimes[0]) {
                return typeAbbrs[0];
            }
            if (t >= transTimes[transTimes.length - 1]) {
                return posixAbbr(t);
            }
            int lo = 0, hi = transTimes.length - 1;
            while (lo < hi) {
                int mid = (lo + hi + 1) / 2;
                if (transTimes[mid] <= t) lo = mid;
                else hi = mid - 1;
            }
            return typeAbbrs[transTypes[lo]];
        }

        int posixOffset(long t) {
            if (!hasDst || !hasDstRule) {
                return -stdPosixOff;
            }
            int year = yearOfUtc(t);
            long startUtc = computeTransitionUtc(year, true);
            long endUtc = computeTransitionUtc(year, false);
            boolean dst;
            if (startUtc < endUtc) {
                dst = (t >= startUtc && t < endUtc);
            } else if (startUtc > endUtc) {
                dst = (t >= startUtc || t < endUtc);
            } else {
                dst = false;
            }
            return dst ? -dstPosixOff : -stdPosixOff;
        }

        String posixAbbr(long t) {
            if (!hasDst || !hasDstRule) {
                return stdName;
            }
            int year = yearOfUtc(t);
            long startUtc = computeTransitionUtc(year, true);
            long endUtc = computeTransitionUtc(year, false);
            boolean dst;
            if (startUtc < endUtc) {
                dst = (t >= startUtc && t < endUtc);
            } else if (startUtc > endUtc) {
                dst = (t >= startUtc || t < endUtc);
            } else {
                dst = false;
            }
            return dst ? dstName : stdName;
        }

        int yearOfUtc(long t) {
            // Convert Unix time to year
            // t could be negative
            long days = Math.floorDiv(t, 86400);
            return LocalDate.ofEpochDay(days).getYear();
        }

        long computeTransitionUtc(int year, boolean isStart) {
            int month = isStart ? startMonth : endMonth;
            int week = isStart ? startWeek : endWeek;
            int dow = isStart ? startDay : endDay; // 0=Sun...6=Sat
            int timeSec = isStart ? startTimeSec : endTimeSec;

            LocalDate firstOfMonth = LocalDate.of(year, month, 1);
            // Java: DayOfWeek.MONDAY=1...SUNDAY=7
            // We need: 0=Sun, 1=Mon, ..., 6=Sat
            int firstDow = firstOfMonth.getDayOfWeek().getValue() % 7; // Sun=0, Mon=1, ..., Sat=6

            int firstOccurrence = 1 + ((dow - firstDow + 7) % 7);

            int day;
            if (week <= 4) {
                day = firstOccurrence + (week - 1) * 7;
            } else {
                int lastDay = firstOfMonth.lengthOfMonth();
                day = firstOccurrence + 4 * 7;
                while (day > lastDay) day -= 7;
            }

            long midnightUtc = LocalDate.of(year, month, day).toEpochDay() * 86400;
            int posixOff = isStart ? stdPosixOff : dstPosixOff;
            return midnightUtc + timeSec + posixOff;
        }
    }

    static String formatOffset(int utcOffsetSec) {
        // utcOffsetSec is what you add to UTC to get local
        // Format: +HH:MM or -HH:MM, with :SS if seconds != 0
        int totalSec = Math.abs(utcOffsetSec);
        int sign = utcOffsetSec >= 0 ? 1 : -1;
        int h = totalSec / 3600;
        int m = (totalSec % 3600) / 60;
        int s = totalSec % 60;
        String signStr = sign >= 0 ? "+" : "-";
        if (s != 0) {
            return String.format("%s%02d:%02d:%02d", signStr, h, m, s);
        } else {
            return String.format("%s%02d:%02d", signStr, h, m);
        }
    }

    static String formatLocal(long unixTime, int utcOffset) {
        long localSec = unixTime + utcOffset;
        // Convert localSec to date-time string (treating as UTC)
        LocalDate date = LocalDate.ofEpochDay(Math.floorDiv(localSec, 86400));
        int timeOfDay = (int) Math.floorMod(localSec, 86400);
        int h = timeOfDay / 3600;
        int m = (timeOfDay % 3600) / 60;
        int s = timeOfDay % 60;
        return String.format("%04d-%02d-%02dT%02d:%02d:%02d", date.getYear(), date.getMonthValue(), date.getDayOfMonth(), h, m, s);
    }

    static long parseWallClock(String s) {
        // Parse YYYY-MM-DDTHH:MM:SS as if UTC, return seconds since epoch
        // s is like "2050-03-27T01:30:00"
        int year = Integer.parseInt(s.substring(0, 4));
        int month = Integer.parseInt(s.substring(5, 7));
        int day = Integer.parseInt(s.substring(8, 10));
        int h = Integer.parseInt(s.substring(11, 13));
        int m = Integer.parseInt(s.substring(14, 16));
        int sec = Integer.parseInt(s.substring(17, 19));
        LocalDate date = LocalDate.of(year, month, day);
        return date.toEpochDay() * 86400 + h * 3600 + m * 60 + sec;
    }

    static long parsePosixOffset(String s) {
        // Parse [+|-]hh[:mm[:ss]], return seconds
        // This is the POSIX offset (add to local to get UTC)
        int idx = 0;
        int sign = 1;
        if (s.charAt(0) == '+') { idx = 1; }
        else if (s.charAt(0) == '-') { sign = -1; idx = 1; }

        int h = 0, m = 0, sec = 0;
        // Parse hours
        int hEnd = idx;
        while (hEnd < s.length() && s.charAt(hEnd) != ':') hEnd++;
        h = Integer.parseInt(s.substring(idx, hEnd));

        if (hEnd < s.length()) {
            // Parse minutes
            idx = hEnd + 1;
            int mEnd = idx;
            while (mEnd < s.length() && s.charAt(mEnd) != ':') mEnd++;
            m = Integer.parseInt(s.substring(idx, mEnd));

            if (mEnd < s.length()) {
                // Parse seconds
                sec = Integer.parseInt(s.substring(mEnd + 1));
            }
        }

        return sign * (h * 3600 + m * 60 + sec);
    }

    static int parseTime(String s) {
        // Parse [+|-]hh[:mm[:ss]], default 02:00:00
        // Returns seconds
        return (int) parsePosixOffset(s);
    }

    static String[] parsePosixTz(String tz) {
        // Parse POSIX TZ string
        // Returns components
        // Actually, let me parse it into the TzifData fields directly
        return null; // placeholder
    }

    static void parsePosixInto(TzifData data, String tz) {
        int i = 0;
        int len = tz.length();

        // Parse std name
        if (i < len && tz.charAt(i) == '<') {
            int end = tz.indexOf('>', i);
            data.stdName = tz.substring(i + 1, end);
            i = end + 1;
        } else {
            int start = i;
            while (i < len && Character.isLetter(tz.charAt(i))) i++;
            data.stdName = tz.substring(start, i);
        }

        // Parse std offset
        data.stdPosixOff = (int) parsePosixOffsetFrom(tz, i);
        i = skipOffset(tz, i);

        // Check if there's a DST part
        if (i >= len) {
            data.hasDst = false;
            data.hasDstRule = false;
            return;
        }

        // Parse dst name
        if (tz.charAt(i) == '<') {
            int end = tz.indexOf('>', i);
            data.dstName = tz.substring(i + 1, end);
            i = end + 1;
        } else {
            int start = i;
            while (i < len && Character.isLetter(tz.charAt(i))) i++;
            data.dstName = tz.substring(start, i);
        }
        data.hasDst = true;

        // Check if there's a DST offset
        if (i < len && (tz.charAt(i) == '+' || tz.charAt(i) == '-' || Character.isDigit(tz.charAt(i)))) {
            data.dstPosixOff = (int) parsePosixOffsetFrom(tz, i);
            i = skipOffset(tz, i);
        } else {
            data.dstPosixOff = data.stdPosixOff - 3600; // default: std + 1 hour DST
        }

        // Check for transition rules
        if (i < len && tz.charAt(i) == ',') {
            i++; // skip comma
            data.hasDstRule = true;
            // Parse start rule
            i = parseRule(tz, i, data, true);
            i++; // skip comma
            // Parse end rule
            i = parseRule(tz, i, data, false);
        } else {
            data.hasDstRule = false;
        }
    }

    static long parsePosixOffsetFrom(String s, int idx) {
        int sign = 1;
        if (idx < s.length() && s.charAt(idx) == '+') { idx++; }
        else if (idx < s.length() && s.charAt(idx) == '-') { sign = -1; idx++; }

        int h = 0, m = 0, sec = 0;
        int hEnd = idx;
        while (hEnd < s.length() && s.charAt(hEnd) != ':' && !Character.isLetter(s.charAt(hEnd)) && s.charAt(hEnd) != ',' && s.charAt(hEnd) != '<') hEnd++;
        h = Integer.parseInt(s.substring(idx, hEnd));
        idx = hEnd;

        if (idx < s.length() && s.charAt(idx) == ':') {
            idx++;
            int mEnd = idx;
            while (mEnd < s.length() && s.charAt(mEnd) != ':' && !Character.isLetter(s.charAt(mEnd)) && s.charAt(mEnd) != ',' && s.charAt(mEnd) != '<') mEnd++;
            m = Integer.parseInt(s.substring(idx, mEnd));
            idx = mEnd;

            if (idx < s.length() && s.charAt(idx) == ':') {
                idx++;
                int sEnd = idx;
                while (sEnd < s.length() && !Character.isLetter(s.charAt(sEnd)) && s.charAt(sEnd) != ',' && s.charAt(sEnd) != '<') sEnd++;
                sec = Integer.parseInt(s.substring(idx, sEnd));
            }
        }

        return sign * (h * 3600 + m * 60 + sec);
    }

    static int skipOffset(String s, int idx) {
        if (idx < s.length() && (s.charAt(idx) == '+' || s.charAt(idx) == '-')) idx++;
        // Skip digits and colons
        while (idx < s.length() && (Character.isDigit(s.charAt(idx)) || s.charAt(idx) == ':')) idx++;
        return idx;
    }

    static int parseRule(String s, int idx, TzifData data, boolean isStart) {
        // Parse Mm.w.d[/time]
        // s.charAt(idx) should be 'M'
        idx++; // skip 'M'

        int mEnd = idx;
        while (mEnd < s.length() && Character.isDigit(s.charAt(mEnd))) mEnd++;
        int month = Integer.parseInt(s.substring(idx, mEnd));
        idx = mEnd + 1; // skip '.'

        int wEnd = idx;
        while (wEnd < s.length() && Character.isDigit(s.charAt(wEnd))) wEnd++;
        int week = Integer.parseInt(s.substring(idx, wEnd));
        idx = wEnd + 1; // skip '.'

        int dEnd = idx;
        while (dEnd < s.length() && Character.isDigit(s.charAt(dEnd))) dEnd++;
        int day = Integer.parseInt(s.substring(idx, dEnd));
        idx = dEnd;

        int timeSec = 2 * 3600; // default 02:00:00
        if (idx < s.length() && s.charAt(idx) == '/') {
            idx++; // skip '/'
            timeSec = (int) parseTimeFrom(s, idx);
            idx = skipTime(s, idx);
        }

        if (isStart) {
            data.startMonth = month;
            data.startWeek = week;
            data.startDay = day;
            data.startTimeSec = timeSec;
        } else {
            data.endMonth = month;
            data.endWeek = week;
            data.endDay = day;
            data.endTimeSec = timeSec;
        }

        return idx;
    }

    static long parseTimeFrom(String s, int idx) {
        int sign = 1;
        if (idx < s.length() && s.charAt(idx) == '+') { idx++; }
        else if (idx < s.length() && s.charAt(idx) == '-') { sign = -1; idx++; }

        int h = 0, m = 0, sec = 0;
        int hEnd = idx;
        while (hEnd < s.length() && Character.isDigit(s.charAt(hEnd))) hEnd++;
        h = Integer.parseInt(s.substring(idx, hEnd));
        idx = hEnd;

        if (idx < s.length() && s.charAt(idx) == ':') {
            idx++;
            int mEnd = idx;
            while (mEnd < s.length() && Character.isDigit(s.charAt(mEnd))) mEnd++;
            m = Integer.parseInt(s.substring(idx, mEnd));
            idx = mEnd;

            if (idx < s.length() && s.charAt(idx) == ':') {
                idx++;
                int sEnd = idx;
                while (sEnd < s.length() && Character.isDigit(s.charAt(sEnd))) sEnd++;
                sec = Integer.parseInt(s.substring(idx, sEnd));
            }
        }

        return sign * (h * 3600 + m * 60 + sec);
    }

    static int skipTime(String s, int idx) {
        if (idx < s.length() && (s.charAt(idx) == '+' || s.charAt(idx) == '-')) idx++;
        while (idx < s.length() && (Character.isDigit(s.charAt(idx)) || s.charAt(idx) == ':')) idx++;
        return idx;
    }

    static TzifData loadTzif(String path) throws Exception {
        byte[] bytes = Files.readAllBytes(Paths.get(path));
        ByteBuffer buf = ByteBuffer.wrap(bytes);

        // Skip first header and data block
        // First header: 44 bytes
        buf.position(0);
        byte[] magic = new byte[4];
        buf.get(magic); // "TZif"
        byte version = buf.get();
        buf.position(44); // skip to end of first header

        // Read first header counts
        int isutcnt1 = buf.getInt();
        int isstdcnt1 = buf.getInt();
        int leapcnt1 = buf.getInt();
        int timecnt1 = buf.getInt();
        int typecnt1 = buf.getInt();
        int charcnt1 = buf.getInt();

        // Skip first data block
        int firstDataSize = timecnt1 * 4 + timecnt1 * 1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1;
        buf.position(buf.position() + firstDataSize);

        // Second header
        buf.position(buf.position() + 44); // skip second header (we'll re-read counts from after)
        // Actually, let me re-read the second header properly

        // Hmm, let me redo this. After the first data block, there's the second header.
        // The second header is also 44 bytes: magic + version + 15 unused + 6 counts

        // Wait, I already skipped 44 bytes for the first header. Then I read 6 ints (24 bytes). So I'm at position 44+24=68? No...

        // Let me redo:
        // Position 0: start of file
        // 44 bytes: first header (magic[4] + version[1] + unused[15] + 6*int32[24]) = 44
        // Then first data block
        // Then second header (44 bytes)
        // Then second data block
        // Then footer

        // Let me restart parsing:
        buf.position(0);
        // First header
        buf.position(4 + 1 + 15); // skip magic, version, unused
        isutcnt1 = buf.getInt();
        isstdcnt1 = buf.getInt();
        leapcnt1 = buf.getInt();
        timecnt1 = buf.getInt();
        typecnt1 = buf.getInt();
        charcnt1 = buf.getInt();
        // Now at position 44

        // First data block
        int pos = 44;
        pos += timecnt1 * 4; // transition times
        pos += timecnt1; // type indices
        pos += typecnt1 * 6; // type records
        pos += charcnt1; // abbreviations
        pos += leapcnt1 * 8; // leap seconds (4+4)
        pos += isstdcnt1;
        pos += isutcnt1;

        // Second header at position pos
        buf.position(pos + 4 + 1 + 15); // skip magic, version, unused of second header
        int isutcnt2 = buf.getInt();
        int isstdcnt2 = buf.getInt();
        int leapcnt2 = buf.getInt();
        int timecnt2 = buf.getInt();
        int typecnt2 = buf.getInt();
        int charcnt2 = buf.getInt();

        // Second data block starts at pos + 44
        int dataPos = pos + 44;

        // Read transition times (64-bit)
        long[] transTimes = new long[timecnt2];
        for (int i = 0; i < timecnt2; i++) {
            transTimes[i] = buf.getLong();
        }

        // Read type indices
        int[] transTypes = new int[timecnt2];
        for (int i = 0; i < timecnt2; i++) {
            transTypes[i] = buf.get() & 0xFF;
        }

        // Read type records
        int[] typeOffsets = new int[typecnt2];
        boolean[] typeIsDst = new boolean[typecnt2];
        int[] typeAbbrIdx = new int[typecnt2];
        for (int i = 0; i < typecnt2; i++) {
            typeOffsets[i] = buf.getInt();
            typeIsDst[i] = buf.get() != 0;
            typeAbbrIdx[i] = buf.get() & 0xFF;
        }

        // Read abbreviation characters
        byte[] abbrBytes = new byte[charcnt2];
        buf.get(abbrBytes);

        // Parse abbreviations
        String[] typeAbbrs = new String[typecnt2];
        for (int i = 0; i < typecnt2; i++) {
            int start = typeAbbrIdx[i];
            int end = start;
            while (end < charcnt2 && abbrBytes[end] != 0) end++;
            typeAbbrs[i] = new String(abbrBytes, start, end - start, "ASCII");
        }

        // Skip leap seconds (8+4 per record)
        buf.position(buf.position() + leapcnt2 * 12);
        buf.position(buf.position() + isstdcnt2);
        buf.position(buf.position() + isutcnt2);

        // Footer: \n + POSIX TZ string + \n
        // Read the footer
        int footerStart = buf.position();
        // Skip leading newline
        buf.get(); // \n
        int posixStart = buf.position();
        int posixEnd = bytes.length - 1; // last byte should be \n
        String posixTz = new String(bytes, posixStart, posixEnd - posixStart, "ASCII");

        // Build TzifData
        TzifData data = new TzifData();
        data.transTimes = transTimes;
        data.transTypes = transTypes;
        data.typeOffsets = typeOffsets;
        data.typeIsDst = typeIsDst;
        data.typeAbbrs = typeAbbrs;

        // Parse POSIX TZ
        parsePosixInto(data, posixTz);

        return data;
    }

    public static void main(String[] args) throws Exception {
        String dir = args[0];

        // Read queries
        List<String> queries = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(dir + "/queries.txt"))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (!line.trim().isEmpty()) {
                    queries.add(line);
                }
            }
        }

        // Cache TZif files
        Map<String, TzifData> cache = new HashMap<>();

        // Process queries
        StringBuilder output = new StringBuilder();
        for (String query : queries) {
            String[] parts = query.split(" ");
            String type = parts[0];
            String fileName = parts[1];

            TzifData tzData = cache.computeIfAbsent(fileName, k -> {
                try {
                    return loadTzif(dir + "/" + k);
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            });

            if (type.equals("UTC")) {
                long t = Long.parseLong(parts[2]);
                int offset = tzData.getOffset(t);
                String abbr = tzData.getAbbr(t);
                String local = formatLocal(t, offset);
                String offsetStr = formatOffset(offset);
                output.append(query).append(" -> ").append(local).append(offsetStr).append(" ").append(abbr).append("\n");
            } else { // LOCAL
                String wallClockStr = parts[2];
                long W = parseWallClock(wallClockStr);

                // Collect candidate offsets
                Set<Integer> candidateOffsets = new TreeSet<>();
                for (int o : tzData.typeOffsets) candidateOffsets.add(o);
                candidateOffsets.add(-tzData.stdPosixOff);
                if (tzData.hasDst) candidateOffsets.add(-tzData.dstPosixOff);

                // Find valid solutions
                List<long[]> solutions = new ArrayList<>(); // [t, offset]
                List<String> abbrs = new ArrayList<>();

                for (int O : candidateOffsets) {
                    long t = W - O;
                    int actualOffset = tzData.getOffset(t);
                    if (actualOffset == O) {
                        solutions.add(new long[]{t, O});
                        abbrs.add(tzData.getAbbr(t));
                    }
                }

                // Sort by t
                solutions.sort((a, b) -> Long.compare(a[0], b[0]));

                if (solutions.size() == 1) {
                    long t = solutions.get(0)[0];
                    int offset = (int) solutions.get(0)[1];
                    String abbr = abbrs.get(0);
                    String offsetStr = formatOffset(offset);
                    output.append(query).append(" -> ").append(t).append(" ").append(offsetStr).append(" ").append(abbr).append("\n");
                } else if (solutions.size() == 2) {
                    long t1 = solutions.get(0)[0];
                    int off1 = (int) solutions.get(0)[1];
                    String abbr1 = abbrs.get(0);
                    long t2 = solutions.get(1)[0];
                    int off2 = (int) solutions.get(1)[1];
                    String abbr2 = abbrs.get(1);
                    output.append(query).append(" -> ").append(t1).append(" ").append(formatOffset(off1)).append(" ").append(abbr1)
                          .append(" | ").append(t2).append(" ").append(formatOffset(off2)).append(" ").append(abbr2).append("\n");
                } else {
                    // Gap
                    // Find old_offset
                    int oldOffset = 0;
                    for (int O : candidateOffsets) {
                        long t = W - O;
                        int actual = tzData.getOffset(t);
                        if (actual != O) {
                            if (actual < O) {
                                oldOffset = actual;
                            } else {
                                oldOffset = O;
                            }
                            break;
                        }
                    }

                    long t = W - oldOffset;
                    int offset = tzData.getOffset(t);
                    String abbr = tzData.getAbbr(t);
                    String local = formatLocal(t, offset);
                    String offsetStr = formatOffset(offset);
                    output.append(query).append(" -> GAP ").append(t).append(" ").append(local).append(offsetStr).append(" ").append(abbr).append("\n");
                }
            }
        }

        System.out.print(output.toString());
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <ctype.h>

/* Big-endian readers */
static int32_t be32(const unsigned char *p) {
    return (int32_t)((uint32_t)p[0]<<24|(uint32_t)p[1]<<16|(uint32_t)p[2]<<8|(uint32_t)p[3]);
}
static int64_t be64(const unsigned char *p) {
    return (int64_t)((uint64_t)p[0]<<56|(uint64_t)p[1]<<48|(uint64_t)p[2]<<40|(uint64_t)p[3]<<32|
                     (uint64_t)p[4]<<24|(uint64_t)p[5]<<16|(uint64_t)p[6]<<8|(uint64_t)p[7]);
}

/* Date helpers */
static int is_leap(int y){return(y%4==0&&y%100!=0)||y%400==0;}
static int dim(int y,int m){static int d[]={31,28,31,30,31,30,31,31,30,31,30,31};return m==2&&is_leap(y)?29:d[m-1];}

static int64_t days_from_civil(int y,int m,int d){
    y-=(m<=2);
    int era=(y>=0?y:y-399)/400;
    unsigned yoe=(unsigned)(y-era*400);
    unsigned doy=(153*(m+(m>2?-3:9))+2)/5+d-1;
    unsigned doe=yoe*365+yoe/4-yoe/100+doy;
    return(int64_t)era*146097+(int64_t)doe-719468;
}

static void civil_from_days(int64_t z,int*y,int*m,int*d){
    z+=719468;
    int64_t era=(z>=0?z:z-146096)/146097;
    unsigned doe=(unsigned)(z-era*146097);
    unsigned yoe=(doe-doe/1460+doe/36524-doe/146096)/365;
    int yy=(int)(yoe+era*400);
    unsigned doy=doe-(365*yoe+yoe/4-yoe/100);
    unsigned mp=(5*doy+2)/153;
    *d=(int)(doy-(153*mp+2)/5+1);
    *m=(int)(mp+(mp<10?3:-9));
    *y=yy+(*m<=2);
}

static int dow(int64_t z){int r=(int)((z+4)%7);return r<0?r+7:r;}

/* TZif structure */
typedef struct{
    int64_t*trans;unsigned char*types;int ntrans;
    int32_t*gmtoff;unsigned char*isdst;unsigned char*abbr_idx;int ntypes;
    char*abbrs;int abbr_len;
    char posix[256];
    int has_dst;
    int32_t std_off,dst_off;
    char std_abbr[64],dst_abbr[64];
    int s_m,s_w,s_d,s_t; /* start rule */
    int e_m,e_w,e_d,e_t; /* end rule */
}TZ;

/* Parse helpers */
static const char*parse_name(const char*p,char*out,int max){
    if(*p=='<'){p++;int i=0;while(*p&&*p!='>'&&i<max-1)out[i++]=*p++;out[i]='\0';if(*p=='>')p++;}
    else{int i=0;while(isalpha((unsigned char)*p)&&i<max-1)out[i++]=*p++;out[i]='\0';}
    return p;
}

static int32_t parse_off(const char*p,const char**end){
    int sign=1;
    if(*p=='-'){sign=-1;p++;}else if(*p=='+'){p++;}
    int h=0,m=0,s=0;
    while(isdigit((unsigned char)*p))h=h*10+(*p++-'0');
    if(*p==':'){p++;while(isdigit((unsigned char)*p))m=m*10+(*p++-'0');}
    if(*p==':'){p++;while(isdigit((unsigned char)*p))s=s*10+(*p++-'0');}
    *end=p;return sign*(h*3600+m*60+s);
}

static const char*parse_rule(const char*p,int*m,int*w,int*d,int*t){
    if(*p=='M'){p++;*m=0;while(isdigit((unsigned char)*p))*m=*m*10+(*p++-'0');
        if(*p=='.')p++;*w=0;while(isdigit((unsigned char)*p))*w=*w*10+(*p++-'0');
        if(*p=='.')p++;*d=0;while(isdigit((unsigned char)*p))*d=*d*10+(*p++-'0');}
    *t=7200; /* default 02:00:00 */
    if(*p=='/'){p++;int sign=1;
        if(*p=='-'){sign=-1;p++;}else if(*p=='+'){p++;}
        int h=0,mm=0,ss=0;
        while(isdigit((unsigned char)*p))h=h*10+(*p++-'0');
        if(*p==':'){p++;while(isdigit((unsigned char)*p))mm=mm*10+(*p++-'0');}
        if(*p==':'){p++;while(isdigit((unsigned char)*p))ss=ss*10+(*p++-'0');}
        *t=sign*(h*3600+mm*60+ss);}
    return p;
}

/* Compute UTC time of a rule occurrence */
static int64_t rule_utc(int yr,int m,int w,int d,int tsec,int32_t off){
    int64_t fd=days_from_civil(yr,m,1);
    int dw=dow(fd);
    int ft=1+((d-dw+7)%7);
    int td;
    if(w==5){int dm=dim(yr,m);td=ft+7*((dm-ft)/7);}
    else td=ft+7*(w-1);
    int64_t loc=days_from_civil(yr,m,td)*86400+tsec;
    return loc-off;
}

/* Parse TZif file */
static void load_tz(TZ*tz,const char*dir,const char*fn){
    char path[1024];snprintf(path,sizeof(path),"%s/%s",dir,fn);
    FILE*f=fopen(path,"rb");if(!f){perror(path);exit(1);}
    fseek(f,0,SEEK_END);long fs=ftell(f);fseek(f,0,SEEK_SET);
    unsigned char*buf=malloc(fs);fread(buf,1,fs,f);fclose(f);

    /* Skip v1 block */
    int32_t tu1=be32(buf+20),ts1=be32(buf+24),tl1=be32(buf+28),tt1=be32(buf+32),ty1=be32(buf+36),tc1=be32(buf+40);
    int off=44+tt1*4+tt1+ty1*6+tc1+tl1*8+ts1+tu1;

    /* v2 header */
    int32_t tu2=be32(buf+off+20),ts2=be32(buf+off+24),tl2=be32(buf+off+28),tt2=be32(buf+off+32),ty2=be32(buf+off+36),tc2=be32(buf+off+40);
    off+=44;

    tz->ntrans=tt2;
    tz->trans=malloc(tt2*sizeof(int64_t));
    for(int i=0;i<tt2;i++){tz->trans[i]=be64(buf+off);off+=8;}
    tz->types=malloc(tt2);memcpy(tz->types,buf+off,tt2);off+=tt2;

    tz->ntypes=ty2;
    tz->gmtoff=malloc(ty2*sizeof(int32_t));
    tz->isdst=malloc(ty2);tz->abbr_idx=malloc(ty2);
    for(int i=0;i<ty2;i++){tz->gmtoff[i]=be32(buf+off);tz->isdst[i]=buf[off+4];tz->abbr_idx[i]=buf[off+5];off+=6;}

    tz->abbr_len=tc2;tz->abbrs=malloc(tc2);memcpy(tz->abbrs,buf+off,tc2);off+=tc2;
    off+=tl2*12+ts2+tu2; /* skip leap, isstd, isut */

    /* Footer */
    if(off<fs&&buf[off]=='\n')off++;
    int pl=0;while(off<fs&&buf[off]!='\n')tz->posix[pl++]=buf[off++];
    tz->posix[pl]='\0';
    free(buf);

    /* Parse POSIX */
    const char*p=tz->posix;
    if(*p=='\0'){tz->has_dst=0;tz->std_off=0;tz->std_abbr[0]='\0';return;}
    p=parse_name(p,tz->std_abbr,64);
    int32_t so;so=parse_off(p,&p);tz->std_off=-so;
    if(isalpha((unsigned char)*p)||*p=='<'){
        tz->has_dst=1;
        p=parse_name(p,tz->dst_abbr,64);
        if(*p=='+'||*p=='-'||isdigit((unsigned char)*p)){
            int32_t doff;doff=parse_off(p,&p);tz->dst_off=-doff;
        }else{
            tz->dst_off=tz->std_off+3600;
        }
    }else{tz->has_dst=0;}
    if(*p==','){p++;p=parse_rule(p,&tz->s_m,&tz->s_w,&tz->s_d,&tz->s_t);
        if(*p==',')p++;p=parse_rule(p,&tz->e_m,&tz->e_w,&tz->e_d,&tz->e_t);}
}

static void free_tz(TZ*tz){free(tz->trans);free(tz->types);free(tz->gmtoff);free(tz->isdst);free(tz->abbr_idx);free(tz->abbrs);}

/* Get offset at time t */
static int32_t get_off(TZ*tz,int64_t t,const char**ab,int*dst){
    if(tz->ntrans==0){/* only POSIX */goto posix;}
    if(t<tz->trans[0]){*ab=&tz->abbrs[tz->abbr_idx[0]];*dst=tz->isdst[0];return tz->gmtoff[0];}
    if(t>tz->trans[tz->ntrans-1]){goto posix;}
    {int lo=0,hi=tz->ntrans-1;
    while(lo<hi){int mid=(lo+hi+1)/2;if(tz->trans[mid]<=t)lo=mid;else hi=mid-1;}
    int ti=tz->types[lo];*ab=&tz->abbrs[tz->abbr_idx[ti]];*dst=tz->isdst[ti];return tz->gmtoff[ti];}
posix:
    if(!tz->has_dst){*ab=tz->std_abbr;*dst=0;return tz->std_off;}
    int64_t days=t/86400;if(t<0&&t%86400!=0)days--;
    int y,m,d;civil_from_days(days,&y,&m,&d);
    int64_t su=rule_utc(y,tz->s_m,tz->s_w,tz->s_d,tz->s_t,tz->std_off);
    int64_t eu=rule_utc(y,tz->e_m,tz->e_w,tz->e_d,tz->e_t,tz->dst_off);
    int act;if(su<eu)act=(t>=su&&t<eu);else act=(t>=su||t<eu);
    if(act){*ab=tz->dst_abbr;*dst=1;return tz->dst_off;}
    else{*ab=tz->std_abbr;*dst=0;return tz->std_off;}
}

/* Format offset */
static char obuf[16];
static const char*fmt_off(int32_t o){
    int s=1;if(o<0){s=-1;o=-o;}
    int h=o/3600,m=(o%3600)/60,sc=o%60;
    if(sc)snprintf(obuf,sizeof(obuf),"%c%02d:%02d:%02d",s>=0?'+':'-',h,m,sc);
    else snprintf(obuf,sizeof(obuf),"%c%02d:%02d",s>=0?'+':'-',h,m);
    return obuf;
}

/* Epoch to datetime */
static void e2dt(int64_t e,int*y,int*m,int*d,int*hh,int*mm,int*ss){
    int64_t days=e/86400;int64_t rem=e%86400;
    if(rem<0){days--;rem+=86400;}
    civil_from_days(days,y,m,d);
    *hh=(int)(rem/3600);*mm=(int)((rem%3600)/60);*ss=(int)(rem%60);
}

int main(int argc,char*argv[]){
    if(argc<2){fprintf(stderr,"Usage: %s <dir>\n",argv[0]);return 1;}
    const char*dir=argv[1];
    char qp[1024];snprintf(qp,sizeof(qp),"%s/queries.txt",dir);
    FILE*qf=fopen(qp,"r");if(!qf){perror(qp);return 1;}

    char line[4096];
    while(fgets(line,sizeof(line),qf)){
        int len=strlen(line);
        while(len>0&&(line[len-1]=='\n'||line[len-1]=='\r'))line[--len]='\0';
        if(len==0)continue;

        char tp[10],fn[256],vl[64];
        if(sscanf(line,"%s %s %s",tp,fn,vl)<3)continue;

        TZ tz;memset(&tz,0,sizeof(tz));
        load_tz(&tz,dir,fn);

        if(strcmp(tp,"UTC")==0){
            int64_t t=strtoll(vl,NULL,10);
            const char*ab;int dst;
            int32_t o=get_off(&tz,t,&ab,&dst);
            int64_t le=t+o;
            int y,m,d,hh,mm,ss;e2dt(le,&y,&m,&d,&hh,&mm,&ss);
            printf("%s -> %04d-%02d-%02dT%02d:%02d:%02d%s %s\n",line,y,m,d,hh,mm,ss,fmt_off(o),ab);
        }else{ /* LOCAL */
            int y,m,d,hh,mm,ss;
            sscanf(vl,"%d-%d-%dT%d:%d:%d",&y,&m,&d,&hh,&mm,&ss);
            int64_t W=days_from_civil(y,m,d)*86400+hh*3600+mm*60+ss;

            /* Collect candidate offsets */
            int32_t cands[256];int nc=0;
            for(int i=0;i<tz.ntypes;i++){int f=0;for(int j=0;j<nc;j++)if(cands[j]==tz.gmtoff[i]){f=1;break;}if(!f)cands[nc++]=tz.gmtoff[i];}
            if(!tz.has_dst){int f=0;for(int j=0;j<nc;j++)if(cands[j]==tz.std_off){f=1;break;}if(!f)cands[nc++]=tz.std_off;}
            else{int f=0;for(int j=0;j<nc;j++)if(cands[j]==tz.std_off){f=1;break;}if(!f)cands[nc++]=tz.std_off;
                 f=0;for(int j=0;j<nc;j++)if(cands[j]==tz.dst_off){f=1;break;}if(!f)cands[nc++]=tz.dst_off;}

            int64_t vt[4];int32_t vo[4];const char*va[4];int nv=0;
            for(int i=0;i<nc;i++){
                int64_t t=W-cands[i];
                const char*ab;int dst;
                int32_t ao=get_off(&tz,t,&ab,&dst);
                if(ao==cands[i]){vt[nv]=t;vo[nv]=ao;va[nv]=ab;nv++;}
            }
            /* sort */
            for(int i=0;i<nv-1;i++)for(int j=i+1;j<nv;j++)if(vt[j]<vt[i]){
                int64_t tt=vt[i];vt[i]=vt[j];vt[j]=tt;
                int32_t to=vo[i];vo[i]=vo[j];vo[j]=to;
                const char*ta=va[i];va[i]=va[j];va[j]=ta;}

            if(nv==1){
                printf("%s -> %lld %s %s\n",line,(long long)vt[0],fmt_off(vo[0]),va[0]);
            }else if(nv==2){
                printf("%s -> %lld %s %s | %lld %s %s\n",line,(long long)vt[0],fmt_off(vo[0]),va[0],(long long)vt[1],fmt_off(vo[1]),va[1]);
            }else{
                /* GAP: find transition */
                int found=0;
                /* File transitions */
                for(int i=0;i<tz.ntrans&&!found;i++){
                    int64_t T=tz.trans[i];
                    int ti=tz.types[i];
                    int32_t oB=tz.gmtoff[ti];
                    const char*ta;int td;
                    int32_t oA=get_off(&tz,T-1,&ta,&td);
                    if(oB>oA&&T+oA<=W&&W<T+oB){
                        int64_t t=W-oA;const char*ab;int dst;
                        int32_t o=get_off(&tz,t,&ab,&dst);
                        int64_t le=t+o;int ly,lm,ld,lh,lmn,ls;e2dt(le,&ly,&lm,&ld,&lh,&lmn,&ls);
                        printf("%s -> GAP %lld %04d-%02d-%02dT%02d:%02d:%02d%s %s\n",line,(long long)t,ly,lm,ld,lh,lmn,ls,fmt_off(o),ab);
                        found=1;
                    }
                }
                /* POSIX transitions */
                if(!found&&tz.has_dst){
                    int64_t days=W/86400;if(W<0&&W%86400!=0)days--;
                    int yr;civil_from_days(days,&yr,&m,&d);
                    for(int yy=yr-1;yy<=yr+1&&!found;yy++){
                        int64_t su=rule_utc(yy,tz.s_m,tz.s_w,tz.s_d,tz.s_t,tz.std_off);
                        if(tz.ntrans>0&&su<=tz.trans[tz.ntrans-1])continue;
                        if(tz.dst_off>tz.std_off&&su+tz.std_off<=W&&W<su+tz.dst_off){
                            int64_t t=W-tz.std_off;const char*ab;int dst;
                            int32_t o=get_off(&tz,t,&ab,&dst);
                            int64_t le=t+o;int ly,lm,ld,lh,lmn,ls;e2dt(le,&ly,&lm,&ld,&lh,&lmn,&ls);
                            printf("%s -> GAP %lld %04d-%02d-%02dT%02d:%02d:%02d%s %s\n",line,(long long)t,ly,lm,ld,lh,lmn,ls,fmt_off(o),ab);
                            found=1;
                        }
                    }
                }
                if(!found){
                    /* Shouldn't happen with valid input, but fallback */
                    printf("%s -> GAP %lld\n",line,(long long)W);
                }
            }
        }
        free_tz(&tz);
    }
    fclose(qf);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <ctype.h>

/* Big-endian readers */
static int32_t be32(const unsigned char *p) {
    return (int32_t)((uint32_t)p[0]<<24|(uint32_t)p[1]<<16|(uint32_t)p[2]<<8|(uint32_t)p[3]);
}
static int64_t be64(const unsigned char *p) {
    return (int64_t)((uint64_t)p[0]<<56|(uint64_t)p[1]<<48|(uint64_t)p[2]<<40|(uint64_t)p[3]<<32|
                     (uint64_t)p[4]<<24|(uint64_t)p[5]<<16|(uint64_t)p[6]<<8|(uint64_t)p[7]);
}

/* Date helpers */
static int is_leap(int y){return(y%4==0&&y%100!=0)||y%400==0;}
static int dim(int y,int m){static int d[]={31,28,31,30,31,30,31,31,30,31,30,31};return m==2&&is_leap(y)?29:d[m-1];}

static int64_t days_from_civil(int y,int m,int d){
    y-=(m<=2);
    int era=(y>=0?y:y-399)/400;
    unsigned yoe=(unsigned)(y-era*400);
    unsigned doy=(153*(m+(m>2?-3:9))+2)/5+d-1;
    unsigned doe=yoe*365+yoe/4-yoe/100+doy;
    return(int64_t)era*146097+(int64_t)doe-719468;
}

static void civil_from_days(int64_t z,int*y,int*m,int*d){
    z+=719468;
    int64_t era=(z>=0?z:z-146096)/146097;
    unsigned doe=(unsigned)(z-era*146097);
    unsigned yoe=(doe-doe/1460+doe/36524-doe/146096)/365;
    int yy=(int)(yoe+era*400);
    unsigned doy=doe-(365*yoe+yoe/4-yoe/100);
    unsigned mp=(5*doy+2)/153;
    *d=(int)(doy-(153*mp+2)/5+1);
    *m=(int)(mp+(mp<10?3:-9));
    *y=yy+(*m<=2);
}

static int dow(int64_t z){int r=(int)((z+4)%7);return r<0?r+7:r;}

/* TZif structure */
typedef struct{
    int64_t*trans;unsigned char*types;int ntrans;
    int32_t*gmtoff;unsigned char*isdst;unsigned char*abbr_idx;int ntypes;
    char*abbrs;int abbr_len;
    char posix[256];
    int has_dst;
    int32_t std_off,dst_off;
    char std_abbr[64],dst_abbr[64];
    int s_m,s_w,s_d,s_t;
    int e_m,e_w,e_d,e_t;
}TZ;

/* Parse helpers */
static const char*parse_name(const char*p,char*out,int max){
    if(*p=='<'){p++;int i=0;while(*p&&*p!='>'&&i<max-1)out[i++]=*p++;out[i]='\0';if(*p=='>')p++;}
    else{int i=0;while(isalpha((unsigned char)*p)&&i<max-1)out[i++]=*p++;out[i]='\0';}
    return p;
}

static int32_t parse_off(const char*p,const char**end){
    int sign=1;
    if(*p=='-'){sign=-1;p++;}else if(*p=='+'){p++;}
    int h=0,m=0,s=0;
    while(isdigit((unsigned char)*p))h=h*10+(*p++-'0');
    if(*p==':'){p++;while(isdigit((unsigned char)*p))m=m*10+(*p++-'0');}
    if(*p==':'){p++;while(isdigit((unsigned char)*p))s=s*10+(*p++-'0');}
    *end=p;return sign*(h*3600+m*60+s);
}

static const char*parse_rule(const char*p,int*m,int*w,int*d,int*t){
    if(*p=='M'){p++;*m=0;while(isdigit((unsigned char)*p))*m=*m*10+(*p++-'0');
        if(*p=='.')p++;*w=0;while(isdigit((unsigned char)*p))*w=*w*10+(*p++-'0');
        if(*p=='.')p++;*d=0;while(isdigit((unsigned char)*p))*d=*d*10+(*p++-'0');}
    *t=7200;
    if(*p=='/'){p++;int sign=1;
        if(*p=='-'){sign=-1;p++;}else if(*p=='+'){p++;}
        int h=0,mm=0,ss=0;
        while(isdigit((unsigned char)*p))h=h*10+(*p++-'0');
        if(*p==':'){p++;while(isdigit((unsigned char)*p))mm=mm*10+(*p++-'0');}
        if(*p==':'){p++;while(isdigit((unsigned char)*p))ss=ss*10+(*p++-'0');}
        *t=sign*(h*3600+mm*60+ss);}
    return p;
}

/* Compute UTC time of a rule occurrence */
static int64_t rule_utc(int yr,int m,int w,int d,int tsec,int32_t off){
    int64_t fd=days_from_civil(yr,m,1);
    int dw=dow(fd);
    int ft=1+((d-dw+7)%7);
    int td;
    if(w==5){int dm=dim(yr,m);td=ft+7*((dm-ft)/7);}
    else td=ft+7*(w-1);
    int64_t loc=days_from_civil(yr,m,td)*86400+tsec;
    return loc-off;
}

/* Parse TZif file */
static void load_tz(TZ*tz,const char*dir,const char*fn){
    char path[1024];snprintf(path,sizeof(path),"%s/%s",dir,fn);
    FILE*f=fopen(path,"rb");if(!f){perror(path);exit(1);}
    fseek(f,0,SEEK_END);long fs=ftell(f);fseek(f,0,SEEK_SET);
    unsigned char*buf=malloc(fs);fread(buf,1,fs,f);fclose(f);

    /* Skip v1 block */
    int32_t tu1=be32(buf+20),ts1=be32(buf+24),tl1=be32(buf+28),tt1=be32(buf+32),ty1=be32(buf+36),tc1=be32(buf+40);
    int off=44+tt1*4+tt1+ty1*6+tc1+tl1*8+ts1+tu1;

    /* v2 header */
    int32_t tu2=be32(buf+off+20),ts2=be32(buf+off+24),tl2=be32(buf+off+28),tt2=be32(buf+off+32),ty2=be32(buf+off+36),tc2=be32(buf+off+40);
    off+=44;

    tz->ntrans=tt2;
    tz->trans=malloc(tt2*sizeof(int64_t));
    for(int i=0;i<tt2;i++){tz->trans[i]=be64(buf+off);off+=8;}
    tz->types=malloc(tt2);memcpy(tz->types,buf+off,tt2);off+=tt2;

    tz->ntypes=ty2;
    tz->gmtoff=malloc(ty2*sizeof(int32_t));
    tz->isdst=malloc(ty2);tz->abbr_idx=malloc(ty2);
    for(int i=0;i<ty2;i++){tz->gmtoff[i]=be32(buf+off);tz->isdst[i]=buf[off+4];tz->abbr_idx[i]=buf[off+5];off+=6;}

    tz->abbr_len=tc2;tz->abbrs=malloc(tc2);memcpy(tz->abbrs,buf+off,tc2);off+=tc2;
    off+=tl2*12+ts2+tu2;

    /* Footer */
    if(off<fs&&buf[off]=='\n')off++;
    int pl=0;while(off<fs&&buf[off]!='\n')tz->posix[pl++]=buf[off++];
    tz->posix[pl]='\0';
    free(buf);

    /* Parse POSIX */
    const char*p=tz->posix;
    if(*p=='\0'){tz->has_dst=0;tz->std_off=0;tz->std_abbr[0]='\0';return;}
    p=parse_name(p,tz->std_abbr,64);
    int32_t so;so=parse_off(p,&p);tz->std_off=-so;
    if(isalpha((unsigned char)*p)||*p=='<'){
        tz->has_dst=1;
        p=parse_name(p,tz->dst_abbr,64);
        if(*p=='+'||*p=='-'||isdigit((unsigned char)*p)){
            int32_t doff;doff=parse_off(p,&p);tz->dst_off=-doff;
        }else{
            tz->dst_off=tz->std_off+3600;
        }
    }else{tz->has_dst=0;}
    if(*p==','){p++;p=parse_rule(p,&tz->s_m,&tz->s_w,&tz->s_d,&tz->s_t);
        if(*p==',')p++;p=parse_rule(p,&tz->e_m,&tz->e_w,&tz->e_d,&tz->e_t);}
}

static void free_tz(TZ*tz){free(tz->trans);free(tz->types);free(tz->gmtoff);free(tz->isdst);free(tz->abbr_idx);free(tz->abbrs);}

/* Get offset at time t */
static int32_t get_off(TZ*tz,int64_t t,const char**ab,int*dst){
    if(tz->ntrans==0){goto posix;}
    if(t<tz->trans[0]){*ab=&tz->abbrs[tz->abbr_idx[0]];*dst=tz->isdst[0];return tz->gmtoff[0];}
    if(t>tz->trans[tz->ntrans-1]){goto posix;}
    {int lo=0,hi=tz->ntrans-1;
    while(lo<hi){int mid=(lo+hi+1)/2;if(tz->trans[mid]<=t)lo=mid;else hi=mid-1;}
    int ti=tz->types[lo];*ab=&tz->abbrs[tz->abbr_idx[ti]];*dst=tz->isdst[ti];return tz->gmtoff[ti];}
posix:
    if(!tz->has_dst){*ab=tz->std_abbr;*dst=0;return tz->std_off;}
    int64_t days=t/86400;if(t<0&&t%86400!=0)days--;
    int y,m,d;civil_from_days(days,&y,&m,&d);
    int64_t su=rule_utc(y,tz->s_m,tz->s_w,tz->s_d,tz->s_t,tz->std_off);
    int64_t eu=rule_utc(y,tz->e_m,tz->e_w,tz->e_d,tz->e_t,tz->dst_off);
    int act;if(su<eu)act=(t>=su&&t<eu);else act=(t>=su||t<eu);
    if(act){*ab=tz->dst_abbr;*dst=1;return tz->dst_off;}
    else{*ab=tz->std_abbr;*dst=0;return tz->std_off;}
}

/* Format offset into caller-provided buffer */
static void fmt_off(int32_t o,char*buf){
    int s=1;if(o<0){s=-1;o=-o;}
    int h=o/3600,m=(o%3600)/60,sc=o%60;
    if(sc)sprintf(buf,"%c%02d:%02d:%02d",s>=0?'+':'-',h,m,sc);
    else sprintf(buf,"%c%02d:%02d",s>=0?'+':'-',h,m);
}

/* Epoch to datetime */
static void e2dt(int64_t e,int*y,int*m,int*d,int*hh,int*mm,int*ss){
    int64_t days=e/86400;int64_t rem=e%86400;
    if(rem<0){days--;rem+=86400;}
    civil_from_days(days,y,m,d);
    *hh=(int)(rem/3600);*mm=(int)((rem%3600)/60);*ss=(int)(rem%60);
}

int main(int argc,char*argv[]){
    if(argc<2){fprintf(stderr,"Usage: %s <dir>\n",argv[0]);return 1;}
    const char*dir=argv[1];
    char qp[1024];snprintf(qp,sizeof(qp),"%s/queries.txt",dir);
    FILE*qf=fopen(qp,"r");if(!qf){perror(qp);return 1;}

    char line[4096];
    while(fgets(line,sizeof(line),qf)){
        int len=strlen(line);
        while(len>0&&(line[len-1]=='\n'||line[len-1]=='\r'))line[--len]='\0';
        if(len==0)continue;

        char tp[10],fn[256],vl[64];
        if(sscanf(line,"%s %s %s",tp,fn,vl)<3)continue;

        TZ tz;memset(&tz,0,sizeof(tz));
        load_tz(&tz,dir,fn);

        if(strcmp(tp,"UTC")==0){
            int64_t t=strtoll(vl,NULL,10);
            const char*ab;int dst;
            int32_t o=get_off(&tz,t,&ab,&dst);
            int64_t le=t+o;
            int y,m,d,hh,mm,ss;e2dt(le,&y,&m,&d,&hh,&mm,&ss);
            char ob[16];fmt_off(o,ob);
            printf("%s -> %04d-%02d-%02dT%02d:%02d:%02d%s %s\n",line,y,m,d,hh,mm,ss,ob,ab);
        }else{ /* LOCAL */
            int y,m,d,hh,mm,ss;
            sscanf(vl,"%d-%d-%dT%d:%d:%d",&y,&m,&d,&hh,&mm,&ss);
            int64_t W=days_from_civil(y,m,d)*86400+hh*3600+mm*60+ss;

            /* Collect candidate offsets */
            int32_t cands[256];int nc=0;
            for(int i=0;i<tz.ntypes;i++){int f=0;for(int j=0;j<nc;j++)if(cands[j]==tz.gmtoff[i]){f=1;break;}if(!f)cands[nc++]=tz.gmtoff[i];}
            if(!tz.has_dst){int f=0;for(int j=0;j<nc;j++)if(cands[j]==tz.std_off){f=1;break;}if(!f)cands[nc++]=tz.std_off;}
            else{int f=0;for(int j=0;j<nc;j++)if(cands[j]==tz.std_off){f=1;break;}if(!f)cands[nc++]=tz.std_off;
                 f=0;for(int j=0;j<nc;j++)if(cands[j]==tz.dst_off){f=1;break;}if(!f)cands[nc++]=tz.dst_off;}

            int64_t vt[4];int32_t vo[4];const char*va[4];int nv=0;
            for(int i=0;i<nc;i++){
                int64_t t=W-cands[i];
                const char*ab;int dst;
                int32_t ao=get_off(&tz,t,&ab,&dst);
                if(ao==cands[i]){vt[nv]=t;vo[nv]=ao;va[nv]=ab;nv++;}
            }
            /* sort by unix time */
            for(int i=0;i<nv-1;i++)for(int j=i+1;j<nv;j++)if(vt[j]<vt[i]){
                int64_t tt=vt[i];vt[i]=vt[j];vt[j]=tt;
                int32_t to=vo[i];vo[i]=vo[j];vo[j]=to;
                const char*ta=va[i];va[i]=va[j];va[j]=ta;}

            if(nv==1){
                char ob[16];fmt_off(vo[0],ob);
                printf("%s -> %lld %s %s\n",line,(long long)vt[0],ob,va[0]);
            }else if(nv==2){
                char ob1[16],ob2[16];
                fmt_off(vo[0],ob1);fmt_off(vo[1],ob2);
                printf("%s -> %lld %s %s | %lld %s %s\n",line,(long long)vt[0],ob1,va[0],(long long)vt[1],ob2,va[1]);
            }else{
                /* GAP */
                int found=0;
                /* File transitions */
                for(int i=0;i<tz.ntrans&&!found;i++){
                    int64_t T=tz.trans[i];
                    int ti=tz.types[i];
                    int32_t oB=tz.gmtoff[ti];
                    const char*ta;int td;
                    int32_t oA=get_off(&tz,T-1,&ta,&td);
                    if(oB>oA&&T+oA<=W&&W<T+oB){
                        int64_t t=W-oA;const char*ab;int dst;
                        int32_t o=get_off(&tz,t,&ab,&dst);
                        int64_t le=t+o;int ly,lm,ld,lh,lmn,ls;e2dt(le,&ly,&lm,&ld,&lh,&lmn,&ls);
                        char ob[16];fmt_off(o,ob);
                        printf("%s -> GAP %lld %04d-%02d-%02dT%02d:%02d:%02d%s %s\n",line,(long long)t,ly,lm,ld,lh,lmn,ls,ob,ab);
                        found=1;
                    }
                }
                /* POSIX transitions */
                if(!found&&tz.has_dst){
                    int64_t days=W/86400;if(W<0&&W%86400!=0)days--;
                    int yr;civil_from_days(days,&yr,&m,&d);
                    for(int yy=yr-1;yy<=yr+1&&!found;yy++){
                        int64_t su=rule_utc(yy,tz.s_m,tz.s_w,tz.s_d,tz.s_t,tz.std_off);
                        if(tz.ntrans>0&&su<=tz.trans[tz.ntrans-1])continue;
                        if(tz.dst_off>tz.std_off&&su+tz.std_off<=W&&W<su+tz.dst_off){
                            int64_t t=W-tz.std_off;const char*ab;int dst;
                            int32_t o=get_off(&tz,t,&ab,&dst);
                            int64_t le=t+o;int ly,lm,ld,lh,lmn,ls;e2dt(le,&ly,&lm,&ld,&lh,&lmn,&ls);
                            char ob[16];fmt_off(o,ob);
                            printf("%s -> GAP %lld %04d-%02d-%02dT%02d:%02d:%02d%s %s\n",line,(long long)t,ly,lm,ld,lh,lmn,ls,ob,ab);
                            found=1;
                        }
                    }
                }
                if(!found){
                    printf("%s -> GAP %lld\n",line,(long long)W);
                }
            }
        }
        free_tz(&tz);
    }
    fclose(qf);
    return 0;
}

import Foundation

// ============ Big-endian reading ============

func readBE32(_ data: [UInt8], _ offset: Int) -> Int32 {
    return Int32(bitPattern: UInt32(data[offset]) << 24 | UInt32(data[offset+1]) << 16 |
                 UInt32(data[offset+2]) << 8 | UInt32(data[offset+3]))
}

func readBEu32(_ data: [UInt8], _ offset: Int) -> UInt32 {
    return UInt32(data[offset]) << 24 | UInt32(data[offset+1]) << 16 |
           UInt32(data[offset+2]) << 8 | UInt32(data[offset+3])
}

func readBE64(_ data: [UInt8], _ offset: Int) -> Int64 {
    return Int64(bitPattern: UInt64(data[offset]) << 56 | UInt64(data[offset+1]) << 48 |
                 UInt64(data[offset+2]) << 40 | UInt64(data[offset+3]) << 32 |
                 UInt64(data[offset+4]) << 24 | UInt64(data[offset+5]) << 16 |
                 UInt64(data[offset+6]) << 8 | UInt64(data[offset+7]))
}

// ============ Calendar helpers ============

func isLeap(_ year: Int) -> Bool {
    return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0
}

func daysInMonth(_ year: Int, _ month: Int) -> Int {
    switch month {
    case 1, 3, 5, 7, 8, 10, 12: return 31
    case 4, 6, 9, 11: return 30
    case 2: return isLeap(year) ? 29 : 28
    default: return 30
    }
}

func dayOfWeek(_ year: Int, _ month: Int, _ day: Int) -> Int {
    // Returns 0=Sunday, ..., 6=Saturday
    var y = year
    var m = month
    if m < 3 { y -= 1; m += 12 }
    let k = y % 100
    let j = y / 100
    let h = (day + 13*(m+1)/5 + k + k/4 + j/4 + 5*j) % 7
    // h: 0=Sat, 1=Sun, ..., 6=Fri
    return (h + 6) % 7
}

func epochFromYMDHMS(_ year: Int, _ month: Int, _ day: Int, _ hour: Int, _ min: Int, _ sec: Int) -> Int64 {
    var y = year
    var m = month
    if m <= 2 { y -= 1; m += 12 }
    let era = (y >= 0 ? y : y - 399) / 400
    let yoe = y - era * 400
    let doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + day - 1
    let doe = yoe * 365 + yoe/4 - yoe/100 + doy
    let days = era * 146097 + doe - 719468
    return Int64(days) * 86400 + Int64(hour) * 3600 + Int64(min) * 60 + Int64(sec)
}

func decomposeEpoch(_ epoch: Int64) -> (year: Int, month: Int, day: Int, hour: Int, min: Int, sec: Int) {
    var days = Int(epoch / 86400)
    var rem = Int(epoch % 86400)
    if rem < 0 { rem += 86400; days -= 1 }

    days += 719468
    let era = (days >= 0 ? days : days - 146096) / 146097
    let doe = days - era * 146097
    let yoe = (doe - doe/1460 + doe/36524 - doe/146096) / 365
    let y = yoe + era * 400
    let doy = doe - (365*yoe + yoe/4 - yoe/100)
    let mp = (5*doy + 2)/153
    let d = doy - (153*mp+2)/5 + 1
    let m = mp + (mp < 10 ? 3 : -9)
    let yr = y + (m <= 2 ? 1 : 0)

    let h = rem / 3600
    let mn = (rem % 3600) / 60
    let sc = rem % 60

    return (yr, m, d, h, mn, sc)
}

// ============ TZif parsing ============

struct LocalTimeType {
    var utoff: Int32
    var isdst: Bool
    var abbr: String
}

struct TZifData {
    var transitions: [Int64]
    var typeIndices: [UInt8]
    var types: [LocalTimeType]
    var posixTZ: String
}

func parseTZif(_ data: [UInt8]) -> TZifData {
    // First header: 44 bytes
    // data[0..3] = "TZif", data[4] = version
    let isutcnt1 = Int(readBEu32(data, 20))
    let isstdcnt1 = Int(readBEu32(data, 16))
    let leapcnt1 = Int(readBEu32(data, 12))
    let timecnt1 = Int(readBEu32(data, 24))
    let typecnt1 = Int(readBEu32(data, 28))
    let charcnt1 = Int(readBEu32(data, 32))

    let block1size = timecnt1 * 4 + timecnt1 + typecnt1 * 6 + charcnt1 + leapcnt1 * 8 + isstdcnt1 + isutcnt1
    let h2offset = 44 + block1size

    let isutcnt2 = Int(readBEu32(data, h2offset + 20))
    let isstdcnt2 = Int(readBEu32(data, h2offset + 16))
    let leapcnt2 = Int(readBEu32(data, h2offset + 12))
    let timecnt2 = Int(readBEu32(data, h2offset + 24))
    let typecnt2 = Int(readBEu32(data, h2offset + 28))
    let charcnt2 = Int(readBEu32(data, h2offset + 32))

    var pos = h2offset + 44

    var transitions: [Int64] = []
    for _ in 0..<timecnt2 {
        transitions.append(readBE64(data, pos))
        pos += 8
    }

    var typeIndices: [UInt8] = []
    for _ in 0..<timecnt2 {
        typeIndices.append(data[pos])
        pos += 1
    }

    var types: [LocalTimeType] = []
    var abbrIndices: [Int] = []
    for _ in 0..<typecnt2 {
        let utoff = readBE32(data, pos)
        let isdst = data[pos + 4] != 0
        let abbrIdx = Int(data[pos + 5])
        types.append(LocalTimeType(utoff: utoff, isdst: isdst, abbr: ""))
        abbrIndices.append(abbrIdx)
        pos += 6
    }

    let abbrStart = pos
    for i in 0..<typecnt2 {
        let idx = abbrIndices[i]
        var s = ""
        var j = abbrStart + idx
        while j < abbrStart + charcnt2 && data[j] != 0 {
            s.append(Character(UnicodeScalar(data[j])))
            j += 1
        }
        types[i].abbr = s
    }
    pos = abbrStart + charcnt2

    // Skip leap seconds (8+4=12 bytes each in v2)
    pos += leapcnt2 * 12
    pos += isstdcnt2 + isutcnt2

    // Footer: \n + posix + \n
    pos += 1  // skip \n
    var posixStr = ""
    while pos < data.count && data[pos] != 10 {
        posixStr.append(Character(UnicodeScalar(data[pos])))
        pos += 1
    }

    return TZifData(transitions: transitions, typeIndices: typeIndices, types: types, posixTZ: posixStr)
}

// ============ POSIX TZ string parsing ============

struct PosixTZ {
    var stdAbbr: String
    var stdOffset: Int  // amount to add to local to get UTC
    var dstAbbr: String?
    var dstOffset: Int?
    var startRule: (month: Int, week: Int, day: Int)?
    var endRule: (month: Int, week: Int, day: Int)?
    var startTime: Int
    var endTime: Int
}

func parsePosixTZ(_ s: String) -> PosixTZ {
    let chars = Array(s)
    var i = 0

    func parseName() -> String {
        if i < chars.count && chars[i] == "<" {
            i += 1
            var name = ""
            while i < chars.count && chars[i] != ">" {
                name.append(chars[i])
                i += 1
            }
            if i < chars.count { i += 1 } // skip >
            return name
        } else {
            var name = ""
            while i < chars.count && chars[i].isLetter {
                name.append(chars[i])
                i += 1
            }
            return name
        }
    }

    func parseOffset() -> Int {
        var sign = 1
        if i < chars.count && chars[i] == "-" { sign = -1; i += 1 }
        else if i < chars.count && chars[i] == "+" { i += 1 }

        var hours = 0
        while i < chars.count && chars[i].isNumber { hours = hours * 10 + Int(String(chars[i]))!; i += 1 }

        var minutes = 0
        if i < chars.count && chars[i] == ":" {
            i += 1
            while i < chars.count && chars[i].isNumber { minutes = minutes * 10 + Int(String(chars[i]))!; i += 1 }
        }

        var seconds = 0
        if i < chars.count && chars[i] == ":" {
            i += 1
            while i < chars.count && chars[i].isNumber { seconds = seconds * 10 + Int(String(chars[i]))!; i += 1 }
        }

        return sign * (hours * 3600 + minutes * 60 + seconds)
    }

    func parseMWD() -> (month: Int, week: Int, day: Int)? {
        guard i < chars.count && chars[i] == "M" else { return nil }
        i += 1
        var month = 0
        while i < chars.count && chars[i].isNumber { month = month * 10 + Int(String(chars[i]))!; i += 1 }
        guard i < chars.count && chars[i] == "." else { return nil }
        i += 1
        var week = 0
        while i < chars.count && chars[i].isNumber { week = week * 10 + Int(String(chars[i]))!; i += 1 }
        guard i < chars.count && chars[i] == "." else { return nil }
        i += 1
        var day = 0
        while i < chars.count && chars[i].isNumber { day = day * 10 + Int(String(chars[i]))!; i += 1 }
        return (month, week, day)
    }

    func parseTime() -> Int {
        var sign = 1
        if i < chars.count && chars[i] == "-" { sign = -1; i += 1 }
        else if i < chars.count && chars[i] == "+" { i += 1 }

        var hours = 0
        while i < chars.count && chars[i].isNumber { hours = hours * 10 + Int(String(chars[i]))!; i += 1 }

        var minutes = 0
        var seconds = 0
        if i < chars.count && chars[i] == ":" {
            i += 1
            while i < chars.count && chars[i].isNumber { minutes = minutes * 10 + Int(String(chars[i]))!; i += 1 }
            if i < chars.count && chars[i] == ":" {
                i += 1
                while i < chars.count && chars[i].isNumber { seconds = seconds * 10 + Int(String(chars[i]))!; i += 1 }
            }
        }

        return sign * (hours * 3600 + minutes * 60 + seconds)
    }

    var result = PosixTZ(stdAbbr: "", stdOffset: 0, dstAbbr: nil, dstOffset: nil,
                         startRule: nil, endRule: nil, startTime: 2*3600, endTime: 2*3600)

    if s.isEmpty { return result }

    result.stdAbbr = parseName()

    if i < chars.count && (chars[i] == "-" || chars[i] == "+" || chars[i].isNumber) {
        result.stdOffset = parseOffset()
    }

    if i < chars.count && (chars[i] == "<" || chars[i].isLetter) {
        result.dstAbbr = parseName()

        if i < chars.count && (chars[i] == "-" || chars[i] == "+" || chars[i].isNumber) {
            result.dstOffset = parseOffset()
        } else {
            result.dstOffset = result.stdOffset - 3600
        }

        if i < chars.count && chars[i] == "," {
            i += 1
            result.startRule = parseMWD()
            if i < chars.count && chars[i] == "/" {
                i += 1
                result.startTime = parseTime()
            }
            if i < chars.count && chars[i] == "," {
                i += 1
                result.endRule = parseMWD()
                if i < chars.count && chars[i] == "/" {
                    i += 1
                    result.endTime = parseTime()
                }
            }
        }
    }

    return result
}

// ============ Time zone offset computation ============

func computeMWDDate(year: Int, month: Int, week: Int, day: Int) -> Int {
    let firstDow = dayOfWeek(year, month, 1)
    var firstOcc = 1 + ((day - firstDow + 7) % 7)
    let target = firstOcc + (week - 1) * 7
    if week == 5 && target > daysInMonth(year, month) {
        return target - 7
    }
    return target
}

func posixTransitionUTC(year: Int, rule: (month: Int, week: Int, day: Int), time: Int, posixOffset: Int) -> Int64 {
    let d = computeMWDDate(year: year, month: rule.month, week: rule.week, day: rule.day)
    let localEpoch = epochFromYMDHMS(year, rule.month, d, 0, 0, 0) + Int64(time)
    return localEpoch + Int64(posixOffset)
}

func posixAtTime(posix: PosixTZ, t: Int64) -> (offset: Int, abbr: String, isdst: Bool) {
    let stdUtoff = -posix.stdOffset

    guard posix.dstAbbr != nil else {
        return (stdUtoff, posix.stdAbbr, false)
    }

    let dstUtoff = -(posix.dstOffset ?? (posix.stdOffset - 3600))

    guard posix.startRule != nil && posix.endRule != nil else {
        // DST always in effect (no rules)
        return (dstUtoff, posix.dstAbbr!, true)
    }

    let year = decomposeEpoch(t).year

    let dstStart = posixTransitionUTC(year: year, rule: posix.startRule!, time: posix.startTime, posixOffset: posix.stdOffset)
    let dstEnd = posixTransitionUTC(year: year, rule: posix.endRule!, time: posix.endTime, posixOffset: posix.dstOffset!)

    if dstStart < dstEnd {
        if t >= dstStart && t < dstEnd {
            return (dstUtoff, posix.dstAbbr!, true)
        } else {
            return (stdUtoff, posix.stdAbbr, false)
        }
    } else if dstStart > dstEnd {
        if t >= dstStart || t < dstEnd {
            return (dstUtoff, posix.dstAbbr!, true)
        } else {
            return (stdUtoff, posix.stdAbbr, false)
        }
    } else {
        // dstStart == dstEnd: DST all year
        return (dstUtoff, posix.dstAbbr!, true)
    }
}

func getOffsetAndAbbr(tz: TZifData, posix: PosixTZ, t: Int64) -> (offset: Int, abbr: String, isdst: Bool) {
    if tz.transitions.isEmpty {
        return (Int(tz.types[0].utoff), tz.types[0].abbr, tz.types[0].isdst)
    }

    if t < tz.transitions[0] {
        return (Int(tz.types[0].utoff), tz.types[0].abbr, tz.types[0].isdst)
    }

    if t >= tz.transitions[tz.transitions.count - 1] {
        return posixAtTime(posix: posix, t: t)
    }

    // Binary search for latest transition <= t
    var lo = 0, hi = tz.transitions.count - 1
    while lo < hi {
        let mid = (lo + hi + 1) / 2
        if tz.transitions[mid] <= t {
            lo = mid
        } else {
            hi = mid - 1
        }
    }
    let typeIdx = Int(tz.typeIndices[lo])
    return (Int(tz.types[typeIdx].utoff), tz.types[typeIdx].abbr, tz.types[typeIdx].isdst)
}

// ============ Output formatting ============

func formatOffset(_ offset: Int) -> String {
    let sign = offset >= 0 ? "+" : "-"
    let a = abs(offset)
    let h = a / 3600
    let m = (a % 3600) / 60
    let s = a % 60
    if s != 0 {
        return String(format: "%@%02d:%02d:%02d", sign, h, m, s)
    } else {
        return String(format: "%@%02d:%02d", sign, h, m)
    }
}

func formatLocal(epoch: Int64, offset: Int) -> String {
    let local = epoch + Int64(offset)
    let (y, mo, d, h, mi, s) = decomposeEpoch(local)
    return String(format: "%04d-%02d-%02dT%02d:%02d:%02d", y, mo, d, h, mi, s) + formatOffset(offset)
}

// ============ Main ============

let args = CommandLine.arguments
guard args.count >= 2 else { exit(1) }
let dir = args[1]

// Read queries
let queriesPath = dir + "/queries.txt"
guard let queriesContent = try? String(contentsOfFile: queriesPath, encoding: .utf8) else { exit(1) }

// Cache parsed TZif files
var tzCache: [String: (TZifData, PosixTZ)] = [:]

func getTZ(_ filename: String) -> (TZifData, PosixTZ) {
    if let cached = tzCache[filename] { return cached }
    let path = dir + "/" + filename
    guard let data = FileManager.default.contents(atPath: path) else {
        fatalError("Cannot read \(path)")
    }
    let bytes = [UInt8](data)
    let tz = parseTZif(bytes)
    let posix = parsePosixTZ(tz.posixTZ)
    let result = (tz, posix)
    tzCache[filename] = result
    return result
}

var outputLines: [String] = []

for line in queriesContent.components(separatedBy: "\n") {
    let trimmed = line.trimmingCharacters(in: .whitespaces)
    if trimmed.isEmpty { continue }

    let fields = trimmed.components(separatedBy: " ")

    if fields[0] == "UTC" {
        let filename = fields[1]
        let t = Int64(fields[2])!
        let (tz, posix) = getTZ(filename)
        let (offset, abbr, _) = getOffsetAndAbbr(tz: tz, posix: posix, t: t)
        let localStr = formatLocal(epoch: t, offset: offset)
        outputLines.append("\(trimmed) -> \(localStr) \(abbr)")
    } else if fields[0] == "LOCAL" {
        let filename = fields[1]
        let wallStr = fields[2]
        let (tz, posix) = getTZ(filename)

        // Parse wall-clock time
        let (y, mo, d, h, mi, s) = parseLocalDateTime(wallStr)
        let wEpoch = epochFromYMDHMS(y, mo, d, h, mi, s)

        // Collect candidate offsets
        var offsets = Set<Int>()
        for type in tz.types {
            offsets.insert(Int(type.utoff))
        }
        let stdUtoff = -posix.stdOffset
        offsets.insert(stdUtoff)
        if posix.dstAbbr != nil {
            let dstOff = posix.dstOffset ?? (posix.stdOffset - 3600)
            offsets.insert(-dstOff)
        }

        var answers: [(t: Int64, offset: Int, abbr: String)] = []

        for O in offsets {
            let t = wEpoch - Int64(O)
            let (actualOffset, abbr, _) = getOffsetAndAbbr(tz: tz, posix: posix, t: t)
            if actualOffset == O {
                answers.append((t, O, abbr))
            }
        }

        answers.sort { $0.t < $1.t }

        // Remove duplicates
        var unique: [(t: Int64, offset: Int, abbr: String)] = []
        for a in answers {
            if unique.isEmpty || unique.last!.t != a.t {
                unique.append(a)
            }
        }
        answers = unique

        if answers.count == 1 {
            let a = answers[0]
            outputLines.append("\(trimmed) -> \(a.t) \(formatOffset(a.offset)) \(a.abbr)")
        } else if answers.count == 2 {
            let a1 = answers[0], a2 = answers[1]
            outputLines.append("\(trimmed) -> \(a1.t) \(formatOffset(a1.offset)) \(a1.abbr) | \(a2.t) \(formatOffset(a2.offset)) \(a2.abbr)")
        } else {
            // GAP
            // Find the transition causing the gap
            var allTransitions: [(time: Int64, beforeOff: Int, afterOff: Int)] = []

            // TZif transitions
            for i in 0..<tz.transitions.count {
                let T = tz.transitions[i]
                let afterIdx = Int(tz.typeIndices[i])
                let afterOff = Int(tz.types[afterIdx].utoff)
                let beforeOff: Int
                if i == 0 {
                    beforeOff = Int(tz.types[0].utoff)
                } else {
                    let beforeIdx = Int(tz.typeIndices[i-1])
                    beforeOff = Int(tz.types[beforeIdx].utoff)
                }
                allTransitions.append((T, beforeOff, afterOff))
            }

            // POSIX transitions
            if posix.dstAbbr != nil && posix.startRule != nil && posix.endRule != nil {
                let baseYear = decomposeEpoch(wEpoch).year
                let dstOff = posix.dstOffset ?? (posix.stdOffset - 3600)
                for yr in (baseYear - 1)...(baseYear + 1) {
                    let startT = posixTransitionUTC(year: yr, rule: posix.startRule!, time: posix.startTime, posixOffset: posix.stdOffset)
                    let endT = posixTransitionUTC(year: yr, rule: posix.endRule!, time: posix.endTime, posixOffset: dstOff)
                    allTransitions.append((startT, stdUtoff, -dstOff))
                    allTransitions.append((endT, -dstOff, stdUtoff))
                }
            }

            var gapBeforeOffset: Int? = nil
            for trans in allTransitions {
                if trans.afterOff > trans.beforeOff {
                    let gapStart = trans.time + Int64(trans.beforeOff)
                    let gapEnd = trans.time + Int64(trans.afterOff)
                    if wEpoch >= gapStart && wEpoch < gapEnd {
                        gapBeforeOffset = trans.beforeOff
                        break
                    }
                }
            }

            let O_before = gapBeforeOffset ?? stdUtoff
            let t = wEpoch - Int64(O_before)
            let (offset, abbr, _) = getOffsetAndAbbr(tz: tz, posix: posix, t: t)
            let localStr = formatLocal(epoch: t, offset: offset)
            outputLines.append("\(trimmed) -> GAP \(t) \(localStr) \(abbr)")
        }
    }
}

print(outputLines.joined(separator: "\n"))

func parseLocalDateTime(_ s: String) -> (Int, Int, Int, Int, Int, Int) {
    // Format: YYYY-MM-DDTHH:MM:SS
    let chars = Array(s)
    var i = 0

    func readInt(_ n: Int) -> Int {
        var val = 0
        for _ in 0..<n {
            val = val * 10 + Int(String(chars[i]))!
            i += 1
        }
        return val
    }

    let year = readInt(4)
    i += 1 // skip -
    let month = readInt(2)
    i += 1 // skip -
    let day = readInt(2)
    i += 1 // skip T
    let hour = readInt(2)
    i += 1 // skip :
    let min = readInt(2)
    i += 1 // skip :
    let sec = readInt(2)

    return (year, month, day, hour, min, sec)
}

#include <stdio.h>
#include <stdlib.h>
