/* ===== SHA-1 ===== */
typedef struct { uint32_t st[5]; uint64_t cnt; uint8_t buf[64]; } SHA1_CTX;

static inline uint32_t rotl32(uint32_t x, int n){ return (x<<n)|(x>>(32-n)); }

static void sha1_blk(uint32_t s[5], const uint8_t b[64]){
    uint32_t w[80];
    for(int i=0;i<16;i++) w[i]=((uint32_t)b[4*i]<<24)|((uint32_t)b[4*i+1]<<16)|((uint32_t)b[4*i+2]<<8)|b[4*i+3];
    for(int i=16;i<80;i++) w[i]=rotl32(w[i-3]^w[i-8]^w[i-14]^w[i-16],1);
    uint32_t a=s[0],bb=s[1],c=s[2],d=s[3],e=s[4];
    for(int i=0;i<80;i++){
        uint32_t f,k;
        if(i<20){f=(bb&c)|(~bb&d);k=0x5A827999;}
        else if(i<40){f=bb^c^d;k=0x6ED9EBA1;}
        else if(i<60){f=(bb&c)|(bb&d)|(c&d);k=0x8F1BBCDC;}
        else{f=bb^c^d;k=0xCA62C1D6;}
        uint32_t t=rotl32(a,5)+f+e+k+w[i];
        e=d;d=c;c=rotl32(bb,30);bb=a;a=t;
    }
    s[0]+=a;s[1]+=bb;s[2]+=c;s[3]+=d;s[4]+=e;
}

static void sha1_init(SHA1_CTX*c){
    c->st[0]=0x67452301;c->st[1]=0xEFCDAB89;c->st[2]=0x98BADCFE;
    c->st[3]=0x10325476;c->st[4]=0xC3D2E1F0;c->cnt=0;
}

static void sha1_update(SHA1_CTX*c,const uint8_t*d,size_t n){
    size_t u=(size_t)(c->cnt&63); c->cnt+=n;
    if(u){size_t sp=64-u;if(n<sp){memcpy(c->buf+u,d,n);return;}memcpy(c->buf+u,d,sp);sha1_blk(c->st,c->buf);d+=sp;n-=sp;}
    while(n>=64){sha1_blk(c->st,d);d+=64;n-=64;}
    if(n)memcpy(c->buf,d,n);
}

static void sha1_final(SHA1_CTX*c,uint8_t h[20]){
    uint64_t bits=c->cnt*8;
    uint8_t pad[72]; memset(pad,0,72); pad[0]=0x80;
    size_t u=(size_t)(c->cnt&63);
    size_t pl=(u<=55)?(56-u):(120-u);
    for(int i=7;i>=0;i--) pad[pl+i]=(uint8_t)(bits>>(i*8));
    pl+=8;
    sha1_update(c,pad,pl);
    for(int i=0;i<5;i++){h[4*i]=(uint8_t)(c->st[i]>>24);h[4*i+1]=(uint8_t)(c->st[i]>>16);h[4*i+2]=(uint8_t)(c->st[i]>>8);h[4*i+3]=(uint8_t)c->st[i];}
}

/* ===== Base64 ===== */
static const char B64C[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static void b64enc(const uint8_t*in,size_t len,char*out){
    size_t i=0,j=0;
    while(i+2<len){uint32_t v=((uint32_t)in[i]<<16)|((uint32_t)in[i+1]<<8)|in[i+2];
        out[j++]=B64C[(v>>18)&63];out[j++]=B64C[(v>>12)&63];out[j++]=B64C[(v>>6)&63];out[j++]=B64C[v&63];i+=3;}
    if(i+1==len){uint32_t v=(uint32_t)in[i]<<16;out[j++]=B64C[(v>>18)&63];out[j++]=B64C[(v>>12)&63];out[j++]='=';out[j++]='=';}
    else if(i+2==len){uint32_t v=((uint32_t)in[i]<<16)|((uint32_t)in[i+1]<<8);out[j++]=B64C[(v>>18)&63];out[j++]=B64C[(v>>12)&63];out[j++]=B64C[(v>>6)&63];out[j++]='=';}
    out[j]='\0';
}

/* ===== UTF-8 ===== */
static size_t u8dec(const uint8_t*s,size_t len,uint32_t*cp,size_t mx){
    size_t i=0,n=0;
    while(i<len&&n<mx){
        if(s[i]<0x80){cp[n++]=s[i];i+=1;}
        else if((s[i]&0xE0)==0xC0){cp[n++]=((uint32_t)(s[i]&0x1F)<<6)|(s[i+1]&0x3F);i+=2;}
        else if((s[i]&0xF0)==0xE0){cp[n++]=((uint32_t)(s[i]&0x0F)<<12)|((uint32_t)(s[i+1]&0x3F)<<6)|(s[i+2]&0x3F);i+=3;}
        else{cp[n++]=((uint32_t)(s[i]&0x07)<<18)|((uint32_t)(s[i+1]&0x3F)<<12)|((uint32_t)(s[i+2]&0x3F)<<6)|(s[i+3]&0x3F);i+=4;}
    }
    return n;
}

static size_t u8enc(const uint32_t*cp,size_t n,uint8_t*out){
    size_t p=0;
    for(size_t i=0;i<n;i++){uint32_t c=cp[i];
        if(c<0x80)out[p++]=(uint8_t)c;
        else if(c<0x800){out[p++]=0xC0|(c>>6);out[p++]=0x80|(c&0x3F);}
        else if(c<0x10000){out[p++]=0xE0|(c>>12);out[p++]=0x80|((c>>6)&0x3F);out[p++]=0x80|(c&0x3F);}
        else{out[p++]=0xF0|(c>>18);out[p++]=0x80|((c>>12)&0x3F);out[p++]=0x80|((c>>6)&0x3F);out[p++]=0x80|(c&0x3F);}
    }
    out[p]='\0';return p;
}

/* ===== Buffered I/O ===== */
typedef struct{int fd;uint8_t buf[65536];size_t len,pos;}conn_t;

static int cfill(conn_t*c){
    if(c->pos<c->len)return 1;
    ssize_t n=read(c->fd,c->buf,sizeof(c->buf));
    if(n<=0)return 0;
    c->pos=0;c->len=(size_t)n;return 1;
}

static int cread(conn_t*c,uint8_t*dst,size_t n){
    size_t g=0;
    while(g<n){
        if(c->pos>=c->len){if(!cfill(c))return -1;}
        size_t av=c->len-c->pos,nd=n-g,ch=av<nd?av:nd;
        memcpy(dst+g,c->buf+c->pos,ch);c->pos+=ch;g+=ch;
    }
    return 0;
}

/* ===== URL ===== */
typedef struct{char host[256];int port;char path[2048];}wsurl;

static int purl(const char*u,wsurl*r){
    if(strncmp(u,"ws://",5)!=0)return -1;
    const char*p=u+5;
    const char*sl=strchr(p,'/');
    const char*co=strchr(p,':');
    if(co&&(!sl||co<sl)){size_t hl=(size_t)(co-p);memcpy(r->host,p,hl);r->host[hl]='\0';r->port=atoi(co+1);}
    else{size_t hl=sl?(size_t)(sl-p):strlen(p);memcpy(r->host,p,hl);r->host[hl]='\0';r->port=80;}
    if(sl)strcpy(r->path,sl);else strcpy(r->path,"/");
    return 0;
}

/* ===== Handshake ===== */
static int wshandshake(conn_t*c,const wsurl*u,const char*key){
    char req[4096];
    int rl=snprintf(req,sizeof(req),
        "GET %s HTTP/1.1\r\n"
        "Host: %s:%d\r\n"
        "Upgrade: websocket\r\n"
        "Connection: Upgrade\r\n"
        "Sec-WebSocket-Version: 13\r\n"
        "Sec-WebSocket-Key: %s\r\n"
        "\r\n",u->path,u->host,u->port,key);
    size_t off=0;
    while(off<(size_t)rl){ssize_t n=write(c->fd,req+off,rl-off);if(n<=0)return -1;off+=(size_t)n;}

    /* read header block */
    char hdr[8192];size_t hp=0;
    while(hp+3<sizeof(hdr)){
        if(c->pos>=c->len){if(!cfill(c))return -1;}
        hdr[hp++]=(char)c->buf[c->pos++];
        if(hp>=4&&memcmp(hdr+hp-4,"\r\n\r\n",4)==0)break;
    }
    hdr[hp]='\0';

    /* parse status */
    int code=0;char reason[512]={0};
    const char*sp=strchr(hdr,' ');
    if(!sp)return -1;
    code=atoi(sp+1);
    const char*sp2=strchr(sp+1,' ');
    if(sp2){
        size_t rlen=strlen(sp2+1);
        while(rlen>0&&(sp2[1+rlen-1]=='\r'||sp2[1+rlen-1]=='\n'))rlen--;
        if(rlen>=sizeof(reason))rlen=sizeof(reason)-1;
        memcpy(reason,sp2+1,rlen);reason[rlen]='\0';
    }
    if(code!=101){printf("handshake failed: %d %s\n",code,reason);return -2;}

    /* compute expected accept */
    char ai[256];snprintf(ai,sizeof(ai),"%s258EAFA5-E914-47DA-95CA-C5AB0DC85B11",key);
    SHA1_CTX sc;sha1_init(&sc);sha1_update(&sc,(const uint8_t*)ai,strlen(ai));
    uint8_t hh[20];sha1_final(&sc,hh);
    char exp[64];b64enc(hh,20,exp);

    /* scan headers for Sec-WebSocket-Accept */
    int accept_ok=0;
    const char*ln=hdr;
    ln=strchr(ln,'\n');if(!ln)return -1;ln++;
    while(*ln){
        const char*eol=strchr(ln,'\r');
        if(!eol)eol=strchr(ln,'\n');
        size_t ll=eol?(size_t)(eol-ln):strlen(ln);
        if(ll==0)break;
        const char*cl=memchr(ln,':',ll);
        if(cl){
            size_t nl=(size_t)(cl-ln);
            if(nl==20&&strncasecmp(ln,"Sec-WebSocket-Accept",20)==0){
                const char*vl=cl+1;while(*vl==' '||*vl=='\t')vl++;
                size_t vlen=eol?(size_t)(eol-vl):strlen(vl);
                while(vlen>0&&(vl[vlen-1]==' '||vl[vlen-1]=='\t'))vlen--;
                if(vlen==strlen(exp)&&memcmp(vl,exp,vlen)==0)accept_ok=1;
                else accept_ok=2;
            }
        }
        ln=eol?eol+1:ln+ll;
        if(*ln=='\n')ln++;
    }
    if(!accept_ok){printf("handshake failed: bad Sec-WebSocket-Accept\n");return -3;}
    return 0;
}

/* ===== WebSocket frames ===== */
typedef struct{int fin;int op;uint8_t*pl;size_t pn;}wframe;

static int wread(conn_t*c,wframe*f){
    uint8_t h[2];if(cread(c,h,2)<0)return -1;
    f->fin=(h[0]>>7)&1;f->op=h[0]&0x0F;
    uint64_t pn=h[1]&0x7F;
    if(pn==126){uint8_t e[2];if(cread(c,e,2)<0)return -1;pn=((uint64_t)e[0]<<8)|e[1];}
    else if(pn==127){uint8_t e[8];if(cread(c,e,8)<0)return -1;pn=0;for(int i=0;i<8;i++)pn=(pn<<8)|e[i];}
    f->pn=(size_t)pn;
    f->pl=pn?malloc(pn):NULL;
    if(pn&&cread(c,f->pl,pn)<0){free(f->pl);return -1;}
    return 0;
}

static int wsend(conn_t*c,int op,const uint8_t*pl,size_t pn){
    uint8_t h[14];size_t hl;
    h[0]=0x80|(op&0x0F);
    if(pn<=125){h[1]=0x80|(uint8_t)pn;hl=2;}
    else if(pn<=65535){h[1]=0x80|126;h[2]=(uint8_t)(pn>>8);h[3]=(uint8_t)pn;hl=4;}
    else{h[1]=0x80|127;for(int i=7;i>=0;i--)h[2+(7-i)]=(uint8_t)(pn>>(i*8));hl=10;}
    uint8_t mk[4];do{arc4random_buf(mk,4);}while(!mk[0]&&!mk[1]&&!mk[2]&&!mk[3]);
    size_t tot=hl+4+pn;uint8_t*fr=malloc(tot);
    memcpy(fr,h,hl);memcpy(fr+hl,mk,4);
    for(size_t i=0;i<pn;i++)fr[hl+4+i]=pl[i]^mk[i&3];
    size_t off=0;while(off<tot){ssize_t n=write(c->fd,fr+off,tot-off);if(n<=0){free(fr);return -1;}off+=(size_t)n;}
    free(fr);return 0;
}

/* ===== Process complete text message ===== */
static void proc_text(conn_t*conn,const uint8_t*msg,size_t mlen,
                      int*sha1_wait,int*bye,int*csent){
    char*txt=malloc(mlen+1);memcpy(txt,msg,mlen);txt[mlen]='\0';

    if(mlen>=4&&memcmp(txt,"ADD ",4)==0){
        const char*p=txt+4;char*ep;
        long long a=strtoll(p,&ep,10);p=ep;
        while(*p==' ')p++;
        long long b=strtoll(p,NULL,10);
        long long s=a+b;
        char rp[32];snprintf(rp,sizeof(rp),"%lld",s);
        wsend(conn,1,(const uint8_t*)rp,strlen(rp));
        printf("%s -> %lld\n",txt,s);
    }else if(mlen>=4&&memcmp(txt,"REV ",4)==0){
        const char*t=txt+4;size_t tl=mlen-4;
        uint32_t cps[65536];size_t nc=u8dec((const uint8_t*)t,tl,cps,65536);
        for(size_t i=0;i<nc/2;i++){uint32_t tmp=cps[i];cps[i]=cps[nc-1-i];cps[nc-1-i]=tmp;}
        uint8_t ob[262144];size_t ol=u8enc(cps,nc,ob);
        wsend(conn,1,ob,ol);
        printf("REV %s -> %s\n",t,(char*)ob);
    }else if(mlen==4&&memcmp(txt,"SHA1",4)==0){
        *sha1_wait=1;
    }else if(mlen==3&&memcmp(txt,"BYE",3)==0){
        uint8_t cp[2]={0x03,0xE8};
        wsend(conn,8,cp,2);
        *csent=1;*bye=1;
    }
    free(txt);
}

/* ===== Process complete binary message ===== */
static void proc_bin(conn_t*conn,const uint8_t*msg,size_t mlen,int*sha1_wait){
    if(!*sha1_wait)return;
    SHA1_CTX sc;sha1_init(&sc);sha1_update(&sc,msg,mlen);
    uint8_t h[20];sha1_final(&sc,h);
    char hex[41];for(int i=0;i<20;i++)sprintf(hex+2*i,"%02x",h[i]);hex[40]='\0';
    wsend(conn,1,(const uint8_t*)hex,40);
    printf("SHA1 %zu -> %s\n",mlen,hex);
    *sha1_wait=0;
}

/* ===== Session ===== */
static void session(const wsurl*u){
    conn_t cn;memset(&cn,0,sizeof(cn));
    cn.fd=socket(AF_INET,SOCK_STREAM,0);
    if(cn.fd<0)return;
    struct sockaddr_in sa;memset(&sa,0,sizeof(sa));
    sa.sin_family=AF_INET;sa.sin_port=htons((uint16_t)u->port);
    inet_pton(AF_INET,u->host,&sa.sin_addr);
    if(connect(cn.fd,(struct sockaddr*)&sa,sizeof(sa))<0){close(cn.fd);return;}

    uint8_t kb[16];arc4random_buf(kb,16);
    char key[24];b64enc(kb,16,key);
    if(wshandshake(&cn,u,key)<0){close(cn.fd);return;}

    int csent=0,sha1_wait=0,bye=0;
    int fa=0,fop=0;uint8_t*fb=NULL;size_t fl=0;

    while(1){
        wframe f;
        if(wread(&cn,&f)<0)break;

        switch(f.op){
        case 1: case 2:
            if(bye){free(f.pl);break;}
            if(f.fin){
                if(f.op==1) proc_text(&cn,f.pl,f.pn,&sha1_wait,&bye,&csent);
                else proc_bin(&cn,f.pl,f.pn,&sha1_wait);
            }else{
                fa=1;fop=f.op;
                fb=f.pn?malloc(f.pn):NULL;
                if(f.pn)memcpy(fb,f.pl,f.pn);
                fl=f.pn;
            }
            break;
        case 0:
            if(bye){free(f.pl);break;}
            if(fa){
                fb=realloc(fb,fl+f.pn);
                if(f.pn)memcpy(fb+fl,f.pl,f.pn);
                fl+=f.pn;
                if(f.fin){
                    if(fop==1) proc_text(&cn,fb,fl,&sha1_wait,&bye,&csent);
                    else proc_bin(&cn,fb,fl,&sha1_wait);
                    fa=0;free(fb);fb=NULL;fl=0;
                }
            }
            break;
        case 9: /* ping */
            wsend(&cn,10,f.pl,f.pn);
            break;
        case 10: /* pong */
            break;
        case 8: /* close */
            {
                uint16_t code=1005;char rsn[1024]={0};
                if(f.pn>=2){
                    code=((uint16_t)f.pl[0]<<8)|f.pl[1];
                    if(f.pn>2){size_t rl=f.pn-2;if(rl>=sizeof(rsn))rl=sizeof(rsn)-1;memcpy(rsn,f.pl+2,rl);rsn[rl]='\0';}
                }
                if(rsn[0])printf("closed %d %s\n",code,rsn);
                else printf("closed %d\n",code);
                if(!csent){uint8_t cp[2]={(uint8_t)(code>>8),(uint8_t)(code&0xFF)};wsend(&cn,8,cp,2);}
                free(f.pl);goto done;
            }
        }
        free(f.pl);
    }
done:
    close(cn.fd);
}

/* ===== main ===== */
int main(int argc,char**argv){
    for(int i=1;i<argc;i++){
        printf("session %d\n",i);
        wsurl u;
        if(purl(argv[i],&u)==0) session(&u);
    }
    return 0;
}

